INSERT INTO lessons (id, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id) VALUES ('lesson-1', 'Bài 1: Chào hỏi (1) - Đơn nguyên 1: Trường học', 'Bài 1', 'Đơn nguyên 1: Trường học', 'Chào hỏi thông thường và theo buổi, câu chữ 是, trợ từ nghi vấn 吗, phó từ 也.', '2026-11-14'::date, 1, TRUE, NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, date_added = EXCLUDED.date_added, sort_order = EXCLUDED.sort_order, is_system = TRUE, updated_at = NOW();
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v1_1', 'lesson-1', '学校', 'xuéxiào', 'học hiệu', 'Trường học', 'Danh từ', '子 (Tử) (Đứa con, trẻ nhỏ, người trí thức)', '学: ⺍ + 冖 (Mịch: mái che) + 子 (Tử: trẻ nhỏ) • 校: 木 (Mộc: cây gỗ) + 交 (Giao: giao nhau)', 'Ghép 学 [bộ 子] + 校 [bộ 木] để nhớ từ 学校 (xuéxiào): "Trường học".', '这是关于“学校”的常用句子。', 'Zhè shì guānyú ''xuéxiào'' de chángyòng jùzi.', 'Đây là câu ví dụ sử dụng từ ''学校'' (Trường học).', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v1_2', 'lesson-1', '老师', 'lǎoshī', 'lão sư', 'Giáo viên, thầy cô giáo', 'Danh từ', '老/耂 (Lão) (Người già, lâu năm, tôn kính)', '老: 耂 (Lão: người già) + 匕 (Chủy) • 师: 𠂤 + 巾 (Cân: khăn vải)', 'Ghép 老 [bộ 耂] + 师 [bộ 巾] để nhớ từ 老师 (lǎoshī): "Giáo viên, thầy cô giáo".', '老师好', 'Lǎoshī hǎo', 'Chào thầy/Chào cô', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v1_3', 'lesson-1', '同学', 'tóngxué', 'đồng học', 'bạn học', 'Danh từ', '口 (Khẩu) (Miệng, ăn uống, lời nói, âm thanh phát ra)', '同: 冂 (Quynh: khung bao) + 一 + 口 (Khẩu: cùng chung một tiếng) • 学: ⺍ + 冖 (Mịch: mái che) + 子 (Tử: trẻ nhỏ)', 'Ghép 同 [bộ 口] + 学 [bộ 子] để nhớ từ 同学 (tóngxué): "bạn học".', '同学们', 'tóngxuémen', 'Các bạn học sinh', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v1_4', 'lesson-1', '学生', 'xuésheng', 'học sinh', 'học sinh', 'Danh từ', '子 (Tử) (Đứa con, trẻ nhỏ, người trí thức)', '学: ⺍ + 冖 (Mịch: mái che) + 子 (Tử: trẻ nhỏ) • 生: Bộ 生 (Sinh - mầm cây nảy từ đất, chữ độc thể)', 'Ghép 学 [bộ 子] + 生 [bộ 生] để nhớ từ 学生 (xuésheng): "học sinh".', '我是大学生。', 'Wǒ shì dàxuéshēng.', 'Tôi là sinh viên.', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v1_5', 'lesson-1', '留学生', 'liúxuéshēng', 'lưu học sinh', 'du học sinh', 'Danh từ', '田 (Điền) (Ruộng đất, khu vực, mặt)', '留: 卯 (biến thể) + 田 (Điền: ruộng đất) • 学: ⺍ + 冖 (Mịch: mái che) + 子 (Tử: trẻ nhỏ) • 生: Bộ 生 (Sinh - mầm cây nảy từ đất, chữ độc thể)', 'Ghép 留 [bộ 田] + 学 [bộ 子] + 生 [bộ 生] để nhớ từ 留学生 (liúxuéshēng): "du học sinh".', '你是留学生吗？', 'Nǐ shì liúxuéshēng ma?', 'Bạn là du học sinh phải không?', 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v1_6', 'lesson-1', '刘', 'Liú', 'Lưu', 'Lưu (họ người)', 'Cụm từ / Tên riêng', '刀/刂 (Đao) (Con dao, cắt xẻ, phân chia)', '刘 = 文 (Văn) + 刂 (Đao).', 'Chữ 刘 (Liú) mang nghĩa "Lưu (họ người)", bộ chính 刀/刂 (Đao); cấu tạo: 文 (Văn) + 刂 (Đao).', '这是关于“刘”的常用句子。', 'Zhè shì guānyú ''Liú'' de chángyòng jùzi.', 'Đây là câu ví dụ sử dụng từ ''刘'' (Lưu (họ người)).', 6) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v1_7', 'lesson-1', '范玉兰', 'Fàn Yùlán', 'Phạm ngọc lan', 'Phạm Ngọc Lan', 'Cụm từ / Tên riêng', '艹 (Thảo) (Cỏ cây, hoa lá, thảo mộc)', '范: 艹 (Thảo: cỏ) + 氵 (Thủy) + 卩 (Tiết) • 玉: Bộ 玉 (Ngọc - ba mảnh ngọc xâu dây kèm chấm, chữ độc thể) • 兰: 丷 (Bát) + 三 (Ba nét ngang)', 'Ghép 范 [bộ 艹] + 玉 [bộ 玉] + 兰 [bộ 八] để nhớ từ 范玉兰 (Fàn Yùlán): "Phạm Ngọc Lan".', '这是关于“范玉兰”的常用句子。', 'Zhè shì guānyú ''Fàn Yùlán'' de chángyòng jùzi.', 'Đây là câu ví dụ sử dụng từ ''范玉兰'' (Phạm Ngọc Lan).', 7) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v1_8', 'lesson-1', '阮日明', 'Ruǎn Rìmíng', 'Nguyễn nhật minh', 'Nguyễn Nhật Minh', 'Cụm từ / Tên riêng', '阝 (Phụ/Ấp) (Gò đất hoặc vùng đất, thành ấp)', '阮: 阝 (Phụ: gò đất) + 元 (Nguyên) • 日: Bộ 日 (Nhật - mặt trời, chữ độc thể) • 明: 日 (Nhật: mặt trời) + 月 (Nguyệt: mặt trăng)', 'Ghép 阮 [bộ 阝] + 日 [bộ 日] + 明 [bộ 日] để nhớ từ 阮日明 (Ruǎn Rìmíng): "Nguyễn Nhật Minh".', '这是关于“阮日明”的常用句子。', 'Zhè shì guānyú ''Ruǎn Rìmíng'' de chángyòng jùzi.', 'Đây là câu ví dụ sử dụng từ ''阮日明'' (Nguyễn Nhật Minh).', 8) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v1_9', 'lesson-1', '早上', 'zǎoshang', 'tảo thượng', 'buổi sáng', 'Danh từ', '日 (Nhật) (Mặt trời, ban ngày, thời gian, ánh sáng)', '早: 日 (Nhật: mặt trời mọc) + 十 (Thập: ngọn cây) • 上: Nét đứng 丨 và nét chấm chỉ hướng phía trên gạch ngang 一', 'Ghép 早 [bộ 日] + 上 [bộ 一] để nhớ từ 早上 (zǎoshang): "buổi sáng".', '早上好！', 'Zǎoshang hǎo', 'Chào buổi sáng!', 9) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v1_10', 'lesson-1', '中午', 'zhōngwǔ', 'trung ngọ', 'buổi trưa', 'Danh từ', '丨 (Cổn) (Nét sổ thẳng, xuyên suốt)', '中: 口 (Khẩu: khung vuông) + 丨 (Cổn: vạch chính giữa) • 午: 𠂉 + 十 (Thập)', 'Ghép 中 [bộ 丨] + 午 [bộ 十] để nhớ từ 中午 (zhōngwǔ): "buổi trưa".', '中午好！', 'Zhōngwǔ hǎo', 'Chào buổi trưa!', 10) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v1_11', 'lesson-1', '下午', 'xiàwǔ', 'hạ ngọ', 'buổi chiều', 'Danh từ', '一 (Nhất) (Số một, nền tảng, nét ngang cơ bản)', '下: Nét ngang 一 phía trên nét sổ 丨 và chấm chỉ hướng xuống dưới • 午: 𠂉 + 十 (Thập)', 'Ghép 下 [bộ 一] + 午 [bộ 十] để nhớ từ 下午 (xiàwǔ): "buổi chiều".', '下午好！', 'Xiàwǔ hǎo', 'Chào buổi chiều!', 11) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v1_12', 'lesson-1', '晚上', 'wǎnshàng', 'vãn thượng', 'buổi tối', 'Danh từ', '日 (Nhật) (Mặt trời, ban ngày, thời gian, ánh sáng)', '晚: 日 (Nhật: mặt trời) + 免 (Miễn: khuất bóng) • 上: Nét đứng 丨 và nét chấm chỉ hướng phía trên gạch ngang 一', 'Ghép 晚 [bộ 日] + 上 [bộ 一] để nhớ từ 晚上 (wǎnshàng): "buổi tối".', '晚上好！', 'Wǎnshang hǎo', 'Chào buổi tối!', 12) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v1_13', 'lesson-1', '是', 'shì', 'thị', 'là, thì...', 'Động từ', '日 (Nhật) (Mặt trời, ban ngày, thời gian, ánh sáng)', '是 = 日 (Nhật: sáng rõ) + 𤴓 (biến thể của 正/疋: ngay thẳng).', 'Chữ 是 (shì) mang nghĩa "là, thì...", bộ chính 日 (Nhật); cấu tạo: 日 (Nhật: sáng rõ) + 𤴓 (biến thể của 正/疋: ngay thẳng).', '我是大学生。', 'Wǒ shì dàxuéshēng.', 'Tôi là sinh viên.', 13) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v1_14', 'lesson-1', '好', 'hǎo', 'hảo', 'tốt, khỏe, hay, ngon...', 'Tính từ', '女 (Nữ) (Phụ nữ, gia đình, tình cảm)', '好 = 女 (Nữ: người mẹ) + 子 (Tử: đứa con).', 'Chữ 好 (hǎo) mang nghĩa "tốt, khỏe, hay, ngon...", bộ chính 女 (Nữ); cấu tạo: 女 (Nữ: người mẹ) + 子 (Tử: đứa con).', '老师好', 'Lǎoshī hǎo', 'Chào thầy/Chào cô', 14) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v1_15', 'lesson-1', '您', 'nín', 'nẫm', 'ngài, ông, bà... (cách gọi tôn trọng và lịch sự dành cho những người có địa vị cao...)', 'Đại từ', '心/忄 (Tâm) (Trái tim, tình cảm, suy nghĩ, tâm lý)', '您 = 你 (Nhĩ: bạn) + 心 (Tâm: đặt trong lòng để kính trọng).', 'Chữ 您 (nín) mang nghĩa "ngài, ông, bà... (cách gọi tôn trọng và lịch sự dành cho những người có địa vị cao...)", bộ chính 心/忄 (Tâm); cấu tạo: 你 (Nhĩ: bạn) + 心 (Tâm: đặt trong lòng để kính trọng).', '老师您好！', 'Lǎoshī nín hǎo', 'Em chào thầy/cô ạ', 15) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v1_16', 'lesson-1', '你', 'nǐ', 'nhĩ', 'bạn, cậu, anh, chị... (ngôi thứ hai số ít)', 'Đại từ', '人/亻 (Nhân) (Con người, nhân loại, hành động)', '你 = 亻 (Nhân đứng: người) + 尔 (Nhĩ).', 'Chữ 你 (nǐ) mang nghĩa "bạn, cậu, anh, chị... (ngôi thứ hai số ít)", bộ chính 人/亻 (Nhân); cấu tạo: 亻 (Nhân đứng: người) + 尔 (Nhĩ).', '你是日明吗？', 'Nǐ shì Rìmíng ma?', 'Cậu là Nhật Minh phải không?', 16) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v1_17', 'lesson-1', '你们', 'nǐmen', 'nhĩ môn', 'các bạn, các anh, các chị… (ngôi thứ hai số nhiều)', 'Đại từ', '人/亻 (Nhân) (Con người, nhân loại, hành động)', '你: 亻 (Nhân đứng: người) + 尔 (Nhĩ) • 们: 亻 (Nhân đứng: người) + 门 (Môn: cửa)', 'Ghép 你 [bộ 亻] + 们 [bộ 亻] để nhớ từ 你们 (nǐmen): "các bạn, các anh, các chị… (ngôi thứ hai số nhiều)".', '这是关于“你们”的常用句子。', 'Zhè shì guānyú ''nǐmen'' de chángyòng jùzi.', 'Đây là câu ví dụ sử dụng từ ''你们'' (các bạn, các anh, các chị… (ngôi thứ hai số nhiều)).', 17) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v1_18', 'lesson-1', '我', 'wǒ', 'ngã', 'tôi, tớ, mình... (ngôi thứ nhất số ít)', 'Đại từ', '戈 (Qua) (Cây giáo, vũ khí, chiến tranh)', '我 = 手 (Thủ: tay biến thể) + 戈 (Qua: binh khí).', 'Chữ 我 (wǒ) mang nghĩa "tôi, tớ, mình... (ngôi thứ nhất số ít)", bộ chính 戈 (Qua); cấu tạo: 手 (Thủ: tay biến thể) + 戈 (Qua: binh khí).', '我是大学生。', 'Wǒ shì dàxuéshēng.', 'Tôi là sinh viên.', 18) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v1_19', 'lesson-1', '我们', 'wǒmen', 'ngã môn', 'chúng ta, chúng mình, chúng tôi… (ngôi thứ nhất số nhiều)', 'Đại từ', '戈 (Qua) (Cây giáo, vũ khí, chiến tranh)', '我: 手 (Thủ: tay biến thể) + 戈 (Qua: binh khí) • 们: 亻 (Nhân đứng: người) + 门 (Môn: cửa)', 'Ghép 我 [bộ 戈] + 们 [bộ 亻] để nhớ từ 我们 (wǒmen): "chúng ta, chúng mình, chúng tôi… (ngôi thứ nhất số nhiều)".', '这是关于“我们”的常用句子。', 'Zhè shì guānyú ''wǒmen'' de chángyòng jùzi.', 'Đây là câu ví dụ sử dụng từ ''我们'' (chúng ta, chúng mình, chúng tôi… (ngôi thứ nhất số nhiều)).', 19) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v1_20', 'lesson-1', '吗', 'ma', 'ma', 'à, ư, hả... (đặt ở cuối câu nghi vấn)', 'Trợ từ', '口 (Khẩu) (Miệng, ăn uống, lời nói, âm thanh phát ra)', '吗 = 口 (Khẩu: lời nói) + 马 (Mã: mượn âm).', 'Chữ 吗 (ma) mang nghĩa "à, ư, hả... (đặt ở cuối câu nghi vấn)", bộ chính 口 (Khẩu); cấu tạo: 口 (Khẩu: lời nói) + 马 (Mã: mượn âm).', '你是日明吗？', 'Nǐ shì Rìmíng ma?', 'Cậu là Nhật Minh phải không?', 20) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v1_21', 'lesson-1', '也', 'yě', 'dã', 'cũng', 'Phó từ', '乙 (Ất) (Uốn cong, số thứ tự, chồi non)', '也 = Bộ 乙 (Ất - nét uốn cong) + 丨 (chữ độc thể).', 'Chữ 也 (yě) mang nghĩa "cũng", bộ chính 乙 (Ất); cấu tạo: Bộ 乙 (Ất - nét uốn cong) + 丨 (chữ độc thể).', '我也是学生。', 'Wǒ yě shì xuéshēng.', 'Tôi cũng là học sinh.', 21) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order) VALUES ('g1_1', 'lesson-1', '1. 打招呼 - Chào hỏi trong tiếng Trung', 'Cấu trúc câu ngữ pháp trọng tâm', 'Quy tắc ngữ pháp quan trọng trong Chào hỏi (1).', NULL, '[{"hanzi":"老师好","pinyin":"Lǎoshī hǎo","meaning":"Chào thầy/Chào cô"},{"hanzi":"老师您好！","pinyin":"Lǎoshī nín hǎo","meaning":"Em chào thầy/cô ạ"}]'::jsonb, 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order) VALUES ('g1_2', 'lesson-1', '1.1. Chào hỏi thông thường', 'Danh từ chỉ người + 好', ' - Khi muốn thực hiện lời chào ai đó trong tiếng Trung sẽ thực hiện theo cách: 你好 /Nǐ hǎo/: Xin chào 老师好 /Lǎoshī hǎo/: Chào thầy/Chào cô - 您好 là lời chào với ngữ khí trang trọng. Nếu muốn biểu thị sự tôn trọng, kính trọng với đối phương thì thay vì d', NULL, '[{"hanzi":"早上好！","pinyin":"Zǎoshang hǎo","meaning":"Chào buổi sáng!"},{"hanzi":"中午好！","pinyin":"Zhōngwǔ hǎo","meaning":"Chào buổi trưa!"}]'::jsonb, 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order) VALUES ('g1_3', 'lesson-1', '1.2. Chào hỏi theo khoảng thời gian', 'Cấu trúc câu ngữ pháp trọng tâm', ' - Đối với các khoảng thời gian sáng, trưa, chiều, tối trong ngày, thay vì chào như thông thường, ta có thể sử dụng theo các cách thức khác như: 早上好！ /Zǎoshang hǎo/: Chào buổi sáng! 中午好！ /Zhōngwǔ hǎo/: Chào buổi trưa! 下午好！ /Xiàwǔ hǎo/: Chào buổi chiề', NULL, '[{"hanzi":"下午好！","pinyin":"Xiàwǔ hǎo","meaning":"Chào buổi chiều!"},{"hanzi":"晚上好！","pinyin":"Wǎnshang hǎo","meaning":"Chào buổi tối!"}]'::jsonb, 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order) VALUES ('g1_4', 'lesson-1', '2. “是”字句 – Câu chữ 是', 'Chủ ngữ + 是 + Danh từ', ' a. Khái niệm Câu chữ 是 là câu vị ngữ động từ 是, biểu thị sự khẳng định, phán đoán. b. Cấu trúc - Hình thức khẳng định: 我是大学生。 Wǒ shì dàxuéshēng. Tôi là sinh viên. 她是老师。 Tā shì lǎoshī. Cô ấy là giáo viên. - Hình thức phủ định: Chủ ngữ + 不是 + Danh từ ', NULL, '[{"hanzi":"我是大学生。","pinyin":"Wǒ shì dàxuéshēng.","meaning":"Tôi là sinh viên."},{"hanzi":"她是老师。","pinyin":"Tā shì lǎoshī.","meaning":"Cô ấy là giáo viên."}]'::jsonb, 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order;
INSERT INTO texts (id, lesson_id, title, description, sort_order) VALUES ('txt_1_1', 'lesson-1', 'Bài khoá #1: Hội thoại giáo trình — Chào hỏi (1)', 'Hội thoại chuẩn giáo trình Bài 1. Từ vựng chưa học được chú thích phiên âm & nghĩa trong ngoặc.', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_1_1_1', 'txt_1_1', '刘老师', '同学们，早上好！', '同学们 (tóngxuémen: các bạn học)，早上好 (zǎoshang hǎo: chào buổi sáng)！', 'Tóngxuémen, zǎoshang hǎo!', 'Các em học sinh, chào buổi sáng!', 1) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_1_1_2', 'txt_1_1', '学生们', '老师好！', '老师好！', 'Lǎoshī hǎo!', 'Em chào thầy/cô ạ!', 2) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_1_1_3', 'txt_1_1', '刘老师', '你是留学生吗？', '你是留学生吗？', 'Nǐ shì liúxuéshēng ma?', 'Bạn là du học sinh phải không?', 3) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_1_1_4', 'txt_1_1', '范玉兰', '是。', '是。', 'Shì.', 'Đúng vậy.', 4) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_1_1_5', 'txt_1_1', '刘老师', '你也是留学生吗？', '你也是留学生吗？', 'Nǐ yě shì liúxuéshēng ma?', 'Bạn cũng là du học sinh à?', 5) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_1_1_6', 'txt_1_1', '阮日明', '是，我也是留学生。', '是，我也是留学生。', 'Shì, wǒ yě shì liúxuéshēng.', 'Vâng, tôi cũng là du học sinh.', 6) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_1_1_1', 'lesson-1', 'txt_1_1', 'listening', 'listening', '同学们，早上好！', NULL, 'Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Vấn đề này tôi không biết nên chỉ đành đi hỏi mẹ.","Các em học sinh, chào buổi sáng!","phía trước (của) tôi","Đợi một chút."]'::jsonb, 1, 'Nội dung nghe được: 同学们，早上好！ (Tóngxuémen, zǎoshang hǎo!) → Các em học sinh, chào buổi sáng!', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_1_1_2', 'lesson-1', 'txt_1_1', 'listening', 'listening', '老师好！', NULL, 'Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["下午好！","你是日明吗？","老师好！","中午好，同学们 (tóngxuémen: các bạn học)！"]'::jsonb, 2, 'Câu vừa đọc: 老师好！ (Lǎoshī hǎo!) → Em chào thầy/cô ạ!', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_1_1_3', 'lesson-1', 'txt_1_1', 'listening', 'listening', '你是留学生吗？', NULL, 'Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Anh ấy đang ăn cơm kìa.","Bạn là du học sinh phải không?","Cảm cúm một lần","Cậu thích mùa xuân hay mùa hè?"]'::jsonb, 1, 'Nội dung nghe được: 你是留学生吗？ (Nǐ shì liúxuéshēng ma?) → Bạn là du học sinh phải không?', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_1_1_4', 'lesson-1', 'txt_1_1', 'listening', 'listening', '你也是留学生吗？', NULL, 'Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["你也是留学生吗？","中午好！","她 (tā: cô ấy, bà ấy)不 (bù: không)是学生吗？","刘老师是学校的 (de: của)老师。"]'::jsonb, 0, 'Câu vừa đọc: 你也是留学生吗？ (Nǐ yě shì liúxuéshēng ma?) → Bạn cũng là du học sinh à?', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
