INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_1_2_3', 'lesson-1', 'txt_1_2', 'listening', 'listening', '早上好！', NULL, '[Bài 1] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Buổi chiều chúng ta đi nhé!","Chào buổi sáng!","Tớ học được môn Thái cực quyền rồi.","cuộc sống hạnh phúc"]'::jsonb, 1, 'Nội dung nghe được: 早上好！ (Zǎoshang hǎo) → Chào buổi sáng!', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_1_2_4', 'lesson-1', 'txt_1_2', 'listening', 'listening', '中午好！', NULL, '[Bài 1] Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["中午好！","你是日明吗？","张红 (Zhāng Hóng: Trương Hồng)是老师吗？","阮日明也是学生吗？"]'::jsonb, 0, 'Câu vừa đọc: 中午好！ (Zhōngwǔ hǎo) → Chào buổi trưa!', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO texts (id, lesson_id, title, description, sort_order) VALUES ('txt_1_3', 'lesson-1', 'Bài khoá mở rộng: Gặp gỡ đầu buổi học (Mở rộng)', 'Hội thoại tình huống mới xây dựng dựa trên từ vựng và ngữ pháp Bài 1 (không trùng lặp nguyên văn giáo trình).', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_1_3_1', 'txt_1_3', 'Minh', '老师，早上好！您是刘老师吗？', '老师，早上好 (zǎoshang hǎo: chào buổi sáng)！您是刘老师吗？', 'Lǎoshī, zǎoshang hǎo! Nín shì Liú lǎoshī ma?', 'Thưa thầy, chào buổi sáng ạ! Thầy có phải thầy Lưu không ạ?', 1) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_1_3_2', 'txt_1_3', 'Thầy Lưu', '早上好！我是刘老师。你是阮日明吗？', '早上好 (zǎoshang hǎo: chào buổi sáng)！我是刘老师。你是阮日明吗？', 'Zǎoshang hǎo! Wǒ shì Liú lǎoshī. Nǐ shì Ruǎn Rìmíng ma?', 'Chào buổi sáng! Tôi là thầy Lưu. Em là Nguyễn Nhật Minh phải không?', 2) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_1_3_3', 'txt_1_3', 'Minh', '是，我是阮日明，我是学校的新留学生。', '是，我是阮日明，我是学校的 (de: của)新 (xīn: mới)留学生。', 'Shì, wǒ shì Ruǎn Rìmíng, wǒ shì xuéxiào de xīn liúxuéshēng.', 'Vâng, em là Nguyễn Nhật Minh, em là du học sinh mới của trường.', 3) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_1_3_4', 'txt_1_3', 'Thầy Lưu', '欢迎！范玉兰也是留学生吗？', '欢迎 (huānyíng: chào mừng, chào đón)！范玉兰也是留学生吗？', 'Huānyíng! Fàn Yùlán yě shì liúxuéshēng ma?', 'Hoan nghênh em! Phạm Ngọc Lan cũng là du học sinh à?', 4) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_1_3_1', 'lesson-1', 'txt_1_3', 'listening', 'listening', '老师，早上好！您是刘老师吗？ 早上好！我是刘老师。你是阮日明吗？ 是，我是阮日明，我是学校的新留学生。 欢迎！范玉兰也是留学生吗？', NULL, '[Nghe hiểu tình huống mới] Theo đoạn hội thoại mở rộng trên, ai là giáo viên?', '["Phạm Ngọc Lan","Thầy Lưu (刘老师)","Nguyễn Nhật Minh","Một bạn học khác"]'::jsonb, 1, 'Trong bài, Nguyễn Nhật Minh hỏi và thầy xác nhận: ''我是刘老师''.', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_1_3_2', 'lesson-1', 'txt_1_3', 'listening', 'listening', '老师，早上好！您是刘老师吗？', NULL, '[Mở rộng] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Thưa thầy, chào buổi sáng ạ! Thầy có phải thầy Lưu không ạ?","Một con đường","đất nước (quốc gia) của chúng tôi","Quyển sách đó ở ngay trên bàn."]'::jsonb, 0, 'Nội dung nghe được: 老师，早上好！您是刘老师吗？ (Lǎoshī, zǎoshang hǎo! Nín shì Liú lǎoshī ma?) → Thưa thầy, chào buổi sáng ạ! Thầy có phải thầy Lưu không ạ?', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_1_3_3', 'lesson-1', 'txt_1_3', 'listening', 'listening', '早上好！我是刘老师。你是阮日明吗？', NULL, '[Mở rộng] Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["我也很 (hěn: rất)高兴 (gāoxìng: vui mừng)。","三 (sān: ba)个 (gè: cái, chiếc)朋友 (péngyou: bạn bè)","她 (tā: cô ấy, bà ấy)不 (bù: không)是兰兰 (Lánlan: Lan Lan)。","早上好 (zǎoshang hǎo: chào buổi sáng)！我是刘老师。你是阮日明吗？"]'::jsonb, 3, 'Câu vừa đọc: 早上好！我是刘老师。你是阮日明吗？ (Zǎoshang hǎo! Wǒ shì Liú lǎoshī. Nǐ shì Ruǎn Rìmíng ma?) → Chào buổi sáng! Tôi là thầy Lưu. Em là Nguyễn Nhật Minh phải không?', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_1_3_4', 'lesson-1', 'txt_1_3', 'listening', 'listening', '是，我是阮日明，我是学校的新留学生。', NULL, '[Mở rộng] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Các bạn học sinh","Nếu cậu gặp khó khăn thì tớ sẽ giúp đỡ.","Vâng, em là Nguyễn Nhật Minh, em là du học sinh mới của trường.","Đây là sách gì?"]'::jsonb, 2, 'Nội dung nghe được: 是，我是阮日明，我是学校的新留学生。 (Shì, wǒ shì Ruǎn Rìmíng, wǒ shì xuéxiào de xīn liúxuéshēng.) → Vâng, em là Nguyễn Nhật Minh, em là du học sinh mới của trường.', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
