INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq1_2', 'lesson-1', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, 'Từ Hán tự “老师” có nghĩa tiếng Việt là gì?', '["các bạn, các anh, các chị… (ngôi thứ hai số nhiều)","cũng","Giáo viên, thầy cô giáo","tốt, khỏe, hay, ngon..."]'::jsonb, 2, '“老师” (lǎoshī) là Danh từ, nghĩa là: Giáo viên, thầy cô giáo.', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq1_3', 'lesson-1', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, 'Từ Hán tự “同学” có nghĩa tiếng Việt là gì?', '["bạn, cậu, anh, chị... (ngôi thứ hai số ít)","buổi tối","buổi sáng","bạn học"]'::jsonb, 3, '“同学” (tóngxué) là Danh từ, nghĩa là: bạn học.', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq1_4', 'lesson-1', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, 'Từ Hán tự “学生” có nghĩa tiếng Việt là gì?', '["à, ư, hả... (đặt ở cuối câu nghi vấn)","các bạn, các anh, các chị… (ngôi thứ hai số nhiều)","học sinh","buổi trưa"]'::jsonb, 2, '“学生” (xuésheng) là Danh từ, nghĩa là: học sinh.', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq1_5', 'lesson-1', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, 'Từ Hán tự “留学生” có nghĩa tiếng Việt là gì?', '["du học sinh","học sinh","à, ư, hả... (đặt ở cuối câu nghi vấn)","chúng ta, chúng mình, chúng tôi… (ngôi thứ nhất số nhiều)"]'::jsonb, 0, '“留学生” (liúxuéshēng) là Danh từ, nghĩa là: du học sinh.', 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq1_6', 'lesson-1', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, 'Từ Hán tự “刘” có nghĩa tiếng Việt là gì?', '["Lưu (họ người)","buổi sáng","buổi tối","bạn, cậu, anh, chị... (ngôi thứ hai số ít)"]'::jsonb, 0, '“刘” (Liú) là Cụm từ / Tên riêng, nghĩa là: Lưu (họ người).', 6) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq1_7', 'lesson-1', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, 'Từ Hán tự “范玉兰” có nghĩa tiếng Việt là gì?', '["Phạm Ngọc Lan","bạn, cậu, anh, chị... (ngôi thứ hai số ít)","ngài, ông, bà... (cách gọi tôn trọng và lịch sự dành cho những người có địa vị cao...)","buổi chiều"]'::jsonb, 0, '“范玉兰” (Fàn Yùlán) là Cụm từ / Tên riêng, nghĩa là: Phạm Ngọc Lan.', 7) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
