INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq1_9', 'lesson-1', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, 'Phiên âm Pinyin chính xác của “吗” là gì?', '["yě","nǐmen","lǎoshī","ma"]'::jsonb, 3, '“吗” đọc là: ma (à, ư, hả... (đặt ở cuối câu nghi vấn)).', 9) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq1_10', 'lesson-1', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, 'Phiên âm Pinyin chính xác của “我们” là gì?', '["tóngxué","zǎoshang","wǒmen","liúxuéshēng"]'::jsonb, 2, '“我们” đọc là: wǒmen (chúng ta, chúng mình, chúng tôi… (ngôi thứ nhất số nhiều)).', 10) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq1_11', 'lesson-1', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, 'Phiên âm Pinyin chính xác của “我” là gì?', '["wǒ","yě","zǎoshang","nín"]'::jsonb, 0, '“我” đọc là: wǒ (tôi, tớ, mình... (ngôi thứ nhất số ít)).', 11) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq1_12', 'lesson-1', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, 'Phiên âm Pinyin chính xác của “你们” là gì?', '["xiàwǔ","wǎnshàng","nǐmen","wǒ"]'::jsonb, 2, '“你们” đọc là: nǐmen (các bạn, các anh, các chị… (ngôi thứ hai số nhiều)).', 12) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq1_13', 'lesson-1', NULL, 'expanded_quiz', 'radical', NULL, NULL, 'Chữ Hán “学校” chứa bộ thủ nào sau đây?', '["子 (Tử) (Đứa con, trẻ nhỏ, người trí thức)","酉 (Dậu) (Bình rượu, lên men, chưng cất)","儿 (Nhi) (Trẻ nhỏ, phần chân nâng đỡ)","干 (Can) (Can thiệp, khô ráo, làm việc)"]'::jsonb, 0, 'Chữ “学校” có bộ chính 子 (Tử) (Đứa con, trẻ nhỏ, người trí thức). Chiết tự: 学: ⺍ + 冖 (Mịch: mái che) + 子 (Tử: trẻ nhỏ) • 校: 木 (Mộc: cây gỗ) + 交 (Giao: giao nhau)', 13) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq1_14', 'lesson-1', NULL, 'expanded_quiz', 'radical', NULL, NULL, 'Chữ Hán “老师” chứa bộ thủ nào sau đây?', '["老/耂 (Lão) (Người già, lâu năm, tôn kính)","青 (Thanh) (Màu xanh, tươi trẻ)","凵 (Khảm) (Há miệng, hố trũng)","彡 (Sam) (Hoa văn, lông tóc, nét trang trí)"]'::jsonb, 0, 'Chữ “老师” có bộ chính 老/耂 (Lão) (Người già, lâu năm, tôn kính). Chiết tự: 老: 耂 (Lão: người già) + 匕 (Chủy) • 师: 𠂤 + 巾 (Cân: khăn vải)', 14) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq1_15', 'lesson-1', NULL, 'expanded_quiz', 'radical', NULL, NULL, 'Chữ Hán “同学” chứa bộ thủ nào sau đây?', '["夕 (Tịch) (Buổi chiều tối, đêm tối)","欠 (Khiếm) (Ngáp, thiếu thốn, hơi thở)","糸/纟 (Mịch) (Sợi tơ, gắn kết, màu sắc)","口 (Khẩu) (Miệng, ăn uống, lời nói, âm thanh phát ra)"]'::jsonb, 3, 'Chữ “同学” có bộ chính 口 (Khẩu) (Miệng, ăn uống, lời nói, âm thanh phát ra). Chiết tự: 同: 冂 (Quynh: khung bao) + 一 + 口 (Khẩu: cùng chung một tiếng) • 学: ⺍ + 冖 (Mịch: mái che) + 子 (Tử: trẻ nhỏ)', 15) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq1_16', 'lesson-1', NULL, 'expanded_quiz', 'radical', NULL, NULL, 'Chữ Hán “学生” chứa bộ thủ nào sau đây?', '["大 (Đại) (To lớn, vĩ đại)","止 (Chỉ) (Dừng lại, bàn chân bước)","子 (Tử) (Đứa con, trẻ nhỏ, người trí thức)","羊 (Dương) (Con dê, cừu, tốt đẹp)"]'::jsonb, 2, 'Chữ “学生” có bộ chính 子 (Tử) (Đứa con, trẻ nhỏ, người trí thức). Chiết tự: 学: ⺍ + 冖 (Mịch: mái che) + 子 (Tử: trẻ nhỏ) • 生: Bộ 生 (Sinh - mầm cây nảy từ đất, chữ độc thể)', 16) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq1_17', 'lesson-1', NULL, 'expanded_quiz', 'reading', NULL, NULL, '[Mở rộng] Câu “刘老师，下午好！” có nghĩa tiếng Việt là gì?', '["học sinh tiểu học","Ba người bạn (cách dùng đúng)","một người","Em chào thầy Lưu buổi chiều ạ!"]'::jsonb, 3, '刘老师，下午好！ (Liú lǎoshī, xiàwǔ hǎo!) → Em chào thầy Lưu buổi chiều ạ!', 17) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq1_18', 'lesson-1', NULL, 'expanded_quiz', 'reading', NULL, NULL, '[Mở rộng] Câu “你们晚上好！” có nghĩa tiếng Việt là gì?', '["Chào buổi tối các bạn!","Đây là sách gì?","môi trường sống","chị em tốt"]'::jsonb, 0, '你们晚上好！ (Nǐmen wǎnshang hǎo!) → Chào buổi tối các bạn!', 18) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq1_19', 'lesson-1', NULL, 'expanded_quiz', 'reading', NULL, NULL, '[Mở rộng] Câu “范玉兰是留学生吗？” có nghĩa tiếng Việt là gì?', '["môi trường làm việc","Anh ấy là ai?","bên trái (của) trường học","Phạm Ngọc Lan là du học sinh phải không?"]'::jsonb, 3, '范玉兰是留学生吗？ (Fàn Yùlán shì liúxuéshēng ma?) → Phạm Ngọc Lan là du học sinh phải không?', 19) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq1_20', 'lesson-1', NULL, 'expanded_quiz', 'reading', NULL, NULL, '[Mở rộng] Câu “阮日明也是学生吗？” có nghĩa tiếng Việt là gì?', '["Nữ sinh phía sau","Nguyễn Nhật Minh cũng là học sinh à?","Cô giáo không ở trong phòng làm việc.","ba cây bút chì"]'::jsonb, 1, '阮日明也是学生吗？ (Ruǎn Rìmíng yě shì xuésheng ma?) → Nguyễn Nhật Minh cũng là học sinh à?', 20) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
