INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq1_22', 'lesson-1', NULL, 'expanded_quiz', 'reading', NULL, NULL, 'Câu “老师好” có nghĩa tiếng Việt là gì?', '["Chào thầy/Chào cô","đứa bé vô cùng","Em chào thầy/cô ạ","phía trước (của) tôi"]'::jsonb, 0, '老师好 (Lǎoshī hǎo) → Chào thầy/Chào cô', 22) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct1_1', 'lesson-1', NULL, 'comprehensive_test', 'listening', '我是大学生。', NULL, 'Nghe đoạn ghi âm và chọn nghĩa tiếng Việt đúng:', '["Chào thầy/Chào cô","Các em học sinh, chào buổi sáng!","Phạm Ngọc Lan là du học sinh phải không?","Tôi là sinh viên."]'::jsonb, 3, 'Nội dung nghe được: “我是大学生。” (Wǒ shì dàxuéshēng.) → Tôi là sinh viên.', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct1_2', 'lesson-1', NULL, 'comprehensive_test', 'listening', '晚上好！', NULL, 'Nghe đoạn ghi âm và chọn câu tiếng Trung khớp với nội dung vừa nghe:', '["我是大学生。","老师您好！","晚上好！","早上好！"]'::jsonb, 2, 'Câu vừa đọc: “晚上好！” (Wǎnshang hǎo) → Chào buổi tối!', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
