INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v2_1', 'lesson-2', '贵姓', 'guìxìng', 'quý tính', 'họ, quý tính, quý danh (cách nói lịch sử)', 'Danh từ', '贝 (Bối) (Vỏ sò, tiền bạc, giá trị)', '贵: 中 (Trung biến thể) + 一 + 贝 (Bối: tiền bạc quý giá) • 姓: 女 (Nữ: mẹ) + 生 (Sinh: sinh ra dòng họ)', 'Ghép 贵 [bộ 贝] + 姓 [bộ 女] để nhớ từ 贵姓 (guìxìng): "họ, quý tính, quý danh (cách nói lịch sử)".', '这是关于“贵姓”的常用句子。', 'Zhè shì guānyú ''guìxìng'' de chángyòng jùzi.', 'Đây là câu ví dụ sử dụng từ ''贵姓'' (họ, quý tính, quý danh (cách nói lịch sử)).', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v2_2', 'lesson-2', '姓', 'xìng', 'tính', 'họ, tính', 'Danh từ / Động từ', '女 (Nữ) (Phụ nữ, gia đình, tình cảm)', '姓 = 女 (Nữ: mẹ) + 生 (Sinh: sinh ra dòng họ).', 'Chữ 姓 (xìng) mang nghĩa "họ, tính", bộ chính 女 (Nữ); cấu tạo: 女 (Nữ: mẹ) + 生 (Sinh: sinh ra dòng họ).', 'B: 我姓林。', 'Wǒ xìng Lín.', 'Tôi họ Lâm.', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v2_3', 'lesson-2', '名字', 'míngzi', 'danh tự', 'tên', 'Danh từ', '口 (Khẩu) (Miệng, ăn uống, lời nói, âm thanh phát ra)', '名: 夕 (Tịch: chiều tối) + 口 (Khẩu: gọi tên trong đêm) • 字: 宀 (Miên: mái nhà) + 子 (Tử: con cái, sinh sôi chữ nghĩa)', 'Ghép 名 [bộ 口] + 字 [bộ 子] để nhớ từ 名字 (míngzi): "tên".', 'A: 你叫什么名字？', 'Nǐ jiào shénme míngzi?', 'Bạn tên là gì?', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v2_4', 'lesson-2', '马克', 'Mǎkè', 'Mã khắc', 'Mark (du học sinh Mỹ)', 'Cụm từ / Tên riêng', '马 (Mã) (Con ngựa, chạy nhanh)', '马: Bộ 马 (Mã - hình dáng con ngựa, chữ độc thể) • 克: 十 (Thập) + 口 (Khẩu) + 儿 (Nhi)', 'Ghép 马 [bộ 马] + 克 [bộ 儿] để nhớ từ 马克 (Mǎkè): "Mark (du học sinh Mỹ)".', '我叫马克。她叫什么名字？', 'Wǒ jiào Mǎkè. Tā jiào shénme míngzi?', 'Tôi tên là Mark. Cô ấy tên là gì?', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v2_5', 'lesson-2', '张风', 'Zhāng Fēng', 'phong', 'Trương Phong (sinh viên người Trung Quốc đại học Thanh Hoa)', 'Cụm từ / Tên riêng', '弓 (Cung) (Cây cung, độ căng, uốn cong)', '张: 弓 (Cung: cây cung) + 长 (Trường: kéo dài dây cung) • 风: Bộ 风 (Phong - khung gió và nét phẩy chấm, chữ độc thể)', 'Ghép 张 [bộ 弓] + 风 [bộ 风] để nhớ từ 张风 (Zhāng Fēng): "Trương Phong (sinh viên người Trung Quốc đại học Thanh Hoa)".', '是。我叫张风。你叫什么名字？', 'Shì. Wǒ jiào Zhāng Fēng. Nǐ jiào shénme míngzi?', 'Đúng rồi. Tôi tên là Trương Phong. Bạn tên là gì?', 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v2_6', 'lesson-2', '白茹雪', 'Bái Rúxuě', 'bạch tuyết', 'Bạch Như Tuyết (sinh viên người Trung Quốc đại học Bắc Kinh)', 'Cụm từ / Tên riêng', '白 (Bạch) (Màu trắng, sáng tỏ)', '白: Bộ 白 (Bạch - ánh sáng trắng, chữ độc thể) • 茹: 艹 (Thảo: cỏ cây) + 如 (Như) • 雪: 雨 (Vũ: mưa) + 彐 (Kệ: kết thành bông tuyết)', 'Ghép 白 [bộ 白] + 茹 [bộ 艹] + 雪 [bộ 雨] để nhớ từ 白茹雪 (Bái Rúxuě): "Bạch Như Tuyết (sinh viên người Trung Quốc đại học Bắc Kinh)".', '她是白茹雪。', 'Tā shì Bái Rúxuě.', 'Cô ấy là Bạch Như Tuyết.', 6) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v2_7', 'lesson-2', '明天', 'míngtiān', 'minh thiên', 'ngày mai', 'Danh từ', '日 (Nhật) (Mặt trời, ban ngày, thời gian, ánh sáng)', '明: 日 (Nhật: mặt trời) + 月 (Nguyệt: mặt trăng) • 天: 一 (Nhất: bầu trời cao) + 大 (Đại: con người dang tay)', 'Ghép 明 [bộ 日] + 天 [bộ 大] để nhớ từ 明天 (míngtiān): "ngày mai".', '明天见！', 'Míngtiān jiàn!', 'Hẹn gặp lại vào ngày mai! (Hoặc “Mai gặp nhé!”)', 7) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v2_8', 'lesson-2', '现在', 'xiànzài', 'hiện tại', 'hiện tại, bây giờ', 'Danh từ', '玉/王 (Ngọc) (Đá quý, vua chúa)', '现: 王 (Ngọc: viên ngọc sáng) + 见 (Kiến: nhìn thấy) • 在: 𠂇 + 土 (Thổ: tồn tại trên mặt đất)', 'Ghép 现 [bộ 王] + 在 [bộ 土] để nhớ từ 现在 (xiànzài): "hiện tại, bây giờ".', '这是关于“现在”的常用句子。', 'Zhè shì guānyú ''xiànzài'' de chángyòng jùzi.', 'Đây là câu ví dụ sử dụng từ ''现在'' (hiện tại, bây giờ).', 8) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v2_9', 'lesson-2', '她', 'tā', 'từ Hán ngữ', 'cô ấy, bà ấy, chị ấy,... (ngôi thứ ba số ít chỉ nữ)', 'Đại từ', '女 (Nữ) (Phụ nữ, gia đình, tình cảm)', '她 = 女 (Nữ: phụ nữ) + 也 (Dã).', 'Chữ 她 (tā) mang nghĩa "cô ấy, bà ấy, chị ấy,... (ngôi thứ ba số ít chỉ nữ)", bộ chính 女 (Nữ); cấu tạo: 女 (Nữ: phụ nữ) + 也 (Dã).', '我叫马克。她叫什么名字？', 'Wǒ jiào Mǎkè. Tā jiào shénme míngzi?', 'Tôi tên là Mark. Cô ấy tên là gì?', 9) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v2_10', 'lesson-2', '什么', 'shénme', 'thập ma', 'cái gì, gì', 'Đại từ', '人/亻 (Nhân) (Con người, nhân loại, hành động)', '什: 亻 (Nhân đứng) + 十 (Thập) • 么: 丿 (Phiệt) + 厶 (Tư)', 'Ghép 什 [bộ 亻] + 么 [bộ 丿] để nhớ từ 什么 (shénme): "cái gì, gì".', 'A: 你叫什么名字？', 'Nǐ jiào shénme míngzi?', 'Bạn tên là gì?', 10) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v2_11', 'lesson-2', '叫', 'jiào', 'khiếu', 'gọi, kêu', 'Động từ', '口 (Khẩu) (Miệng, ăn uống, lời nói, âm thanh phát ra)', '叫 = 口 (Khẩu: miệng) + 丩 (Cưu: tiếng kêu).', 'Chữ 叫 (jiào) mang nghĩa "gọi, kêu", bộ chính 口 (Khẩu); cấu tạo: 口 (Khẩu: miệng) + 丩 (Cưu: tiếng kêu).', 'A: 你叫什么名字？', 'Nǐ jiào shénme míngzi?', 'Bạn tên là gì?', 11) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v2_12', 'lesson-2', '上课', 'shàng kè', 'thượng', 'vào học, lên lớp', 'Động từ', '一 (Nhất) (Số một, nền tảng, nét ngang cơ bản)', '上: Nét đứng 丨 và nét chấm chỉ hướng phía trên gạch ngang 一 • 课: 讠 (Ngôn: lời giảng) + 果 (Quả: kết quả)', 'Ghép 上 [bộ 一] + 课 [bộ 讠] để nhớ từ 上课 (shàng kè): "vào học, lên lớp".', '我明天上午八点上课。', 'Wǒ míngtiān shàngwǔ bā diǎn shàngkè.', 'Tám giờ sáng ngày mai tớ đi học.', 12) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v2_13', 'lesson-2', '见', 'jiàn', 'từ Hán ngữ', 'nhìn thấy, gặp', 'Động từ', '见 (Kiến) (Nhìn thấy, gặp gỡ)', '见 = Bộ 见 (Kiến - con mắt phía trên đôi chân, nhìn thấy).', 'Chữ 见 (jiàn) mang nghĩa "nhìn thấy, gặp", bộ chính 见 (Kiến); cấu tạo: Bộ 见 (Kiến - con mắt phía trên đôi chân, nhìn thấy).', '再见！', 'Zàijiàn!', 'Tạm biệt!', 13) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v2_14', 'lesson-2', '再见', 'zàijiàn', 'từ Hán ngữ', 'tạm biệt, hẹn gặp lại', 'Động từ', '冂 (Quynh) (Vùng biên giới, khung bao)', '再: 一 + 冂 (Quynh) + 土 (Thổ) • 见: Bộ 见 (Kiến - con mắt phía trên đôi chân, nhìn thấy)', 'Ghép 再 [bộ 冂] + 见 [bộ 见] để nhớ từ 再见 (zàijiàn): "tạm biệt, hẹn gặp lại".', '再见！', 'Zàijiàn!', 'Tạm biệt!', 14) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v2_15', 'lesson-2', '要', 'yào', 'yếu', 'phải', 'Động từ năng nguyện', '西/覀 (Tây) (Phương tây, che đậy)', '要 = 覀 (Tây biến thể) + 女 (Nữ).', 'Chữ 要 (yào) mang nghĩa "phải", bộ chính 西/覀 (Tây); cấu tạo: 覀 (Tây biến thể) + 女 (Nữ).', '我要回宿舍了。再见!', 'Wǒ yào huí sùshè le. Zàijiàn!', 'Tôi phải về ký túc xá rồi. Tạm biệt!', 15) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v2_16', 'lesson-2', '回', 'huí', 'từ Hán ngữ', 'về, trở về, trở lại', 'Động từ', '囗 (Vi) (Vây quanh, không gian kín, lãnh thổ)', '回 = 囗 (Vi: vòng ngoài) + 口 (Khẩu: vòng trong, quay về).', 'Chữ 回 (huí) mang nghĩa "về, trở về, trở lại", bộ chính 囗 (Vi); cấu tạo: 囗 (Vi: vòng ngoài) + 口 (Khẩu: vòng trong, quay về).', '我要回宿舍了。再见!', 'Wǒ yào huí sùshè le. Zàijiàn!', 'Tôi phải về ký túc xá rồi. Tạm biệt!', 16) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v2_17', 'lesson-2', '宿舍', 'sùshè', 'từ Hán ngữ', 'ký túc xá', 'Danh từ', '宀 (Miên) (Mái nhà, che chở, nơi ở)', '宿: 宀 (Miên: mái nhà) + 亻 (Nhân) + 百 (Bách: trăm người nghỉ) • 舍: 人 (Nhân: mái chóp) + 舌 (Thiệt)', 'Ghép 宿 [bộ 宀] + 舍 [bộ 舌] để nhớ từ 宿舍 (sùshè): "ký túc xá".', '我要回宿舍了。再见!', 'Wǒ yào huí sùshè le. Zàijiàn!', 'Tôi phải về ký túc xá rồi. Tạm biệt!', 17) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v2_18', 'lesson-2', '了', 'le', 'từ Hán ngữ', 'rồi', 'Trợ từ', '亅 (Quyết) (Nét móc đứng)', '了 = Bộ 亅 (Quyết - nét móc kết thúc, chữ độc thể).', 'Chữ 了 (le) mang nghĩa "rồi", bộ chính 亅 (Quyết); cấu tạo: Bộ 亅 (Quyết - nét móc kết thúc, chữ độc thể).', '你昨天去学校了吗？', 'Nǐ zuótiān qù xuéxiào le ma?', 'Hôm qua cậu đã đến trường chưa?', 18) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order) VALUES ('g2_1', 'lesson-2', '1. Cách chào tạm biệt', 'Cấu trúc câu ngữ pháp trọng tâm', ' Có một số câu chào tạm biệt đơn giản như sau: 再见！/Zàijiàn!/: Tạm biệt! 明天见！/Míngtiān jiàn!/: Hẹn gặp lại vào ngày mai! (Hoặc “Mai gặp nhé!”) 拜拜！/Bàibai!/:   Bye! (thường dùng trong giới trẻ)', NULL, '[{"hanzi":"再见！","pinyin":"Zàijiàn!","meaning":"Tạm biệt!"},{"hanzi":"明天见！","pinyin":"Míngtiān jiàn!","meaning":"Hẹn gặp lại vào ngày mai! (Hoặc “Mai gặp nhé!”)"}]'::jsonb, 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order) VALUES ('g2_2', 'lesson-2', '2. Cách hỏi tên và trả lời', 'Cấu trúc câu ngữ pháp trọng tâm', ' a. Cách hỏi Khi muốn hỏi tên ai đó, có thể sử dụng các mẫu câu sau: * 您贵姓？ Cách hỏi này mang ngữ khí lịch sự, thường dùng để hỏi họ của người có địa vị cao hơn người nói, người lớn tuổi hơn, ... * 你叫什么(名字)？ Cách hỏi này mang ngữ khí tự nhiên hơn, th', NULL, '[{"hanzi":"拜拜！","pinyin":"Bàibai!","meaning":"Bye! (thường dùng trong giới trẻ)"},{"hanzi":"B: 我姓林。","pinyin":"Wǒ xìng Lín.","meaning":"Tôi họ Lâm."}]'::jsonb, 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order) VALUES ('g2_3', 'lesson-2', '3. Đại từ nghi vấn 什么', 'Cấu trúc câu ngữ pháp trọng tâm', ' - 什么 là đại từ nghi vấn, biểu thị ý nghĩa “cái gì, thứ gì, gì”. 你说什么？ Nǐ shuō shénme? Cậu nói gì? - Đại từ nghi vấn 什么 cũng có thể đứng trước danh từ, hỏi thành phần tu sức cho danh từ trung tâm, làm rõ chủng loại,... (Nội dung này sẽ được làm rõ hơ', NULL, '[{"hanzi":"A: 你叫什么名字？","pinyin":"Nǐ jiào shénme míngzi?","meaning":"Bạn tên là gì?"},{"hanzi":"B: 我叫陈英。","pinyin":"Wǒ jiào Chén Yīng.","meaning":"Tôi là Trần Anh."}]'::jsonb, 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order) VALUES ('g2_4', 'lesson-2', '4. Trạng ngữ chỉ thời gian', 'Cấu trúc câu ngữ pháp trọng tâm', ' a. Khái niệm Trạng ngữ chỉ thời gian do danh từ hoặc cụm danh từ biểu thị thời gian đảm nhiệm, biểu thị thời gian xảy ra hiện tượng, động tác,... b. Cách dùng Trạng ngữ chỉ thời gian thường đứng sát ngay trước động từ, tính từ (sau chủ ngữ) hoặc trư', NULL, '[{"hanzi":"你说什么？","pinyin":"Nǐ shuō shénme?","meaning":"Cậu nói gì?"},{"hanzi":"这是什么书？","pinyin":"Zhè shì shénme shū?","meaning":"Đây là sách gì?"}]'::jsonb, 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order;
INSERT INTO texts (id, lesson_id, title, description, sort_order) VALUES ('txt_2_1', 'lesson-2', 'Bài khoá #1: Hội thoại giáo trình — Chào hỏi (2)', 'Hội thoại chuẩn giáo trình Bài 2. Từ vựng chưa học được chú thích phiên âm & nghĩa trong ngoặc.', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_2_1_1', 'txt_2_1', '张风', '你好！', '你好！', 'Nǐ hǎo!', 'Xin chào!', 1) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_2_1_2', 'txt_2_1', '马克', '你好！你也是学生吗？', '你好！你也是学生吗？', 'Nǐ hǎo! Nǐ yě shì xuésheng ma?', 'Xin chào! Bạn cũng là học sinh à?', 2) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_2_1_3', 'txt_2_1', '张风', '是。我叫张风。你叫什么名字？', '是。我叫张风。你叫什么名字？', 'Shì. Wǒ jiào Zhāng Fēng. Nǐ jiào shénme míngzi?', 'Đúng rồi. Tôi tên là Trương Phong. Bạn tên là gì?', 3) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_2_1_4', 'txt_2_1', '马克', '我叫马克。她叫什么名字？', '我叫马克。她叫什么名字？', 'Wǒ jiào Mǎkè. Tā jiào shénme míngzi?', 'Tôi tên là Mark. Cô ấy tên là gì?', 4) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_2_1_5', 'txt_2_1', '张风', '她是白茹雪。', '她是白茹雪。', 'Tā shì Bái Rúxuě.', 'Cô ấy là Bạch Như Tuyết.', 5) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_2_1_1', 'lesson-2', 'txt_2_1', 'listening', 'listening', '你好！', NULL, 'Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Xin chào!","Khó quá đi, tôi không biết nên làm như thế nào nữa!","Bạn tôi sắp đi Trùng Khánh du học rồi.","Nếu ngày mai mưa thì chúng tôi sẽ không đi chơi nữa."]'::jsonb, 0, 'Nội dung nghe được: 你好！ (Nǐ hǎo!) → Xin chào!', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_2_1_2', 'lesson-2', 'txt_2_1', 'listening', 'listening', '你好！你也是学生吗？', NULL, 'Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["B: 我叫陈英 (Chén Yīng: Trần Anh)。","B: 我姓林 (Lín: Lâm)。","我姓范，叫范玉兰。","你好！你也是学生吗？"]'::jsonb, 3, 'Câu vừa đọc: 你好！你也是学生吗？ (Nǐ hǎo! Nǐ yě shì xuésheng ma?) → Xin chào! Bạn cũng là học sinh à?', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_2_1_3', 'lesson-2', 'txt_2_1', 'listening', 'listening', '是。我叫张风。你叫什么名字？', NULL, 'Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Ngày mai tôi sẽ đi Thượng Hải.","Đúng rồi. Tôi tên là Trương Phong. Bạn tên là gì?","Hôm nay anh ta bảo tôi tháng sau ra nước ngoài.","Tôi có một cậu em trai."]'::jsonb, 1, 'Nội dung nghe được: 是。我叫张风。你叫什么名字？ (Shì. Wǒ jiào Zhāng Fēng. Nǐ jiào shénme míngzi?) → Đúng rồi. Tôi tên là Trương Phong. Bạn tên là gì?', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_2_1_4', 'lesson-2', 'txt_2_1', 'listening', 'listening', '我叫马克。她叫什么名字？', NULL, 'Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["你好！","A: 你叫什么名字？","我叫马克。她叫什么名字？","再见！"]'::jsonb, 2, 'Câu vừa đọc: 我叫马克。她叫什么名字？ (Wǒ jiào Mǎkè. Tā jiào shénme míngzi?) → Tôi tên là Mark. Cô ấy tên là gì?', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
