INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_2_3_1', 'lesson-2', 'txt_2_3', 'listening', 'listening', '你是日明吗？', NULL, '[Ôn tập Bài 1] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Cậu là Nhật Minh phải không?","tiếng gõ cửa","Cậu hãy cố gắng nghĩ nữa đi.","Năm nay tôi 60 rồi."]'::jsonb, 0, 'Nội dung nghe được: 你是日明吗？ (Nǐ shì Rìmíng ma?) → Cậu là Nhật Minh phải không?', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_2_3_2', 'lesson-2', 'txt_2_3', 'listening', 'listening', '再见！', NULL, '[Bài 2] Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["她是白茹雪。","再见！","她叫什么名字？","你说 (shuō: nói)什么？"]'::jsonb, 1, 'Câu vừa đọc: 再见！ (Zàijiàn!) → Tạm biệt!', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_2_3_3', 'lesson-2', 'txt_2_3', 'listening', 'listening', '老师好', NULL, '[Ôn tập Bài 1] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["thời gian bắt đầu cuộc họp","Tôi có một cậu em trai.","Chào thầy/Chào cô","Trong phòng học có 3 người."]'::jsonb, 2, 'Nội dung nghe được: 老师好 (Lǎoshī hǎo) → Chào thầy/Chào cô', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_2_3_4', 'lesson-2', 'txt_2_3', 'listening', 'listening', '明天见！', NULL, '[Bài 2] Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["B: 我姓林 (Lín: Lâm)。","她叫什么名字？","明天见！","你好！你也是学生吗？"]'::jsonb, 2, 'Câu vừa đọc: 明天见！ (Míngtiān jiàn!) → Hẹn gặp lại vào ngày mai! (Hoặc “Mai gặp nhé!”)', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_2_3_5', 'lesson-2', 'txt_2_3', 'listening', 'listening', '晚上好！', NULL, '[Ôn tập Bài 1] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Chào buổi tối!","Cô ấy là Bạch Như Tuyết.","Cậu ấy vội vàng vẫy tay với tôi.","đất nước (quốc gia) của chúng tôi"]'::jsonb, 0, 'Nội dung nghe được: 晚上好！ (Wǎnshang hǎo) → Chào buổi tối!', 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO texts (id, lesson_id, title, description, sort_order) VALUES ('txt_2_4', 'lesson-2', 'Bài khoá mở rộng: Làm quen sau giờ học (Mở rộng)', 'Hội thoại tình huống mới xây dựng dựa trên từ vựng và ngữ pháp Bài 2 (không trùng lặp nguyên văn giáo trình).', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_2_4_1', 'txt_2_4', 'Lan', '你好，同学！请问你贵姓？', '你好，同学！请问 (qǐngwèn: xin hỏi)你贵姓？', 'Nǐ hǎo, tóngxué! Qǐngwèn nín guìxìng?', 'Chào bạn! Xin hỏi bạn họ gì vậy?', 1) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_2_4_2', 'txt_2_4', 'Phong', '我姓张，叫张风。现在我要去上课了。', '我姓张 (zhāng: tờ, tấm, chiếc)，叫张风。现在我要去 (qù: đi)上课了。', 'Wǒ xìng Zhāng, jiào Zhāng Fēng. Xiànzài wǒ yào qù shàngkè le.', 'Tôi họ Trương, tên là Trương Phong. Bây giờ tôi phải đi học rồi.', 2) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_2_4_3', 'txt_2_4', 'Lan', '我也去上课。明天我们什么时候见？', '我也去 (qù: đi)上课。明天我们什么时候 (shíhou: thời gian, lúc)见？', 'Wǒ yě qù shàngkè. Míngtiān wǒmen shénme shíhou jiàn?', 'Tôi cũng đi học đây. Ngày mai chúng ta gặp nhau lúc nào?', 3) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_2_4_4', 'txt_2_4', 'Phong', '明天早上见，再见！', '明天早上见，再见！', 'Míngtiān zǎoshang jiàn, zàijiàn!', 'Sáng mai gặp lại nhé, tạm biệt!', 4) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_2_4_1', 'lesson-2', 'txt_2_4', 'listening', 'listening', '你好，同学！请问你贵姓？ 我姓张，叫张风。现在我要去上课了。 我也去上课。明天我们什么时候见？ 明天早上见，再见！', NULL, '[Nghe hiểu tình huống mới] Bạn nam họ Trương tên đầy đủ là gì và hẹn gặp lại khi nào?', '["Mark, hẹn gặp tuần sau","Trương Minh, hẹn gặp vào tối nay","Trương Phong, hẹn gặp lại vào sáng mai","Bạch Như Tuyết, không hẹn gặp"]'::jsonb, 2, 'Bạn nam tự giới thiệu tên 张风 và hẹn 明天早上见 (sáng mai gặp).', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_2_4_2', 'lesson-2', 'txt_2_4', 'listening', 'listening', '你好，同学！请问你贵姓？', NULL, '[Mở rộng] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Chào buổi sáng!","Chào bạn! Xin hỏi bạn họ gì vậy?","Cậu nói gì vậy?","Tôi có một cậu em trai."]'::jsonb, 1, 'Nội dung nghe được: 你好，同学！请问你贵姓？ (Nǐ hǎo, tóngxué! Qǐngwèn nín guìxìng?) → Chào bạn! Xin hỏi bạn họ gì vậy?', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_2_4_3', 'lesson-2', 'txt_2_4', 'listening', 'listening', '我姓张，叫张风。现在我要去上课了。', NULL, '[Mở rộng] Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["她是白茹雪。","好，明天见！","这 (zhè: đây, này)是什么书 (shū: sách)？","我姓张 (zhāng: tờ, tấm, chiếc)，叫张风。现在我要去 (qù: đi)上课了。"]'::jsonb, 3, 'Câu vừa đọc: 我姓张，叫张风。现在我要去上课了。 (Wǒ xìng Zhāng, jiào Zhāng Fēng. Xiànzài wǒ yào qù shàngkè le.) → Tôi họ Trương, tên là Trương Phong. Bây giờ tôi phải đi học rồi.', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_2_4_4', 'lesson-2', 'txt_2_4', 'listening', 'listening', '我也去上课。明天我们什么时候见？', NULL, '[Mở rộng] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Thành tích kiểm tra của anh ấy chẳng ra làm sao. (Ý nói kết quả kém)","thành tích kiểm tra","Tôi cũng đi học đây. Ngày mai chúng ta gặp nhau lúc nào?","Một chiếc khăn"]'::jsonb, 2, 'Nội dung nghe được: 我也去上课。明天我们什么时候见？ (Wǒ yě qù shàngkè. Míngtiān wǒmen shénme shíhou jiàn?) → Tôi cũng đi học đây. Ngày mai chúng ta gặp nhau lúc nào?', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
