INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr2_zh_exp_7', 'lesson-2', 'zh_to_vi', '明天早上见，再见！', '明天早上见，再见！', 'Míngtiān zǎoshang jiàn, zàijiàn!', NULL, 'Sáng mai gặp lại nhé, tạm biệt!', NULL, '["sáng","mai","gặp","lại","nhé","tạm","biệt"]'::jsonb, 'Pinyin: Míngtiān zǎoshang jiàn, zàijiàn!', '明天早上见，再见！ (Míngtiān zǎoshang jiàn, zàijiàn!) nghĩa là: Sáng mai gặp lại nhé, tạm biệt!', 25) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr2_zh_exp_8', 'lesson-2', 'zh_to_vi', '我也去上课。明天我们什么时候见？', '我也去上课。明天我们什么时候见？', 'Wǒ yě qù shàngkè. Míngtiān wǒmen shénme shíhou jiàn?', NULL, 'Tôi cũng đi học đây. Ngày mai chúng ta gặp nhau lúc nào?', NULL, '["tôi","cũng","đi","học","đây","ngày","mai","chúng","ta","gặp","nhau","lúc","nào"]'::jsonb, 'Pinyin: Wǒ yě qù shàngkè. Míngtiān wǒmen shénme shíhou jiàn?', '我也去上课。明天我们什么时候见？ (Wǒ yě qù shàngkè. Míngtiān wǒmen shénme shíhou jiàn?) nghĩa là: Tôi cũng đi học đây. Ngày mai chúng ta gặp nhau lúc nào?', 26) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr2_zh_exp_9', 'lesson-2', 'zh_to_vi', '我姓张，叫张风。现在我要去上课了。', '我姓张，叫张风。现在我要去上课了。', 'Wǒ xìng Zhāng, jiào Zhāng Fēng. Xiànzài wǒ yào qù shàngkè le.', NULL, 'Tôi họ Trương, tên là Trương Phong. Bây giờ tôi phải đi học rồi.', NULL, '["tôi","họ","trương","tên","là","trương","phong","bây","giờ","tôi","phải","đi","học","rồi"]'::jsonb, 'Pinyin: Wǒ xìng Zhāng, jiào Zhāng Fēng. Xiànzài wǒ yào qù shàngkè le.', '我姓张，叫张风。现在我要去上课了。 (Wǒ xìng Zhāng, jiào Zhāng Fēng. Xiànzài wǒ yào qù shàngkè le.) nghĩa là: Tôi họ Trương, tên là Trương Phong. Bây giờ tôi phải đi học rồi.', 27) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr2_zh_exp_10', 'lesson-2', 'zh_to_vi', '你好，同学！请问你贵姓？', '你好，同学！请问你贵姓？', 'Nǐ hǎo, tóngxué! Qǐngwèn nín guìxìng?', NULL, 'Chào bạn! Xin hỏi bạn họ gì vậy?', NULL, '["chào","bạn","xin","hỏi","bạn","họ","gì","vậy"]'::jsonb, 'Pinyin: Nǐ hǎo, tóngxué! Qǐngwèn nín guìxìng?', '你好，同学！请问你贵姓？ (Nǐ hǎo, tóngxué! Qǐngwèn nín guìxìng?) nghĩa là: Chào bạn! Xin hỏi bạn họ gì vậy?', 28) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
