INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq2_13', 'lesson-2', NULL, 'expanded_quiz', 'radical', NULL, NULL, 'Chữ Hán “贵姓” chứa bộ thủ nào sau đây?', '["衣/衤 (Y) (Áo quần, y phục)","贝 (Bối) (Vỏ sò, tiền bạc, giá trị)","黑 (Hắc) (Màu đen, tối tăm)","夕 (Tịch) (Buổi chiều tối, đêm tối)"]'::jsonb, 1, 'Chữ “贵姓” có bộ chính 贝 (Bối) (Vỏ sò, tiền bạc, giá trị). Chiết tự: 贵: 中 (Trung biến thể) + 一 + 贝 (Bối: tiền bạc quý giá) • 姓: 女 (Nữ: mẹ) + 生 (Sinh: sinh ra dòng họ)', 13) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq2_14', 'lesson-2', NULL, 'expanded_quiz', 'radical', NULL, NULL, 'Chữ Hán “姓” chứa bộ thủ nào sau đây?', '["女 (Nữ) (Phụ nữ, gia đình, tình cảm)","斤 (Cân) (Cái rìu, đơn vị cân nặng)","石 (Thạch) (Hòn đá, vật cứng)","阝 (Phụ/Ấp) (Gò đất hoặc vùng đất, thành ấp)"]'::jsonb, 0, 'Chữ “姓” có bộ chính 女 (Nữ) (Phụ nữ, gia đình, tình cảm). Chiết tự: 姓 = 女 (Nữ: mẹ) + 生 (Sinh: sinh ra dòng họ).', 14) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq2_15', 'lesson-2', NULL, 'expanded_quiz', 'radical', NULL, NULL, 'Chữ Hán “名字” chứa bộ thủ nào sau đây?', '["女 (Nữ) (Phụ nữ, gia đình, tình cảm)","口 (Khẩu) (Miệng, ăn uống, lời nói, âm thanh phát ra)","歹 (Ngạt) (Xấu xa, xương tàn, nguy hiểm)","羊 (Dương) (Con dê, cừu, tốt đẹp)"]'::jsonb, 1, 'Chữ “名字” có bộ chính 口 (Khẩu) (Miệng, ăn uống, lời nói, âm thanh phát ra). Chiết tự: 名: 夕 (Tịch: chiều tối) + 口 (Khẩu: gọi tên trong đêm) • 字: 宀 (Miên: mái nhà) + 子 (Tử: con cái, sinh sôi chữ nghĩa)', 15) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq2_16', 'lesson-2', NULL, 'expanded_quiz', 'radical', NULL, NULL, 'Chữ Hán “马克” chứa bộ thủ nào sau đây?', '["马 (Mã) (Con ngựa, chạy nhanh)","廾 (Củng) (Hai tay chắp, nâng đỡ)","瓦 (Ngõa) (Ngói, đồ gốm sứ)","衣/衤 (Y) (Áo quần, y phục)"]'::jsonb, 0, 'Chữ “马克” có bộ chính 马 (Mã) (Con ngựa, chạy nhanh). Chiết tự: 马: Bộ 马 (Mã - hình dáng con ngựa, chữ độc thể) • 克: 十 (Thập) + 口 (Khẩu) + 儿 (Nhi)', 16) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq2_17', 'lesson-2', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, '[Ôn tập Bài 1] Từ đã học “您” (nín) có nghĩa là gì?', '["hiện tại, bây giờ","ngài, ông, bà... (cách gọi tôn trọng và lịch sự dành cho những người có địa vị cao...)","bạn, cậu, anh, chị... (ngôi thứ hai số ít)","buổi tối"]'::jsonb, 1, 'Ôn tập Bài 1: “您” (nín) nghĩa là: ngài, ông, bà... (cách gọi tôn trọng và lịch sự dành cho những người có địa vị cao...).', 17) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq2_18', 'lesson-2', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, '[Ôn tập Bài 1] Từ đã học “是” (shì) có nghĩa là gì?', '["phải","là, thì...","Trường học","hiện tại, bây giờ"]'::jsonb, 1, 'Ôn tập Bài 1: “是” (shì) nghĩa là: là, thì....', 18) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq2_19', 'lesson-2', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, '[Ôn tập Bài 1] Từ đã học “好” (hǎo) có nghĩa là gì?', '["rồi","tốt, khỏe, hay, ngon...","Bạch Như Tuyết (sinh viên người Trung Quốc đại học Bắc Kinh)","tên"]'::jsonb, 1, 'Ôn tập Bài 1: “好” (hǎo) nghĩa là: tốt, khỏe, hay, ngon....', 19) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq2_20', 'lesson-2', NULL, 'expanded_quiz', 'reading', NULL, NULL, '[Mở rộng] Câu “现在我要上课了。” có nghĩa tiếng Việt là gì?', '["cây thước kẻ của anh ấy","Tôi đợi các bạn ở cổng trường.","Nữ sinh phía sau","Bây giờ tôi phải vào lớp học rồi."]'::jsonb, 3, '现在我要上课了。 (Xiànzài wǒ yào shàngkè le.) → Bây giờ tôi phải vào lớp học rồi.', 20) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
