INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq2_22', 'lesson-2', NULL, 'expanded_quiz', 'reading', NULL, NULL, 'Câu “再见！” có nghĩa tiếng Việt là gì?', '["Em chào thầy/cô ạ","Tạm biệt!","Tám giờ sáng ngày mai tớ đi học.","phía trước (của) tôi"]'::jsonb, 1, '再见！ (Zàijiàn!) → Tạm biệt!', 22) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct2_1', 'lesson-2', NULL, 'comprehensive_test', 'listening', '我叫陈英。', NULL, 'Nghe đoạn ghi âm và chọn nghĩa tiếng Việt đúng:', '["Tám giờ sáng ngày mai tớ đi học.","Các thầy cô giáo","Vâng, em là Nguyễn Nhật Minh, em là du học sinh mới của trường.","Tôi là Trần Anh."]'::jsonb, 3, 'Nội dung nghe được: “我叫陈英。” (Wǒ jiào Chén Yīng.) → Tôi là Trần Anh.', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct2_2', 'lesson-2', NULL, 'comprehensive_test', 'listening', '你是日明吗？', NULL, 'Nghe đoạn ghi âm và chọn câu tiếng Trung khớp với nội dung vừa nghe:', '["早上好！","她是白茹雪。","你是日明吗？","我姓张，叫张风。现在我要去上课了。"]'::jsonb, 2, 'Câu vừa đọc: “你是日明吗？” (Nǐ shì Rìmíng ma?) → Cậu là Nhật Minh phải không?', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct2_3', 'lesson-2', NULL, 'comprehensive_test', 'listening', '现在我要上课了', NULL, 'Nghe đoạn ghi âm và chọn nghĩa tiếng Việt đúng:', '["Các bạn học sinh","Thầy Lưu là giáo viên của trường.","Bây giờ tôi phải vào lớp học rồi.","Xin chào! Bạn cũng là học sinh à?"]'::jsonb, 2, 'Nội dung nghe được: “现在我要上课了” (Xiànzài wǒ yào shàngkè le.) → Bây giờ tôi phải vào lớp học rồi.', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct2_4', 'lesson-2', NULL, 'comprehensive_test', 'listening', '刘老师是学校的老师', NULL, 'Nghe đoạn ghi âm và chọn câu tiếng Trung khớp với nội dung vừa nghe:', '["下午好！","她是白茹雪。","刘老师是学校的老师","我要回宿舍了。再见!"]'::jsonb, 2, 'Câu vừa đọc: “刘老师是学校的老师” (Liú lǎoshī shì xuéxiào de lǎoshī.) → Thầy Lưu là giáo viên của trường.', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct2_5', 'lesson-2', NULL, 'comprehensive_test', 'listening', '阮日明也是学生吗', NULL, 'Nghe đoạn ghi âm và chọn nghĩa tiếng Việt đúng:', '["Chào buổi tối các bạn!","Các thầy cô giáo","Phạm Ngọc Lan là du học sinh phải không?","Nguyễn Nhật Minh cũng là học sinh à?"]'::jsonb, 3, 'Nội dung nghe được: “阮日明也是学生吗” (Ruǎn Rìmíng yě shì xuésheng ma?) → Nguyễn Nhật Minh cũng là học sinh à?', 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct2_6', 'lesson-2', NULL, 'comprehensive_test', 'listening', '我姓张，叫张风。现在我要去上课了。', NULL, 'Nghe đoạn ghi âm và chọn câu tiếng Trung khớp với nội dung vừa nghe:', '["是，我也是留学生。","老师们","我姓张，叫张风。现在我要去上课了。","下午好！"]'::jsonb, 2, 'Câu vừa đọc: “我姓张，叫张风。现在我要去上课了。” (Wǒ xìng Zhāng, jiào Zhāng Fēng. Xiànzài wǒ yào qù shàngkè le.) → Tôi họ Trương, tên là Trương Phong. Bây giờ tôi phải đi học rồi.', 6) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct2_7', 'lesson-2', NULL, 'comprehensive_test', 'listening', '马克明天早上见', NULL, 'Nghe đoạn ghi âm và chọn nghĩa tiếng Việt đúng:', '["Tôi họ Trương, tên là Trương Phong. Bây giờ tôi phải đi học rồi.","Mark, sáng mai gặp lại nhé!","Các em học sinh, chào buổi sáng!","Các thầy cô giáo"]'::jsonb, 1, 'Nội dung nghe được: “马克明天早上见” (Mǎkè, míngtiān zǎoshang jiàn!) → Mark, sáng mai gặp lại nhé!', 7) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
