INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct2_36', 'lesson-2', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ Hán tự “见” (nhìn thấy, gặp) có phiên âm Pinyin đúng là gì?', '["jiàn","Liú","hǎo","guìxìng"]'::jsonb, 0, '“见” đọc là “jiàn”, nghĩa là: nhìn thấy, gặp.', 36) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct2_37', 'lesson-2', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ “回” có nghĩa tiếng Việt là gì?', '["cô ấy, bà ấy, chị ấy,... (ngôi thứ ba số ít chỉ nữ)","ký túc xá","du học sinh","về, trở về, trở lại"]'::jsonb, 3, '“回” (huí) là Động từ, nghĩa là: về, trở về, trở lại.', 37) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct2_38', 'lesson-2', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ Hán tự “名字” (tên) có phiên âm Pinyin đúng là gì?', '["nín","míngzi","wǒmen","Fàn Yùlán"]'::jsonb, 1, '“名字” đọc là “míngzi”, nghĩa là: tên.', 38) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
