INSERT INTO lessons (id, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id) VALUES ('lesson-3', 'Bài 3: Kết bạn - Đơn nguyên 1: Trường học', 'Bài 3', 'Đơn nguyên 1: Trường học', 'Hỏi quốc tịch, làm quen bạn bè quốc tế, câu hỏi với 哪 và 谁, phó từ 都.', '2026-11-14'::date, 3, TRUE, NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, date_added = EXCLUDED.date_added, sort_order = EXCLUDED.sort_order, is_system = TRUE, updated_at = NOW();
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v3_1', 'lesson-3', '朋友', 'péngyou', 'bằng hữu', 'bạn bè', 'Danh từ', '月 (Nguyệt/Nhục) (Mặt trăng hoặc các bộ phận thân thể người)', '朋: 月 (Nguyệt) + 月 (Nguyệt: hai người kề vai) • 友: 𠂇 + 又 (Hựu: hai bàn tay nắm lấy nhau)', 'Ghép 朋 [bộ 月] + 友 [bộ 又] để nhớ từ 朋友 (péngyou): "bạn bè".', '这是我的好朋友，他叫马克。', 'Zhè shì wǒ de hǎo péngyou, tā jiào Mǎkè.', 'Đây là bạn thân của tôi, cậu ấy tên là Mark.', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v3_2', 'lesson-3', '人', 'rén', 'nhân', 'người, con người', 'Danh từ', '人/亻 (Nhân) (Con người, nhân loại, hành động)', '人 = Bộ 人 (Nhân - dáng người đứng bước, chữ độc thể).', 'Ghi nhớ chữ [人] (người, con người) qua hình tượng Con người, nhân loại.', '你是哪国人？', 'Nǐ shì nǎ guó rén?', 'Bạn là người nước nào?', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v3_3', 'lesson-3', '安妮', 'Ānnī', 'An Ni', 'Annie', 'Cụm từ / Tên riêng', '宀 (Miên) (Mái nhà, che chở, nơi ở)', '安: 宀 (Miên: mái nhà) + 女 (Nữ: người phụ nữ bình yên trong nhà) • 妮: 女 (Nữ) + 尼 (Ni)', 'Ghép 安 [bộ 宀] + 妮 [bộ 女] để nhớ từ 安妮 (Ānnī): "Annie".', '安妮同学！你好！这是谁啊？', 'Ānnī tóngxué nǐ hǎo! Zhè shì shéi a?', 'Chào bạn Annie! Đây là ai vậy?', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v3_4', 'lesson-3', '国家', 'guójiā', 'quốc gia', 'quốc gia, đất nước', 'Danh từ', '囗 (Vi) (Vây quanh, không gian kín, lãnh thổ)', '国: 囗 (Vi: biên giới) + 玉 (Ngọc: báu vật quốc gia) • 家: 宀 (Miên: mái nhà) + 豕 (Thỉ: lợn nuôi dưới mái nhà)', 'Ghép 国 [bộ 囗] + 家 [bộ 宀] để nhớ từ 国家 (guójiā): "quốc gia, đất nước".', '不是。我是美国人。你来自哪个国家？', 'Bú shì. Wǒ shì Měiguó rén. Nǐ láizì nǎ gè guójiā?', 'Không phải. Tôi là người Mỹ. Bạn đến từ nước nào?', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v3_5', 'lesson-3', '越南', 'Yuènán', 'Việt Nam', 'Việt Nam', 'Cụm từ / Tên riêng', '走 (Tẩu) (Chạy, đi lại, rời đi)', '越: 走 (Tẩu: đi qua) + 戉 (Việt) • 南: 十 (Thập) + 冂 (Quynh) + 羊 (biến thể)', 'Ghép 越 [bộ 走] + 南 [bộ 十] để nhớ từ 越南 (Yuènán): "Việt Nam".', '我来自越南。', 'Wǒ láizì Yuènán.', 'Tôi đến từ Việt Nam.', 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v3_6', 'lesson-3', '加拿大', 'Jiānádà', 'đại', 'Canada', 'Cụm từ / Tên riêng', '力 (Lực) (Sức mạnh, động lực)', '加: 力 (Lực: sức) + 口 (Khẩu: lời thêm vào) • 拿: 合 (Hợp) + 手 (Thủ: bàn tay cầm nắm) • 大: Bộ 大 (Đại - người dang rộng tay chân, chữ độc thể)', 'Ghép 加 [bộ 力] + 拿 [bộ 手] + 大 [bộ 大] để nhớ từ 加拿大 (Jiānádà): "Canada".', '马克同学你好！你也是加拿大人吗？', 'Mǎkè tóngxué nǐ hǎo! Nǐ yě shì Jiānádà rén ma?', 'Chào bạn Mark! Bạn cũng là người Canada à?', 6) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v3_7', 'lesson-3', '美国', 'Měiguó', 'Mỹ quốc', 'Mỹ', 'Cụm từ / Tên riêng', '羊 (Dương) (Con dê, cừu, tốt đẹp)', '美: 羊 (Dương: cừu béo) + 大 (Đại: to lớn là đẹp) • 国: 囗 (Vi: biên giới) + 玉 (Ngọc: báu vật quốc gia)', 'Ghép 美 [bộ 羊] + 国 [bộ 囗] để nhớ từ 美国 (Měiguó): "Mỹ".', '不是。我是美国人。你来自哪个国家？', 'Bú shì. Wǒ shì Měiguó rén. Nǐ láizì nǎ gè guójiā?', 'Không phải. Tôi là người Mỹ. Bạn đến từ nước nào?', 7) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v3_8', 'lesson-3', '生活', 'shēnghuó', 'sinh', 'cuộc sống, đời sống', 'Danh từ', '生 (Sinh) (Sinh sôi, sự sống, mới mẻ)', '生: Bộ 生 (Sinh - mầm cây nảy từ đất, chữ độc thể) • 活: 氵 (Thủy: nước) + 舌 (Thiệt: nước thấm đầu lưỡi là sống)', 'Ghép 生 [bộ 生] + 活 [bộ 氵] để nhớ từ 生活 (shēnghuó): "cuộc sống, đời sống".', '这是关于“生活”的常用句子。', 'Zhè shì guānyú ''shēnghuó'' de chángyòng jùzi.', 'Đây là câu ví dụ sử dụng từ ''生活'' (cuộc sống, đời sống).', 8) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v3_9', 'lesson-3', '认识', 'rènshi', 'nhận thức', 'quen biết, biết', 'Động từ', '言/讠 (Ngôn) (Lời nói, ngôn ngữ, giao tiếp)', '认: 讠 (Ngôn: lời nói) + 人 (Nhân: con người) • 识: 讠 (Ngôn: lời nói) + 只 (Chỉ: ghi nhớ)', 'Ghép 认 [bộ 讠] + 识 [bộ 讠] để nhớ từ 认识 (rènshi): "quen biết, biết".', '很高兴认识你！', 'Hěn gāoxìng rènshi nǐ!', 'Rất vui được làm quen với bạn!', 9) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v3_10', 'lesson-3', '来自', 'láizì', 'lai', 'đến từ (đâu)', 'Động từ', '木 (Mộc) (Cây cối, gỗ, thực vật)', '来: 一 + 米 (Mễ biến thể / cây lúa) • 自: Bộ 自 (Tự - hình cái mũi, chỉ bản thân)', 'Ghép 来 [bộ 木] + 自 [bộ 自] để nhớ từ 来自 (láizì): "đến từ (đâu)".', '不是。我是美国人。你来自哪个国家？', 'Bú shì. Wǒ shì Měiguó rén. Nǐ láizì nǎ gè guójiā?', 'Không phải. Tôi là người Mỹ. Bạn đến từ nước nào?', 10) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v3_11', 'lesson-3', '高兴', 'gāoxìng', 'cao hưng', 'vui mừng', 'Tính từ', '高 (Cao) (Cao lớn, tầng cao)', '高: Bộ 高 (Cao - tháp lầu nhiều tầng cao) • 兴: ⺍ + 一 + 八 (Bát: nhiều người nâng lên)', 'Ghép 高 [bộ 高] + 兴 [bộ 八] để nhớ từ 高兴 (gāoxìng): "vui mừng".', '很高兴认识你！', 'Hěn gāoxìng rènshi nǐ!', 'Rất vui được làm quen với bạn!', 11) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v3_12', 'lesson-3', '他', 'tā', 'từ Hán ngữ', 'anh ấy, cậu ấy... (ngôi thứ ba số ít chỉ nam)', 'Đại từ', '人/亻 (Nhân) (Con người, nhân loại, hành động)', '他 = 亻 (Nhân đứng: người) + 也 (Dã).', 'Chữ 他 (tā) mang nghĩa "anh ấy, cậu ấy... (ngôi thứ ba số ít chỉ nam)", bộ chính 人/亻 (Nhân); cấu tạo: 亻 (Nhân đứng: người) + 也 (Dã).', '他是我的老师。', 'Tā shì wǒ de lǎoshī.', 'Thầy ấy là thầy giáo của tớ.', 12) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v3_13', 'lesson-3', '谁', 'shuí / shéi', 'thùy', 'ai', 'Đại từ', '言/讠 (Ngôn) (Lời nói, ngôn ngữ, giao tiếp)', '谁 = 讠 (Ngôn: lời hỏi) + 隹 (Chuy).', 'Chữ 谁 (shuí / shéi) mang nghĩa "ai", bộ chính 言/讠 (Ngôn); cấu tạo: 讠 (Ngôn: lời hỏi) + 隹 (Chuy).', '谁啊？', 'Shéi a?', 'Ai đấy?', 13) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v3_14', 'lesson-3', '哪', 'nǎ', 'nả', 'nào, đâu', 'Đại từ', '口 (Khẩu) (Miệng, ăn uống, lời nói, âm thanh phát ra)', '哪 = 口 (Khẩu: hỏi) + 那 (Na).', 'Chữ 哪 (nǎ) mang nghĩa "nào, đâu", bộ chính 口 (Khẩu); cấu tạo: 口 (Khẩu: hỏi) + 那 (Na).', '你是哪国人？', 'Nǐ shì nǎ guó rén?', 'Bạn là người nước nào?', 14) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v3_15', 'lesson-3', '这', 'zhè', 'giá', 'đây, này', 'Đại từ', '辶 (Sước) (Bước đi, di chuyển, khoảng cách)', '这 = 文 (Văn) + 辶 (Sước: bước đi gần đây).', 'Chữ 这 (zhè) mang nghĩa "đây, này", bộ chính 辶 (Sước); cấu tạo: 文 (Văn) + 辶 (Sước: bước đi gần đây).', '这是我的书。', 'Zhè shì wǒ de shū.', 'Đây là sách của tôi.', 15) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v3_16', 'lesson-3', '那', 'nà', 'na', 'kia, đó', 'Đại từ', '阝 (Phụ/Ấp) (Gò đất hoặc vùng đất, thành ấp)', '那 = 𠃌 + 二 + 阝 (Ấp: vùng đất xa).', 'Chữ 那 (nà) mang nghĩa "kia, đó", bộ chính 阝 (Phụ/Ấp); cấu tạo: 𠃌 + 二 + 阝 (Ấp: vùng đất xa).', '那个人是王老师。', 'Nà gè rén shì Wáng lǎoshī.', 'Người đó là thầy Vương.', 16) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v3_17', 'lesson-3', '很', 'hěn', 'hấn', 'rất', 'Phó từ', '彳 (Xích) (Bước chân trái, con đường, hành động)', '很 = 彳 (Xích: bước chân) + 艮 (Cấn).', 'Chữ 很 (hěn) mang nghĩa "rất", bộ chính 彳 (Xích); cấu tạo: 彳 (Xích: bước chân) + 艮 (Cấn).', '她很漂亮。', 'Tā hěn piàoliang.', 'Cô ấy rất xinh đẹp.', 17) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v3_18', 'lesson-3', '个', 'gè', 'từ Hán ngữ', 'cái, chiếc,...', 'Lượng từ', '人/亻 (Nhân) (Con người, nhân loại, hành động)', '个 = 人 (Nhân) + 丨 (Cổn).', 'Chữ 个 (gè) mang nghĩa "cái, chiếc,...", bộ chính 人/亻 (Nhân); cấu tạo: 人 (Nhân) + 丨 (Cổn).', '她是哪个学校的学生？', 'Tā shì nǎ gè xuéxiào de xuésheng?', 'Cô ấy là học sinh trường nào?', 18) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v3_19', 'lesson-3', '的', 'de', 'từ Hán ngữ', 'của (trợ từ)', 'Trợ từ', '白 (Bạch) (Màu trắng, sáng tỏ)', '的 = 白 (Bạch) + 勺 (Thược).', 'Chữ 的 (de) mang nghĩa "của (trợ từ)", bộ chính 白 (Bạch); cấu tạo: 白 (Bạch) + 勺 (Thược).', '他是我的老师。', 'Tā shì wǒ de lǎoshī.', 'Thầy ấy là thầy giáo của tớ.', 19) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order) VALUES ('g3_1', 'lesson-3', '1. Trợ từ kết cấu 的', 'Chủ sở hữu  +的 + được sở hữu.', ' Đây là trợ từ kết cấu biểu thị mối quan hệ sở hữu, được sử dụng theo cấu trúc: Trong đó chủ sở hữu thường là danh từ hoặc đại từ còn được sở hữu thường là danh từ. 他是我的老师。 Tā shì wǒ de lǎoshī. Thầy ấy là thầy giáo của tớ. 这是我的书。 Zhè shì wǒ de shū. Đ', NULL, '[{"hanzi":"他是我的老师。","pinyin":"Tā shì wǒ de lǎoshī.","meaning":"Thầy ấy là thầy giáo của tớ."},{"hanzi":"这是我的书。","pinyin":"Zhè shì wǒ de shū.","meaning":"Đây là sách của tôi."}]'::jsonb, 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order) VALUES ('g3_2', 'lesson-3', '2. 疑问代词 “哪”、“谁” – Đại từ nghi vấn 哪, 谁', 'Cấu trúc câu ngữ pháp trọng tâm', ' a. Đại từ nghi vấn 哪 Phía sau có thể thêm danh từ hoặc số lượng từ, hỏi xác định phạm vi hoặc xác định sự vật (đâu) trong 1 loạt sự vật cùng loại (nào).', NULL, '[{"hanzi":"你是哪国人？","pinyin":"Nǐ shì nǎ guó rén?","meaning":"Bạn là người nước nào?"},{"hanzi":"她是哪个学校的学生？","pinyin":"Tā shì nǎ gè xuéxiào de xuésheng?","meaning":"Cô ấy là học sinh trường nào?"}]'::jsonb, 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order) VALUES ('g3_3', 'lesson-3', '1. 哪 + lượng từ / số lượng từ + Danh từ', 'Cấu trúc câu ngữ pháp trọng tâm', 'Quy tắc ngữ pháp quan trọng trong Kết bạn.', NULL, '[{"hanzi":"谁啊？","pinyin":"Shéi a?","meaning":"Ai đấy?"},{"hanzi":"他是谁？","pinyin":"Tā shì shéi?","meaning":"Anh ấy là ai?"}]'::jsonb, 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order) VALUES ('g3_4', 'lesson-3', '2. 哪 + Danh từ lượng từ', 'Cấu trúc câu ngữ pháp trọng tâm', ' 你是哪国人？ Nǐ shì nǎ guó rén? Bạn là người nước nào? 她是哪个学校的学生？ Tā shì nǎ gè xuéxiào de xuésheng? Cô ấy là học sinh trường nào? 你哪天去上课? ( 天 là một danh lượng từ) Nǐ nǎ tiān qù shàngkè? Ngày nào mày đi học? b. Đại từ nghi vấn 谁 - Đây là đại từ nghi vấn c', NULL, '[{"hanzi":"这本书是我的书。","pinyin":"Zhè běn shū shì wǒ de shū.","meaning":"Quyển sách này là sách của tớ."},{"hanzi":"那个人是王老师。","pinyin":"Nà gè rén shì Wáng lǎoshī.","meaning":"Người đó là thầy Vương."}]'::jsonb, 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order;
INSERT INTO texts (id, lesson_id, title, description, sort_order) VALUES ('txt_3_1', 'lesson-3', 'Bài khoá #1: Hội thoại giáo trình — Kết bạn', 'Hội thoại chuẩn giáo trình Bài 3. Từ vựng chưa học được chú thích phiên âm & nghĩa trong ngoặc.', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_3_1_1', 'txt_3_1', '安妮', '日明同学！你好！', '日明同学！你好！', 'Rìmíng tóngxué! Nǐ hǎo!', 'Chào bạn Nhật Minh!', 1) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_3_1_2', 'txt_3_1', '阮日明', '安妮同学！你好！这是谁啊？', '安妮同学！你好！这是谁啊 (a: dùng cuối câu)？', 'Ānnī tóngxué nǐ hǎo! Zhè shì shéi a?', 'Chào bạn Annie! Đây là ai vậy?', 2) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_3_1_3', 'txt_3_1', '安妮', '这是我的好朋友，他叫马克。', '这是我的好朋友，他叫马克。', 'Zhè shì wǒ de hǎo péngyou, tā jiào Mǎkè.', 'Đây là bạn thân của tôi, cậu ấy tên là Mark.', 3) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_3_1_4', 'txt_3_1', '阮日明', '马克同学你好！你也是加拿大人吗？', '马克同学你好！你也是加拿大人吗？', 'Mǎkè tóngxué nǐ hǎo! Nǐ yě shì Jiānádà rén ma?', 'Chào bạn Mark! Bạn cũng là người Canada à?', 4) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_3_1_5', 'txt_3_1', '马克', '不是。我是美国人。你来自哪个国家？', '不 (bù: không)是。我是美国人。你来自哪个国家？', 'Bú shì. Wǒ shì Měiguó rén. Nǐ láizì nǎ gè guójiā?', 'Không phải. Tôi là người Mỹ. Bạn đến từ nước nào?', 5) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_3_1_6', 'txt_3_1', '阮日明', '我来自越南。', '我来自越南。', 'Wǒ láizì Yuènán.', 'Tôi đến từ Việt Nam.', 6) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_3_1_7', 'txt_3_1', '马克', '很高兴认识你！', '很高兴认识你！', 'Hěn gāoxìng rènshi nǐ!', 'Rất vui được làm quen với bạn!', 7) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_3_1_8', 'txt_3_1', '阮日明', '我也很高兴认识你。', '我也很高兴认识你。', 'Wǒ yě hěn gāoxìng rènshi nǐ.', 'Tôi cũng rất vui được làm quen với bạn.', 8) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_3_1_1', 'lesson-3', 'txt_3_1', 'listening', 'listening', '日明同学！你好！', NULL, 'Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Không phải ngoài trời đang mưa à? Cậu dùng ô của tớ đi! (Khẳng định","Tôi đang đọc sách.","Chào bạn Nhật Minh!","Bây giờ cậu cảm thấy thế nào?"]'::jsonb, 2, 'Nội dung nghe được: 日明同学！你好！ (Rìmíng tóngxué! Nǐ hǎo!) → Chào bạn Nhật Minh!', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_3_1_2', 'lesson-3', 'txt_3_1', 'listening', 'listening', '安妮同学！你好！这是谁啊？', NULL, 'Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["你认识阮日明吗？","张风不 (bù: không)是美国人，他是中国 (Zhōngguó: Trung Quốc)人。","安妮同学！你好！这是谁啊 (a: dùng cuối câu)？","日明同学！你好！"]'::jsonb, 2, 'Câu vừa đọc: 安妮同学！你好！这是谁啊？ (Ānnī tóngxué nǐ hǎo! Zhè shì shéi a?) → Chào bạn Annie! Đây là ai vậy?', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_3_1_3', 'lesson-3', 'txt_3_1', 'listening', 'listening', '这是我的好朋友，他叫马克。', NULL, 'Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Anh ta thật sự nói như thế.","Đây là bạn thân của tôi, cậu ấy tên là Mark.","Tàu hỏa sắp chạy ngay bây giờ.","Bệnh của mẹ khỏi lâu rồi, con đừng lo lắng."]'::jsonb, 1, 'Nội dung nghe được: 这是我的好朋友，他叫马克。 (Zhè shì wǒ de hǎo péngyou, tā jiào Mǎkè.) → Đây là bạn thân của tôi, cậu ấy tên là Mark.', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_3_1_4', 'lesson-3', 'txt_3_1', 'listening', 'listening', '马克同学你好！你也是加拿大人吗？', NULL, 'Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["张风不 (bù: không)是美国人，他是中国 (Zhōngguó: Trung Quốc)人。","这是我的好朋友，他叫马克。","马克同学你好！你也是加拿大人吗？","认识刘老师我很高兴。"]'::jsonb, 2, 'Câu vừa đọc: 马克同学你好！你也是加拿大人吗？ (Mǎkè tóngxué nǐ hǎo! Nǐ yě shì Jiānádà rén ma?) → Chào bạn Mark! Bạn cũng là người Canada à?', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO texts (id, lesson_id, title, description, sort_order) VALUES ('txt_3_2', 'lesson-3', 'Bài nghe tổng hợp: Ôn tập lũy tiến (Bài 1 – Bài 3)', 'Kết hợp từ vựng & mẫu câu đã học từ Bài 1 đến Bài 2 cùng trọng tâm Bài 3 để củng cố phản xạ nghe.', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
