INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss3_exp_5', 'lesson-3', '不是我是美国人你来自哪个国家', 'Không phải. Tôi là người Mỹ. Bạn đến từ nước nào?', 'Bú shì. Wǒ shì Měiguó rén. Nǐ láizì nǎ gè guójiā?', '["不是","我","是","美国","人","你","来自","哪","个","国家"]'::jsonb, NULL, 11) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
