INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr3_zh_exp_7', 'lesson-3', 'zh_to_vi', '不是，我来自美国。安妮是加拿大人。', '不是，我来自美国。安妮是加拿大人。', 'Bú shì, wǒ láizì Měiguó. Ānnī shì Jiānádà rén.', NULL, 'Không phải, tôi đến từ Mỹ. Annie là người Canada.', NULL, '["không","phải","tôi","đến","từ","mỹ","annie","là","người","canada"]'::jsonb, 'Pinyin: Bú shì, wǒ láizì Měiguó. Ānnī shì Jiānádà rén.', '不是，我来自美国。安妮是加拿大人。 (Bú shì, wǒ láizì Měiguó. Ānnī shì Jiānádà rén.) nghĩa là: Không phải, tôi đến từ Mỹ. Annie là người Canada.', 25) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
