INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq3_13', 'lesson-3', NULL, 'expanded_quiz', 'radical', NULL, NULL, 'Chữ Hán “朋友” chứa bộ thủ nào sau đây?', '["八 (Bát) (Số tám, phân chia, mở rộng)","广 (Nghiễm) (Mái nhà rộng, nơi công cộng)","瓜 (Qua) (Quả dưa, cây leo)","月 (Nguyệt/Nhục) (Mặt trăng hoặc các bộ phận thân thể người)"]'::jsonb, 3, 'Chữ “朋友” có bộ chính 月 (Nguyệt/Nhục) (Mặt trăng hoặc các bộ phận thân thể người). Chiết tự: 朋: 月 (Nguyệt) + 月 (Nguyệt: hai người kề vai) • 友: 𠂇 + 又 (Hựu: hai bàn tay nắm lấy nhau)', 13) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq3_14', 'lesson-3', NULL, 'expanded_quiz', 'radical', NULL, NULL, 'Chữ Hán “人” chứa bộ thủ nào sau đây?', '["士 (Sĩ) (Người học thức, kẻ sĩ)","人/亻 (Nhân) (Con người, nhân loại, hành động)","曰 (Viết) (Nói rằng, lời nói)","立 (Lập) (Đứng vững, thiết lập)"]'::jsonb, 1, 'Chữ “人” có bộ chính 人/亻 (Nhân) (Con người, nhân loại, hành động). Chiết tự: 人 = Bộ 人 (Nhân - dáng người đứng bước, chữ độc thể).', 14) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq3_15', 'lesson-3', NULL, 'expanded_quiz', 'radical', NULL, NULL, 'Chữ Hán “安妮” chứa bộ thủ nào sau đây?', '["曰 (Viết) (Nói rằng, lời nói)","立 (Lập) (Đứng vững, thiết lập)","宀 (Miên) (Mái nhà, che chở, nơi ở)","长 (Trường) (Dài lâu, phát triển)"]'::jsonb, 2, 'Chữ “安妮” có bộ chính 宀 (Miên) (Mái nhà, che chở, nơi ở). Chiết tự: 安: 宀 (Miên: mái nhà) + 女 (Nữ: người phụ nữ bình yên trong nhà) • 妮: 女 (Nữ) + 尼 (Ni)', 15) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq3_16', 'lesson-3', NULL, 'expanded_quiz', 'radical', NULL, NULL, 'Chữ Hán “国家” chứa bộ thủ nào sau đây?', '["火/灬 (Hỏa) (Lửa, nhiệt độ, nấu nướng, nóng bức)","自 (Tự) (Cái mũi, bản thân, tự mình)","囗 (Vi) (Vây quanh, không gian kín, lãnh thổ)","飞 (Phi) (Bay lượn)"]'::jsonb, 2, 'Chữ “国家” có bộ chính 囗 (Vi) (Vây quanh, không gian kín, lãnh thổ). Chiết tự: 国: 囗 (Vi: biên giới) + 玉 (Ngọc: báu vật quốc gia) • 家: 宀 (Miên: mái nhà) + 豕 (Thỉ: lợn nuôi dưới mái nhà)', 16) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq3_17', 'lesson-3', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, '[Ôn tập Bài 1] Từ đã học “刘” (Liú) có nghĩa là gì?', '["ngài, ông, bà... (cách gọi tôn trọng và lịch sự dành cho những người có địa vị cao...)","Lưu (họ người)","Giáo viên, thầy cô giáo","ký túc xá"]'::jsonb, 1, 'Ôn tập Bài 1: “刘” (Liú) nghĩa là: Lưu (họ người).', 17) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq3_18', 'lesson-3', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, '[Ôn tập Bài 2] Từ đã học “回” (huí) có nghĩa là gì?', '["rồi","quốc gia, đất nước","ai","về, trở về, trở lại"]'::jsonb, 3, 'Ôn tập Bài 2: “回” (huí) nghĩa là: về, trở về, trở lại.', 18) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq3_19', 'lesson-3', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, '[Ôn tập Bài 2] Từ đã học “再见” (zàijiàn) có nghĩa là gì?', '["ngài, ông, bà... (cách gọi tôn trọng và lịch sự dành cho những người có địa vị cao...)","tạm biệt, hẹn gặp lại","họ, quý tính, quý danh (cách nói lịch sử)","hiện tại, bây giờ"]'::jsonb, 1, 'Ôn tập Bài 2: “再见” (zàijiàn) nghĩa là: tạm biệt, hẹn gặp lại.', 19) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq3_20', 'lesson-3', NULL, 'expanded_quiz', 'reading', NULL, NULL, '[Mở rộng] Câu “安妮是我的好朋友。” có nghĩa tiếng Việt là gì?', '["Annie là bạn thân của tôi.","Câu phía dưới","đất nước (quốc gia) của chúng tôi","Phía dưới bàn"]'::jsonb, 0, '安妮是我的好朋友。 (Ānnī shì wǒ de hǎo péngyou.) → Annie là bạn thân của tôi.', 20) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq3_21', 'lesson-3', NULL, 'expanded_quiz', 'reading', NULL, NULL, '[Đọc hiểu mở rộng] Đọc đoạn hội thoại:
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq3_22', 'lesson-3', NULL, 'expanded_quiz', 'reading', NULL, NULL, 'Câu “他是我的老师。” có nghĩa tiếng Việt là gì?', '["bút bi của cô ấy","Thầy ấy là thầy giáo của tớ.","Trước mặt bạn là thư viện thành phố.","quyển sách thú vị, có ý nghĩa"]'::jsonb, 1, '他是我的老师。 (Tā shì wǒ de lǎoshī.) → Thầy ấy là thầy giáo của tớ.', 22) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct3_1', 'lesson-3', NULL, 'comprehensive_test', 'listening', '中午好！', NULL, 'Nghe đoạn ghi âm và chọn nghĩa tiếng Việt đúng:', '["Bạn tên là gì?","Cô ấy là Bạch Như Tuyết.","Chào buổi trưa!","Tôi họ Lâm."]'::jsonb, 2, 'Nội dung nghe được: “中午好！” (Zhōngwǔ hǎo) → Chào buổi trưa!', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct3_2', 'lesson-3', NULL, 'comprehensive_test', 'listening', '那个人是王老师。', NULL, 'Nghe đoạn ghi âm và chọn câu tiếng Trung khớp với nội dung vừa nghe:', '["老师，早上好！您是刘老师吗？","那个人是王老师。","我姓张，叫张风。现在我要去上课了。","你好！你也是学生吗？"]'::jsonb, 1, 'Câu vừa đọc: “那个人是王老师。” (Nà gè rén shì Wáng lǎoshī.) → Người đó là thầy Vương.', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct3_3', 'lesson-3', NULL, 'comprehensive_test', 'listening', '你是哪国人？', NULL, 'Nghe đoạn ghi âm và chọn nghĩa tiếng Việt đúng:', '["Không phải. Tôi là người Mỹ. Bạn đến từ nước nào?","Bạn là người nước nào?","Tôi là sinh viên.","Sáng mai gặp lại nhé, tạm biệt!"]'::jsonb, 1, 'Nội dung nghe được: “你是哪国人？” (Nǐ shì nǎ guó rén?) → Bạn là người nước nào?', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct3_4', 'lesson-3', NULL, 'comprehensive_test', 'listening', '我来自越南，现在生活在这里。', NULL, 'Nghe đoạn ghi âm và chọn câu tiếng Trung khớp với nội dung vừa nghe:', '["我来自越南，现在生活在这里。","那个人是王老师。","明天见！","很高兴认识你！"]'::jsonb, 0, 'Câu vừa đọc: “我来自越南，现在生活在这里。” (Wǒ láizì Yuènán, xiànzài shēnghuó zài zhèlǐ.) → Tôi đến từ Việt Nam, hiện đang sống ở đây.', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct3_5', 'lesson-3', NULL, 'comprehensive_test', 'listening', '这是我的书。', NULL, 'Nghe đoạn ghi âm và chọn nghĩa tiếng Việt đúng:', '["Đây là sách của tôi.","Không phải. Tôi là người Mỹ. Bạn đến từ nước nào?","Tôi đến từ Việt Nam, hiện đang sống ở đây.","Tám giờ sáng ngày mai tớ đi học."]'::jsonb, 0, 'Nội dung nghe được: “这是我的书。” (Zhè shì wǒ de shū.) → Đây là sách của tôi.', 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct3_6', 'lesson-3', NULL, 'comprehensive_test', 'listening', '安妮是我的好朋友', NULL, 'Nghe đoạn ghi âm và chọn câu tiếng Trung khớp với nội dung vừa nghe:', '["安妮是我的好朋友","那个人是王老师。","她是哪个学校的学生？","欢迎！范玉兰也是留学生吗？"]'::jsonb, 0, 'Câu vừa đọc: “安妮是我的好朋友” (Ānnī shì wǒ de hǎo péngyou.) → Annie là bạn thân của tôi.', 6) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct3_7', 'lesson-3', NULL, 'comprehensive_test', 'listening', '明天见！', NULL, 'Nghe đoạn ghi âm và chọn nghĩa tiếng Việt đúng:', '["Chào bạn Annie! Đây là ai vậy?","Hẹn gặp lại vào ngày mai! (Hoặc “Mai gặp nhé!”)","Tám giờ sáng ngày mai tớ đi học.","Cậu là Nhật Minh phải không?"]'::jsonb, 1, 'Nội dung nghe được: “明天见！” (Míngtiān jiàn!) → Hẹn gặp lại vào ngày mai! (Hoặc “Mai gặp nhé!”)', 7) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
