INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct3_20', 'lesson-3', NULL, 'comprehensive_test', 'listening', '日明，这位是我的朋友，他叫马克。 很高兴认识你！你来自加拿大吗？ 不是，我来自美国。安妮是加拿大人。 我来自越南，现在生活在这里。', NULL, 'Theo đoạn hội thoại, quốc tịch của Mark và Annie lần lượt là gì?', '["Cả hai đều là người Canada","Mark là người Mỹ, Annie là người Canada","Mark người Canada, Annie người Trung Quốc","Mark người Việt Nam, Annie người Mỹ"]'::jsonb, 1, 'Mark nói ''我来自美国'' (Mỹ) và ''安妮是加拿大人'' (Canada).', 20) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
