INSERT INTO lessons (id, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id) VALUES ('lesson-4', 'Bài 4: Địa điểm - Đơn nguyên 1: Trường học', 'Bài 4', 'Đơn nguyên 1: Trường học', 'Các địa điểm trong trường (căn tin, thư viện, ký túc xá), động từ 在 và 去, đại từ chỉ nơi chốn 这儿, 那儿, 哪儿.', '2026-11-14'::date, 4, TRUE, NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, date_added = EXCLUDED.date_added, sort_order = EXCLUDED.sort_order, is_system = TRUE, updated_at = NOW();
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v4_1', 'lesson-4', '食堂', 'shítáng', 'thực đường', 'nhà ăn', 'Danh từ', '食/饣 (Thực) (Đồ ăn, ẩm thực)', '食: Bộ 食 (Thực - mâm cơm, đồ ăn) • 堂: 尚 (Thượng: phần trên) + 土 (Thổ: nền đất, sảnh lớn)', 'Ghép 食 [bộ 食] + 堂 [bộ 土] để nhớ từ 食堂 (shítáng): "nhà ăn".', '食堂在教学楼旁边。', 'Shítáng zài jiàoxué lóu pángbiān.', 'Nhà ăn ở cạnh giảng đường.', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v4_2', 'lesson-4', '图书馆', 'túshūguǎn', 'đồ thư quán', 'thư viện', 'Danh từ', '囗 (Vi) (Vây quanh, không gian kín, lãnh thổ)', '图: 囗 (Vi: khung tranh) + 冬 (Đông: bản vẽ bên trong) • 书: Nét gấp 乛 + 乛 + 丨 + 丶 (cuốn sách, bút viết) • 馆: 饣 (Thực) + 官 (Quan: nơi công cộng)', 'Ghép 图 [bộ 囗] + 书 [bộ 乙] + 馆 [bộ 饣] để nhớ từ 图书馆 (túshūguǎn): "thư viện".', '你的前面是城市图书馆。', 'Nǐ de qiánmian shì chéngshì túshūguǎn.', 'Trước mặt bạn là thư viện thành phố.', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v4_3', 'lesson-4', '楼', 'lóu', 'lầu', 'tòa nhà, lầu', 'Danh từ', '木 (Mộc) (Cây cối, gỗ, thực vật)', '楼 = 木 (Mộc: cột gỗ) + 娄 (Lâu).', 'Chữ 楼 (lóu) mang nghĩa "tòa nhà, lầu", bộ chính 木 (Mộc); cấu tạo: 木 (Mộc: cột gỗ) + 娄 (Lâu).', '我的左边不是教学楼。', 'Wǒ de zuǒbian búshì jiàoxué lóu.', 'Bên trái tôi không phải là tòa giảng đường.', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v4_4', 'lesson-4', '教学楼', 'jiàoxuélóu', 'giáo học lầu', 'tòa giảng đường', 'Danh từ', '攴/攵 (Phộc) (Đánh khẽ, hành động, dạy dỗ)', '教: 孝 (Hiếu) + 攵 (Phộc: thầy cầm roi dạy bảo) • 学: ⺍ + 冖 (Mịch: mái che) + 子 (Tử: trẻ nhỏ) • 楼: 木 (Mộc: cột gỗ) + 娄 (Lâu)', 'Ghép 教 [bộ 攵] + 学 [bộ 子] + 楼 [bộ 木] để nhớ từ 教学楼 (jiàoxuélóu): "tòa giảng đường".', '我的左边不是教学楼。', 'Wǒ de zuǒbian búshì jiàoxué lóu.', 'Bên trái tôi không phải là tòa giảng đường.', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v4_5', 'lesson-4', '饭', 'fàn', 'từ Hán ngữ', 'cơm', 'Danh từ', '食/饣 (Thực) (Đồ ăn, ẩm thực)', '饭 = 饣 (Thực: thức ăn) + 反 (Phản).', 'Chữ 饭 (fàn) mang nghĩa "cơm", bộ chính 食/饣 (Thực); cấu tạo: 饣 (Thực: thức ăn) + 反 (Phản).', '好的，我去食堂吃饭。啊，你知道图书馆在哪里吗？', 'Hǎo de, wǒ qù shítáng chīfàn. A, nǐ zhīdào túshūguǎn zài nǎli ma?', 'Vâng, tôi đến nhà ăn ăn cơm. À, bạn có biết thư viện ở đâu không?', 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v4_6', 'lesson-4', '书', 'shū', 'thư', 'sách', 'Danh từ', '乙 (Ất) (Uốn cong, số thứ tự, chồi non)', '书 = Nét gấp 乛 + 乛 + 丨 + 丶 (cuốn sách, bút viết).', 'Chữ 书 (shū) mang nghĩa "sách", bộ chính 乙 (Ất); cấu tạo: Nét gấp 乛 + 乛 + 丨 + 丶 (cuốn sách, bút viết).', '你的前面是城市图书馆。', 'Nǐ de qiánmian shì chéngshì túshūguǎn.', 'Trước mặt bạn là thư viện thành phố.', 6) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v4_7', 'lesson-4', '前面', 'qiánmian', 'tiền', 'phía trước', 'Danh từ', '刀/刂 (Đao) (Con dao, cắt xẻ, phân chia)', '前: 丷 + 一 + 月 (Nguyệt/Thuyền) + 刂 (Đao) • 面: Bộ 面 (Diện - khuôn mặt, bề mặt)', 'Ghép 前 [bộ 刂] + 面 [bộ 面] để nhớ từ 前面 (qiánmian): "phía trước".', '你的前面是城市图书馆。', 'Nǐ de qiánmian shì chéngshì túshūguǎn.', 'Trước mặt bạn là thư viện thành phố.', 7) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v4_8', 'lesson-4', '左边', 'zuǒbian', 'biên', 'bên trái', 'Danh từ', '工 (Công) (Công việc, kỹ thuật, thợ thủ công)', '左: 𠂇 (bàn tay trái) + 工 (Công: thước thợ) • 边: 力 (Lực) + 辶 (Sước: đi ven mép)', 'Ghép 左 [bộ 工] + 边 [bộ 辶] để nhớ từ 左边 (zuǒbian): "bên trái".', '我的左边不是教学楼。', 'Wǒ de zuǒbian búshì jiàoxué lóu.', 'Bên trái tôi không phải là tòa giảng đường.', 8) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v4_9', 'lesson-4', '右边', 'yòubian', 'biên', 'bên phải', 'Danh từ', '口 (Khẩu) (Miệng, ăn uống, lời nói, âm thanh phát ra)', '右: 𠂇 (bàn tay phải) + 口 (Khẩu: miệng) • 边: 力 (Lực) + 辶 (Sước: đi ven mép)', 'Ghép 右 [bộ 口] + 边 [bộ 辶] để nhớ từ 右边 (yòubian): "bên phải".', '医院在我们学校的右边。', 'Yīyuàn zài wǒmen xuéxiào de yòubian.', 'Bệnh viện ở bên phải trường học của chúng ta.', 9) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v4_10', 'lesson-4', '地方', 'dìfāng', 'địa', 'nơi, vùng, nơi ấy, chốn ấy', 'Danh từ', '土 (Thổ) (Đất đai, vị trí, công trình)', '地: 土 (Thổ: đất) + 也 (Dã) • 方: Bộ 方 (Phương - hình vuông, phương hướng)', 'Ghép 地 [bộ 土] + 方 [bộ 方] để nhớ từ 地方 (dìfāng): "nơi, vùng, nơi ấy, chốn ấy".', '这是关于“地方”的常用句子。', 'Zhè shì guānyú ''dìfāng'' de chángyòng jùzi.', 'Đây là câu ví dụ sử dụng từ ''地方'' (nơi, vùng, nơi ấy, chốn ấy).', 10) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v4_11', 'lesson-4', '附近', 'fùjìn', 'từ Hán ngữ', 'lân cận, gần đây', 'Danh từ', '阝 (Phụ/Ấp) (Gò đất hoặc vùng đất, thành ấp)', '附: 阝 (Phụ: gò đất) + 付 (Phó: kề bên) • 近: 斤 (Cân) + 辶 (Sước: đi lại gần)', 'Ghép 附 [bộ 阝] + 近 [bộ 辶] để nhớ từ 附近 (fùjìn): "lân cận, gần đây".', '这是关于“附近”的常用句子。', 'Zhè shì guānyú ''fùjìn'' de chángyòng jùzi.', 'Đây là câu ví dụ sử dụng từ ''附近'' (lân cận, gần đây).', 11) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v4_12', 'lesson-4', '请', 'qǐng', 'thỉnh', 'mời, xin', 'Động từ', '言/讠 (Ngôn) (Lời nói, ngôn ngữ, giao tiếp)', '请 = 讠 (Ngôn: lời nói lịch sự) + 青 (Thanh).', 'Chữ 请 (qǐng) mang nghĩa "mời, xin", bộ chính 言/讠 (Ngôn); cấu tạo: 讠 (Ngôn: lời nói lịch sự) + 青 (Thanh).', '你好。请问，学校的食堂在哪儿？', 'Nǐ hǎo. Qǐngwèn, xuéxiào de shítáng zài nǎr?', 'Xin chào. Xin hỏi nhà ăn của trường ở đâu vậy?', 12) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v4_13', 'lesson-4', '问', 'wèn', 'vấn', 'hỏi', 'Động từ', '门 (Môn) (Cánh cửa, lối ra vào)', '问 = 门 (Môn: cánh cửa) + 口 (Khẩu: mở miệng hỏi ngoài cửa).', 'Chữ 问 (wèn) mang nghĩa "hỏi", bộ chính 门 (Môn); cấu tạo: 门 (Môn: cánh cửa) + 口 (Khẩu: mở miệng hỏi ngoài cửa).', '你好。请问，学校的食堂在哪儿？', 'Nǐ hǎo. Qǐngwèn, xuéxiào de shítáng zài nǎr?', 'Xin chào. Xin hỏi nhà ăn của trường ở đâu vậy?', 13) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v4_14', 'lesson-4', '知道', 'zhīdào', 'đạo', 'biết', 'Động từ', '矢 (Thỉ) (Mũi tên, thẳng thắn, hiểu biết)', '知: 矢 (Thỉ: mũi tên, nhanh chóng) + 口 (Khẩu: nói ra điều biết) • 道: 首 (Thủ: cái đầu dẫn hướng) + 辶 (Sước: bước đi trên đường)', 'Ghép 知 [bộ 矢] + 道 [bộ 辶] để nhớ từ 知道 (zhīdào): "biết".', '好的，我去食堂吃饭。啊，你知道图书馆在哪里吗？', 'Hǎo de, wǒ qù shítáng chīfàn. A, nǐ zhīdào túshūguǎn zài nǎli ma?', 'Vâng, tôi đến nhà ăn ăn cơm. À, bạn có biết thư viện ở đâu không?', 14) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v4_15', 'lesson-4', '在', 'zài', 'tại', 'ở', 'Động từ / Giới từ', '土 (Thổ) (Đất đai, vị trí, công trình)', '在 = 𠂇 + 土 (Thổ: tồn tại trên mặt đất).', 'Chữ 在 (zài) mang nghĩa "ở", bộ chính 土 (Thổ); cấu tạo: 𠂇 + 土 (Thổ: tồn tại trên mặt đất).', '医院在我们学校的右边。', 'Yīyuàn zài wǒmen xuéxiào de yòubian.', 'Bệnh viện ở bên phải trường học của chúng ta.', 15) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v4_16', 'lesson-4', '谢谢', 'xièxie', 'từ Hán ngữ', 'cảm ơn', 'Động từ', '言/讠 (Ngôn) (Lời nói, ngôn ngữ, giao tiếp)', '谢: 讠 (Ngôn: lời nói) + 射 (Xạ: cúi mình cảm tạ) • 谢: 讠 (Ngôn: lời nói) + 射 (Xạ: cúi mình cảm tạ)', 'Ghép 谢 [bộ 讠] + 谢 [bộ 讠] để nhớ từ 谢谢 (xièxie): "cảm ơn".', '是啊，谢谢你！', 'Shì a, xièxie nǐ!', 'Đúng vậy, cảm ơn bạn!', 16) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v4_17', 'lesson-4', '看', 'kàn', 'khán', 'đọc, xem, nhìn, thăm,...', 'Động từ', '目 (Mục) (Con mắt, nhìn ngắm, thị giác)', '看 = 手 (Thủ biến thể: tay che trán) + 目 (Mục: mắt nhìn).', 'Chữ 看 (kàn) mang nghĩa "đọc, xem, nhìn, thăm,...", bộ chính 目 (Mục); cấu tạo: 手 (Thủ biến thể: tay che trán) + 目 (Mục: mắt nhìn).', '教学楼的右边是图书馆。你去图书馆看书吗？', 'Jiàoxué lóu de yòubian shì túshūguǎn. Nǐ qù túshūguǎn kànshū ma?', 'Bên phải tòa nhà giảng đường là thư viện. Bạn đi thư viện đọc sách à?', 17) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v4_18', 'lesson-4', '去', 'qù', 'khứ', 'đi', 'Động từ', '厶 (Tư) (Riêng tư, cuộn tròn)', '去 = 土 (Thổ: đất) + 厶 (Tư).', 'Chữ 去 (qù) mang nghĩa "đi", bộ chính 厶 (Tư); cấu tạo: 土 (Thổ: đất) + 厶 (Tư).', '好的，我去食堂吃饭。啊，你知道图书馆在哪里吗？', 'Hǎo de, wǒ qù shítáng chīfàn. A, nǐ zhīdào túshūguǎn zài nǎli ma?', 'Vâng, tôi đến nhà ăn ăn cơm. À, bạn có biết thư viện ở đâu không?', 18) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v4_19', 'lesson-4', '吃', 'chī', 'ngật', 'ăn', 'Động từ', '口 (Khẩu) (Miệng, ăn uống, lời nói, âm thanh phát ra)', '吃 = 口 (Khẩu: miệng) + 乞 (Khất).', 'Chữ 吃 (chī) mang nghĩa "ăn", bộ chính 口 (Khẩu); cấu tạo: 口 (Khẩu: miệng) + 乞 (Khất).', '好的，我去食堂吃饭。啊，你知道图书馆在哪里吗？', 'Hǎo de, wǒ qù shítáng chīfàn. A, nǐ zhīdào túshūguǎn zài nǎli ma?', 'Vâng, tôi đến nhà ăn ăn cơm. À, bạn có biết thư viện ở đâu không?', 19) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v4_20', 'lesson-4', '哪儿', 'nǎr', 'nả nhi', 'ở đâu', 'Đại từ', '口 (Khẩu) (Miệng, ăn uống, lời nói, âm thanh phát ra)', '哪: 口 (Khẩu: hỏi) + 那 (Na) • 儿: Bộ 儿 (Nhi - nét cong, chữ độc thể)', 'Ghép 哪 [bộ 口] + 儿 [bộ 儿] để nhớ từ 哪儿 (nǎr): "ở đâu".', '你好。请问，学校的食堂在哪儿？', 'Nǐ hǎo. Qǐngwèn, xuéxiào de shítáng zài nǎr?', 'Xin chào. Xin hỏi nhà ăn của trường ở đâu vậy?', 20) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v4_21', 'lesson-4', '哪里', 'nǎlǐ', 'nả', 'ở đâu', 'Đại từ', '口 (Khẩu) (Miệng, ăn uống, lời nói, âm thanh phát ra)', '哪: 口 (Khẩu: hỏi) + 那 (Na) • 里: 日 (Nhật) + 土 (Thổ: ruộng đất làng xóm)', 'Ghép 哪 [bộ 口] + 里 [bộ 里] để nhớ từ 哪里 (nǎlǐ): "ở đâu".', '好的，我去食堂吃饭。啊，你知道图书馆在哪里吗？', 'Hǎo de, wǒ qù shítáng chīfàn. A, nǐ zhīdào túshūguǎn zài nǎli ma?', 'Vâng, tôi đến nhà ăn ăn cơm. À, bạn có biết thư viện ở đâu không?', 21) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v4_22', 'lesson-4', '啊', 'a', 'từ Hán ngữ', 'dùng cuối câu, biểu thị ngữ khí cảm thán.', 'Thán từ', '口 (Khẩu) (Miệng, ăn uống, lời nói, âm thanh phát ra)', '啊 = 口 (Khẩu: tiếng thốt ra) + 阿 (A).', 'Chữ 啊 (a) mang nghĩa "dùng cuối câu, biểu thị ngữ khí cảm thán.", bộ chính 口 (Khẩu); cấu tạo: 口 (Khẩu: tiếng thốt ra) + 阿 (A).', '好的，我去食堂吃饭。啊，你知道图书馆在哪里吗？', 'Hǎo de, wǒ qù shítáng chīfàn. A, nǐ zhīdào túshūguǎn zài nǎli ma?', 'Vâng, tôi đến nhà ăn ăn cơm. À, bạn có biết thư viện ở đâu không?', 22) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v4_23', 'lesson-4', '座', 'zuò', 'từ Hán ngữ', 'ngôi (trường), tòa ( nhà)', 'Lượng từ', '广 (Nghiễm) (Mái nhà rộng, nơi công cộng)', '座 = 广 (Nghiễm: mái nhà) + 坐 (Tọa: ngồi).', 'Chữ 座 (zuò) mang nghĩa "ngôi (trường), tòa ( nhà)", bộ chính 广 (Nghiễm); cấu tạo: 广 (Nghiễm: mái nhà) + 坐 (Tọa: ngồi).', '后面的那座楼是宿舍，食堂在宿舍的左边。', 'Hòumian de nà zuò lóu shì sùshè, shítáng zài sùshè de zuǒbian.', 'Tòa nhà phía sau kia là ký túc xá, nhà ăn nằm ở bên trái ký túc xá.', 23) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v4_24', 'lesson-4', '不客气', 'bú kèqì', 'khách khí', 'đừng khách sáo', 'Cụm từ / Tên riêng', '一 (Nhất) (Số một, nền tảng, nét ngang cơ bản)', '不: 一 (Nhất) + 丿 + 丨 + 丶 (chữ độc thể phủ định) • 客: 宀 (Miên: mái nhà) + 各 (Các: người tới nhà) • 气: Bộ 气 (Khí - làn hơi bốc lên, chữ độc thể)', 'Ghép 不 [bộ 一] + 客 [bộ 宀] + 气 [bộ 气] để nhớ từ 不客气 (bú kèqì): "đừng khách sáo".', '不客气！', 'Bú kèqì!', 'Không có gì!', 24) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order) VALUES ('g4_1', 'lesson-4', '1. Miêu tả vị trí phương vị với 在 và 是', '+ Dạng khẳng định:', ' a. 在 (Dùng như một động từ) - 在 thường đứng trước từ chỉ địa điểm, nơi chốn để xác định vị trí, mang nghĩa “ở”, “tại”,... Chủ ngữ + 在 + Danh từđịa điểm, nơi chốn/PVT 医院在我们学校的右边。 Yīyuàn zài wǒmen xuéxiào de yòubian. Bệnh viện ở bên phải trường học củ', NULL, '[{"hanzi":"医院在我们学校的右边。","pinyin":"Yīyuàn zài wǒmen xuéxiào de yòubian.","meaning":"Bệnh viện ở bên phải trường học của chúng ta."},{"hanzi":"老师不在办公室里。","pinyin":"Lǎoshī búzài bàngōngshì li.","meaning":"Cô giáo không ở trong phòng làm việc."}]'::jsonb, 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order) VALUES ('g4_2', 'lesson-4', '2. 方位词 – Phương vị từ', '- Phương vị từ ghép: Phương vị từ đơn + 边/面/间', ' a. Khái niệm Phương vị từ là danh từ biểu thị phương hướng hoặc vị trí không gian, có thể đặt trực tiếp ngay phía sau danh từ. b. Phân loại - Phương vị từ đơn: 上,下, 前, 后, 左, 右, 东, 南, 里, 外,... 上面 /shàngmiàn/: Phía trên, bên trên >< 下面 /xiàmian/: Phía', NULL, '[{"hanzi":"爸爸在洗手间里吗？","pinyin":"Bàba zài xǐshǒujiān li ma?","meaning":"Bố có trong nhà vệ sinh không?"},{"hanzi":"弟弟在花园里玩儿。","pinyin":"Dìdi zài huāyuán li wánr.","meaning":"Em trai tôi chơi trong vườn hoa."}]'::jsonb, 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order) VALUES ('g4_3', 'lesson-4', '3. 处所状语 – Trạng ngữ chỉ địa điểm', 'Công thức: 在 + Địa điểm + Động từ', ' Trạng ngữ chỉ địa điểm phải đặt trước vị ngữ động từ và thường có giới từ 在 đứng trước địa điểm đó. 他在图书馆读书。 /Tā zài túshūguǎn dúshū. / Anh ấy đọc sách trong thư viện. 我在外交部当翻译。 /Wǒ zài wàijiāo bù dāng fānyì./ Tôi làm phiên dịch ở Bộ Ngoại giao. 我在学', NULL, '[{"hanzi":"你的前面是城市图书馆。","pinyin":"Nǐ de qiánmian shì chéngshì túshūguǎn.","meaning":"Trước mặt bạn là thư viện thành phố."},{"hanzi":"我的左边不是教学楼。","pinyin":"Wǒ de zuǒbian búshì jiàoxué lóu.","meaning":"Bên trái tôi không phải là tòa giảng đường."}]'::jsonb, 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order) VALUES ('g4_4', 'lesson-4', '4. Đại từ nghi vấn 哪儿 và 哪里', '- Câu hỏi: Danh từ/Đại từ + 在 + 哪儿/哪里? (Cái gì/ai ở đâu?)', ' Đại từ nghi vấn, dùng để hỏi phương vị: ở đâu, không cần dùng 吗 cuối câu hỏi, chúng có chức năng như một danh từ. - Trả lời: Danh từ/Đại từ + 在 + từ chỉ nơi chốn (Cái gì/ai ở …) A: 他在哪儿/哪里？/ Tā zài nǎr/ nǎ li?/ : Anh ấy ở đâu? B: 他在宿舍楼。/Tā zài sùshè', NULL, '[{"hanzi":"老师在外面等你。","pinyin":"Lǎoshī zài wàimian děng nǐ.","meaning":"Thầy giáo đang đợi bạn ở bên ngoài."},{"hanzi":"食堂在教学楼旁边。","pinyin":"Shítáng zài jiàoxué lóu pángbiān.","meaning":"Nhà ăn ở cạnh giảng đường."}]'::jsonb, 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order;
INSERT INTO texts (id, lesson_id, title, description, sort_order) VALUES ('txt_4_1', 'lesson-4', 'Bài khoá #1: Hội thoại giáo trình — Địa điểm', 'Hội thoại chuẩn giáo trình Bài 4. Từ vựng chưa học được chú thích phiên âm & nghĩa trong ngoặc.', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_4_1_1', 'txt_4_1', '马克', '你好。请问，学校的食堂在哪儿？', '你好。请问 (qǐngwèn: xin hỏi)，学校的食堂在哪儿？', 'Nǐ hǎo. Qǐngwèn, xuéxiào de shítáng zài nǎr?', 'Xin chào. Xin hỏi nhà ăn của trường ở đâu vậy?', 1) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_4_1_2', 'txt_4_1', '张风', '后面的那座楼是宿舍，食堂在宿舍的左边。', '后面 (hòumian: phía sau)的那座楼是宿舍，食堂在宿舍的左边。', 'Hòumian de nà zuò lóu shì sùshè, shítáng zài sùshè de zuǒbian.', 'Tòa nhà phía sau kia là ký túc xá, nhà ăn nằm ở bên trái ký túc xá.', 2) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_4_1_3', 'txt_4_1', '马克', '好的，我去食堂吃饭。啊，你知道图书馆在哪里吗？', '好的，我去食堂吃饭。啊，你知道图书馆在哪里吗？', 'Hǎo de, wǒ qù shítáng chīfàn. A, nǐ zhīdào túshūguǎn zài nǎli ma?', 'Vâng, tôi đến nhà ăn ăn cơm. À, bạn có biết thư viện ở đâu không?', 3) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_4_1_4', 'txt_4_1', '张风', '教学楼的右边是图书馆。你去图书馆看书吗？', '教学楼的右边是图书馆。你去图书馆看书吗？', 'Jiàoxué lóu de yòubian shì túshūguǎn. Nǐ qù túshūguǎn kànshū ma?', 'Bên phải tòa nhà giảng đường là thư viện. Bạn đi thư viện đọc sách à?', 4) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_4_1_5', 'txt_4_1', '马克', '是啊，谢谢你！', '是啊，谢谢你！', 'Shì a, xièxie nǐ!', 'Đúng vậy, cảm ơn bạn!', 5) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_4_1_6', 'txt_4_1', '张风', '不客气！', '不客气！', 'Bú kèqì!', 'Không có gì!', 6) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_4_1_1', 'lesson-4', 'txt_4_1', 'listening', 'listening', '你好。请问，学校的食堂在哪儿？', NULL, 'Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Cô ấy không phải Lan Lan.","Anh ấy đi du học ở Bắc Kinh.","Xin chào. Xin hỏi nhà ăn của trường ở đâu vậy?","Tôi đang đi ngang qua từ tầng dưới."]'::jsonb, 2, 'Nội dung nghe được: 你好。请问，学校的食堂在哪儿？ (Nǐ hǎo. Qǐngwèn, xuéxiào de shítáng zài nǎr?) → Xin chào. Xin hỏi nhà ăn của trường ở đâu vậy?', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_4_1_2', 'lesson-4', 'txt_4_1', 'listening', 'listening', '后面的那座楼是宿舍，食堂在宿舍的左边。', NULL, 'Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["下面 (xiàmian: bên dưới)的句子 (jùzi: câu)","老师在外面 (wàimian: bên ngoài)等 (děng: đợi)你。","后面 (hòumian: phía sau)的那座楼是宿舍，食堂在宿舍的左边。","我在外交部 (wàijiāobù: Bộ Ngoại giao)当 (dāng: đảm nhiệm, làm)翻译 (fānyì: dịch, phiên dịch)。"]'::jsonb, 2, 'Câu vừa đọc: 后面的那座楼是宿舍，食堂在宿舍的左边。 (Hòumian de nà zuò lóu shì sùshè, shítáng zài sùshè de zuǒbian.) → Tòa nhà phía sau kia là ký túc xá, nhà ăn nằm ở bên trái ký túc xá.', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_4_1_3', 'lesson-4', 'txt_4_1', 'listening', 'listening', '好的，我去食堂吃饭。啊，你知道图书馆在哪里吗？', NULL, 'Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Cảm cúm một lần","Bên phải tòa nhà giảng đường là thư viện. Bạn đi thư viện đọc sách à?","Vâng, tôi đến nhà ăn ăn cơm. À, bạn có biết thư viện ở đâu không?","Tôi làm phiên dịch ở Bộ Ngoại giao."]'::jsonb, 2, 'Nội dung nghe được: 好的，我去食堂吃饭。啊，你知道图书馆在哪里吗？ (Hǎo de, wǒ qù shítáng chīfàn. A, nǐ zhīdào túshūguǎn zài nǎli ma?) → Vâng, tôi đến nhà ăn ăn cơm. À, bạn có biết thư viện ở đâu không?', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_4_1_4', 'lesson-4', 'txt_4_1', 'listening', 'listening', '教学楼的右边是图书馆。你去图书馆看书吗？', NULL, 'Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["教学楼的右边是图书馆。你去图书馆看书吗？","食堂在教学楼旁边 (pángbiān: bên cạnh)。","爸爸 (bàba: bố)在洗手间 (xǐshǒujiān: nhà vệ sinh)里 (lǐ: trong)吗？","桌子 (zhuōzi: cái bàn)下面 (xiàmian: bên dưới)"]'::jsonb, 0, 'Câu vừa đọc: 教学楼的右边是图书馆。你去图书馆看书吗？ (Jiàoxué lóu de yòubian shì túshūguǎn. Nǐ qù túshūguǎn kànshū ma?) → Bên phải tòa nhà giảng đường là thư viện. Bạn đi thư viện đọc sách à?', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO texts (id, lesson_id, title, description, sort_order) VALUES ('txt_4_2', 'lesson-4', 'Bài nghe tổng hợp: Ôn tập lũy tiến (Bài 1 – Bài 4)', 'Kết hợp từ vựng & mẫu câu đã học từ Bài 1 đến Bài 3 cùng trọng tâm Bài 4 để củng cố phản xạ nghe.', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_4_2_1', 'txt_4_2', 'Ôn Bài 3', '他是谁？', '他是谁？', 'Tā shì shéi?', 'Anh ấy là ai?', 1) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_4_2_2', 'txt_4_2', 'Bài 4', '食堂左边', '食堂左边', 'shítáng zuǒbian', 'Phía bên trái nhà ăn', 2) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_4_2_3', 'txt_4_2', 'Ôn Bài 2', 'A: 你叫什么名字？', 'A: 你叫什么名字？', 'Nǐ jiào shénme míngzi?', 'Bạn tên là gì?', 3) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_4_2_4', 'txt_4_2', 'Bài 4', '好的，我去食堂吃饭。啊，你知道图书馆在哪里吗？', '好的，我去食堂吃饭。啊，你知道图书馆在哪里吗？', 'Hǎo de, wǒ qù shítáng chīfàn. A, nǐ zhīdào túshūguǎn zài nǎli ma?', 'Vâng, tôi đến nhà ăn ăn cơm. À, bạn có biết thư viện ở đâu không?', 4) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_4_2_5', 'txt_4_2', 'Ôn Bài 1', '老师们', '老师们', 'lǎoshīmen', 'Các thầy cô giáo', 5) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_4_2_6', 'txt_4_2', 'Bài 4', '教学楼的右边是图书馆。你去图书馆看书吗？', '教学楼的右边是图书馆。你去图书馆看书吗？', 'Jiàoxué lóu de yòubian shì túshūguǎn. Nǐ qù túshūguǎn kànshū ma?', 'Bên phải tòa nhà giảng đường là thư viện. Bạn đi thư viện đọc sách à?', 6) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_4_2_7', 'txt_4_2', 'Ôn Bài 3', '他是我的老师。', '他是我的老师。', 'Tā shì wǒ de lǎoshī.', 'Thầy ấy là thầy giáo của tớ.', 7) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_4_2_8', 'txt_4_2', 'Bài 4', '是啊，谢谢你！', '是啊，谢谢你！', 'Shì a, xièxie nǐ!', 'Đúng vậy, cảm ơn bạn!', 8) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_4_2_1', 'lesson-4', 'txt_4_2', 'listening', 'listening', '他是谁？', NULL, '[Ôn tập Bài 3] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Anh ấy là ai?","Cậu đi gì đến siêu thị thế?","Anh ấy vẫn cứ chờ đợi cậu.","Con đang ăn nè."]'::jsonb, 0, 'Nội dung nghe được: 他是谁？ (Tā shì shéi?) → Anh ấy là ai?', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_4_2_2', 'lesson-4', 'txt_4_2', 'listening', 'listening', '食堂左边', NULL, '[Bài 4] Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["请问 (qǐngwèn: xin hỏi)，马克在那个楼吗？","好的，我去食堂吃饭。啊，你知道图书馆在哪里吗？","你的前面是城市 (chéngshì: thành phố)图书馆。","食堂左边"]'::jsonb, 3, 'Câu vừa đọc: 食堂左边 (shítáng zuǒbian) → Phía bên trái nhà ăn', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_4_2_3', 'lesson-4', 'txt_4_2', 'listening', 'listening', 'A: 你叫什么名字？', NULL, '[Ôn tập Bài 2] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Nếu có gì không biết thì cậu cứ hỏi tớ.","Tôi đang đọc sách.","ba cây bút chì","Bạn tên là gì?"]'::jsonb, 3, 'Nội dung nghe được: A: 你叫什么名字？ (Nǐ jiào shénme míngzi?) → Bạn tên là gì?', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_4_2_4', 'lesson-4', 'txt_4_2', 'listening', 'listening', '好的，我去食堂吃饭。啊，你知道图书馆在哪里吗？', NULL, '[Bài 4] Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["好的，我去食堂吃饭。啊，你知道图书馆在哪里吗？","后边 (hòubian: phía sau)的女生 (nǚshēng: nữ sinh)","学校的图书馆在哪儿？","我的左边不 (bù: không)是教学楼。"]'::jsonb, 0, 'Câu vừa đọc: 好的，我去食堂吃饭。啊，你知道图书馆在哪里吗？ (Hǎo de, wǒ qù shítáng chīfàn. A, nǐ zhīdào túshūguǎn zài nǎli ma?) → Vâng, tôi đến nhà ăn ăn cơm. À, bạn có biết thư viện ở đâu không?', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_4_2_5', 'lesson-4', 'txt_4_2', 'listening', 'listening', '老师们', NULL, '[Ôn tập Bài 1] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["quyển sách này","Thử qua một chút.","Các thầy cô giáo","Bạn bè tốt đã mời tôi, tôi đâu thể không đi được? (Tôi nhất định sẽ đi)"]'::jsonb, 2, 'Nội dung nghe được: 老师们 (lǎoshīmen) → Các thầy cô giáo', 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO texts (id, lesson_id, title, description, sort_order) VALUES ('txt_4_3', 'lesson-4', 'Bài khoá mở rộng: Tìm đường trong khuôn viên trường (Mở rộng)', 'Hội thoại tình huống mới xây dựng dựa trên từ vựng và ngữ pháp Bài 4 (không trùng lặp nguyên văn giáo trình).', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_4_3_1', 'txt_4_3', 'Lan', '请问，附近有食堂吗？', '请问 (qǐngwèn: xin hỏi)，附近有 (yǒu: có)食堂吗？', 'Qǐngwèn, fùjìn yǒu shítáng ma?', 'Xin hỏi quanh đây có nhà ăn không ạ?', 1) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_4_3_2', 'txt_4_3', 'Minh', '有，食堂在教学楼的右边。', '有 (yǒu: có)，食堂在教学楼的右边。', 'Yǒu, shítáng zài jiàoxué lóu de yòubian.', 'Có, nhà ăn nằm ở bên phải tòa nhà giảng đường.', 2) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_4_3_3', 'txt_4_3', 'Lan', '图书馆也在教学楼前面吗？', '图书馆也在教学楼前面吗？', 'Túshūguǎn yě zài jiàoxué lóu qiánmian ma?', 'Thư viện cũng ở phía trước tòa giảng đường à?', 3) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_4_3_4', 'txt_4_3', 'Minh', '不是，图书馆在教学楼的左边，我们一起去吧！', '不 (bù: không)是，图书馆在教学楼的左边，我们一起 (yīqǐ: cùng nhau)去吧 (ba: đi, nhé)！', 'Bú shì, túshūguǎn zài jiàoxué lóu de zuǒbian, wǒmen yīqǐ qù ba!', 'Không, thư viện ở bên trái tòa giảng đường, chúng ta cùng đi nhé!', 4) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_4_3_1', 'lesson-4', 'txt_4_3', 'listening', 'listening', '请问，附近有食堂吗？ 有，食堂在教学楼的右边。 图书馆也在教学楼前面吗？ 不是，图书馆在教学楼的左边，我们一起去吧！', NULL, '[Nghe hiểu tình huống mới] Theo chỉ dẫn của Minh, thư viện nằm ở phía nào so với tòa giảng đường?', '["Ở bên trái tòa nhà giảng đường","Ở bên phải tòa nhà giảng đường","Ở phía sau nhà ăn","Ở ngoài trường học"]'::jsonb, 0, 'Minh nói rõ: ''图书馆在教学楼的左边'' (bên trái tòa giảng đường).', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_4_3_2', 'lesson-4', 'txt_4_3', 'listening', 'listening', '请问，附近有食堂吗？', NULL, '[Mở rộng] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Xin hỏi quanh đây có nhà ăn không ạ?","Bố có trong nhà vệ sinh không?","Lớp cậu có bao nhiêu học sinh?","Cậu nên ngủ sớm dậy sớm."]'::jsonb, 0, 'Nội dung nghe được: 请问，附近有食堂吗？ (Qǐngwèn, fùjìn yǒu shítáng ma?) → Xin hỏi quanh đây có nhà ăn không ạ?', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_4_3_3', 'lesson-4', 'txt_4_3', 'listening', 'listening', '有，食堂在教学楼的右边。', NULL, '[Mở rộng] Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["请问 (qǐngwèn: xin hỏi)，马克在那个楼吗？","好的，我去食堂吃饭。啊，你知道图书馆在哪里吗？","有 (yǒu: có)，食堂在教学楼的右边。","你去学校附近的地方吗？"]'::jsonb, 2, 'Câu vừa đọc: 有，食堂在教学楼的右边。 (Yǒu, shítáng zài jiàoxué lóu de yòubian.) → Có, nhà ăn nằm ở bên phải tòa nhà giảng đường.', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_4_3_4', 'lesson-4', 'txt_4_3', 'listening', 'listening', '图书馆也在教学楼前面吗？', NULL, '[Mở rộng] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Trương Hồng là giáo viên à?","Thư viện cũng ở phía trước tòa giảng đường à?","Cô ấy tự tin tham gia cuộc thi.","Tạm biệt!"]'::jsonb, 1, 'Nội dung nghe được: 图书馆也在教学楼前面吗？ (Túshūguǎn yě zài jiàoxué lóu qiánmian ma?) → Thư viện cũng ở phía trước tòa giảng đường à?', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
