INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss4_exp_1', 'lesson-4', '你好请问学校的食堂在哪儿', 'Xin chào. Xin hỏi nhà ăn của trường ở đâu vậy?', 'Nǐ hǎo. Qǐngwèn, xuéxiào de shítáng zài nǎr?', '["你好","请问","学校","的","食堂","在","哪儿"]'::jsonb, NULL, 7) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss4_exp_2', 'lesson-4', '后面的那座楼是宿舍食堂在宿舍的左边', 'Tòa nhà phía sau kia là ký túc xá, nhà ăn nằm ở bên trái ký túc xá.', 'Hòumian de nà zuò lóu shì sùshè, shítáng zài sùshè de zuǒbian.', '["后","面","的","那","座","楼","是","宿舍","食堂","在","宿舍","的","左边"]'::jsonb, NULL, 8) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss4_exp_3', 'lesson-4', '好的我去食堂吃饭啊你知道图书馆在哪里吗', 'Vâng, tôi đến nhà ăn ăn cơm. À, bạn có biết thư viện ở đâu không?', 'Hǎo de, wǒ qù shítáng chīfàn. A, nǐ zhīdào túshūguǎn zài nǎli ma?', '["好","的","我","去","食堂","吃","饭","啊","你","知道","图书馆","在","哪里","吗"]'::jsonb, NULL, 9) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss4_exp_4', 'lesson-4', '教学楼的右边是图书馆你去图书馆看书吗', 'Bên phải tòa nhà giảng đường là thư viện. Bạn đi thư viện đọc sách à?', 'Jiàoxué lóu de yòubian shì túshūguǎn. Nǐ qù túshūguǎn kànshū ma?', '["教学楼","的","右边","是","图书馆","你","去","图书馆","看","书","吗"]'::jsonb, NULL, 10) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
