INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr4_vi_exp_1', 'lesson-4', 'vi_to_zh', 'Xin chào. Xin hỏi nhà ăn của trường ở đâu vậy?', NULL, NULL, '你好。请问，学校的食堂在哪儿？', NULL, 'nǐ hǎo qǐngwèn xuéxiào de shítáng zài nǎr', '[]'::jsonb, 'Gợi ý Pinyin: Nǐ hǎo. Qǐngwèn, xuéxiào de shítáng zài nǎr?', 'Xin chào. Xin hỏi nhà ăn của trường ở đâu vậy? → 你好。请问，学校的食堂在哪儿？ (Nǐ hǎo. Qǐngwèn, xuéxiào de shítáng zài nǎr?)', 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr4_vi_exp_2', 'lesson-4', 'vi_to_zh', 'Tòa nhà phía sau kia là ký túc xá, nhà ăn nằm ở bên trái ký túc xá.', NULL, NULL, '后面的那座楼是宿舍，食堂在宿舍的左边。', NULL, 'hòumian de nà zuò lóu shì sùshè shítáng zài sùshè de zuǒbian', '[]'::jsonb, 'Gợi ý Pinyin: Hòumian de nà zuò lóu shì sùshè, shítáng zài sùshè de zuǒbian.', 'Tòa nhà phía sau kia là ký túc xá, nhà ăn nằm ở bên trái ký túc xá. → 后面的那座楼是宿舍，食堂在宿舍的左边。 (Hòumian de nà zuò lóu shì sùshè, shítáng zài sùshè de zuǒbian.)', 6) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr4_vi_exp_3', 'lesson-4', 'vi_to_zh', 'Vâng, tôi đến nhà ăn ăn cơm. À, bạn có biết thư viện ở đâu không?', NULL, NULL, '好的，我去食堂吃饭。啊，你知道图书馆在哪里吗？', NULL, 'hǎo de wǒ qù shítáng chīfàn a nǐ zhīdào túshūguǎn zài nǎli ma', '[]'::jsonb, 'Gợi ý Pinyin: Hǎo de, wǒ qù shítáng chīfàn. A, nǐ zhīdào túshūguǎn zài nǎli ma?', 'Vâng, tôi đến nhà ăn ăn cơm. À, bạn có biết thư viện ở đâu không? → 好的，我去食堂吃饭。啊，你知道图书馆在哪里吗？ (Hǎo de, wǒ qù shítáng chīfàn. A, nǐ zhīdào túshūguǎn zài nǎli ma?)', 7) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
