INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq5_13', 'lesson-5', NULL, 'expanded_quiz', 'radical', NULL, NULL, 'Chữ Hán “时间” chứa bộ thủ nào sau đây?', '["艹 (Thảo) (Cỏ cây, hoa lá, thảo mộc)","鸟 (Điểu) (Chim chóc, loài có cánh)","土 (Thổ) (Đất đai, vị trí, công trình)","日 (Nhật) (Mặt trời, ban ngày, thời gian, ánh sáng)"]'::jsonb, 3, 'Chữ “时间” có bộ chính 日 (Nhật) (Mặt trời, ban ngày, thời gian, ánh sáng). Chiết tự: 时: 日 (Nhật: mặt trời) + 寸 (Thốn: đo thời gian) • 间: 门 (Môn: khe cửa) + 日 (Nhật: ánh nắng lọt qua)', 13) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq5_14', 'lesson-5', NULL, 'expanded_quiz', 'radical', NULL, NULL, 'Chữ Hán “时候” chứa bộ thủ nào sau đây?', '["日 (Nhật) (Mặt trời, ban ngày, thời gian, ánh sáng)","匚 (Phương) (Hộp đựng, vật chứa)","户 (Hộ) (Cánh cửa, gia đình, nhà cửa)","皮 (Bì) (Da dẻ, vỏ ngoài)"]'::jsonb, 0, 'Chữ “时候” có bộ chính 日 (Nhật) (Mặt trời, ban ngày, thời gian, ánh sáng). Chiết tự: 时: 日 (Nhật: mặt trời) + 寸 (Thốn: đo thời gian) • 候: 亻 (Nhân đứng) + 丨 + 矢 (Thỉ)', 14) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq5_15', 'lesson-5', NULL, 'expanded_quiz', 'radical', NULL, NULL, 'Chữ Hán “点” chứa bộ thủ nào sau đây?', '["火/灬 (Hỏa) (Lửa, nhiệt độ, nấu nướng, nóng bức)","毛 (Mao) (Lông tóc, sợi mảnh)","耳 (Nhĩ) (Cái tai, lắng nghe)","页 (Hiệt) (Đầu mặt, trang giấy)"]'::jsonb, 0, 'Chữ “点” có bộ chính 火/灬 (Hỏa) (Lửa, nhiệt độ, nấu nướng, nóng bức). Chiết tự: 点 = 占 (Chiếm) + 灬 (Hỏa: ngọn lửa chấm sáng).', 15) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq5_16', 'lesson-5', NULL, 'expanded_quiz', 'radical', NULL, NULL, 'Chữ Hán “点钟” chứa bộ thủ nào sau đây?', '["干 (Can) (Can thiệp, khô ráo, làm việc)","玉/王 (Ngọc) (Đá quý, châu báu)","艹 (Thảo) (Cỏ cây, hoa lá, thảo mộc)","火/灬 (Hỏa) (Lửa, nhiệt độ, nấu nướng, nóng bức)"]'::jsonb, 3, 'Chữ “点钟” có bộ chính 火/灬 (Hỏa) (Lửa, nhiệt độ, nấu nướng, nóng bức). Chiết tự: 点: 占 (Chiếm) + 灬 (Hỏa: ngọn lửa chấm sáng) • 钟: 钅 (Kim: kim loại đúc chuông/đồng hồ) + 中 (Trung)', 16) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
