INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq5_22', 'lesson-5', NULL, 'expanded_quiz', 'reading', NULL, NULL, 'Câu “我明天上午八点上课。” có nghĩa tiếng Việt là gì?', '["Tám giờ sáng ngày mai tớ đi học.","Tạm biệt!","Em chào thầy/cô ạ","Bye! (thường dùng trong giới trẻ)"]'::jsonb, 0, '我明天上午八点上课。 (Wǒ míngtiān shàngwǔ bā diǎn shàngkè.) → Tám giờ sáng ngày mai tớ đi học.', 22) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct5_1', 'lesson-5', NULL, 'comprehensive_test', 'listening', '五点半！你想借书吗？', NULL, 'Nghe đoạn ghi âm và chọn nghĩa tiếng Việt đúng:', '["Tôi đến từ Việt Nam.","Mark, sáng mai gặp lại nhé!","Tôi là Trần Anh.","5 giờ rưỡi! Bạn muốn mượn sách à?"]'::jsonb, 3, 'Nội dung nghe được: “五点半！你想借书吗？” (Wǔ diǎn bàn! Nǐ xiǎng jiè shū ma?) → 5 giờ rưỡi! Bạn muốn mượn sách à?', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct5_2', 'lesson-5', NULL, 'comprehensive_test', 'listening', '不客气！', NULL, 'Nghe đoạn ghi âm và chọn câu tiếng Trung khớp với nội dung vừa nghe:', '["我叫马克。她叫什么名字？","我明天上午八点上课。","我要回宿舍了。再见!","不客气！"]'::jsonb, 3, 'Câu vừa đọc: “不客气！” (Bú kèqì!) → Không có gì!', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct5_3', 'lesson-5', NULL, 'comprehensive_test', 'listening', '中午好同学们', NULL, 'Nghe đoạn ghi âm và chọn nghĩa tiếng Việt đúng:', '["Thư viện của trường ở đâu vậy?","Bệnh viện ở bên phải trường học của chúng ta.","Đúng vậy, cảm ơn bạn!","Chào buổi trưa các bạn học sinh!"]'::jsonb, 3, 'Nội dung nghe được: “中午好同学们” (Zhōngwǔ hǎo, tóngxuémen!) → Chào buổi trưa các bạn học sinh!', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct5_4', 'lesson-5', NULL, 'comprehensive_test', 'listening', '小兰，你房间号码是多少？', NULL, 'Nghe đoạn ghi âm và chọn câu tiếng Trung khớp với nội dung vừa nghe:', '["她是老师。","早上好！","小兰，你房间号码是多少？","现在是上午八点一刻"]'::jsonb, 2, 'Câu vừa đọc: “小兰，你房间号码是多少？” (Xiǎolán, nǐ fángjiān hàomǎ shì duōshao?) → Lan ơi, số phòng của cậu là bao nhiêu?', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct5_5', 'lesson-5', NULL, 'comprehensive_test', 'listening', '老师好', NULL, 'Nghe đoạn ghi âm và chọn nghĩa tiếng Việt đúng:', '["Thư viện của trường ở đâu vậy?","Tạm biệt!","Chào thầy/Chào cô","Vâng, tôi đến nhà ăn ăn cơm. À, bạn có biết thư viện ở đâu không?"]'::jsonb, 2, 'Nội dung nghe được: “老师好” (Lǎoshī hǎo) → Chào thầy/Chào cô', 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct5_6', 'lesson-5', NULL, 'comprehensive_test', 'listening', '昨天下午你去图书馆了吗', NULL, 'Nghe đoạn ghi âm và chọn câu tiếng Trung khớp với nội dung vừa nghe:', '["你好，同学！请问你贵姓？","这是什么书？","昨天下午你去图书馆了吗","同学们"]'::jsonb, 2, 'Câu vừa đọc: “昨天下午你去图书馆了吗” (Zuótiān xiàwǔ nǐ qù túshūguǎn le ma?) → Chiều hôm qua bạn có đi thư viện không?', 6) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct5_7', 'lesson-5', NULL, 'comprehensive_test', 'listening', '明天上午你几点去教室？', NULL, 'Nghe đoạn ghi âm và chọn nghĩa tiếng Việt đúng:', '["Sáng mai mấy giờ bạn đến phòng học?","Rất vui được làm quen với bạn! Bạn đến từ Canada à?","Chào bạn! Xin hỏi bạn họ gì vậy?","Vâng, em là Nguyễn Nhật Minh, em là du học sinh mới của trường."]'::jsonb, 0, 'Nội dung nghe được: “明天上午你几点去教室？” (Míngtiān shàngwǔ nǐ jǐ diǎn qù jiàoshì?) → Sáng mai mấy giờ bạn đến phòng học?', 7) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct5_8', 'lesson-5', NULL, 'comprehensive_test', 'listening', '张风，现在几点了？', NULL, 'Nghe đoạn ghi âm và chọn câu tiếng Trung khớp với nội dung vừa nghe:', '["图书馆几点关门？","不是。我是美国人。你来自哪个国家？","张风，现在几点了？","很高兴认识你！你来自加拿大吗？"]'::jsonb, 2, 'Câu vừa đọc: “张风，现在几点了？” (Zhāng Fēng, xiànzài jǐ diǎn le?) → Trương Phong, bây giờ mấy giờ rồi?', 8) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
