INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct5_48', 'lesson-5', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ Hán tự “点钟” (giờ đúng, giờ chẵn, tiếng (đồng hồ)) có phiên âm Pinyin đúng là gì?', '["shénme","diǎnzhōng","wèn","jiàoxuélóu"]'::jsonb, 1, '“点钟” đọc là “diǎnzhōng”, nghĩa là: giờ đúng, giờ chẵn, tiếng (đồng hồ).', 48) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
