INSERT INTO lessons (id, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id) VALUES ('lesson-6', 'Bài 6: Hỏi đường - Đơn nguyên 1: Trường học', 'Bài 6', 'Đơn nguyên 1: Trường học', 'Phương vị từ (trước, sau, trong, ngoài, trái, phải), chỉ đường và cấu trúc 从... 到..., 往... 走.', '2026-11-14'::date, 6, TRUE, NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, date_added = EXCLUDED.date_added, sort_order = EXCLUDED.sort_order, is_system = TRUE, updated_at = NOW();
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v6_1', 'lesson-6', '书店', 'shūdiàn', 'thư điếm', 'hiệu sách', 'Danh từ', '乙 (Ất) (Uốn cong, số thứ tự, chồi non)', '书: Nét gấp 乛 + 乛 + 丨 + 丶 (cuốn sách, bút viết) • 店: 广 (Nghiễm: mái hiên) + 占 (Chiếm: quầy hàng)', 'Ghép 书 [bộ 乙] + 店 [bộ 广] để nhớ từ 书店 (shūdiàn): "hiệu sách".', '张风，你知道书店在哪儿吗？', 'Zhāng Fēng, nǐ zhīdào shūdiàn zài nǎr ma?', 'Trương Phong, bạn có biết hiệu sách ở đâu không?', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v6_2', 'lesson-6', '电影院', 'diànyǐngyuàn', 'điện ảnh viện', 'rạp chiếu phim', 'Danh từ', '田 (Điền) (Ruộng đất, khu vực, mặt)', '电: 日/田 (biến thể) + 乚 (tia sét phóng xuống) • 影: 景 (Cảnh: ánh sáng) + 彡 (Sam: bóng rọi) • 院: 阝 (Phụ: tường thành) + 完 (Hoàn: khu nhà khép kín)', 'Ghép 电 [bộ 田] + 影 [bộ 彡] + 院 [bộ 阝] để nhớ từ 电影院 (diànyǐngyuàn): "rạp chiếu phim".', '书店在西边，在美术馆和电影院中间。', 'Shūdiàn zài xībian, zài měishùguǎn hé diànyǐngyuàn zhōngjiān.', 'Hiệu sách ở phía tây, nằm giữa bảo tàng mỹ thuật và rạp chiếu phim.', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v6_3', 'lesson-6', '美术馆', 'měishùguǎn', 'Mỹ quán', 'bảo tàng mỹ thuật', 'Danh từ', '羊 (Dương) (Con dê, cừu, tốt đẹp)', '美: 羊 (Dương: cừu béo) + 大 (Đại: to lớn là đẹp) • 术: 木 (Mộc: cây cối) + 丶 (Chủ) • 馆: 饣 (Thực) + 官 (Quan: nơi công cộng)', 'Ghép 美 [bộ 羊] + 术 [bộ 木] + 馆 [bộ 饣] để nhớ từ 美术馆 (měishùguǎn): "bảo tàng mỹ thuật".', '书店在西边，在美术馆和电影院中间。', 'Shūdiàn zài xībian, zài měishùguǎn hé diànyǐngyuàn zhōngjiān.', 'Hiệu sách ở phía tây, nằm giữa bảo tàng mỹ thuật và rạp chiếu phim.', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v6_4', 'lesson-6', '马路', 'mǎlù', 'Mã', 'đường lớn, đường cái', 'Danh từ', '马 (Mã) (Con ngựa, chạy nhanh)', '马: Bộ 马 (Mã - hình dáng con ngựa, chữ độc thể) • 路: ⻊ (Túc: bàn chân bước đi) + 各 (Các)', 'Ghép 马 [bộ 马] + 路 [bộ 足] để nhớ từ 马路 (mǎlù): "đường lớn, đường cái".', '你从这儿一直往东走，到十字路口往左拐，马路西边有一座白色的大楼，那就是书店。', 'Nǐ cóng zhèr yīzhí wǎng dōng zǒu, dào shízìlùkǒu wǎng zuǒ guǎi, mǎlù xībian yǒu yízuò báisè de dàlóu, nà jiùshì shūdiàn.', 'Bạn đi thẳng về phía đông từ đây, đến ngã tư thì rẽ trái, phía tây con đường có một tòa nhà lớn màu trắng, đó chính là hiệu sách.', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v6_5', 'lesson-6', '十字路口', 'shízìlùkǒu', 'tự khẩu', 'ngã tư', 'Danh từ', '十 (Thập) (Số mười, hoàn chỉnh, giao nhau)', '十: Bộ 十 (Thập - nét ngang cắt nét dọc, số 10) • 字: 宀 (Miên: mái nhà) + 子 (Tử: con cái, sinh sôi chữ nghĩa) • 路: ⻊ (Túc: bàn chân bước đi) + 各 (Các) • 口: Bộ 口 (Khẩu - hình cái miệng mở, chữ độc thể)', 'Ghép 十 [bộ 十] + 字 [bộ 子] + 路 [bộ 足] + 口 [bộ 口] để nhớ từ 十字路口 (shízìlùkǒu): "ngã tư".', '你从这儿一直往东走，到十字路口往左拐，马路西边有一座白色的大楼，那就是书店。', 'Nǐ cóng zhèr yīzhí wǎng dōng zǒu, dào shízìlùkǒu wǎng zuǒ guǎi, mǎlù xībian yǒu yízuò báisè de dàlóu, nà jiùshì shūdiàn.', 'Bạn đi thẳng về phía đông từ đây, đến ngã tư thì rẽ trái, phía tây con đường có một tòa nhà lớn màu trắng, đó chính là hiệu sách.', 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v6_6', 'lesson-6', '东边', 'dōngbian', 'biên', 'hướng đông', 'Danh từ', '一 (Nhất) (Số một, nền tảng, nét ngang cơ bản)', '东: Mặt trời mọc sau thân cây (七 + 小) • 边: 力 (Lực) + 辶 (Sước: đi ven mép)', 'Ghép 东 [bộ 一] + 边 [bộ 辶] để nhớ từ 东边 (dōngbian): "hướng đông".', '这是关于“东边”的常用句子。', 'Zhè shì guānyú ''dōngbian'' de chángyòng jùzi.', 'Đây là câu ví dụ sử dụng từ ''东边'' (hướng đông).', 6) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v6_7', 'lesson-6', '西边', 'xībian', 'tây biên', 'hướng tây', 'Danh từ', '西/覀 (Tây) (Phương tây, che đậy)', '西: Bộ 西 (Tây - chim về tổ lúc mặt trời lặn) • 边: 力 (Lực) + 辶 (Sước: đi ven mép)', 'Ghép 西 [bộ 西] + 边 [bộ 辶] để nhớ từ 西边 (xībian): "hướng tây".', '书店在西边，在美术馆和电影院中间。', 'Shūdiàn zài xībian, zài měishùguǎn hé diànyǐngyuàn zhōngjiān.', 'Hiệu sách ở phía tây, nằm giữa bảo tàng mỹ thuật và rạp chiếu phim.', 7) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v6_8', 'lesson-6', '南边', 'nánbian', 'Nam biên', 'hướng nam', 'Danh từ', '十 (Thập) (Số mười, hoàn chỉnh, giao nhau)', '南: 十 (Thập) + 冂 (Quynh) + 羊 (biến thể) • 边: 力 (Lực) + 辶 (Sước: đi ven mép)', 'Ghép 南 [bộ 十] + 边 [bộ 辶] để nhớ từ 南边 (nánbian): "hướng nam".', '这是关于“南边”的常用句子。', 'Zhè shì guānyú ''nánbian'' de chángyòng jùzi.', 'Đây là câu ví dụ sử dụng từ ''南边'' (hướng nam).', 8) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v6_9', 'lesson-6', '北边', 'běibian', 'biên', 'hướng bắc', 'Danh từ', '匕 (Chủy) (Cái thìa, dao găm)', '北: Hai người quay lưng vào nhau (sóng đôi ngược chiều) • 边: 力 (Lực) + 辶 (Sước: đi ven mép)', 'Ghép 北 [bộ 匕] + 边 [bộ 辶] để nhớ từ 北边 (běibian): "hướng bắc".', '这是关于“北边”的常用句子。', 'Zhè shì guānyú ''běibian'' de chángyòng jùzi.', 'Đây là câu ví dụ sử dụng từ ''北边'' (hướng bắc).', 9) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v6_10', 'lesson-6', '中间', 'zhōngjiān', 'trung gian', 'ở giữa, chính giữa', 'Danh từ', '丨 (Cổn) (Nét sổ thẳng, xuyên suốt)', '中: 口 (Khẩu: khung vuông) + 丨 (Cổn: vạch chính giữa) • 间: 门 (Môn: khe cửa) + 日 (Nhật: ánh nắng lọt qua)', 'Ghép 中 [bộ 丨] + 间 [bộ 门] để nhớ từ 中间 (zhōngjiān): "ở giữa, chính giữa".', '书店在西边，在美术馆和电影院中间。', 'Shūdiàn zài xībian, zài měishùguǎn hé diànyǐngyuàn zhōngjiān.', 'Hiệu sách ở phía tây, nằm giữa bảo tàng mỹ thuật và rạp chiếu phim.', 10) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v6_11', 'lesson-6', '走', 'zǒu', 'từ Hán ngữ', 'đi', 'Động từ', '走 (Tẩu) (Chạy, đi lại, rời đi)', '走 = 土 (Thổ) + 龰 (Chân bước nhanh trên đất).', 'Ghi nhớ chữ [走] (đi) qua hình tượng Chạy, đi lại, rời đi.', 'A: 请问，去医院怎么走呢？', 'Qǐngwèn, qù yīyuàn zěnme zǒu ne?', 'Xin hỏi, đi đến bệnh viện như thế nào vậy?', 11) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v6_12', 'lesson-6', '到', 'dào', 'đáo', 'đến', 'Động từ', '刀/刂 (Đao) (Con dao, cắt xẻ, phân chia)', '到 = 至 (Chí: đi tới) + 刂 (Đao).', 'Chữ 到 (dào) mang nghĩa "đến", bộ chính 刀/刂 (Đao); cấu tạo: 至 (Chí: đi tới) + 刂 (Đao).', 'B: 你一直往前走，然后右拐就看到医院在你左边。', 'Nǐ yīzhí wǎng qián zǒu, ránhòu yòu guǎi jiù kàndào yīyuàn zài nǐ zuǒbian.', 'Bạn cứ đi thẳng, sau đó rẽ phải là sẽ nhìn thấy bệnh viện ở bên trái của', 12) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v6_13', 'lesson-6', '拐', 'guǎi', 'từ Hán ngữ', 'rẽ', 'Động từ', '手/扌 (Thủ) (Bàn tay, động tác, thao tác)', '拐 = 扌 (Thủ: tay rẽ hướng) + 另 (Lệnh).', 'Chữ 拐 (guǎi) mang nghĩa "rẽ", bộ chính 手/扌 (Thủ); cấu tạo: 扌 (Thủ: tay rẽ hướng) + 另 (Lệnh).', 'B: 你一直往前走，然后右拐就看到医院在你左边。', 'Nǐ yīzhí wǎng qián zǒu, ránhòu yòu guǎi jiù kàndào yīyuàn zài nǐ zuǒbian.', 'Bạn cứ đi thẳng, sau đó rẽ phải là sẽ nhìn thấy bệnh viện ở bên trái của', 13) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v6_14', 'lesson-6', '离', 'lí', 'từ Hán ngữ', 'cách', 'Động từ', '亠 (Đầu) (Nóc, đỉnh đầu)', '离 = 亠 + 凶 (Hung) + 禸.', 'Chữ 离 (lí) mang nghĩa "cách", bộ chính 亠 (Đầu); cấu tạo: 亠 + 凶 (Hung) + 禸.', '离这儿远吗？', 'Lí zhèr yuǎn ma?', 'Cách đây có xa không?', 14) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v6_15', 'lesson-6', '有', 'yǒu', 'hữu', 'có', 'Động từ', '月 (Nguyệt/Nhục) (Mặt trăng hoặc các bộ phận thân thể người)', '有 = 𠂇 (bàn tay) + 月 (Nguyệt/Nhục: cầm miếng thịt là có).', 'Chữ 有 (yǒu) mang nghĩa "có", bộ chính 月 (Nguyệt/Nhục); cấu tạo: 𠂇 (bàn tay) + 月 (Nguyệt/Nhục: cầm miếng thịt là có).', '不远，很近。从这儿到那儿有二百米。', 'Bù yuǎn，hěn jìn. Cóng zhèr dào nàr yǒu èrbǎi mǐ.', 'Không xa, rất gần. Từ đây đến đó khoảng 200 mét.', 15) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v6_16', 'lesson-6', '买', 'mǎi', 'mãi', 'mua', 'Động từ', '乙 (Ất) (Uốn cong, số thứ tự, chồi non)', '买 = 乛 (nét gập) + 头 (Đầu).', 'Chữ 买 (mǎi) mang nghĩa "mua", bộ chính 乙 (Ất); cấu tạo: 乛 (nét gập) + 头 (Đầu).', '谢谢，你常到那儿买书吗？', 'Xièxie, nǐ cháng dào nàr mǎi shū ma?', 'Cảm ơn, bạn có hay đến đó mua sách không?', 16) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v6_17', 'lesson-6', '远', 'yuǎn', 'từ Hán ngữ', 'xa', 'Tính từ', '辶 (Sước) (Bước đi, di chuyển, khoảng cách)', '远 = 元 (Nguyên) + 辶 (Sước: bước đường xa).', 'Chữ 远 (yuǎn) mang nghĩa "xa", bộ chính 辶 (Sước); cấu tạo: 元 (Nguyên) + 辶 (Sước: bước đường xa).', '离这儿远吗？', 'Lí zhèr yuǎn ma?', 'Cách đây có xa không?', 17) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v6_18', 'lesson-6', '近', 'jìn', 'từ Hán ngữ', 'gần', 'Tính từ', '辶 (Sước) (Bước đi, di chuyển, khoảng cách)', '近 = 斤 (Cân) + 辶 (Sước: đi lại gần).', 'Chữ 近 (jìn) mang nghĩa "gần", bộ chính 辶 (Sước); cấu tạo: 斤 (Cân) + 辶 (Sước: đi lại gần).', '不远，很近。从这儿到那儿有二百米。', 'Bù yuǎn，hěn jìn. Cóng zhèr dào nàr yǒu èrbǎi mǐ.', 'Không xa, rất gần. Từ đây đến đó khoảng 200 mét.', 18) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v6_19', 'lesson-6', '米', 'mǐ', 'từ Hán ngữ', 'mét (m)', 'Lượng từ', '米 (Mễ) (Hạt gạo, tinh bột)', '米 = Bộ 米 (Mễ - các hạt gạo vây quanh chữ thập).', 'Ghi nhớ chữ [米] (mét (m)) qua hình tượng Hạt gạo, tinh bột.', '不远，很近。从这儿到那儿有二百米。', 'Bù yuǎn，hěn jìn. Cóng zhèr dào nàr yǒu èrbǎi mǐ.', 'Không xa, rất gần. Từ đây đến đó khoảng 200 mét.', 19) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v6_20', 'lesson-6', '往', 'wǎng', 'từ Hán ngữ', 'hướng về', 'Giới từ', '彳 (Xích) (Bước chân trái, con đường, hành động)', '往 = 彳 (Xích: bước chân đi) + 主 (Chủ).', 'Chữ 往 (wǎng) mang nghĩa "hướng về", bộ chính 彳 (Xích); cấu tạo: 彳 (Xích: bước chân đi) + 主 (Chủ).', 'B: 你一直往前走，然后右拐就看到医院在你左边。', 'Nǐ yīzhí wǎng qián zǒu, ránhòu yòu guǎi jiù kàndào yīyuàn zài nǐ zuǒbian.', 'Bạn cứ đi thẳng, sau đó rẽ phải là sẽ nhìn thấy bệnh viện ở bên trái của', 20) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v6_21', 'lesson-6', '从', 'cóng', 'tùng', 'từ', 'Giới từ', '人/亻 (Nhân) (Con người, nhân loại, hành động)', '从 = 人 (Nhân) + 人 (Nhân: người này đi theo người kia).', 'Chữ 从 (cóng) mang nghĩa "từ", bộ chính 人/亻 (Nhân); cấu tạo: 人 (Nhân) + 人 (Nhân: người này đi theo người kia).', '从早上八点到下午五点，他要在公司工作。', 'Cóng zǎoshang bā diǎn dào xiàwǔ wǔ diǎn, tā yào zài gōngsī gōngzuò.', 'Anh ấy phải làm việc ở công ty từ 8 giờ sáng đến 5 giờ chiều.', 21) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v6_22', 'lesson-6', '一直', 'yīzhí', 'từ Hán ngữ', 'thẳng, một mạch', 'Phó từ', '一 (Nhất) (Số một, nền tảng, nét ngang cơ bản)', '一: Bộ 一 (Nhất - 1 nét ngang, số 1) • 直: 十 (Thập) + 目 (Mục: mắt nhìn thẳng) + 乚', 'Ghép 一 [bộ 一] + 直 [bộ 目] để nhớ từ 一直 (yīzhí): "thẳng, một mạch".', 'B: 你一直往前走，然后右拐就看到医院在你左边。', 'Nǐ yīzhí wǎng qián zǒu, ránhòu yòu guǎi jiù kàndào yīyuàn zài nǐ zuǒbian.', 'Bạn cứ đi thẳng, sau đó rẽ phải là sẽ nhìn thấy bệnh viện ở bên trái của', 22) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v6_23', 'lesson-6', '怎么', 'zěnme', 'ma', 'như thế nào', 'Đại từ', '心/忄 (Tâm) (Trái tim, tình cảm, suy nghĩ, tâm lý)', '怎: 乍 (Sạ) + 心 (Tâm: băn khoăn trong lòng) • 么: 丿 (Phiệt) + 厶 (Tư)', 'Ghép 怎 [bộ 心] + 么 [bộ 丿] để nhớ từ 怎么 (zěnme): "như thế nào".', 'A: 请问，去医院怎么走呢？', 'Qǐngwèn, qù yīyuàn zěnme zǒu ne?', 'Xin hỏi, đi đến bệnh viện như thế nào vậy?', 23) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v6_24', 'lesson-6', '那儿', 'nàr', 'na nhi', 'chỗ kia, chỗ ấy', 'Đại từ', '阝 (Phụ/Ấp) (Gò đất hoặc vùng đất, thành ấp)', '那: 𠃌 + 二 + 阝 (Ấp: vùng đất xa) • 儿: Bộ 儿 (Nhi - nét cong, chữ độc thể)', 'Ghép 那 [bộ 阝] + 儿 [bộ 儿] để nhớ từ 那儿 (nàr): "chỗ kia, chỗ ấy".', '不远，很近。从这儿到那儿有二百米。', 'Bù yuǎn，hěn jìn. Cóng zhèr dào nàr yǒu èrbǎi mǐ.', 'Không xa, rất gần. Từ đây đến đó khoảng 200 mét.', 24) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v6_25', 'lesson-6', '这儿', 'zhèr', 'giá nhi', 'chỗ này', 'Đại từ', '辶 (Sước) (Bước đi, di chuyển, khoảng cách)', '这: 文 (Văn) + 辶 (Sước: bước đi gần đây) • 儿: Bộ 儿 (Nhi - nét cong, chữ độc thể)', 'Ghép 这 [bộ 辶] + 儿 [bộ 儿] để nhớ từ 这儿 (zhèr): "chỗ này".', '离这儿远吗？', 'Lí zhèr yuǎn ma?', 'Cách đây có xa không?', 25) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v6_26', 'lesson-6', '每', 'měi', 'từ Hán ngữ', 'mỗi, từng', 'Đại từ', '毋/母 (Vô/Mẫu) (Mẹ, nuôi dưỡng, ngăn cấm)', '每 = 𠂉 + 母 (Mẫu: người mẹ sinh nở mỗi lần).', 'Chữ 每 (měi) mang nghĩa "mỗi, từng", bộ chính 毋/母 (Vô/Mẫu); cấu tạo: 𠂉 + 母 (Mẫu: người mẹ sinh nở mỗi lần).', '每一个学生都坐公共汽车上课。', 'Měi yígè xuésheng dōu zuò gōnggòng qìchē shàngkè.', 'Mỗi học sinh đều đi học bằng xe buýt.', 26) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v6_27', 'lesson-6', '都', 'dōu', 'đô', 'đều', 'Phó từ', '阝 (Phụ/Ấp) (Gò đất hoặc vùng đất, thành ấp)', '都 = 者 (Giả) + 阝 (Ấp: thành thị).', 'Chữ 都 (dōu) mang nghĩa "đều", bộ chính 阝 (Phụ/Ấp); cấu tạo: 者 (Giả) + 阝 (Ấp: thành thị).', '每一个学生都坐公共汽车上课。', 'Měi yígè xuésheng dōu zuò gōnggòng qìchē shàngkè.', 'Mỗi học sinh đều đi học bằng xe buýt.', 27) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v6_28', 'lesson-6', '就', 'jiù', 'từ Hán ngữ', 'là (dùng sau từ chỉ thời gian, số lượng từ, biểu thị thời gian sớm, số lượng ít, nhỏ tuổi, cuối câu thường dùng 了).', 'Phó từ', '尤/尢 (Uông) (Đặc biệt, khuyết tật)', '就 = 京 (Kinh: kinh đô) + 尤 (Uông).', 'Chữ 就 (jiù) mang nghĩa "là (dùng sau từ chỉ thời gian, số lượng từ, biểu thị thời gian sớm, số lượng ít, nhỏ tuổi, cuối câu thường dùng 了).", bộ chính 尤/尢 (Uông); cấu tạo: 京 (Kinh: kinh đô) + 尤 (Uông).', 'B: 你一直往前走，然后右拐就看到医院在你左边。', 'Nǐ yīzhí wǎng qián zǒu, ránhòu yòu guǎi jiù kàndào yīyuàn zài nǐ zuǒbian.', 'Bạn cứ đi thẳng, sau đó rẽ phải là sẽ nhìn thấy bệnh viện ở bên trái của', 28) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v6_29', 'lesson-6', '常', 'cháng', 'từ Hán ngữ', 'thường xuyên', 'Phó từ', '巾 (Cân) (Khăn vải, mũ nón, vải vóc)', '常 = 尚 (Thượng) + 巾 (Cân: mảnh vải mặc thường ngày).', 'Chữ 常 (cháng) mang nghĩa "thường xuyên", bộ chính 巾 (Cân); cấu tạo: 尚 (Thượng) + 巾 (Cân: mảnh vải mặc thường ngày).', '谢谢，你常到那儿买书吗？', 'Xièxie, nǐ cháng dào nàr mǎi shū ma?', 'Cảm ơn, bạn có hay đến đó mua sách không?', 29) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v6_30', 'lesson-6', '呢', 'ne', 'từ Hán ngữ', 'thế, nhé, nhỉ, cơ (dùng ở cuối câu trần thuật hoặc nghi vấn)', 'Trợ từ', '口 (Khẩu) (Miệng, ăn uống, lời nói, âm thanh phát ra)', '呢 = 口 (Khẩu: tiếng hỏi) + 尼 (Ni).', 'Chữ 呢 (ne) mang nghĩa "thế, nhé, nhỉ, cơ (dùng ở cuối câu trần thuật hoặc nghi vấn)", bộ chính 口 (Khẩu); cấu tạo: 口 (Khẩu: tiếng hỏi) + 尼 (Ni).', 'A: 请问，去医院怎么走呢？', 'Qǐngwèn, qù yīyuàn zěnme zǒu ne?', 'Xin hỏi, đi đến bệnh viện như thế nào vậy?', 30) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v6_31', 'lesson-6', '和', 'hé', 'từ Hán ngữ', 'và, với, cùng', 'Liên từ / Giới từ', '口 (Khẩu) (Miệng, ăn uống, lời nói, âm thanh phát ra)', '和 = 禾 (Hòa: cây lúa) + 口 (Khẩu: ai cũng có cơm ăn là hòa bình).', 'Chữ 和 (hé) mang nghĩa "và, với, cùng", bộ chính 口 (Khẩu); cấu tạo: 禾 (Hòa: cây lúa) + 口 (Khẩu: ai cũng có cơm ăn là hòa bình).', '书店在西边，在美术馆和电影院中间。', 'Shūdiàn zài xībian, zài měishùguǎn hé diànyǐngyuàn zhōngjiān.', 'Hiệu sách ở phía tây, nằm giữa bảo tàng mỹ thuật và rạp chiếu phim.', 31) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v6_32', 'lesson-6', '白色', 'báisè', 'bạch sắc', 'màu trắng', 'Danh từ', '白 (Bạch) (Màu trắng, sáng tỏ)', '白: Bộ 白 (Bạch - ánh sáng trắng, chữ độc thể) • 色: Bộ 色 (Sắc - ⺈ + 巴, sắc mặt, màu sắc)', 'Ghép 白 [bộ 白] + 色 [bộ 色] để nhớ từ 白色 (báisè): "màu trắng".', '你从这儿一直往东走，到十字路口往左拐，马路西边有一座白色的大楼，那就是书店。', 'Nǐ cóng zhèr yīzhí wǎng dōng zǒu, dào shízìlùkǒu wǎng zuǒ guǎi, mǎlù xībian yǒu yízuò báisè de dàlóu, nà jiùshì shūdiàn.', 'Bạn đi thẳng về phía đông từ đây, đến ngã tư thì rẽ trái, phía tây con đường có một tòa nhà lớn màu trắng, đó chính là hiệu sách.', 32) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v6_33', 'lesson-6', '周末', 'zhōumò', 'chu mạt', 'cuối tuần', 'Danh từ', '口 (Khẩu) (Miệng, ăn uống, lời nói, âm thanh phát ra)', '周: 冂 (Quynh) + 土 (Thổ) + 口 (Khẩu) • 末: 木 (Mộc) + 一 ở phần ngọn (chỉ ngọn cây, phần cuối)', 'Ghép 周 [bộ 口] + 末 [bộ 木] để nhớ từ 周末 (zhōumò): "cuối tuần".', '是，每个周末我都到那儿买书。', 'Shì, měi gè zhōumò wǒ dōu dào nàr mǎi shū.', 'Có, cuối tuần nào tôi cũng đến đó mua sách.', 33) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v6_34', 'lesson-6', '对', 'duì', 'từ Hán ngữ', 'đúng, phải', 'Tính từ', '寸 (Thốn) (Đo lường, bàn tay, phép tắc)', '对 = 又 (Hựu) + 寸 (Thốn: đối chiếu cân xứng).', 'Chữ 对 (duì) mang nghĩa "đúng, phải", bộ chính 寸 (Thốn); cấu tạo: 又 (Hựu) + 寸 (Thốn: đối chiếu cân xứng).', '这是关于“对”的常用句子。', 'Zhè shì guānyú ''duì'' de chángyòng jùzi.', 'Đây là câu ví dụ sử dụng từ ''对'' (đúng, phải).', 34) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order) VALUES ('g6_1', 'lesson-6', '1. 询问动作行为的方式 - Hỏi phương thức hành động của động tác', '怎 么 + Động từ', ' - Khi muốn hỏi phương thức hoặc phương pháp hành động của động tác, muốn đối phương nói rõ làm chuyện gì đó như thế nào ta sử dụng cấu trúc: A: 请问，去医院怎么走呢？ Qǐngwèn, qù yīyuàn zěnme zǒu ne? Xin hỏi, đi đến bệnh viện như thế nào vậy? B: 你一直往前走，然后右拐就看到', NULL, '[{"hanzi":"A: 请问，去医院怎么走呢？","pinyin":"Qǐngwèn, qù yīyuàn zěnme zǒu ne?","meaning":"Xin hỏi, đi đến bệnh viện như thế nào vậy?"},{"hanzi":"B: 你一直往前走，然后右拐就看到医院在你左边。","pinyin":"Nǐ yīzhí wǎng qián zǒu, ránhòu yòu guǎi jiù kàndào yīyuàn zài nǐ zuǒbian.","meaning":"Bạn cứ đi thẳng, sau đó rẽ phải là sẽ nhìn thấy bệnh viện ở bên trái của"}]'::jsonb, 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order) VALUES ('g6_2', 'lesson-6', '2. 从...... 到......: Từ… đến…', '从 + Từ chỉ địa điểm/thời gian + 到 + Từ chỉ địa điểm/thời gian', ' a. Khái niệm Cấu trúc “从...... 到……” biểu thị ý nghĩa “từ… đến…”, từ cái gì đến cái gì. Tân ngữ phía sau “从” và “到” thường thuộc cùng một trường từ vựng, có thể là từ chỉ thời gian, địa điểm hoặc một cột mốc nào đó. b. Cấu trúc 从我家到银行有二十公里。 Cóng wǒji', NULL, '[{"hanzi":"A: 你知道这个字怎么写吗？","pinyin":"Nǐ zhīdào zhè gè zì zěnme xiě ma?","meaning":"Cậu có biết chữ này viết như thế nào không?"},{"hanzi":"B: 我不知道。","pinyin":"Wǒ bù zhīdào.","meaning":"Mình không biết."}]'::jsonb, 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order) VALUES ('g6_3', 'lesson-6', '3. 每...... 都......: Mỗi/từng… đều…', 'Cấu trúc câu ngữ pháp trọng tâm', ' ●       Khái niệm Cấu trúc “每...... 都......” biểu thị không có ngoại lệ, tất cả đối tượng thuộc trường từ vựng của đại từ hay danh từ phía sau 每  đều có tính chất, trạng thái hoặc hành động phía sau 都. 每一个学生都坐公共汽车上课。 Měi yígè xuésheng dōu zuò gōnggò', NULL, '[{"hanzi":"A: 请问，超市怎么走呢？","pinyin":"Qǐngwèn, chāoshì zěnme zǒu ne?","meaning":"Xin hỏi đến siêu thị đi thế nào vậy?"},{"hanzi":"B: 你往左拐，然后一直往前走就到。","pinyin":"Nǐ wǎng zuǒ guǎi, ránhòu yīzhí wǎng qián","meaning":"zǒu jiù dào."}]'::jsonb, 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order;
INSERT INTO texts (id, lesson_id, title, description, sort_order) VALUES ('txt_6_1', 'lesson-6', 'Bài khoá #1: Hội thoại giáo trình — Hỏi đường', 'Hội thoại chuẩn giáo trình Bài 6. Từ vựng chưa học được chú thích phiên âm & nghĩa trong ngoặc.', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_6_1_1', 'txt_6_1', '马克', '张风，你知道书店在哪儿吗？', '张风，你知道书店在哪儿吗？', 'Zhāng Fēng, nǐ zhīdào shūdiàn zài nǎr ma?', 'Trương Phong, bạn có biết hiệu sách ở đâu không?', 1) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_6_1_2', 'txt_6_1', '张风', '书店在西边，在美术馆和电影院中间。', '书店在西边，在美术馆和电影院中间。', 'Shūdiàn zài xībian, zài měishùguǎn hé diànyǐngyuàn zhōngjiān.', 'Hiệu sách ở phía tây, nằm giữa bảo tàng mỹ thuật và rạp chiếu phim.', 2) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_6_1_3', 'txt_6_1', '马克', '离这儿远吗？', '离这儿远吗？', 'Lí zhèr yuǎn ma?', 'Cách đây có xa không?', 3) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_6_1_4', 'txt_6_1', '张风', '不远，很近。从这儿到那儿有二百米。', '不 (bù: không)远，很近。从这儿到那儿有二百 (bǎi: trăm)米。', 'Bù yuǎn，hěn jìn. Cóng zhèr dào nàr yǒu èrbǎi mǐ.', 'Không xa, rất gần. Từ đây đến đó khoảng 200 mét.', 4) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_6_1_5', 'txt_6_1', '马克', '怎么走呢？', '怎么走呢？', 'Zěnme zǒu ne?', 'Đi như thế nào vậy?', 5) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_6_1_6', 'txt_6_1', '张风', '你从这儿一直往东走，到十字路口往左拐，马路西边有一座白色的大楼，那就是书店。', '你从这儿一直往东 (dōng: phía Đông)走，到十字路口往左 (zuǒ: trái)拐，马路西边有一座白色的大 (dà: to, lớn)楼，那就是书店。', 'Nǐ cóng zhèr yīzhí wǎng dōng zǒu, dào shízìlùkǒu wǎng zuǒ guǎi, mǎlù xībian yǒu yízuò báisè de dàlóu, nà jiùshì shūdiàn.', 'Bạn đi thẳng về phía đông từ đây, đến ngã tư thì rẽ trái, phía tây con đường có một tòa nhà lớn màu trắng, đó chính là hiệu sách.', 6) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_6_1_7', 'txt_6_1', '马克', '谢谢，你常到那儿买书吗？', '谢谢，你常到那儿买书吗？', 'Xièxie, nǐ cháng dào nàr mǎi shū ma?', 'Cảm ơn, bạn có hay đến đó mua sách không?', 7) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_6_1_8', 'txt_6_1', '张风', '是，每个周末我都到那儿买书。', '是，每个周末我都到那儿买书。', 'Shì, měi gè zhōumò wǒ dōu dào nàr mǎi shū.', 'Có, cuối tuần nào tôi cũng đến đó mua sách.', 8) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_6_1_1', 'lesson-6', 'txt_6_1', 'listening', 'listening', '张风，你知道书店在哪儿吗？', NULL, 'Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Trương Phong, bạn có biết hiệu sách ở đâu không?","Không phải ngoài trời đang mưa à? Cậu dùng ô của tớ đi! (Khẳng định","Tạm biệt!","Sao bố vẫn chưa tan làm, con sắp đói chết rồi!"]'::jsonb, 0, 'Nội dung nghe được: 张风，你知道书店在哪儿吗？ (Zhāng Fēng, nǐ zhīdào shūdiàn zài nǎr ma?) → Trương Phong, bạn có biết hiệu sách ở đâu không?', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_6_1_2', 'lesson-6', 'txt_6_1', 'listening', 'listening', '书店在西边，在美术馆和电影院中间。', NULL, 'Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["是，每个周末我都到那儿买书。","怎么走呢？","每一个学生都坐 (zuò: ngồi)公共汽车 (gōnggòng qìchē: xe buýt)上课。","书店在西边，在美术馆和电影院中间。"]'::jsonb, 3, 'Câu vừa đọc: 书店在西边，在美术馆和电影院中间。 (Shūdiàn zài xībian, zài měishùguǎn hé diànyǐngyuàn zhōngjiān.) → Hiệu sách ở phía tây, nằm giữa bảo tàng mỹ thuật và rạp chiếu phim.', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_6_1_3', 'lesson-6', 'txt_6_1', 'listening', 'listening', '离这儿远吗？', NULL, 'Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Cách đây có xa không?","Anh ta mời tôi ngày mai tới nhà dùng cơm.","tôi của sau này, tôi của tương lai","Lớp cậu có bao nhiêu học sinh?"]'::jsonb, 0, 'Nội dung nghe được: 离这儿远吗？ (Lí zhèr yuǎn ma?) → Cách đây có xa không?', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_6_1_4', 'lesson-6', 'txt_6_1', 'listening', 'listening', '不远，很近。从这儿到那儿有二百米。', NULL, 'Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["怎么走呢？","张风，你知道书店在哪儿吗？","A: 请问 (qǐngwèn: xin hỏi)，去医院 (yīyuàn: bệnh viện)怎么走呢？","不 (bù: không)远，很近。从这儿到那儿有二百 (bǎi: trăm)米。"]'::jsonb, 3, 'Câu vừa đọc: 不远，很近。从这儿到那儿有二百米。 (Bù yuǎn，hěn jìn. Cóng zhèr dào nàr yǒu èrbǎi mǐ.) → Không xa, rất gần. Từ đây đến đó khoảng 200 mét.', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO texts (id, lesson_id, title, description, sort_order) VALUES ('txt_6_2', 'lesson-6', 'Bài nghe tổng hợp: Ôn tập lũy tiến (Bài 1 – Bài 6)', 'Kết hợp từ vựng & mẫu câu đã học từ Bài 1 đến Bài 5 cùng trọng tâm Bài 6 để củng cố phản xạ nghe.', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_6_2_1', 'txt_6_2', 'Ôn Bài 5', '你昨天去学校了吗？', '你昨天去学校了吗？', 'Nǐ zuótiān qù xuéxiào le ma?', 'Hôm qua cậu đã đến trường chưa?', 1) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_6_2_2', 'txt_6_2', 'Bài 6', '张风，你知道书店在哪儿吗？', '张风，你知道书店在哪儿吗？', 'Zhāng Fēng, nǐ zhīdào shūdiàn zài nǎr ma?', 'Trương Phong, bạn có biết hiệu sách ở đâu không?', 2) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_6_2_3', 'txt_6_2', 'Ôn Bài 3', '他是谁？', '他是谁？', 'Tā shì shéi?', 'Anh ấy là ai?', 3) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_6_2_4', 'txt_6_2', 'Bài 6', '书店在西边，在美术馆和电影院中间。', '书店在西边，在美术馆和电影院中间。', 'Shūdiàn zài xībian, zài měishùguǎn hé diànyǐngyuàn zhōngjiān.', 'Hiệu sách ở phía tây, nằm giữa bảo tàng mỹ thuật và rạp chiếu phim.', 4) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_6_2_5', 'txt_6_2', 'Ôn Bài 1', '你是日明吗？', '你是日明吗？', 'Nǐ shì Rìmíng ma?', 'Cậu là Nhật Minh phải không?', 5) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_6_2_6', 'txt_6_2', 'Bài 6', '离这儿远吗？', '离这儿远吗？', 'Lí zhèr yuǎn ma?', 'Cách đây có xa không?', 6) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_6_2_7', 'txt_6_2', 'Ôn Bài 4', '食堂左边', '食堂左边', 'shítáng zuǒbian', 'Phía bên trái nhà ăn', 7) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_6_2_8', 'txt_6_2', 'Bài 6', '怎么走呢？', '怎么走呢？', 'Zěnme zǒu ne?', 'Đi như thế nào vậy?', 8) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_6_2_1', 'lesson-6', 'txt_6_2', 'listening', 'listening', '你昨天去学校了吗？', NULL, '[Ôn tập Bài 5] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Năm nay cháu mấy tuổi rồi (Hỏi trẻ em dưới mười tuổi)","người Trung Quốc","Tôi đợi các bạn ở cổng trường.","Hôm qua cậu đã đến trường chưa?"]'::jsonb, 3, 'Nội dung nghe được: 你昨天去学校了吗？ (Nǐ zuótiān qù xuéxiào le ma?) → Hôm qua cậu đã đến trường chưa?', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_6_2_2', 'lesson-6', 'txt_6_2', 'listening', 'listening', '张风，你知道书店在哪儿吗？', NULL, '[Bài 6] Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["B: 你一直往前 (qián: trước)走，然后 (ránhòu: đầu tiên... sau đó...)右 (yòu: phải)拐就看到医院 (yīyuàn: bệnh viện)在你左边。","张风，你知道书店在哪儿吗？","B: 我打算 (dǎsuan: dự định)坐 (zuò: ngồi)公共汽车 (gōnggòng qìchē: xe buýt)。","离这儿远吗？"]'::jsonb, 1, 'Câu vừa đọc: 张风，你知道书店在哪儿吗？ (Zhāng Fēng, nǐ zhīdào shūdiàn zài nǎr ma?) → Trương Phong, bạn có biết hiệu sách ở đâu không?', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_6_2_3', 'lesson-6', 'txt_6_2', 'listening', 'listening', '他是谁？', NULL, '[Ôn tập Bài 3] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Anh ấy là ai?","Ngày mai có lẽ là ngày nắng.","Bọn họ chỉ quan tâm đến bản thân mình mà thôi.","Lúc đó, người con gái ấy khóc không ngớt."]'::jsonb, 0, 'Nội dung nghe được: 他是谁？ (Tā shì shéi?) → Anh ấy là ai?', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_6_2_4', 'lesson-6', 'txt_6_2', 'listening', 'listening', '书店在西边，在美术馆和电影院中间。', NULL, '[Bài 6] Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["书店在西边，在美术馆和电影院中间。","图书馆南边是什么地方？","B: 我不 (bù: không)知道。","到前面那个十字路口往右 (yòu: phải)拐。"]'::jsonb, 0, 'Câu vừa đọc: 书店在西边，在美术馆和电影院中间。 (Shūdiàn zài xībian, zài měishùguǎn hé diànyǐngyuàn zhōngjiān.) → Hiệu sách ở phía tây, nằm giữa bảo tàng mỹ thuật và rạp chiếu phim.', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_6_2_5', 'lesson-6', 'txt_6_2', 'listening', 'listening', '你是日明吗？', NULL, '[Ôn tập Bài 1] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Cậu là Nhật Minh phải không?","đất nước (quốc gia) của chúng tôi","Tối qua ngủ có ngon không?","Có khả năng ông chủ quên hôm nay có cuộc họp rồi."]'::jsonb, 0, 'Nội dung nghe được: 你是日明吗？ (Nǐ shì Rìmíng ma?) → Cậu là Nhật Minh phải không?', 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO texts (id, lesson_id, title, description, sort_order) VALUES ('txt_6_3', 'lesson-6', 'Bài khoá mở rộng: Chỉ đường đến hiệu sách (Mở rộng)', 'Hội thoại tình huống mới xây dựng dựa trên từ vựng và ngữ pháp Bài 6 (không trùng lặp nguyên văn giáo trình).', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_6_3_1', 'txt_6_3', 'Annie', '请问，电影院附近有书店吗？', '请问 (qǐngwèn: xin hỏi)，电影院附近有书店吗？', 'Qǐngwèn, diànyǐngyuàn fùjìn yǒu shūdiàn ma?', 'Xin hỏi quanh rạp chiếu phim có hiệu sách không?', 1) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_6_3_2', 'txt_6_3', 'Phong', '有，书店在电影院和美术馆中间，离这儿只有三百米。', '有，书店在电影院和美术馆中间，离这儿只 (zhī: con)有三百 (bǎi: trăm)米。', 'Yǒu, shūdiàn zài diànyǐngyuàn hé měishùguǎn zhōngjiān, lí zhèr zhǐyǒu sānbǎi mǐ.', 'Có, hiệu sách nằm giữa rạp chiếu phim và bảo tàng mỹ thuật, cách đây chỉ 300 mét.', 2) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_6_3_3', 'txt_6_3', 'Annie', '从这儿到书店怎么走？', '从这儿到书店怎么走？', 'Cóng zhèr dào shūdiàn zěnme zǒu?', 'Từ đây đến hiệu sách đi như thế nào?', 3) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_6_3_4', 'txt_6_3', 'Phong', '你一直往北走，到十字路口往右拐就到了。', '你一直往北 (běi: phía Bắc)走，到十字路口往右 (yòu: phải)拐就到了。', 'Nǐ yīzhí wǎng běi zǒu, dào shízìlùkǒu wǎng yòu guǎi jiù dào le.', 'Bạn cứ đi thẳng về phía bắc, đến ngã tư rẽ phải là tới.', 4) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_6_3_1', 'lesson-6', 'txt_6_3', 'listening', 'listening', '请问，电影院附近有书店吗？ 有，书店在电影院和美术馆中间，离这儿只有三百米。 从这儿到书店怎么走？ 你一直往北走，到十字路口往右拐就到了。', NULL, '[Nghe hiểu tình huống mới] Để đến được hiệu sách từ chỗ hiện tại, Annie cần đi hướng nào?', '["Đi thẳng hướng bắc rồi rẽ phải ở ngã tư","Đi hướng nam rồi rẽ trái","Quay lại cổng trường","Đi xe buýt hai tiếng"]'::jsonb, 0, 'Phong chỉ: ''一直往北走，到十字路口往右拐'' (đi thẳng hướng bắc, đến ngã tư rẽ phải).', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_6_3_2', 'lesson-6', 'txt_6_3', 'listening', 'listening', '请问，电影院附近有书店吗？', NULL, '[Mở rộng] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Con ăn nhiều rau chút, có lợi cho sức khỏe!","Chào buổi tối!","Lúc cô giáo giảng bài thì tôi đang tra từ mới.","Xin hỏi quanh rạp chiếu phim có hiệu sách không?"]'::jsonb, 3, 'Nội dung nghe được: 请问，电影院附近有书店吗？ (Qǐngwèn, diànyǐngyuàn fùjìn yǒu shūdiàn ma?) → Xin hỏi quanh rạp chiếu phim có hiệu sách không?', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_6_3_3', 'lesson-6', 'txt_6_3', 'listening', 'listening', '有，书店在电影院和美术馆中间，离这儿只有三百米。', NULL, '[Mở rộng] Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["A: 你知道这个字 (zì: chữ)怎么写 (xiě: viết)吗？","有，书店在电影院和美术馆中间，离这儿只 (zhī: con)有三百 (bǎi: trăm)米。","B: 你一直往前 (qián: trước)走，然后 (ránhòu: đầu tiên... sau đó...)右 (yòu: phải)拐就看到医院 (yīyuàn: bệnh viện)在你左边。","怎么走呢？"]'::jsonb, 1, 'Câu vừa đọc: 有，书店在电影院和美术馆中间，离这儿只有三百米。 (Yǒu, shūdiàn zài diànyǐngyuàn hé měishùguǎn zhōngjiān, lí zhèr zhǐyǒu sānbǎi mǐ.) → Có, hiệu sách nằm giữa rạp chiếu phim và bảo tàng mỹ thuật, cách đây chỉ 300 mét.', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_6_3_4', 'lesson-6', 'txt_6_3', 'listening', 'listening', '从这儿到书店怎么走？', NULL, '[Mở rộng] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Cậu là ai thế?","Từ đây đến hiệu sách đi như thế nào?","Anh ấy đọc sách trong thư viện.","Con nên uống nước lọc nhiều hơn và uống ít nước ngọt thôi!"]'::jsonb, 1, 'Nội dung nghe được: 从这儿到书店怎么走？ (Cóng zhèr dào shūdiàn zěnme zǒu?) → Từ đây đến hiệu sách đi như thế nào?', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss6_1', 'lesson-6', '电影院在美术馆的东边', '[Mở rộng] Rạp chiếu phim nằm ở phía đông bảo tàng mỹ thuật.', 'Diànyǐngyuàn zài měishùguǎn de dōngbian.', '["电影院","在","美术馆","的","东边"]'::jsonb, NULL, 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss6_2', 'lesson-6', '从宿舍到食堂怎么走', '[Mở rộng] Từ ký túc xá đến nhà ăn đi như thế nào?', 'Cóng sùshè dào shítáng zěnme zǒu?', '["从","宿舍","到","食堂","怎么","走"]'::jsonb, NULL, 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss6_3', 'lesson-6', '张风你知道书店在哪儿吗', 'Trương Phong, bạn có biết hiệu sách ở đâu không?', 'Zhāng Fēng, nǐ zhīdào shūdiàn zài nǎr ma?', '["张风","你","知道","书店","在","哪儿吗"]'::jsonb, NULL, 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
