INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss6_5', 'lesson-6', '我的朋友在食堂吃饭', '[Ôn tập Bài 4] Bạn của tôi đang ăn cơm ở nhà ăn.', 'Wǒ de péngyou zài shítáng chīfàn.', '["我的","朋友","在","食堂","吃","饭"]'::jsonb, NULL, 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
