INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss6_exp_1', 'lesson-6', '书店在西边在美术馆和电影院中间', 'Hiệu sách ở phía tây, nằm giữa bảo tàng mỹ thuật và rạp chiếu phim.', 'Shūdiàn zài xībian, zài měishùguǎn hé diànyǐngyuàn zhōngjiān.', '["书店","在","西边","在","美术馆","和","电影院","中间"]'::jsonb, NULL, 7) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss6_exp_2', 'lesson-6', '不远很近从这儿到那儿有二百米', 'Không xa, rất gần. Từ đây đến đó khoảng 200 mét.', 'Bù yuǎn，hěn jìn. Cóng zhèr dào nàr yǒu èrbǎi mǐ.', '["不","远","很","近","从","这儿","到","那儿","有","二","百","米"]'::jsonb, NULL, 8) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss6_exp_3', 'lesson-6', '怎么走呢', 'Đi như thế nào vậy?', 'Zěnme zǒu ne?', '["怎么","走","呢"]'::jsonb, NULL, 9) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss6_exp_4', 'lesson-6', '你从这儿一直往东走到十字路口往左拐马路西边有一座白色的大楼那就是书店', 'Bạn đi thẳng về phía đông từ đây, đến ngã tư thì rẽ trái, phía tây con đường có một tòa nhà lớn màu trắng, đó chính là hiệu sách.', 'Nǐ cóng zhèr yīzhí wǎng dōng zǒu, dào shízìlùkǒu wǎng zuǒ guǎi, mǎlù xībian yǒu yízuò báisè de dàlóu, nà jiùshì shūdiàn.', '["你","从","这儿","一直","往","东","走","到","十字路口","往","左","拐","马路","西边","有","一","座","白色","的","大","楼","那","就","是","书店"]'::jsonb, NULL, 10) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
