INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss6_exp_6', 'lesson-6', '是每个周末我都到那儿买书', 'Có, cuối tuần nào tôi cũng đến đó mua sách.', 'Shì, měi gè zhōumò wǒ dōu dào nàr mǎi shū.', '["是","每","个","周末","我","都","到","那儿","买","书"]'::jsonb, NULL, 12) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
