INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr6_vi_exp_6', 'lesson-6', 'vi_to_zh', 'Bạn đi thẳng về phía đông từ đây, đến ngã tư thì rẽ trái, phía tây con đường có một tòa nhà lớn màu trắng, đó chính là hiệu sách.', NULL, NULL, '你从这儿一直往东走，到十字路口往左拐，马路西边有一座白色的大楼，那就是书店。', NULL, 'nǐ cóng zhèr yīzhí wǎng dōng zǒu dào shízìlùkǒu wǎng zuǒ guǎi mǎlù xībian yǒu yízuò báisè de dàlóu nà jiùshì shūdiàn', '[]'::jsonb, 'Gợi ý Pinyin: Nǐ cóng zhèr yīzhí wǎng dōng zǒu, dào shízìlùkǒu wǎng zuǒ guǎi, mǎlù xībian yǒu yízuò báisè de dàlóu, nà jiùshì shūdiàn.', 'Bạn đi thẳng về phía đông từ đây, đến ngã tư thì rẽ trái, phía tây con đường có một tòa nhà lớn màu trắng, đó chính là hiệu sách. → 你从这儿一直往东走，到十字路口往左拐，马路西边有一座白色的大楼，那就是书店。 (Nǐ cóng zhèr yīzhí wǎng dōng zǒu, dào shízìlùkǒu wǎng zuǒ guǎi, mǎlù xībian yǒu yízuò báisè de dàlóu, nà jiùshì shūdiàn.)', 10) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
