INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr6_zh_exp_2', 'lesson-6', 'zh_to_vi', '从早上八点到下午五点，他要在公司工作。', '从早上八点到下午五点，他要在公司工作。', 'Cóng zǎoshang bā diǎn dào xiàwǔ wǔ diǎn, tā yào zài gōngsī gōngzuò.', NULL, 'Anh ấy phải làm việc ở công ty từ 8 giờ sáng đến 5 giờ chiều.', NULL, '["anh","ấy","phải","làm","việc","công","ty","từ","giờ","sáng","đến","giờ","chiều"]'::jsonb, 'Pinyin: Cóng zǎoshang bā diǎn dào xiàwǔ wǔ diǎn, tā yào zài gōngsī gōngzuò.', '从早上八点到下午五点，他要在公司工作。 (Cóng zǎoshang bā diǎn dào xiàwǔ wǔ diǎn, tā yào zài gōngsī gōngzuò.) nghĩa là: Anh ấy phải làm việc ở công ty từ 8 giờ sáng đến 5 giờ chiều.', 20) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
