INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr6_zh_exp_7', 'lesson-6', 'zh_to_vi', '你一直往前走，然后右拐就看到医院在你左边。', '你一直往前走，然后右拐就看到医院在你左边。', 'Nǐ yīzhí wǎng qián zǒu, ránhòu yòu guǎi jiù kàndào yīyuàn zài nǐ zuǒbian.', NULL, 'Bạn cứ đi thẳng, sau đó rẽ phải là sẽ nhìn thấy bệnh viện ở bên trái của', NULL, '["bạn","cứ","đi","thẳng","sau","đó","rẽ","phải","là","sẽ","nhìn","thấy","bệnh","viện","bên","trái","của"]'::jsonb, 'Pinyin: Nǐ yīzhí wǎng qián zǒu, ránhòu yòu guǎi jiù kàndào yīyuàn zài nǐ zuǒbian.', '你一直往前走，然后右拐就看到医院在你左边。 (Nǐ yīzhí wǎng qián zǒu, ránhòu yòu guǎi jiù kàndào yīyuàn zài nǐ zuǒbian.) nghĩa là: Bạn cứ đi thẳng, sau đó rẽ phải là sẽ nhìn thấy bệnh viện ở bên trái của', 25) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
