INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct6_25', 'lesson-6', NULL, 'comprehensive_test', 'listening', '请问，电影院附近有书店吗？ 有，书店在电影院和美术馆中间，离这儿只有三百米。 从这儿到书店怎么走？ 你一直往北走，到十字路口往右拐就到了。', NULL, 'Để đến được hiệu sách từ chỗ hiện tại, Annie cần đi hướng nào?', '["Đi thẳng hướng bắc rồi rẽ phải ở ngã tư","Đi hướng nam rồi rẽ trái","Quay lại cổng trường","Đi xe buýt hai tiếng"]'::jsonb, 0, 'Phong chỉ: ''一直往北走，到十字路口往右拐'' (đi thẳng hướng bắc, đến ngã tư rẽ phải).', 25) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
