INSERT INTO lessons (id, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id) VALUES ('lesson-7', 'Bài 7: Đồ dùng học tập của tôi - Đơn nguyên 1: Trường học', 'Bài 7', 'Đơn nguyên 1: Trường học', 'Đồ dùng học tập (bút, thước, vở, cặp sách), màu sắc, lượng từ và trợ từ kết cấu 的.', '2026-11-14'::date, 7, TRUE, NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, date_added = EXCLUDED.date_added, sort_order = EXCLUDED.sort_order, is_system = TRUE, updated_at = NOW();
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v7_1', 'lesson-7', '书包', 'shūbāo', 'thư bao', 'cặp sách, balo', 'Danh từ', '乙 (Ất) (Uốn cong, số thứ tự, chồi non)', '书: Nét gấp 乛 + 乛 + 丨 + 丶 (cuốn sách, bút viết) • 包: 勹 (Bao: bọc lại) + 巳 (Tỵ: thai nhi bên trong)', 'Ghép 书 [bộ 乙] + 包 [bộ 勹] để nhớ từ 书包 (shūbāo): "cặp sách, balo".', '这个书包', 'zhègè shūbāo', 'chiếc cặp này', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v7_2', 'lesson-7', '圆珠笔', 'yuánzhūbǐ', 'từ Hán ngữ', 'bút bi', 'Danh từ', '囗 (Vi) (Vây quanh, không gian kín, lãnh thổ)', '圆: 囗 (Vi: vòng tròn ngoài) + 员 (Viên) • 珠: 王 (Ngọc: viên ngọc) + 朱 (Chu) • 笔: ⺮ (Trúc: thân bút bằng tre) + 毛 (Mao: đầu lông bút)', 'Ghép 圆 [bộ 囗] + 珠 [bộ 王] + 笔 [bộ 竹] để nhớ từ 圆珠笔 (yuánzhūbǐ): "bút bi".', '她的圆珠笔', 'tā de yuánzhūbǐ', 'bút bi của cô ấy', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v7_3', 'lesson-7', '尺子', 'chǐzi', 'từ Hán ngữ', 'thước kẻ', 'Danh từ', '尸 (Thi) (Thân người, mái nhà, nơi ở)', '尺: Bộ 尸 (Thi) + nét mác (cây thước đo xưa) • 子: Bộ 子 (Tử - đứa trẻ dang tay, chữ độc thể)', 'Ghép 尺 [bộ 尸] + 子 [bộ 子] để nhớ từ 尺子 (chǐzi): "thước kẻ".', '他的尺子', 'tā de chǐzi', 'cây thước kẻ của anh ấy', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v7_4', 'lesson-7', '笔记本', 'bǐjìběn', 'từ Hán ngữ', 'vở ghi, sổ ghi', 'Danh từ', '竹/⺮ (Trúc) (Tre trúc, đồ đan, sách vở)', '笔: ⺮ (Trúc: thân bút bằng tre) + 毛 (Mao: đầu lông bút) • 记: 讠 (Ngôn: lời nói) + 己 (Kỷ: tự mình ghi nhớ) • 本: 木 (Mộc: cây) + nét gạch ngang 一 dưới gốc (gốc rễ, quyển sách)', 'Ghép 笔 [bộ 竹] + 记 [bộ 讠] + 本 [bộ 木] để nhớ từ 笔记本 (bǐjìběn): "vở ghi, sổ ghi".', '我想去商店买两支圆珠笔、一把尺子和三本笔记本。你想去吗？', 'Wǒ xiǎng qù shāngdiàn mǎi liǎng zhī yuánzhūbǐ, yī bǎ chǐzi hé sān běn bǐjìběn. Nǐ xiǎng qù ma?', 'Tôi muốn đi cửa hàng mua hai cây bút bi, một cây thước kẻ và ba quyển vở ghi chép. Bạn có muốn đi không?', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v7_5', 'lesson-7', '铅笔', 'qiānbǐ', 'từ Hán ngữ', 'bút chì', 'Danh từ', '金/钅 (Kim) (Kim loại, tiền bạc, đồ dùng kim khí)', '铅: 钅 (Kim: kim loại chì) + 沿 (biến thể: 几 + 口) • 笔: ⺮ (Trúc: thân bút bằng tre) + 毛 (Mao: đầu lông bút)', 'Ghép 铅 [bộ 钅] + 笔 [bộ 竹] để nhớ từ 铅笔 (qiānbǐ): "bút chì".', '三支铅笔', 'sān zhī qiānbǐ', 'ba cây bút chì', 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v7_6', 'lesson-7', '词典', 'cídiǎn', 'từ Hán ngữ', 'từ điển', 'Danh từ', '言/讠 (Ngôn) (Lời nói, ngôn ngữ, giao tiếp)', '词: 讠 (Ngôn: ngôn từ) + 司 (Tư) • 典: 曲 (Khúc: quyển sách quý) + 八 (Bát: giá đỡ sách)', 'Ghép 词 [bộ 讠] + 典 [bộ 八] để nhớ từ 词典 (cídiǎn): "từ điển".', '汉语词典', 'Hànyǔ cídiǎn', 'từ điển tiếng Trung', 6) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v7_7', 'lesson-7', '汉语', 'Hànyǔ', 'ngữ', 'tiếng Trung Quốc', 'Danh từ', '水/氵 (Thủy) (Nước, chất lỏng, sông ngòi)', '汉: 氵 (Thủy: sông Hán) + 又 (Hựu) • 语: 讠 (Ngôn: lời nói) + 吾 (Ngô)', 'Ghép 汉 [bộ 氵] + 语 [bộ 讠] để nhớ từ 汉语 (Hànyǔ): "tiếng Trung Quốc".', '汉语老师', 'Hànyǔ lǎoshī', 'giáo viên tiếng Trung', 7) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v7_8', 'lesson-7', '商店', 'shāngdiàn', 'thương điếm', 'cửa hàng', 'Danh từ', '口 (Khẩu) (Miệng, ăn uống, lời nói, âm thanh phát ra)', '商: 亠 + 丷 + 冂 + 八 + 口 (buôn bán, thương lượng) • 店: 广 (Nghiễm: mái hiên) + 占 (Chiếm: quầy hàng)', 'Ghép 商 [bộ 口] + 店 [bộ 广] để nhớ từ 商店 (shāngdiàn): "cửa hàng".', '我想去商店买两支圆珠笔、一把尺子和三本笔记本。你想去吗？', 'Wǒ xiǎng qù shāngdiàn mǎi liǎng zhī yuánzhūbǐ, yī bǎ chǐzi hé sān běn bǐjìběn. Nǐ xiǎng qù ma?', 'Tôi muốn đi cửa hàng mua hai cây bút bi, một cây thước kẻ và ba quyển vở ghi chép. Bạn có muốn đi không?', 8) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v7_9', 'lesson-7', '今天', 'jīntiān', 'kim thiên', 'hôm nay', 'Danh từ', '人/亻 (Nhân) (Con người, nhân loại, hành động)', '今: 人 (Nhân: mái che) + 丶 + 乛 (hiện tại hôm nay) • 天: 一 (Nhất: bầu trời cao) + 大 (Đại: con người dang tay)', 'Ghép 今 [bộ 人] + 天 [bộ 大] để nhớ từ 今天 (jīntiān): "hôm nay".', '马克，今天下午你去哪儿？', 'Mǎkè, jīntiān xiàwǔ nǐ qù nǎr?', 'Mark, chiều nay bạn đi đâu?', 9) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v7_10', 'lesson-7', '蓝色', 'lán sè', 'lam sắc', 'màu xanh lam', 'Danh từ', '艹 (Thảo) (Cỏ cây, hoa lá, thảo mộc)', '蓝: 艹 (Thảo: cây chàm nhuộm xanh) + 监 (Giám) • 色: Bộ 色 (Sắc - ⺈ + 巴, sắc mặt, màu sắc)', 'Ghép 蓝 [bộ 艹] + 色 [bộ 色] để nhớ từ 蓝色 (lán sè): "màu xanh lam".', '哇，真好看啊！你买的那家商店有蓝色的书包吗？', 'Wa, zhēn hǎokàn a! Nǐ mǎi de nà jiā shāngdiàn yǒu lán sè de shūbāo ma?', 'Chà, đẹp quá đi mất! Cửa hàng bạn mua có cặp sách màu xanh dương không?', 10) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v7_11', 'lesson-7', '黄色', 'huángsè', 'hoàng sắc', 'màu vàng', 'Danh từ', '黄 (Hoàng) (Màu vàng)', '黄: Bộ 黄 (Hoàng - màu vàng đất) • 色: Bộ 色 (Sắc - ⺈ + 巴, sắc mặt, màu sắc)', 'Ghép 黄 [bộ 黄] + 色 [bộ 色] để nhớ từ 黄色 (huángsè): "màu vàng".', '有啊，还有黄色和白色的书包。', 'Yǒu a, hái yǒu huángsè hé báisè de shūbāo.', 'Có chứ, còn có cả cặp màu vàng và màu trắng nữa.', 11) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v7_12', 'lesson-7', '等', 'děng', 'từ Hán ngữ', 'đợi', 'Động từ', '竹/⺮ (Trúc) (Tre trúc, đồ đan, sách vở)', '等 = ⺮ (Trúc: thẻ tre ghi thứ bậc) + 寺 (Tự).', 'Chữ 等 (děng) mang nghĩa "đợi", bộ chính 竹/⺮ (Trúc); cấu tạo: ⺮ (Trúc: thẻ tre ghi thứ bậc) + 寺 (Tự).', '那今天下午四点我在学校门口等你。我们一起去，好吗？', 'Nà jīntiān xiàwǔ sìdiǎn wǒ zài xuéxiào ménkǒu děng nǐ. Wǒmen yīqǐ qù, hǎo ma?', 'Vậy chiều nay 4 giờ tôi đợi bạn ở cổng trường. Chúng ta cùng đi nhé, được không?', 12) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v7_13', 'lesson-7', '觉得', 'juéde', 'từ Hán ngữ', 'thấy, cảm thấy', 'Động từ', '见 (Kiến) (Nhìn thấy, gặp gỡ)', '觉: ⺍ + 冖 (Mịch) + 见 (Kiến: nhận thấy, cảm giác) • 得: 彳 (Xích: bước đi) + 旦 (Đán) + 寸 (Thốn: tay nắm được)', 'Ghép 觉 [bộ 见] + 得 [bộ 彳] để nhớ từ 觉得 (juéde): "thấy, cảm thấy".', '小白，你觉得我今天买的书包怎么样？', 'Xiǎobái, nǐ juéde wǒ jīntiān mǎi de shūbāo zěnmeyàng?', 'Tiểu Bạch, bạn thấy chiếc cặp sách hôm nay tôi mua thế nào?', 13) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v7_14', 'lesson-7', '好看', 'hǎokàn', 'hảo khán', 'đẹp, dễ nhìn, hay, thú vị', 'Tính từ', '女 (Nữ) (Phụ nữ, gia đình, tình cảm)', '好: 女 (Nữ: người mẹ) + 子 (Tử: đứa con) • 看: 手 (Thủ biến thể: tay che trán) + 目 (Mục: mắt nhìn)', 'Ghép 好 [bộ 女] + 看 [bộ 目] để nhớ từ 好看 (hǎokàn): "đẹp, dễ nhìn, hay, thú vị".', '哇，真好看啊！你买的那家商店有蓝色的书包吗？', 'Wa, zhēn hǎokàn a! Nǐ mǎi de nà jiā shāngdiàn yǒu lán sè de shūbāo ma?', 'Chà, đẹp quá đi mất! Cửa hàng bạn mua có cặp sách màu xanh dương không?', 14) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v7_15', 'lesson-7', '漂亮', 'piàoliang', 'từ Hán ngữ', 'đẹp, xinh đẹp', 'Tính từ', '水/氵 (Thủy) (Nước, chất lỏng, sông ngòi)', '漂: 氵 (Thủy: nước) + 票 (Phiếu) • 亮: 亠 + 口 + 冖 + 几 (sáng tỏ, đẹp đẽ)', 'Ghép 漂 [bộ 氵] + 亮 [bộ 亠] để nhớ từ 漂亮 (piàoliang): "đẹp, xinh đẹp".', '后面的姑娘很漂亮。', 'Hòumian de gūniang hěn piàoliang.', 'Cô gái ở phía sau rất xinh đẹp.', 15) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v7_16', 'lesson-7', '家', 'jiā', 'gia', 'ngôi, hiệu, tiệm, quán (lượng từ của cửa hàng, công ty,...)', 'Lượng từ', '宀 (Miên) (Mái nhà, che chở, nơi ở)', '家 = 宀 (Miên: mái nhà) + 豕 (Thỉ: lợn nuôi dưới mái nhà).', 'Chữ 家 (jiā) mang nghĩa "ngôi, hiệu, tiệm, quán (lượng từ của cửa hàng, công ty,...)", bộ chính 宀 (Miên); cấu tạo: 宀 (Miên: mái nhà) + 豕 (Thỉ: lợn nuôi dưới mái nhà).', '我们国家', 'wǒmen guójiā', 'đất nước (quốc gia) của chúng tôi', 16) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v7_17', 'lesson-7', '支', 'zhī', 'từ Hán ngữ', 'cái, chiếc, cây (lượng từ của cái bút,...)', 'Lượng từ', '支 (Chi) (Nhành cây, nâng đỡ, chi trả)', '支 = 十 (Thập) + 又 (Hựu: tay cầm cành tre).', 'Chữ 支 (zhī) mang nghĩa "cái, chiếc, cây (lượng từ của cái bút,...)", bộ chính 支 (Chi); cấu tạo: 十 (Thập) + 又 (Hựu: tay cầm cành tre).', '三支铅笔', 'sān zhī qiānbǐ', 'ba cây bút chì', 17) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v7_18', 'lesson-7', '本', 'běn', 'từ Hán ngữ', 'cuốn; vở; quyển; tập (dùng cho sách vở sổ sách)', 'Lượng từ', '木 (Mộc) (Cây cối, gỗ, thực vật)', '本 = 木 (Mộc: cây) + nét gạch ngang 一 dưới gốc (gốc rễ, quyển sách).', 'Chữ 本 (běn) mang nghĩa "cuốn; vở; quyển; tập (dùng cho sách vở sổ sách)", bộ chính 木 (Mộc); cấu tạo: 木 (Mộc: cây) + nét gạch ngang 一 dưới gốc (gốc rễ, quyển sách).', '这本书', 'zhè běn shū', 'quyển sách này', 18) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v7_19', 'lesson-7', '把', 'bǎ', 'từ Hán ngữ', 'chiếc, cái ( lượng từ của cái thước kẻ)', 'Lượng từ', '手/扌 (Thủ) (Bàn tay, động tác, thao tác)', '把 = 扌 (Thủ: bàn tay) + 巴 (Ba: nắm giữ).', 'Chữ 把 (bǎ) mang nghĩa "chiếc, cái ( lượng từ của cái thước kẻ)", bộ chính 手/扌 (Thủ); cấu tạo: 扌 (Thủ: bàn tay) + 巴 (Ba: nắm giữ).', '我想去商店买两支圆珠笔、一把尺子和三本笔记本。你想去吗？', 'Wǒ xiǎng qù shāngdiàn mǎi liǎng zhī yuánzhūbǐ, yī bǎ chǐzi hé sān běn bǐjìběn. Nǐ xiǎng qù ma?', 'Tôi muốn đi cửa hàng mua hai cây bút bi, một cây thước kẻ và ba quyển vở ghi chép. Bạn có muốn đi không?', 19) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v7_20', 'lesson-7', '太', 'tài', 'thái', 'quá, lắm', 'Phó từ', '大 (Đại) (To lớn, vĩ đại)', '太 = 大 (Đại: to lớn) + 丶 (Chủ: quá mức).', 'Chữ 太 (tài) mang nghĩa "quá, lắm", bộ chính 大 (Đại); cấu tạo: 大 (Đại: to lớn) + 丶 (Chủ: quá mức).', '太漂亮了！我下午也想去买一个。', 'Tài piàoliang le! Wǒ xiàwǔ yě xiǎng qù mǎi yígè.', 'Đẹp quá! Chiều nay tôi cũng muốn đi mua một cái.', 20) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v7_21', 'lesson-7', '真', 'zhēn', 'từ Hán ngữ', 'thật', 'Phó từ', '目 (Mục) (Con mắt, nhìn ngắm, thị giác)', '真 = 十 (Thập) + 目 (Mục) + 一 + 八 (mắt nhìn thật rõ).', 'Chữ 真 (zhēn) mang nghĩa "thật", bộ chính 目 (Mục); cấu tạo: 十 (Thập) + 目 (Mục) + 一 + 八 (mắt nhìn thật rõ).', '哇，真好看啊！你买的那家商店有蓝色的书包吗？', 'Wa, zhēn hǎokàn a! Nǐ mǎi de nà jiā shāngdiàn yǒu lán sè de shūbāo ma?', 'Chà, đẹp quá đi mất! Cửa hàng bạn mua có cặp sách màu xanh dương không?', 21) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v7_22', 'lesson-7', '一起', 'yīqǐ', 'từ Hán ngữ', 'cùng nhau', 'Phó từ', '一 (Nhất) (Số một, nền tảng, nét ngang cơ bản)', '一: Bộ 一 (Nhất - 1 nét ngang, số 1) • 起: 走 (Tẩu: bước chạy) + 己 (Kỷ: tự đứng dậy)', 'Ghép 一 [bộ 一] + 起 [bộ 走] để nhớ từ 一起 (yīqǐ): "cùng nhau".', '那今天下午四点我在学校门口等你。我们一起去，好吗？', 'Nà jīntiān xiàwǔ sìdiǎn wǒ zài xuéxiào ménkǒu děng nǐ. Wǒmen yīqǐ qù, hǎo ma?', 'Vậy chiều nay 4 giờ tôi đợi bạn ở cổng trường. Chúng ta cùng đi nhé, được không?', 22) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v7_23', 'lesson-7', '怎么样', 'zěnmeyàng', 'ma', 'như thế nào', 'Đại từ', '心/忄 (Tâm) (Trái tim, tình cảm, suy nghĩ, tâm lý)', '怎: 乍 (Sạ) + 心 (Tâm: băn khoăn trong lòng) • 么: 丿 (Phiệt) + 厶 (Tư) • 样: 木 (Mộc: khuôn gỗ) + 羊 (Dương)', 'Ghép 怎 [bộ 心] + 么 [bộ 丿] + 样 [bộ 木] để nhớ từ 怎么样 (zěnmeyàng): "như thế nào".', '小王是个怎么样的人，你给我介绍一下儿。', 'Xiǎowáng shì gè zěnmeyàng de rén, nǐ gěi wǒ jièshào yíxiàr.', 'Vương là người như thế nào, bạn giới thiệu cho tôi xíu đi.', 23) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order) VALUES ('g7_1', 'lesson-7', '1. Các trường hợp giữa định ngữ và trung tâm ngữ không cần thêm trợ từ', 'Cấu trúc câu ngữ pháp trọng tâm', ' kết cấu “的”', NULL, '[{"hanzi":"好学生","pinyin":"hǎo xuésheng","meaning":"học sinh tốt, học sinh giỏi"},{"hanzi":"好兄弟","pinyin":"hǎo xiōngdì","meaning":"anh em tốt"}]'::jsonb, 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order) VALUES ('g7_2', 'lesson-7', '1.1 Định ngữ là tính từ đơn âm tiết thì thường không cần dùng“的”.', 'Cấu trúc câu ngữ pháp trọng tâm', ' 好人 /hǎorén/ : người tốt 坏人  /huàirén / : người xấu 好学生 /hǎo xuésheng/  : học sinh tốt, học sinh giỏi 大楼  /dàlóu /：tòa nhà lớn 好兄弟 /hǎo xiōngdì/ : anh em tốt 好姐妹  /hǎo jiěmèi/: chị em tốt 小学生  /xiǎoxuéshēng/: học sinh tiểu học 大学生 /dàxuéshēng/ : sinh', NULL, '[{"hanzi":"好姐妹","pinyin":"hǎo jiěmèi","meaning":"chị em tốt"},{"hanzi":"小学生","pinyin":"xiǎoxuéshēng","meaning":"học sinh tiểu học"}]'::jsonb, 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order) VALUES ('g7_3', 'lesson-7', '1.2.   Định ngữ là danh từ dùng để nói rõ nghề nghiệp chức vị, hoặc nói', 'Cấu trúc câu ngữ pháp trọng tâm', ' về  thuộc tính, nguyên liệu, nguồn gốc, phân biệt chủng loại của sự vật thì thường không cần dùng“的”. 汉语老师 /Hànyǔ lǎoshī /: giáo viên tiếng Trung 汉语词典 /Hànyǔ cídiǎn/: từ điển tiếng Trung 中国人 /Zhōngguó rén/: người Trung Quốc 牛仔裤   /niúzǎikù/ : quần j', NULL, '[{"hanzi":"大学生","pinyin":"dàxuéshēng","meaning":"sinh viên đại học"},{"hanzi":"汉语老师","pinyin":"Hànyǔ lǎoshī","meaning":"giáo viên tiếng Trung"}]'::jsonb, 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order) VALUES ('g7_4', 'lesson-7', '1.4.    Định ngữ là số từ, lượng từ hoặc cụm số lượng từ biểu thị quan hệ hạn', 'Cấu trúc câu ngữ pháp trọng tâm', ' chế thì thường sẽ không thêm “的” 一个故事 /yígè gùshì/ : một câu chuyện 一个人 /yígè rén/ : một người 两本书  /liǎng běn shū/ : hai quyển sách 三支铅笔 /sān zhī qiānbǐ/ : ba cây bút chì', NULL, '[{"hanzi":"汉语词典","pinyin":"Hànyǔ cídiǎn","meaning":"từ điển tiếng Trung"},{"hanzi":"中国人","pinyin":"Zhōngguó rén","meaning":"người Trung Quốc"}]'::jsonb, 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order;
INSERT INTO texts (id, lesson_id, title, description, sort_order) VALUES ('txt_7_1', 'lesson-7', 'Bài khoá #1: Hội thoại giáo trình — Đồ dùng học tập của tôi', 'Hội thoại chuẩn giáo trình Bài 7. Từ vựng chưa học được chú thích phiên âm & nghĩa trong ngoặc.', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_7_1_1', 'txt_7_1', '安妮', '马克，今天下午你去哪儿？', '马克，今天下午你去哪儿？', 'Mǎkè, jīntiān xiàwǔ nǐ qù nǎr?', 'Mark, chiều nay bạn đi đâu?', 1) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_7_1_2', 'txt_7_1', '马克', '我想去商店买两支圆珠笔、一把尺子和三本笔记本。你想去吗？', '我想去商店买两 (liǎng: hai (số lượng))支圆珠笔、一把尺子和三本笔记本。你想去吗？', 'Wǒ xiǎng qù shāngdiàn mǎi liǎng zhī yuánzhūbǐ, yī bǎ chǐzi hé sān běn bǐjìběn. Nǐ xiǎng qù ma?', 'Tôi muốn đi cửa hàng mua hai cây bút bi, một cây thước kẻ và ba quyển vở ghi chép. Bạn có muốn đi không?', 2) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_7_1_3', 'txt_7_1', '安妮', '我也想去买一支铅笔和一本汉语词典。', '我也想去买一支铅笔和一本汉语词典。', 'Wǒ yě xiǎng qù mǎi yī zhī qiānbǐ hé yī běn Hànyǔ cídiǎn.', 'Tôi cũng muốn đi mua một cây bút chì và một quyển từ điển tiếng Hán.', 3) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_7_1_4', 'txt_7_1', '马克', '那今天下午四点我在学校门口等你。我们一起去，好吗？', '那今天下午四点我在学校门口 (kǒu: khẩu, người)等你。我们一起去，好吗？', 'Nà jīntiān xiàwǔ sìdiǎn wǒ zài xuéxiào ménkǒu děng nǐ. Wǒmen yīqǐ qù, hǎo ma?', 'Vậy chiều nay 4 giờ tôi đợi bạn ở cổng trường. Chúng ta cùng đi nhé, được không?', 4) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_7_1_5', 'txt_7_1', '安妮', '好啊！', '好啊！', 'Hǎo a!', 'Được chứ!', 5) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_7_1_1', 'lesson-7', 'txt_7_1', 'listening', 'listening', '马克，今天下午你去哪儿？', NULL, 'Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Mark, chiều nay bạn đi đâu?","Đợi tôi năm phút ở phía trước hiệu sách nhé.","Cậu thích mùa xuân hay mùa hè?","Mẹ ơi, quần áo của con ở đâu nhỉ?"]'::jsonb, 0, 'Nội dung nghe được: 马克，今天下午你去哪儿？ (Mǎkè, jīntiān xiàwǔ nǐ qù nǎr?) → Mark, chiều nay bạn đi đâu?', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_7_1_2', 'lesson-7', 'txt_7_1', 'listening', 'listening', '我想去商店买两支圆珠笔、一把尺子和三本笔记本。你想去吗？', NULL, 'Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["一个故事 (shì: việc, chuyện)","我想去商店买两 (liǎng: hai (số lượng))支圆珠笔、一把尺子和三本笔记本。你想去吗？","汉语老师","好兄弟 (xiōngdì: anh em)"]'::jsonb, 1, 'Câu vừa đọc: 我想去商店买两支圆珠笔、一把尺子和三本笔记本。你想去吗？ (Wǒ xiǎng qù shāngdiàn mǎi liǎng zhī yuánzhūbǐ, yī bǎ chǐzi hé sān běn bǐjìběn. Nǐ xiǎng qù ma?) → Tôi muốn đi cửa hàng mua hai cây bút bi, một cây thước kẻ và ba quyển vở ghi chép. Bạn có muốn đi không?', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_7_1_3', 'lesson-7', 'txt_7_1', 'listening', 'listening', '我也想去买一支铅笔和一本汉语词典。', NULL, 'Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Tôi không hay (không thường) liên lạc với Lý Quân.","Tôi cũng muốn đi mua một cây bút chì và một quyển từ điển tiếng Hán.","Vấn đề này tôi không biết nên chỉ đành đi hỏi mẹ.","Anh ấy nói tiếng Trung không tốt."]'::jsonb, 1, 'Nội dung nghe được: 我也想去买一支铅笔和一本汉语词典。 (Wǒ yě xiǎng qù mǎi yī zhī qiānbǐ hé yī běn Hànyǔ cídiǎn.) → Tôi cũng muốn đi mua một cây bút chì và một quyển từ điển tiếng Hán.', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_7_1_4', 'lesson-7', 'txt_7_1', 'listening', 'listening', '那今天下午四点我在学校门口等你。我们一起去，好吗？', NULL, 'Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["今天下午我买了一把新 (xīn: mới)尺子。","那今天下午四点我在学校门口 (kǒu: khẩu, người)等你。我们一起去，好吗？","那本词典","这条 (tiáo: cái, chiếc)路 (lù: đường)"]'::jsonb, 1, 'Câu vừa đọc: 那今天下午四点我在学校门口等你。我们一起去，好吗？ (Nà jīntiān xiàwǔ sìdiǎn wǒ zài xuéxiào ménkǒu děng nǐ. Wǒmen yīqǐ qù, hǎo ma?) → Vậy chiều nay 4 giờ tôi đợi bạn ở cổng trường. Chúng ta cùng đi nhé, được không?', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO texts (id, lesson_id, title, description, sort_order) VALUES ('txt_7_2', 'lesson-7', 'Bài khoá #2: Hội thoại giáo trình — Đồ dùng học tập của tôi', 'Hội thoại chuẩn giáo trình Bài 7. Từ vựng chưa học được chú thích phiên âm & nghĩa trong ngoặc.', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_7_2_1', 'txt_7_2', '范玉兰', '小白，你觉得我今天买的书包怎么样？', '小白，你觉得我今天买的书包怎么样？', 'Xiǎobái, nǐ juéde wǒ jīntiān mǎi de shūbāo zěnmeyàng?', 'Tiểu Bạch, bạn thấy chiếc cặp sách hôm nay tôi mua thế nào?', 1) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_7_2_2', 'txt_7_2', '白茹雪', '哇，真好看啊！你买的那家商店有蓝色的书包吗？', '哇 (wa: oa, chà (cảm thán))，真好看啊！你买的那家商店有蓝色的书包吗？', 'Wa, zhēn hǎokàn a! Nǐ mǎi de nà jiā shāngdiàn yǒu lán sè de shūbāo ma?', 'Chà, đẹp quá đi mất! Cửa hàng bạn mua có cặp sách màu xanh dương không?', 2) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_7_2_3', 'txt_7_2', '范玉兰', '有啊，还有黄色和白色的书包。', '有啊，还 (hái: còn, vẫn)有黄色和白色的书包。', 'Yǒu a, hái yǒu huángsè hé báisè de shūbāo.', 'Có chứ, còn có cả cặp màu vàng và màu trắng nữa.', 3) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_7_2_4', 'txt_7_2', '白茹雪', '太漂亮了！我下午也想去买一个。', '太漂亮了！我下午也想去买一个。', 'Tài piàoliang le! Wǒ xiàwǔ yě xiǎng qù mǎi yígè.', 'Đẹp quá! Chiều nay tôi cũng muốn đi mua một cái.', 4) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_7_2_5', 'txt_7_2', '范玉兰', '那家商店就在学校门口前面。', '那家商店就在学校门口 (kǒu: khẩu, người)前面。', 'Nà jiā shāngdiàn jiù zài xuéxiào ménkǒu qiánmian.', 'Cửa hàng đó nằm ngay phía trước cổng trường đấy.', 5) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_7_2_6', 'txt_7_2', '白茹雪', '好，谢谢你！', '好，谢谢你！', 'Hǎo, xièxie nǐ!', 'Được, cảm ơn bạn!', 6) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_7_2_1', 'lesson-7', 'txt_7_2', 'listening', 'listening', '小白，你觉得我今天买的书包怎么样？', NULL, 'Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Tôi muốn đi siêu thị mua một chút đồ.","Một bông hoa","Tiểu Bạch, bạn thấy chiếc cặp sách hôm nay tôi mua thế nào?","Anh ấy không phải giáo viên."]'::jsonb, 2, 'Nội dung nghe được: 小白，你觉得我今天买的书包怎么样？ (Xiǎobái, nǐ juéde wǒ jīntiān mǎi de shūbāo zěnmeyàng?) → Tiểu Bạch, bạn thấy chiếc cặp sách hôm nay tôi mua thế nào?', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_7_2_2', 'lesson-7', 'txt_7_2', 'listening', 'listening', '哇，真好看啊！你买的那家商店有蓝色的书包吗？', NULL, 'Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["那本词典","哇 (wa: oa, chà (cảm thán))，真好看啊！你买的那家商店有蓝色的书包吗？","这个书包","我想买两 (liǎng: hai (số lượng))支蓝色圆珠笔。"]'::jsonb, 1, 'Câu vừa đọc: 哇，真好看啊！你买的那家商店有蓝色的书包吗？ (Wa, zhēn hǎokàn a! Nǐ mǎi de nà jiā shāngdiàn yǒu lán sè de shūbāo ma?) → Chà, đẹp quá đi mất! Cửa hàng bạn mua có cặp sách màu xanh dương không?', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_7_2_3', 'lesson-7', 'txt_7_2', 'listening', 'listening', '有啊，还有黄色和白色的书包。', NULL, 'Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Vận động viên bị thương rồi nên đành phải bỏ thi đấu.","Sao cậu lại đến nữa vậy?","Một khuôn mặt","Có chứ, còn có cả cặp màu vàng và màu trắng nữa."]'::jsonb, 3, 'Nội dung nghe được: 有啊，还有黄色和白色的书包。 (Yǒu a, hái yǒu huángsè hé báisè de shūbāo.) → Có chứ, còn có cả cặp màu vàng và màu trắng nữa.', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_7_2_4', 'lesson-7', 'txt_7_2', 'listening', 'listening', '太漂亮了！我下午也想去买一个。', NULL, 'Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["我想买两 (liǎng: hai (số lượng))支蓝色圆珠笔。","你觉得这支铅笔好看吗？","太漂亮了！我下午也想去买一个。","在书店前面等我五分钟。"]'::jsonb, 2, 'Câu vừa đọc: 太漂亮了！我下午也想去买一个。 (Tài piàoliang le! Wǒ xiàwǔ yě xiǎng qù mǎi yígè.) → Đẹp quá! Chiều nay tôi cũng muốn đi mua một cái.', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO texts (id, lesson_id, title, description, sort_order) VALUES ('txt_7_3', 'lesson-7', 'Bài nghe tổng hợp: Ôn tập lũy tiến (Bài 1 – Bài 7)', 'Kết hợp từ vựng & mẫu câu đã học từ Bài 1 đến Bài 6 cùng trọng tâm Bài 7 để củng cố phản xạ nghe.', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
