INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_7_3_7', 'txt_7_3', 'Ôn Bài 2', '这是什么书？', '这是什么书？', 'Zhè shì shénme shū?', 'Đây là sách gì?', 7) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_7_3_8', 'txt_7_3', 'Bài 7', '这本书', '这本书', 'zhè běn shū', 'quyển sách này', 8) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_7_3_1', 'lesson-7', 'txt_7_3', 'listening', 'listening', 'A: 你怎么去超市呢？', NULL, '[Ôn tập Bài 6] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Anh ấy kể chuyện cho tôi nghe một cách hạnh phúc.","Nếu cậu ấy tham gia cuộc thi lần này thì tôi sẽ tham gia.","Ba bạn sinh viên","Cậu đi gì đến siêu thị thế?"]'::jsonb, 3, 'Nội dung nghe được: A: 你怎么去超市呢？ (Nǐ zěnme qù chāoshì ne?) → Cậu đi gì đến siêu thị thế?', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_7_3_2', 'lesson-7', 'txt_7_3', 'listening', 'listening', '好学生', NULL, '[Bài 7] Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["好学生","汉语词典","今天下午我买了一把新 (xīn: mới)尺子。","三支铅笔"]'::jsonb, 0, 'Câu vừa đọc: 好学生 (hǎo xuésheng) → học sinh tốt, học sinh giỏi', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_7_3_3', 'lesson-7', 'txt_7_3', 'listening', 'listening', '谁啊？', NULL, '[Ôn tập Bài 3] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Hôm qua chúng tôi đi hiệu sách, anh ấy đã mua một cuốn từ điển.","Ai đấy?","Hôm nay trời rất lạnh.","đứa bé vô cùng"]'::jsonb, 1, 'Nội dung nghe được: 谁啊？ (Shéi a?) → Ai đấy?', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_7_3_4', 'lesson-7', 'txt_7_3', 'listening', 'listening', '汉语老师', NULL, '[Bài 7] Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["汉语老师","一个人","今天下午我买了一把新 (xīn: mới)尺子。","我想买两 (liǎng: hai (số lượng))支蓝色圆珠笔。"]'::jsonb, 0, 'Câu vừa đọc: 汉语老师 (Hànyǔ lǎoshī) → giáo viên tiếng Trung', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_7_3_5', 'lesson-7', 'txt_7_3', 'listening', 'listening', '三个朋友', NULL, '[Ôn tập Bài 1] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["chi phí sinh hoạt","Con người anh ta thật là tốt!","Cô ấy là giáo viên.","Ba người bạn (cách dùng đúng)"]'::jsonb, 3, 'Nội dung nghe được: 三个朋友 (sān gè péngyou) → Ba người bạn (cách dùng đúng)', 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO texts (id, lesson_id, title, description, sort_order) VALUES ('txt_7_4', 'lesson-7', 'Bài khoá mở rộng: Mua văn phòng phẩm chuẩn bị học kỳ mới (Mở rộng)', 'Hội thoại tình huống mới xây dựng dựa trên từ vựng và ngữ pháp Bài 7 (không trùng lặp nguyên văn giáo trình).', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_7_4_1', 'txt_7_4', 'Lan', '马克，今天你想去商店买什么？', '马克，今天你想去商店买什么？', 'Mǎkè, jīntiān nǐ xiǎng qù shāngdiàn mǎi shénme?', 'Mark, hôm nay cậu muốn đi cửa hàng mua gì?', 1) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_7_4_2', 'txt_7_4', 'Mark', '我想买两本笔记本、一支铅笔和一本汉语词典。', '我想买两 (liǎng: hai (số lượng))本笔记本、一支铅笔和一本汉语词典。', 'Wǒ xiǎng mǎi liǎng běn bǐjìběn, yì zhī qiānbǐ hé yì běn Hànyǔ cídiǎn.', 'Tôi muốn mua hai quyển vở ghi, một cây bút chì và một quyển từ điển Hán ngữ.', 2) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_7_4_3', 'txt_7_4', 'Lan', '你看这个蓝色的书包，好看吗？', '你看这个蓝色的书包，好看吗？', 'Nǐ kàn zhège lán sè de shūbāo, hǎokàn ma?', 'Cậu xem chiếc cặp màu xanh dương này có đẹp không?', 3) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_7_4_4', 'txt_7_4', 'Mark', '真漂亮！我也想买一个黄色的。', '真漂亮！我也想买一个黄色的。', 'Zhēn piàoliang! Wǒ yě xiǎng mǎi yígè huángsè de.', 'Đẹp thật! Tôi cũng muốn mua một chiếc màu vàng.', 4) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_7_4_1', 'lesson-7', 'txt_7_4', 'listening', 'listening', '马克，今天你想去商店买什么？ 我想买两本笔记本、一支铅笔和一本汉语词典。 你看这个蓝色的书包，好看吗？ 真漂亮！我也想买一个黄色的。', NULL, '[Nghe hiểu tình huống mới] Mark dự định mua chiếc cặp sách màu gì?', '["Màu xanh dương","Màu vàng (黄色)","Màu đen","Không mua cặp sách"]'::jsonb, 1, 'Lan khen cặp xanh dương, còn Mark nói ''我也想买一个黄色的'' (tôi muốn mua màu vàng).', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_7_4_2', 'lesson-7', 'txt_7_4', 'listening', 'listening', '马克，今天你想去商店买什么？', NULL, '[Mở rộng] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Cô ấy tự tin tham gia cuộc thi.","Bệnh viện ở bên phải trường học của chúng ta.","Anh ấy hát rất hay.","Mark, hôm nay cậu muốn đi cửa hàng mua gì?"]'::jsonb, 3, 'Nội dung nghe được: 马克，今天你想去商店买什么？ (Mǎkè, jīntiān nǐ xiǎng qù shāngdiàn mǎi shénme?) → Mark, hôm nay cậu muốn đi cửa hàng mua gì?', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_7_4_3', 'lesson-7', 'txt_7_4', 'listening', 'listening', '我想买两本笔记本、一支铅笔和一本汉语词典。', NULL, '[Mở rộng] Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["今天下午我买了一把新 (xīn: mới)尺子。","我想买两 (liǎng: hai (số lượng))本笔记本、一支铅笔和一本汉语词典。","我想买两 (liǎng: hai (số lượng))支蓝色圆珠笔。","那本词典"]'::jsonb, 1, 'Câu vừa đọc: 我想买两本笔记本、一支铅笔和一本汉语词典。 (Wǒ xiǎng mǎi liǎng běn bǐjìběn, yì zhī qiānbǐ hé yì běn Hànyǔ cídiǎn.) → Tôi muốn mua hai quyển vở ghi, một cây bút chì và một quyển từ điển Hán ngữ.', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_7_4_4', 'lesson-7', 'txt_7_4', 'listening', 'listening', '你看这个蓝色的书包，好看吗？', NULL, '[Mở rộng] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Tốt nhất bạn nên tiếp tục rèn luyện sức khỏe đi!","Chúng ta cùng qua bên đó xem đi!","Mark, chiều nay bạn đi đâu?","Cậu xem chiếc cặp màu xanh dương này có đẹp không?"]'::jsonb, 3, 'Nội dung nghe được: 你看这个蓝色的书包，好看吗？ (Nǐ kàn zhège lán sè de shūbāo, hǎokàn ma?) → Cậu xem chiếc cặp màu xanh dương này có đẹp không?', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss7_1', 'lesson-7', '那个黄色的书包真漂亮', '[Mở rộng] Chiếc cặp sách màu vàng kia đẹp thật đấy!', 'Nàge huángsè de shūbāo zhēn piàoliang!', '["那个","黄色","的","书包","真","漂亮"]'::jsonb, NULL, 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss7_2', 'lesson-7', '在书店前面等我五分钟', '[Mở rộng] Đợi tôi năm phút ở phía trước hiệu sách nhé.', 'Zài shūdiàn qiánmian děng wǒ wǔ fēnzhōng.', '["在","书店","前面","等我","五","分钟"]'::jsonb, NULL, 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
