INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss7_5', 'lesson-7', '到前面那个十字路口往右拐', '[Ôn tập Bài 6] Đến ngã tư phía trước kia thì rẽ phải.', 'Dào qiánmian nàge shízìlùkǒu wǎng yòu guǎi.', '["到","前面","那个","十字路口","往右","拐"]'::jsonb, 'Từ chưa học: 右 (yòu: phải)', 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss7_6', 'lesson-7', '你去学校附近的地方吗', '[Ôn tập Bài 4] Bạn có đi đến chỗ gần trường không?', 'Nǐ qù xuéxiào fùjìn de dìfang ma?', '["你去","学校","附近","的","地方","吗"]'::jsonb, NULL, 6) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss7_exp_1', 'lesson-7', '马克今天下午你去哪儿', 'Mark, chiều nay bạn đi đâu?', 'Mǎkè, jīntiān xiàwǔ nǐ qù nǎr?', '["马克","今天","下午","你","去","哪儿"]'::jsonb, NULL, 7) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss7_exp_2', 'lesson-7', '我想去商店买两支圆珠笔一把尺子和三本笔记本你想去吗', 'Tôi muốn đi cửa hàng mua hai cây bút bi, một cây thước kẻ và ba quyển vở ghi chép. Bạn có muốn đi không?', 'Wǒ xiǎng qù shāngdiàn mǎi liǎng zhī yuánzhūbǐ, yī bǎ chǐzi hé sān běn bǐjìběn. Nǐ xiǎng qù ma?', '["我","想","去","商店","买","两","支","圆珠笔","一","把","尺子","和","三","本","笔记本","你","想","去","吗"]'::jsonb, NULL, 8) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss7_exp_3', 'lesson-7', '我也想去买一支铅笔和一本汉语词典', 'Tôi cũng muốn đi mua một cây bút chì và một quyển từ điển tiếng Hán.', 'Wǒ yě xiǎng qù mǎi yī zhī qiānbǐ hé yī běn Hànyǔ cídiǎn.', '["我","也","想","去","买","一","支","铅笔","和","一","本","汉语","词典"]'::jsonb, NULL, 9) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss7_exp_4', 'lesson-7', '那今天下午四点我在学校门口等你我们一起去好吗', 'Vậy chiều nay 4 giờ tôi đợi bạn ở cổng trường. Chúng ta cùng đi nhé, được không?', 'Nà jīntiān xiàwǔ sìdiǎn wǒ zài xuéxiào ménkǒu děng nǐ. Wǒmen yīqǐ qù, hǎo ma?', '["那","今天","下午","四","点","我","在","学校","门","口","等","你","我们","一起","去","好","吗"]'::jsonb, NULL, 10) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss7_exp_5', 'lesson-7', '小白你觉得我今天买的书包怎么样', 'Tiểu Bạch, bạn thấy chiếc cặp sách hôm nay tôi mua thế nào?', 'Xiǎobái, nǐ juéde wǒ jīntiān mǎi de shūbāo zěnmeyàng?', '["小","白","你","觉得","我","今天","买","的","书包","怎么样"]'::jsonb, NULL, 11) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss7_exp_6', 'lesson-7', '哇真好看啊你买的那家商店有蓝色的书包吗', 'Chà, đẹp quá đi mất! Cửa hàng bạn mua có cặp sách màu xanh dương không?', 'Wa, zhēn hǎokàn a! Nǐ mǎi de nà jiā shāngdiàn yǒu lán sè de shūbāo ma?', '["哇","真","好看","啊","你","买","的","那","家","商店","有","蓝色","的","书包","吗"]'::jsonb, NULL, 12) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss7_exp_7', 'lesson-7', '有啊还有黄色和白色的书包', 'Có chứ, còn có cả cặp màu vàng và màu trắng nữa.', 'Yǒu a, hái yǒu huángsè hé báisè de shūbāo.', '["有","啊","还","有","黄色","和","白色","的","书包"]'::jsonb, NULL, 13) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss7_exp_8', 'lesson-7', '太漂亮了我下午也想去买一个', 'Đẹp quá! Chiều nay tôi cũng muốn đi mua một cái.', 'Tài piàoliang le! Wǒ xiàwǔ yě xiǎng qù mǎi yígè.', '["太","漂亮","了","我","下午","也","想","去","买","一","个"]'::jsonb, NULL, 14) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
