INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr7_vi_1', 'lesson-7', 'vi_to_zh', '[Mở rộng] Chiếc cặp sách màu vàng kia đẹp thật đấy!', NULL, NULL, '那个黄色的书包真漂亮！', NULL, 'nàge huángsè de shūbāo zhēn piàoliang', '[]'::jsonb, 'Gợi ý Pinyin: Nàge huángsè de shūbāo zhēn piàoliang!', 'Chiếc cặp sách màu vàng kia đẹp thật đấy! → 那个黄色的书包真漂亮！ (Nàge huángsè de shūbāo zhēn piàoliang!)', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
