INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq7_13', 'lesson-7', NULL, 'expanded_quiz', 'radical', NULL, NULL, 'Chữ Hán “书包” chứa bộ thủ nào sau đây?', '["乙 (Ất) (Uốn cong, số thứ tự, chồi non)","厂 (Hán) (Vách đá, mái che, công xưởng)","文 (Văn) (Văn chương, chữ viết, hoa văn)","矛 (Mâu) (Cây giáo, mâu thuẫn)"]'::jsonb, 0, 'Chữ “书包” có bộ chính 乙 (Ất) (Uốn cong, số thứ tự, chồi non). Chiết tự: 书: Nét gấp 乛 + 乛 + 丨 + 丶 (cuốn sách, bút viết) • 包: 勹 (Bao: bọc lại) + 巳 (Tỵ: thai nhi bên trong)', 13) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq7_14', 'lesson-7', NULL, 'expanded_quiz', 'radical', NULL, NULL, 'Chữ Hán “圆珠笔” chứa bộ thủ nào sau đây?', '["月 (Nguyệt/Nhục) (Mặt trăng hoặc các bộ phận thân thể người)","囗 (Vi) (Vây quanh, không gian kín, lãnh thổ)","糸/纟 (Mịch) (Sợi tơ, gắn kết, màu sắc)","雨 (Vũ) (Mưa, sương, tuyết, hiện tượng thời tiết)"]'::jsonb, 1, 'Chữ “圆珠笔” có bộ chính 囗 (Vi) (Vây quanh, không gian kín, lãnh thổ). Chiết tự: 圆: 囗 (Vi: vòng tròn ngoài) + 员 (Viên) • 珠: 王 (Ngọc: viên ngọc) + 朱 (Chu) • 笔: ⺮ (Trúc: thân bút bằng tre) + 毛 (Mao: đầu lông bút)', 14) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq7_15', 'lesson-7', NULL, 'expanded_quiz', 'radical', NULL, NULL, 'Chữ Hán “尺子” chứa bộ thủ nào sau đây?', '["足/⻊ (Túc) (Bàn chân, bước chân, đá bóng, chạy)","丿 (Phiệt) (Nét phẩy nghiêng)","山 (Sơn) (Núi non, đồi núi)","尸 (Thi) (Thân người, mái nhà, nơi ở)"]'::jsonb, 3, 'Chữ “尺子” có bộ chính 尸 (Thi) (Thân người, mái nhà, nơi ở). Chiết tự: 尺: Bộ 尸 (Thi) + nét mác (cây thước đo xưa) • 子: Bộ 子 (Tử - đứa trẻ dang tay, chữ độc thể)', 15) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq7_16', 'lesson-7', NULL, 'expanded_quiz', 'radical', NULL, NULL, 'Chữ Hán “笔记本” chứa bộ thủ nào sau đây?', '["舌 (Thiệt) (Cái lưỡi, lời nói, nếm vị)","香 (Hương) (Mùi thơm, hương vị)","厶 (Tư) (Riêng tư, cuộn tròn)","竹/⺮ (Trúc) (Tre trúc, đồ đan, sách vở)"]'::jsonb, 3, 'Chữ “笔记本” có bộ chính 竹/⺮ (Trúc) (Tre trúc, đồ đan, sách vở). Chiết tự: 笔: ⺮ (Trúc: thân bút bằng tre) + 毛 (Mao: đầu lông bút) • 记: 讠 (Ngôn: lời nói) + 己 (Kỷ: tự mình ghi nhớ) • 本: 木 (Mộc: cây) + nét gạch ngang 一 dưới gốc (gốc rễ, quyển sách)', 16) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq7_17', 'lesson-7', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, '[Ôn tập Bài 4] Từ đã học “知道” (zhīdào) có nghĩa là gì?', '["vào học, lên lớp","biết","thế, nhé, nhỉ, cơ (dùng ở cuối câu trần thuật hoặc nghi vấn)","anh ấy, cậu ấy... (ngôi thứ ba số ít chỉ nam)"]'::jsonb, 1, 'Ôn tập Bài 4: “知道” (zhīdào) nghĩa là: biết.', 17) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
