INSERT INTO lessons (id, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id) VALUES ('lesson-8', 'Bài 8: Mua hoa quả - Đơn nguyên 2: Mua sắm', 'Bài 8', 'Đơn nguyên 2: Mua sắm', 'Hỏi giá cả, đơn vị tiền tệ (khoái, mao), cách nói số lượng và mặc cả khi mua trái cây.', '2026-11-14'::date, 8, TRUE, NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, date_added = EXCLUDED.date_added, sort_order = EXCLUDED.sort_order, is_system = TRUE, updated_at = NOW();
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v8_1', 'lesson-8', '水果', 'shuǐguǒ', 'thủy quả', 'hoa quả, trái cây', 'Danh từ', '水/氵 (Thủy) (Nước, chất lỏng, sông ngòi)', '水: Bộ 水 (Thủy - dòng nước chảy, chữ độc thể) • 果: 田 (Điền: trái tròn) + 木 (Mộc: trên ngọn cây)', 'Ghép 水 [bộ 水] + 果 [bộ 木] để nhớ từ 水果 (shuǐguǒ): "hoa quả, trái cây".', '这是关于“水果”的常用句子。', 'Zhè shì guānyú ''shuǐguǒ'' de chángyòng jùzi.', 'Đây là câu ví dụ sử dụng từ ''水果'' (hoa quả, trái cây).', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v8_2', 'lesson-8', '苹果', 'píngguǒ', 'bình quả', 'táo', 'Danh từ', '艹 (Thảo) (Cỏ cây, hoa lá, thảo mộc)', '苹: 艹 (Thảo: thực vật) + 平 (Bình) • 果: 田 (Điền: trái tròn) + 木 (Mộc: trên ngọn cây)', 'Ghép 苹 [bộ 艹] + 果 [bộ 木] để nhớ từ 苹果 (píngguǒ): "táo".', '一斤苹果多少钱？', 'Yī jīn píngguǒ duōshao qián?', 'Nửa kg (1 cân) táo bao nhiêu tiền?', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v8_3', 'lesson-8', '芒果', 'mángguǒ', 'quả', 'xoài', 'Danh từ', '艹 (Thảo) (Cỏ cây, hoa lá, thảo mộc)', '芒: 艹 (Thảo: thực vật) + 亡 (Vong) • 果: 田 (Điền: trái tròn) + 木 (Mộc: trên ngọn cây)', 'Ghép 芒 [bộ 艹] + 果 [bộ 木] để nhớ từ 芒果 (mángguǒ): "xoài".', '我买三斤。啊，阿姨，西瓜和芒果怎么卖？', 'Wǒ mǎi sān jīn. A, āyí, xīguā hé mángguǒ zěnme mài?', 'Cháu mua ba cân ạ. À cô ơi, dưa hấu và xoài bán thế nào ạ?', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v8_4', 'lesson-8', '西瓜', 'xīguā', 'tây qua', 'dưa hấu', 'Danh từ', '西/覀 (Tây) (Phương tây, che đậy)', '西: Bộ 西 (Tây - chim về tổ lúc mặt trời lặn) • 瓜: Bộ 瓜 (Qua - trái dưa treo trên giàn leo)', 'Ghép 西 [bộ 西] + 瓜 [bộ 瓜] để nhớ từ 西瓜 (xīguā): "dưa hấu".', '你买几个西瓜？', 'Nǐ mǎi jǐ gè xīguā?', 'Cậu mua mấy quả dưa hấu thế?', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v8_5', 'lesson-8', '木瓜', 'mùguā', 'qua', 'đu đủ', 'Danh từ', '木 (Mộc) (Cây cối, gỗ, thực vật)', '木: Bộ 木 (Mộc - thân cây, cành và rễ, chữ độc thể) • 瓜: Bộ 瓜 (Qua - trái dưa treo trên giàn leo)', 'Ghép 木 [bộ 木] + 瓜 [bộ 瓜] để nhớ từ 木瓜 (mùguā): "đu đủ".', '不太酸, 很好吃。还有木瓜和火龙果很甜，你要买什么吗？', 'Bú tài suān, hěn hǎo chī. Hái yǒu mùguā hé huǒlóng guǒ hěn tián, nǐ yào mǎi shénme ma?', 'Không chua lắm, ngon lắm. Còn có đu đủ và thanh long rất ngọt, cháu muốn mua thêm gì không?', 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v8_6', 'lesson-8', '火龙果', 'huǒlóngguǒ', 'hỏa quả', 'thanh long', 'Danh từ', '火/灬 (Hỏa) (Lửa, nhiệt độ, nấu nướng, nóng bức)', '火: Bộ 火 (Hỏa - ngọn lửa bốc lên, chữ độc thể) • 龙: Bộ 龙 (Long - hình con rồng uốn lượn, chữ độc thể) • 果: 田 (Điền: trái tròn) + 木 (Mộc: trên ngọn cây)', 'Ghép 火 [bộ 火] + 龙 [bộ 龙] + 果 [bộ 木] để nhớ từ 火龙果 (huǒlóngguǒ): "thanh long".', '不太酸, 很好吃。还有木瓜和火龙果很甜，你要买什么吗？', 'Bú tài suān, hěn hǎo chī. Hái yǒu mùguā hé huǒlóng guǒ hěn tián, nǐ yào mǎi shénme ma?', 'Không chua lắm, ngon lắm. Còn có đu đủ và thanh long rất ngọt, cháu muốn mua thêm gì không?', 6) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v8_7', 'lesson-8', '草莓', 'cǎoméi', 'từ Hán ngữ', 'dâu tây', 'Danh từ', '艹 (Thảo) (Cỏ cây, hoa lá, thảo mộc)', '草: 艹 (Thảo: cây cỏ) + 早 (Tảo) • 莓: 艹 (Thảo: cây dâu) + 每 (Mỗi)', 'Ghép 草 [bộ 艹] + 莓 [bộ 艹] để nhớ từ 草莓 (cǎoméi): "dâu tây".', '草莓果汁多少钱一杯？', 'Cǎoméi guǒzhī duōshao qián yī bēi?', 'Nước ép dâu tây bao nhiêu tiền một cốc ạ?', 7) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v8_8', 'lesson-8', '果汁', 'guǒzhī', 'quả', 'nước ép hoa quả', 'Danh từ', '木 (Mộc) (Cây cối, gỗ, thực vật)', '果: 田 (Điền: trái tròn) + 木 (Mộc: trên ngọn cây) • 汁: 氵 (Thủy: chất lỏng) + 十 (Thập)', 'Ghép 果 [bộ 木] + 汁 [bộ 氵] để nhớ từ 果汁 (guǒzhī): "nước ép hoa quả".', '这里有果汁吗？', 'Zhè li yǒu guǒzhī ma?', 'Ở đây có nước ép trái cây không ạ?', 8) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v8_9', 'lesson-8', '东西', 'dōngxi', 'tây', 'đồ đạc', 'Danh từ', '一 (Nhất) (Số một, nền tảng, nét ngang cơ bản)', '东: Mặt trời mọc sau thân cây (七 + 小) • 西: Bộ 西 (Tây - chim về tổ lúc mặt trời lặn)', 'Ghép 东 [bộ 一] + 西 [bộ 西] để nhớ từ 东西 (dōngxi): "đồ đạc".', '这是关于“东西”的常用句子。', 'Zhè shì guānyú ''dōngxi'' de chángyòng jùzi.', 'Đây là câu ví dụ sử dụng từ ''东西'' (đồ đạc).', 9) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v8_10', 'lesson-8', '阿姨', 'āyí', 'từ Hán ngữ', 'cô, dì', 'Danh từ', '阝 (Phụ/Ấp) (Gò đất hoặc vùng đất, thành ấp)', '阿: 阝 (Phụ) + 可 (Khả) • 姨: 女 (Nữ: phụ nữ) + 夷 (Di)', 'Ghép 阿 [bộ 阝] + 姨 [bộ 女] để nhớ từ 阿姨 (āyí): "cô, dì".', '阿姨，请问，一斤苹果多少钱？', 'Āyí, qǐngwèn, yī jīn píngguǒ duōshao qián?', 'Cô ơi, cho cháu hỏi một cân táo bao nhiêu tiền ạ?', 10) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v8_11', 'lesson-8', '钱', 'qián', 'tiền', 'tiền', 'Danh từ', '金/钅 (Kim) (Kim loại, tiền bạc, đồ dùng kim khí)', '钱 = 钅 (Kim: tiền xu kim loại) + 戋 (Tiên).', 'Chữ 钱 (qián) mang nghĩa "tiền", bộ chính 金/钅 (Kim); cấu tạo: 钅 (Kim: tiền xu kim loại) + 戋 (Tiên).', '一斤苹果多少钱？', 'Yī jīn píngguǒ duōshao qián?', 'Nửa kg (1 cân) táo bao nhiêu tiền?', 11) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v8_12', 'lesson-8', '要', 'yào', 'yếu', 'muốn', 'Động từ năng nguyện', '西/覀 (Tây) (Phương tây, che đậy)', '要 = 覀 (Tây biến thể) + 女 (Nữ).', 'Chữ 要 (yào) mang nghĩa "muốn", bộ chính 西/覀 (Tây); cấu tạo: 覀 (Tây biến thể) + 女 (Nữ).', '不太酸, 很好吃。还有木瓜和火龙果很甜，你要买什么吗？', 'Bú tài suān, hěn hǎo chī. Hái yǒu mùguā hé huǒlóng guǒ hěn tián, nǐ yào mǎi shénme ma?', 'Không chua lắm, ngon lắm. Còn có đu đủ và thanh long rất ngọt, cháu muốn mua thêm gì không?', 12) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v8_13', 'lesson-8', '卖', 'mài', 'mại', 'bán', 'Động từ', '十 (Thập) (Số mười, hoàn chỉnh, giao nhau)', '卖 = 十 (Thập) + 买 (Mãi: mang hàng ra bán).', 'Chữ 卖 (mài) mang nghĩa "bán", bộ chính 十 (Thập); cấu tạo: 十 (Thập) + 买 (Mãi: mang hàng ra bán).', '我买三斤。啊，阿姨，西瓜和芒果怎么卖？', 'Wǒ mǎi sān jīn. A, āyí, xīguā hé mángguǒ zěnme mài?', 'Cháu mua ba cân ạ. À cô ơi, dưa hấu và xoài bán thế nào ạ?', 13) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v8_14', 'lesson-8', '找', 'zhǎo', 'trảo', 'trả (tiền thừa), tìm', 'Động từ', '手/扌 (Thủ) (Bàn tay, động tác, thao tác)', '找 = 扌 (Thủ: tay lần tìm) + 戈 (Qua).', 'Chữ 找 (zhǎo) mang nghĩa "trả (tiền thừa), tìm", bộ chính 手/扌 (Thủ); cấu tạo: 扌 (Thủ: tay lần tìm) + 戈 (Qua).', '这是 60 块，找你 7 块。谢谢！', 'Zhè shì 60 kuài, zhǎo nǐ 7 kuài. Xièxie!', 'Đây là 60 tệ, trả lại cháu 7 tệ. Cảm ơn cháu!', 14) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v8_15', 'lesson-8', '甜', 'tián', 'từ Hán ngữ', 'ngọt', 'Tính từ', '甘 (Cam) (Vị ngọt, hài lòng)', '甜 = 舌 (Thiệt: đầu lưỡi) + 甘 (Cam: nếm vị ngọt).', 'Chữ 甜 (tián) mang nghĩa "ngọt", bộ chính 甘 (Cam); cấu tạo: 舌 (Thiệt: đầu lưỡi) + 甘 (Cam: nếm vị ngọt).', '苹果很甜，一斤两块。你想买几斤？', 'Píngguǒ hěn tián, yī jīn liǎng kuài. Nǐ xiǎng mǎi jǐ jīn?', 'Táo ngọt lắm, một cân 2 tệ. Cháu muốn mua mấy cân?', 15) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v8_16', 'lesson-8', '酸', 'suān', 'từ Hán ngữ', 'chua', 'Tính từ', '酉 (Dậu) (Bình rượu, lên men, chưng cất)', '酸 = 酉 (Dậu: bình rượu lên men) + 夋 (Thuân: vị chua).', 'Chữ 酸 (suān) mang nghĩa "chua", bộ chính 酉 (Dậu); cấu tạo: 酉 (Dậu: bình rượu lên men) + 夋 (Thuân: vị chua).', '芒果酸吗？', 'Mángguǒ suān ma?', 'Xoài có chua không ạ?', 16) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v8_17', 'lesson-8', '好吃', 'hǎochī', 'hảo ngật', 'ngon (đồ ăn)', 'Tính từ', '女 (Nữ) (Phụ nữ, gia đình, tình cảm)', '好: 女 (Nữ: người mẹ) + 子 (Tử: đứa con) • 吃: 口 (Khẩu: miệng) + 乞 (Khất)', 'Ghép 好 [bộ 女] + 吃 [bộ 口] để nhớ từ 好吃 (hǎochī): "ngon (đồ ăn)".', '不太酸, 很好吃。还有木瓜和火龙果很甜，你要买什么吗？', 'Bú tài suān, hěn hǎo chī. Hái yǒu mùguā hé huǒlóng guǒ hěn tián, nǐ yào mǎi shénme ma?', 'Không chua lắm, ngon lắm. Còn có đu đủ và thanh long rất ngọt, cháu muốn mua thêm gì không?', 17) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v8_18', 'lesson-8', '多少', 'duōshao', 'đa thiểu', 'bao nhiêu', 'Đại từ', '夕 (Tịch) (Buổi chiều tối, đêm tối)', '多: 夕 (Tịch) + 夕 (Tịch: nhiều lớp chồng nhau) • 少: 小 (Tiểu: nhỏ) + 丿 (Phiệt: cắt bớt còn ít)', 'Ghép 多 [bộ 夕] + 少 [bộ 小] để nhớ từ 多少 (duōshao): "bao nhiêu".', '你们班有多少学生？', 'Nǐmen bān yǒu duōshao xuésheng?', 'Lớp cậu có bao nhiêu học sinh?', 18) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v8_19', 'lesson-8', '多', 'duō', 'đa', 'nhiều', 'Tính từ', '夕 (Tịch) (Buổi chiều tối, đêm tối)', '多 = 夕 (Tịch) + 夕 (Tịch: nhiều lớp chồng nhau).', 'Chữ 多 (duō) mang nghĩa "nhiều", bộ chính 夕 (Tịch); cấu tạo: 夕 (Tịch) + 夕 (Tịch: nhiều lớp chồng nhau).', '你们班有多少学生？', 'Nǐmen bān yǒu duōshao xuésheng?', 'Lớp cậu có bao nhiêu học sinh?', 19) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v8_20', 'lesson-8', '杯', 'bēi', 'từ Hán ngữ', 'cốc/ly', 'Lượng từ', '木 (Mộc) (Cây cối, gỗ, thực vật)', '杯 = 木 (Mộc: chén gỗ xưa) + 不 (Bất).', 'Chữ 杯 (bēi) mang nghĩa "cốc/ly", bộ chính 木 (Mộc); cấu tạo: 木 (Mộc: chén gỗ xưa) + 不 (Bất).', '草莓果汁多少钱一杯？', 'Cǎoméi guǒzhī duōshao qián yī bēi?', 'Nước ép dâu tây bao nhiêu tiền một cốc ạ?', 20) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v8_21', 'lesson-8', '斤', 'jīn', 'cân', 'cân (= 0,5kg ở Việt Nam)', 'Lượng từ', '斤 (Cân) (Cái rìu, đơn vị cân nặng)', '斤 = Bộ 斤 (Cân - lưỡi rìu, đơn vị cân).', 'Chữ 斤 (jīn) mang nghĩa "cân (= 0,5kg ở Việt Nam)", bộ chính 斤 (Cân); cấu tạo: Bộ 斤 (Cân - lưỡi rìu, đơn vị cân).', '一斤苹果多少钱？', 'Yī jīn píngguǒ duōshao qián?', 'Nửa kg (1 cân) táo bao nhiêu tiền?', 21) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v8_22', 'lesson-8', '块', 'kuài', 'khối', 'đồng (đơn vị tiền)', 'Lượng từ', '土 (Thổ) (Đất đai, vị trí, công trình)', '块 = 土 (Thổ: cục đất) + 夬 (Quái).', 'Chữ 块 (kuài) mang nghĩa "đồng (đơn vị tiền)", bộ chính 土 (Thổ); cấu tạo: 土 (Thổ: cục đất) + 夬 (Quái).', '苹果很甜，一斤两块。你想买几斤？', 'Píngguǒ hěn tián, yī jīn liǎng kuài. Nǐ xiǎng mǎi jǐ jīn?', 'Táo ngọt lắm, một cân 2 tệ. Cháu muốn mua mấy cân?', 22) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v8_23', 'lesson-8', '总共', 'zǒnggòng', 'cộng', 'tổng cộng', 'Phó từ', '心/忄 (Tâm) (Trái tim, tình cảm, suy nghĩ, tâm lý)', '总: 丷 + 口 + 心 (Tâm: gom chung lại) • 共: 廿 (Nhấp) + 一 + 八 (Bát: hai tay cùng nâng)', 'Ghép 总 [bộ 心] + 共 [bộ 八] để nhớ từ 总共 (zǒnggòng): "tổng cộng".', '好。总共 53 块。', 'Hǎo. Zǒnggòng 53 kuài.', 'Được rồi. Tổng cộng là 53 tệ.', 23) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order) VALUES ('g8_1', 'lesson-8', '1. Đại từ nghi vấn 几 và 多少', '几 + (Lượng từ) + Danh từ', ' 几 và 多少 là các đại từ nghi vấn có thể dùng để hỏi số lượng, mã số và tuổi, cụ thể: a. Đại từ nghi vấn 几 - 几 là đại từ nghi vấn thường được dùng để hỏi số lượng ít hoặc được mặc định là ít (thường hỏi với số lượng nhỏ hơn 10). Cấu trúc: 你买几个西瓜？ Nǐ mǎ', NULL, '[{"hanzi":"你买几个西瓜？","pinyin":"Nǐ mǎi jǐ gè xīguā?","meaning":"Cậu mua mấy quả dưa hấu thế?"},{"hanzi":"小姑娘，你今年几岁？","pinyin":"Xiǎo gūniang, nǐ jīnnián jǐ suì?","meaning":"Cô bé, năm nay cháu mấy tuổi rồi?"}]'::jsonb, 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order) VALUES ('g8_2', 'lesson-8', '2. Lượng từ', '+ Lượng từ 个 dùng khá phổ biến và cho nhiều đồ vật.', ' a. Khái niệm Lượng từ là những đơn vị từ dùng để biểu thị người, sự vật, hoạt động..., tương đương với “quyển, con, cái, chiếc, tấm...” trong tiếng Việt, tùy trường hợp mà lượng từ sẽ dịch khác nhau để phù hợp với danh từ phía sau. b. Các loại lượng', NULL, '[{"hanzi":"这幅画有几千年历史了？","pinyin":"Zhè fú huà yǒu jǐ qiān nián lìshǐ le?","meaning":"Bức tranh này có lịch sử mấy nghìn năm rồi?"},{"hanzi":"今天星期几？","pinyin":"Jīntiān xīngqī jǐ?","meaning":"Hôm nay là thứ mấy?"}]'::jsonb, 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order) VALUES ('g8_3', 'lesson-8', '3. 二 và 两', 'Cấu trúc câu ngữ pháp trọng tâm', ' - Trước lượng từ phải dùng 两, tuy nhiên khi chỉ người trong trường hợp trang trọng thì dùng 二. 两棵树 /liǎng kē shù/: Hai cái cây 两个人/liǎng gè rén/: Hai người 二位贵宾 /èr wèi guìbīn/: Hai vị khách quý - Khi đếm số dùng 二. 一，二，三 /yī, èr, sān/: Một, hai, ba', NULL, '[{"hanzi":"你们班有多少学生？","pinyin":"Nǐmen bān yǒu duōshao xuésheng?","meaning":"Lớp cậu có bao nhiêu học sinh?"},{"hanzi":"你家有多少人？","pinyin":"Nǐ jiā yǒu duōshao rén?","meaning":"Nhà cậu có bao nhiêu người?"}]'::jsonb, 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order) VALUES ('g8_4', 'lesson-8', '1.超市 chāoshì  dt. siêu thị', 'Cấu trúc câu ngữ pháp trọng tâm', 'Quy tắc ngữ pháp quan trọng trong Mua hoa quả.', NULL, '[{"hanzi":"一斤苹果多少钱？","pinyin":"Yī jīn píngguǒ duōshao qián?","meaning":"Nửa kg (1 cân) táo bao nhiêu tiền?"},{"hanzi":"一个人","pinyin":"yígè rén","meaning":"Một người"}]'::jsonb, 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order;
INSERT INTO texts (id, lesson_id, title, description, sort_order) VALUES ('txt_8_1', 'lesson-8', 'Bài khoá #1: Hội thoại giáo trình — Mua hoa quả', 'Hội thoại chuẩn giáo trình Bài 8. Từ vựng chưa học được chú thích phiên âm & nghĩa trong ngoặc.', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_8_1_1', 'txt_8_1', '阮日明', '阿姨，请问，一斤苹果多少钱？', '阿姨，请问 (qǐngwèn: xin hỏi)，一斤苹果多少钱？', 'Āyí, qǐngwèn, yī jīn píngguǒ duōshao qián?', 'Cô ơi, cho cháu hỏi một cân táo bao nhiêu tiền ạ?', 1) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_8_1_2', 'txt_8_1', '服务员', '苹果很甜，一斤两块。你想买几斤？', '苹果很甜，一斤两 (liǎng: hai (số lượng))块。你想买几斤？', 'Píngguǒ hěn tián, yī jīn liǎng kuài. Nǐ xiǎng mǎi jǐ jīn?', 'Táo ngọt lắm, một cân 2 tệ. Cháu muốn mua mấy cân?', 2) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_8_1_3', 'txt_8_1', '阮日明', '我买三斤。啊，阿姨，西瓜和芒果怎么卖？', '我买三斤。啊，阿姨，西瓜和芒果怎么卖？', 'Wǒ mǎi sān jīn. A, āyí, xīguā hé mángguǒ zěnme mài?', 'Cháu mua ba cân ạ. À cô ơi, dưa hấu và xoài bán thế nào ạ?', 3) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_8_1_4', 'txt_8_1', '服务员', '西瓜一个十五块。芒果一斤七块。', '西瓜一个十五块。芒果一斤七块。', 'Xīguā yí gè shíwǔ kuài. Mángguǒ yī jīn qī kuài.', 'Dưa hấu 15 tệ một quả. Xoài 7 tệ một cân.', 4) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_8_1_5', 'txt_8_1', '阮日明', '芒果酸吗？', '芒果酸吗？', 'Mángguǒ suān ma?', 'Xoài có chua không ạ?', 5) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_8_1_6', 'txt_8_1', '服务员', '不太酸, 很好吃。还有木瓜和火龙果很甜，你要买什么吗？', '不 (bù: không)太酸, 很好吃。还 (hái: còn, vẫn)有木瓜和火龙果很甜，你要买什么吗？', 'Bú tài suān, hěn hǎo chī. Hái yǒu mùguā hé huǒlóng guǒ hěn tián, nǐ yào mǎi shénme ma?', 'Không chua lắm, ngon lắm. Còn có đu đủ và thanh long rất ngọt, cháu muốn mua thêm gì không?', 6) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_8_1_7', 'txt_8_1', '阮日明', '木瓜多少钱一个呢？', '木瓜多少钱一个呢？', 'Mùguā duōshao qián yí gè ne?', 'Đu đủ bao nhiêu tiền một quả vậy cô?', 7) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_8_1_8', 'txt_8_1', '服务员', '一个七块。', '一个七块。', 'Yí gè qī kuài.', 'Một quả 7 tệ.', 8) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_8_1_9', 'txt_8_1', '阮日明', '这里有果汁吗？', '这里 (lǐ: trong)有果汁吗？', 'Zhè li yǒu guǒzhī ma?', 'Ở đây có nước ép trái cây không ạ?', 9) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_8_1_10', 'txt_8_1', '服务员', '有啊，你要买什么果汁呢？', '有啊，你要买什么果汁呢？', 'Yǒu a, nǐ yāomǎi shénme guǒzhī ne?', 'Có chứ, cháu muốn mua nước ép gì nào?', 10) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_8_1_11', 'txt_8_1', '阮日明', '草莓果汁多少钱一杯？', '草莓果汁多少钱一杯？', 'Cǎoméi guǒzhī duōshao qián yī bēi?', 'Nước ép dâu tây bao nhiêu tiền một cốc ạ?', 11) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_8_1_12', 'txt_8_1', '服务员', '一杯六块。', '一杯六块。', 'Yī bēi liù kuài.', 'Một cốc 6 tệ.', 12) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_8_1_13', 'txt_8_1', '阮日明', '那我买三斤苹果、两个木瓜、一个西瓜和三杯草莓果汁。', '那我买三斤苹果、两 (liǎng: hai (số lượng))个木瓜、一个西瓜和三杯草莓果汁。', 'Nà wǒ mǎi sān jīn píngguǒ, liǎng gè mùguā, yí gè xīguā hé sān bēi cǎoméi guǒzhī.', 'Vậy cháu mua ba cân táo, hai quả đu đủ, một quả dưa hấu và ba cốc nước ép dâu tây ạ.', 13) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_8_1_14', 'txt_8_1', '服务员', '好。总共 53 块。', '好。总共 53 块。', 'Hǎo. Zǒnggòng 53 kuài.', 'Được rồi. Tổng cộng là 53 tệ.', 14) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_8_1_15', 'txt_8_1', '阮日明', '好，给你钱。', '好，给你钱。', 'Hǎo. Gěi nǐ qián.', 'Vâng, gửi cô tiền ạ.', 15) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_8_1_16', 'txt_8_1', '服务员', '这是 60 块，找你 7 块。谢谢！', '这是 60 块，找你 7 块。谢谢！', 'Zhè shì 60 kuài, zhǎo nǐ 7 kuài. Xièxie!', 'Đây là 60 tệ, trả lại cháu 7 tệ. Cảm ơn cháu!', 16) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_8_1_17', 'txt_8_1', '阮日明', '谢谢！', '谢谢！', 'Xièxie!', 'Cảm ơn cô ạ!', 17) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_8_1_1', 'lesson-8', 'txt_8_1', 'listening', 'listening', '阿姨，请问，一斤苹果多少钱？', NULL, 'Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Tôi sẽ không về nhà cùng với anh ta đâu.","Tôi học tiếng Hán được 3 năm.","Cô ơi, cho cháu hỏi một cân táo bao nhiêu tiền ạ?","Tôi dậy rất sớm."]'::jsonb, 2, 'Nội dung nghe được: 阿姨，请问，一斤苹果多少钱？ (Āyí, qǐngwèn, yī jīn píngguǒ duōshao qián?) → Cô ơi, cho cháu hỏi một cân táo bao nhiêu tiền ạ?', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_8_1_2', 'lesson-8', 'txt_8_1', 'listening', 'listening', '苹果很甜，一斤两块。你想买几斤？', NULL, 'Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["这里 (lǐ: trong)的水果怎么卖？","你买几个西瓜？","草莓果汁十块钱两 (liǎng: hai (số lượng))杯。","苹果很甜，一斤两 (liǎng: hai (số lượng))块。你想买几斤？"]'::jsonb, 3, 'Câu vừa đọc: 苹果很甜，一斤两块。你想买几斤？ (Píngguǒ hěn tián, yī jīn liǎng kuài. Nǐ xiǎng mǎi jǐ jīn?) → Táo ngọt lắm, một cân 2 tệ. Cháu muốn mua mấy cân?', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_8_1_3', 'lesson-8', 'txt_8_1', 'listening', 'listening', '我买三斤。啊，阿姨，西瓜和芒果怎么卖？', NULL, 'Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["tiếng gõ cửa","Một con ngựa","Anh ấy phải làm việc ở công ty từ 8 giờ sáng đến 5 giờ chiều.","Cháu mua ba cân ạ. À cô ơi, dưa hấu và xoài bán thế nào ạ?"]'::jsonb, 3, 'Nội dung nghe được: 我买三斤。啊，阿姨，西瓜和芒果怎么卖？ (Wǒ mǎi sān jīn. A, āyí, xīguā hé mángguǒ zěnme mài?) → Cháu mua ba cân ạ. À cô ơi, dưa hấu và xoài bán thế nào ạ?', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_8_1_4', 'lesson-8', 'txt_8_1', 'listening', 'listening', '西瓜一个十五块。芒果一斤七块。', NULL, 'Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["西瓜一个十五块。芒果一斤七块。","一个面包 (miànbāo: bánh mì)","一个人","我要一个西瓜，一共 (yígòng: tổng cộng)多少钱？"]'::jsonb, 0, 'Câu vừa đọc: 西瓜一个十五块。芒果一斤七块。 (Xīguā yí gè shíwǔ kuài. Mángguǒ yī jīn qī kuài.) → Dưa hấu 15 tệ một quả. Xoài 7 tệ một cân.', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO texts (id, lesson_id, title, description, sort_order) VALUES ('txt_8_2', 'lesson-8', 'Bài nghe tổng hợp: Ôn tập lũy tiến (Bài 1 – Bài 8)', 'Kết hợp từ vựng & mẫu câu đã học từ Bài 1 đến Bài 7 cùng trọng tâm Bài 8 để củng cố phản xạ nghe.', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
