INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss8_exp_1', 'lesson-8', '阿姨请问一斤苹果多少钱', 'Cô ơi, cho cháu hỏi một cân táo bao nhiêu tiền ạ?', 'Āyí, qǐngwèn, yī jīn píngguǒ duōshao qián?', '["阿姨","请问","一","斤","苹果","多少","钱"]'::jsonb, NULL, 7) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss8_exp_2', 'lesson-8', '苹果很甜一斤两块你想买几斤', 'Táo ngọt lắm, một cân 2 tệ. Cháu muốn mua mấy cân?', 'Píngguǒ hěn tián, yī jīn liǎng kuài. Nǐ xiǎng mǎi jǐ jīn?', '["苹果","很","甜","一","斤","两","块","你","想","买","几","斤"]'::jsonb, NULL, 8) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss8_exp_3', 'lesson-8', '我买三斤啊阿姨西瓜和芒果怎么卖', 'Cháu mua ba cân ạ. À cô ơi, dưa hấu và xoài bán thế nào ạ?', 'Wǒ mǎi sān jīn. A, āyí, xīguā hé mángguǒ zěnme mài?', '["我","买","三","斤","啊","阿姨","西瓜","和","芒果","怎么","卖"]'::jsonb, NULL, 9) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
