INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss8_exp_6', 'lesson-8', '不太酸很好吃还有木瓜和火龙果很甜你要买什么吗', 'Không chua lắm, ngon lắm. Còn có đu đủ và thanh long rất ngọt, cháu muốn mua thêm gì không?', 'Bú tài suān, hěn hǎo chī. Hái yǒu mùguā hé huǒlóng guǒ hěn tián, nǐ yào mǎi shénme ma?', '["不","太","酸","很","好吃","还","有","木瓜","和","火龙果","很","甜","你","要","买","什么","吗"]'::jsonb, NULL, 12) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
