INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr8_vi_1', 'lesson-8', 'vi_to_zh', '[Mở rộng] Cô ơi, táo hôm nay có ngọt không ạ?', NULL, NULL, '阿姨，今天的苹果甜不甜？', NULL, 'āyí jīntiān de píngguǒ tián bu tián', '[]'::jsonb, 'Gợi ý Pinyin: Āyí, jīntiān de píngguǒ tián bu tián? | Từ chưa học: 不 (bù: không)', 'Cô ơi, táo hôm nay có ngọt không ạ? → 阿姨，今天的苹果甜不甜？ (Āyí, jīntiān de píngguǒ tián bu tián?)', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr8_vi_2', 'lesson-8', 'vi_to_zh', '[Mở rộng] Cháu muốn mua hai cân thanh long và một cân xoài.', NULL, NULL, '我想买两斤火龙果和一斤芒果。', NULL, 'wǒ xiǎng mǎi liǎng jīn huǒlóngguǒ hé yì jīn mángguǒ', '[]'::jsonb, 'Gợi ý Pinyin: Wǒ xiǎng mǎi liǎng jīn huǒlóngguǒ hé yì jīn mángguǒ. | Từ chưa học: 两 (liǎng: hai (số lượng))', 'Cháu muốn mua hai cân thanh long và một cân xoài. → 我想买两斤火龙果和一斤芒果。 (Wǒ xiǎng mǎi liǎng jīn huǒlóngguǒ hé yì jīn mángguǒ.)', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
