INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr8_zh_exp_6', 'lesson-8', 'zh_to_vi', '给我一个西瓜和两斤火龙果，还要两杯草莓果汁。', '给我一个西瓜和两斤火龙果，还要两杯草莓果汁。', 'Gěi wǒ yígè xīguā hé liǎng jīn huǒlóngguǒ, hái yào liǎng bēi cǎoméi guǒzhī.', NULL, 'Lấy cho cháu một quả dưa hấu, hai cân thanh long và hai cốc nước ép dâu.', NULL, '["lấy","cho","cháu","một","quả","dưa","hấu","hai","cân","thanh","long","và","hai","cốc","nước","ép","dâu"]'::jsonb, 'Pinyin: Gěi wǒ yígè xīguā hé liǎng jīn huǒlóngguǒ, hái yào liǎng bēi cǎoméi guǒzhī.', '给我一个西瓜和两斤火龙果，还要两杯草莓果汁。 (Gěi wǒ yígè xīguā hé liǎng jīn huǒlóngguǒ, hái yào liǎng bēi cǎoméi guǒzhī.) nghĩa là: Lấy cho cháu một quả dưa hấu, hai cân thanh long và hai cốc nước ép dâu.', 24) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
