INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq8_13', 'lesson-8', NULL, 'expanded_quiz', 'radical', NULL, NULL, 'Chữ Hán “水果” chứa bộ thủ nào sau đây?', '["士 (Sĩ) (Người học thức, kẻ sĩ)","水/氵 (Thủy) (Nước, chất lỏng, sông ngòi)","曰 (Viết) (Nói rằng, lời nói)","米 (Mễ) (Hạt gạo, tinh bột)"]'::jsonb, 1, 'Chữ “水果” có bộ chính 水/氵 (Thủy) (Nước, chất lỏng, sông ngòi). Chiết tự: 水: Bộ 水 (Thủy - dòng nước chảy, chữ độc thể) • 果: 田 (Điền: trái tròn) + 木 (Mộc: trên ngọn cây)', 13) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq8_14', 'lesson-8', NULL, 'expanded_quiz', 'radical', NULL, NULL, 'Chữ Hán “苹果” chứa bộ thủ nào sau đây?', '["艹 (Thảo) (Cỏ cây, hoa lá, thảo mộc)","毛 (Mao) (Lông tóc, sợi mảnh)","而 (Nhi) (Mà, râu ria)","页 (Hiệt) (Đầu mặt, trang giấy)"]'::jsonb, 0, 'Chữ “苹果” có bộ chính 艹 (Thảo) (Cỏ cây, hoa lá, thảo mộc). Chiết tự: 苹: 艹 (Thảo: thực vật) + 平 (Bình) • 果: 田 (Điền: trái tròn) + 木 (Mộc: trên ngọn cây)', 14) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq8_15', 'lesson-8', NULL, 'expanded_quiz', 'radical', NULL, NULL, 'Chữ Hán “芒果” chứa bộ thủ nào sau đây?', '["疋/⺪ (Thất) (Cuộn vải, bàn chân)","贝 (Bối) (Vỏ sò, tiền bạc, giá trị)","丨 (Cổn) (Nét sổ thẳng, xuyên suốt)","艹 (Thảo) (Cỏ cây, hoa lá, thảo mộc)"]'::jsonb, 3, 'Chữ “芒果” có bộ chính 艹 (Thảo) (Cỏ cây, hoa lá, thảo mộc). Chiết tự: 芒: 艹 (Thảo: thực vật) + 亡 (Vong) • 果: 田 (Điền: trái tròn) + 木 (Mộc: trên ngọn cây)', 15) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq8_16', 'lesson-8', NULL, 'expanded_quiz', 'radical', NULL, NULL, 'Chữ Hán “西瓜” chứa bộ thủ nào sau đây?', '["毛 (Mao) (Lông tóc, sợi mảnh)","耳 (Nhĩ) (Cái tai, lắng nghe)","西/覀 (Tây) (Phương tây, che đậy)","风 (Phong) (Cơn gió, phong cách)"]'::jsonb, 2, 'Chữ “西瓜” có bộ chính 西/覀 (Tây) (Phương tây, che đậy). Chiết tự: 西: Bộ 西 (Tây - chim về tổ lúc mặt trời lặn) • 瓜: Bộ 瓜 (Qua - trái dưa treo trên giàn leo)', 16) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq8_17', 'lesson-8', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, '[Ôn tập Bài 7] Từ đã học “蓝色” (lán sè) có nghĩa là gì?', '["hỏi","màu xanh lam","ở giữa, chính giữa","đừng khách sáo"]'::jsonb, 1, 'Ôn tập Bài 7: “蓝色” (lán sè) nghĩa là: màu xanh lam.', 17) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq8_18', 'lesson-8', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, '[Ôn tập Bài 5] Từ đã học “八” (bā) có nghĩa là gì?', '["anh ấy, cậu ấy... (ngôi thứ ba số ít chỉ nam)","chua","tám","ở đâu"]'::jsonb, 2, 'Ôn tập Bài 5: “八” (bā) nghĩa là: tám.', 18) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq8_19', 'lesson-8', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, '[Ôn tập Bài 5] Từ đã học “门” (mén) có nghĩa là gì?', '["cửa, cổng","Canada","bảy","chua"]'::jsonb, 0, 'Ôn tập Bài 5: “门” (mén) nghĩa là: cửa, cổng.', 19) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq8_20', 'lesson-8', NULL, 'expanded_quiz', 'reading', NULL, NULL, '[Mở rộng] Câu “阿姨，今天的苹果甜不 (bù: không)甜？” có nghĩa tiếng Việt là gì?', '["Cô ơi, táo hôm nay có ngọt không ạ?","Lớp cậu có bao nhiêu học sinh?","Tôi muốn đi siêu thị mua một chút đồ.","Một căn nhà"]'::jsonb, 0, '阿姨，今天的苹果甜不甜？ (Āyí, jīntiān de píngguǒ tián bu tián?) → Cô ơi, táo hôm nay có ngọt không ạ?', 20) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
