INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct8_22', 'lesson-8', NULL, 'comprehensive_test', 'listening', '阿姨，请问西瓜和火龙果怎么卖？ 西瓜十二块钱一个，火龙果八块钱一斤。 给我一个西瓜和两斤火龙果，还要两杯草莓果汁。 果汁五块钱一杯，一共三十八块钱。', NULL, 'Lan đã mua tất cả những thứ gì?', '["Chỉ mua 2 cân xoài","2 quả đu đủ và 1 cốc nước ép","3 cân táo và 1 quả dưa hấu","1 quả dưa hấu, 2 cân thanh long và 2 cốc nước ép dâu"]'::jsonb, 3, 'Lan gọi rõ ''一个西瓜和两斤火龙果，还要两杯草莓果汁''.', 22) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
