INSERT INTO lessons (id, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id) VALUES ('lesson-9', 'Bài 9: Mua quần áo - Đơn nguyên 2: Mua sắm', 'Bài 9', 'Đơn nguyên 2: Mua sắm', 'Trang phục, kích cỡ, màu sắc, thử đồ, câu so sánh hơn 比 và phó từ 太... 了.', '2026-11-14'::date, 9, TRUE, NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, date_added = EXCLUDED.date_added, sort_order = EXCLUDED.sort_order, is_system = TRUE, updated_at = NOW();
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v9_1', 'lesson-9', '超市', 'chāoshì', 'siêu thị', 'siêu thị', 'Danh từ', '走 (Tẩu) (Chạy, đi lại, rời đi)', '超: 走 (Tẩu: chạy) + 召 (Triệu: vượt qua) • 市: 亠 (Đầu) + 巾 (Cân: lều vải nơi chợ búa)', 'Ghép 超 [bộ 走] + 市 [bộ 巾] để nhớ từ 超市 (chāoshì): "siêu thị".', '我想来超市买一些东西。', 'Wǒ xiǎng lái chāoshì mǎi yīxiē dōngxi.', 'Tôi muốn đi siêu thị mua một chút đồ.', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v9_2', 'lesson-9', '售货员', 'shòuhuòyuán', 'từ Hán ngữ', 'nhân viên bán hàng', 'Danh từ', '口 (Khẩu) (Miệng, ăn uống, lời nói, âm thanh phát ra)', '售: 隹 (Chuy) + 口 (Khẩu: rao bán hàng) • 货: 化 (Hóa) + 贝 (Bối: hàng hóa quy thành tiền) • 员: 口 (Khẩu) + 贝 (Bối: người làm công việc)', 'Ghép 售 [bộ 口] + 货 [bộ 贝] + 员 [bộ 口] để nhớ từ 售货员 (shòuhuòyuán): "nhân viên bán hàng".', '这是关于“售货员”的常用句子。', 'Zhè shì guānyú ''shòuhuòyuán'' de chángyòng jùzi.', 'Đây là câu ví dụ sử dụng từ ''售货员'' (nhân viên bán hàng).', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v9_3', 'lesson-9', '衣服', 'yīfu', 'y phục', 'quần áo', 'Danh từ', '衣/衤 (Y) (Áo quần, y phục)', '衣: Bộ 衣 (Y - cổ áo và vạt áo, chữ độc thể) • 服: 月 (Nguyệt) + 卩 + 又 (trang phục vừa vặn)', 'Ghép 衣 [bộ 衣] + 服 [bộ 月] để nhớ từ 衣服 (yīfu): "quần áo".', '小兰！你跟我一起去超市买衣服，好吗？', 'Xiǎolán, nǐ gēn wǒ yīqǐ qù chāoshì mǎi yīfu, hǎo ma?', 'Tiểu Lan! Cậu đi siêu thị mua quần áo cùng tớ nhé, được không?', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v9_4', 'lesson-9', '裤子', 'kùzi', 'từ Hán ngữ', 'quần', 'Danh từ', '衣/衤 (Y) (Áo quần, y phục)', '裤: 衤 (Y: áo quần) + 库 (Khố: mượn âm) • 子: Bộ 子 (Tử - đứa trẻ dang tay, chữ độc thể)', 'Ghép 裤 [bộ 衤] + 子 [bộ 子] để nhớ từ 裤子 (kùzi): "quần".', '我想买一条裤子，一条裙子和一件大衣。', 'Wǒ xiǎng mǎi yī tiáo kùzi, yī tiáo qúnzi hé yī jiàn dàyī.', 'Tớ muốn mua một chiếc quần dài, một chiếc váy và một chiếc áo khoác dài.', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v9_5', 'lesson-9', '裙子', 'qúnzi', 'từ Hán ngữ', 'váy', 'Danh từ', '衣/衤 (Y) (Áo quần, y phục)', '裙: 衤 (Y: áo quần) + 君 (Quân: mượn âm) • 子: Bộ 子 (Tử - đứa trẻ dang tay, chữ độc thể)', 'Ghép 裙 [bộ 衤] + 子 [bộ 子] để nhớ từ 裙子 (qúnzi): "váy".', '我想买一条裤子，一条裙子和一件大衣。', 'Wǒ xiǎng mǎi yī tiáo kùzi, yī tiáo qúnzi hé yī jiàn dàyī.', 'Tớ muốn mua một chiếc quần dài, một chiếc váy và một chiếc áo khoác dài.', 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v9_6', 'lesson-9', '大衣', 'dàyī', 'đại y', 'áo khoác', 'Danh từ', '大 (Đại) (To lớn, vĩ đại)', '大: Bộ 大 (Đại - người dang rộng tay chân, chữ độc thể) • 衣: Bộ 衣 (Y - cổ áo và vạt áo, chữ độc thể)', 'Ghép 大 [bộ 大] + 衣 [bộ 衣] để nhớ từ 大衣 (dàyī): "áo khoác".', '我想买一条裤子，一条裙子和一件大衣。', 'Wǒ xiǎng mǎi yī tiáo kùzi, yī tiáo qúnzi hé yī jiàn dàyī.', 'Tớ muốn mua một chiếc quần dài, một chiếc váy và một chiếc áo khoác dài.', 6) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v9_7', 'lesson-9', '颜色', 'yánsè', 'nhan sắc', 'màu sắc', 'Danh từ', '页 (Hiệt) (Đầu mặt, trang giấy)', '颜: 彦 (Ngạn) + 页 (Hiệt: khuôn mặt, sắc diện) • 色: Bộ 色 (Sắc - ⺈ + 巴, sắc mặt, màu sắc)', 'Ghép 颜 [bộ 页] + 色 [bộ 色] để nhớ từ 颜色 (yánsè): "màu sắc".', '我觉得颜色不太好看，我不喜欢绿色，我最喜欢红色和黄色。', 'Wǒ juéde yánsè bú tài hǎokàn, wǒ bù xǐhuan lǜsè, wǒ zuì xǐhuan hóngsè hé huángsè.', 'Tớ thấy màu sắc không đẹp lắm, tớ không thích màu xanh lá, tớ thích nhất màu đỏ và màu vàng.', 7) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v9_8', 'lesson-9', '绿色', 'lǜsè', 'lục sắc', 'màu xanh lá', 'Danh từ', '糸/纟 (Mịch) (Sợi tơ, gắn kết, màu sắc)', '绿: 纟 (Mịch: sợi tơ nhuộm màu) + 录 (Lục) • 色: Bộ 色 (Sắc - ⺈ + 巴, sắc mặt, màu sắc)', 'Ghép 绿 [bộ 纟] + 色 [bộ 色] để nhớ từ 绿色 (lǜsè): "màu xanh lá".', '我觉得颜色不太好看，我不喜欢绿色，我最喜欢红色和黄色。', 'Wǒ juéde yánsè bú tài hǎokàn, wǒ bù xǐhuan lǜsè, wǒ zuì xǐhuan hóngsè hé huángsè.', 'Tớ thấy màu sắc không đẹp lắm, tớ không thích màu xanh lá, tớ thích nhất màu đỏ và màu vàng.', 8) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v9_9', 'lesson-9', '红色', 'hóngsè', 'hồng sắc', 'màu đỏ', 'Danh từ', '糸/纟 (Mịch) (Sợi tơ, gắn kết, màu sắc)', '红: 纟 (Mịch: sợi tơ nhuộm đỏ) + 工 (Công) • 色: Bộ 色 (Sắc - ⺈ + 巴, sắc mặt, màu sắc)', 'Ghép 红 [bộ 纟] + 色 [bộ 色] để nhớ từ 红色 (hóngsè): "màu đỏ".', '我觉得颜色不太好看，我不喜欢绿色，我最喜欢红色和黄色。', 'Wǒ juéde yánsè bú tài hǎokàn, wǒ bù xǐhuan lǜsè, wǒ zuì xǐhuan hóngsè hé huángsè.', 'Tớ thấy màu sắc không đẹp lắm, tớ không thích màu xanh lá, tớ thích nhất màu đỏ và màu vàng.', 9) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v9_10', 'lesson-9', '粉红色', 'fěnhóngsè', 'hồng sắc', 'màu hồng phấn', 'Danh từ', '米 (Mễ) (Hạt gạo, tinh bột)', '粉: 米 (Mễ: hạt gạo) + 分 (Phân: nghiền nhỏ thành bột/phấn) • 红: 纟 (Mịch: sợi tơ nhuộm đỏ) + 工 (Công) • 色: Bộ 色 (Sắc - ⺈ + 巴, sắc mặt, màu sắc)', 'Ghép 粉 [bộ 米] + 红 [bộ 纟] + 色 [bộ 色] để nhớ từ 粉红色 (fěnhóngsè): "màu hồng phấn".', '很好看，我买这件黄色的大衣和这条粉红色的裙子。你觉得这件大衣贵不贵？', 'Hěn hǎokàn, wǒ mǎi zhè jiàn huángsè de dàyī hé zhè tiáo fěnhóngsè de qúnzi. Nǐ juéde zhè jiàn dàyī guì bu guì?', 'Đẹp lắm, tớ sẽ mua chiếc áo khoác màu vàng này và chiếc váy màu hồng này. Cậu thấy chiếc áo khoác này có đắt không?', 10) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v9_11', 'lesson-9', '试', 'shì', 'thí', 'thử', 'Động từ', '言/讠 (Ngôn) (Lời nói, ngôn ngữ, giao tiếp)', '试 = 讠 (Ngôn: lời hỏi) + 式 (Thức: phép thử).', 'Chữ 试 (shì) mang nghĩa "thử", bộ chính 言/讠 (Ngôn); cấu tạo: 讠 (Ngôn: lời hỏi) + 式 (Thức: phép thử).', '那这条红色的裤子行吗？你试试看！', 'Nà zhè tiáo hóngsè de kùzi xíng ma? Nǐ shìshi kàn!', 'Vậy chiếc quần màu đỏ này có được không? Cậu mặc thử xem!', 11) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v9_12', 'lesson-9', '结账', 'jié zhàng', 'từ Hán ngữ', 'thanh toán', 'Động từ', '糸/纟 (Mịch) (Sợi tơ, gắn kết, màu sắc)', '结: 纟 (Mịch: sợi dây buộc lại) + 吉 (Cát) • 账: 贝 (Bối: tiền bạc sổ sách) + 长 (Trường)', 'Ghép 结 [bộ 纟] + 账 [bộ 贝] để nhớ từ 结账 (jié zhàng): "thanh toán".', '好的，我们去结账吧！', 'Hǎo de, wǒmen qù jiézhàng ba!', 'Được rồi, chúng ta đi thanh toán thôi!', 12) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v9_13', 'lesson-9', '喜欢', 'xǐ huān', 'hoan', 'thích', 'Động từ', '口 (Khẩu) (Miệng, ăn uống, lời nói, âm thanh phát ra)', '喜: 壴 (Trú: tiếng trống) + 口 (Khẩu: miệng cười vui) • 欢: 又 (Hựu) + 欠 (Khiếm: reo vui)', 'Ghép 喜 [bộ 口] + 欢 [bộ 欠] để nhớ từ 喜欢 (xǐ huān): "thích".', '他最喜欢打篮球。', 'Tā zuì xǐhuān dǎ lánqiú.', 'Anh ấy thích chơi bóng rổ nhất.', 13) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v9_14', 'lesson-9', '不错', 'bùcuò', 'từ Hán ngữ', 'được, tốt, không tồi', 'Tính từ', '一 (Nhất) (Số một, nền tảng, nét ngang cơ bản)', '不: 一 (Nhất) + 丿 + 丨 + 丶 (chữ độc thể phủ định) • 错: 钅 (Kim) + 昔 (Tích)', 'Ghép 不 [bộ 一] + 错 [bộ 钅] để nhớ từ 不错 (bùcuò): "được, tốt, không tồi".', '不错，很合适。我买这条吧！', 'Búcuò, hěn héshì. Wǒ mǎi zhè tiáo ba!', 'Khá ổn, rất vừa vặn. Tớ mua chiếc này nhé!', 14) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v9_15', 'lesson-9', '合适', 'héshì', 'hợp thích', 'vừa vặn, thích hợp, vừa', 'Tính từ', '口 (Khẩu) (Miệng, ăn uống, lời nói, âm thanh phát ra)', '合: 人 (Nhân) + 一 + 口 (Khẩu: nắp đậy vừa khít) • 适: 舌 (Thiệt) + 辶 (Sước: đi đến nơi phù hợp)', 'Ghép 合 [bộ 口] + 适 [bộ 辶] để nhớ từ 合适 (héshì): "vừa vặn, thích hợp, vừa".', '不错，很合适。我买这条吧！', 'Búcuò, hěn héshì. Wǒ mǎi zhè tiáo ba!', 'Khá ổn, rất vừa vặn. Tớ mua chiếc này nhé!', 15) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v9_16', 'lesson-9', '贵', 'guì', 'quý', 'đắt', 'Tính từ', '贝 (Bối) (Vỏ sò, tiền bạc, giá trị)', '贵 = 中 (Trung biến thể) + 一 + 贝 (Bối: tiền bạc quý giá).', 'Chữ 贵 (guì) mang nghĩa "đắt", bộ chính 贝 (Bối); cấu tạo: 中 (Trung biến thể) + 一 + 贝 (Bối: tiền bạc quý giá).', '很好看，我买这件黄色的大衣和这条粉红色的裙子。你觉得这件大衣贵不贵？', 'Hěn hǎokàn, wǒ mǎi zhè jiàn huángsè de dàyī hé zhè tiáo fěnhóngsè de qúnzi. Nǐ juéde zhè jiàn dàyī guì bu guì?', 'Đẹp lắm, tớ sẽ mua chiếc áo khoác màu vàng này và chiếc váy màu hồng này. Cậu thấy chiếc áo khoác này có đắt không?', 16) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v9_17', 'lesson-9', '便宜', 'piányi', 'tiện nghi', 'rẻ', 'Tính từ', '人/亻 (Nhân) (Con người, nhân loại, hành động)', '便: 亻 (Nhân đứng) + 更 (Canh) • 宜: 宀 (Miên: mái nhà) + 且 (Thả: thích hợp)', 'Ghép 便 [bộ 亻] + 宜 [bộ 宀] để nhớ từ 便宜 (piányi): "rẻ".', '我觉得不贵，很便宜!', 'Wǒ juéde bú guì, hěn piányi!', 'Tớ thấy không đắt đâu, rất rẻ!', 17) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v9_18', 'lesson-9', '新', 'xīn', 'tân', 'mới', 'Tính từ', '斤 (Cân) (Cái rìu, đơn vị cân nặng)', '新 = 立 + 木 (Tân) + 斤 (Cân: rìu chặt gỗ mới).', 'Chữ 新 (xīn) mang nghĩa "mới", bộ chính 斤 (Cân); cấu tạo: 立 + 木 (Tân) + 斤 (Cân: rìu chặt gỗ mới).', '这是关于“新”的常用句子。', 'Zhè shì guānyú ''xīn'' de chángyòng jùzi.', 'Đây là câu ví dụ sử dụng từ ''新'' (mới).', 18) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v9_19', 'lesson-9', '旧', 'jiù', 'cựu', 'cũ', 'Tính từ', '日 (Nhật) (Mặt trời, ban ngày, thời gian, ánh sáng)', '旧 = 丨 (Cổn) + 日 (Nhật: đồ cũ lâu ngày).', 'Chữ 旧 (jiù) mang nghĩa "cũ", bộ chính 日 (Nhật); cấu tạo: 丨 (Cổn) + 日 (Nhật: đồ cũ lâu ngày).', '这是关于“旧”的常用句子。', 'Zhè shì guānyú ''jiù'' de chángyòng jùzi.', 'Đây là câu ví dụ sử dụng từ ''旧'' (cũ).', 19) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v9_20', 'lesson-9', '一共', 'yígòng', 'cộng', 'tổng cộng', 'Phó từ', '一 (Nhất) (Số một, nền tảng, nét ngang cơ bản)', '一: Bộ 一 (Nhất - 1 nét ngang, số 1) • 共: 廿 (Nhấp) + 一 + 八 (Bát: hai tay cùng nâng)', 'Ghép 一 [bộ 一] + 共 [bộ 八] để nhớ từ 一共 (yígòng): "tổng cộng".', '好的，一共 150 块。', 'Hǎo de, yígòng 150 kuài.', 'Vâng, tổng cộng 150 tệ ạ.', 20) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v9_21', 'lesson-9', '最', 'zuì', 'từ Hán ngữ', 'nhất', 'Phó từ', '日 (Nhật) (Mặt trời, ban ngày, thời gian, ánh sáng)', '最 = 日 (Nhật) + 取 (Thủ: đoạt giải nhất).', 'Chữ 最 (zuì) mang nghĩa "nhất", bộ chính 日 (Nhật); cấu tạo: 日 (Nhật) + 取 (Thủ: đoạt giải nhất).', '他最喜欢打篮球。', 'Tā zuì xǐhuān dǎ lánqiú.', 'Anh ấy thích chơi bóng rổ nhất.', 21) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v9_22', 'lesson-9', '条', 'tiáo', 'từ Hán ngữ', 'cái, chiếc,..lượng từ của quần, váy', 'Lượng từ', '木 (Mộc) (Cây cối, gỗ, thực vật)', '条 = 夂 (Trĩ) + 木 (Mộc: nhánh cây thuôn dài).', 'Chữ 条 (tiáo) mang nghĩa "cái, chiếc,..lượng từ của quần, váy", bộ chính 木 (Mộc); cấu tạo: 夂 (Trĩ) + 木 (Mộc: nhánh cây thuôn dài).', '我想买一条裤子，一条裙子和一件大衣。', 'Wǒ xiǎng mǎi yī tiáo kùzi, yī tiáo qúnzi hé yī jiàn dàyī.', 'Tớ muốn mua một chiếc quần dài, một chiếc váy và một chiếc áo khoác dài.', 22) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v9_23', 'lesson-9', '一下儿', 'yíxiàr', 'hạ nhi', 'một chút, một lát', 'Lượng từ', '一 (Nhất) (Số một, nền tảng, nét ngang cơ bản)', '一: Bộ 一 (Nhất - 1 nét ngang, số 1) • 下: Nét ngang 一 phía trên nét sổ 丨 và chấm chỉ hướng xuống dưới • 儿: Bộ 儿 (Nhi - nét cong, chữ độc thể)', 'Ghép 一 [bộ 一] + 下 [bộ 一] + 儿 [bộ 儿] để nhớ từ 一下儿 (yíxiàr): "một chút, một lát".', '你好，请给我们结一下儿账！', 'Nǐ hǎo, qǐng gěi wǒmen jié yíxiàr zhàng!', 'Chào bạn, làm ơn thanh toán giúp bọn mình nhé!', 23) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v9_24', 'lesson-9', '吧', 'ba', 'từ Hán ngữ', 'đi, nhé,…', 'Trợ từ', '口 (Khẩu) (Miệng, ăn uống, lời nói, âm thanh phát ra)', '吧 = 口 (Khẩu: ngữ khí cuối câu) + 巴 (Ba).', 'Chữ 吧 (ba) mang nghĩa "đi, nhé,…", bộ chính 口 (Khẩu); cấu tạo: 口 (Khẩu: ngữ khí cuối câu) + 巴 (Ba).', '我们一起去那边吧！', 'Wǒmen yīqǐ qù nàbian ba!', 'Chúng ta cùng qua bên đó xem đi!', 24) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v9_25', 'lesson-9', '那么', 'nàme', 'na ma', 'thế thì, vậy thì, trong trường hợp ấy', 'Liên từ', '阝 (Phụ/Ấp) (Gò đất hoặc vùng đất, thành ấp)', '那: 𠃌 + 二 + 阝 (Ấp: vùng đất xa) • 么: 丿 (Phiệt) + 厶 (Tư)', 'Ghép 那 [bộ 阝] + 么 [bộ 丿] để nhớ từ 那么 (nàme): "thế thì, vậy thì, trong trường hợp ấy".', '这是关于“那么”的常用句子。', 'Zhè shì guānyú ''nàme'' de chángyòng jùzi.', 'Đây là câu ví dụ sử dụng từ ''那么'' (thế thì, vậy thì, trong trường hợp ấy).', 25) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order) VALUES ('g9_1', 'lesson-9', '1. A 跟/和 B 一起 + Động từ + Tân ngữ', 'Cấu trúc câu ngữ pháp trọng tâm', ' Đây là cấu trúc biểu thị ý nghĩa A và B cùng nhau thực hiện hành vi, động tác gì đó. 明天我跟小林一起去旅游。 Míngtiān wǒ gēn Xiǎo Lín yīqǐ qù lǚyóu. Ngày mai tôi sẽ đi du lịch với Lâm. 我不会跟他一起回家。 Wǒ bú huì gēn tā yīqǐ huí jiā. Tôi sẽ không về nhà cùng với anh ', NULL, '[{"hanzi":"明天我跟小林一起去旅游。","pinyin":"Míngtiān wǒ gēn Xiǎo Lín yīqǐ qù lǚyóu.","meaning":"Ngày mai tôi sẽ đi du lịch với Lâm."},{"hanzi":"我不会跟他一起回家。","pinyin":"Wǒ bú huì gēn tā yīqǐ huí jiā.","meaning":"Tôi sẽ không về nhà cùng với anh ta đâu."}]'::jsonb, 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order) VALUES ('g9_2', 'lesson-9', '2. 连动词 – Câu liên động', '去/来 + Địa điểm + Động từ', ' Câu mà có thành phần vị ngữ do hai động từ, cụm động từ trở lên tạo thành và có chung chủ ngữ gọi là câu liên động. Câu liên động biểu thị mục đích và phương thức của hành vi động tác: - Biểu đạt mục đích của hành động: Trong đó, động từ thứ nhất th', NULL, '[{"hanzi":"你可以跟我一起去买帽子吗？","pinyin":"Nǐ kěyǐ gēn wǒ yīqǐ qù mǎi màozi ma?","meaning":"Bạn có thể đi mua mũ cùng với tôi không?"},{"hanzi":"他去北京留学。","pinyin":"Tā qù Běijīng liúxué.","meaning":"Anh ấy đi du học ở Bắc Kinh."}]'::jsonb, 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order) VALUES ('g9_3', 'lesson-9', '3. 最', '最 + Động từ tâm lý, cảm xúc /Tính từ', ' 最 là phó từ chỉ mức độ được dùng trong so sánh nhất, biểu thị chủ thể của 最 có tính chất hay trạng thái nào đó vượt qua tất cả người hoặc sự vật cùng loại, đạt đến đỉnh cao nhất trong phạm vi so sánh. 最 có thể đứng trước tính từ, động từ tâm lý... 他', NULL, '[{"hanzi":"我想来超市买一些东西。","pinyin":"Wǒ xiǎng lái chāoshì mǎi yīxiē dōngxi.","meaning":"Tôi muốn đi siêu thị mua một chút đồ."},{"hanzi":"她去银行取钱了。","pinyin":"Tā qù yínháng qǔqián le.","meaning":"Chị ấy đi ngân hàng rút tiền rồi."}]'::jsonb, 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order) VALUES ('g9_4', 'lesson-9', '4. Dạng câu hỏi chính phản của động từ, tính từ', 'Cấu trúc câu ngữ pháp trọng tâm', ' A 不 A? Đây là dạng câu hỏi chính phản, ý nghĩa tương đương với “A 吗？”, trong đó A làm động từ hoặc một tính từ. 那家商店的东西贵不贵？                  = 那家商店的东西贵吗？ Nà jiā shāngdiàn de dōngxi guì bu guì? = Nà jiā shāngdiàn de dōngxi guì ma? Đồ của cửa hàng đó ', NULL, '[{"hanzi":"小林去英国旅游过一次。","pinyin":"Xiǎolín qù Yīngguó lǚyóuguo yícì.","meaning":"Lâm từng đi Anh du lịch một lần."},{"hanzi":"我用法语跟小芳谈话。","pinyin":"Wǒ yòng Fǎyǔ gēn Xiǎofāng tánhuà.","meaning":"Tôi dùng tiếng Pháp nói chuyện với Phương."}]'::jsonb, 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order;
INSERT INTO texts (id, lesson_id, title, description, sort_order) VALUES ('txt_9_1', 'lesson-9', 'Bài khoá #1: Hội thoại giáo trình — Mua quần áo', 'Hội thoại chuẩn giáo trình Bài 9. Từ vựng chưa học được chú thích phiên âm & nghĩa trong ngoặc.', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_9_1_1', 'txt_9_1', '白茹雪', '小兰！你跟我一起去超市买衣服，好吗？', '小兰！你跟 (gēn: cùng, với)我一起去超市买衣服，好吗？', 'Xiǎolán, nǐ gēn wǒ yīqǐ qù chāoshì mǎi yīfu, hǎo ma?', 'Tiểu Lan! Cậu đi siêu thị mua quần áo cùng tớ nhé, được không?', 1) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_9_1_2', 'txt_9_1', '范玉兰', '好啊。', '好啊。', 'Hǎo a.', 'Được chứ.', 2) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_9_1_3', 'txt_9_1', '范玉兰', '你想买什么衣服？', '你想买什么衣服？', 'Nǐ xiǎng mǎi shénme yīfu?', 'Cậu muốn mua quần áo gì?', 3) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_9_1_4', 'txt_9_1', '白茹雪', '我想买一条裤子，一条裙子和一件大衣。', '我想买一条裤子，一条裙子和一件 (jiàn: cái, chiếc (áo, việc))大衣。', 'Wǒ xiǎng mǎi yī tiáo kùzi, yī tiáo qúnzi hé yī jiàn dàyī.', 'Tớ muốn mua một chiếc quần dài, một chiếc váy và một chiếc áo khoác dài.', 4) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_9_1_5', 'txt_9_1', '范玉兰', '你觉得这条裤子好不好看？', '你觉得这条裤子好不 (bù: không)好看？', 'Nǐ juéde zhè tiáo kùzi hǎo bu hǎokàn?', 'Cậu thấy chiếc quần này có đẹp không?', 5) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_9_1_6', 'txt_9_1', '白茹雪', '我觉得颜色不太好看，我不喜欢绿色，我最喜欢红色和黄色。', '我觉得颜色不 (bù: không)太好看，我不喜欢绿色，我最喜欢红色和黄色。', 'Wǒ juéde yánsè bú tài hǎokàn, wǒ bù xǐhuan lǜsè, wǒ zuì xǐhuan hóngsè hé huángsè.', 'Tớ thấy màu sắc không đẹp lắm, tớ không thích màu xanh lá, tớ thích nhất màu đỏ và màu vàng.', 6) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_9_1_7', 'txt_9_1', '范玉兰', '那这条红色的裤子行吗？你试试看！', '那这条红色的裤子行 (xíng: được)吗？你试试看！', 'Nà zhè tiáo hóngsè de kùzi xíng ma? Nǐ shìshi kàn!', 'Vậy chiếc quần màu đỏ này có được không? Cậu mặc thử xem!', 7) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_9_1_8', 'txt_9_1', '白茹雪', '不错，很合适。我买这条吧！', '不错，很合适。我买这条吧！', 'Búcuò, hěn héshì. Wǒ mǎi zhè tiáo ba!', 'Khá ổn, rất vừa vặn. Tớ mua chiếc này nhé!', 8) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_9_1_9', 'txt_9_1', '范玉兰', '你看，那边是大衣和裙子，好漂亮啊！', '你看，那边 (biān: bên, phía)是大衣和裙子，好漂亮啊！', 'Nǐ kàn, nàbian shì dàyī hé qúnzi, hǎo piàoliang a!', 'Cậu nhìn kìa, bên kia là áo khoác và váy, đẹp quá đi!', 9) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_9_1_10', 'txt_9_1', '白茹雪', '很好看，我买这件黄色的大衣和这条粉红色的裙子。你觉得这件大衣贵不贵？', '很好看，我买这件 (jiàn: cái, chiếc (áo, việc))黄色的大衣和这条粉红色的裙子。你觉得这件大衣贵不 (bù: không)贵？', 'Hěn hǎokàn, wǒ mǎi zhè jiàn huángsè de dàyī hé zhè tiáo fěnhóngsè de qúnzi. Nǐ juéde zhè jiàn dàyī guì bu guì?', 'Đẹp lắm, tớ sẽ mua chiếc áo khoác màu vàng này và chiếc váy màu hồng này. Cậu thấy chiếc áo khoác này có đắt không?', 10) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_9_1_11', 'txt_9_1', '范玉兰', '我觉得不贵，很便宜!', '我觉得不 (bù: không)贵，很便宜!', 'Wǒ juéde bú guì, hěn piányi!', 'Tớ thấy không đắt đâu, rất rẻ!', 11) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_9_1_12', 'txt_9_1', '白茹雪', '好的，我们去结账吧！', '好的，我们去结账吧！', 'Hǎo de, wǒmen qù jiézhàng ba!', 'Được rồi, chúng ta đi thanh toán thôi!', 12) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_9_1_13', 'txt_9_1', '白茹雪', '你好，请给我们结一下儿账！', '你好，请给我们结一下儿账！', 'Nǐ hǎo, qǐng gěi wǒmen jié yíxiàr zhàng!', 'Chào bạn, làm ơn thanh toán giúp bọn mình nhé!', 13) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_9_1_14', 'txt_9_1', '售货员', '好的，一共 150 块。', '好的，一共 150 块。', 'Hǎo de, yígòng 150 kuài.', 'Vâng, tổng cộng 150 tệ ạ.', 14) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_9_1_15', 'txt_9_1', '白茹雪', '给你，谢谢!', '给你，谢谢!', 'Gěi nǐ, xièxie!', 'Gửi bạn tiền, cảm ơn nhé!', 15) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_9_1_16', 'txt_9_1', '售货员', '谢谢你们！', '谢谢你们！', 'Xièxie nǐmen!', 'Cảm ơn hai bạn!', 16) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_9_1_1', 'lesson-9', 'txt_9_1', 'listening', 'listening', '小兰！你跟我一起去超市买衣服，好吗？', NULL, 'Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Bye! (thường dùng trong giới trẻ)","Cậu ấy ngủ suốt chín tiếng đồng hồ.","Tiểu Lan! Cậu đi siêu thị mua quần áo cùng tớ nhé, được không?","Năm nay bác tôi 56 tuổi, bác cậu thì sao?"]'::jsonb, 2, 'Nội dung nghe được: 小兰！你跟我一起去超市买衣服，好吗？ (Xiǎolán, nǐ gēn wǒ yīqǐ qù chāoshì mǎi yīfu, hǎo ma?) → Tiểu Lan! Cậu đi siêu thị mua quần áo cùng tớ nhé, được không?', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_9_1_2', 'lesson-9', 'txt_9_1', 'listening', 'listening', '好啊。', NULL, 'Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["小兰！你跟 (gēn: cùng, với)我一起去超市买衣服，好吗？","我不 (bù: không)会 (huì: Phó, đtnn biết)跟 (gēn: cùng, với)他一起回家。","他是班里 (bān li: trong lớp)最高 (gāo: cao)的同学。","好啊。"]'::jsonb, 3, 'Câu vừa đọc: 好啊。 (Hǎo a.) → Được chứ.', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_9_1_3', 'lesson-9', 'txt_9_1', 'listening', 'listening', '你想买什么衣服？', NULL, 'Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Được rồi, tôi đồng ý, cậu đừng nói lại nữa!","Cậu muốn mua quần áo gì?","Bạn đã chuẩn bị đầy đủ đồ đạc để đi du lịch chưa?","Năm nay cháu mấy tuổi rồi?"]'::jsonb, 1, 'Nội dung nghe được: 你想买什么衣服？ (Nǐ xiǎng mǎi shénme yīfu?) → Cậu muốn mua quần áo gì?', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_9_1_4', 'lesson-9', 'txt_9_1', 'listening', 'listening', '我想买一条裤子，一条裙子和一件大衣。', NULL, 'Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["我想来 (lái: đến)超市买一些 (yīxiē: một ít, một vài)东西。","我想买一条裤子，一条裙子和一件 (jiàn: cái, chiếc (áo, việc))大衣。","他是班里 (bān li: trong lớp)最高 (gāo: cao)的同学。","她去银行 (xíng: được)取 (qǔ: lấy)钱了。"]'::jsonb, 1, 'Câu vừa đọc: 我想买一条裤子，一条裙子和一件大衣。 (Wǒ xiǎng mǎi yī tiáo kùzi, yī tiáo qúnzi hé yī jiàn dàyī.) → Tớ muốn mua một chiếc quần dài, một chiếc váy và một chiếc áo khoác dài.', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO texts (id, lesson_id, title, description, sort_order) VALUES ('txt_9_2', 'lesson-9', 'Bài nghe tổng hợp: Ôn tập lũy tiến (Bài 1 – Bài 9)', 'Kết hợp từ vựng & mẫu câu đã học từ Bài 1 đến Bài 8 cùng trọng tâm Bài 9 để củng cố phản xạ nghe.', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_9_2_1', 'txt_9_2', 'Ôn Bài 8', '一座楼', '一座楼', 'yízuò lóu', 'Một tòa nhà', 1) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
