INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_9_2_6', 'txt_9_2', 'Bài 9', '好啊。', '好啊。', 'Hǎo a.', 'Được chứ.', 6) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_9_2_7', 'txt_9_2', 'Ôn Bài 3', '这是我的书。', '这是我的书。', 'Zhè shì wǒ de shū.', 'Đây là sách của tôi.', 7) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_9_2_8', 'txt_9_2', 'Bài 9', '你想买什么衣服？', '你想买什么衣服？', 'Nǐ xiǎng mǎi shénme yīfu?', 'Cậu muốn mua quần áo gì?', 8) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_9_2_1', 'lesson-9', 'txt_9_2', 'listening', 'listening', '一座楼', NULL, '[Ôn tập Bài 8] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Lúc đó, người con gái ấy khóc không ngớt.","Tôi chưa ăn cơm.","con đường này","Một tòa nhà"]'::jsonb, 3, 'Nội dung nghe được: 一座楼 (yízuò lóu) → Một tòa nhà', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_9_2_2', 'lesson-9', 'txt_9_2', 'listening', 'listening', '我们下午去吧！', NULL, '[Bài 9] Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["明天上午我们一起去超市吧！","我们下午去吧！","他去北京 (Běijīng: Bắc Kinh)留学 (liúxué: du học)。","我听 (tīng: nghe)着 (zhe: đang (trạng thái))音乐看书。"]'::jsonb, 1, 'Câu vừa đọc: 我们下午去吧！ (Wǒmen xiàwǔ qù ba!) → Buổi chiều chúng ta đi nhé!', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_9_2_3', 'lesson-9', 'txt_9_2', 'listening', 'listening', '食堂左边', NULL, '[Ôn tập Bài 4] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["quyển sách thú vị, có ý nghĩa","Phía bên trái nhà ăn","Cô ấy đẹp quá.","Một con đường"]'::jsonb, 1, 'Nội dung nghe được: 食堂左边 (shítáng zuǒbian) → Phía bên trái nhà ăn', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_9_2_4', 'lesson-9', 'txt_9_2', 'listening', 'listening', '你买吧！', NULL, '[Bài 9] Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["你买吧！","我觉得粉红色的裙子更 (gèng: càng)合适。","请问 (qǐngwèn: xin hỏi)，在哪儿结账？","我想来 (lái: đến)超市买一些 (yīxiē: một ít, một vài)东西。"]'::jsonb, 0, 'Câu vừa đọc: 你买吧！ (Nǐ mǎi ba!) → Cậu mua đi!', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_9_2_5', 'lesson-9', 'txt_9_2', 'listening', 'listening', '三个朋友', NULL, '[Ôn tập Bài 1] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Bài hát này dạo gần đây khá thịnh hành đấy!","Ba người bạn (cách dùng đúng)","cây thước kẻ của anh ấy","Em trai tôi chơi trong vườn hoa."]'::jsonb, 1, 'Nội dung nghe được: 三个朋友 (sān gè péngyou) → Ba người bạn (cách dùng đúng)', 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO texts (id, lesson_id, title, description, sort_order) VALUES ('txt_9_3', 'lesson-9', 'Bài khoá mở rộng: Chọn áo khoác ở siêu thị (Mở rộng)', 'Hội thoại tình huống mới xây dựng dựa trên từ vựng và ngữ pháp Bài 9 (không trùng lặp nguyên văn giáo trình).', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_9_3_1', 'txt_9_3', 'Nhân viên', '你好，你想买什么衣服？', '你好，你想买什么衣服？', 'Nǐ hǎo, nǐ xiǎng mǎi shénme yīfu?', 'Chào bạn, bạn muốn mua trang phục gì?', 1) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_9_3_2', 'txt_9_3', 'Lan', '我想试一下那件白色的大衣和这条黑色的裤子。', '我想试一下 (xià: dưới / xuống)那件 (jiàn: cái, chiếc (áo, việc))白色的大衣和这条黑色的裤子。', 'Wǒ xiǎng shì yíxià nà jiàn báisè de dàyī hé zhè tiáo hēisè de kùzi.', 'Tôi muốn mặc thử chiếc áo khoác trắng kia và chiếc quần đen này.', 2) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_9_3_3', 'txt_9_3', 'Lan', '大衣很合适，颜色也不错，但是裤子有点儿大。', '大衣很合适，颜色也不错，但是 (dànshì: nhưng, nhưng mà)裤子有点儿 (yǒudiǎnr: hơi hơi, có hơi)大 (dà: to, lớn)。', 'Dàyī hěn héshì, yánsè yě búcuò, dànshì kùzi yǒudiǎnr dà.', 'Áo khoác rất vừa vặn, màu cũng đẹp, nhưng quần hơi rộng một chút.', 3) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_9_3_4', 'txt_9_3', 'Nhân viên', '那你试试这条小一点儿的吧。', '那你试试这条小 (xiǎo: nhỏ, bé)一点儿 (ér: con, (âm uốn lưỡi))的吧。', 'Nà nǐ shìshi zhè tiáo xiǎo yìdiǎnr de ba.', 'Vậy bạn thử chiếc nhỏ hơn một chút này nhé.', 4) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_9_3_1', 'lesson-9', 'txt_9_3', 'listening', 'listening', '你好，你想买什么衣服？ 我想试一下那件白色的大衣和这条黑色的裤子。 大衣很合适，颜色也不错，但是裤子有点儿大。 那你试试这条小一点儿的吧。', NULL, '[Nghe hiểu tình huống mới] Sau khi mặc thử, Lan nhận xét chiếc quần thế nào?', '["Quá chật không mặc vừa","Hơi rộng một chút (有点儿大)","Màu sắc không đẹp","Vừa vặn hoàn hảo"]'::jsonb, 1, 'Lan nói rõ ''大衣很合适... 但是裤子有点儿大'' (quần hơi rộng).', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_9_3_2', 'lesson-9', 'txt_9_3', 'listening', 'listening', '你好，你想买什么衣服？', NULL, '[Mở rộng] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Chào bạn, bạn muốn mua trang phục gì?","Cô giáo không ở trong phòng làm việc.","Một tòa nhà","Mỗi ngày anh ấy đều đến thư viện mượn sách."]'::jsonb, 0, 'Nội dung nghe được: 你好，你想买什么衣服？ (Nǐ hǎo, nǐ xiǎng mǎi shénme yīfu?) → Chào bạn, bạn muốn mua trang phục gì?', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_9_3_3', 'lesson-9', 'txt_9_3', 'listening', 'listening', '我想试一下那件白色的大衣和这条黑色的裤子。', NULL, '[Mở rộng] Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["售货员说 (shuō: nói)那件 (jiàn: cái, chiếc (áo, việc))红色衣服不错。","我想试一下 (xià: dưới / xuống)那件 (jiàn: cái, chiếc (áo, việc))白色的大衣和这条黑色的裤子。","好啊。","你买吧！"]'::jsonb, 1, 'Câu vừa đọc: 我想试一下那件白色的大衣和这条黑色的裤子。 (Wǒ xiǎng shì yíxià nà jiàn báisè de dàyī hé zhè tiáo hēisè de kùzi.) → Tôi muốn mặc thử chiếc áo khoác trắng kia và chiếc quần đen này.', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_9_3_4', 'lesson-9', 'txt_9_3', 'listening', 'listening', '大衣很合适，颜色也不错，但是裤子有点儿大。', NULL, '[Mở rộng] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Áo khoác rất vừa vặn, màu cũng đẹp, nhưng quần hơi rộng một chút.","Bọn họ tặng cho tôi rất nhiều quà.","Cơ thể con sao rồi?","Anh ấy hát rất hay."]'::jsonb, 0, 'Nội dung nghe được: 大衣很合适，颜色也不错，但是裤子有点儿大。 (Dàyī hěn héshì, yánsè yě búcuò, dànshì kùzi yǒudiǎnr dà.) → Áo khoác rất vừa vặn, màu cũng đẹp, nhưng quần hơi rộng một chút.', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss9_1', 'lesson-9', '明天上午我们一起去超市吧', '[Mở rộng] Sáng mai chúng ta cùng đi siêu thị nhé!', 'Míngtiān shàngwǔ wǒmen yīqǐ qù chāoshì ba!', '["明天","上午","我们","一起","去","超市吧"]'::jsonb, NULL, 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss9_2', 'lesson-9', '这件大衣的颜色我很喜欢', '[Mở rộng] Màu sắc của chiếc áo khoác dài này tôi rất thích.', 'Zhè jiàn dàyī de yánsè wǒ hěn xǐhuan.', '["这件","大衣的","颜色","我","很","喜欢"]'::jsonb, 'Từ chưa học: 件 (jiàn: cái, chiếc (áo, việc))', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss9_3', 'lesson-9', '我们下午去吧', 'Buổi chiều chúng ta đi nhé!', 'Wǒmen xiàwǔ qù ba!', '["我们","下午","去","吧"]'::jsonb, NULL, 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss9_4', 'lesson-9', '你想买什么衣服', 'Cậu muốn mua quần áo gì?', 'Nǐ xiǎng mǎi shénme yīfu?', '["你","想","买","什么","衣服"]'::jsonb, NULL, 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss9_5', 'lesson-9', '这里的水果怎么卖', '[Ôn tập Bài 8] Hoa quả ở đây bán thế nào vậy ạ?', 'Zhèlǐ de shuǐguǒ zěnme mài?', '["这","里","的","水果","怎么","卖"]'::jsonb, 'Từ chưa học: 里 (lǐ: trong)', 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss9_6', 'lesson-9', '他来自哪个国家', '[Ôn tập Bài 3] Anh ấy đến từ đất nước nào?', 'Tā láizì nǎ gè guójiā?', '["他","来自","哪","个","国家"]'::jsonb, NULL, 6) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss9_exp_1', 'lesson-9', '小兰你跟我一起去超市买衣服好吗', 'Tiểu Lan! Cậu đi siêu thị mua quần áo cùng tớ nhé, được không?', 'Xiǎolán, nǐ gēn wǒ yīqǐ qù chāoshì mǎi yīfu, hǎo ma?', '["小","兰","你","跟","我","一起","去","超市","买","衣服","好","吗"]'::jsonb, NULL, 7) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss9_exp_2', 'lesson-9', '我想买一条裤子一条裙子和一件大衣', 'Tớ muốn mua một chiếc quần dài, một chiếc váy và một chiếc áo khoác dài.', 'Wǒ xiǎng mǎi yī tiáo kùzi, yī tiáo qúnzi hé yī jiàn dàyī.', '["我","想","买","一","条","裤子","一","条","裙子","和","一","件","大衣"]'::jsonb, NULL, 8) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss9_exp_3', 'lesson-9', '你觉得这条裤子好不好看', 'Cậu thấy chiếc quần này có đẹp không?', 'Nǐ juéde zhè tiáo kùzi hǎo bu hǎokàn?', '["你","觉得","这","条","裤子","好","不","好看"]'::jsonb, NULL, 9) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss9_exp_4', 'lesson-9', '我觉得颜色不太好看我不喜欢绿色我最喜欢红色和黄色', 'Tớ thấy màu sắc không đẹp lắm, tớ không thích màu xanh lá, tớ thích nhất màu đỏ và màu vàng.', 'Wǒ juéde yánsè bú tài hǎokàn, wǒ bù xǐhuan lǜsè, wǒ zuì xǐhuan hóngsè hé huángsè.', '["我","觉得","颜色","不","太","好看","我","不","喜欢","绿色","我","最","喜欢","红色","和","黄色"]'::jsonb, NULL, 10) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss9_exp_5', 'lesson-9', '那这条红色的裤子行吗你试试看', 'Vậy chiếc quần màu đỏ này có được không? Cậu mặc thử xem!', 'Nà zhè tiáo hóngsè de kùzi xíng ma? Nǐ shìshi kàn!', '["那","这","条","红色","的","裤子","行","吗","你","试","试","看"]'::jsonb, NULL, 11) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss9_exp_6', 'lesson-9', '不错很合适我买这条吧', 'Khá ổn, rất vừa vặn. Tớ mua chiếc này nhé!', 'Búcuò, hěn héshì. Wǒ mǎi zhè tiáo ba!', '["不错","很","合适","我","买","这","条","吧"]'::jsonb, NULL, 12) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss9_exp_7', 'lesson-9', '你看那边是大衣和裙子好漂亮啊', 'Cậu nhìn kìa, bên kia là áo khoác và váy, đẹp quá đi!', 'Nǐ kàn, nàbian shì dàyī hé qúnzi, hǎo piàoliang a!', '["你","看","那","边","是","大衣","和","裙子","好","漂亮","啊"]'::jsonb, NULL, 13) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss9_exp_8', 'lesson-9', '很好看我买这件黄色的大衣和这条粉红色的裙子你觉得这件大衣贵不贵', 'Đẹp lắm, tớ sẽ mua chiếc áo khoác màu vàng này và chiếc váy màu hồng này. Cậu thấy chiếc áo khoác này có đắt không?', 'Hěn hǎokàn, wǒ mǎi zhè jiàn huángsè de dàyī hé zhè tiáo fěnhóngsè de qúnzi. Nǐ juéde zhè jiàn dàyī guì bu guì?', '["很","好看","我","买","这","件","黄色","的","大衣","和","这","条","粉红色","的","裙子","你","觉得","这","件","大衣","贵","不","贵"]'::jsonb, NULL, 14) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss9_exp_9', 'lesson-9', '我觉得不贵很便宜', 'Tớ thấy không đắt đâu, rất rẻ!', 'Wǒ juéde bú guì, hěn piányi!', '["我","觉得","不","贵","很","便宜"]'::jsonb, NULL, 15) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss9_exp_10', 'lesson-9', '好的我们去结账吧', 'Được rồi, chúng ta đi thanh toán thôi!', 'Hǎo de, wǒmen qù jiézhàng ba!', '["好","的","我们","去","结账","吧"]'::jsonb, NULL, 16) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss9_exp_11', 'lesson-9', '你好请给我们结一下儿账', 'Chào bạn, làm ơn thanh toán giúp bọn mình nhé!', 'Nǐ hǎo, qǐng gěi wǒmen jié yíxiàr zhàng!', '["你好","请","给","我们","结","一下儿","账"]'::jsonb, NULL, 17) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
