INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr9_vi_1', 'lesson-9', 'vi_to_zh', '[Mở rộng] Sáng mai chúng ta cùng đi siêu thị nhé!', NULL, NULL, '明天上午我们一起去超市吧！', NULL, 'míngtiān shàngwǔ wǒmen yīqǐ qù chāoshì ba', '[]'::jsonb, 'Gợi ý Pinyin: Míngtiān shàngwǔ wǒmen yīqǐ qù chāoshì ba!', 'Sáng mai chúng ta cùng đi siêu thị nhé! → 明天上午我们一起去超市吧！ (Míngtiān shàngwǔ wǒmen yīqǐ qù chāoshì ba!)', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr9_vi_2', 'lesson-9', 'vi_to_zh', '[Mở rộng] Màu sắc của chiếc áo khoác dài này tôi rất thích.', NULL, NULL, '这件大衣的颜色我很喜欢。', NULL, 'zhè jiàn dàyī de yánsè wǒ hěn xǐhuan', '[]'::jsonb, 'Gợi ý Pinyin: Zhè jiàn dàyī de yánsè wǒ hěn xǐhuan. | Từ chưa học: 件 (jiàn: cái, chiếc (áo, việc))', 'Màu sắc của chiếc áo khoác dài này tôi rất thích. → 这件大衣的颜色我很喜欢。 (Zhè jiàn dàyī de yánsè wǒ hěn xǐhuan.)', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr9_vi_3', 'lesson-9', 'vi_to_zh', 'Buổi chiều chúng ta đi nhé!', NULL, NULL, '我们下午去吧！', NULL, 'wǒmen xiàwǔ qù ba', '[]'::jsonb, 'Gợi ý Pinyin: Wǒmen xiàwǔ qù ba!', 'Buổi chiều chúng ta đi nhé! → 我们下午去吧！ (Wǒmen xiàwǔ qù ba!)', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr9_vi_4', 'lesson-9', 'vi_to_zh', 'Cậu mua đi!', NULL, NULL, '你买吧！', NULL, 'nǐ mǎi ba', '[]'::jsonb, 'Gợi ý Pinyin: Nǐ mǎi ba!', 'Cậu mua đi! → 你买吧！ (Nǐ mǎi ba!)', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr9_vi_exp_1', 'lesson-9', 'vi_to_zh', 'Tiểu Lan! Cậu đi siêu thị mua quần áo cùng tớ nhé, được không?', NULL, NULL, '小兰！你跟我一起去超市买衣服，好吗？', NULL, 'xiǎolán nǐ gēn wǒ yīqǐ qù chāoshì mǎi yīfu hǎo ma', '[]'::jsonb, 'Gợi ý Pinyin: Xiǎolán, nǐ gēn wǒ yīqǐ qù chāoshì mǎi yīfu, hǎo ma?', 'Tiểu Lan! Cậu đi siêu thị mua quần áo cùng tớ nhé, được không? → 小兰！你跟我一起去超市买衣服，好吗？ (Xiǎolán, nǐ gēn wǒ yīqǐ qù chāoshì mǎi yīfu, hǎo ma?)', 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr9_vi_exp_2', 'lesson-9', 'vi_to_zh', 'Cậu muốn mua quần áo gì?', NULL, NULL, '你想买什么衣服？', NULL, 'nǐ xiǎng mǎi shénme yīfu', '[]'::jsonb, 'Gợi ý Pinyin: Nǐ xiǎng mǎi shénme yīfu?', 'Cậu muốn mua quần áo gì? → 你想买什么衣服？ (Nǐ xiǎng mǎi shénme yīfu?)', 6) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr9_vi_exp_3', 'lesson-9', 'vi_to_zh', 'Tớ muốn mua một chiếc quần dài, một chiếc váy và một chiếc áo khoác dài.', NULL, NULL, '我想买一条裤子，一条裙子和一件大衣。', NULL, 'wǒ xiǎng mǎi yī tiáo kùzi yī tiáo qúnzi hé yī jiàn dàyī', '[]'::jsonb, 'Gợi ý Pinyin: Wǒ xiǎng mǎi yī tiáo kùzi, yī tiáo qúnzi hé yī jiàn dàyī.', 'Tớ muốn mua một chiếc quần dài, một chiếc váy và một chiếc áo khoác dài. → 我想买一条裤子，一条裙子和一件大衣。 (Wǒ xiǎng mǎi yī tiáo kùzi, yī tiáo qúnzi hé yī jiàn dàyī.)', 7) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr9_vi_exp_4', 'lesson-9', 'vi_to_zh', 'Cậu thấy chiếc quần này có đẹp không?', NULL, NULL, '你觉得这条裤子好不好看？', NULL, 'nǐ juéde zhè tiáo kùzi hǎo bu hǎokàn', '[]'::jsonb, 'Gợi ý Pinyin: Nǐ juéde zhè tiáo kùzi hǎo bu hǎokàn?', 'Cậu thấy chiếc quần này có đẹp không? → 你觉得这条裤子好不好看？ (Nǐ juéde zhè tiáo kùzi hǎo bu hǎokàn?)', 8) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr9_vi_exp_5', 'lesson-9', 'vi_to_zh', 'Tớ thấy màu sắc không đẹp lắm, tớ không thích màu xanh lá, tớ thích nhất màu đỏ và màu vàng.', NULL, NULL, '我觉得颜色不太好看，我不喜欢绿色，我最喜欢红色和黄色。', NULL, 'wǒ juéde yánsè bú tài hǎokàn wǒ bù xǐhuan lǜsè wǒ zuì xǐhuan hóngsè hé huángsè', '[]'::jsonb, 'Gợi ý Pinyin: Wǒ juéde yánsè bú tài hǎokàn, wǒ bù xǐhuan lǜsè, wǒ zuì xǐhuan hóngsè hé huángsè.', 'Tớ thấy màu sắc không đẹp lắm, tớ không thích màu xanh lá, tớ thích nhất màu đỏ và màu vàng. → 我觉得颜色不太好看，我不喜欢绿色，我最喜欢红色和黄色。 (Wǒ juéde yánsè bú tài hǎokàn, wǒ bù xǐhuan lǜsè, wǒ zuì xǐhuan hóngsè hé huángsè.)', 9) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr9_vi_exp_6', 'lesson-9', 'vi_to_zh', 'Vậy chiếc quần màu đỏ này có được không? Cậu mặc thử xem!', NULL, NULL, '那这条红色的裤子行吗？你试试看！', NULL, 'nà zhè tiáo hóngsè de kùzi xíng ma nǐ shìshi kàn', '[]'::jsonb, 'Gợi ý Pinyin: Nà zhè tiáo hóngsè de kùzi xíng ma? Nǐ shìshi kàn!', 'Vậy chiếc quần màu đỏ này có được không? Cậu mặc thử xem! → 那这条红色的裤子行吗？你试试看！ (Nà zhè tiáo hóngsè de kùzi xíng ma? Nǐ shìshi kàn!)', 10) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr9_vi_exp_7', 'lesson-9', 'vi_to_zh', 'Khá ổn, rất vừa vặn. Tớ mua chiếc này nhé!', NULL, NULL, '不错，很合适。我买这条吧！', NULL, 'búcuò hěn héshì wǒ mǎi zhè tiáo ba', '[]'::jsonb, 'Gợi ý Pinyin: Búcuò, hěn héshì. Wǒ mǎi zhè tiáo ba!', 'Khá ổn, rất vừa vặn. Tớ mua chiếc này nhé! → 不错，很合适。我买这条吧！ (Búcuò, hěn héshì. Wǒ mǎi zhè tiáo ba!)', 11) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr9_vi_exp_8', 'lesson-9', 'vi_to_zh', 'Cậu nhìn kìa, bên kia là áo khoác và váy, đẹp quá đi!', NULL, NULL, '你看，那边是大衣和裙子，好漂亮啊！', NULL, 'nǐ kàn nàbian shì dàyī hé qúnzi hǎo piàoliang a', '[]'::jsonb, 'Gợi ý Pinyin: Nǐ kàn, nàbian shì dàyī hé qúnzi, hǎo piàoliang a!', 'Cậu nhìn kìa, bên kia là áo khoác và váy, đẹp quá đi! → 你看，那边是大衣和裙子，好漂亮啊！ (Nǐ kàn, nàbian shì dàyī hé qúnzi, hǎo piàoliang a!)', 12) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr9_vi_exp_9', 'lesson-9', 'vi_to_zh', 'Đẹp lắm, tớ sẽ mua chiếc áo khoác màu vàng này và chiếc váy màu hồng này. Cậu thấy chiếc áo khoác này có đắt không?', NULL, NULL, '很好看，我买这件黄色的大衣和这条粉红色的裙子。你觉得这件大衣贵不贵？', NULL, 'hěn hǎokàn wǒ mǎi zhè jiàn huángsè de dàyī hé zhè tiáo fěnhóngsè de qúnzi nǐ juéde zhè jiàn dàyī guì bu guì', '[]'::jsonb, 'Gợi ý Pinyin: Hěn hǎokàn, wǒ mǎi zhè jiàn huángsè de dàyī hé zhè tiáo fěnhóngsè de qúnzi. Nǐ juéde zhè jiàn dàyī guì bu guì?', 'Đẹp lắm, tớ sẽ mua chiếc áo khoác màu vàng này và chiếc váy màu hồng này. Cậu thấy chiếc áo khoác này có đắt không? → 很好看，我买这件黄色的大衣和这条粉红色的裙子。你觉得这件大衣贵不贵？ (Hěn hǎokàn, wǒ mǎi zhè jiàn huángsè de dàyī hé zhè tiáo fěnhóngsè de qúnzi. Nǐ juéde zhè jiàn dàyī guì bu guì?)', 13) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
