INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq9_12', 'lesson-9', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, 'Phiên âm Pinyin chính xác của “最” là gì?', '["yīfu","ba","yígòng","zuì"]'::jsonb, 3, '“最” đọc là: zuì (nhất).', 12) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq9_13', 'lesson-9', NULL, 'expanded_quiz', 'radical', NULL, NULL, 'Chữ Hán “超市” chứa bộ thủ nào sau đây?', '["立 (Lập) (Đứng vững, thiết lập)","门 (Môn) (Cánh cửa, lối ra vào)","走 (Tẩu) (Chạy, đi lại, rời đi)","冖 (Mịch) (Khăn phủ, mái che)"]'::jsonb, 2, 'Chữ “超市” có bộ chính 走 (Tẩu) (Chạy, đi lại, rời đi). Chiết tự: 超: 走 (Tẩu: chạy) + 召 (Triệu: vượt qua) • 市: 亠 (Đầu) + 巾 (Cân: lều vải nơi chợ búa)', 13) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq9_14', 'lesson-9', NULL, 'expanded_quiz', 'radical', NULL, NULL, 'Chữ Hán “售货员” chứa bộ thủ nào sau đây?', '["口 (Khẩu) (Miệng, ăn uống, lời nói, âm thanh phát ra)","身 (Thân) (Thân thể, vóc dáng)","乙 (Ất) (Uốn cong, số thứ tự, chồi non)","山 (Sơn) (Núi non, đồi núi)"]'::jsonb, 0, 'Chữ “售货员” có bộ chính 口 (Khẩu) (Miệng, ăn uống, lời nói, âm thanh phát ra). Chiết tự: 售: 隹 (Chuy) + 口 (Khẩu: rao bán hàng) • 货: 化 (Hóa) + 贝 (Bối: hàng hóa quy thành tiền) • 员: 口 (Khẩu) + 贝 (Bối: người làm công việc)', 14) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq9_15', 'lesson-9', NULL, 'expanded_quiz', 'radical', NULL, NULL, 'Chữ Hán “衣服” chứa bộ thủ nào sau đây?', '["鱼 (Ngư) (Con cá, thủy sản)","衣/衤 (Y) (Áo quần, y phục)","囗 (Vi) (Vây quanh, không gian kín, lãnh thổ)","无 (Vô) (Không có, phủ định)"]'::jsonb, 1, 'Chữ “衣服” có bộ chính 衣/衤 (Y) (Áo quần, y phục). Chiết tự: 衣: Bộ 衣 (Y - cổ áo và vạt áo, chữ độc thể) • 服: 月 (Nguyệt) + 卩 + 又 (trang phục vừa vặn)', 15) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq9_16', 'lesson-9', NULL, 'expanded_quiz', 'radical', NULL, NULL, 'Chữ Hán “裤子” chứa bộ thủ nào sau đây?', '["干 (Can) (Can thiệp, khô ráo, làm việc)","犬/犭 (Khuyển) (Con chó, loài thú)","色 (Sắc) (Màu sắc, vẻ mặt)","衣/衤 (Y) (Áo quần, y phục)"]'::jsonb, 3, 'Chữ “裤子” có bộ chính 衣/衤 (Y) (Áo quần, y phục). Chiết tự: 裤: 衤 (Y: áo quần) + 库 (Khố: mượn âm) • 子: Bộ 子 (Tử - đứa trẻ dang tay, chữ độc thể)', 16) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq9_17', 'lesson-9', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, '[Ôn tập Bài 1] Từ đã học “是” (shì) có nghĩa là gì?', '["quần","ba","là, thì...","ở đâu"]'::jsonb, 2, 'Ôn tập Bài 1: “是” (shì) nghĩa là: là, thì....', 17) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq9_18', 'lesson-9', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, '[Ôn tập Bài 4] Từ đã học “食堂” (shítáng) có nghĩa là gì?', '["ngài, ông, bà... (cách gọi tôn trọng và lịch sự dành cho những người có địa vị cao...)","bảy","đến từ (đâu)","nhà ăn"]'::jsonb, 3, 'Ôn tập Bài 4: “食堂” (shítáng) nghĩa là: nhà ăn.', 18) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq9_19', 'lesson-9', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, '[Ôn tập Bài 1] Từ đã học “晚上” (wǎnshàng) có nghĩa là gì?', '["ngã tư","bút bi","buổi tối","thư viện"]'::jsonb, 2, 'Ôn tập Bài 1: “晚上” (wǎnshàng) nghĩa là: buổi tối.', 19) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq9_20', 'lesson-9', NULL, 'expanded_quiz', 'reading', NULL, NULL, '[Mở rộng] Câu “明天上午我们一起去超市吧！” có nghĩa tiếng Việt là gì?', '["Một cái ô","Bài hát này dạo gần đây khá thịnh hành đấy!","Sáng mai chúng ta cùng đi siêu thị nhé!","Hai trăm bảy mươi nghìn"]'::jsonb, 2, '明天上午我们一起去超市吧！ (Míngtiān shàngwǔ wǒmen yīqǐ qù chāoshì ba!) → Sáng mai chúng ta cùng đi siêu thị nhé!', 20) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq9_21', 'lesson-9', NULL, 'expanded_quiz', 'reading', NULL, NULL, '[Đọc hiểu mở rộng] Đọc đoạn hội thoại:
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq9_22', 'lesson-9', NULL, 'expanded_quiz', 'reading', NULL, NULL, 'Câu “我们下午去吧！” có nghĩa tiếng Việt là gì?', '["Buổi chiều chúng ta đi nhé!","Một con gà","Cô bé, năm nay cháu mấy tuổi rồi?","Một cái ghế"]'::jsonb, 0, '我们下午去吧！ (Wǒmen xiàwǔ qù ba!) → Buổi chiều chúng ta đi nhé!', 22) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct9_1', 'lesson-9', NULL, 'comprehensive_test', 'listening', '一座楼', NULL, 'Nghe đoạn ghi âm và chọn nghĩa tiếng Việt đúng:', '["Chào buổi sáng!","Chào buổi tối!","Một tòa nhà","Tôi muốn đi cửa hàng mua hai cây bút bi, một cây thước kẻ và ba quyển vở ghi chép. Bạn có muốn đi không?"]'::jsonb, 2, 'Nội dung nghe được: “一座楼” (yízuò lóu) → Một tòa nhà', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct9_2', 'lesson-9', NULL, 'comprehensive_test', 'listening', '小兰！你跟我一起去超市买衣服，好吗？', NULL, 'Nghe đoạn ghi âm và chọn câu tiếng Trung khớp với nội dung vừa nghe:', '["你一直往前走，然后右拐就看到医院在你左边。","大学生","小兰！你跟我一起去超市买衣服，好吗？","你也是留学生吗？"]'::jsonb, 2, 'Câu vừa đọc: “小兰！你跟我一起去超市买衣服，好吗？” (Xiǎolán, nǐ gēn wǒ yīqǐ qù chāoshì mǎi yīfu, hǎo ma?) → Tiểu Lan! Cậu đi siêu thị mua quần áo cùng tớ nhé, được không?', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct9_3', 'lesson-9', NULL, 'comprehensive_test', 'listening', '他最喜欢打篮球。', NULL, 'Nghe đoạn ghi âm và chọn nghĩa tiếng Việt đúng:', '["Anh ấy thích chơi bóng rổ nhất.","Nhật Minh, vị này là bạn tôi, cậu ấy tên là Mark.","Lấy cho cháu một quả dưa hấu, hai cân thanh long và hai cốc nước ép dâu.","Hoa quả ở đây bán thế nào vậy ạ?"]'::jsonb, 0, 'Nội dung nghe được: “他最喜欢打篮球。” (Tā zuì xǐhuān dǎ lánqiú.) → Anh ấy thích chơi bóng rổ nhất.', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct9_4', 'lesson-9', NULL, 'comprehensive_test', 'listening', '你可以跟我一起去买帽子吗？', NULL, 'Nghe đoạn ghi âm và chọn câu tiếng Trung khớp với nội dung vừa nghe:', '["现在八点一刻，你要去哪儿？","我想去商店买两支圆珠笔、一把尺子和三本笔记本。你想去吗？","从早上八点到下午五点，他要在公司工作。","你可以跟我一起去买帽子吗？"]'::jsonb, 3, 'Câu vừa đọc: “你可以跟我一起去买帽子吗？” (Nǐ kěyǐ gēn wǒ yīqǐ qù mǎi màozi ma?) → Bạn có thể đi mua mũ cùng với tôi không?', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct9_5', 'lesson-9', NULL, 'comprehensive_test', 'listening', '食堂左边', NULL, 'Nghe đoạn ghi âm và chọn nghĩa tiếng Việt đúng:', '["Màu sắc của chiếc áo khoác dài này tôi rất thích.","Chiều hôm qua bạn có đi thư viện không?","Xin hỏi quanh rạp chiếu phim có hiệu sách không?","Phía bên trái nhà ăn"]'::jsonb, 3, 'Nội dung nghe được: “食堂左边” (shítáng zuǒbian) → Phía bên trái nhà ăn', 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct9_6', 'lesson-9', NULL, 'comprehensive_test', 'listening', '你好，你想买什么衣服？', NULL, 'Nghe đoạn ghi âm và chọn câu tiếng Trung khớp với nội dung vừa nghe:', '["好啊。","你好，你想买什么衣服？","他最喜欢打篮球。","从早上八点到下午五点，他要在公司工作。"]'::jsonb, 1, 'Câu vừa đọc: “你好，你想买什么衣服？” (Nǐ hǎo, nǐ xiǎng mǎi shénme yīfu?) → Chào bạn, bạn muốn mua trang phục gì?', 6) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct9_7', 'lesson-9', NULL, 'comprehensive_test', 'listening', '不错，很合适。我买这条吧！', NULL, 'Nghe đoạn ghi âm và chọn nghĩa tiếng Việt đúng:', '["Khá ổn, rất vừa vặn. Tớ mua chiếc này nhé!","Chà, đẹp quá đi mất! Cửa hàng bạn mua có cặp sách màu xanh dương không?","Đây là sách của tôi.","Cảm ơn cô ạ!"]'::jsonb, 0, 'Nội dung nghe được: “不错，很合适。我买这条吧！” (Búcuò, hěn héshì. Wǒ mǎi zhè tiáo ba!) → Khá ổn, rất vừa vặn. Tớ mua chiếc này nhé!', 7) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
