INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v10_1', 'lesson-10', '网上', 'wǎngshàng', 'võng thượng', 'mạng, internet', 'Danh từ', '网/罒 (Võng) (Tấm lưới, che phủ)', '网: Bộ 网 (Võng - mắt lưới đan chéo) • 上: Nét đứng 丨 và nét chấm chỉ hướng phía trên gạch ngang 一', 'Ghép 网 [bộ 网] + 上 [bộ 一] để nhớ từ 网上 (wǎngshàng): "mạng, internet".', '你怎么到现在还去商店买东西啊！在中国，人们都在网上买了！', 'Nǐ zěnme dào xiànzài hái qù shāngdiàn mǎi dōngxi a! Zài Zhōngguó, rénmen dōu zài wǎngshàng mǎi le!', 'Sao đến bây giờ cậu vẫn còn ra cửa hàng mua đồ vậy! Ở Trung Quốc mọi người đều mua trên mạng hết rồi!', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v10_2', 'lesson-10', '电脑', 'diànnǎo', 'điện não', 'máy vi tính', 'Danh từ', '田 (Điền) (Ruộng đất, khu vực, mặt)', '电: 日/田 (biến thể) + 乚 (tia sét phóng xuống) • 脑: 月 (Nhục: cơ quan cơ thể) + 亠 + 凶 (Não bộ)', 'Ghép 电 [bộ 田] + 脑 [bộ 月] để nhớ từ 电脑 (diànnǎo): "máy vi tính".', '真的。网上购物还挺方便，你只要有电脑或者手机，不用出门也能买到东西。很容易是吧！', 'Zhēn de. Wǎngshàng gòuwù hái tǐng fāngbiàn, nǐ zhǐyào yǒu diànnǎo huòzhě shǒujī, búyòng chūmén yě néng mǎi dào dōngxi. Hěn róngyì shì ba!', 'Thật đấy. Mua sắm trực tuyến khá tiện lợi, chỉ cần có máy tính hoặc điện thoại là không cần ra khỏi nhà cũng mua được đồ. Rất dễ đúng không nào!', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v10_3', 'lesson-10', '手机', 'shǒujī', 'cơ', 'điện thoại di động', 'Danh từ', '手/扌 (Thủ) (Bàn tay, động tác, thao tác)', '手: Bộ 手 (Thủ - hình bàn tay 5 ngón) • 机: 木 (Mộc: khung máy) + 几 (Kỷ)', 'Ghép 手 [bộ 手] + 机 [bộ 木] để nhớ từ 手机 (shǒujī): "điện thoại di động".', '真的。网上购物还挺方便，你只要有电脑或者手机，不用出门也能买到东西。很容易是吧！', 'Zhēn de. Wǎngshàng gòuwù hái tǐng fāngbiàn, nǐ zhǐyào yǒu diànnǎo huòzhě shǒujī, búyòng chūmén yě néng mǎi dào dōngxi. Hěn róngyì shì ba!', 'Thật đấy. Mua sắm trực tuyến khá tiện lợi, chỉ cần có máy tính hoặc điện thoại là không cần ra khỏi nhà cũng mua được đồ. Rất dễ đúng không nào!', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v10_4', 'lesson-10', '手表', 'shǒubiǎo', 'từ Hán ngữ', 'đồng hồ', 'Danh từ', '手/扌 (Thủ) (Bàn tay, động tác, thao tác)', '手: Bộ 手 (Thủ - hình bàn tay 5 ngón) • 表: 三 + 丨 + 衣 (phần ngoài áo, biểu hiện, đồng hồ)', 'Ghép 手 [bộ 手] + 表 [bộ 衣] để nhớ từ 手表 (shǒubiǎo): "đồng hồ".', '是啊。在网上你可以买到很多东西，比如衣服、手表、眼镜、书本等等。', 'Shì a. Zài wǎngshàng nǐ kěyǐ mǎidào hěn duō dōngxi, bǐrú yīfu, shǒubiǎo, yǎnjìng, shūběn děngděng.', 'Có chứ. Trên mạng cậu có thể mua được rất nhiều thứ, ví dụ như quần áo, đồng hồ, kính mắt, sách vở, v.v.', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v10_5', 'lesson-10', '眼镜', 'yǎnjìng', 'từ Hán ngữ', 'kính mắt', 'Danh từ', '目 (Mục) (Con mắt, nhìn ngắm, thị giác)', '眼: 目 (Mục: con mắt) + 艮 (Cấn) • 镜: 钅 (Kim: gương đồng/gọng kim loại) + 竟 (Cánh)', 'Ghép 眼 [bộ 目] + 镜 [bộ 钅] để nhớ từ 眼镜 (yǎnjìng): "kính mắt".', '是啊。在网上你可以买到很多东西，比如衣服、手表、眼镜、书本等等。', 'Shì a. Zài wǎngshàng nǐ kěyǐ mǎidào hěn duō dōngxi, bǐrú yīfu, shǒubiǎo, yǎnjìng, shūběn děngděng.', 'Có chứ. Trên mạng cậu có thể mua được rất nhiều thứ, ví dụ như quần áo, đồng hồ, kính mắt, sách vở, v.v.', 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v10_6', 'lesson-10', '书本', 'shūběn', 'thư', 'sách vở (nói chung)', 'Danh từ', '乙 (Ất) (Uốn cong, số thứ tự, chồi non)', '书: Nét gấp 乛 + 乛 + 丨 + 丶 (cuốn sách, bút viết) • 本: 木 (Mộc: cây) + nét gạch ngang 一 dưới gốc (gốc rễ, quyển sách)', 'Ghép 书 [bộ 乙] + 本 [bộ 木] để nhớ từ 书本 (shūběn): "sách vở (nói chung)".', '小雪，下午你跟我一起去商店买书本吧！', 'Xiǎoxuě, xiàwǔ nǐ gēn wǒ yīqǐ qù shāngdiàn mǎi shūběn ba!', 'Tiểu Tuyết, chiều nay cậu cùng tớ ra cửa hàng mua sách vở nhé!', 6) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v10_7', 'lesson-10', '价格', 'jiàgé', 'từ Hán ngữ', 'giá cả', 'Danh từ', '人/亻 (Nhân) (Con người, nhân loại, hành động)', '价: 亻 (Nhân đứng) + 介 (Giới: giá trị) • 格: 木 (Mộc: khung gỗ kẻ ô) + 各 (Các)', 'Ghép 价 [bộ 亻] + 格 [bộ 木] để nhớ từ 价格 (jiàgé): "giá cả".', '哇！太方便了！但是网上的东西价格怎么样？', 'Wa! Tài fāngbiàn le! Dànshì wǎngshàng de dōngxi jiàgé zěnmeyàng?', 'Chà! Tiện lợi quá! Nhưng giá cả đồ trên mạng thế nào?', 7) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v10_8', 'lesson-10', '质量', 'zhìliàng', 'từ Hán ngữ', 'chất lượng', 'Danh từ', '贝 (Bối) (Vỏ sò, tiền bạc, giá trị)', '质: 厂 (Hán) + 十 + 贝 (Bối: đem vật cầm cố đánh giá) • 量: 旦 (Đán) + 里 (Lý: đong đếm khối lượng)', 'Ghép 质 [bộ 贝] + 量 [bộ 里] để nhớ từ 质量 (zhìliàng): "chất lượng".', '质量呢？', 'Zhìliàng ne?', 'Còn chất lượng thì sao?', 8) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v10_9', 'lesson-10', '告诉', 'gàosù', 'từ Hán ngữ', 'nói cho', 'Động từ', '口 (Khẩu) (Miệng, ăn uống, lời nói, âm thanh phát ra)', '告: 牛 (Ngưu: biến thể) + 口 (Khẩu: báo tin) • 诉: 讠 (Ngôn: lời nói) + 斥 (Xích: kể lại)', 'Ghép 告 [bộ 口] + 诉 [bộ 讠] để nhớ từ 告诉 (gàosù): "nói cho".', '这个不好说。你上网吧，我会告诉你怎么买。', 'Zhège bù hǎoshuō. Nǐ shàngwǎng ba, wǒ huì gàosù nǐ zěnme mǎi.', 'Chuyện này khó nói lắm. Cậu lên mạng đi, tớ sẽ chỉ cậu cách mua.', 9) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v10_10', 'lesson-10', '比如', 'bǐrú', 'từ Hán ngữ', 'Ví dụ như', 'Động từ', '比 (Tỷ) (So sánh, kề bên)', '比: Bộ 比 (Tỷ - hai người đứng cạnh so sánh) • 如: 女 (Nữ) + 口 (Khẩu)', 'Ghép 比 [bộ 比] + 如 [bộ 女] để nhớ từ 比如 (bǐrú): "Ví dụ như".', '是啊。在网上你可以买到很多东西，比如衣服、手表、眼镜、书本等等。', 'Shì a. Zài wǎngshàng nǐ kěyǐ mǎidào hěn duō dōngxi, bǐrú yīfu, shǒubiǎo, yǎnjìng, shūběn děngděng.', 'Có chứ. Trên mạng cậu có thể mua được rất nhiều thứ, ví dụ như quần áo, đồng hồ, kính mắt, sách vở, v.v.', 10) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v10_11', 'lesson-10', '上网', 'shàngwǎng', 'thượng võng', 'lên mạng', 'Động từ', '一 (Nhất) (Số một, nền tảng, nét ngang cơ bản)', '上: Nét đứng 丨 và nét chấm chỉ hướng phía trên gạch ngang 一 • 网: Bộ 网 (Võng - mắt lưới đan chéo)', 'Ghép 上 [bộ 一] + 网 [bộ 网] để nhớ từ 上网 (shàngwǎng): "lên mạng".', '我不常上网买东西。你经常在网上买东西吗？', 'Wǒ bù cháng shàngwǎng mǎi dōngxi. Nǐ jīngcháng zài wǎngshàng mǎi dōngxi ma?', 'Tớ ít khi lên mạng mua đồ. Cậu có hay mua đồ qua mạng không?', 11) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v10_12', 'lesson-10', '购物', 'gòuwù', 'vật', 'mua hàng, mua đồ', 'Động từ', '贝 (Bối) (Vỏ sò, tiền bạc, giá trị)', '购: 贝 (Bối: tiền bạc mua sắm) + 勾 (Câu) • 物: 牜 (Ngưu: con vật) + 勿 (Vật)', 'Ghép 购 [bộ 贝] + 物 [bộ 牛] để nhớ từ 购物 (gòuwù): "mua hàng, mua đồ".', '真的。网上购物还挺方便，你只要有电脑或者手机，不用出门也能买到东西。很容易是吧！', 'Zhēn de. Wǎngshàng gòuwù hái tǐng fāngbiàn, nǐ zhǐyào yǒu diànnǎo huòzhě shǒujī, búyòng chūmén yě néng mǎi dào dōngxi. Hěn róngyì shì ba!', 'Thật đấy. Mua sắm trực tuyến khá tiện lợi, chỉ cần có máy tính hoặc điện thoại là không cần ra khỏi nhà cũng mua được đồ. Rất dễ đúng không nào!', 12) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v10_13', 'lesson-10', '小心', 'xiǎoxīn', 'tiểu', 'cẩn thận', 'Động từ', '小 (Tiểu) (Nhỏ bé, ít ỏi)', '小: Bộ 小 (Tiểu - hạt cát nhỏ bé) • 心: Bộ 心 (Tâm - hình trái tim)', 'Ghép 小 [bộ 小] + 心 [bộ 心] để nhớ từ 小心 (xiǎoxīn): "cẩn thận".', '有的质量挺好，但是也有的太差了！你要小心啊！', 'Yǒu de zhìliàng tǐng hǎo, dànshì yě yǒu de tài chà le! Nǐ yào xiǎoxīn a!', 'Có thứ chất lượng rất tốt, nhưng cũng có thứ tệ lắm! Cậu phải cẩn thận đấy!', 13) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v10_14', 'lesson-10', '出门', 'chūmén', 'môn', 'ra ngoài', 'Động từ', '凵 (Khảm) (Há miệng, hố trũng)', '出: 山 (Sơn) chồng hai tầng bước ra ngoài • 门: Bộ 门 (Môn - hình hai cánh cửa)', 'Ghép 出 [bộ 凵] + 门 [bộ 门] để nhớ từ 出门 (chūmén): "ra ngoài".', '真的。网上购物还挺方便，你只要有电脑或者手机，不用出门也能买到东西。很容易是吧！', 'Zhēn de. Wǎngshàng gòuwù hái tǐng fāngbiàn, nǐ zhǐyào yǒu diànnǎo huòzhě shǒujī, búyòng chūmén yě néng mǎi dào dōngxi. Hěn róngyì shì ba!', 'Thật đấy. Mua sắm trực tuyến khá tiện lợi, chỉ cần có máy tính hoặc điện thoại là không cần ra khỏi nhà cũng mua được đồ. Rất dễ đúng không nào!', 14) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v10_15', 'lesson-10', '方便', 'fāngbiàn', 'tiện', 'thuận tiện, tiện lợi', 'Tính từ', '方 (Phương) (Vuông vức, phương hướng)', '方: Bộ 方 (Phương - hình vuông, phương hướng) • 便: 亻 (Nhân đứng) + 更 (Canh)', 'Ghép 方 [bộ 方] + 便 [bộ 亻] để nhớ từ 方便 (fāngbiàn): "thuận tiện, tiện lợi".', '真的。网上购物还挺方便，你只要有电脑或者手机，不用出门也能买到东西。很容易是吧！', 'Zhēn de. Wǎngshàng gòuwù hái tǐng fāngbiàn, nǐ zhǐyào yǒu diànnǎo huòzhě shǒujī, búyòng chūmén yě néng mǎi dào dōngxi. Hěn róngyì shì ba!', 'Thật đấy. Mua sắm trực tuyến khá tiện lợi, chỉ cần có máy tính hoặc điện thoại là không cần ra khỏi nhà cũng mua được đồ. Rất dễ đúng không nào!', 15) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v10_16', 'lesson-10', '容易', 'róngyì', 'từ Hán ngữ', 'dễ dàng', 'Tính từ', '宀 (Miên) (Mái nhà, che chở, nơi ở)', '容: 宀 (Miên: mái nhà) + 谷 (Cốc: thung lũng rộng chứa đựng) • 易: 日 (Nhật: mặt trời) + 勿 (Vật: thay đổi dễ dàng)', 'Ghép 容 [bộ 宀] + 易 [bộ 日] để nhớ từ 容易 (róngyì): "dễ dàng".', '真的。网上购物还挺方便，你只要有电脑或者手机，不用出门也能买到东西。很容易是吧！', 'Zhēn de. Wǎngshàng gòuwù hái tǐng fāngbiàn, nǐ zhǐyào yǒu diànnǎo huòzhě shǒujī, búyòng chūmén yě néng mǎi dào dōngxi. Hěn róngyì shì ba!', 'Thật đấy. Mua sắm trực tuyến khá tiện lợi, chỉ cần có máy tính hoặc điện thoại là không cần ra khỏi nhà cũng mua được đồ. Rất dễ đúng không nào!', 16) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v10_17', 'lesson-10', '可以', 'kěyǐ', 'từ Hán ngữ', 'có thể', 'Động từ năng nguyện', '口 (Khẩu) (Miệng, ăn uống, lời nói, âm thanh phát ra)', '可: 丁 (Đinh) + 口 (Khẩu: đồng ý) • 以: 乚 + 丶 + 人 (Nhân)', 'Ghép 可 [bộ 口] + 以 [bộ 人] để nhớ từ 可以 (kěyǐ): "có thể".', '是啊。在网上你可以买到很多东西，比如衣服、手表、眼镜、书本等等。', 'Shì a. Zài wǎngshàng nǐ kěyǐ mǎidào hěn duō dōngxi, bǐrú yīfu, shǒubiǎo, yǎnjìng, shūběn děngděng.', 'Có chứ. Trên mạng cậu có thể mua được rất nhiều thứ, ví dụ như quần áo, đồng hồ, kính mắt, sách vở, v.v.', 17) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v10_18', 'lesson-10', '能', 'néng', 'từ Hán ngữ', 'có thể', 'Động từ năng nguyện', '月 (Nguyệt/Nhục) (Mặt trăng hoặc các bộ phận thân thể người)', '能 = 厶 + 月 (Nhục) + 匕 + 匕 (gấu mạnh mẽ có khả năng).', 'Chữ 能 (néng) mang nghĩa "có thể", bộ chính 月 (Nguyệt/Nhục); cấu tạo: 厶 + 月 (Nhục) + 匕 + 匕 (gấu mạnh mẽ có khả năng).', '真的。网上购物还挺方便，你只要有电脑或者手机，不用出门也能买到东西。很容易是吧！', 'Zhēn de. Wǎngshàng gòuwù hái tǐng fāngbiàn, nǐ zhǐyào yǒu diànnǎo huòzhě shǒujī, búyòng chūmén yě néng mǎi dào dōngxi. Hěn róngyì shì ba!', 'Thật đấy. Mua sắm trực tuyến khá tiện lợi, chỉ cần có máy tính hoặc điện thoại là không cần ra khỏi nhà cũng mua được đồ. Rất dễ đúng không nào!', 18) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v10_19', 'lesson-10', '但是', 'dànshì', 'thị', 'nhưng, nhưng mà', 'Liên từ', '人/亻 (Nhân) (Con người, nhân loại, hành động)', '但: 亻 (Nhân đứng) + 旦 (Đán) • 是: 日 (Nhật: sáng rõ) + 𤴓 (biến thể của 正/疋: ngay thẳng)', 'Ghép 但 [bộ 亻] + 是 [bộ 日] để nhớ từ 但是 (dànshì): "nhưng, nhưng mà".', '哇！太方便了！但是网上的东西价格怎么样？', 'Wa! Tài fāngbiàn le! Dànshì wǎngshàng de dōngxi jiàgé zěnmeyàng?', 'Chà! Tiện lợi quá! Nhưng giá cả đồ trên mạng thế nào?', 19) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v10_20', 'lesson-10', '或者', 'huòzhě', 'từ Hán ngữ', 'hoặc, hoặc là', 'Liên từ', '戈 (Qua) (Cây giáo, vũ khí, chiến tranh)', '或: 戈 (Qua: vũ khí bảo vệ) + 口 + 一 • 者: 耂 (Lão) + 日 (Nhật)', 'Ghép 或 [bộ 戈] + 者 [bộ 耂] để nhớ từ 或者 (huòzhě): "hoặc, hoặc là".', '真的。网上购物还挺方便，你只要有电脑或者手机，不用出门也能买到东西。很容易是吧！', 'Zhēn de. Wǎngshàng gòuwù hái tǐng fāngbiàn, nǐ zhǐyào yǒu diànnǎo huòzhě shǒujī, búyòng chūmén yě néng mǎi dào dōngxi. Hěn róngyì shì ba!', 'Thật đấy. Mua sắm trực tuyến khá tiện lợi, chỉ cần có máy tính hoặc điện thoại là không cần ra khỏi nhà cũng mua được đồ. Rất dễ đúng không nào!', 20) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v10_21', 'lesson-10', '还', 'hái', 'hoàn', 'còn, vẫn', 'Phó từ', '辶 (Sước) (Bước đi, di chuyển, khoảng cách)', '还 = 不 (Bất) + 辶 (Sước: quay đi rồi vẫn quay lại).', 'Chữ 还 (hái) mang nghĩa "còn, vẫn", bộ chính 辶 (Sước); cấu tạo: 不 (Bất) + 辶 (Sước: quay đi rồi vẫn quay lại).', '你怎么到现在还去商店买东西啊！在中国，人们都在网上买了！', 'Nǐ zěnme dào xiànzài hái qù shāngdiàn mǎi dōngxi a! Zài Zhōngguó, rénmen dōu zài wǎngshàng mǎi le!', 'Sao đến bây giờ cậu vẫn còn ra cửa hàng mua đồ vậy! Ở Trung Quốc mọi người đều mua trên mạng hết rồi!', 21) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v10_22', 'lesson-10', '经常', 'jīngcháng', 'từ Hán ngữ', 'thường xuyên', 'Phó từ', '糸/纟 (Mịch) (Sợi tơ, gắn kết, màu sắc)', '经: 纟 (Mịch: sợi dọc khung cửi) + 圣 • 常: 尚 (Thượng) + 巾 (Cân: mảnh vải mặc thường ngày)', 'Ghép 经 [bộ 纟] + 常 [bộ 巾] để nhớ từ 经常 (jīngcháng): "thường xuyên".', '我不常上网买东西。你经常在网上买东西吗？', 'Wǒ bù cháng shàngwǎng mǎi dōngxi. Nǐ jīngcháng zài wǎngshàng mǎi dōngxi ma?', 'Tớ ít khi lên mạng mua đồ. Cậu có hay mua đồ qua mạng không?', 22) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v10_23', 'lesson-10', '挺', 'tǐng', 'từ Hán ngữ', 'rất', 'Phó từ', '手/扌 (Thủ) (Bàn tay, động tác, thao tác)', '挺 = 扌 (Thủ: tay giơ thẳng) + 廷 (Đình).', 'Chữ 挺 (tǐng) mang nghĩa "rất", bộ chính 手/扌 (Thủ); cấu tạo: 扌 (Thủ: tay giơ thẳng) + 廷 (Đình).', '我昨天睡得挺晚的，所以今天有点儿困！', 'Wǒ zuótiān shuì de tǐng wǎn de, suǒyǐ jīntiān yǒudiǎnr kùn!', 'Hôm qua tớ ngủ khá trễ nên hôm nay hơi buồn ngủ!', 23) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v10_24', 'lesson-10', '等等', 'děng děng', 'từ Hán ngữ', 'vân vân', 'Cụm từ / Tên riêng', '竹/⺮ (Trúc) (Tre trúc, đồ đan, sách vở)', '等: ⺮ (Trúc: thẻ tre ghi thứ bậc) + 寺 (Tự) • 等: ⺮ (Trúc: thẻ tre ghi thứ bậc) + 寺 (Tự)', 'Ghép 等 [bộ 竹] + 等 [bộ 竹] để nhớ từ 等等 (děng děng): "vân vân".', '是啊。在网上你可以买到很多东西，比如衣服、手表、眼镜、书本等等。', 'Shì a. Zài wǎngshàng nǐ kěyǐ mǎidào hěn duō dōngxi, bǐrú yīfu, shǒubiǎo, yǎnjìng, shūběn děngděng.', 'Có chứ. Trên mạng cậu có thể mua được rất nhiều thứ, ví dụ như quần áo, đồng hồ, kính mắt, sách vở, v.v.', 24) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v10_25', 'lesson-10', '这样', 'zhèyàng', 'giá', 'như vậy, như thế đấy', 'Đại từ', '辶 (Sước) (Bước đi, di chuyển, khoảng cách)', '这: 文 (Văn) + 辶 (Sước: bước đi gần đây) • 样: 木 (Mộc: khuôn gỗ) + 羊 (Dương)', 'Ghép 这 [bộ 辶] + 样 [bộ 木] để nhớ từ 这样 (zhèyàng): "như vậy, như thế đấy".', '这是关于“这样”的常用句子。', 'Zhè shì guānyú ''zhèyàng'' de chángyòng jùzi.', 'Đây là câu ví dụ sử dụng từ ''这样'' (như vậy, như thế đấy).', 25) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order) VALUES ('g10_1', 'lesson-10', '1. Kết cấu tổ từ chữ 的', 'Cấu trúc câu ngữ pháp trọng tâm', ' Các danh từ, đại từ, động từ, tính từ hoặc cụm từ thêm 的 phía sau, sẽ hình thành tổ từ chữ 的. Khi đó trung tâm ngữ có thể được lược bỏ. Dùng để tỉnh lược danh  từ  đã được nhắc tới phía trước, hoặc người nghe, người nói đều hiểu để giúp câu nói ngắn', NULL, '[{"hanzi":"这本书是我的。","pinyin":"Zhè běn shū shì wǒ de.","meaning":"Quyển sách này là sách của tôi."},{"hanzi":"那件蓝色的衣服没有这件白色的好看。","pinyin":"Nà jiàn lánsè de yīfu méiyǒu zhè jiàn báisè de hǎokàn.","meaning":"Bộ quần áo màu xanh da trời kia không đẹp bằng bộ màu trắng này."}]'::jsonb, 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order) VALUES ('g10_2', 'lesson-10', '2. Phó từ 常常', 'Cấu trúc câu ngữ pháp trọng tâm', ' 常常 là phó từ mang nghĩa “thường thường, thường xuyên”, biểu thị động tác, hành vi xảy ra nhiều lần, nhấn mạnh tần suất của hành vi hoặc trạng thái, có thể biểu thị hành động trong quá khứ, hiện tại hoặc tương lai. Hình thức phủ định của 常常 là 不常 hoặ', NULL, '[{"hanzi":"这条裙子是你的吗？","pinyin":"Zhè tiáo qúnzi shì nǐ de ma?","meaning":"Cái váy này là của em à?"},{"hanzi":"爸爸很少带我去旅游。","pinyin":"Bàba hěnshǎo dài wǒ qù lǚyóu.","meaning":"Bố rất ít đưa tôi đi du lịch."}]'::jsonb, 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order) VALUES ('g10_3', 'lesson-10', '3. Phó từ 挺 và 太', '...... 挺 + Tính từ + 的。', ' a. Phó từ 挺 Đây là phó từ chỉ mức độ tương đối cao, tương đương với 很, thường kết hợp với 的 theo cấu trúc sau: 我昨天睡得挺晚的，所以今天有点儿困！ Wǒ zuótiān shuì de tǐng wǎn de, suǒyǐ jīntiān yǒudiǎnr kùn! Hôm qua tớ ngủ khá trễ nên hôm nay hơi buồn ngủ! 这首歌最近挺流行的！', NULL, '[{"hanzi":"我不常跟李君联系。","pinyin":"Wǒ bù cháng gēn Lǐ Jūn liánxì.","meaning":"Tôi không hay (không thường) liên lạc với Lý Quân."},{"hanzi":"我昨天睡得挺晚的，所以今天有点儿困！","pinyin":"Wǒ zuótiān shuì de tǐng wǎn de, suǒyǐ jīntiān yǒudiǎnr kùn!","meaning":"Hôm qua tớ ngủ khá trễ nên hôm nay hơi buồn ngủ!"}]'::jsonb, 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order) VALUES ('g10_4', 'lesson-10', '1.家 jiā dt. nhà', 'Cấu trúc câu ngữ pháp trọng tâm', 'Quy tắc ngữ pháp quan trọng trong Mua hàng trên mạng.', NULL, '[{"hanzi":"这首歌最近挺流行的！","pinyin":"Zhè shǒu gē zuìjìn tǐng liúxíng de!","meaning":"Bài hát này dạo gần đây khá thịnh hành đấy!"},{"hanzi":"天气太舒服了！","pinyin":"Tiānqì tài shūfu le!","meaning":"Thời tiết dễ chịu quá!"}]'::jsonb, 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order;
INSERT INTO texts (id, lesson_id, title, description, sort_order) VALUES ('txt_10_1', 'lesson-10', 'Bài khoá #1: Hội thoại giáo trình — Mua hàng trên mạng', 'Hội thoại chuẩn giáo trình Bài 10. Từ vựng chưa học được chú thích phiên âm & nghĩa trong ngoặc.', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_10_1_1', 'txt_10_1', '范玉兰', '小雪，下午你跟我一起去商店买书本吧！', '小雪 (Xiǎoxuě: Tiểu Tuyết)，下午你跟 (gēn: cùng, với)我一起去商店买书本吧！', 'Xiǎoxuě, xiàwǔ nǐ gēn wǒ yīqǐ qù shāngdiàn mǎi shūběn ba!', 'Tiểu Tuyết, chiều nay cậu cùng tớ ra cửa hàng mua sách vở nhé!', 1) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_10_1_2', 'txt_10_1', '白茹雪', '你怎么到现在还去商店买东西啊！在中国，人们都在网上买了！', '你怎么到现在还去商店买东西啊！在中国 (Zhōngguó: Trung Quốc)，人们都在网上买了！', 'Nǐ zěnme dào xiànzài hái qù shāngdiàn mǎi dōngxi a! Zài Zhōngguó, rénmen dōu zài wǎngshàng mǎi le!', 'Sao đến bây giờ cậu vẫn còn ra cửa hàng mua đồ vậy! Ở Trung Quốc mọi người đều mua trên mạng hết rồi!', 2) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_10_1_3', 'txt_10_1', '范玉兰', '我不常上网买东西。你经常在网上买东西吗？', '我不常 (bù cháng: không thường xuyên, ít khi)上网买东西。你经常在网上买东西吗？', 'Wǒ bù cháng shàngwǎng mǎi dōngxi. Nǐ jīngcháng zài wǎngshàng mǎi dōngxi ma?', 'Tớ ít khi lên mạng mua đồ. Cậu có hay mua đồ qua mạng không?', 3) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_10_1_4', 'txt_10_1', '白茹雪', '是啊。在网上你可以买到很多东西，比如衣服、手表、眼镜、书本等等。', '是啊。在网上你可以买到很多东西，比如衣服、手表、眼镜、书本等等。', 'Shì a. Zài wǎngshàng nǐ kěyǐ mǎidào hěn duō dōngxi, bǐrú yīfu, shǒubiǎo, yǎnjìng, shūběn děngděng.', 'Có chứ. Trên mạng cậu có thể mua được rất nhiều thứ, ví dụ như quần áo, đồng hồ, kính mắt, sách vở, v.v.', 4) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_10_1_5', 'txt_10_1', '范玉兰', '真的吗？', '真的吗？', 'Zhēn de ma?', 'Thật sao?', 5) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_10_1_6', 'txt_10_1', '白茹雪', '真的。网上购物还挺方便，你只要有电脑或者手机，不用出门也能买到东西。很容易是吧！', '真的。网上购物还挺方便，你只 (zhī: con)要有电脑或者手机，不 (bù: không)用 (yòng: dùng)出门也能买到东西。很容易是吧！', 'Zhēn de. Wǎngshàng gòuwù hái tǐng fāngbiàn, nǐ zhǐyào yǒu diànnǎo huòzhě shǒujī, búyòng chūmén yě néng mǎi dào dōngxi. Hěn róngyì shì ba!', 'Thật đấy. Mua sắm trực tuyến khá tiện lợi, chỉ cần có máy tính hoặc điện thoại là không cần ra khỏi nhà cũng mua được đồ. Rất dễ đúng không nào!', 6) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_10_1_7', 'txt_10_1', '范玉兰', '哇！太方便了！但是网上的东西价格怎么样？', '哇 (wa: oa, chà (cảm thán))！太方便了！但是网上的东西价格怎么样？', 'Wa! Tài fāngbiàn le! Dànshì wǎngshàng de dōngxi jiàgé zěnmeyàng?', 'Chà! Tiện lợi quá! Nhưng giá cả đồ trên mạng thế nào?', 7) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_10_1_8', 'txt_10_1', '白茹雪', '有的挺便宜，有的挺贵。', '有的挺便宜，有的挺贵。', 'Yǒu de tǐng piányi, yǒu de tǐng guì.', 'Có thứ khá rẻ, cũng có thứ khá đắt.', 8) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_10_1_9', 'txt_10_1', '范玉兰', '质量呢？', '质量呢？', 'Zhìliàng ne?', 'Còn chất lượng thì sao?', 9) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_10_1_10', 'txt_10_1', '白茹雪', '有的质量挺好，但是也有的太差了！你要小心啊！', '有的质量挺好，但是也有的太差了！你要小心啊！', 'Yǒu de zhìliàng tǐng hǎo, dànshì yě yǒu de tài chà le! Nǐ yào xiǎoxīn a!', 'Có thứ chất lượng rất tốt, nhưng cũng có thứ tệ lắm! Cậu phải cẩn thận đấy!', 10) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_10_1_11', 'txt_10_1', '范玉兰', '那怎么才能买到好东西？', '那怎么才 (cái: mới)能买到好东西？', 'Nà zěnme cái néng mǎidào hǎo dōngxi?', 'Vậy làm sao để mua được đồ tốt?', 11) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_10_1_12', 'txt_10_1', '白茹雪', '这个不好说。你上网吧，我会告诉你怎么买。', '这个不 (bù: không)好说 (shuō: nói)。你上网吧，我会 (huì: Phó, đtnn biết)告诉你怎么买。', 'Zhège bù hǎoshuō. Nǐ shàngwǎng ba, wǒ huì gàosù nǐ zěnme mǎi.', 'Chuyện này khó nói lắm. Cậu lên mạng đi, tớ sẽ chỉ cậu cách mua.', 12) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_10_1_13', 'txt_10_1', '范玉兰', '好，谢谢你！', '好，谢谢你！', 'Hǎo, xièxie nǐ!', 'Được, cảm ơn bạn!', 13) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_10_1_1', 'lesson-10', 'txt_10_1', 'listening', 'listening', '小雪，下午你跟我一起去商店买书本吧！', NULL, 'Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Người (mà) đi hiệu sách mua sách rất nhiều.","Tiểu Tuyết, chiều nay cậu cùng tớ ra cửa hàng mua sách vở nhé!","Bạn tên là gì?","Tôi làm phiên dịch ở Bộ Ngoại giao."]'::jsonb, 1, 'Nội dung nghe được: 小雪，下午你跟我一起去商店买书本吧！ (Xiǎoxuě, xiàwǔ nǐ gēn wǒ yīqǐ qù shāngdiàn mǎi shūběn ba!) → Tiểu Tuyết, chiều nay cậu cùng tớ ra cửa hàng mua sách vở nhé!', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_10_1_2', 'lesson-10', 'txt_10_1', 'listening', 'listening', '你怎么到现在还去商店买东西啊！在中国，人们都在网上买了！', NULL, 'Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["网上有很多书本，比如词典和笔记本。","你怎么到现在还去商店买东西啊！在中国 (Zhōngguó: Trung Quốc)，人们都在网上买了！","我不常 (bù cháng: không thường xuyên, ít khi)跟 (gēn: cùng, với)李君 (Lǐ Jūn: Lý Quân)联系。","我不常 (bù cháng: không thường xuyên, ít khi)上网买东西。你经常在网上买东西吗？"]'::jsonb, 1, 'Câu vừa đọc: 你怎么到现在还去商店买东西啊！在中国，人们都在网上买了！ (Nǐ zěnme dào xiànzài hái qù shāngdiàn mǎi dōngxi a! Zài Zhōngguó, rénmen dōu zài wǎngshàng mǎi le!) → Sao đến bây giờ cậu vẫn còn ra cửa hàng mua đồ vậy! Ở Trung Quốc mọi người đều mua trên mạng hết rồi!', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_10_1_3', 'lesson-10', 'txt_10_1', 'listening', 'listening', '我不常上网买东西。你经常在网上买东西吗？', NULL, 'Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Nữ sinh phía sau","Bây giờ con chưa muốn làm bài tập, để đến buổi tối rồi làm tiếp!","Hẳn là anh ấy đồng ý rồi?","Tớ ít khi lên mạng mua đồ. Cậu có hay mua đồ qua mạng không?"]'::jsonb, 3, 'Nội dung nghe được: 我不常上网买东西。你经常在网上买东西吗？ (Wǒ bù cháng shàngwǎng mǎi dōngxi. Nǐ jīngcháng zài wǎngshàng mǎi dōngxi ma?) → Tớ ít khi lên mạng mua đồ. Cậu có hay mua đồ qua mạng không?', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_10_1_4', 'lesson-10', 'txt_10_1', 'listening', 'listening', '是啊。在网上你可以买到很多东西，比如衣服、手表、眼镜、书本等等。', NULL, 'Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["是啊。在网上你可以买到很多东西，比如衣服、手表、眼镜、书本等等。","请告诉我这副眼镜多少钱。","这本书是我的。","太难 (nán: khó)了，我不 (bù: không)知道该怎么做 (zuò: làm)！"]'::jsonb, 0, 'Câu vừa đọc: 是啊。在网上你可以买到很多东西，比如衣服、手表、眼镜、书本等等。 (Shì a. Zài wǎngshàng nǐ kěyǐ mǎidào hěn duō dōngxi, bǐrú yīfu, shǒubiǎo, yǎnjìng, shūběn děngděng.) → Có chứ. Trên mạng cậu có thể mua được rất nhiều thứ, ví dụ như quần áo, đồng hồ, kính mắt, sách vở, v.v.', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO texts (id, lesson_id, title, description, sort_order) VALUES ('txt_10_2', 'lesson-10', 'Bài nghe tổng hợp: Ôn tập lũy tiến (Bài 1 – Bài 10)', 'Kết hợp từ vựng & mẫu câu đã học từ Bài 1 đến Bài 9 cùng trọng tâm Bài 10 để củng cố phản xạ nghe.', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_10_2_1', 'txt_10_2', 'Ôn Bài 9', '我们下午去吧！', '我们下午去吧！', 'Wǒmen xiàwǔ qù ba!', 'Buổi chiều chúng ta đi nhé!', 1) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_10_2_2', 'txt_10_2', 'Bài 10', '这本书是我的。', '这本书是我的。', 'Zhè běn shū shì wǒ de.', 'Quyển sách này là sách của tôi.', 2) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_10_2_3', 'txt_10_2', 'Ôn Bài 5', '我明天上午八点上课。', '我明天上午八点上课。', 'Wǒ míngtiān shàngwǔ bā diǎn shàngkè.', 'Tám giờ sáng ngày mai tớ đi học.', 3) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_10_2_4', 'txt_10_2', 'Bài 10', '这条裙子是你的吗？', '这条裙子是你的吗？', 'Zhè tiáo qúnzi shì nǐ de ma?', 'Cái váy này là của em à?', 4) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_10_2_5', 'txt_10_2', 'Ôn Bài 1', '晚上好！', '晚上好！', 'Wǎnshang hǎo', 'Chào buổi tối!', 5) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_10_2_6', 'txt_10_2', 'Bài 10', '是啊。在网上你可以买到很多东西，比如衣服、手表、眼镜、书本等等。', '是啊。在网上你可以买到很多东西，比如衣服、手表、眼镜、书本等等。', 'Shì a. Zài wǎngshàng nǐ kěyǐ mǎidào hěn duō dōngxi, bǐrú yīfu, shǒubiǎo, yǎnjìng, shūběn děngděng.', 'Có chứ. Trên mạng cậu có thể mua được rất nhiều thứ, ví dụ như quần áo, đồng hồ, kính mắt, sách vở, v.v.', 6) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_10_2_7', 'txt_10_2', 'Ôn Bài 8', '你家有多少人？', '你家有多少人？', 'Nǐ jiā yǒu duōshao rén?', 'Nhà cậu có bao nhiêu người?', 7) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_10_2_8', 'txt_10_2', 'Bài 10', '真的吗？', '真的吗？', 'Zhēn de ma?', 'Thật sao?', 8) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_10_2_1', 'lesson-10', 'txt_10_2', 'listening', 'listening', '我们下午去吧！', NULL, '[Ôn tập Bài 9] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Em chào thầy/cô ạ","Cậu nên ngủ sớm dậy sớm.","Tớ bảo mình không phải người Hà Nội lúc nào? (Tớ là người Hà Nội)","Buổi chiều chúng ta đi nhé!"]'::jsonb, 3, 'Nội dung nghe được: 我们下午去吧！ (Wǒmen xiàwǔ qù ba!) → Buổi chiều chúng ta đi nhé!', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_10_2_2', 'lesson-10', 'txt_10_2', 'listening', 'listening', '这本书是我的。', NULL, '[Bài 10] Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["小雪 (Xiǎoxuě: Tiểu Tuyết)，下午你跟 (gēn: cùng, với)我一起去商店买书本吧！","质量呢？","这本书是我的。","我不常 (bù cháng: không thường xuyên, ít khi)跟 (gēn: cùng, với)李君 (Lǐ Jūn: Lý Quân)联系。"]'::jsonb, 2, 'Câu vừa đọc: 这本书是我的。 (Zhè běn shū shì wǒ de.) → Quyển sách này là sách của tôi.', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_10_2_3', 'lesson-10', 'txt_10_2', 'listening', 'listening', '我明天上午八点上课。', NULL, '[Ôn tập Bài 5] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["tiếng gõ cửa","Tám giờ sáng ngày mai tớ đi học.","sách mà tôi mua","Bộ quần áo này không to cũng không nhỏ."]'::jsonb, 1, 'Nội dung nghe được: 我明天上午八点上课。 (Wǒ míngtiān shàngwǔ bā diǎn shàngkè.) → Tám giờ sáng ngày mai tớ đi học.', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_10_2_4', 'lesson-10', 'txt_10_2', 'listening', 'listening', '这条裙子是你的吗？', NULL, '[Bài 10] Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["这条裙子是你的吗？","网上有很多书本，比如词典和笔记本。","小雪 (Xiǎoxuě: Tiểu Tuyết)，下午你跟 (gēn: cùng, với)我一起去商店买书本吧！","我不常 (bù cháng: không thường xuyên, ít khi)跟 (gēn: cùng, với)李君 (Lǐ Jūn: Lý Quân)联系。"]'::jsonb, 0, 'Câu vừa đọc: 这条裙子是你的吗？ (Zhè tiáo qúnzi shì nǐ de ma?) → Cái váy này là của em à?', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_10_2_5', 'lesson-10', 'txt_10_2', 'listening', 'listening', '晚上好！', NULL, '[Ôn tập Bài 1] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Chào buổi tối!","Tôi so sánh đáp án với anh ấy.","Chào thầy/Chào cô","Cậu ấy vẽ hết một buổi sáng mới vẽ xong bức tranh này."]'::jsonb, 0, 'Nội dung nghe được: 晚上好！ (Wǎnshang hǎo) → Chào buổi tối!', 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO texts (id, lesson_id, title, description, sort_order) VALUES ('txt_10_3', 'lesson-10', 'Bài khoá mở rộng: Mua đồ dùng học tập trực tuyến (Mở rộng)', 'Hội thoại tình huống mới xây dựng dựa trên từ vựng và ngữ pháp Bài 10 (không trùng lặp nguyên văn giáo trình).', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_10_3_1', 'txt_10_3', 'Mark', '你这副新眼镜是在超市买的吗？', '你这副新眼镜是在超市买的吗？', 'Nǐ zhè fù xīn yǎnjìng shì zài chāoshì mǎi de ma?', 'Cặp kính mắt mới này của bạn mua ở siêu thị à?', 1) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_10_3_2', 'txt_10_3', 'Minh', '不是，我是在网上买的，不用出门也很方便。', '不 (bù: không)是，我是在网上买的，不用 (yòng: dùng)出门也很方便。', 'Bú shì, wǒ shì zài wǎngshàng mǎi de, búyòng chūmén yě hěn fāngbiàn.', 'Không, tôi mua trên mạng đấy, không cần ra ngoài mà rất tiện lợi.', 2) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_10_3_3', 'txt_10_3', 'Mark', '网上的价格便宜吗？质量好不好？', '网上的价格便宜吗？质量好不 (bù: không)好？', 'Wǎngshàng de jiàgé piányi ma? Zhìliàng hǎo bu hǎo?', 'Giá trên mạng có rẻ không? Chất lượng có tốt không?', 3) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_10_3_4', 'txt_10_3', 'Minh', '价格比商店便宜，但是买的时候要小心看质量。', '价格比商店便宜，但是买的时候要小心看质量。', 'Jiàgé bǐ shāngdiàn piányi, dànshì mǎi de shíhou yào xiǎoxīn kàn zhìliàng.', 'Giá rẻ hơn cửa hàng, nhưng lúc mua phải cẩn thận xem chất lượng.', 4) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_10_3_1', 'lesson-10', 'txt_10_3', 'listening', 'listening', '你这副新眼镜是在超市买的吗？ 不是，我是在网上买的，不用出门也很方便。 网上的价格便宜吗？质量好不好？ 价格比商店便宜，但是买的时候要小心看质量。', NULL, '[Nghe hiểu tình huống mới] Theo lời Minh, khi mua hàng trên mạng cần chú ý điều gì?', '["Chỉ cần chọn món đắt nhất","Không được mua kính mắt trên mạng","Phải đến tận siêu thị thanh toán","Phải cẩn thận xem xét chất lượng sản phẩm"]'::jsonb, 3, 'Minh khuyên: ''买的时候要小心看质量'' (cẩn thận xem chất lượng).', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_10_3_2', 'lesson-10', 'txt_10_3', 'listening', 'listening', '你这副新眼镜是在超市买的吗？', NULL, '[Mở rộng] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Cặp kính mắt mới này của bạn mua ở siêu thị à?","Tớ học được môn Thái cực quyền rồi.","Tôi có một cậu em trai.","Phía bên trái nhà ăn"]'::jsonb, 0, 'Nội dung nghe được: 你这副新眼镜是在超市买的吗？ (Nǐ zhè fù xīn yǎnjìng shì zài chāoshì mǎi de ma?) → Cặp kính mắt mới này của bạn mua ở siêu thị à?', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_10_3_3', 'lesson-10', 'txt_10_3', 'listening', 'listening', '不是，我是在网上买的，不用出门也很方便。', NULL, '[Mở rộng] Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["网上买的手表质量怎么样？","真的吗？","有的质量挺好，但是也有的太差了！你要小心啊！","不 (bù: không)是，我是在网上买的，不用 (yòng: dùng)出门也很方便。"]'::jsonb, 3, 'Câu vừa đọc: 不是，我是在网上买的，不用出门也很方便。 (Bú shì, wǒ shì zài wǎngshàng mǎi de, búyòng chūmén yě hěn fāngbiàn.) → Không, tôi mua trên mạng đấy, không cần ra ngoài mà rất tiện lợi.', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_10_3_4', 'lesson-10', 'txt_10_3', 'listening', 'listening', '网上的价格便宜吗？质量好不好？', NULL, '[Mở rộng] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Hai người họ dường như là bạn bè thân thiết đã nhiều năm rồi.","Bạn có thể đi mua mũ cùng với tôi không?","Tôi đang đọc sách.","Giá trên mạng có rẻ không? Chất lượng có tốt không?"]'::jsonb, 3, 'Nội dung nghe được: 网上的价格便宜吗？质量好不好？ (Wǎngshàng de jiàgé piányi ma? Zhìliàng hǎo bu hǎo?) → Giá trên mạng có rẻ không? Chất lượng có tốt không?', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss10_1', 'lesson-10', '网上买的手表质量怎么样', '[Mở rộng] Chất lượng đồng hồ mua trên mạng thế nào?', 'Wǎngshàng mǎi de shǒubiǎo zhìliàng zěnmeyàng?', '["网上","买","的","手表","质量","怎么样"]'::jsonb, NULL, 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss10_2', 'lesson-10', '请告诉我这副眼镜多少钱', '[Mở rộng] Làm ơn cho tôi biết cặp kính mắt này bao nhiêu tiền.', 'Qǐng gàosu wǒ zhè fù yǎnjìng duōshao qián.', '["请告诉","我这","副","眼镜","多少","钱"]'::jsonb, NULL, 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss10_3', 'lesson-10', '这本书是我的', 'Quyển sách này là sách của tôi.', 'Zhè běn shū shì wǒ de.', '["这","本","书","是","我","的"]'::jsonb, NULL, 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss10_4', 'lesson-10', '这条裙子是你的吗', 'Cái váy này là của em à?', 'Zhè tiáo qúnzi shì nǐ de ma?', '["这","条","裙子","是","你的","吗"]'::jsonb, NULL, 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss10_5', 'lesson-10', '她叫什么名字', '[Ôn tập Bài 2] Cô ấy tên là gì?', 'Tā jiào shénme míngzi?', '["她","叫","什么","名字"]'::jsonb, NULL, 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss10_6', 'lesson-10', '你去学校附近的地方吗', '[Ôn tập Bài 4] Bạn có đi đến chỗ gần trường không?', 'Nǐ qù xuéxiào fùjìn de dìfang ma?', '["你去","学校","附近","的","地方","吗"]'::jsonb, NULL, 6) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss10_exp_1', 'lesson-10', '小雪下午你跟我一起去商店买书本吧', 'Tiểu Tuyết, chiều nay cậu cùng tớ ra cửa hàng mua sách vở nhé!', 'Xiǎoxuě, xiàwǔ nǐ gēn wǒ yīqǐ qù shāngdiàn mǎi shūběn ba!', '["小","雪","下午","你","跟","我","一起","去","商店","买","书本","吧"]'::jsonb, NULL, 7) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss10_exp_2', 'lesson-10', '你怎么到现在还去商店买东西啊在中国人们都在网上买了', 'Sao đến bây giờ cậu vẫn còn ra cửa hàng mua đồ vậy! Ở Trung Quốc mọi người đều mua trên mạng hết rồi!', 'Nǐ zěnme dào xiànzài hái qù shāngdiàn mǎi dōngxi a! Zài Zhōngguó, rénmen dōu zài wǎngshàng mǎi le!', '["你","怎么","到","现在","还","去","商店","买","东西","啊","在","中国","人","们","都","在","网上","买","了"]'::jsonb, NULL, 8) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss10_exp_3', 'lesson-10', '我不常上网买东西你经常在网上买东西吗', 'Tớ ít khi lên mạng mua đồ. Cậu có hay mua đồ qua mạng không?', 'Wǒ bù cháng shàngwǎng mǎi dōngxi. Nǐ jīngcháng zài wǎngshàng mǎi dōngxi ma?', '["我","不","常","上网","买","东西","你","经常","在","网上","买","东西","吗"]'::jsonb, NULL, 9) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss10_exp_4', 'lesson-10', '是啊在网上你可以买到很多东西比如衣服手表眼镜书本等等', 'Có chứ. Trên mạng cậu có thể mua được rất nhiều thứ, ví dụ như quần áo, đồng hồ, kính mắt, sách vở, v.v.', 'Shì a. Zài wǎngshàng nǐ kěyǐ mǎidào hěn duō dōngxi, bǐrú yīfu, shǒubiǎo, yǎnjìng, shūběn děngděng.', '["是","啊","在","网上","你","可以","买","到","很","多","东西","比如","衣服","手表","眼镜","书本","等等"]'::jsonb, NULL, 10) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss10_exp_5', 'lesson-10', '真的吗', 'Thật sao?', 'Zhēn de ma?', '["真","的","吗"]'::jsonb, NULL, 11) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss10_exp_6', 'lesson-10', '真的网上购物还挺方便你只要有电脑或者手机不用出门也能买到东西很容易是吧', 'Thật đấy. Mua sắm trực tuyến khá tiện lợi, chỉ cần có máy tính hoặc điện thoại là không cần ra khỏi nhà cũng mua được đồ. Rất dễ đúng không nào!', 'Zhēn de. Wǎngshàng gòuwù hái tǐng fāngbiàn, nǐ zhǐyào yǒu diànnǎo huòzhě shǒujī, búyòng chūmén yě néng mǎi dào dōngxi. Hěn róngyì shì ba!', '["真","的","网上","购物","还","挺","方便","你","只","要","有","电脑","或者","手机","不","用","出门","也","能","买","到","东西","很","容易","是","吧"]'::jsonb, NULL, 12) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss10_exp_7', 'lesson-10', '哇太方便了但是网上的东西价格怎么样', 'Chà! Tiện lợi quá! Nhưng giá cả đồ trên mạng thế nào?', 'Wa! Tài fāngbiàn le! Dànshì wǎngshàng de dōngxi jiàgé zěnmeyàng?', '["哇","太","方便","了","但是","网上","的","东西","价格","怎么样"]'::jsonb, NULL, 13) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss10_exp_8', 'lesson-10', '有的挺便宜有的挺贵', 'Có thứ khá rẻ, cũng có thứ khá đắt.', 'Yǒu de tǐng piányi, yǒu de tǐng guì.', '["有","的","挺","便宜","有","的","挺","贵"]'::jsonb, NULL, 14) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss10_exp_9', 'lesson-10', '质量呢', 'Còn chất lượng thì sao?', 'Zhìliàng ne?', '["质量","呢"]'::jsonb, NULL, 15) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss10_exp_10', 'lesson-10', '有的质量挺好但是也有的太差了你要小心啊', 'Có thứ chất lượng rất tốt, nhưng cũng có thứ tệ lắm! Cậu phải cẩn thận đấy!', 'Yǒu de zhìliàng tǐng hǎo, dànshì yě yǒu de tài chà le! Nǐ yào xiǎoxīn a!', '["有","的","质量","挺","好","但是","也","有","的","太","差","了","你","要","小心","啊"]'::jsonb, NULL, 16) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss10_exp_11', 'lesson-10', '那怎么才能买到好东西', 'Vậy làm sao để mua được đồ tốt?', 'Nà zěnme cái néng mǎidào hǎo dōngxi?', '["那","怎么","才","能","买","到","好","东西"]'::jsonb, NULL, 17) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss10_exp_12', 'lesson-10', '这个不好说你上网吧我会告诉你怎么买', 'Chuyện này khó nói lắm. Cậu lên mạng đi, tớ sẽ chỉ cậu cách mua.', 'Zhège bù hǎoshuō. Nǐ shàngwǎng ba, wǒ huì gàosù nǐ zěnme mǎi.', '["这","个","不","好","说","你","上网","吧","我","会","告诉","你","怎么","买"]'::jsonb, NULL, 18) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss10_exp_13', 'lesson-10', '好谢谢你', 'Được, cảm ơn bạn!', 'Hǎo, xièxie nǐ!', '["好","谢谢","你"]'::jsonb, NULL, 19) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss10_exp_14', 'lesson-10', '我们下午去吧', 'Buổi chiều chúng ta đi nhé!', 'Wǒmen xiàwǔ qù ba!', '["我们","下午","去","吧"]'::jsonb, NULL, 20) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr10_vi_1', 'lesson-10', 'vi_to_zh', '[Mở rộng] Chất lượng đồng hồ mua trên mạng thế nào?', NULL, NULL, '网上买的手表质量怎么样？', NULL, 'wǎngshàng mǎi de shǒubiǎo zhìliàng zěnmeyàng', '[]'::jsonb, 'Gợi ý Pinyin: Wǎngshàng mǎi de shǒubiǎo zhìliàng zěnmeyàng?', 'Chất lượng đồng hồ mua trên mạng thế nào? → 网上买的手表质量怎么样？ (Wǎngshàng mǎi de shǒubiǎo zhìliàng zěnmeyàng?)', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr10_vi_2', 'lesson-10', 'vi_to_zh', '[Mở rộng] Trên mạng có rất nhiều sách vở, ví dụ như từ điển và vở ghi.', NULL, NULL, '网上有很多书本，比如词典和笔记本。', NULL, 'wǎngshàng yǒu hěnduō shūběn bǐrú cídiǎn hé bǐjìběn', '[]'::jsonb, 'Gợi ý Pinyin: Wǎngshàng yǒu hěnduō shūběn, bǐrú cídiǎn hé bǐjìběn.', 'Trên mạng có rất nhiều sách vở, ví dụ như từ điển và vở ghi. → 网上有很多书本，比如词典和笔记本。 (Wǎngshàng yǒu hěnduō shūběn, bǐrú cídiǎn hé bǐjìběn.)', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr10_vi_3', 'lesson-10', 'vi_to_zh', 'Quyển sách này là sách của tôi.', NULL, NULL, '这本书是我的。', NULL, 'zhè běn shū shì wǒ de', '[]'::jsonb, 'Gợi ý Pinyin: Zhè běn shū shì wǒ de.', 'Quyển sách này là sách của tôi. → 这本书是我的。 (Zhè běn shū shì wǒ de.)', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr10_vi_4', 'lesson-10', 'vi_to_zh', 'Cái váy này là của em à?', NULL, NULL, '这条裙子是你的吗？', NULL, 'zhè tiáo qúnzi shì nǐ de ma', '[]'::jsonb, 'Gợi ý Pinyin: Zhè tiáo qúnzi shì nǐ de ma?', 'Cái váy này là của em à? → 这条裙子是你的吗？ (Zhè tiáo qúnzi shì nǐ de ma?)', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr10_vi_exp_1', 'lesson-10', 'vi_to_zh', 'Tiểu Tuyết, chiều nay cậu cùng tớ ra cửa hàng mua sách vở nhé!', NULL, NULL, '小雪，下午你跟我一起去商店买书本吧！', NULL, 'xiǎoxuě xiàwǔ nǐ gēn wǒ yīqǐ qù shāngdiàn mǎi shūběn ba', '[]'::jsonb, 'Gợi ý Pinyin: Xiǎoxuě, xiàwǔ nǐ gēn wǒ yīqǐ qù shāngdiàn mǎi shūběn ba!', 'Tiểu Tuyết, chiều nay cậu cùng tớ ra cửa hàng mua sách vở nhé! → 小雪，下午你跟我一起去商店买书本吧！ (Xiǎoxuě, xiàwǔ nǐ gēn wǒ yīqǐ qù shāngdiàn mǎi shūběn ba!)', 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr10_vi_exp_2', 'lesson-10', 'vi_to_zh', 'Sao đến bây giờ cậu vẫn còn ra cửa hàng mua đồ vậy! Ở Trung Quốc mọi người đều mua trên mạng hết rồi!', NULL, NULL, '你怎么到现在还去商店买东西啊！在中国，人们都在网上买了！', NULL, 'nǐ zěnme dào xiànzài hái qù shāngdiàn mǎi dōngxi a zài zhōngguó rénmen dōu zài wǎngshàng mǎi le', '[]'::jsonb, 'Gợi ý Pinyin: Nǐ zěnme dào xiànzài hái qù shāngdiàn mǎi dōngxi a! Zài Zhōngguó, rénmen dōu zài wǎngshàng mǎi le!', 'Sao đến bây giờ cậu vẫn còn ra cửa hàng mua đồ vậy! Ở Trung Quốc mọi người đều mua trên mạng hết rồi! → 你怎么到现在还去商店买东西啊！在中国，人们都在网上买了！ (Nǐ zěnme dào xiànzài hái qù shāngdiàn mǎi dōngxi a! Zài Zhōngguó, rénmen dōu zài wǎngshàng mǎi le!)', 6) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr10_vi_exp_3', 'lesson-10', 'vi_to_zh', 'Tớ ít khi lên mạng mua đồ. Cậu có hay mua đồ qua mạng không?', NULL, NULL, '我不常上网买东西。你经常在网上买东西吗？', NULL, 'wǒ bù cháng shàngwǎng mǎi dōngxi nǐ jīngcháng zài wǎngshàng mǎi dōngxi ma', '[]'::jsonb, 'Gợi ý Pinyin: Wǒ bù cháng shàngwǎng mǎi dōngxi. Nǐ jīngcháng zài wǎngshàng mǎi dōngxi ma?', 'Tớ ít khi lên mạng mua đồ. Cậu có hay mua đồ qua mạng không? → 我不常上网买东西。你经常在网上买东西吗？ (Wǒ bù cháng shàngwǎng mǎi dōngxi. Nǐ jīngcháng zài wǎngshàng mǎi dōngxi ma?)', 7) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr10_vi_exp_4', 'lesson-10', 'vi_to_zh', 'Có chứ. Trên mạng cậu có thể mua được rất nhiều thứ, ví dụ như quần áo, đồng hồ, kính mắt, sách vở, v.v.', NULL, NULL, '是啊。在网上你可以买到很多东西，比如衣服、手表、眼镜、书本等等。', NULL, 'shì a zài wǎngshàng nǐ kěyǐ mǎidào hěn duō dōngxi bǐrú yīfu shǒubiǎo yǎnjìng shūběn děngděng', '[]'::jsonb, 'Gợi ý Pinyin: Shì a. Zài wǎngshàng nǐ kěyǐ mǎidào hěn duō dōngxi, bǐrú yīfu, shǒubiǎo, yǎnjìng, shūběn děngděng.', 'Có chứ. Trên mạng cậu có thể mua được rất nhiều thứ, ví dụ như quần áo, đồng hồ, kính mắt, sách vở, v.v. → 是啊。在网上你可以买到很多东西，比如衣服、手表、眼镜、书本等等。 (Shì a. Zài wǎngshàng nǐ kěyǐ mǎidào hěn duō dōngxi, bǐrú yīfu, shǒubiǎo, yǎnjìng, shūběn děngděng.)', 8) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr10_vi_exp_5', 'lesson-10', 'vi_to_zh', 'Thật sao?', NULL, NULL, '真的吗？', NULL, 'zhēn de ma', '[]'::jsonb, 'Gợi ý Pinyin: Zhēn de ma?', 'Thật sao? → 真的吗？ (Zhēn de ma?)', 9) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr10_vi_exp_6', 'lesson-10', 'vi_to_zh', 'Thật đấy. Mua sắm trực tuyến khá tiện lợi, chỉ cần có máy tính hoặc điện thoại là không cần ra khỏi nhà cũng mua được đồ. Rất dễ đúng không nào!', NULL, NULL, '真的。网上购物还挺方便，你只要有电脑或者手机，不用出门也能买到东西。很容易是吧！', NULL, 'zhēn de wǎngshàng gòuwù hái tǐng fāngbiàn nǐ zhǐyào yǒu diànnǎo huòzhě shǒujī búyòng chūmén yě néng mǎi dào dōngxi hěn róngyì shì ba', '[]'::jsonb, 'Gợi ý Pinyin: Zhēn de. Wǎngshàng gòuwù hái tǐng fāngbiàn, nǐ zhǐyào yǒu diànnǎo huòzhě shǒujī, búyòng chūmén yě néng mǎi dào dōngxi. Hěn róngyì shì ba!', 'Thật đấy. Mua sắm trực tuyến khá tiện lợi, chỉ cần có máy tính hoặc điện thoại là không cần ra khỏi nhà cũng mua được đồ. Rất dễ đúng không nào! → 真的。网上购物还挺方便，你只要有电脑或者手机，不用出门也能买到东西。很容易是吧！ (Zhēn de. Wǎngshàng gòuwù hái tǐng fāngbiàn, nǐ zhǐyào yǒu diànnǎo huòzhě shǒujī, búyòng chūmén yě néng mǎi dào dōngxi. Hěn róngyì shì ba!)', 10) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr10_vi_exp_7', 'lesson-10', 'vi_to_zh', 'Chà! Tiện lợi quá! Nhưng giá cả đồ trên mạng thế nào?', NULL, NULL, '哇！太方便了！但是网上的东西价格怎么样？', NULL, 'wa tài fāngbiàn le dànshì wǎngshàng de dōngxi jiàgé zěnmeyàng', '[]'::jsonb, 'Gợi ý Pinyin: Wa! Tài fāngbiàn le! Dànshì wǎngshàng de dōngxi jiàgé zěnmeyàng?', 'Chà! Tiện lợi quá! Nhưng giá cả đồ trên mạng thế nào? → 哇！太方便了！但是网上的东西价格怎么样？ (Wa! Tài fāngbiàn le! Dànshì wǎngshàng de dōngxi jiàgé zěnmeyàng?)', 11) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr10_vi_exp_8', 'lesson-10', 'vi_to_zh', 'Có thứ khá rẻ, cũng có thứ khá đắt.', NULL, NULL, '有的挺便宜，有的挺贵。', NULL, 'yǒu de tǐng piányi yǒu de tǐng guì', '[]'::jsonb, 'Gợi ý Pinyin: Yǒu de tǐng piányi, yǒu de tǐng guì.', 'Có thứ khá rẻ, cũng có thứ khá đắt. → 有的挺便宜，有的挺贵。 (Yǒu de tǐng piányi, yǒu de tǐng guì.)', 12) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr10_vi_exp_9', 'lesson-10', 'vi_to_zh', 'Còn chất lượng thì sao?', NULL, NULL, '质量呢？', NULL, 'zhìliàng ne', '[]'::jsonb, 'Gợi ý Pinyin: Zhìliàng ne?', 'Còn chất lượng thì sao? → 质量呢？ (Zhìliàng ne?)', 13) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr10_vi_exp_10', 'lesson-10', 'vi_to_zh', 'Có thứ chất lượng rất tốt, nhưng cũng có thứ tệ lắm! Cậu phải cẩn thận đấy!', NULL, NULL, '有的质量挺好，但是也有的太差了！你要小心啊！', NULL, 'yǒu de zhìliàng tǐng hǎo dànshì yě yǒu de tài chà le nǐ yào xiǎoxīn a', '[]'::jsonb, 'Gợi ý Pinyin: Yǒu de zhìliàng tǐng hǎo, dànshì yě yǒu de tài chà le! Nǐ yào xiǎoxīn a!', 'Có thứ chất lượng rất tốt, nhưng cũng có thứ tệ lắm! Cậu phải cẩn thận đấy! → 有的质量挺好，但是也有的太差了！你要小心啊！ (Yǒu de zhìliàng tǐng hǎo, dànshì yě yǒu de tài chà le! Nǐ yào xiǎoxīn a!)', 14) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
