INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq10_13', 'lesson-10', NULL, 'expanded_quiz', 'radical', NULL, NULL, 'Chữ Hán “网上” chứa bộ thủ nào sau đây?', '["网/罒 (Võng) (Tấm lưới, che phủ)","面 (Diện) (Khuôn mặt, bề mặt, mì sợi)","勹 (Bao) (Bao bọc, ôm lấy)","心/忄 (Tâm) (Trái tim, tình cảm, suy nghĩ, tâm lý)"]'::jsonb, 0, 'Chữ “网上” có bộ chính 网/罒 (Võng) (Tấm lưới, che phủ). Chiết tự: 网: Bộ 网 (Võng - mắt lưới đan chéo) • 上: Nét đứng 丨 và nét chấm chỉ hướng phía trên gạch ngang 一', 13) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq10_14', 'lesson-10', NULL, 'expanded_quiz', 'radical', NULL, NULL, 'Chữ Hán “电脑” chứa bộ thủ nào sau đây?', '["八 (Bát) (Số tám, phân chia, mở rộng)","幺 (Yêu) (Nhỏ bé, sợi tơ nhỏ)","玉/王 (Ngọc) (Đá quý, vua chúa)","田 (Điền) (Ruộng đất, khu vực, mặt)"]'::jsonb, 3, 'Chữ “电脑” có bộ chính 田 (Điền) (Ruộng đất, khu vực, mặt). Chiết tự: 电: 日/田 (biến thể) + 乚 (tia sét phóng xuống) • 脑: 月 (Nhục: cơ quan cơ thể) + 亠 + 凶 (Não bộ)', 14) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq10_15', 'lesson-10', NULL, 'expanded_quiz', 'radical', NULL, NULL, 'Chữ Hán “手机” chứa bộ thủ nào sau đây?', '["白 (Bạch) (Màu trắng, sáng tỏ)","走 (Tẩu) (Chạy, đi lại, rời đi)","手/扌 (Thủ) (Bàn tay, động tác, thao tác)","丶 (Chủ) (Điểm chấm, khởi đầu)"]'::jsonb, 2, 'Chữ “手机” có bộ chính 手/扌 (Thủ) (Bàn tay, động tác, thao tác). Chiết tự: 手: Bộ 手 (Thủ - hình bàn tay 5 ngón) • 机: 木 (Mộc: khung máy) + 几 (Kỷ)', 15) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq10_16', 'lesson-10', NULL, 'expanded_quiz', 'radical', NULL, NULL, 'Chữ Hán “手表” chứa bộ thủ nào sau đây?', '["手/扌 (Thủ) (Bàn tay, động tác, thao tác)","老/耂 (Lão) (Người già, lâu năm, tôn kính)","音 (Âm) (Âm thanh, tiếng vang)","匕 (Chủy) (Cái thìa, dao găm)"]'::jsonb, 0, 'Chữ “手表” có bộ chính 手/扌 (Thủ) (Bàn tay, động tác, thao tác). Chiết tự: 手: Bộ 手 (Thủ - hình bàn tay 5 ngón) • 表: 三 + 丨 + 衣 (phần ngoài áo, biểu hiện, đồng hồ)', 16) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq10_17', 'lesson-10', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, '[Ôn tập Bài 1] Từ đã học “晚上” (wǎnshàng) có nghĩa là gì?', '["cùng nhau","nói cho","buổi tối","Giáo viên, thầy cô giáo"]'::jsonb, 2, 'Ôn tập Bài 1: “晚上” (wǎnshàng) nghĩa là: buổi tối.', 17) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq10_18', 'lesson-10', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, '[Ôn tập Bài 2] Từ đã học “她” (tā) có nghĩa là gì?', '["cô ấy, bà ấy, chị ấy,... (ngôi thứ ba số ít chỉ nữ)","Sao thế, như thế nào","chất lượng","cân (= 0,5kg ở Việt Nam)"]'::jsonb, 0, 'Ôn tập Bài 2: “她” (tā) nghĩa là: cô ấy, bà ấy, chị ấy,... (ngôi thứ ba số ít chỉ nữ).', 18) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq10_19', 'lesson-10', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, '[Ôn tập Bài 1] Từ đã học “学校” (xuéxiào) có nghĩa là gì?', '["anh ấy, cậu ấy... (ngôi thứ ba số ít chỉ nam)","đi","Trường học","đồng hồ"]'::jsonb, 2, 'Ôn tập Bài 1: “学校” (xuéxiào) nghĩa là: Trường học.', 19) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq10_20', 'lesson-10', NULL, 'expanded_quiz', 'reading', NULL, NULL, '[Mở rộng] Câu “网上买的手表质量怎么样？” có nghĩa tiếng Việt là gì?', '["Chất lượng đồng hồ mua trên mạng thế nào?","Quyển sách này là sách của tôi.","Một con bò","Một việc/chuyện"]'::jsonb, 0, '网上买的手表质量怎么样？ (Wǎngshàng mǎi de shǒubiǎo zhìliàng zěnmeyàng?) → Chất lượng đồng hồ mua trên mạng thế nào?', 20) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
