INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq10_22', 'lesson-10', NULL, 'expanded_quiz', 'reading', NULL, NULL, 'Câu “这本书是我的。” có nghĩa tiếng Việt là gì?', '["Cậu mua đi!","Quyển sách này là sách của tôi.","Chạy một chuyến","Dùng điện thoại lên mạng mua sắm vô cùng tiện lợi."]'::jsonb, 1, '这本书是我的。 (Zhè běn shū shì wǒ de.) → Quyển sách này là sách của tôi.', 22) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct10_1', 'lesson-10', NULL, 'comprehensive_test', 'listening', '你家有多少人？', NULL, 'Nghe đoạn ghi âm và chọn nghĩa tiếng Việt đúng:', '["Nhà cậu có bao nhiêu người?","Vậy chiều nay 4 giờ tôi đợi bạn ở cổng trường. Chúng ta cùng đi nhé, được không?","zǒu jiù dào.","cây thước kẻ của anh ấy"]'::jsonb, 0, 'Nội dung nghe được: “你家有多少人？” (Nǐ jiā yǒu duōshao rén?) → Nhà cậu có bao nhiêu người?', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct10_2', 'lesson-10', NULL, 'comprehensive_test', 'listening', '晚上好！', NULL, 'Nghe đoạn ghi âm và chọn câu tiếng Trung khớp với nội dung vừa nghe:', '["你的前面是城市图书馆。","晚上好！","真漂亮！我也想买一个黄色的。","小兰！你跟我一起去超市买衣服，好吗？"]'::jsonb, 1, 'Câu vừa đọc: “晚上好！” (Wǎnshang hǎo) → Chào buổi tối!', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct10_3', 'lesson-10', NULL, 'comprehensive_test', 'listening', '这首歌最近挺流行的！', NULL, 'Nghe đoạn ghi âm và chọn nghĩa tiếng Việt đúng:', '["Giá trên mạng có rẻ không? Chất lượng có tốt không?","Tớ muốn mua một chiếc quần dài, một chiếc váy và một chiếc áo khoác dài.","Cậu xem chiếc cặp màu xanh dương này có đẹp không?","Bài hát này dạo gần đây khá thịnh hành đấy!"]'::jsonb, 3, 'Nội dung nghe được: “这首歌最近挺流行的！” (Zhè shǒu gē zuìjìn tǐng liúxíng de!) → Bài hát này dạo gần đây khá thịnh hành đấy!', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct10_4', 'lesson-10', NULL, 'comprehensive_test', 'listening', '哇！太方便了！但是网上的东西价格怎么样？', NULL, 'Nghe đoạn ghi âm và chọn câu tiếng Trung khớp với nội dung vừa nghe:', '["你觉得这条裤子好不好看？","哇！太方便了！但是网上的东西价格怎么样？","张风，你知道书店在哪儿吗？","你怎么到现在还去商店买东西啊！在中国，人们都在网上买了！"]'::jsonb, 1, 'Câu vừa đọc: “哇！太方便了！但是网上的东西价格怎么样？” (Wa! Tài fāngbiàn le! Dànshì wǎngshàng de dōngxi jiàgé zěnmeyàng?) → Chà! Tiện lợi quá! Nhưng giá cả đồ trên mạng thế nào?', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct10_5', 'lesson-10', NULL, 'comprehensive_test', 'listening', '请告诉我这副眼镜多少钱', NULL, 'Nghe đoạn ghi âm và chọn nghĩa tiếng Việt đúng:', '["Một quả 7 tệ.","Đây là sách của tôi.","Phòng của thầy Vương là số mấy?","Làm ơn cho tôi biết cặp kính mắt này bao nhiêu tiền."]'::jsonb, 3, 'Nội dung nghe được: “请告诉我这副眼镜多少钱” (Qǐng gàosu wǒ zhè fù yǎnjìng duōshao qián.) → Làm ơn cho tôi biết cặp kính mắt này bao nhiêu tiền.', 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct10_6', 'lesson-10', NULL, 'comprehensive_test', 'listening', '是啊。在网上你可以买到很多东西，比如衣服、手表、眼镜、书本等等。', NULL, 'Nghe đoạn ghi âm và chọn câu tiếng Trung khớp với nội dung vừa nghe:', '["我也是。这是我的电话号码 0322110012。明天去上课的时候你给我打电话，好吗？","不错，很合适。我买这条吧！","你也是留学生吗？","是啊。在网上你可以买到很多东西，比如衣服、手表、眼镜、书本等等。"]'::jsonb, 3, 'Câu vừa đọc: “是啊。在网上你可以买到很多东西，比如衣服、手表、眼镜、书本等等。” (Shì a. Zài wǎngshàng nǐ kěyǐ mǎidào hěn duō dōngxi, bǐrú yīfu, shǒubiǎo, yǎnjìng, shūběn děngděng.) → Có chứ. Trên mạng cậu có thể mua được rất nhiều thứ, ví dụ như quần áo, đồng hồ, kính mắt, sách vở, v.v.', 6) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct10_7', 'lesson-10', NULL, 'comprehensive_test', 'listening', '那怎么才能买到好东西？', NULL, 'Nghe đoạn ghi âm và chọn nghĩa tiếng Việt đúng:', '["Cậu có biết chữ này viết như thế nào không?","Vậy làm sao để mua được đồ tốt?","Hôm qua cậu đã đến trường chưa?","Phía bên trái nhà ăn"]'::jsonb, 1, 'Nội dung nghe được: “那怎么才能买到好东西？” (Nà zěnme cái néng mǎidào hǎo dōngxi?) → Vậy làm sao để mua được đồ tốt?', 7) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
