INSERT INTO lessons (id, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id) VALUES ('lesson-11', 'Bài 11: Thành viên trong gia đình - Đơn nguyên 3: Gia đình', 'Bài 11', 'Đơn nguyên 3: Gia đình', 'Xưng hô trong gia đình, nghề nghiệp người thân, cấu trúc 有/没有, lượng từ 口 và 个.', '2026-11-14'::date, 11, TRUE, NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, date_added = EXCLUDED.date_added, sort_order = EXCLUDED.sort_order, is_system = TRUE, updated_at = NOW();
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v11_1', 'lesson-11', '家', 'jiā', 'gia', 'nhà', 'Danh từ', '宀 (Miên) (Mái nhà, che chở, nơi ở)', '家 = 宀 (Miên: mái nhà) + 豕 (Thỉ: lợn nuôi dưới mái nhà).', 'Chữ 家 (jiā) mang nghĩa "nhà", bộ chính 宀 (Miên); cấu tạo: 宀 (Miên: mái nhà) + 豕 (Thỉ: lợn nuôi dưới mái nhà).', '学校左边有一家银行。', 'Xuéxiào zuǒbian yǒu yījiā yínháng.', 'Phía bên trái trường học có một ngân hàng.', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v11_2', 'lesson-11', '全家', 'quánjiā', 'gia', 'cả nhà', 'Danh từ', '人/亻 (Nhân) (Con người, nhân loại, hành động)', '全: 人 (Nhân: mái che) + 王 (Ngọc: viên ngọc nguyên vẹn) • 家: 宀 (Miên: mái nhà) + 豕 (Thỉ: lợn nuôi dưới mái nhà)', 'Ghép 全 [bộ 人] + 家 [bộ 宀] để nhớ từ 全家 (quánjiā): "cả nhà".', '她今年 22 岁。你想看我们全家的照片吗?', 'Tā jīnnián 22 suì. Nǐ xiǎng kàn wǒmen quánjiā de zhàopiàn ma?', 'Chị ấy năm nay 22 tuổi. Bạn có muốn xem ảnh cả nhà tôi không?', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v11_3', 'lesson-11', '照片', 'zhàopiàn', 'từ Hán ngữ', 'ảnh', 'Danh từ', '火/灬 (Hỏa) (Lửa, nhiệt độ, nấu nướng, nóng bức)', '照: 昭 (Chiêu: ánh sáng) + 灬 (Hỏa: ngọn lửa soi chiếu) • 片: Bộ 片 (Phiến - nửa thân gỗ xẻ mỏng)', 'Ghép 照 [bộ 灬] + 片 [bộ 片] để nhớ từ 照片 (zhàopiàn): "ảnh".', '她今年 22 岁。你想看我们全家的照片吗?', 'Tā jīnnián 22 suì. Nǐ xiǎng kàn wǒmen quánjiā de zhàopiàn ma?', 'Chị ấy năm nay 22 tuổi. Bạn có muốn xem ảnh cả nhà tôi không?', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v11_4', 'lesson-11', '爷爷', 'yéye', 'từ Hán ngữ', 'ông nội', 'Danh từ', '父 (Phụ) (Người cha)', '爷: 父 (Phụ: cha) + 卩 (Tiết) • 爷: 父 (Phụ: cha) + 卩 (Tiết)', 'Ghép 爷 [bộ 父] + 爷 [bộ 父] để nhớ từ 爷爷 (yéye): "ông nội".', '我家有六口人：我爷爷、奶奶、爸爸、妈妈、哥哥和我。你家呢？', 'Wǒjiā yǒu liù kǒu rén: Wǒ yéye, nǎinai, bàba, māma, gēge hé wǒ. Nǐ jiā ne?', 'Nhà tôi có 6 người: ông nội, bà nội, bố, mẹ, anh trai và tôi. Còn nhà bạn thì sao?', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v11_5', 'lesson-11', '奶奶', 'nǎinai', 'từ Hán ngữ', 'bà nội', 'Danh từ', '女 (Nữ) (Phụ nữ, gia đình, tình cảm)', '奶: 女 (Nữ: phụ nữ) + 乃 (Nãi) • 奶: 女 (Nữ: phụ nữ) + 乃 (Nãi)', 'Ghép 奶 [bộ 女] + 奶 [bộ 女] để nhớ từ 奶奶 (nǎinai): "bà nội".', '我家有六口人：我爷爷、奶奶、爸爸、妈妈、哥哥和我。你家呢？', 'Wǒjiā yǒu liù kǒu rén: Wǒ yéye, nǎinai, bàba, māma, gēge hé wǒ. Nǐ jiā ne?', 'Nhà tôi có 6 người: ông nội, bà nội, bố, mẹ, anh trai và tôi. Còn nhà bạn thì sao?', 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v11_6', 'lesson-11', '爸爸', 'bàba', 'bà bà', 'bố', 'Danh từ', '父 (Phụ) (Người cha)', '爸: 父 (Phụ: người cha) + 巴 (Ba) • 爸: 父 (Phụ: người cha) + 巴 (Ba)', 'Ghép 爸 [bộ 父] + 爸 [bộ 父] để nhớ từ 爸爸 (bàba): "bố".', '我家有六口人：我爷爷、奶奶、爸爸、妈妈、哥哥和我。你家呢？', 'Wǒjiā yǒu liù kǒu rén: Wǒ yéye, nǎinai, bàba, māma, gēge hé wǒ. Nǐ jiā ne?', 'Nhà tôi có 6 người: ông nội, bà nội, bố, mẹ, anh trai và tôi. Còn nhà bạn thì sao?', 6) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v11_7', 'lesson-11', '妈妈', 'māma', 'ma ma', 'mẹ', 'Danh từ', '女 (Nữ) (Phụ nữ, gia đình, tình cảm)', '妈: 女 (Nữ: phụ nữ) + 马 (Mã: mượn âm) • 妈: 女 (Nữ: phụ nữ) + 马 (Mã: mượn âm)', 'Ghép 妈 [bộ 女] + 妈 [bộ 女] để nhớ từ 妈妈 (māma): "mẹ".', '我家有六口人：我爷爷、奶奶、爸爸、妈妈、哥哥和我。你家呢？', 'Wǒjiā yǒu liù kǒu rén: Wǒ yéye, nǎinai, bàba, māma, gēge hé wǒ. Nǐ jiā ne?', 'Nhà tôi có 6 người: ông nội, bà nội, bố, mẹ, anh trai và tôi. Còn nhà bạn thì sao?', 7) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v11_8', 'lesson-11', '姐姐', 'jiějie', 'tỷ tỷ', 'chị gái', 'Danh từ', '女 (Nữ) (Phụ nữ, gia đình, tình cảm)', '姐: 女 (Nữ: phụ nữ) + 且 (Thả) • 姐: 女 (Nữ: phụ nữ) + 且 (Thả)', 'Ghép 姐 [bộ 女] + 姐 [bộ 女] để nhớ từ 姐姐 (jiějie): "chị gái".', '我家有五口人：爸爸、妈妈、姐姐、弟弟和我。', 'Wǒjiā yǒu wǔ kǒu rén: Bàba, māma, jiějie, dìdi hé wǒ.', 'Nhà tôi có 5 người: bố, mẹ, chị gái, em trai và tôi.', 8) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v11_9', 'lesson-11', '哥哥', 'gēge', 'ca ca', 'anh trai', 'Danh từ', '口 (Khẩu) (Miệng, ăn uống, lời nói, âm thanh phát ra)', '哥: 可 (Khả) + 可 (Khả: anh trai) • 哥: 可 (Khả) + 可 (Khả: anh trai)', 'Ghép 哥 [bộ 口] + 哥 [bộ 口] để nhớ từ 哥哥 (gēge): "anh trai".', '我家有六口人：我爷爷、奶奶、爸爸、妈妈、哥哥和我。你家呢？', 'Wǒjiā yǒu liù kǒu rén: Wǒ yéye, nǎinai, bàba, māma, gēge hé wǒ. Nǐ jiā ne?', 'Nhà tôi có 6 người: ông nội, bà nội, bố, mẹ, anh trai và tôi. Còn nhà bạn thì sao?', 9) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v11_10', 'lesson-11', '弟弟', 'dìdi', 'đệ đệ', 'em trai', 'Danh từ', '弓 (Cung) (Cây cung, độ căng, uốn cong)', '弟: 丷 + 弓 (Cung) + 丨 + 丿 (em trai) • 弟: 丷 + 弓 (Cung) + 丨 + 丿 (em trai)', 'Ghép 弟 [bộ 弓] + 弟 [bộ 弓] để nhớ từ 弟弟 (dìdi): "em trai".', '我有一个弟弟。', 'Wǒ yǒu yígè dìdi.', 'Tôi có một cậu em trai.', 10) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v11_11', 'lesson-11', '自己', 'zìjǐ', 'từ Hán ngữ', 'tự mình, bản thân, một mình', 'Đại từ', '自 (Tự) (Cái mũi, bản thân, tự mình)', '自: Bộ 自 (Tự - hình cái mũi, chỉ bản thân) • 己: Bộ 己 (Kỷ - bản thân, chữ độc thể)', 'Ghép 自 [bộ 自] + 己 [bộ 己] để nhớ từ 自己 (zìjǐ): "tự mình, bản thân, một mình".', '他们只关心自己。', 'Tāmen zhǐ guānxīn zìjǐ.', 'Bọn họ chỉ quan tâm đến bản thân mình mà thôi.', 11) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v11_12', 'lesson-11', '岁', 'suì', 'từ Hán ngữ', 'tuổi', 'Danh từ', '山 (Sơn) (Núi non, đồi núi)', '岁 = 山 (Sơn) + 夕 (Tịch: năm tháng trôi qua).', 'Chữ 岁 (suì) mang nghĩa "tuổi", bộ chính 山 (Sơn); cấu tạo: 山 (Sơn) + 夕 (Tịch: năm tháng trôi qua).', '她今年 22 岁。你想看我们全家的照片吗?', 'Tā jīnnián 22 suì. Nǐ xiǎng kàn wǒmen quánjiā de zhàopiàn ma?', 'Chị ấy năm nay 22 tuổi. Bạn có muốn xem ảnh cả nhà tôi không?', 12) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v11_13', 'lesson-11', '年', 'nián', 'niên', 'năm', 'Danh từ', '干 (Can) (Can thiệp, khô ráo, làm việc)', '年 = 𠂉 + 干/土 (mùa màng thu hoạch một năm).', 'Chữ 年 (nián) mang nghĩa "năm", bộ chính 干 (Can); cấu tạo: 𠂉 + 干/土 (mùa màng thu hoạch một năm).', '你姐姐今年多大了？', 'Nǐ jiějie jīnnián duōdà le?', 'Chị gái bạn năm nay bao nhiêu tuổi rồi?', 13) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v11_14', 'lesson-11', '狗', 'gǒu', 'từ Hán ngữ', 'con chó', 'Danh từ', '犬/犭 (Khuyển) (Con chó, loài thú)', '狗 = 犭 (Khuyển: loài chó) + 句 (Cú).', 'Chữ 狗 (gǒu) mang nghĩa "con chó", bộ chính 犬/犭 (Khuyển); cấu tạo: 犭 (Khuyển: loài chó) + 句 (Cú).', '这里还有一条狗和一只猫。你们家是不是很爱它们？', 'Zhèli hái yǒu yītiáo gǒu hé yī zhī māo. Nǐmen jiā shì bu shì hěn ài tāmen?', 'Ở đây còn có một con chó và một con mèo nữa. Nhà bạn chắc yêu quý chúng lắm nhỉ?', 14) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v11_15', 'lesson-11', '猫', 'māo', 'từ Hán ngữ', 'con mèo', 'Danh từ', '犬/犭 (Khuyển) (Con chó, loài thú)', '猫 = 犭 (Khuyển: loài thú) + 苗 (Miêu: tiếng mèo kêu meo).', 'Chữ 猫 (māo) mang nghĩa "con mèo", bộ chính 犬/犭 (Khuyển); cấu tạo: 犭 (Khuyển: loài thú) + 苗 (Miêu: tiếng mèo kêu meo).', '这里还有一条狗和一只猫。你们家是不是很爱它们？', 'Zhèli hái yǒu yītiáo gǒu hé yī zhī māo. Nǐmen jiā shì bu shì hěn ài tāmen?', 'Ở đây còn có một con chó và một con mèo nữa. Nhà bạn chắc yêu quý chúng lắm nhỉ?', 15) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v11_16', 'lesson-11', '部分', 'bùfen', 'phân', 'bộ phận', 'Danh từ', '阝 (Phụ/Ấp) (Gò đất hoặc vùng đất, thành ấp)', '部: 咅 (Thôi) + 阝 (Ấp) • 分: 八 (Bát: chia đôi) + 刀 (Đao: con dao cắt chia)', 'Ghép 部 [bộ 阝] + 分 [bộ 刀] để nhớ từ 部分 (bùfen): "bộ phận".', '是的，它们也是我家的一部分，对我来说，它们也是我的朋友。', 'Shì de, tāmen yěshì wǒjiā de yíbùfen, duì wǒ lái shuō, tāmen yěshì wǒ de péngyou.', 'Đúng rồi, chúng cũng là một phần của gia đình tôi; đối với tôi, chúng còn là những người bạn nữa.', 16) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v11_17', 'lesson-11', '爱', 'ài', 'ái', 'yêu', 'Động từ', '爪/爫 (Trảo) (Móng vuốt, bàn tay chụp lấy)', '爱 = 爫 (Trảo: tay vuốt ve) + 冖 + 友 (Hựu: tình bạn yêu thương).', 'Chữ 爱 (ài) mang nghĩa "yêu", bộ chính 爪/爫 (Trảo); cấu tạo: 爫 (Trảo: tay vuốt ve) + 冖 + 友 (Hựu: tình bạn yêu thương).', '这样也很可爱嘛！你姐姐好漂亮啊！', 'Zhèyàng yě hěn kě''ài ma! Nǐ jiějie hǎo piàoliang a!', 'Thế này cũng rất đáng yêu mà! Chị gái bạn xinh quá đi!', 17) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v11_18', 'lesson-11', '关心', 'guānxīn', 'từ Hán ngữ', 'quan tâm, chú ý', 'Động từ', '八 (Bát) (Số tám, phân chia, mở rộng)', '关: 丷 + 天 (Thiên: then cài cửa) • 心: Bộ 心 (Tâm - hình trái tim)', 'Ghép 关 [bộ 八] + 心 [bộ 心] để nhớ từ 关心 (guānxīn): "quan tâm, chú ý".', '他们只关心自己。', 'Tāmen zhǐ guānxīn zìjǐ.', 'Bọn họ chỉ quan tâm đến bản thân mình mà thôi.', 18) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v11_19', 'lesson-11', '高', 'gāo', 'cao', 'cao', 'Tính từ', '高 (Cao) (Cao lớn, tầng cao)', '高 = Bộ 高 (Cao - tháp lầu nhiều tầng cao).', 'Chữ 高 (gāo) mang nghĩa "cao", bộ chính 高 (Cao); cấu tạo: Bộ 高 (Cao - tháp lầu nhiều tầng cao).', '你们家的人都那么高吗？', 'Nǐmen jiā de rén dōu nàme gāo ma?', 'Mọi người trong nhà bạn đều cao thế sao?', 19) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v11_20', 'lesson-11', '矮', 'ǎi', 'từ Hán ngữ', 'thấp', 'Tính từ', '矢 (Thỉ) (Mũi tên, thẳng thắn, hiểu biết)', '矮 = 矢 (Thỉ: thước đo) + 委 (Ủy).', 'Chữ 矮 (ǎi) mang nghĩa "thấp", bộ chính 矢 (Thỉ); cấu tạo: 矢 (Thỉ: thước đo) + 委 (Ủy).', '是的，只有我这么矮。', 'Shì de, zhǐyǒu wǒ zhème ǎi.', 'Đúng vậy, chỉ có mình tôi lùn thế này thôi.', 20) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v11_21', 'lesson-11', '可爱', 'kě''ài', 'ái', 'đáng yêu', 'Tính từ', '口 (Khẩu) (Miệng, ăn uống, lời nói, âm thanh phát ra)', '可: 丁 (Đinh) + 口 (Khẩu: đồng ý) • 爱: 爫 (Trảo: tay vuốt ve) + 冖 + 友 (Hựu: tình bạn yêu thương)', 'Ghép 可 [bộ 口] + 爱 [bộ 爫] để nhớ từ 可爱 (kě''ài): "đáng yêu".', '这样也很可爱嘛！你姐姐好漂亮啊！', 'Zhèyàng yě hěn kě''ài ma! Nǐ jiějie hǎo piàoliang a!', 'Thế này cũng rất đáng yêu mà! Chị gái bạn xinh quá đi!', 21) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v11_22', 'lesson-11', '像', 'xiàng', 'từ Hán ngữ', 'giống', 'Động từ', '人/亻 (Nhân) (Con người, nhân loại, hành động)', '像 = 亻 (Nhân đứng: người) + 象 (Tượng: hình dáng).', 'Chữ 像 (xiàng) mang nghĩa "giống", bộ chính 人/亻 (Nhân); cấu tạo: 亻 (Nhân đứng: người) + 象 (Tượng: hình dáng).', '这是关于“像”的常用句子。', 'Zhè shì guānyú ''xiàng'' de chángyòng jùzi.', 'Đây là câu ví dụ sử dụng từ ''像'' (giống).', 22) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v11_23', 'lesson-11', '口', 'kǒu', 'khẩu', 'khẩu, người', 'Lượng từ', '口 (Khẩu) (Miệng, ăn uống, lời nói, âm thanh phát ra)', '口 = Bộ 口 (Khẩu - hình cái miệng mở, chữ độc thể).', 'Ghi nhớ chữ [口] (khẩu, người) qua hình tượng Miệng, ăn uống, lời nói, âm thanh phát ra.', '安妮，你家有几口人？', 'Ānnī, nǐ jiā yǒu jǐ kǒu rén?', 'Annie, nhà bạn có mấy người?', 23) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v11_24', 'lesson-11', '只', 'zhī', 'từ Hán ngữ', 'con (lượng từ)', 'Lượng từ', '口 (Khẩu) (Miệng, ăn uống, lời nói, âm thanh phát ra)', '只 = 口 (Khẩu) + 八 (Bát).', 'Chữ 只 (zhī) mang nghĩa "con (lượng từ)", bộ chính 口 (Khẩu); cấu tạo: 口 (Khẩu) + 八 (Bát).', '这里只有我们两个人？', 'Zhèli zhǐ yǒu wǒmen liǎng gèrén?', 'Ở đây chỉ có hai người chúng ta?', 24) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v11_25', 'lesson-11', '只', 'zhǐ', 'từ Hán ngữ', 'chỉ', 'Phó từ', '口 (Khẩu) (Miệng, ăn uống, lời nói, âm thanh phát ra)', '只 = 口 (Khẩu) + 八 (Bát).', 'Chữ 只 (zhǐ) mang nghĩa "chỉ", bộ chính 口 (Khẩu); cấu tạo: 口 (Khẩu) + 八 (Bát).', '这里只有我们两个人？', 'Zhèli zhǐ yǒu wǒmen liǎng gèrén?', 'Ở đây chỉ có hai người chúng ta?', 25) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v11_26', 'lesson-11', '它', 'tā', 'từ Hán ngữ', 'nó (ngôi thứ ba số ít, chỉ vật)', 'Đại từ', '宀 (Miên) (Mái nhà, che chở, nơi ở)', '它 = 宀 (Miên) + 匕 (Chủy).', 'Chữ 它 (tā) mang nghĩa "nó (ngôi thứ ba số ít, chỉ vật)", bộ chính 宀 (Miên); cấu tạo: 宀 (Miên) + 匕 (Chủy).', '这里还有一条狗和一只猫。你们家是不是很爱它们？', 'Zhèli hái yǒu yītiáo gǒu hé yī zhī māo. Nǐmen jiā shì bu shì hěn ài tāmen?', 'Ở đây còn có một con chó và một con mèo nữa. Nhà bạn chắc yêu quý chúng lắm nhỉ?', 26) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v11_27', 'lesson-11', '它们', 'tāmen', 'môn', 'chúng nó (ngôi thứ ba số nhiều, chỉ vật)', 'Đại từ', '宀 (Miên) (Mái nhà, che chở, nơi ở)', '它: 宀 (Miên) + 匕 (Chủy) • 们: 亻 (Nhân đứng: người) + 门 (Môn: cửa)', 'Ghép 它 [bộ 宀] + 们 [bộ 亻] để nhớ từ 它们 (tāmen): "chúng nó (ngôi thứ ba số nhiều, chỉ vật)".', '这里还有一条狗和一只猫。你们家是不是很爱它们？', 'Zhèli hái yǒu yītiáo gǒu hé yī zhī māo. Nǐmen jiā shì bu shì hěn ài tāmen?', 'Ở đây còn có một con chó và một con mèo nữa. Nhà bạn chắc yêu quý chúng lắm nhỉ?', 27) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v11_28', 'lesson-11', '多大', 'duōdà', 'đa đại', 'bao nhiêu tuổi, to/lớn chừng nào...(để hỏi)', 'Cụm từ / Tên riêng', '夕 (Tịch) (Buổi chiều tối, đêm tối)', '多: 夕 (Tịch) + 夕 (Tịch: nhiều lớp chồng nhau) • 大: Bộ 大 (Đại - người dang rộng tay chân, chữ độc thể)', 'Ghép 多 [bộ 夕] + 大 [bộ 大] để nhớ từ 多大 (duōdà): "bao nhiêu tuổi, to/lớn chừng nào...(để hỏi)".', '你姐姐今年多大了？', 'Nǐ jiějie jīnnián duōdà le?', 'Chị gái bạn năm nay bao nhiêu tuổi rồi?', 28) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v11_29', 'lesson-11', '那么', 'nàme', 'na ma', 'như thế, như thế kia thì, vậy thì, trong trường hợp ấy', 'Đại từ / Liên từ', '阝 (Phụ/Ấp) (Gò đất hoặc vùng đất, thành ấp)', '那: 𠃌 + 二 + 阝 (Ấp: vùng đất xa) • 么: 丿 (Phiệt) + 厶 (Tư)', 'Ghép 那 [bộ 阝] + 么 [bộ 丿] để nhớ từ 那么 (nàme): "như thế, như thế kia thì, vậy thì, trong trường hợp ấy".', '为什么你昨天那么晚才回来？', 'Wèishénme nǐ zuótiān nàme wǎn cái huílai?', 'Vì sao tối qua muộn như thế anh mới về?', 29) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v11_30', 'lesson-11', '这么', 'zhème', 'giá ma', 'như thế, như thế này', 'Đại từ', '辶 (Sước) (Bước đi, di chuyển, khoảng cách)', '这: 文 (Văn) + 辶 (Sước: bước đi gần đây) • 么: 丿 (Phiệt) + 厶 (Tư)', 'Ghép 这 [bộ 辶] + 么 [bộ 丿] để nhớ từ 这么 (zhème): "như thế, như thế này".', '他真的这么说。', 'Tā zhēn de zhème shuō.', 'Anh ta thật sự nói như thế.', 30) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v11_31', 'lesson-11', '当然', 'dāngrán', 'từ Hán ngữ', 'đương nhiên, dĩ nhiên', 'Tính từ / Phó từ', '彐 (Kệ) (Đầu nhím, bàn tay nắm)', '当: ⺌ + 彐 (Kệ) • 然: 肰 (Nhiên) + 灬 (Hỏa: ngọn lửa đốt)', 'Ghép 当 [bộ 彐] + 然 [bộ 灬] để nhớ từ 当然 (dāngrán): "đương nhiên, dĩ nhiên".', '当然了。', 'Dāngrán le.', 'Tất nhiên rồi.', 31) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v11_32', 'lesson-11', '对我来说', 'duì wǒ lái shuō', 'ngã lai thuyết', 'đối với tôi mà nói,...', 'Cụm từ / Tên riêng', '寸 (Thốn) (Đo lường, bàn tay, phép tắc)', '对: 又 (Hựu) + 寸 (Thốn: đối chiếu cân xứng) • 我: 手 (Thủ: tay biến thể) + 戈 (Qua: binh khí) • 来: 一 + 米 (Mễ biến thể / cây lúa) • 说: 讠 (Ngôn: lời nói) + 兑 (Đoài)', 'Ghép 对 [bộ 寸] + 我 [bộ 戈] + 来 [bộ 木] + 说 [bộ 讠] để nhớ từ 对我来说 (duì wǒ lái shuō): "đối với tôi mà nói,...".', '是的，它们也是我家的一部分，对我来说，它们也是我的朋友。', 'Shì de, tāmen yěshì wǒjiā de yíbùfen, duì wǒ lái shuō, tāmen yěshì wǒ de péngyou.', 'Đúng rồi, chúng cũng là một phần của gia đình tôi; đối với tôi, chúng còn là những người bạn nữa.', 32) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order) VALUES ('g11_1', 'lesson-11', '1. “有” 句子 – Câu chữ 有', '●    Hình thức khẳng định: Chủ ngữ + 有 + Danh từ', ' ❖      有 được dùng để biểu thị sự sở hữu – có ●      Hình thức phủ định: Chủ ngữ + 没有+ Danh từ ●       Hình thức nghi vấn:  Chủ ngữ + 有 + Danh từ + 吗？ Chủ ngữ + 有没有+ Danh từ？ 我有一个弟弟。 Wǒ yǒu yígè dìdi. Tôi có một cậu em trai. 我没有弟弟。 Wǒ méiyǒu dìdi. T', NULL, '[{"hanzi":"我有一个弟弟。","pinyin":"Wǒ yǒu yígè dìdi.","meaning":"Tôi có một cậu em trai."},{"hanzi":"我没有弟弟。","pinyin":"Wǒ méiyǒu dìdi.","meaning":"Tôi không có em trai."}]'::jsonb, 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order) VALUES ('g11_2', 'lesson-11', '2. 只 +  Động từ  :   chỉ...', '只 + Động từ mang nghĩa là chỉ làm gì đó', ' 这里只有我们两个人？ Zhèli zhǐ yǒu wǒmen liǎng gèrén? Ở đây chỉ có hai người chúng ta? 他们只关心自己。 Tāmen zhǐ guānxīn zìjǐ. Bọn họ chỉ quan tâm đến bản thân mình mà thôi. 他不相信命运，只相信自己。 Tā bù xiāngxìn mìngyùn, zhǐ xiāngxìn zìjǐ. Anh ấy không tin vào vận mệnh, chỉ ', NULL, '[{"hanzi":"教室里有三个人。","pinyin":"Jiàoshì li yǒu sān gèrén.","meaning":"Trong phòng học có 3 người."},{"hanzi":"学校左边有一家银行。","pinyin":"Xuéxiào zuǒbian yǒu yījiā yínháng.","meaning":"Phía bên trái trường học có một ngân hàng."}]'::jsonb, 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order) VALUES ('g11_3', 'lesson-11', '3. 呢', 'Cấu trúc câu ngữ pháp trọng tâm', ' a) Trong 1 số tình huống nhất định, 呢 có thể dùng để thay thế cho đại từ nghi vấn 我的书呢？          =               我的书在哪儿呢？  (Sách của tôi đâu?) Wǒ de shū ne?        =               Wǒ de shū zài nǎr ne? 然后呢？           =               然后怎么样呢？        (', NULL, '[{"hanzi":"这里只有我们两个人？","pinyin":"Zhèli zhǐ yǒu wǒmen liǎng gèrén?","meaning":"Ở đây chỉ có hai người chúng ta?"},{"hanzi":"他们只关心自己。","pinyin":"Tāmen zhǐ guānxīn zìjǐ.","meaning":"Bọn họ chỉ quan tâm đến bản thân mình mà thôi."}]'::jsonb, 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order) VALUES ('g11_4', 'lesson-11', '4. 这么/那么 – như thế này, như vậy, như thế kia, như thế', 'Cấu trúc câu ngữ pháp trọng tâm', ' Là các đại từ chỉ thị, chỉ tính chất, trạng thái, phương thức, trình độ... thường dùng trước tính từ, động từ. 他真的这么说。 Tā zhēn de zhème shuō. Anh ta thật sự nói như thế. 你怎么这么早就起床了？ Nǐ zěnme zhème zǎo jiù qǐchuáng le? Sao sớm như thế này con đã dậy ', NULL, '[{"hanzi":"他不相信命运，只相信自己。","pinyin":"Tā bù xiāngxìn mìngyùn, zhǐ xiāngxìn zìjǐ.","meaning":"Anh ấy không tin vào vận mệnh, chỉ tin vào bản thân mình."},{"hanzi":"你是谁呢？","pinyin":"Nǐ shì shéi ne?","meaning":"Cậu là ai thế?"}]'::jsonb, 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order;
INSERT INTO texts (id, lesson_id, title, description, sort_order) VALUES ('txt_11_1', 'lesson-11', 'Bài khoá #1: Hội thoại giáo trình — Thành viên trong gia đình', 'Hội thoại chuẩn giáo trình Bài 11. Từ vựng chưa học được chú thích phiên âm & nghĩa trong ngoặc.', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_11_1_1', 'txt_11_1', '范玉兰', '安妮，你家有几口人？', '安妮，你家有几口人？', 'Ānnī, nǐ jiā yǒu jǐ kǒu rén?', 'Annie, nhà bạn có mấy người?', 1) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_11_1_2', 'txt_11_1', '安妮', '我家有六口人：我爷爷、奶奶、爸爸、妈妈、哥哥和我。你家呢？', '我家有六口人：我爷爷、奶奶、爸爸、妈妈、哥哥和我。你家呢？', 'Wǒjiā yǒu liù kǒu rén: Wǒ yéye, nǎinai, bàba, māma, gēge hé wǒ. Nǐ jiā ne?', 'Nhà tôi có 6 người: ông nội, bà nội, bố, mẹ, anh trai và tôi. Còn nhà bạn thì sao?', 2) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_11_1_3', 'txt_11_1', '范玉兰', '我家有五口人：爸爸、妈妈、姐姐、弟弟和我。', '我家有五口人：爸爸、妈妈、姐姐、弟弟和我。', 'Wǒjiā yǒu wǔ kǒu rén: Bàba, māma, jiějie, dìdi hé wǒ.', 'Nhà tôi có 5 người: bố, mẹ, chị gái, em trai và tôi.', 3) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_11_1_4', 'txt_11_1', '安妮', '你姐姐今年多大了？', '你姐姐今 (jīn: hôm nay, nay)年多大了？', 'Nǐ jiějie jīnnián duōdà le?', 'Chị gái bạn năm nay bao nhiêu tuổi rồi?', 4) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_11_1_5', 'txt_11_1', '范玉兰', '她今年 22 岁。你想看我们全家的照片吗?', '她今 (jīn: hôm nay, nay)年 22 岁。你想看我们全家的照片吗?', 'Tā jīnnián 22 suì. Nǐ xiǎng kàn wǒmen quánjiā de zhàopiàn ma?', 'Chị ấy năm nay 22 tuổi. Bạn có muốn xem ảnh cả nhà tôi không?', 5) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_11_1_6', 'txt_11_1', '安妮', '当然了。', '当然了。', 'Dāngrán le.', 'Tất nhiên rồi.', 6) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_11_1_7', 'txt_11_1', '范玉兰', '等我一下儿，这是我家的照片，给你看。', '等我一下儿，这是我家的照片，给你看。', 'Děng wǒ yíxiàr, zhè shì wǒjiā de zhàopiàn, gěi nǐ kàn.', 'Chờ tôi một lát, đây là ảnh gia đình tôi, cho bạn xem này.', 7) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_11_1_8', 'txt_11_1', '安妮', '你们家的人都那么高吗？', '你们家的人都那么高吗？', 'Nǐmen jiā de rén dōu nàme gāo ma?', 'Mọi người trong nhà bạn đều cao thế sao?', 8) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_11_1_9', 'txt_11_1', '范玉兰', '是的，只有我这么矮。', '是的，只有我这么矮。', 'Shì de, zhǐyǒu wǒ zhème ǎi.', 'Đúng vậy, chỉ có mình tôi lùn thế này thôi.', 9) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_11_1_10', 'txt_11_1', '安妮', '这样也很可爱嘛！你姐姐好漂亮啊！', '这样也很可爱嘛 (ma: mà (ngữ khí))！你姐姐好漂亮啊！', 'Zhèyàng yě hěn kě''ài ma! Nǐ jiějie hǎo piàoliang a!', 'Thế này cũng rất đáng yêu mà! Chị gái bạn xinh quá đi!', 10) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_11_1_11', 'txt_11_1', '范玉兰', '对啊！很多人喜欢她。', '对啊！很多人喜欢她。', 'Duì a! Hěnduō rén xǐhuan tā.', 'Đúng vậy! Nhiều người thích chị ấy lắm.', 11) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_11_1_12', 'txt_11_1', '安妮', '这里还有一条狗和一只猫。你们家是不是很爱它们？', '这里 (lǐ: trong)还有一条狗和一只猫。你们家是不 (bù: không)是很爱它们？', 'Zhèli hái yǒu yītiáo gǒu hé yī zhī māo. Nǐmen jiā shì bu shì hěn ài tāmen?', 'Ở đây còn có một con chó và một con mèo nữa. Nhà bạn chắc yêu quý chúng lắm nhỉ?', 12) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_11_1_13', 'txt_11_1', '范玉兰', '是的，它们也是我家的一部分，对我来说，它们也是我的朋友。', '是的，它们也是我家的一部分，对我来说，它们也是我的朋友。', 'Shì de, tāmen yěshì wǒjiā de yíbùfen, duì wǒ lái shuō, tāmen yěshì wǒ de péngyou.', 'Đúng rồi, chúng cũng là một phần của gia đình tôi; đối với tôi, chúng còn là những người bạn nữa.', 13) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_11_1_1', 'lesson-11', 'txt_11_1', 'listening', 'listening', '安妮，你家有几口人？', NULL, 'Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Một cái ghế","một câu chuyện","Annie, nhà bạn có mấy người?","quyển sách rất hay"]'::jsonb, 2, 'Nội dung nghe được: 安妮，你家有几口人？ (Ānnī, nǐ jiā yǒu jǐ kǒu rén?) → Annie, nhà bạn có mấy người?', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_11_1_2', 'lesson-11', 'txt_11_1', 'listening', 'listening', '我家有六口人：我爷爷、奶奶、爸爸、妈妈、哥哥和我。你家呢？', NULL, 'Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["我姐姐比弟弟大 (dà: to, lớn)五岁。","你说 (shuō: nói)什么呢？","奶奶和爷爷每天 (tiān: ngày, trời)都很高兴。","我家有六口人：我爷爷、奶奶、爸爸、妈妈、哥哥和我。你家呢？"]'::jsonb, 3, 'Câu vừa đọc: 我家有六口人：我爷爷、奶奶、爸爸、妈妈、哥哥和我。你家呢？ (Wǒjiā yǒu liù kǒu rén: Wǒ yéye, nǎinai, bàba, māma, gēge hé wǒ. Nǐ jiā ne?) → Nhà tôi có 6 người: ông nội, bà nội, bố, mẹ, anh trai và tôi. Còn nhà bạn thì sao?', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_11_1_3', 'lesson-11', 'txt_11_1', 'listening', 'listening', '我家有五口人：爸爸、妈妈、姐姐、弟弟和我。', NULL, 'Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Ở đây còn có một con chó và một con mèo nữa. Nhà bạn chắc yêu quý chúng lắm nhỉ?","Bà ngoại cậu năm nay bao nhiêu rồi?","Nhà tôi có 5 người: bố, mẹ, chị gái, em trai và tôi.","Tớ muốn đến công viên chạy bộ."]'::jsonb, 2, 'Nội dung nghe được: 我家有五口人：爸爸、妈妈、姐姐、弟弟和我。 (Wǒjiā yǒu wǔ kǒu rén: Bàba, māma, jiějie, dìdi hé wǒ.) → Nhà tôi có 5 người: bố, mẹ, chị gái, em trai và tôi.', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_11_1_4', 'lesson-11', 'txt_11_1', 'listening', 'listening', '你姐姐今年多大了？', NULL, 'Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["我有一个弟弟。","奶奶和爷爷每天 (tiān: ngày, trời)都很高兴。","你姐姐今 (jīn: hôm nay, nay)年多大了？","你说 (shuō: nói)什么呢？"]'::jsonb, 2, 'Câu vừa đọc: 你姐姐今年多大了？ (Nǐ jiějie jīnnián duōdà le?) → Chị gái bạn năm nay bao nhiêu tuổi rồi?', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO texts (id, lesson_id, title, description, sort_order) VALUES ('txt_11_2', 'lesson-11', 'Bài nghe tổng hợp: Ôn tập lũy tiến (Bài 1 – Bài 11)', 'Kết hợp từ vựng & mẫu câu đã học từ Bài 1 đến Bài 10 cùng trọng tâm Bài 11 để củng cố phản xạ nghe.', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_11_2_1', 'txt_11_2', 'Ôn Bài 10', '这本书是我的。', '这本书是我的。', 'Zhè běn shū shì wǒ de.', 'Quyển sách này là sách của tôi.', 1) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_11_2_2', 'txt_11_2', 'Bài 11', '我有一个弟弟。', '我有一个弟弟。', 'Wǒ yǒu yígè dìdi.', 'Tôi có một cậu em trai.', 2) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_11_2_3', 'txt_11_2', 'Ôn Bài 5', '我明天上午八点上课。', '我明天上午八点上课。', 'Wǒ míngtiān shàngwǔ bā diǎn shàngkè.', 'Tám giờ sáng ngày mai tớ đi học.', 3) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_11_2_4', 'txt_11_2', 'Bài 11', '他们只关心自己。', '他们只关心自己。', 'Tāmen zhǐ guānxīn zìjǐ.', 'Bọn họ chỉ quan tâm đến bản thân mình mà thôi.', 4) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_11_2_5', 'txt_11_2', 'Ôn Bài 1', '她是老师。', '她是老师。', 'Tā shì lǎoshī.', 'Cô ấy là giáo viên.', 5) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_11_2_6', 'txt_11_2', 'Bài 11', '你是谁呢？', '你是谁呢？', 'Nǐ shì shéi ne?', 'Cậu là ai thế?', 6) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_11_2_7', 'txt_11_2', 'Ôn Bài 3', '她很漂亮。', '她很漂亮。', 'Tā hěn piàoliang.', 'Cô ấy rất xinh đẹp.', 7) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_11_2_8', 'txt_11_2', 'Bài 11', '他在吃饭呢。', '他在吃饭呢。', 'Tā zài chīfàn ne.', 'Anh ấy đang ăn cơm kìa.', 8) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_11_2_1', 'lesson-11', 'txt_11_2', 'listening', 'listening', '这本书是我的。', NULL, '[Ôn tập Bài 10] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Nhà tôi có 5 người: bố, mẹ, chị gái, em trai và tôi.","Một phần quà","Thầy ấy là thầy giáo của tớ.","Quyển sách này là sách của tôi."]'::jsonb, 3, 'Nội dung nghe được: 这本书是我的。 (Zhè běn shū shì wǒ de.) → Quyển sách này là sách của tôi.', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_11_2_2', 'lesson-11', 'txt_11_2', 'listening', 'listening', '我有一个弟弟。', NULL, '[Bài 11] Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["奶奶和爷爷每天 (tiān: ngày, trời)都很高兴。","这里 (lǐ: trong)只有我们两 (liǎng: hai (số lượng))个人？","这张 (zhāng: tờ, tấm, chiếc)全家的照片真好看！","我有一个弟弟。"]'::jsonb, 3, 'Câu vừa đọc: 我有一个弟弟。 (Wǒ yǒu yígè dìdi.) → Tôi có một cậu em trai.', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_11_2_3', 'lesson-11', 'txt_11_2', 'listening', 'listening', '我明天上午八点上课。', NULL, '[Ôn tập Bài 5] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Tớ biết bơi, còn biết trượt băng.","Tám giờ sáng ngày mai tớ đi học.","Thầy ấy là thầy giáo của tớ.","Đã bảy giờ rồi, chắc anh ấy đã tan làm về nhà rồi."]'::jsonb, 1, 'Nội dung nghe được: 我明天上午八点上课。 (Wǒ míngtiān shàngwǔ bā diǎn shàngkè.) → Tám giờ sáng ngày mai tớ đi học.', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_11_2_4', 'lesson-11', 'txt_11_2', 'listening', 'listening', '他们只关心自己。', NULL, '[Bài 11] Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["他正在 (zhèngzài: đang, động tác đang diễn ra)听音乐 (tīng yīnyuè: nghe nhạc)呢。","他们只关心自己。","你是谁呢？","他真的这么说 (shuō: nói)。"]'::jsonb, 1, 'Câu vừa đọc: 他们只关心自己。 (Tāmen zhǐ guānxīn zìjǐ.) → Bọn họ chỉ quan tâm đến bản thân mình mà thôi.', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_11_2_5', 'lesson-11', 'txt_11_2', 'listening', 'listening', '她是老师。', NULL, '[Ôn tập Bài 1] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Tôi dậy rất sớm.","Kỳ học này tôi kiểm tra một lần rồi.","Tôi đứng ở giữa Lâm và Phương.","Cô ấy là giáo viên."]'::jsonb, 3, 'Nội dung nghe được: 她是老师。 (Tā shì lǎoshī.) → Cô ấy là giáo viên.', 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO texts (id, lesson_id, title, description, sort_order) VALUES ('txt_11_3', 'lesson-11', 'Bài khoá mở rộng: Giới thiệu ảnh gia đình (Mở rộng)', 'Hội thoại tình huống mới xây dựng dựa trên từ vựng và ngữ pháp Bài 11 (không trùng lặp nguyên văn giáo trình).', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_11_3_1', 'txt_11_3', 'Annie', '日明，这是你全家的照片吗？你们家有几口人？', '日明，这是你全家的照片吗？你们家有几口人？', 'Rìmíng, zhè shì nǐ quánjiā de zhàopiàn ma? Nǐmen jiā yǒu jǐ kǒu rén?', 'Nhật Minh, đây là ảnh cả gia đình bạn à? Nhà bạn có mấy người?', 1) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_11_3_2', 'txt_11_3', 'Minh', '我家有五口人：爷爷、爸爸、妈妈、姐姐和我。', '我家有五口人：爷爷、爸爸、妈妈、姐姐和我。', 'Wǒ jiā yǒu wǔ kǒu rén: yéye, bàba, māma, jiějie hé wǒ.', 'Nhà tôi có năm người: ông nội, bố, mẹ, chị gái và tôi.', 2) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_11_3_3', 'txt_11_3', 'Annie', '你姐姐今年多大？她工作了吗？', '你姐姐今 (jīn: hôm nay, nay)年多大？她工作 (gōngzuò: nghề nghiệp, công việc)了吗？', 'Nǐ jiějie jīnnián duōdà? Tā gōngzuò le ma?', 'Chị gái bạn năm nay bao nhiêu tuổi? Chị ấy đi làm chưa?', 3) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_11_3_4', 'txt_11_3', 'Minh', '她二十五岁了，在一家医院工作，很喜欢小猫。', '她二十五岁了，在一家医院 (yīyuàn: bệnh viện)工作 (gōngzuò: nghề nghiệp, công việc)，很喜欢小 (xiǎo: nhỏ, bé)猫。', 'Tā èrshíwǔ suì le, zài yì jiā yīyuàn gōngzuò, hěn xǐhuan xiǎo māo.', 'Chị ấy 25 tuổi rồi, làm việc ở một bệnh viện và rất thích mèo con.', 4) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_11_3_1', 'lesson-11', 'txt_11_3', 'listening', 'listening', '日明，这是你全家的照片吗？你们家有几口人？ 我家有五口人：爷爷、爸爸、妈妈、姐姐和我。 你姐姐今年多大？她工作了吗？ 她二十五岁了，在一家医院工作，很喜欢小猫。', NULL, '[Nghe hiểu tình huống mới] Chị gái của Nhật Minh năm nay bao nhiêu tuổi và làm việc ở đâu?', '["18 tuổi, thích nuôi chó","25 tuổi, làm việc tại một bệnh viện","22 tuổi, còn là sinh viên","25 tuổi, làm ở hiệu sách"]'::jsonb, 1, 'Minh nói ''她二十五岁了，在一家医院工作''.', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_11_3_2', 'lesson-11', 'txt_11_3', 'listening', 'listening', '日明，这是你全家的照片吗？你们家有几口人？', NULL, '[Mở rộng] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Tôi không có em trai.","Khó quá đi, tôi không biết nên làm như thế nào nữa!","Mỗi học sinh đều đi học bằng xe buýt.","Nhật Minh, đây là ảnh cả gia đình bạn à? Nhà bạn có mấy người?"]'::jsonb, 3, 'Nội dung nghe được: 日明，这是你全家的照片吗？你们家有几口人？ (Rìmíng, zhè shì nǐ quánjiā de zhàopiàn ma? Nǐmen jiā yǒu jǐ kǒu rén?) → Nhật Minh, đây là ảnh cả gia đình bạn à? Nhà bạn có mấy người?', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_11_3_3', 'lesson-11', 'txt_11_3', 'listening', 'listening', '我家有五口人：爷爷、爸爸、妈妈、姐姐和我。', NULL, '[Mở rộng] Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["我家有五口人：爷爷、爸爸、妈妈、姐姐和我。","你姐姐今 (jīn: hôm nay, nay)年多大了？","奶奶和爷爷每天 (tiān: ngày, trời)都很高兴。","学校左边有一家银行 (xíng: được)。"]'::jsonb, 0, 'Câu vừa đọc: 我家有五口人：爷爷、爸爸、妈妈、姐姐和我。 (Wǒ jiā yǒu wǔ kǒu rén: yéye, bàba, māma, jiějie hé wǒ.) → Nhà tôi có năm người: ông nội, bố, mẹ, chị gái và tôi.', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_11_3_4', 'lesson-11', 'txt_11_3', 'listening', 'listening', '你姐姐今年多大？她工作了吗？', NULL, '[Mở rộng] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Chị gái bạn năm nay bao nhiêu tuổi? Chị ấy đi làm chưa?","Hai mươi lăm cái","Cậu ấy là người cao nhất trong lớp.","Mai tớ thi rồi, không thể đi cùng cậu được."]'::jsonb, 0, 'Nội dung nghe được: 你姐姐今年多大？她工作了吗？ (Nǐ jiějie jīnnián duōdà? Tā gōngzuò le ma?) → Chị gái bạn năm nay bao nhiêu tuổi? Chị ấy đi làm chưa?', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss11_1', 'lesson-11', '我家有四口人爸爸妈妈哥哥和我', '[Mở rộng] Nhà tôi có bốn người: bố, mẹ, anh trai và tôi.', 'Wǒ jiā yǒu sì kǒu rén: bàba, māma, gēge hé wǒ.', '["我家有四","口人","爸爸","妈妈","哥哥","和我"]'::jsonb, NULL, 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss11_2', 'lesson-11', '奶奶和爷爷每天都很高兴', '[Mở rộng] Bà nội và ông nội ngày nào cũng rất vui vẻ.', 'Nǎinai hé yéye měitiān dōu hěn gāoxìng.', '["奶奶","和","爷爷","每天","都很","高兴"]'::jsonb, 'Từ chưa học: 天 (tiān: ngày, trời)', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss11_3', 'lesson-11', '我有一个弟弟', 'Tôi có một cậu em trai.', 'Wǒ yǒu yígè dìdi.', '["我","有","一","个","弟弟"]'::jsonb, NULL, 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss11_4', 'lesson-11', '他们只关心自己', 'Bọn họ chỉ quan tâm đến bản thân mình mà thôi.', 'Tāmen zhǐ guānxīn zìjǐ.', '["他","们","只","关心","自己"]'::jsonb, NULL, 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss11_5', 'lesson-11', '昨天下午你去图书馆了吗', '[Ôn tập Bài 5] Chiều hôm qua bạn có đi thư viện không?', 'Zuótiān xiàwǔ nǐ qù túshūguǎn le ma?', '["昨天","下午","你","去","图书馆","了吗"]'::jsonb, NULL, 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss11_6', 'lesson-11', '草莓果汁十块钱两杯', '[Ôn tập Bài 8] Nước ép dâu tây 10 tệ hai cốc.', 'Cǎoméi guǒzhī shí kuài qián liǎng bēi.', '["草莓","果汁","十块","钱","两","杯"]'::jsonb, 'Từ chưa học: 两 (liǎng: hai (số lượng))', 6) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss11_exp_1', 'lesson-11', '安妮你家有几口人', 'Annie, nhà bạn có mấy người?', 'Ānnī, nǐ jiā yǒu jǐ kǒu rén?', '["安妮","你","家","有","几","口","人"]'::jsonb, NULL, 7) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss11_exp_2', 'lesson-11', '我家有六口人我爷爷奶奶爸爸妈妈哥哥和我你家呢', 'Nhà tôi có 6 người: ông nội, bà nội, bố, mẹ, anh trai và tôi. Còn nhà bạn thì sao?', 'Wǒjiā yǒu liù kǒu rén: Wǒ yéye, nǎinai, bàba, māma, gēge hé wǒ. Nǐ jiā ne?', '["我","家","有","六","口","人","我","爷爷","奶奶","爸爸","妈妈","哥哥","和","我","你","家","呢"]'::jsonb, NULL, 8) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss11_exp_3', 'lesson-11', '我家有五口人爸爸妈妈姐姐弟弟和我', 'Nhà tôi có 5 người: bố, mẹ, chị gái, em trai và tôi.', 'Wǒjiā yǒu wǔ kǒu rén: Bàba, māma, jiějie, dìdi hé wǒ.', '["我","家","有","五","口","人","爸爸","妈妈","姐姐","弟弟","和","我"]'::jsonb, NULL, 9) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss11_exp_4', 'lesson-11', '你姐姐今年多大了', 'Chị gái bạn năm nay bao nhiêu tuổi rồi?', 'Nǐ jiějie jīnnián duōdà le?', '["你","姐姐","今","年","多大","了"]'::jsonb, NULL, 10) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss11_exp_5', 'lesson-11', '她今年岁你想看我们全家的照片吗', 'Chị ấy năm nay 22 tuổi. Bạn có muốn xem ảnh cả nhà tôi không?', 'Tā jīnnián 22 suì. Nǐ xiǎng kàn wǒmen quánjiā de zhàopiàn ma?', '["她","今","年","岁","你","想","看","我们","全家","的","照片","吗"]'::jsonb, NULL, 11) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss11_exp_6', 'lesson-11', '当然了', 'Tất nhiên rồi.', 'Dāngrán le.', '["当然","了"]'::jsonb, NULL, 12) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss11_exp_7', 'lesson-11', '等我一下儿这是我家的照片给你看', 'Chờ tôi một lát, đây là ảnh gia đình tôi, cho bạn xem này.', 'Děng wǒ yíxiàr, zhè shì wǒjiā de zhàopiàn, gěi nǐ kàn.', '["等","我","一下儿","这","是","我","家","的","照片","给","你","看"]'::jsonb, NULL, 13) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss11_exp_8', 'lesson-11', '你们家的人都那么高吗', 'Mọi người trong nhà bạn đều cao thế sao?', 'Nǐmen jiā de rén dōu nàme gāo ma?', '["你们","家","的","人","都","那么","高","吗"]'::jsonb, NULL, 14) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss11_exp_9', 'lesson-11', '是的只有我这么矮', 'Đúng vậy, chỉ có mình tôi lùn thế này thôi.', 'Shì de, zhǐyǒu wǒ zhème ǎi.', '["是","的","只","有","我","这么","矮"]'::jsonb, NULL, 15) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss11_exp_10', 'lesson-11', '这样也很可爱嘛你姐姐好漂亮啊', 'Thế này cũng rất đáng yêu mà! Chị gái bạn xinh quá đi!', 'Zhèyàng yě hěn kě''ài ma! Nǐ jiějie hǎo piàoliang a!', '["这样","也","很","可爱","嘛","你","姐姐","好","漂亮","啊"]'::jsonb, NULL, 16) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss11_exp_11', 'lesson-11', '对啊很多人喜欢她', 'Đúng vậy! Nhiều người thích chị ấy lắm.', 'Duì a! Hěnduō rén xǐhuan tā.', '["对","啊","很","多","人","喜欢","她"]'::jsonb, NULL, 17) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss11_exp_12', 'lesson-11', '这里还有一条狗和一只猫你们家是不是很爱它们', 'Ở đây còn có một con chó và một con mèo nữa. Nhà bạn chắc yêu quý chúng lắm nhỉ?', 'Zhèli hái yǒu yītiáo gǒu hé yī zhī māo. Nǐmen jiā shì bu shì hěn ài tāmen?', '["这里","还","有","一","条","狗","和","一","只","猫","你们","家","是","不是","很","爱","它们"]'::jsonb, NULL, 18) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss11_exp_13', 'lesson-11', '是的它们也是我家的一部分对我来说它们也是我的朋友', 'Đúng rồi, chúng cũng là một phần của gia đình tôi; đối với tôi, chúng còn là những người bạn nữa.', 'Shì de, tāmen yěshì wǒjiā de yíbùfen, duì wǒ lái shuō, tāmen yěshì wǒ de péngyou.', '["是","的","它们","也","是","我","家","的","一","部分","对我来说","它们","也","是","我","的","朋友"]'::jsonb, NULL, 19) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss11_exp_14', 'lesson-11', '这本书是我的', 'Quyển sách này là sách của tôi.', 'Zhè běn shū shì wǒ de.', '["这","本","书","是","我","的"]'::jsonb, NULL, 20) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr11_vi_1', 'lesson-11', 'vi_to_zh', '[Mở rộng] Nhà tôi có bốn người: bố, mẹ, anh trai và tôi.', NULL, NULL, '我家有四口人：爸爸、妈妈、哥哥和我。', NULL, 'wǒ jiā yǒu sì kǒu rén bàba māma gēge hé wǒ', '[]'::jsonb, 'Gợi ý Pinyin: Wǒ jiā yǒu sì kǒu rén: bàba, māma, gēge hé wǒ.', 'Nhà tôi có bốn người: bố, mẹ, anh trai và tôi. → 我家有四口人：爸爸、妈妈、哥哥和我。 (Wǒ jiā yǒu sì kǒu rén: bàba, māma, gēge hé wǒ.)', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr11_vi_2', 'lesson-11', 'vi_to_zh', '[Mở rộng] Bà nội và ông nội ngày nào cũng rất vui vẻ.', NULL, NULL, '奶奶和爷爷每天都很高兴。', NULL, 'nǎinai hé yéye měitiān dōu hěn gāoxìng', '[]'::jsonb, 'Gợi ý Pinyin: Nǎinai hé yéye měitiān dōu hěn gāoxìng. | Từ chưa học: 天 (tiān: ngày, trời)', 'Bà nội và ông nội ngày nào cũng rất vui vẻ. → 奶奶和爷爷每天都很高兴。 (Nǎinai hé yéye měitiān dōu hěn gāoxìng.)', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr11_vi_3', 'lesson-11', 'vi_to_zh', 'Tôi có một cậu em trai.', NULL, NULL, '我有一个弟弟。', NULL, 'wǒ yǒu yígè dìdi', '[]'::jsonb, 'Gợi ý Pinyin: Wǒ yǒu yígè dìdi.', 'Tôi có một cậu em trai. → 我有一个弟弟。 (Wǒ yǒu yígè dìdi.)', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr11_vi_4', 'lesson-11', 'vi_to_zh', 'Bọn họ chỉ quan tâm đến bản thân mình mà thôi.', NULL, NULL, '他们只关心自己。', NULL, 'tāmen zhǐ guānxīn zìjǐ', '[]'::jsonb, 'Gợi ý Pinyin: Tāmen zhǐ guānxīn zìjǐ.', 'Bọn họ chỉ quan tâm đến bản thân mình mà thôi. → 他们只关心自己。 (Tāmen zhǐ guānxīn zìjǐ.)', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr11_vi_exp_1', 'lesson-11', 'vi_to_zh', 'Annie, nhà bạn có mấy người?', NULL, NULL, '安妮，你家有几口人？', NULL, 'ānnī nǐ jiā yǒu jǐ kǒu rén', '[]'::jsonb, 'Gợi ý Pinyin: Ānnī, nǐ jiā yǒu jǐ kǒu rén?', 'Annie, nhà bạn có mấy người? → 安妮，你家有几口人？ (Ānnī, nǐ jiā yǒu jǐ kǒu rén?)', 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr11_vi_exp_2', 'lesson-11', 'vi_to_zh', 'Nhà tôi có 6 người: ông nội, bà nội, bố, mẹ, anh trai và tôi. Còn nhà bạn thì sao?', NULL, NULL, '我家有六口人：我爷爷、奶奶、爸爸、妈妈、哥哥和我。你家呢？', NULL, 'wǒjiā yǒu liù kǒu rén wǒ yéye nǎinai bàba māma gēge hé wǒ nǐ jiā ne', '[]'::jsonb, 'Gợi ý Pinyin: Wǒjiā yǒu liù kǒu rén: Wǒ yéye, nǎinai, bàba, māma, gēge hé wǒ. Nǐ jiā ne?', 'Nhà tôi có 6 người: ông nội, bà nội, bố, mẹ, anh trai và tôi. Còn nhà bạn thì sao? → 我家有六口人：我爷爷、奶奶、爸爸、妈妈、哥哥和我。你家呢？ (Wǒjiā yǒu liù kǒu rén: Wǒ yéye, nǎinai, bàba, māma, gēge hé wǒ. Nǐ jiā ne?)', 6) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
