INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq11_10', 'lesson-11', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, 'Phiên âm Pinyin chính xác của “这么” là gì?', '["zhème","gǒu","gāo","bàba"]'::jsonb, 0, '“这么” đọc là: zhème (như thế, như thế này).', 10) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq11_11', 'lesson-11', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, 'Phiên âm Pinyin chính xác của “那么” là gì?', '["nàme","ǎi","māo","zhàopiàn"]'::jsonb, 0, '“那么” đọc là: nàme (như thế, như thế kia thì, vậy thì, trong trường hợp ấy).', 11) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq11_12', 'lesson-11', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, 'Phiên âm Pinyin chính xác của “多大” là gì?', '["xiàng","ǎi","nián","duōdà"]'::jsonb, 3, '“多大” đọc là: duōdà (bao nhiêu tuổi, to/lớn chừng nào...(để hỏi)).', 12) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq11_13', 'lesson-11', NULL, 'expanded_quiz', 'radical', NULL, NULL, 'Chữ Hán “家” chứa bộ thủ nào sau đây?', '["生 (Sinh) (Sinh sôi, sự sống, mới mẻ)","宀 (Miên) (Mái nhà, che chở, nơi ở)","见 (Kiến) (Nhìn thấy, gặp gỡ)","鼻 (Tỵ) (Cái mũi)"]'::jsonb, 1, 'Chữ “家” có bộ chính 宀 (Miên) (Mái nhà, che chở, nơi ở). Chiết tự: 家 = 宀 (Miên: mái nhà) + 豕 (Thỉ: lợn nuôi dưới mái nhà).', 13) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq11_14', 'lesson-11', NULL, 'expanded_quiz', 'radical', NULL, NULL, 'Chữ Hán “全家” chứa bộ thủ nào sau đây?', '["卩 (Tiết) (Đốt tre, ấn tín, quỳ gối)","人/亻 (Nhân) (Con người, nhân loại, hành động)","文 (Văn) (Văn chương, chữ viết, hoa văn)","矛 (Mâu) (Cây giáo, mâu thuẫn)"]'::jsonb, 1, 'Chữ “全家” có bộ chính 人/亻 (Nhân) (Con người, nhân loại, hành động). Chiết tự: 全: 人 (Nhân: mái che) + 王 (Ngọc: viên ngọc nguyên vẹn) • 家: 宀 (Miên: mái nhà) + 豕 (Thỉ: lợn nuôi dưới mái nhà)', 14) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq11_15', 'lesson-11', NULL, 'expanded_quiz', 'radical', NULL, NULL, 'Chữ Hán “照片” chứa bộ thủ nào sau đây?', '["囗 (Vi) (Vây quanh, không gian kín, lãnh thổ)","无 (Vô) (Không có, phủ định)","立 (Lập) (Đứng vững, thiết lập)","火/灬 (Hỏa) (Lửa, nhiệt độ, nấu nướng, nóng bức)"]'::jsonb, 3, 'Chữ “照片” có bộ chính 火/灬 (Hỏa) (Lửa, nhiệt độ, nấu nướng, nóng bức). Chiết tự: 照: 昭 (Chiêu: ánh sáng) + 灬 (Hỏa: ngọn lửa soi chiếu) • 片: Bộ 片 (Phiến - nửa thân gỗ xẻ mỏng)', 15) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq11_16', 'lesson-11', NULL, 'expanded_quiz', 'radical', NULL, NULL, 'Chữ Hán “爷爷” chứa bộ thủ nào sau đây?', '["户 (Hộ) (Cánh cửa, gia đình, nhà cửa)","父 (Phụ) (Người cha)","皮 (Bì) (Da dẻ, vỏ ngoài)","足/⻊ (Túc) (Bàn chân, bước chân, đá bóng, chạy)"]'::jsonb, 1, 'Chữ “爷爷” có bộ chính 父 (Phụ) (Người cha). Chiết tự: 爷: 父 (Phụ: cha) + 卩 (Tiết) • 爷: 父 (Phụ: cha) + 卩 (Tiết)', 16) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq11_17', 'lesson-11', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, '[Ôn tập Bài 9] Từ đã học “粉红色” (fěnhóngsè) có nghĩa là gì?', '["xa","màu hồng phấn","giờ, châm(lửa)","rẽ"]'::jsonb, 1, 'Ôn tập Bài 9: “粉红色” (fěnhóngsè) nghĩa là: màu hồng phấn.', 17) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq11_18', 'lesson-11', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, '[Ôn tập Bài 9] Từ đã học “结账” (jié zhàng) có nghĩa là gì?', '["thanh toán","phía trước","hiện tại, bây giờ","về, trở về, trở lại"]'::jsonb, 0, 'Ôn tập Bài 9: “结账” (jié zhàng) nghĩa là: thanh toán.', 18) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq11_19', 'lesson-11', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, '[Ôn tập Bài 7] Từ đã học “家” (jiā) có nghĩa là gì?', '["giống","ngôi, hiệu, tiệm, quán (lượng từ của cửa hàng, công ty,...)","cửa, cổng","đáng yêu"]'::jsonb, 1, 'Ôn tập Bài 7: “家” (jiā) nghĩa là: ngôi, hiệu, tiệm, quán (lượng từ của cửa hàng, công ty,...).', 19) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq11_20', 'lesson-11', NULL, 'expanded_quiz', 'reading', NULL, NULL, '[Mở rộng] Câu “我家有四口人：爸爸、妈妈、哥哥和我。” có nghĩa tiếng Việt là gì?', '["Bệnh của mẹ khỏi lâu rồi, con đừng lo lắng.","Nhà tôi có bốn người: bố, mẹ, anh trai và tôi.","Mark, cậu lại đang làm gì nữa vậy?","Cậu nói gì vậy?"]'::jsonb, 1, '我家有四口人：爸爸、妈妈、哥哥和我。 (Wǒ jiā yǒu sì kǒu rén: bàba, māma, gēge hé wǒ.) → Nhà tôi có bốn người: bố, mẹ, anh trai và tôi.', 20) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq11_21', 'lesson-11', NULL, 'expanded_quiz', 'reading', NULL, NULL, '[Đọc hiểu mở rộng] Đọc đoạn hội thoại:
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq11_22', 'lesson-11', NULL, 'expanded_quiz', 'reading', NULL, NULL, 'Câu “我有一个弟弟。” có nghĩa tiếng Việt là gì?', '["Tôi không có em trai.","Bệnh của mẹ khỏi lâu rồi, con đừng lo lắng.","Lúc mẹ nấu cơm thì tôi đang tắm.","Tôi có một cậu em trai."]'::jsonb, 3, '我有一个弟弟。 (Wǒ yǒu yígè dìdi.) → Tôi có một cậu em trai.', 22) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct11_1', 'lesson-11', NULL, 'comprehensive_test', 'listening', '你姐姐今年多大了？', NULL, 'Nghe đoạn ghi âm và chọn nghĩa tiếng Việt đúng:', '["Cậu nói gì?","Xin chào!","Chị gái bạn năm nay bao nhiêu tuổi rồi?","Được rồi, chúng ta đi thanh toán thôi!"]'::jsonb, 2, 'Nội dung nghe được: “你姐姐今年多大了？” (Nǐ jiějie jīnnián duōdà le?) → Chị gái bạn năm nay bao nhiêu tuổi rồi?', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct11_2', 'lesson-11', NULL, 'comprehensive_test', 'listening', '她是老师。', NULL, 'Nghe đoạn ghi âm và chọn câu tiếng Trung khớp với nội dung vừa nghe:', '["是啊。在网上你可以买到很多东西，比如衣服、手表、眼镜、书本等等。","西瓜一个十五块。芒果一斤七块。","她是老师。","是啊，谢谢你！"]'::jsonb, 2, 'Câu vừa đọc: “她是老师。” (Tā shì lǎoshī.) → Cô ấy là giáo viên.', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct11_3', 'lesson-11', NULL, 'comprehensive_test', 'listening', '草莓果汁十块钱两杯', NULL, 'Nghe đoạn ghi âm và chọn nghĩa tiếng Việt đúng:', '["Nửa kg (1 cân) táo bao nhiêu tiền?","Sáng mai mấy giờ bạn đến phòng học?","Nước ép dâu tây 10 tệ hai cốc.","Bây giờ là 8 giờ 15 phút sáng."]'::jsonb, 2, 'Nội dung nghe được: “草莓果汁十块钱两杯” (Cǎoméi guǒzhī shí kuài qián liǎng bēi.) → Nước ép dâu tây 10 tệ hai cốc.', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct11_4', 'lesson-11', NULL, 'comprehensive_test', 'listening', '我有一个弟弟。', NULL, 'Nghe đoạn ghi âm và chọn câu tiếng Trung khớp với nội dung vừa nghe:', '["安妮，你家有几口人？","有的质量挺好，但是也有的太差了！你要小心啊！","我有一个弟弟。","网上买的手表质量怎么样"]'::jsonb, 2, 'Câu vừa đọc: “我有一个弟弟。” (Wǒ yǒu yígè dìdi.) → Tôi có một cậu em trai.', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct11_5', 'lesson-11', NULL, 'comprehensive_test', 'listening', '奶奶和爷爷每天都很高兴', NULL, 'Nghe đoạn ghi âm và chọn nghĩa tiếng Việt đúng:', '["Đây là sách gì?","Chào thầy/Chào cô","Bà nội và ông nội ngày nào cũng rất vui vẻ.","Lấy cho cháu một quả dưa hấu, hai cân thanh long và hai cốc nước ép dâu."]'::jsonb, 2, 'Nội dung nghe được: “奶奶和爷爷每天都很高兴” (Nǎinai hé yéye měitiān dōu hěn gāoxìng.) → Bà nội và ông nội ngày nào cũng rất vui vẻ.', 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct11_6', 'lesson-11', NULL, 'comprehensive_test', 'listening', '安妮，你家有几口人？', NULL, 'Nghe đoạn ghi âm và chọn câu tiếng Trung khớp với nội dung vừa nghe:', '["我不知道。","是啊。在网上你可以买到很多东西，比如衣服、手表、眼镜、书本等等。","你是日明吗？","安妮，你家有几口人？"]'::jsonb, 3, 'Câu vừa đọc: “安妮，你家有几口人？” (Ānnī, nǐ jiā yǒu jǐ kǒu rén?) → Annie, nhà bạn có mấy người?', 6) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct11_7', 'lesson-11', NULL, 'comprehensive_test', 'listening', '我家有四口人爸爸妈妈哥哥和我', NULL, 'Nghe đoạn ghi âm và chọn nghĩa tiếng Việt đúng:', '["Bạn là du học sinh phải không?","Nguyễn Nhật Minh cũng là học sinh à?","Nhà tôi có bốn người: bố, mẹ, anh trai và tôi.","Chiếc cặp sách màu vàng kia đẹp thật đấy!"]'::jsonb, 2, 'Nội dung nghe được: “我家有四口人爸爸妈妈哥哥和我” (Wǒ jiā yǒu sì kǒu rén: bàba, māma, gēge hé wǒ.) → Nhà tôi có bốn người: bố, mẹ, anh trai và tôi.', 7) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct11_8', 'lesson-11', NULL, 'comprehensive_test', 'listening', '为什么你昨天那么晚才回来？', NULL, 'Nghe đoạn ghi âm và chọn câu tiếng Trung khớp với nội dung vừa nghe:', '["为什么你昨天那么晚才回来？","你往左拐，然后一直往前走就到。","医院在我们学校的右边。","老师在外面等你。"]'::jsonb, 0, 'Câu vừa đọc: “为什么你昨天那么晚才回来？” (Wèishénme nǐ zuótiān nàme wǎn cái huílai?) → Vì sao tối qua muộn như thế anh mới về?', 8) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
