INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct11_47', 'lesson-11', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ “自己” có nghĩa tiếng Việt là gì?', '["quen biết, biết","bao nhiêu tuổi, to/lớn chừng nào...(để hỏi)","Trường học","tự mình, bản thân, một mình"]'::jsonb, 3, '“自己” (zìjǐ) là Đại từ, nghĩa là: tự mình, bản thân, một mình.', 47) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct11_48', 'lesson-11', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ Hán tự “爱” (yêu) có phiên âm Pinyin đúng là gì?', '["Mǎkè","zìjǐ","dàyī","ài"]'::jsonb, 3, '“爱” đọc là “ài”, nghĩa là: yêu.', 48) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
