INSERT INTO lessons (id, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id) VALUES ('lesson-12', 'Bài 12: Tiếp đãi khách - Đơn nguyên 3: Gia đình', 'Bài 12', 'Đơn nguyên 3: Gia đình', 'Mời khách vào nhà, pha trà, mời hoa quả, phép lịch sự và thói quen hiếu khách.', '2026-11-14'::date, 12, TRUE, NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, date_added = EXCLUDED.date_added, sort_order = EXCLUDED.sort_order, is_system = TRUE, updated_at = NOW();
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v12_1', 'lesson-12', '客人', 'kèrén', 'khách nhân', 'khách', 'Danh từ', '宀 (Miên) (Mái nhà, che chở, nơi ở)', '客: 宀 (Miên: mái nhà) + 各 (Các: người tới nhà) • 人: Bộ 人 (Nhân - dáng người đứng bước, chữ độc thể)', 'Ghép 客 [bộ 宀] + 人 [bộ 人] để nhớ từ 客人 (kèrén): "khách".', '这是关于“客人”的常用句子。', 'Zhè shì guānyú ''kèrén'' de chángyòng jùzi.', 'Đây là câu ví dụ sử dụng từ ''客人'' (khách).', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v12_2', 'lesson-12', '水', 'shǔi', 'thủy', 'nước', 'Danh từ', '水/氵 (Thủy) (Nước, chất lỏng, sông ngòi)', '水 = Bộ 水 (Thủy - dòng nước chảy, chữ độc thể).', 'Chữ 水 (shǔi) mang nghĩa "nước", bộ chính 水/氵 (Thủy); cấu tạo: Bộ 水 (Thủy - dòng nước chảy, chữ độc thể).', '我也有点儿不好意思，但是张风和他家人都很欢迎我们。阿姨给我们准备了很多好吃的，有茶、咖啡、牛肉、鱼、水果等等。', 'Wǒ yě yǒudiǎnr bù hǎoyìsi, dànshì Zhāng Fēng hé tā jiārén dōu hěn huānyíng wǒmen. Āyí gěi wǒmen zhǔnbèi le hěnduō hǎo chī de, yǒu chá, kāfēi, niúròu, yú, shuǐguǒ děng děng.', 'Tớ cũng hơi ngại một chút, nhưng Trương Phong và gia đình cậu ấy rất hoan nghênh bọn tớ. Cô ấy chuẩn bị cho bọn tớ rất nhiều đồ ngon, nào là trà, cà phê, thịt bò, cá, hoa quả, v.v.', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v12_3', 'lesson-12', '茶', 'chá', 'trà', 'trà', 'Danh từ', '艹 (Thảo) (Cỏ cây, hoa lá, thảo mộc)', '茶 = 艹 (Thảo: lá chè) + 人 (Nhân) + 木 (Mộc: cây cỏ hái bởi người).', 'Chữ 茶 (chá) mang nghĩa "trà", bộ chính 艹 (Thảo); cấu tạo: 艹 (Thảo: lá chè) + 人 (Nhân) + 木 (Mộc: cây cỏ hái bởi người).', '我也有点儿不好意思，但是张风和他家人都很欢迎我们。阿姨给我们准备了很多好吃的，有茶、咖啡、牛肉、鱼、水果等等。', 'Wǒ yě yǒudiǎnr bù hǎoyìsi, dànshì Zhāng Fēng hé tā jiārén dōu hěn huānyíng wǒmen. Āyí gěi wǒmen zhǔnbèi le hěnduō hǎo chī de, yǒu chá, kāfēi, niúròu, yú, shuǐguǒ děng děng.', 'Tớ cũng hơi ngại một chút, nhưng Trương Phong và gia đình cậu ấy rất hoan nghênh bọn tớ. Cô ấy chuẩn bị cho bọn tớ rất nhiều đồ ngon, nào là trà, cà phê, thịt bò, cá, hoa quả, v.v.', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v12_4', 'lesson-12', '咖啡', 'kāfēi', 'từ Hán ngữ', 'cà phê', 'Danh từ', '口 (Khẩu) (Miệng, ăn uống, lời nói, âm thanh phát ra)', '咖: 口 (Khẩu: thức uống) + 加 (Gia: phiên âm ca) • 啡: 口 (Khẩu: thức uống) + 非 (Phi: phiên âm phê)', 'Ghép 咖 [bộ 口] + 啡 [bộ 口] để nhớ từ 咖啡 (kāfēi): "cà phê".', '我也有点儿不好意思，但是张风和他家人都很欢迎我们。阿姨给我们准备了很多好吃的，有茶、咖啡、牛肉、鱼、水果等等。', 'Wǒ yě yǒudiǎnr bù hǎoyìsi, dànshì Zhāng Fēng hé tā jiārén dōu hěn huānyíng wǒmen. Āyí gěi wǒmen zhǔnbèi le hěnduō hǎo chī de, yǒu chá, kāfēi, niúròu, yú, shuǐguǒ děng děng.', 'Tớ cũng hơi ngại một chút, nhưng Trương Phong và gia đình cậu ấy rất hoan nghênh bọn tớ. Cô ấy chuẩn bị cho bọn tớ rất nhiều đồ ngon, nào là trà, cà phê, thịt bò, cá, hoa quả, v.v.', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v12_5', 'lesson-12', '牛肉', 'niúròu', 'từ Hán ngữ', 'thịt bò', 'Danh từ', '牛/牜 (Ngưu) (Con trâu, bò, gia súc)', '牛: Bộ 牛 (Ngưu - đầu và sừng con bò/trâu) • 肉: Bộ 肉 (Nhục - miếng thịt có thớ)', 'Ghép 牛 [bộ 牛] + 肉 [bộ 肉] để nhớ từ 牛肉 (niúròu): "thịt bò".', '我也有点儿不好意思，但是张风和他家人都很欢迎我们。阿姨给我们准备了很多好吃的，有茶、咖啡、牛肉、鱼、水果等等。', 'Wǒ yě yǒudiǎnr bù hǎoyìsi, dànshì Zhāng Fēng hé tā jiārén dōu hěn huānyíng wǒmen. Āyí gěi wǒmen zhǔnbèi le hěnduō hǎo chī de, yǒu chá, kāfēi, niúròu, yú, shuǐguǒ děng děng.', 'Tớ cũng hơi ngại một chút, nhưng Trương Phong và gia đình cậu ấy rất hoan nghênh bọn tớ. Cô ấy chuẩn bị cho bọn tớ rất nhiều đồ ngon, nào là trà, cà phê, thịt bò, cá, hoa quả, v.v.', 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v12_6', 'lesson-12', '鱼', 'yú', 'từ Hán ngữ', 'cá', 'Danh từ', '鱼 (Ngư) (Con cá, thủy sản)', '鱼 = Bộ 鱼 (Ngư - đầu, thân vảy và đuôi con cá).', 'Chữ 鱼 (yú) mang nghĩa "cá", bộ chính 鱼 (Ngư); cấu tạo: Bộ 鱼 (Ngư - đầu, thân vảy và đuôi con cá).', '我也有点儿不好意思，但是张风和他家人都很欢迎我们。阿姨给我们准备了很多好吃的，有茶、咖啡、牛肉、鱼、水果等等。', 'Wǒ yě yǒudiǎnr bù hǎoyìsi, dànshì Zhāng Fēng hé tā jiārén dōu hěn huānyíng wǒmen. Āyí gěi wǒmen zhǔnbèi le hěnduō hǎo chī de, yǒu chá, kāfēi, niúròu, yú, shuǐguǒ děng děng.', 'Tớ cũng hơi ngại một chút, nhưng Trương Phong và gia đình cậu ấy rất hoan nghênh bọn tớ. Cô ấy chuẩn bị cho bọn tớ rất nhiều đồ ngon, nào là trà, cà phê, thịt bò, cá, hoa quả, v.v.', 6) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v12_7', 'lesson-12', '下次', 'xià cì', 'hạ', 'lần sau', 'Danh từ', '一 (Nhất) (Số một, nền tảng, nét ngang cơ bản)', '下: Nét ngang 一 phía trên nét sổ 丨 và chấm chỉ hướng xuống dưới • 次: 冫 (Băng) + 欠 (Khiếm)', 'Ghép 下 [bộ 一] + 次 [bộ 欠] để nhớ từ 下次 (xià cì): "lần sau".', '昨天上午山本才说他可以去，所以到那个时候我们才决定去!等下次吧！下次去玩儿我就跟你说。', 'Zuótiān shàngwǔ Shānběn cái shuō tā kěyǐ qù, suǒyǐ dào nàge shíhou wǒmen cái juédìng qù! Děng xià cì ba! Xià cì qù wánr wǒ jiù gēn nǐ shuō.', 'Sáng hôm qua Yamamoto mới nói có thể đi, nên lúc đó bọn tớ mới quyết định đi! Đợi lần sau nhé! Lần sau đi chơi tớ sẽ rủ cậu.', 7) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v12_8', 'lesson-12', '做客', 'zuòkè', 'tác khách', 'làm khách', 'Động từ', '人/亻 (Nhân) (Con người, nhân loại, hành động)', '做: 亻 (Nhân đứng: người) + 故 (Cố: làm việc) • 客: 宀 (Miên: mái nhà) + 各 (Các: người tới nhà)', 'Ghép 做 [bộ 亻] + 客 [bộ 宀] để nhớ từ 做客 (zuòkè): "làm khách".', '张风请我们去他家做客。', 'Zhāng Fēng qǐng wǒmen qù tā jiā zuòkè.', 'Trương Phong mời bọn tớ đến nhà cậu ấy chơi.', 8) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v12_9', 'lesson-12', '欢迎', 'huānyíng', 'hoan nghênh', 'chào mừng, chào đón', 'Động từ', '欠 (Khiếm) (Ngáp, thiếu thốn, hơi thở)', '欢: 又 (Hựu) + 欠 (Khiếm: reo vui) • 迎: 卬 (Ngưỡng) + 辶 (Sước: bước ra đón)', 'Ghép 欢 [bộ 欠] + 迎 [bộ 辶] để nhớ từ 欢迎 (huānyíng): "chào mừng, chào đón".', '我也有点儿不好意思，但是张风和他家人都很欢迎我们。阿姨给我们准备了很多好吃的，有茶、咖啡、牛肉、鱼、水果等等。', 'Wǒ yě yǒudiǎnr bù hǎoyìsi, dànshì Zhāng Fēng hé tā jiārén dōu hěn huānyíng wǒmen. Āyí gěi wǒmen zhǔnbèi le hěnduō hǎo chī de, yǒu chá, kāfēi, niúròu, yú, shuǐguǒ děng děng.', 'Tớ cũng hơi ngại một chút, nhưng Trương Phong và gia đình cậu ấy rất hoan nghênh bọn tớ. Cô ấy chuẩn bị cho bọn tớ rất nhiều đồ ngon, nào là trà, cà phê, thịt bò, cá, hoa quả, v.v.', 9) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v12_10', 'lesson-12', '接待', 'jiēdài', 'từ Hán ngữ', 'tiếp đãi, tiếp đón', 'Động từ', '手/扌 (Thủ) (Bàn tay, động tác, thao tác)', '接: 扌 (Thủ: bàn tay đưa ra) + 妾 (Thiếp) • 待: 彳 (Xích: dừng chân chờ đợi) + 寺 (Tự)', 'Ghép 接 [bộ 扌] + 待 [bộ 彳] để nhớ từ 接待 (jiēdài): "tiếp đãi, tiếp đón".', '是的。张风给我们介绍了他的妈妈和弟弟，他爸爸不在家。阿姨很漂亮、很年轻，他弟弟也很可爱。他们都很热情地接待了我们。', 'Shì de. Zhāng Fēng gěi wǒmen jièshào le tā de māma hé dìdi, tā bàba bú zàijiā. Āyí hěn piàoliang, hěn niánqīng, tā dìdi yě hěn kě''ài. Tāmen dōu hěn rèqíng de jiēdài le wǒmen.', 'Đúng rồi. Trương Phong giới thiệu mẹ và em trai cậu ấy cho bọn tớ, bố cậu ấy không có ở nhà. Cô ấy rất xinh đẹp và trẻ trung, em trai cậu ấy cũng rất đáng yêu. Mọi người đều tiếp đón bọn tớ rất nhiệt tình.', 10) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v12_11', 'lesson-12', '介绍', 'jièshào', 'từ Hán ngữ', 'giới thiệu', 'Động từ', '人/亻 (Nhân) (Con người, nhân loại, hành động)', '介: 人 (Nhân) + 儿 (những vạch phân chia) • 绍: 纟 (Mịch: sợi dây kết nối) + 召 (Triệu)', 'Ghép 介 [bộ 人] + 绍 [bộ 纟] để nhớ từ 介绍 (jièshào): "giới thiệu".', '是的。张风给我们介绍了他的妈妈和弟弟，他爸爸不在家。阿姨很漂亮、很年轻，他弟弟也很可爱。他们都很热情地接待了我们。', 'Shì de. Zhāng Fēng gěi wǒmen jièshào le tā de māma hé dìdi, tā bàba bú zàijiā. Āyí hěn piàoliang, hěn niánqīng, tā dìdi yě hěn kě''ài. Tāmen dōu hěn rèqíng de jiēdài le wǒmen.', 'Đúng rồi. Trương Phong giới thiệu mẹ và em trai cậu ấy cho bọn tớ, bố cậu ấy không có ở nhà. Cô ấy rất xinh đẹp và trẻ trung, em trai cậu ấy cũng rất đáng yêu. Mọi người đều tiếp đón bọn tớ rất nhiệt tình.', 11) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v12_12', 'lesson-12', '说', 'shuō', 'thuyết', 'nói', 'Động từ', '言/讠 (Ngôn) (Lời nói, ngôn ngữ, giao tiếp)', '说 = 讠 (Ngôn: lời nói) + 兑 (Đoài).', 'Chữ 说 (shuō) mang nghĩa "nói", bộ chính 言/讠 (Ngôn); cấu tạo: 讠 (Ngôn: lời nói) + 兑 (Đoài).', '昨天上午山本才说他可以去，所以到那个时候我们才决定去!等下次吧！下次去玩儿我就跟你说。', 'Zuótiān shàngwǔ Shānběn cái shuō tā kěyǐ qù, suǒyǐ dào nàge shíhou wǒmen cái juédìng qù! Děng xià cì ba! Xià cì qù wánr wǒ jiù gēn nǐ shuō.', 'Sáng hôm qua Yamamoto mới nói có thể đi, nên lúc đó bọn tớ mới quyết định đi! Đợi lần sau nhé! Lần sau đi chơi tớ sẽ rủ cậu.', 12) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v12_13', 'lesson-12', '聊天儿', 'liáotiānr', 'thiên nhi', 'nói chuyện phiếm', 'Động từ', '耳 (Nhĩ) (Cái tai, lắng nghe)', '聊: 耳 (Nhĩ: tai nghe) + 卯 (Mão) • 天: 一 (Nhất: bầu trời cao) + 大 (Đại: con người dang tay) • 儿: Bộ 儿 (Nhi - nét cong, chữ độc thể)', 'Ghép 聊 [bộ 耳] + 天 [bộ 大] + 儿 [bộ 儿] để nhớ từ 聊天儿 (liáotiānr): "nói chuyện phiếm".', '打游戏、听音乐、聊天儿、喝 水、吃东西。到十点半我们才回宿舍。现在回想起来，昨天真快乐，真热闹。', 'Dǎ yóuxì, tīng yīnyuè, liáotiānr, hē shuǐ, chī dōngxi. Dào shí diǎn bàn wǒmen cái huí sùshè. Xiànzài huíxiǎng qǐlai, zuótiān zhēn kuàilè, zhēn rènao.', 'Chơi game, nghe nhạc, trò chuyện, uống nước, ăn uống. Đến 10 giờ rưỡi bọn tớ mới về ký túc xá. Giờ nhớ lại, hôm qua thật vui và náo nhiệt.', 13) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v12_14', 'lesson-12', '喝', 'hē', 'hát', 'uống', 'Động từ', '口 (Khẩu) (Miệng, ăn uống, lời nói, âm thanh phát ra)', '喝 = 口 (Khẩu: miệng uống) + 曷 (Hạt).', 'Chữ 喝 (hē) mang nghĩa "uống", bộ chính 口 (Khẩu); cấu tạo: 口 (Khẩu: miệng uống) + 曷 (Hạt).', '打游戏、听音乐、聊天儿、喝 水、吃东西。到十点半我们才回宿舍。现在回想起来，昨天真快乐，真热闹。', 'Dǎ yóuxì, tīng yīnyuè, liáotiānr, hē shuǐ, chī dōngxi. Dào shí diǎn bàn wǒmen cái huí sùshè. Xiànzài huíxiǎng qǐlai, zuótiān zhēn kuàilè, zhēn rènao.', 'Chơi game, nghe nhạc, trò chuyện, uống nước, ăn uống. Đến 10 giờ rưỡi bọn tớ mới về ký túc xá. Giờ nhớ lại, hôm qua thật vui và náo nhiệt.', 14) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v12_15', 'lesson-12', '听音乐', 'tīng yīnyuè', 'thính lạc', 'nghe nhạc', 'Động từ', '口 (Khẩu) (Miệng, ăn uống, lời nói, âm thanh phát ra)', '听: 口 (Khẩu) + 斤 (Cân) • 音: 立 (Lập) + 日 (Nhật: tiếng vang phát ra) • 乐: Nét phẩy trên nhạc cụ dây/trống gỗ (vui vẻ, âm nhạc)', 'Ghép 听 [bộ 口] + 音 [bộ 音] + 乐 [bộ 丿] để nhớ từ 听音乐 (tīng yīnyuè): "nghe nhạc".', '打游戏、听音乐、聊天儿、喝 水、吃东西。到十点半我们才回宿舍。现在回想起来，昨天真快乐，真热闹。', 'Dǎ yóuxì, tīng yīnyuè, liáotiānr, hē shuǐ, chī dōngxi. Dào shí diǎn bàn wǒmen cái huí sùshè. Xiànzài huíxiǎng qǐlai, zuótiān zhēn kuàilè, zhēn rènao.', 'Chơi game, nghe nhạc, trò chuyện, uống nước, ăn uống. Đến 10 giờ rưỡi bọn tớ mới về ký túc xá. Giờ nhớ lại, hôm qua thật vui và náo nhiệt.', 15) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v12_16', 'lesson-12', '打游戏', 'dǎ yóuxì', 'du', 'chơi game, chơi trò chơi', 'Động từ', '手/扌 (Thủ) (Bàn tay, động tác, thao tác)', '打: 扌 (Thủ: bàn tay) + 丁 (Đinh) • 游: 氵 (Thủy: bơi lội trong nước) + 斿 • 戏: 又 (Hựu) + 戈 (Qua: diễn trò)', 'Ghép 打 [bộ 扌] + 游 [bộ 氵] + 戏 [bộ 戈] để nhớ từ 打游戏 (dǎ yóuxì): "chơi game, chơi trò chơi".', '打游戏、听音乐、聊天儿、喝 水、吃东西。到十点半我们才回宿舍。现在回想起来，昨天真快乐，真热闹。', 'Dǎ yóuxì, tīng yīnyuè, liáotiānr, hē shuǐ, chī dōngxi. Dào shí diǎn bàn wǒmen cái huí sùshè. Xiànzài huíxiǎng qǐlai, zuótiān zhēn kuàilè, zhēn rènao.', 'Chơi game, nghe nhạc, trò chuyện, uống nước, ăn uống. Đến 10 giờ rưỡi bọn tớ mới về ký túc xá. Giờ nhớ lại, hôm qua thật vui và náo nhiệt.', 16) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v12_17', 'lesson-12', '玩儿', 'wánr', 'ngoạn nhi', 'chơi', 'Động từ', '玉/王 (Ngọc) (Đá quý, vua chúa)', '玩: 王 (Ngọc: viên ngọc cầm chơi) + 元 (Nguyên) • 儿: Bộ 儿 (Nhi - nét cong, chữ độc thể)', 'Ghép 玩 [bộ 王] + 儿 [bộ 儿] để nhớ từ 玩儿 (wánr): "chơi".', '昨天上午山本才说他可以去，所以到那个时候我们才决定去!等下次吧！下次去玩儿我就跟你说。', 'Zuótiān shàngwǔ Shānběn cái shuō tā kěyǐ qù, suǒyǐ dào nàge shíhou wǒmen cái juédìng qù! Děng xià cì ba! Xià cì qù wánr wǒ jiù gēn nǐ shuō.', 'Sáng hôm qua Yamamoto mới nói có thể đi, nên lúc đó bọn tớ mới quyết định đi! Đợi lần sau nhé! Lần sau đi chơi tớ sẽ rủ cậu.', 17) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v12_18', 'lesson-12', '准备', 'zhǔnbèi', 'từ Hán ngữ', 'chuẩn bị', 'Động từ', '冫 (Băng) (Nước đá, lạnh giá)', '准: 冫 (Băng) + 隹 (Chuy) • 备: 夂 (Trĩ) + 田 (Điền)', 'Ghép 准 [bộ 冫] + 备 [bộ 夂] để nhớ từ 准备 (zhǔnbèi): "chuẩn bị".', '我也有点儿不好意思，但是张风和他家人都很欢迎我们。阿姨给我们准备了很多好吃的，有茶、咖啡、牛肉、鱼、水果等等。', 'Wǒ yě yǒudiǎnr bù hǎoyìsi, dànshì Zhāng Fēng hé tā jiārén dōu hěn huānyíng wǒmen. Āyí gěi wǒmen zhǔnbèi le hěnduō hǎo chī de, yǒu chá, kāfēi, niúròu, yú, shuǐguǒ děng děng.', 'Tớ cũng hơi ngại một chút, nhưng Trương Phong và gia đình cậu ấy rất hoan nghênh bọn tớ. Cô ấy chuẩn bị cho bọn tớ rất nhiều đồ ngon, nào là trà, cà phê, thịt bò, cá, hoa quả, v.v.', 18) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v12_19', 'lesson-12', '聚会', 'jùhuì', 'từ Hán ngữ', 'tụ họp, buổi tụ họp', 'Động từ / Danh từ', '耳 (Nhĩ) (Cái tai, lắng nghe)', '聚: 取 (Thủ: gom lấy) + 𠂊/众 (nhiều người tụ họp) • 会: 人 (Nhân: mái tụ họp) + 云 (Vân)', 'Ghép 聚 [bộ 耳] + 会 [bộ 人] để nhớ từ 聚会 (jùhuì): "tụ họp, buổi tụ họp".', '你们到他家聚会还是有什么事？', 'Nǐmen dào tā jiā jùhuì háishi yǒu shénme shì?', 'Các cậu đến nhà cậu ấy tụ tập hay có việc gì thế?', 19) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v12_20', 'lesson-12', '决定', 'juédìng', 'từ Hán ngữ', 'quyết định', 'Động từ', '冫 (Băng) (Nước đá, lạnh giá)', '决: 冫 (Băng) + 夬 (Quái) • 定: 宀 (Miên: mái nhà yên ổn) + 疋 (Thất)', 'Ghép 决 [bộ 冫] + 定 [bộ 宀] để nhớ từ 决定 (juédìng): "quyết định".', '昨天上午山本才说他可以去，所以到那个时候我们才决定去!等下次吧！下次去玩儿我就跟你说。', 'Zuótiān shàngwǔ Shānběn cái shuō tā kěyǐ qù, suǒyǐ dào nàge shíhou wǒmen cái juédìng qù! Děng xià cì ba! Xià cì qù wánr wǒ jiù gēn nǐ shuō.', 'Sáng hôm qua Yamamoto mới nói có thể đi, nên lúc đó bọn tớ mới quyết định đi! Đợi lần sau nhé! Lần sau đi chơi tớ sẽ rủ cậu.', 20) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v12_21', 'lesson-12', '热闹', 'rènao', 'nhiệt', 'ồn ào, náo nhiệt', 'Tính từ', '火/灬 (Hỏa) (Lửa, nhiệt độ, nấu nướng, nóng bức)', '热: 执 (Chấp) + 灬 (Hỏa: ngọn lửa nóng rực) • 闹: 门 (Môn: cổng chợ) + 市 (Thị: phố chợ đông đúc)', 'Ghép 热 [bộ 灬] + 闹 [bộ 门] để nhớ từ 热闹 (rènao): "ồn ào, náo nhiệt".', '打游戏、听音乐、聊天儿、喝 水、吃东西。到十点半我们才回宿舍。现在回想起来，昨天真快乐，真热闹。', 'Dǎ yóuxì, tīng yīnyuè, liáotiānr, hē shuǐ, chī dōngxi. Dào shí diǎn bàn wǒmen cái huí sùshè. Xiànzài huíxiǎng qǐlai, zuótiān zhēn kuàilè, zhēn rènao.', 'Chơi game, nghe nhạc, trò chuyện, uống nước, ăn uống. Đến 10 giờ rưỡi bọn tớ mới về ký túc xá. Giờ nhớ lại, hôm qua thật vui và náo nhiệt.', 21) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v12_22', 'lesson-12', '快乐', 'kuàilè', 'khoái lạc', 'vui vẻ', 'Tính từ', '心/忄 (Tâm) (Trái tim, tình cảm, suy nghĩ, tâm lý)', '快: 忄 (Tâm đứng: cảm xúc) + 夬 (Quái: nhanh, vui) • 乐: Nét phẩy trên nhạc cụ dây/trống gỗ (vui vẻ, âm nhạc)', 'Ghép 快 [bộ 忄] + 乐 [bộ 丿] để nhớ từ 快乐 (kuàilè): "vui vẻ".', '打游戏、听音乐、聊天儿、喝 水、吃东西。到十点半我们才回宿舍。现在回想起来，昨天真快乐，真热闹。', 'Dǎ yóuxì, tīng yīnyuè, liáotiānr, hē shuǐ, chī dōngxi. Dào shí diǎn bàn wǒmen cái huí sùshè. Xiànzài huíxiǎng qǐlai, zuótiān zhēn kuàilè, zhēn rènao.', 'Chơi game, nghe nhạc, trò chuyện, uống nước, ăn uống. Đến 10 giờ rưỡi bọn tớ mới về ký túc xá. Giờ nhớ lại, hôm qua thật vui và náo nhiệt.', 22) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v12_23', 'lesson-12', '紧张', 'jǐnzhāng', 'từ Hán ngữ', 'căng thẳng, hồi hộp', 'Tính từ', '糸/纟 (Mịch) (Sợi tơ, gắn kết, màu sắc)', '紧: 臤 (Hiền rút gọn) + 糸 (Mịch: sợi dây kéo căng) • 张: 弓 (Cung: cây cung) + 长 (Trường: kéo dài dây cung)', 'Ghép 紧 [bộ 糸] + 张 [bộ 弓] để nhớ từ 紧张 (jǐnzhāng): "căng thẳng, hồi hộp".', '你们不觉得紧张吗？如果是我，我就紧张死了。', 'Nǐmen bù juéde jǐnzhāng ma? Rúguǒ shì wǒ, wǒ jiù jǐnzhāng sǐle.', 'Các cậu không thấy hồi hộp à? Nếu là tớ chắc tớ hồi hộp chết mất.', 23) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v12_24', 'lesson-12', '热情', 'rèqíng', 'nhiệt', 'nhiệt tình', 'Tính từ', '火/灬 (Hỏa) (Lửa, nhiệt độ, nấu nướng, nóng bức)', '热: 执 (Chấp) + 灬 (Hỏa: ngọn lửa nóng rực) • 情: 忄 (Tâm đứng: trái tim) + 青 (Thanh: tình cảm tươi trẻ)', 'Ghép 热 [bộ 灬] + 情 [bộ 忄] để nhớ từ 热情 (rèqíng): "nhiệt tình".', '是的。张风给我们介绍了他的妈妈和弟弟，他爸爸不在家。阿姨很漂亮、很年轻，他弟弟也很可爱。他们都很热情地接待了我们。', 'Shì de. Zhāng Fēng gěi wǒmen jièshào le tā de māma hé dìdi, tā bàba bú zàijiā. Āyí hěn piàoliang, hěn niánqīng, tā dìdi yě hěn kě''ài. Tāmen dōu hěn rèqíng de jiēdài le wǒmen.', 'Đúng rồi. Trương Phong giới thiệu mẹ và em trai cậu ấy cho bọn tớ, bố cậu ấy không có ở nhà. Cô ấy rất xinh đẹp và trẻ trung, em trai cậu ấy cũng rất đáng yêu. Mọi người đều tiếp đón bọn tớ rất nhiệt tình.', 24) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v12_25', 'lesson-12', '年轻', 'niánqīng', 'niên', 'trẻ tuổi', 'Tính từ', '干 (Can) (Can thiệp, khô ráo, làm việc)', '年: 𠂉 + 干/土 (mùa màng thu hoạch một năm) • 轻: 车 (Xa: xe cộ) + 圣 (xe nhỏ chạy nhẹ nhàng)', 'Ghép 年 [bộ 干] + 轻 [bộ 车] để nhớ từ 年轻 (niánqīng): "trẻ tuổi".', '是的。张风给我们介绍了他的妈妈和弟弟，他爸爸不在家。阿姨很漂亮、很年轻，他弟弟也很可爱。他们都很热情地接待了我们。', 'Shì de. Zhāng Fēng gěi wǒmen jièshào le tā de māma hé dìdi, tā bàba bú zàijiā. Āyí hěn piàoliang, hěn niánqīng, tā dìdi yě hěn kě''ài. Tāmen dōu hěn rèqíng de jiēdài le wǒmen.', 'Đúng rồi. Trương Phong giới thiệu mẹ và em trai cậu ấy cho bọn tớ, bố cậu ấy không có ở nhà. Cô ấy rất xinh đẹp và trẻ trung, em trai cậu ấy cũng rất đáng yêu. Mọi người đều tiếp đón bọn tớ rất nhiệt tình.', 25) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v12_26', 'lesson-12', '有点儿', 'yǒudiǎnr', 'hữu điểm nhi', 'hơi hơi, có hơi', 'Phó từ', '月 (Nguyệt/Nhục) (Mặt trăng hoặc các bộ phận thân thể người)', '有: 𠂇 (bàn tay) + 月 (Nguyệt/Nhục: cầm miếng thịt là có) • 点: 占 (Chiếm) + 灬 (Hỏa: ngọn lửa chấm sáng) • 儿: Bộ 儿 (Nhi - nét cong, chữ độc thể)', 'Ghép 有 [bộ 月] + 点 [bộ 灬] + 儿 [bộ 儿] để nhớ từ 有点儿 (yǒudiǎnr): "hơi hơi, có hơi".', '我也有点儿不好意思，但是张风和他家人都很欢迎我们。阿姨给我们准备了很多好吃的，有茶、咖啡、牛肉、鱼、水果等等。', 'Wǒ yě yǒudiǎnr bù hǎoyìsi, dànshì Zhāng Fēng hé tā jiārén dōu hěn huānyíng wǒmen. Āyí gěi wǒmen zhǔnbèi le hěnduō hǎo chī de, yǒu chá, kāfēi, niúròu, yú, shuǐguǒ děng děng.', 'Tớ cũng hơi ngại một chút, nhưng Trương Phong và gia đình cậu ấy rất hoan nghênh bọn tớ. Cô ấy chuẩn bị cho bọn tớ rất nhiều đồ ngon, nào là trà, cà phê, thịt bò, cá, hoa quả, v.v.', 26) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v12_27', 'lesson-12', '还是', 'háishi', 'hoàn thị', 'hay là (thường dùng trong câu hỏi)', 'Phó từ / Liên từ', '辶 (Sước) (Bước đi, di chuyển, khoảng cách)', '还: 不 (Bất) + 辶 (Sước: quay đi rồi vẫn quay lại) • 是: 日 (Nhật: sáng rõ) + 𤴓 (biến thể của 正/疋: ngay thẳng)', 'Ghép 还 [bộ 辶] + 是 [bộ 日] để nhớ từ 还是 (háishi): "hay là (thường dùng trong câu hỏi)".', '你喜欢学汉语还是英语？', 'Nǐ xǐhuan xué Hànyǔ háishi Yīngyǔ?', 'Em thích học tiếng Trung hay tiếng Anh?', 27) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v12_28', 'lesson-12', '如果', 'rúguǒ', 'quả', 'nếu, nếu như', 'Liên từ', '女 (Nữ) (Phụ nữ, gia đình, tình cảm)', '如: 女 (Nữ) + 口 (Khẩu) • 果: 田 (Điền: trái tròn) + 木 (Mộc: trên ngọn cây)', 'Ghép 如 [bộ 女] + 果 [bộ 木] để nhớ từ 如果 (rúguǒ): "nếu, nếu như".', '你们不觉得紧张吗？如果是我，我就紧张死了。', 'Nǐmen bù juéde jǐnzhāng ma? Rúguǒ shì wǒ, wǒ jiù jǐnzhāng sǐle.', 'Các cậu không thấy hồi hộp à? Nếu là tớ chắc tớ hồi hộp chết mất.', 28) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v12_29', 'lesson-12', '……死了', '……sǐ le', 'từ Hán ngữ', 'chết, mất', 'Cụm từ / Tên riêng', '歹 (Ngạt) (Xấu xa, xương tàn, nguy hiểm)', '死: 一 + 歹 (Ngạt: xương tàn) + 匕 (Chủy) • 了: Bộ 亅 (Quyết - nét móc kết thúc, chữ độc thể)', 'Ghép 死 [bộ 歹] + 了 [bộ 亅] để nhớ từ ……死了 (……sǐ le): "chết, mất".', '你们不觉得紧张吗？如果是我，我就紧张死了。', 'Nǐmen bù juéde jǐnzhāng ma? Rúguǒ shì wǒ, wǒ jiù jǐnzhāng sǐle.', 'Các cậu không thấy hồi hộp à? Nếu là tớ chắc tớ hồi hộp chết mất.', 29) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v12_30', 'lesson-12', '不好意思', 'bù hǎo yìsi', 'hảo', 'ngại, ngượng ngùng, xấu hổ', 'Cụm từ / Tên riêng', '一 (Nhất) (Số một, nền tảng, nét ngang cơ bản)', '不: 一 (Nhất) + 丿 + 丨 + 丶 (chữ độc thể phủ định) • 好: 女 (Nữ: người mẹ) + 子 (Tử: đứa con) • 意: 音 (Âm: tiếng nói) + 心 (Tâm: ý nghĩ trong lòng) • 思: 田 (Điền: hộp sọ/não) + 心 (Tâm: trái tim suy nghĩ)', 'Ghép 不 [bộ 一] + 好 [bộ 女] + 意 [bộ 心] + 思 [bộ 心] để nhớ từ 不好意思 (bù hǎo yìsi): "ngại, ngượng ngùng, xấu hổ".', '我也有点儿不好意思，但是张风和他家人都很欢迎我们。阿姨给我们准备了很多好吃的，有茶、咖啡、牛肉、鱼、水果等等。', 'Wǒ yě yǒudiǎnr bù hǎoyìsi, dànshì Zhāng Fēng hé tā jiārén dōu hěn huānyíng wǒmen. Āyí gěi wǒmen zhǔnbèi le hěnduō hǎo chī de, yǒu chá, kāfēi, niúròu, yú, shuǐguǒ děng děng.', 'Tớ cũng hơi ngại một chút, nhưng Trương Phong và gia đình cậu ấy rất hoan nghênh bọn tớ. Cô ấy chuẩn bị cho bọn tớ rất nhiều đồ ngon, nào là trà, cà phê, thịt bò, cá, hoa quả, v.v.', 30) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order) VALUES ('g12_1', 'lesson-12', '1. 真', 'Cấu trúc câu ngữ pháp trọng tâm', ' - Là tính từ biểu thị ý nghĩa chân thật, thật. 那件事是真的。 Nà jiàn shì shì zhēn de. Việc đó là thật. 我真心真意想跟你去。 Wǒ zhēnxīn zhēnyì xiǎng gēn nǐ qù. Tôi thật lòng muốn đi cùng em. - Là phó từ dùng trước động từ hoặc tính từ, biểu thị sự khẳng định: thật s', NULL, '[{"hanzi":"那件事是真的。","pinyin":"Nà jiàn shì shì zhēn de.","meaning":"Việc đó là thật."},{"hanzi":"我真心真意想跟你去。","pinyin":"Wǒ zhēnxīn zhēnyì xiǎng gēn nǐ qù.","meaning":"Tôi thật lòng muốn đi cùng em."}]'::jsonb, 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order) VALUES ('g12_2', 'lesson-12', '2. 还是', 'Cấu trúc câu ngữ pháp trọng tâm', ' a. A 还是 B: A hay là B? - 还是 được dùng trong câu nghi vấn để biểu thị sự lựa chọn A hay là B. - Trong đó hai thành phần A và B thường tương đương với nhau về chức năng, kết cấu... có thể cùng là vị ngữ, tân ngữ, chủ ngữ hoặc trạng ngữ. 你喜欢学汉语还是英语？ Nǐ', NULL, '[{"hanzi":"他这个人真好！","pinyin":"Tā zhège rén zhēn hǎo!","meaning":"Con người anh ta thật là tốt!"},{"hanzi":"我真不喜欢！","pinyin":"Wǒ zhēn bù xǐhuan!","meaning":"Tôi thực sự không thích!"}]'::jsonb, 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order) VALUES ('g12_3', 'lesson-12', '3. “就” 和 “才” - 就 và 才', 'Cấu trúc câu ngữ pháp trọng tâm', ' a. Phó từ 就 Biểu thị hành vi, động tác, sự việc diễn ra, phát sinh nhanh hoặc sớm. 他上个星期就回国了。 Tā shàng gè xīngqī jiù huí guó le. Anh ấy đã về nước từ tuần trước rồi. 从我家走路到学校，五分钟就到。 Cóng wǒ jiā zǒulù dào xuéxiào, wǔ fēnzhōng jiù dào. Đi bộ từ nhà tô', NULL, '[{"hanzi":"你喜欢学汉语还是英语？","pinyin":"Nǐ xǐhuan xué Hànyǔ háishi Yīngyǔ?","meaning":"Em thích học tiếng Trung hay tiếng Anh?"},{"hanzi":"这个会议，你去还是小明去？","pinyin":"Zhège huìyì, nǐ qù háishi Xiǎomíng qù?","meaning":"Hội nghị này, cậu đi hay Minh đi?"}]'::jsonb, 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order) VALUES ('g12_4', 'lesson-12', '1. 生日 shēngrì dt. sinh nhật', 'Cấu trúc câu ngữ pháp trọng tâm', 'Quy tắc ngữ pháp quan trọng trong Tiếp đãi khách.', NULL, '[{"hanzi":"你今年去留学还是明年去？","pinyin":"Nǐ jīnnián qù liúxué háishi míngnián qù?","meaning":"Năm nay hay năm sau cậu đi du học?"},{"hanzi":"A: 中村是中国人还是日本人？","pinyin":"Zhōngcūn shì Zhōngguó rén háishi Rìběn rén?","meaning":"Nakamura là người Trung Quốc hay người Nhật Bản?"}]'::jsonb, 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order;
INSERT INTO texts (id, lesson_id, title, description, sort_order) VALUES ('txt_12_1', 'lesson-12', 'Bài khoá #1: Hội thoại giáo trình — Tiếp đãi khách', 'Hội thoại chuẩn giáo trình Bài 12. Từ vựng chưa học được chú thích phiên âm & nghĩa trong ngoặc.', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_12_1_1', 'txt_12_1', '范玉兰', '昨天你去哪儿了？我到你的宿舍但是没见到你。', '昨天你去哪儿了？我到你的宿舍但是没 (méi: chưa, không có)见到你。', 'Zuótiān nǐ qù nǎr le? Wǒ dào nǐ de sùshè dànshì méi jiàn dào nǐ.', 'Hôm qua cậu đi đâu thế? Tớ qua ký túc xá của cậu nhưng không gặp được cậu.', 1) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_12_1_2', 'txt_12_1', '阮日明', '你问上午还是下午？上午六点我去图书馆学习，下午跟 山本同学、马克同学到张风家。', '你问上午还是下午？上午六点我去图书馆学习 (xuéxí: học tập)，下午跟 (gēn: cùng, với) 山本 (Shānběn: Yamamoto)同学、马克同学到张风家。', 'Nǐ wèn shàngwǔ háishi xiàwǔ? Shàngwǔ liù diǎn wǒ qù túshūguǎn xuéxí, xiàwǔ gēn Shānběn tóngxué, Mǎkè tóngxué dào Zhāng Fēng jiā.', 'Cậu hỏi buổi sáng hay buổi chiều? 6 giờ sáng tớ đi thư viện học, buổi chiều cùng bạn Yamamoto và bạn Mark đến nhà Trương Phong.', 2) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_12_1_3', 'txt_12_1', '范玉兰', '你们到他家聚会还是有什么事？', '你们到他家聚会还是有什么事 (shì: việc, chuyện)？', 'Nǐmen dào tā jiā jùhuì háishi yǒu shénme shì?', 'Các cậu đến nhà cậu ấy tụ tập hay có việc gì thế?', 3) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_12_1_4', 'txt_12_1', '阮日明', '张风请我们去他家做客。', '张风请我们去他家做客。', 'Zhāng Fēng qǐng wǒmen qù tā jiā zuòkè.', 'Trương Phong mời bọn tớ đến nhà cậu ấy chơi.', 4) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_12_1_5', 'txt_12_1', '范玉兰', '那么你一定见到他的家人了吧？他们怎么样？', '那么你一定 (yīdìng: nhất định)见到他的家人 (jiārén: người nhà)了吧？他们怎么样？', 'Nàme nǐ yídìng jiàn dào tā de jiārén le ba? Tāmen zěnmeyàng?', 'Vậy chắc cậu đã gặp người nhà cậu ấy rồi nhỉ? Họ thế nào?', 5) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_12_1_6', 'txt_12_1', '阮日明', '是的。张风给我们介绍了他的妈妈和弟弟，他爸爸不在家。阿姨很漂亮、很年轻，他弟弟也很可爱。他们都很热情地接待了我们。', '是的。张风给我们介绍了他的妈妈和弟弟，他爸爸不 (bù: không)在家。阿姨很漂亮、很年轻，他弟弟也很可爱。他们都很热情地 (de: liên kết trạng từ và trung t)接待了我们。', 'Shì de. Zhāng Fēng gěi wǒmen jièshào le tā de māma hé dìdi, tā bàba bú zàijiā. Āyí hěn piàoliang, hěn niánqīng, tā dìdi yě hěn kě''ài. Tāmen dōu hěn rèqíng de jiēdài le wǒmen.', 'Đúng rồi. Trương Phong giới thiệu mẹ và em trai cậu ấy cho bọn tớ, bố cậu ấy không có ở nhà. Cô ấy rất xinh đẹp và trẻ trung, em trai cậu ấy cũng rất đáng yêu. Mọi người đều tiếp đón bọn tớ rất nhiệt tình.', 6) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_12_1_7', 'txt_12_1', '范玉兰', '你们不觉得紧张吗？如果是我，我就紧张死了。', '你们不 (bù: không)觉得紧张吗？如果是我，我就紧张死了。', 'Nǐmen bù juéde jǐnzhāng ma? Rúguǒ shì wǒ, wǒ jiù jǐnzhāng sǐle.', 'Các cậu không thấy hồi hộp à? Nếu là tớ chắc tớ hồi hộp chết mất.', 7) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_12_1_8', 'txt_12_1', '阮日明', '我也有点儿不好意思，但是张风和他家人都很欢迎我们。阿姨给我们准备了很多好吃的，有茶、咖啡、牛肉、鱼、水果等等。', '我也有点儿不好意思，但是张风和他家人 (jiārén: người nhà)都很欢迎我们。阿姨给我们准备了很多好吃的，有茶、咖啡、牛肉、鱼、水果等等。', 'Wǒ yě yǒudiǎnr bù hǎoyìsi, dànshì Zhāng Fēng hé tā jiārén dōu hěn huānyíng wǒmen. Āyí gěi wǒmen zhǔnbèi le hěnduō hǎo chī de, yǒu chá, kāfēi, niúròu, yú, shuǐguǒ děng děng.', 'Tớ cũng hơi ngại một chút, nhưng Trương Phong và gia đình cậu ấy rất hoan nghênh bọn tớ. Cô ấy chuẩn bị cho bọn tớ rất nhiều đồ ngon, nào là trà, cà phê, thịt bò, cá, hoa quả, v.v.', 8) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_12_1_9', 'txt_12_1', '范玉兰', '哇！她真好！你们在他家做什么了？', '哇 (wa: oa, chà (cảm thán))！她真好！你们在他家做 (zuò: làm)什么了？', 'Wa! Tā zhēn hǎo! Nǐmen zài tā jiā zuò shénme le?', 'Chà! Cô ấy tốt thật đấy! Các cậu đã làm gì ở nhà cậu ấy?', 9) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_12_1_10', 'txt_12_1', '阮日明', '打游戏、听音乐、聊天儿、喝 水、吃东西。到十点半我们才回宿舍。现在回想起来，昨天真快乐，真热闹。', '打游戏、听音乐、聊天儿、喝 水、吃东西。到十点半我们才 (cái: mới)回宿舍。现在回想起来 (qǐlái: lên (bổ ngữ))，昨天真快乐，真热闹。', 'Dǎ yóuxì, tīng yīnyuè, liáotiānr, hē shuǐ, chī dōngxi. Dào shí diǎn bàn wǒmen cái huí sùshè. Xiànzài huíxiǎng qǐlai, zuótiān zhēn kuàilè, zhēn rènao.', 'Chơi game, nghe nhạc, trò chuyện, uống nước, ăn uống. Đến 10 giờ rưỡi bọn tớ mới về ký túc xá. Giờ nhớ lại, hôm qua thật vui và náo nhiệt.', 10) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_12_1_11', 'txt_12_1', '范玉兰', '我也想去啊。你们怎么不叫我一起去？', '我也想去啊。你们怎么不 (bù: không)叫我一起去？', 'Wǒ yě xiǎng qù a. Nǐmen zěnme bú jiào wǒ yīqǐ qù?', 'Tớ cũng muốn đi mà. Sao các cậu không rủ tớ đi cùng?', 11) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_12_1_12', 'txt_12_1', '阮日明', '昨天上午山本才说他可以去，所以到那个时候我们才决定去!等下次吧！下次去玩儿我就跟你说。', '昨天上午山本 (Shānběn: Yamamoto)才 (cái: mới)说他可以去，所以 (suǒyǐ: cho nên)到那个时候我们才决定去!等下次吧！下次去玩儿我就跟 (gēn: cùng, với)你说。', 'Zuótiān shàngwǔ Shānběn cái shuō tā kěyǐ qù, suǒyǐ dào nàge shíhou wǒmen cái juédìng qù! Děng xià cì ba! Xià cì qù wánr wǒ jiù gēn nǐ shuō.', 'Sáng hôm qua Yamamoto mới nói có thể đi, nên lúc đó bọn tớ mới quyết định đi! Đợi lần sau nhé! Lần sau đi chơi tớ sẽ rủ cậu.', 12) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_12_1_13', 'txt_12_1', '范玉兰', '好，下次一定要叫我啊！', '好，下次一定 (yīdìng: nhất định)要叫我啊！', 'Hǎo, xià cì yídìng yào jiào wǒ a!', 'Được, lần sau nhất định phải gọi tớ nhé!', 13) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_12_1_1', 'lesson-12', 'txt_12_1', 'listening', 'listening', '昨天你去哪儿了？我到你的宿舍但是没见到你。', NULL, 'Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Hôm qua cậu đi đâu thế? Tớ qua ký túc xá của cậu nhưng không gặp được cậu.","Phòng của thầy Vương là số mấy?","Lan vừa cãi nhau với bạn.","Tôi là Trần Anh."]'::jsonb, 0, 'Nội dung nghe được: 昨天你去哪儿了？我到你的宿舍但是没见到你。 (Zuótiān nǐ qù nǎr le? Wǒ dào nǐ de sùshè dànshì méi jiàn dào nǐ.) → Hôm qua cậu đi đâu thế? Tớ qua ký túc xá của cậu nhưng không gặp được cậu.', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_12_1_2', 'lesson-12', 'txt_12_1', 'listening', 'listening', '你问上午还是下午？上午六点我去图书馆学习，下午跟 山本同学、马克同学到张风家。', NULL, 'Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["你问上午还是下午？上午六点我去图书馆学习 (xuéxí: học tập)，下午跟 (gēn: cùng, với) 山本 (Shānběn: Yamamoto)同学、马克同学到张风家。","那么你一定 (yīdìng: nhất định)见到他的家人 (jiārén: người nhà)了吧？他们怎么样？","我真不 (bù: không)喜欢！","从我家走路 (zǒulù: đi bộ)到学校，五分钟就到。"]'::jsonb, 0, 'Câu vừa đọc: 你问上午还是下午？上午六点我去图书馆学习，下午跟 山本同学、马克同学到张风家。 (Nǐ wèn shàngwǔ háishi xiàwǔ? Shàngwǔ liù diǎn wǒ qù túshūguǎn xuéxí, xiàwǔ gēn Shānběn tóngxué, Mǎkè tóngxué dào Zhāng Fēng jiā.) → Cậu hỏi buổi sáng hay buổi chiều? 6 giờ sáng tớ đi thư viện học, buổi chiều cùng bạn Yamamoto và bạn Mark đến nhà Trương Phong.', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_12_1_3', 'lesson-12', 'txt_12_1', 'listening', 'listening', '你们到他家聚会还是有什么事？', NULL, 'Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Các cậu đến nhà cậu ấy tụ tập hay có việc gì thế?","Hôm qua cậu đi đâu thế? Tớ qua ký túc xá của cậu nhưng không gặp được cậu.","Năm nay cháu mấy tuổi rồi (Hỏi trẻ em dưới mười tuổi)","ba cây bút chì"]'::jsonb, 0, 'Nội dung nghe được: 你们到他家聚会还是有什么事？ (Nǐmen dào tā jiā jùhuì háishi yǒu shénme shì?) → Các cậu đến nhà cậu ấy tụ tập hay có việc gì thế?', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_12_1_4', 'lesson-12', 'txt_12_1', 'listening', 'listening', '张风请我们去他家做客。', NULL, 'Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["他这个人真好！","妈妈做 (zuò: làm)了一盘很好吃的牛肉和鱼。","你喜欢学 (xué: học)汉语还是英语 (Yīngyǔ: tiếng Anh)？","张风请我们去他家做客。"]'::jsonb, 3, 'Câu vừa đọc: 张风请我们去他家做客。 (Zhāng Fēng qǐng wǒmen qù tā jiā zuòkè.) → Trương Phong mời bọn tớ đến nhà cậu ấy chơi.', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO texts (id, lesson_id, title, description, sort_order) VALUES ('txt_12_2', 'lesson-12', 'Bài nghe tổng hợp: Ôn tập lũy tiến (Bài 1 – Bài 12)', 'Kết hợp từ vựng & mẫu câu đã học từ Bài 1 đến Bài 11 cùng trọng tâm Bài 12 để củng cố phản xạ nghe.', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_12_2_1', 'txt_12_2', 'Ôn Bài 11', '他在吃饭呢。', '他在吃饭呢。', 'Tā zài chīfàn ne.', 'Anh ấy đang ăn cơm kìa.', 1) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_12_2_2', 'txt_12_2', 'Bài 12', '他这个人真好！', '他这个人真好！', 'Tā zhège rén zhēn hǎo!', 'Con người anh ta thật là tốt!', 2) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_12_2_3', 'txt_12_2', 'Ôn Bài 6', 'A: 你怎么去超市呢？', 'A: 你怎么去超市呢？', 'Nǐ zěnme qù chāoshì ne?', 'Cậu đi gì đến siêu thị thế?', 3) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_12_2_4', 'txt_12_2', 'Bài 12', '张风请我们去他家做客。', '张风请我们去他家做客。', 'Zhāng Fēng qǐng wǒmen qù tā jiā zuòkè.', 'Trương Phong mời bọn tớ đến nhà cậu ấy chơi.', 4) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_12_2_5', 'txt_12_2', 'Ôn Bài 1', '晚上好！', '晚上好！', 'Wǎnshang hǎo', 'Chào buổi tối!', 5) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_12_2_6', 'txt_12_2', 'Bài 12', '我真不喜欢！', '我真不 (bù: không)喜欢！', 'Wǒ zhēn bù xǐhuan!', 'Tôi thực sự không thích!', 6) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_12_2_7', 'txt_12_2', 'Ôn Bài 9', '你买吧！', '你买吧！', 'Nǐ mǎi ba!', 'Cậu mua đi!', 7) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_12_2_8', 'txt_12_2', 'Bài 12', 'B: 他是日本人。', 'B: 他是日 (rì: ngày)本人。', 'Tā shì Rìběn rén.', 'Cậu ấy là người Nhật Bản.', 8) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_12_2_1', 'lesson-12', 'txt_12_2', 'listening', 'listening', '他在吃饭呢。', NULL, '[Ôn tập Bài 11] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Anh ấy đang ăn cơm kìa.","Trương Hồng là giáo viên à?","Một bộ quần áo","hai quyển sách"]'::jsonb, 0, 'Nội dung nghe được: 他在吃饭呢。 (Tā zài chīfàn ne.) → Anh ấy đang ăn cơm kìa.', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_12_2_2', 'lesson-12', 'txt_12_2', 'listening', 'listening', '他这个人真好！', NULL, '[Bài 12] Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["张风请我们去他家做客。","他这个人真好！","这个会 (huì: Phó, đtnn biết)议，你去还是小 (xiǎo: nhỏ, bé)明 (míng: ngày mai, sáng)去？","我喜欢一边 (biān: bên, phía)喝水一边听音乐。"]'::jsonb, 1, 'Câu vừa đọc: 他这个人真好！ (Tā zhège rén zhēn hǎo!) → Con người anh ta thật là tốt!', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_12_2_3', 'lesson-12', 'txt_12_2', 'listening', 'listening', 'A: 你怎么去超市呢？', NULL, '[Ôn tập Bài 6] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Thời tiết dễ chịu quá!","Anh ấy đang nghe nhạc.","Cậu ấy là người cao nhất trong lớp.","Cậu đi gì đến siêu thị thế?"]'::jsonb, 3, 'Nội dung nghe được: A: 你怎么去超市呢？ (Nǐ zěnme qù chāoshì ne?) → Cậu đi gì đến siêu thị thế?', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_12_2_4', 'lesson-12', 'txt_12_2', 'listening', 'listening', '张风请我们去他家做客。', NULL, '[Bài 12] Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["下次我们再 (zài: lại)一起聊天儿吧！","我不 (bù: không)知道这个人是男 (nán: nam)的还是女 (nǚ: nữ)的。","张风请我们去他家做客。","你今 (jīn: hôm nay, nay)年去留学 (liúxué: du học)还是明年 (míngnián: năm sau)去？"]'::jsonb, 2, 'Câu vừa đọc: 张风请我们去他家做客。 (Zhāng Fēng qǐng wǒmen qù tā jiā zuòkè.) → Trương Phong mời bọn tớ đến nhà cậu ấy chơi.', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_12_2_5', 'lesson-12', 'txt_12_2', 'listening', 'listening', '晚上好！', NULL, '[Ôn tập Bài 1] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Chào buổi tối!","Anh ấy là ai?","Mời uống một tách trà nóng hoặc cà phê nhé.","Tôi không hay (không thường) liên lạc với Lý Quân."]'::jsonb, 0, 'Nội dung nghe được: 晚上好！ (Wǎnshang hǎo) → Chào buổi tối!', 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO texts (id, lesson_id, title, description, sort_order) VALUES ('txt_12_3', 'lesson-12', 'Bài khoá mở rộng: Đón bạn đến chơi nhà cuối tuần (Mở rộng)', 'Hội thoại tình huống mới xây dựng dựa trên từ vựng và ngữ pháp Bài 12 (không trùng lặp nguyên văn giáo trình).', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_12_3_1', 'txt_12_3', 'Phong', '欢迎大家来我家做客！快请坐！', '欢迎大家 (dàjiā: mọi người)来 (lái: đến)我家做客！快 (kuài: nhanh)请坐 (zuò: ngồi)！', 'Huānyíng dàjiā lái wǒ jiā zuòkè! Kuài qǐng zuò!', 'Chào mừng mọi người đến nhà mình chơi! Mời ngồi tự nhiên nhé!', 1) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_12_3_2', 'txt_12_3', 'Lan', '谢谢你和阿姨这么热情地接待我们。', '谢谢你和阿姨这么热情地 (de: liên kết trạng từ và trung t)接待我们。', 'Xièxie nǐ hé āyí zhème rèqíng de jiēdài wǒmen.', 'Cảm ơn cậu và cô đã tiếp đón bọn mình nhiệt tình thế này.', 2) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_12_3_3', 'txt_12_3', 'Phong', '你们想喝茶还是咖啡？这里还有水果和牛肉。', '你们想喝茶还是咖啡？这里 (lǐ: trong)还有水果和牛肉。', 'Nǐmen xiǎng hē chá háishi kāfēi? Zhèlǐ hái yǒu shuǐguǒ hé niúròu.', 'Các cậu muốn uống trà hay cà phê? Ở đây còn có hoa quả và thịt bò nữa.', 3) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_12_3_4', 'txt_12_3', 'Lan', '我要一杯热茶吧。吃饱了我们一起听音乐、聊天儿！', '我要一杯热 (rè: nóng)茶吧。吃饱 (bǎo: no)了我们一起听音乐、聊天儿！', 'Wǒ yào yì bēi rè chá ba. Chībǎo le wǒmen yīqǐ tīng yīnyuè, liáotiānr!', 'Cho mình một tách trà nóng nhé. Ăn xong chúng ta cùng nghe nhạc và trò chuyện!', 4) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_12_3_1', 'lesson-12', 'txt_12_3', 'listening', 'listening', '欢迎大家来我家做客！快请坐！ 谢谢你和阿姨这么热情地接待我们。 你们想喝茶还是咖啡？这里还有水果和牛肉。 我要一杯热茶吧。吃饱了我们一起听音乐、聊天儿！', NULL, '[Nghe hiểu tình huống mới] Lan chọn đồ uống gì khi đến nhà Trương Phong làm khách?', '["Một ly cà phê đá","Một ly sữa tươi","Một cốc nước ép táo","Một tách trà nóng (热茶)"]'::jsonb, 3, 'Lan trả lời ''我要一杯热茶吧'' (một tách trà nóng).', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_12_3_2', 'lesson-12', 'txt_12_3', 'listening', 'listening', '欢迎大家来我家做客！快请坐！', NULL, '[Mở rộng] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Hoan nghênh các vị khách đến chơi nhà tôi!","Chào buổi sáng!","Chào mừng mọi người đến nhà mình chơi! Mời ngồi tự nhiên nhé!","Anh ta là người chẳng ra gì."]'::jsonb, 2, 'Nội dung nghe được: 欢迎大家来我家做客！快请坐！ (Huānyíng dàjiā lái wǒ jiā zuòkè! Kuài qǐng zuò!) → Chào mừng mọi người đến nhà mình chơi! Mời ngồi tự nhiên nhé!', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_12_3_3', 'lesson-12', 'txt_12_3', 'listening', 'listening', '谢谢你和阿姨这么热情地接待我们。', NULL, '[Mở rộng] Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["那件 (jiàn: cái, chiếc (áo, việc))事 (shì: việc, chuyện)是真的。","谢谢你和阿姨这么热情地 (de: liên kết trạng từ và trung t)接待我们。","你问上午还是下午？上午六点我去图书馆学习 (xuéxí: học tập)，下午跟 (gēn: cùng, với) 山本 (Shānběn: Yamamoto)同学、马克同学到张风家。","我喜欢一边 (biān: bên, phía)喝水一边听音乐。"]'::jsonb, 1, 'Câu vừa đọc: 谢谢你和阿姨这么热情地接待我们。 (Xièxie nǐ hé āyí zhème rèqíng de jiēdài wǒmen.) → Cảm ơn cậu và cô đã tiếp đón bọn mình nhiệt tình thế này.', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_12_3_4', 'lesson-12', 'txt_12_3', 'listening', 'listening', '你们想喝茶还是咖啡？这里还有水果和牛肉。', NULL, '[Mở rộng] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Không sớm cũng không muộn, rất đúng giờ!","đứa bé vô cùng","Các cậu muốn uống trà hay cà phê? Ở đây còn có hoa quả và thịt bò nữa.","Tôi so sánh đáp án với anh ấy."]'::jsonb, 2, 'Nội dung nghe được: 你们想喝茶还是咖啡？这里还有水果和牛肉。 (Nǐmen xiǎng hē chá háishi kāfēi? Zhèlǐ hái yǒu shuǐguǒ hé niúròu.) → Các cậu muốn uống trà hay cà phê? Ở đây còn có hoa quả và thịt bò nữa.', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss12_1', 'lesson-12', '请喝一杯热茶或者咖啡吧', '[Mở rộng] Mời uống một tách trà nóng hoặc cà phê nhé.', 'Qǐng hē yì bēi rè chá huòzhě kāfēi ba.', '["请喝","一杯","热茶","或者","咖啡","吧"]'::jsonb, 'Từ chưa học: 热 (rè: nóng)', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss12_2', 'lesson-12', '爸爸热情地接待了我的同学', '[Mở rộng] Bố tôi đã tiếp đón bạn học của tôi rất nhiệt tình.', 'Bàba rèqíng de jiēdài le wǒ de tóngxué.', '["爸爸","热情","地","接待了","我的","同学"]'::jsonb, 'Từ chưa học: 地 (de: liên kết trạng từ và trung t)', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
