INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss12_5', 'lesson-12', '马路北边有一个大书店', '[Ôn tập Bài 6] Phía bắc con đường có một hiệu sách lớn.', 'Mǎlù běibian yǒu yígè dà shūdiàn.', '["马路","北边","有一","个","大","书店"]'::jsonb, 'Từ chưa học: 大 (dà: to, lớn)', 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss12_6', 'lesson-12', '教学楼在图书馆的左边', '[Ôn tập Bài 4] Tòa nhà giảng đường nằm ở bên trái thư viện.', 'Jiàoxué lóu zài túshūguǎn de zuǒbian.', '["教学楼","在","图书馆","的","左边"]'::jsonb, NULL, 6) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss12_exp_1', 'lesson-12', '昨天你去哪儿了我到你的宿舍但是没见到你', 'Hôm qua cậu đi đâu thế? Tớ qua ký túc xá của cậu nhưng không gặp được cậu.', 'Zuótiān nǐ qù nǎr le? Wǒ dào nǐ de sùshè dànshì méi jiàn dào nǐ.', '["昨天","你","去","哪儿","了","我","到","你","的","宿舍","但是","没","见","到","你"]'::jsonb, NULL, 7) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss12_exp_2', 'lesson-12', '你问上午还是下午上午六点我去图书馆学习下午跟山本同学马克同学到张风家', 'Cậu hỏi buổi sáng hay buổi chiều? 6 giờ sáng tớ đi thư viện học, buổi chiều cùng bạn Yamamoto và bạn Mark đến nhà Trương Phong.', 'Nǐ wèn shàngwǔ háishi xiàwǔ? Shàngwǔ liù diǎn wǒ qù túshūguǎn xuéxí, xiàwǔ gēn Shānběn tóngxué, Mǎkè tóngxué dào Zhāng Fēng jiā.', '["你","问","上午","还是","下午","上午","六","点","我","去","图书馆","学","习","下午","跟","山","本","同学","马克","同学","到","张风","家"]'::jsonb, NULL, 8) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss12_exp_3', 'lesson-12', '你们到他家聚会还是有什么事', 'Các cậu đến nhà cậu ấy tụ tập hay có việc gì thế?', 'Nǐmen dào tā jiā jùhuì háishi yǒu shénme shì?', '["你们","到","他","家","聚会","还是","有","什么","事"]'::jsonb, NULL, 9) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss12_exp_4', 'lesson-12', '那么你一定见到他的家人了吧他们怎么样', 'Vậy chắc cậu đã gặp người nhà cậu ấy rồi nhỉ? Họ thế nào?', 'Nàme nǐ yídìng jiàn dào tā de jiārén le ba? Tāmen zěnmeyàng?', '["那么","你","一","定","见","到","他","的","家","人","了","吧","他们","怎么样"]'::jsonb, NULL, 10) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss12_exp_5', 'lesson-12', '是的张风给我们介绍了他的妈妈和弟弟他爸爸不在家阿姨很漂亮很年轻他弟弟也很可爱他们都很热情地接待了我们', 'Đúng rồi. Trương Phong giới thiệu mẹ và em trai cậu ấy cho bọn tớ, bố cậu ấy không có ở nhà. Cô ấy rất xinh đẹp và trẻ trung, em trai cậu ấy cũng rất đáng yêu. Mọi người đều tiếp đón bọn tớ rất nhiệt tình.', 'Shì de. Zhāng Fēng gěi wǒmen jièshào le tā de māma hé dìdi, tā bàba bú zàijiā. Āyí hěn piàoliang, hěn niánqīng, tā dìdi yě hěn kě''ài. Tāmen dōu hěn rèqíng de jiēdài le wǒmen.', '["是","的","张风","给","我们","介绍","了","他","的","妈妈","和","弟弟","他","爸爸","不","在","家","阿姨","很","漂亮","很","年轻","他","弟弟","也","很","可爱","他们","都","很","热情","地","接待","了","我们"]'::jsonb, NULL, 11) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss12_exp_6', 'lesson-12', '你们不觉得紧张吗如果是我我就紧张死了', 'Các cậu không thấy hồi hộp à? Nếu là tớ chắc tớ hồi hộp chết mất.', 'Nǐmen bù juéde jǐnzhāng ma? Rúguǒ shì wǒ, wǒ jiù jǐnzhāng sǐle.', '["你们","不","觉得","紧张","吗","如果","是","我","我","就","紧张","死了"]'::jsonb, NULL, 12) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss12_exp_7', 'lesson-12', '我也有点儿不好意思但是张风和他家人都很欢迎我们阿姨给我们准备了很多好吃的有茶咖啡牛肉鱼水果等等', 'Tớ cũng hơi ngại một chút, nhưng Trương Phong và gia đình cậu ấy rất hoan nghênh bọn tớ. Cô ấy chuẩn bị cho bọn tớ rất nhiều đồ ngon, nào là trà, cà phê, thịt bò, cá, hoa quả, v.v.', 'Wǒ yě yǒudiǎnr bù hǎoyìsi, dànshì Zhāng Fēng hé tā jiārén dōu hěn huānyíng wǒmen. Āyí gěi wǒmen zhǔnbèi le hěnduō hǎo chī de, yǒu chá, kāfēi, niúròu, yú, shuǐguǒ děng děng.', '["我","也","有点儿","不好意思","但是","张风","和","他","家","人","都","很","欢迎","我们","阿姨","给","我们","准备","了","很","多","好吃","的","有","茶","咖啡","牛肉","鱼","水果","等等"]'::jsonb, NULL, 13) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss12_exp_8', 'lesson-12', '哇她真好你们在他家做什么了', 'Chà! Cô ấy tốt thật đấy! Các cậu đã làm gì ở nhà cậu ấy?', 'Wa! Tā zhēn hǎo! Nǐmen zài tā jiā zuò shénme le?', '["哇","她","真","好","你们","在","他","家","做","什么","了"]'::jsonb, NULL, 14) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss12_exp_9', 'lesson-12', '打游戏听音乐聊天儿喝水吃东西到十点半我们才回宿舍现在回想起来昨天真快乐真热闹', 'Chơi game, nghe nhạc, trò chuyện, uống nước, ăn uống. Đến 10 giờ rưỡi bọn tớ mới về ký túc xá. Giờ nhớ lại, hôm qua thật vui và náo nhiệt.', 'Dǎ yóuxì, tīng yīnyuè, liáotiānr, hē shuǐ, chī dōngxi. Dào shí diǎn bàn wǒmen cái huí sùshè. Xiànzài huíxiǎng qǐlai, zuótiān zhēn kuàilè, zhēn rènao.', '["打游戏","听音乐","聊天儿","喝","水","吃","东西","到","十","点","半","我们","才","回","宿舍","现在","回","想","起","来","昨天","真","快乐","真","热闹"]'::jsonb, NULL, 15) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss12_exp_10', 'lesson-12', '我也想去啊你们怎么不叫我一起去', 'Tớ cũng muốn đi mà. Sao các cậu không rủ tớ đi cùng?', 'Wǒ yě xiǎng qù a. Nǐmen zěnme bú jiào wǒ yīqǐ qù?', '["我","也","想","去","啊","你们","怎么","不","叫","我","一起","去"]'::jsonb, NULL, 16) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss12_exp_11', 'lesson-12', '昨天上午山本才说他可以去所以到那个时候我们才决定去等下次吧下次去玩儿我就跟你说', 'Sáng hôm qua Yamamoto mới nói có thể đi, nên lúc đó bọn tớ mới quyết định đi! Đợi lần sau nhé! Lần sau đi chơi tớ sẽ rủ cậu.', 'Zuótiān shàngwǔ Shānběn cái shuō tā kěyǐ qù, suǒyǐ dào nàge shíhou wǒmen cái juédìng qù! Děng xià cì ba! Xià cì qù wánr wǒ jiù gēn nǐ shuō.', '["昨天","上午","山","本","才","说","他","可以","去","所以","到","那","个","时候","我们","才","决定","去","等","下次","吧","下次","去","玩儿","我","就","跟","你","说"]'::jsonb, NULL, 17) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss12_exp_12', 'lesson-12', '好下次一定要叫我啊', 'Được, lần sau nhất định phải gọi tớ nhé!', 'Hǎo, xià cì yídìng yào jiào wǒ a!', '["好","下次","一","定","要","叫","我","啊"]'::jsonb, NULL, 18) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss12_exp_13', 'lesson-12', '他在吃饭呢', 'Anh ấy đang ăn cơm kìa.', 'Tā zài chīfàn ne.', '["他","在","吃","饭","呢"]'::jsonb, NULL, 19) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss12_exp_14', 'lesson-12', '你怎么去超市呢', 'Cậu đi gì đến siêu thị thế?', 'Nǐ zěnme qù chāoshì ne?', '["你","怎么","去","超市","呢"]'::jsonb, NULL, 20) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr12_vi_1', 'lesson-12', 'vi_to_zh', '[Mở rộng] Mời uống một tách trà nóng hoặc cà phê nhé.', NULL, NULL, '请喝一杯热茶或者咖啡吧。', NULL, 'qǐng hē yì bēi rè chá huòzhě kāfēi ba', '[]'::jsonb, 'Gợi ý Pinyin: Qǐng hē yì bēi rè chá huòzhě kāfēi ba. | Từ chưa học: 热 (rè: nóng)', 'Mời uống một tách trà nóng hoặc cà phê nhé. → 请喝一杯热茶或者咖啡吧。 (Qǐng hē yì bēi rè chá huòzhě kāfēi ba.)', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr12_vi_2', 'lesson-12', 'vi_to_zh', '[Mở rộng] Bố tôi đã tiếp đón bạn học của tôi rất nhiệt tình.', NULL, NULL, '爸爸热情地接待了我的同学。', NULL, 'bàba rèqíng de jiēdài le wǒ de tóngxué', '[]'::jsonb, 'Gợi ý Pinyin: Bàba rèqíng de jiēdài le wǒ de tóngxué. | Từ chưa học: 地 (de: liên kết trạng từ và trung t)', 'Bố tôi đã tiếp đón bạn học của tôi rất nhiệt tình. → 爸爸热情地接待了我的同学。 (Bàba rèqíng de jiēdài le wǒ de tóngxué.)', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr12_vi_3', 'lesson-12', 'vi_to_zh', 'Con người anh ta thật là tốt!', NULL, NULL, '他这个人真好！', NULL, 'tā zhège rén zhēn hǎo', '[]'::jsonb, 'Gợi ý Pinyin: Tā zhège rén zhēn hǎo!', 'Con người anh ta thật là tốt! → 他这个人真好！ (Tā zhège rén zhēn hǎo!)', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr12_vi_4', 'lesson-12', 'vi_to_zh', 'Tôi thực sự không thích!', NULL, NULL, '我真不喜欢！', NULL, 'wǒ zhēn bù xǐhuan', '[]'::jsonb, 'Gợi ý Pinyin: Wǒ zhēn bù xǐhuan! | Từ chưa học: 不 (bù: không)', 'Tôi thực sự không thích! → 我真不喜欢！ (Wǒ zhēn bù xǐhuan!)', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr12_vi_exp_1', 'lesson-12', 'vi_to_zh', 'Hôm qua cậu đi đâu thế? Tớ qua ký túc xá của cậu nhưng không gặp được cậu.', NULL, NULL, '昨天你去哪儿了？我到你的宿舍但是没见到你。', NULL, 'zuótiān nǐ qù nǎr le wǒ dào nǐ de sùshè dànshì méi jiàn dào nǐ', '[]'::jsonb, 'Gợi ý Pinyin: Zuótiān nǐ qù nǎr le? Wǒ dào nǐ de sùshè dànshì méi jiàn dào nǐ.', 'Hôm qua cậu đi đâu thế? Tớ qua ký túc xá của cậu nhưng không gặp được cậu. → 昨天你去哪儿了？我到你的宿舍但是没见到你。 (Zuótiān nǐ qù nǎr le? Wǒ dào nǐ de sùshè dànshì méi jiàn dào nǐ.)', 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr12_vi_exp_2', 'lesson-12', 'vi_to_zh', 'Cậu hỏi buổi sáng hay buổi chiều? 6 giờ sáng tớ đi thư viện học, buổi chiều cùng bạn Yamamoto và bạn Mark đến nhà Trương Phong.', NULL, NULL, '你问上午还是下午？上午六点我去图书馆学习，下午跟 山本同学、马克同学到张风家。', NULL, 'nǐ wèn shàngwǔ háishi xiàwǔ shàngwǔ liù diǎn wǒ qù túshūguǎn xuéxí xiàwǔ gēn shānběn tóngxué mǎkè tóngxué dào zhāng fēng jiā', '[]'::jsonb, 'Gợi ý Pinyin: Nǐ wèn shàngwǔ háishi xiàwǔ? Shàngwǔ liù diǎn wǒ qù túshūguǎn xuéxí, xiàwǔ gēn Shānběn tóngxué, Mǎkè tóngxué dào Zhāng Fēng jiā.', 'Cậu hỏi buổi sáng hay buổi chiều? 6 giờ sáng tớ đi thư viện học, buổi chiều cùng bạn Yamamoto và bạn Mark đến nhà Trương Phong. → 你问上午还是下午？上午六点我去图书馆学习，下午跟 山本同学、马克同学到张风家。 (Nǐ wèn shàngwǔ háishi xiàwǔ? Shàngwǔ liù diǎn wǒ qù túshūguǎn xuéxí, xiàwǔ gēn Shānběn tóngxué, Mǎkè tóngxué dào Zhāng Fēng jiā.)', 6) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr12_vi_exp_3', 'lesson-12', 'vi_to_zh', 'Các cậu đến nhà cậu ấy tụ tập hay có việc gì thế?', NULL, NULL, '你们到他家聚会还是有什么事？', NULL, 'nǐmen dào tā jiā jùhuì háishi yǒu shénme shì', '[]'::jsonb, 'Gợi ý Pinyin: Nǐmen dào tā jiā jùhuì háishi yǒu shénme shì?', 'Các cậu đến nhà cậu ấy tụ tập hay có việc gì thế? → 你们到他家聚会还是有什么事？ (Nǐmen dào tā jiā jùhuì háishi yǒu shénme shì?)', 7) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr12_vi_exp_4', 'lesson-12', 'vi_to_zh', 'Trương Phong mời bọn tớ đến nhà cậu ấy chơi.', NULL, NULL, '张风请我们去他家做客。', NULL, 'zhāng fēng qǐng wǒmen qù tā jiā zuòkè', '[]'::jsonb, 'Gợi ý Pinyin: Zhāng Fēng qǐng wǒmen qù tā jiā zuòkè.', 'Trương Phong mời bọn tớ đến nhà cậu ấy chơi. → 张风请我们去他家做客。 (Zhāng Fēng qǐng wǒmen qù tā jiā zuòkè.)', 8) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr12_vi_exp_5', 'lesson-12', 'vi_to_zh', 'Vậy chắc cậu đã gặp người nhà cậu ấy rồi nhỉ? Họ thế nào?', NULL, NULL, '那么你一定见到他的家人了吧？他们怎么样？', NULL, 'nàme nǐ yídìng jiàn dào tā de jiārén le ba tāmen zěnmeyàng', '[]'::jsonb, 'Gợi ý Pinyin: Nàme nǐ yídìng jiàn dào tā de jiārén le ba? Tāmen zěnmeyàng?', 'Vậy chắc cậu đã gặp người nhà cậu ấy rồi nhỉ? Họ thế nào? → 那么你一定见到他的家人了吧？他们怎么样？ (Nàme nǐ yídìng jiàn dào tā de jiārén le ba? Tāmen zěnmeyàng?)', 9) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr12_vi_exp_6', 'lesson-12', 'vi_to_zh', 'Đúng rồi. Trương Phong giới thiệu mẹ và em trai cậu ấy cho bọn tớ, bố cậu ấy không có ở nhà. Cô ấy rất xinh đẹp và trẻ trung, em trai cậu ấy cũng rất đáng yêu. Mọi người đều tiếp đón bọn tớ rất nhiệt tình.', NULL, NULL, '是的。张风给我们介绍了他的妈妈和弟弟，他爸爸不在家。阿姨很漂亮、很年轻，他弟弟也很可爱。他们都很热情地接待了我们。', NULL, 'shì de zhāng fēng gěi wǒmen jièshào le tā de māma hé dìdi tā bàba bú zàijiā āyí hěn piàoliang hěn niánqīng tā dìdi yě hěn kě ài tāmen dōu hěn rèqíng de jiēdài le wǒmen', '[]'::jsonb, 'Gợi ý Pinyin: Shì de. Zhāng Fēng gěi wǒmen jièshào le tā de māma hé dìdi, tā bàba bú zàijiā. Āyí hěn piàoliang, hěn niánqīng, tā dìdi yě hěn kě''ài. Tāmen dōu hěn rèqíng de jiēdài le wǒmen.', 'Đúng rồi. Trương Phong giới thiệu mẹ và em trai cậu ấy cho bọn tớ, bố cậu ấy không có ở nhà. Cô ấy rất xinh đẹp và trẻ trung, em trai cậu ấy cũng rất đáng yêu. Mọi người đều tiếp đón bọn tớ rất nhiệt tình. → 是的。张风给我们介绍了他的妈妈和弟弟，他爸爸不在家。阿姨很漂亮、很年轻，他弟弟也很可爱。他们都很热情地接待了我们。 (Shì de. Zhāng Fēng gěi wǒmen jièshào le tā de māma hé dìdi, tā bàba bú zàijiā. Āyí hěn piàoliang, hěn niánqīng, tā dìdi yě hěn kě''ài. Tāmen dōu hěn rèqíng de jiēdài le wǒmen.)', 10) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr12_vi_exp_7', 'lesson-12', 'vi_to_zh', 'Các cậu không thấy hồi hộp à? Nếu là tớ chắc tớ hồi hộp chết mất.', NULL, NULL, '你们不觉得紧张吗？如果是我，我就紧张死了。', NULL, 'nǐmen bù juéde jǐnzhāng ma rúguǒ shì wǒ wǒ jiù jǐnzhāng sǐle', '[]'::jsonb, 'Gợi ý Pinyin: Nǐmen bù juéde jǐnzhāng ma? Rúguǒ shì wǒ, wǒ jiù jǐnzhāng sǐle.', 'Các cậu không thấy hồi hộp à? Nếu là tớ chắc tớ hồi hộp chết mất. → 你们不觉得紧张吗？如果是我，我就紧张死了。 (Nǐmen bù juéde jǐnzhāng ma? Rúguǒ shì wǒ, wǒ jiù jǐnzhāng sǐle.)', 11) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr12_vi_exp_8', 'lesson-12', 'vi_to_zh', 'Tớ cũng hơi ngại một chút, nhưng Trương Phong và gia đình cậu ấy rất hoan nghênh bọn tớ. Cô ấy chuẩn bị cho bọn tớ rất nhiều đồ ngon, nào là trà, cà phê, thịt bò, cá, hoa quả, v.v.', NULL, NULL, '我也有点儿不好意思，但是张风和他家人都很欢迎我们。阿姨给我们准备了很多好吃的，有茶、咖啡、牛肉、鱼、水果等等。', NULL, 'wǒ yě yǒudiǎnr bù hǎoyìsi dànshì zhāng fēng hé tā jiārén dōu hěn huānyíng wǒmen āyí gěi wǒmen zhǔnbèi le hěnduō hǎo chī de yǒu chá kāfēi niúròu yú shuǐguǒ děng děng', '[]'::jsonb, 'Gợi ý Pinyin: Wǒ yě yǒudiǎnr bù hǎoyìsi, dànshì Zhāng Fēng hé tā jiārén dōu hěn huānyíng wǒmen. Āyí gěi wǒmen zhǔnbèi le hěnduō hǎo chī de, yǒu chá, kāfēi, niúròu, yú, shuǐguǒ děng děng.', 'Tớ cũng hơi ngại một chút, nhưng Trương Phong và gia đình cậu ấy rất hoan nghênh bọn tớ. Cô ấy chuẩn bị cho bọn tớ rất nhiều đồ ngon, nào là trà, cà phê, thịt bò, cá, hoa quả, v.v. → 我也有点儿不好意思，但是张风和他家人都很欢迎我们。阿姨给我们准备了很多好吃的，有茶、咖啡、牛肉、鱼、水果等等。 (Wǒ yě yǒudiǎnr bù hǎoyìsi, dànshì Zhāng Fēng hé tā jiārén dōu hěn huānyíng wǒmen. Āyí gěi wǒmen zhǔnbèi le hěnduō hǎo chī de, yǒu chá, kāfēi, niúròu, yú, shuǐguǒ děng děng.)', 12) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr12_vi_exp_9', 'lesson-12', 'vi_to_zh', 'Chà! Cô ấy tốt thật đấy! Các cậu đã làm gì ở nhà cậu ấy?', NULL, NULL, '哇！她真好！你们在他家做什么了？', NULL, 'wa tā zhēn hǎo nǐmen zài tā jiā zuò shénme le', '[]'::jsonb, 'Gợi ý Pinyin: Wa! Tā zhēn hǎo! Nǐmen zài tā jiā zuò shénme le?', 'Chà! Cô ấy tốt thật đấy! Các cậu đã làm gì ở nhà cậu ấy? → 哇！她真好！你们在他家做什么了？ (Wa! Tā zhēn hǎo! Nǐmen zài tā jiā zuò shénme le?)', 13) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr12_vi_exp_10', 'lesson-12', 'vi_to_zh', 'Chơi game, nghe nhạc, trò chuyện, uống nước, ăn uống. Đến 10 giờ rưỡi bọn tớ mới về ký túc xá. Giờ nhớ lại, hôm qua thật vui và náo nhiệt.', NULL, NULL, '打游戏、听音乐、聊天儿、喝 水、吃东西。到十点半我们才回宿舍。现在回想起来，昨天真快乐，真热闹。', NULL, 'dǎ yóuxì tīng yīnyuè liáotiānr hē shuǐ chī dōngxi dào shí diǎn bàn wǒmen cái huí sùshè xiànzài huíxiǎng qǐlai zuótiān zhēn kuàilè zhēn rènao', '[]'::jsonb, 'Gợi ý Pinyin: Dǎ yóuxì, tīng yīnyuè, liáotiānr, hē shuǐ, chī dōngxi. Dào shí diǎn bàn wǒmen cái huí sùshè. Xiànzài huíxiǎng qǐlai, zuótiān zhēn kuàilè, zhēn rènao.', 'Chơi game, nghe nhạc, trò chuyện, uống nước, ăn uống. Đến 10 giờ rưỡi bọn tớ mới về ký túc xá. Giờ nhớ lại, hôm qua thật vui và náo nhiệt. → 打游戏、听音乐、聊天儿、喝 水、吃东西。到十点半我们才回宿舍。现在回想起来，昨天真快乐，真热闹。 (Dǎ yóuxì, tīng yīnyuè, liáotiānr, hē shuǐ, chī dōngxi. Dào shí diǎn bàn wǒmen cái huí sùshè. Xiànzài huíxiǎng qǐlai, zuótiān zhēn kuàilè, zhēn rènao.)', 14) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr12_zh_1', 'lesson-12', 'zh_to_vi', '[Mở rộng] 下次我们再 (zài: lại)一起聊天儿吧！', '下次我们再一起聊天儿吧！', 'Xiàcì wǒmen zài yīqǐ liáotiānr ba!', NULL, 'Lần sau chúng ta lại cùng nhau trò chuyện nhé!', NULL, '["Lần","sau","chúng"]'::jsonb, 'Pinyin: Xiàcì wǒmen zài yīqǐ liáotiānr ba!', '下次我们再一起聊天儿吧！ (Xiàcì wǒmen zài yīqǐ liáotiānr ba!) nghĩa là: Lần sau chúng ta lại cùng nhau trò chuyện nhé!', 15) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
