INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr12_zh_exp_7', 'lesson-12', 'zh_to_vi', '我要一杯热茶吧。吃饱了我们一起听音乐、聊天儿！', '我要一杯热茶吧。吃饱了我们一起听音乐、聊天儿！', 'Wǒ yào yì bēi rè chá ba. Chībǎo le wǒmen yīqǐ tīng yīnyuè, liáotiānr!', NULL, 'Cho mình một tách trà nóng nhé. Ăn xong chúng ta cùng nghe nhạc và trò chuyện!', NULL, '["cho","mình","một","tách","trà","nóng","nhé","ăn","xong","chúng","ta","cùng","nghe","nhạc","và","trò","chuyện"]'::jsonb, 'Pinyin: Wǒ yào yì bēi rè chá ba. Chībǎo le wǒmen yīqǐ tīng yīnyuè, liáotiānr!', '我要一杯热茶吧。吃饱了我们一起听音乐、聊天儿！ (Wǒ yào yì bēi rè chá ba. Chībǎo le wǒmen yīqǐ tīng yīnyuè, liáotiānr!) nghĩa là: Cho mình một tách trà nóng nhé. Ăn xong chúng ta cùng nghe nhạc và trò chuyện!', 25) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr12_zh_exp_8', 'lesson-12', 'zh_to_vi', '你们想喝茶还是咖啡？这里还有水果和牛肉。', '你们想喝茶还是咖啡？这里还有水果和牛肉。', 'Nǐmen xiǎng hē chá háishi kāfēi? Zhèlǐ hái yǒu shuǐguǒ hé niúròu.', NULL, 'Các cậu muốn uống trà hay cà phê? Ở đây còn có hoa quả và thịt bò nữa.', NULL, '["các","cậu","muốn","uống","trà","hay","cà","phê","đây","còn","có","hoa","quả","và","thịt","bò","nữa"]'::jsonb, 'Pinyin: Nǐmen xiǎng hē chá háishi kāfēi? Zhèlǐ hái yǒu shuǐguǒ hé niúròu.', '你们想喝茶还是咖啡？这里还有水果和牛肉。 (Nǐmen xiǎng hē chá háishi kāfēi? Zhèlǐ hái yǒu shuǐguǒ hé niúròu.) nghĩa là: Các cậu muốn uống trà hay cà phê? Ở đây còn có hoa quả và thịt bò nữa.', 26) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
