INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq12_7', 'lesson-12', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, 'Từ Hán tự “下次” có nghĩa tiếng Việt là gì?', '["chơi game, chơi trò chơi","lần sau","chết, mất","cà phê"]'::jsonb, 1, '“下次” (xià cì) là Danh từ, nghĩa là: lần sau.', 7) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq12_8', 'lesson-12', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, 'Phiên âm Pinyin chính xác của “不好意思” là gì?', '["bù hǎo yìsi","shuō","hē","xià cì"]'::jsonb, 0, '“不好意思” đọc là: bù hǎo yìsi (ngại, ngượng ngùng, xấu hổ).', 8) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq12_9', 'lesson-12', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, 'Phiên âm Pinyin chính xác của “……死了” là gì?', '["……sǐ le","yú","chá","bù hǎo yìsi"]'::jsonb, 0, '“……死了” đọc là: ……sǐ le (chết, mất).', 9) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
