INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss13_exp_4', 'lesson-13', '我妹妹的', 'Của em gái tớ.', 'Wǒ mèimei de.', '["我","妹妹","的"]'::jsonb, NULL, 10) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss13_exp_5', 'lesson-13', '你打算送给她什么礼物', 'Cậu định tặng em ấy món quà gì?', 'Nǐ dǎsuan sòng gěi tā shénme lǐwù?', '["你","打算","送","给","她","什么","礼物"]'::jsonb, NULL, 11) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss13_exp_6', 'lesson-13', '我打算送给她一顶帽子和一双鞋你觉得这顶红色的帽子怎么样', 'Tớ định tặng em ấy một chiếc mũ và một đôi giày. Cậu thấy chiếc mũ màu đỏ này thế nào?', 'Wǒ dǎsuan sòng gěi tā yī dǐng màozi hé yīshuāng xié. Nǐ juéde zhè dǐng hóngsè de màozi zěnmeyàng?', '["我","打算","送","给","她","一","顶","帽子","和","一","双","鞋","你","觉得","这","顶","红色","的","帽子","怎么样"]'::jsonb, NULL, 12) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss13_exp_7', 'lesson-13', '哇太好看了我觉得你妹妹一定很喜欢对了你妹妹的生日是几月几号', 'Chà, đẹp quá đi! Tớ nghĩ em gái cậu nhất định sẽ rất thích! À, sinh nhật em gái cậu là ngày mấy tháng mấy?', 'Wa, tài hǎokàn le! Wǒ juéde nǐ mèimei yídìng hěn xǐhuan! Duì le, nǐ mèimei de shēngrì shì jǐ yuè jǐ hào?', '["哇","太","好看","了","我","觉得","你","妹妹","一","定","很","喜欢","对","了","你","妹妹","的","生日","是","几","月","几","号"]'::jsonb, NULL, 13) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss13_exp_8', 'lesson-13', '十二月二十四号', 'Ngày 24 tháng 12.', 'Shí''èr yuè èrshísì hào.', '["十","二","月","二","十","四","号"]'::jsonb, NULL, 14) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss13_exp_9', 'lesson-13', '是星期几', 'Là thứ mấy?', 'Shì xīngqī jǐ?', '["是","星期几"]'::jsonb, NULL, 15) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss13_exp_10', 'lesson-13', '是星期六怎么了', 'Là thứ Bảy, có chuyện gì thế?', 'Shì xīngqīliù, zěnme le?', '["是","星期六","怎么了"]'::jsonb, NULL, 16) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss13_exp_11', 'lesson-13', '我差点儿忘了星期六也是我的一个朋友的生日那你买你的吧我现在去书店给他买一本汉语书明天再跟你说吧', 'Suýt nữa tớ quên mất, thứ Bảy cũng là sinh nhật một người bạn của tớ. Vậy cậu cứ mua đồ của cậu đi, giờ tớ ra hiệu sách mua tặng cậu ấy một quyển sách tiếng Hán, mai nói chuyện với cậu sau nhé!', 'Wǒ chàdiǎnr wàng le, xīngqīliù yěshì wǒ de yígè péngyou de shēngrì. Nà nǐ mǎi nǐ de ba, wǒ xiànzài qù shūdiàn gěi tā mǎi yī běn Hànyǔ shū, míngtiān zài gēn nǐ shuō ba!', '["我","差点儿","忘","了","星期六","也","是","我","的","一","个","朋友","的","生日","那","你","买","你","的","吧","我","现在","去","书店","给","他","买","一","本","汉语","书","明天","再","跟","你","说","吧"]'::jsonb, NULL, 17) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss13_exp_12', 'lesson-13', '好再见', 'Được, tạm biệt!', 'Hǎo, zàijiàn!', '["好","再见"]'::jsonb, NULL, 18) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss13_exp_13', 'lesson-13', '他这个人真好', 'Con người anh ta thật là tốt!', 'Tā zhège rén zhēn hǎo!', '["他","这","个","人","真","好"]'::jsonb, NULL, 19) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss13_exp_14', 'lesson-13', '你怎么去超市呢', 'Cậu đi gì đến siêu thị thế?', 'Nǐ zěnme qù chāoshì ne?', '["你","怎么","去","超市","呢"]'::jsonb, NULL, 20) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr13_vi_1', 'lesson-13', 'vi_to_zh', '[Mở rộng] Thứ Bảy tuần sau là sinh nhật em gái tôi.', NULL, NULL, '下星期六是我妹妹的生日。', NULL, 'xià xīngqīliù shì wǒ mèimei de shēngrì', '[]'::jsonb, 'Gợi ý Pinyin: Xià xīngqīliù shì wǒ mèimei de shēngrì. | Từ chưa học: 下 (xià: dưới / xuống)', 'Thứ Bảy tuần sau là sinh nhật em gái tôi. → 下星期六是我妹妹的生日。 (Xià xīngqīliù shì wǒ mèimei de shēngrì.)', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr13_vi_2', 'lesson-13', 'vi_to_zh', '[Mở rộng] Tôi đã mua một chiếc mũ trắng làm quà sinh nhật.', NULL, NULL, '我买了一顶白色帽子当生日礼物。', NULL, 'wǒ mǎi le yì dǐng báisè màozi dāng shēngrì lǐwù', '[]'::jsonb, 'Gợi ý Pinyin: Wǒ mǎi le yì dǐng báisè màozi dāng shēngrì lǐwù. | Từ chưa học: 当 (dāng: đảm nhiệm, làm)', 'Tôi đã mua một chiếc mũ trắng làm quà sinh nhật. → 我买了一顶白色帽子当生日礼物。 (Wǒ mǎi le yì dǐng báisè màozi dāng shēngrì lǐwù.)', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr13_vi_3', 'lesson-13', 'vi_to_zh', 'Tôi đang đọc sách.', NULL, NULL, '我在看书呢。', NULL, 'wǒ zài kànshū ne', '[]'::jsonb, 'Gợi ý Pinyin: Wǒ zài kànshū ne.', 'Tôi đang đọc sách. → 我在看书呢。 (Wǒ zài kànshū ne.)', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr13_vi_4', 'lesson-13', 'vi_to_zh', 'Anh ấy vẫn cứ chờ đợi cậu.', NULL, NULL, '他一直在等你。', NULL, 'tā yīzhí zài děng nǐ', '[]'::jsonb, 'Gợi ý Pinyin: Tā yīzhí zài děng nǐ.', 'Anh ấy vẫn cứ chờ đợi cậu. → 他一直在等你。 (Tā yīzhí zài děng nǐ.)', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr13_vi_exp_1', 'lesson-13', 'vi_to_zh', 'Mark, cậu đang làm gì thế?', NULL, NULL, '马克，你在干什么呢？', NULL, 'mǎkè nǐ zài gàn shénme ne', '[]'::jsonb, 'Gợi ý Pinyin: Mǎkè, nǐ zài gàn shénme ne?', 'Mark, cậu đang làm gì thế? → 马克，你在干什么呢？ (Mǎkè, nǐ zài gàn shénme ne?)', 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
