INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr13_vi_exp_6', 'lesson-13', 'vi_to_zh', 'Tớ định tặng em ấy một chiếc mũ và một đôi giày. Cậu thấy chiếc mũ màu đỏ này thế nào?', NULL, NULL, '我打算送给她一顶帽子和一双鞋。你觉得这顶红色的帽子怎么样？', NULL, 'wǒ dǎsuan sòng gěi tā yī dǐng màozi hé yīshuāng xié nǐ juéde zhè dǐng hóngsè de màozi zěnmeyàng', '[]'::jsonb, 'Gợi ý Pinyin: Wǒ dǎsuan sòng gěi tā yī dǐng màozi hé yīshuāng xié. Nǐ juéde zhè dǐng hóngsè de màozi zěnmeyàng?', 'Tớ định tặng em ấy một chiếc mũ và một đôi giày. Cậu thấy chiếc mũ màu đỏ này thế nào? → 我打算送给她一顶帽子和一双鞋。你觉得这顶红色的帽子怎么样？ (Wǒ dǎsuan sòng gěi tā yī dǐng màozi hé yīshuāng xié. Nǐ juéde zhè dǐng hóngsè de màozi zěnmeyàng?)', 10) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr13_vi_exp_7', 'lesson-13', 'vi_to_zh', 'Chà, đẹp quá đi! Tớ nghĩ em gái cậu nhất định sẽ rất thích! À, sinh nhật em gái cậu là ngày mấy tháng mấy?', NULL, NULL, '哇，太好看了！我觉得你妹妹一定很喜欢！对了，你妹妹的生日是几月几号？', NULL, 'wa tài hǎokàn le wǒ juéde nǐ mèimei yídìng hěn xǐhuan duì le nǐ mèimei de shēngrì shì jǐ yuè jǐ hào', '[]'::jsonb, 'Gợi ý Pinyin: Wa, tài hǎokàn le! Wǒ juéde nǐ mèimei yídìng hěn xǐhuan! Duì le, nǐ mèimei de shēngrì shì jǐ yuè jǐ hào?', 'Chà, đẹp quá đi! Tớ nghĩ em gái cậu nhất định sẽ rất thích! À, sinh nhật em gái cậu là ngày mấy tháng mấy? → 哇，太好看了！我觉得你妹妹一定很喜欢！对了，你妹妹的生日是几月几号？ (Wa, tài hǎokàn le! Wǒ juéde nǐ mèimei yídìng hěn xǐhuan! Duì le, nǐ mèimei de shēngrì shì jǐ yuè jǐ hào?)', 11) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
