INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr13_zh_exp_9', 'lesson-13', 'zh_to_vi', '太好了！我和玉兰给你准备了一双漂亮的运动鞋。', '太好了！我和玉兰给你准备了一双漂亮的运动鞋。', 'Tài hǎo le! Wǒ hé Yùlán gěi nǐ zhǔnbèi le yì shuāng piàoliang de yùndòngxié.', NULL, 'Tuyệt quá! Tớ và Ngọc Lan đã chuẩn bị tặng cậu một đôi giày thể thao rất đẹp.', NULL, '["tuyệt","quá","tớ","và","ngọc","lan","đã","chuẩn","bị","tặng","cậu","một","đôi","giày","thể","thao","rất","đẹp"]'::jsonb, 'Pinyin: Tài hǎo le! Wǒ hé Yùlán gěi nǐ zhǔnbèi le yì shuāng piàoliang de yùndòngxié.', '太好了！我和玉兰给你准备了一双漂亮的运动鞋。 (Tài hǎo le! Wǒ hé Yùlán gěi nǐ zhǔnbèi le yì shuāng piàoliang de yùndòngxié.) nghĩa là: Tuyệt quá! Tớ và Ngọc Lan đã chuẩn bị tặng cậu một đôi giày thể thao rất đẹp.', 27) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr13_zh_exp_10', 'lesson-13', 'zh_to_vi', '对呀！我打算星期五晚上在宿舍附近请大家吃饭。', '对呀！我打算星期五晚上在宿舍附近请大家吃饭。', 'Duì ya! Wǒ dǎsuan xīngqīwǔ wǎnshang zài sùshè fùjìn qǐng dàjiā chīfàn.', NULL, 'Đúng rồi! Tớ định tối thứ Sáu mời mọi người ăn cơm gần ký túc xá.', NULL, '["đúng","rồi","tớ","định","tối","thứ","sáu","mời","mọi","người","ăn","cơm","gần","ký","túc","xá"]'::jsonb, 'Pinyin: Duì ya! Wǒ dǎsuan xīngqīwǔ wǎnshang zài sùshè fùjìn qǐng dàjiā chīfàn.', '对呀！我打算星期五晚上在宿舍附近请大家吃饭。 (Duì ya! Wǒ dǎsuan xīngqīwǔ wǎnshang zài sùshè fùjìn qǐng dàjiā chīfàn.) nghĩa là: Đúng rồi! Tớ định tối thứ Sáu mời mọi người ăn cơm gần ký túc xá.', 28) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
