INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct13_20', 'lesson-13', NULL, 'comprehensive_test', 'listening', '我差点儿忘了，星期六也是我的一个朋友的生日。那你买你的吧，我现在去书店给他买一本汉语书，明天再跟你说吧！
