INSERT INTO lessons (id, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id) VALUES ('lesson-14', 'Bài 14: Sở thích của các thành viên - Đơn nguyên 3: Gia đình', 'Bài 14', 'Đơn nguyên 3: Gia đình', 'Sở thích, ca hát, bóng đá, vẽ tranh, đi dạo, trợ từ động thái 了 và tổng kết đơn nguyên 3.', '2026-11-14'::date, 14, TRUE, NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, date_added = EXCLUDED.date_added, sort_order = EXCLUDED.sort_order, is_system = TRUE, updated_at = NOW();
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v14_1', 'lesson-14', '家人', 'jiārén', 'gia nhân', 'người nhà', 'Danh từ', '宀 (Miên) (Mái nhà, che chở, nơi ở)', '家: 宀 (Miên: mái nhà) + 豕 (Thỉ: lợn nuôi dưới mái nhà) • 人: Bộ 人 (Nhân - dáng người đứng bước, chữ độc thể)', 'Ghép 家 [bộ 宀] + 人 [bộ 人] để nhớ từ 家人 (jiārén): "người nhà".', '小兰，你家人的爱好是什么？', 'Xiǎo Lán, nǐ jiārén de àihào shì shénme?', 'Tiểu Lan, sở thích của những người trong gia đình cậu là gì?', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v14_2', 'lesson-14', '足球迷', 'zúqiúmí', 'túc cầu', 'fan cuồng bóng đá', 'Danh từ', '足/⻊ (Túc) (Bàn chân, bước chân, đá bóng, chạy)', '足: Bộ 足 (Túc - đầu gối và bàn chân) • 球: 王 (Ngọc: quả cầu tròn như ngọc) + 求 (Cầu) • 迷: 米 (Mễ: hạt gạo vãi khắp) + 辶 (Sước: lạc lối / say mê)', 'Ghép 足 [bộ 足] + 球 [bộ 王] + 迷 [bộ 辶] để nhớ từ 足球迷 (zúqiúmí): "fan cuồng bóng đá".', '我也是。我家人都叫我足球迷。', 'Wǒ yěshì. Wǒ jiā rén dōu jiào wǒ zúqiúmí.', 'Tớ cũng vậy. Người nhà tớ đều gọi tớ là tín đồ bóng đá.', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v14_3', 'lesson-14', '爱好', 'àihào', 'ái hảo', 'sở thích', 'Danh từ', '爪/爫 (Trảo) (Móng vuốt, bàn tay chụp lấy)', '爱: 爫 (Trảo: tay vuốt ve) + 冖 + 友 (Hựu: tình bạn yêu thương) • 好: 女 (Nữ: người mẹ) + 子 (Tử: đứa con)', 'Ghép 爱 [bộ 爫] + 好 [bộ 女] để nhớ từ 爱好 (àihào): "sở thích".', '小兰，你家人的爱好是什么？', 'Xiǎo Lán, nǐ jiārén de àihào shì shénme?', 'Tiểu Lan, sở thích của những người trong gia đình cậu là gì?', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v14_4', 'lesson-14', '园子', 'yuánzi', 'từ Hán ngữ', 'vườn', 'Danh từ', '囗 (Vi) (Vây quanh, không gian kín, lãnh thổ)', '园: 囗 (Vi: tường rào bao quanh) + 元 (Nguyên: khu vườn) • 子: Bộ 子 (Tử - đứa trẻ dang tay, chữ độc thể)', 'Ghép 园 [bộ 囗] + 子 [bộ 子] để nhớ từ 园子 (yuánzi): "vườn".', '我爸爸很喜欢种树，我家有一个小园子，园子里全都是花和树.', 'Wǒ bàba hěn xǐhuan zhòng shù, wǒjiā yǒu yígè xiǎo yuánzi, yuánzi li quán dōu shì huā hé shù.', 'Bố tớ rất thích trồng cây, nhà tớ có một khu vườn nhỏ, trong vườn toàn là hoa và cây cối.', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v14_5', 'lesson-14', '真容', 'zhēnróng', 'từ Hán ngữ', 'chân dung', 'Danh từ', '目 (Mục) (Con mắt, nhìn ngắm, thị giác)', '真: 十 (Thập) + 目 (Mục) + 一 + 八 (mắt nhìn thật rõ) • 容: 宀 (Miên: mái nhà) + 谷 (Cốc: thung lũng rộng chứa đựng)', 'Ghép 真 [bộ 目] + 容 [bộ 宀] để nhớ từ 真容 (zhēnróng): "chân dung".', '我弟弟今年 6 岁，他最喜欢画画儿。你看，这是他画的画儿，他画了爷爷的真容。', 'Wǒ dìdi jīnnián 6 suì, tā zuì xǐhuan huà huàr. Nǐ kàn，zhè shì tā huà de huàr, tā huà le yéye de zhēnróng.', 'Em trai tớ năm nay 6 tuổi, em ấy thích nhất là vẽ tranh. Cậu xem, đây là bức tranh em ấy vẽ, em ấy vẽ chân dung ông nội đấy.', 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v14_6', 'lesson-14', '树', 'shù', 'từ Hán ngữ', 'cây', 'Danh từ', '木 (Mộc) (Cây cối, gỗ, thực vật)', '树 = 木 (Mộc: cây cối) + 对 (Đối: trồng cây).', 'Chữ 树 (shù) mang nghĩa "cây", bộ chính 木 (Mộc); cấu tạo: 木 (Mộc: cây cối) + 对 (Đối: trồng cây).', '我爸爸很喜欢种树，我家有一个小园子，园子里全都是花和树.', 'Wǒ bàba hěn xǐhuan zhòng shù, wǒjiā yǒu yígè xiǎo yuánzi, yuánzi li quán dōu shì huā hé shù.', 'Bố tớ rất thích trồng cây, nhà tớ có một khu vườn nhỏ, trong vườn toàn là hoa và cây cối.', 6) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v14_7', 'lesson-14', '花', 'huā', 'từ Hán ngữ', 'hoa', 'Danh từ', '艹 (Thảo) (Cỏ cây, hoa lá, thảo mộc)', '花 = 艹 (Thảo: thực vật) + 化 (Hóa: nở thành hoa).', 'Chữ 花 (huā) mang nghĩa "hoa", bộ chính 艹 (Thảo); cấu tạo: 艹 (Thảo: thực vật) + 化 (Hóa: nở thành hoa).', '我爸爸很喜欢种树，我家有一个小园子，园子里全都是花和树.', 'Wǒ bàba hěn xǐhuan zhòng shù, wǒjiā yǒu yígè xiǎo yuánzi, yuánzi li quán dōu shì huā hé shù.', 'Bố tớ rất thích trồng cây, nhà tớ có một khu vườn nhỏ, trong vườn toàn là hoa và cây cối.', 7) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v14_8', 'lesson-14', '公园', 'gōngyuán', 'công', 'công viên', 'Danh từ', '八 (Bát) (Số tám, phân chia, mở rộng)', '公: 八 (Bát: chia đều) + 厶 (Tư: không giữ riêng, công cộng) • 园: 囗 (Vi: tường rào bao quanh) + 元 (Nguyên: khu vườn)', 'Ghép 公 [bộ 八] + 园 [bộ 囗] để nhớ từ 公园 (gōngyuán): "công viên".', '爷爷很喜欢散步和看报纸，他每天早上在家看报纸，下午去公园散步。你有什么爱好吗？', 'Yéye hěn xǐhuan sànbù hé kàn bàozhǐ, tā měitiān zǎoshang zài jiā kàn bàozhǐ, xiàwǔ qù gōngyuán sànbù. Nǐ yǒu shénme àihào ma?', 'Ông nội rất thích đi dạo và đọc báo, sáng nào ông cũng đọc báo ở nhà, chiều ra công viên đi dạo. Cậu có sở thích gì không?', 8) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v14_9', 'lesson-14', '比赛', 'bǐsài', 'từ Hán ngữ', 'trận đấu', 'Danh từ', '比 (Tỷ) (So sánh, kề bên)', '比: Bộ 比 (Tỷ - hai người đứng cạnh so sánh) • 赛: 宀 + 共 biến thể + 贝 (Bối: phần thưởng thi đấu)', 'Ghép 比 [bộ 比] + 赛 [bộ 贝] để nhớ từ 比赛 (bǐsài): "trận đấu".', '我最喜欢踢足球，如果学校有足球比赛, 我一定参加。', 'Wǒ zuì xǐhuan tī zúqiú, rúguǒ xuéxiào yǒu zúqiú bǐsài, wǒ yídìng cānjiā.', 'Tớ thích nhất đá bóng, nếu trường có giải bóng đá, tớ nhất định sẽ tham gia.', 9) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v14_10', 'lesson-14', '画儿', 'huàr', 'họa nhi', '(bức) tranh', 'Danh từ', '田 (Điền) (Ruộng đất, khu vực, mặt)', '画: 一 + 田 (Điền: khung tranh chia ô) + 凵 • 儿: Bộ 儿 (Nhi - nét cong, chữ độc thể)', 'Ghép 画 [bộ 田] + 儿 [bộ 儿] để nhớ từ 画儿 (huàr): "(bức) tranh".', '我弟弟今年 6 岁，他最喜欢画画儿。你看，这是他画的画儿，他画了爷爷的真容。', 'Wǒ dìdi jīnnián 6 suì, tā zuì xǐhuan huà huàr. Nǐ kàn，zhè shì tā huà de huàr, tā huà le yéye de zhēnróng.', 'Em trai tớ năm nay 6 tuổi, em ấy thích nhất là vẽ tranh. Cậu xem, đây là bức tranh em ấy vẽ, em ấy vẽ chân dung ông nội đấy.', 10) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v14_11', 'lesson-14', '报纸', 'bàozhǐ', 'từ Hán ngữ', 'báo', 'Danh từ', '手/扌 (Thủ) (Bàn tay, động tác, thao tác)', '报: 扌 (Thủ) + 卩 + 又 • 纸: 纟 (Mịch: sợi xơ làm giấy) + 氏 (Thị)', 'Ghép 报 [bộ 扌] + 纸 [bộ 纟] để nhớ từ 报纸 (bàozhǐ): "báo".', '爷爷很喜欢散步和看报纸，他每天早上在家看报纸，下午去公园散步。你有什么爱好吗？', 'Yéye hěn xǐhuan sànbù hé kàn bàozhǐ, tā měitiān zǎoshang zài jiā kàn bàozhǐ, xiàwǔ qù gōngyuán sànbù. Nǐ yǒu shénme àihào ma?', 'Ông nội rất thích đi dạo và đọc báo, sáng nào ông cũng đọc báo ở nhà, chiều ra công viên đi dạo. Cậu có sở thích gì không?', 11) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v14_12', 'lesson-14', '种', 'zhòng', 'từ Hán ngữ', 'trồng cây, hoa)', 'Động từ', '禾 (Hòa) (Cây lúa, ngũ cốc, thời vụ)', '种 = 禾 (Hòa: cây lúa) + 中 (Trung: gieo hạt giống).', 'Chữ 种 (zhòng) mang nghĩa "trồng cây, hoa)", bộ chính 禾 (Hòa); cấu tạo: 禾 (Hòa: cây lúa) + 中 (Trung: gieo hạt giống).', '我爸爸很喜欢种树，我家有一个小园子，园子里全都是花和树.', 'Wǒ bàba hěn xǐhuan zhòng shù, wǒjiā yǒu yígè xiǎo yuánzi, yuánzi li quán dōu shì huā hé shù.', 'Bố tớ rất thích trồng cây, nhà tớ có một khu vườn nhỏ, trong vườn toàn là hoa và cây cối.', 12) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v14_13', 'lesson-14', '画', 'huà', 'họa', 'vẽ (tranh)', 'Động từ', '田 (Điền) (Ruộng đất, khu vực, mặt)', '画 = 一 + 田 (Điền: khung tranh chia ô) + 凵.', 'Chữ 画 (huà) mang nghĩa "vẽ (tranh)", bộ chính 田 (Điền); cấu tạo: 一 + 田 (Điền: khung tranh chia ô) + 凵.', '我弟弟今年 6 岁，他最喜欢画画儿。你看，这是他画的画儿，他画了爷爷的真容。', 'Wǒ dìdi jīnnián 6 suì, tā zuì xǐhuan huà huàr. Nǐ kàn，zhè shì tā huà de huàr, tā huà le yéye de zhēnróng.', 'Em trai tớ năm nay 6 tuổi, em ấy thích nhất là vẽ tranh. Cậu xem, đây là bức tranh em ấy vẽ, em ấy vẽ chân dung ông nội đấy.', 13) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v14_14', 'lesson-14', '唱歌', 'chàng gē', 'xướng ca', 'hát', 'Động từ', '口 (Khẩu) (Miệng, ăn uống, lời nói, âm thanh phát ra)', '唱: 口 (Khẩu: miệng hát) + 昌 (Xương: vang xa) • 歌: 哥 (Ca) + 欠 (Khiếm: mở miệng ngân nga)', 'Ghép 唱 [bộ 口] + 歌 [bộ 欠] để nhớ từ 唱歌 (chàng gē): "hát".', '我妈妈很喜欢唱歌和看书，她买了很多书。', 'Wǒ māma hěn xǐhuan chàng gē hé kànshū, tā mǎi le hěnduō shū.', 'Mẹ tớ rất thích hát và đọc sách, bà mua rất nhiều sách.', 14) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v14_15', 'lesson-14', '散步', 'sànbù', 'bộ', 'đi dạo', 'Động từ', '攴/攵 (Phộc) (Đánh khẽ, hành động, dạy dỗ)', '散: 龷 + 月 (Nhục) + 攵 (Phộc) • 步: 止 (Chỉ: bước chân trên) + 少 biến thể (bước chân dưới)', 'Ghép 散 [bộ 攵] + 步 [bộ 止] để nhớ từ 散步 (sànbù): "đi dạo".', '爷爷很喜欢散步和看报纸，他每天早上在家看报纸，下午去公园散步。你有什么爱好吗？', 'Yéye hěn xǐhuan sànbù hé kàn bàozhǐ, tā měitiān zǎoshang zài jiā kàn bàozhǐ, xiàwǔ qù gōngyuán sànbù. Nǐ yǒu shénme àihào ma?', 'Ông nội rất thích đi dạo và đọc báo, sáng nào ông cũng đọc báo ở nhà, chiều ra công viên đi dạo. Cậu có sở thích gì không?', 15) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v14_16', 'lesson-14', '讲故事', 'jiǎng gùshi', 'sự', 'kể chuyện', 'Động từ', '言/讠 (Ngôn) (Lời nói, ngôn ngữ, giao tiếp)', '讲: 讠 (Ngôn: lời nói) + 井 (Tỉnh: nói rành mạch) • 故: 古 (Cổ: chuyện xưa) + 攵 (Phộc) • 事: 一 + 口 + 彐 + 亅 (tay cầm sổ ghi công việc)', 'Ghép 讲 [bộ 讠] + 故 [bộ 攵] + 事 [bộ 亅] để nhớ từ 讲故事 (jiǎng gùshi): "kể chuyện".', '我爸爸也很喜欢看书，他有空儿的时候就给我和弟弟讲故事。你弟弟喜欢什么？', 'Wǒ bàba yě hěn xǐhuan kànshū, tā yǒu kòngr de shíhou jiù gěi wǒ hé dìdi jiǎng gùshi. Nǐ dìdi xǐhuan shénme?', 'Bố tớ cũng rất thích đọc sách, lúc rảnh rỗi ông thường kể chuyện cho tớ và em trai nghe. Em trai cậu thích gì?', 16) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v14_17', 'lesson-14', '踢足球', 'tī zúqiú', 'thích túc cầu', 'chơi bóng đá', 'Động từ', '足/⻊ (Túc) (Bàn chân, bước chân, đá bóng, chạy)', '踢: ⻊ (Túc: bàn chân) + 易 (Dịch: động tác đá) • 足: Bộ 足 (Túc - đầu gối và bàn chân) • 球: 王 (Ngọc: quả cầu tròn như ngọc) + 求 (Cầu)', 'Ghép 踢 [bộ 足] + 足 [bộ 足] + 球 [bộ 王] để nhớ từ 踢足球 (tī zúqiú): "chơi bóng đá".', '我最喜欢踢足球，如果学校有足球比赛, 我一定参加。', 'Wǒ zuì xǐhuan tī zúqiú, rúguǒ xuéxiào yǒu zúqiú bǐsài, wǒ yídìng cānjiā.', 'Tớ thích nhất đá bóng, nếu trường có giải bóng đá, tớ nhất định sẽ tham gia.', 17) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v14_18', 'lesson-14', '参加', 'cānjiā', 'từ Hán ngữ', 'tham gia', 'Động từ', '厶 (Tư) (Riêng tư, cuộn tròn)', '参: 厶 (Tư) + 大 (Đại) + 彡 (Sam) • 加: 力 (Lực: sức) + 口 (Khẩu: lời thêm vào)', 'Ghép 参 [bộ 厶] + 加 [bộ 力] để nhớ từ 参加 (cānjiā): "tham gia".', '我最喜欢踢足球，如果学校有足球比赛, 我一定参加。', 'Wǒ zuì xǐhuan tī zúqiú, rúguǒ xuéxiào yǒu zúqiú bǐsài, wǒ yídìng cānjiā.', 'Tớ thích nhất đá bóng, nếu trường có giải bóng đá, tớ nhất định sẽ tham gia.', 18) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v14_19', 'lesson-14', '一样', 'yíyàng', 'từ Hán ngữ', 'giống nhau', 'Tính từ', '一 (Nhất) (Số một, nền tảng, nét ngang cơ bản)', '一: Bộ 一 (Nhất - 1 nét ngang, số 1) • 样: 木 (Mộc: khuôn gỗ) + 羊 (Dương)', 'Ghép 一 [bộ 一] + 样 [bộ 木] để nhớ từ 一样 (yíyàng): "giống nhau".', '我家有很多人，每个人的爱好都不一样。', 'Wǒ jiā yǒu hěn duō rén, měi gèrén de àihào dōu bù yíyàng.', 'Nhà tớ có rất nhiều người, sở thích của mỗi người đều khác nhau.', 19) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v14_20', 'lesson-14', '小', 'xiǎo', 'tiểu', 'nhỏ, bé', 'Tính từ', '小 (Tiểu) (Nhỏ bé, ít ỏi)', '小 = Bộ 小 (Tiểu - hạt cát nhỏ bé).', 'Ghi nhớ chữ [小] (nhỏ, bé) qua hình tượng Nhỏ bé, ít ỏi.', '小兰，你家人的爱好是什么？', 'Xiǎo Lán, nǐ jiārén de àihào shì shénme?', 'Tiểu Lan, sở thích của những người trong gia đình cậu là gì?', 20) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v14_21', 'lesson-14', '全', 'quán', 'từ Hán ngữ', 'toàn, tất cả', 'Tính từ', '人/亻 (Nhân) (Con người, nhân loại, hành động)', '全 = 人 (Nhân: mái che) + 王 (Ngọc: viên ngọc nguyên vẹn).', 'Chữ 全 (quán) mang nghĩa "toàn, tất cả", bộ chính 人/亻 (Nhân); cấu tạo: 人 (Nhân: mái che) + 王 (Ngọc: viên ngọc nguyên vẹn).', '我爸爸很喜欢种树，我家有一个小园子，园子里全都是花和树.', 'Wǒ bàba hěn xǐhuan zhòng shù, wǒjiā yǒu yígè xiǎo yuánzi, yuánzi li quán dōu shì huā hé shù.', 'Bố tớ rất thích trồng cây, nhà tớ có một khu vườn nhỏ, trong vườn toàn là hoa và cây cối.', 21) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v14_22', 'lesson-14', '有空儿', 'yǒu kòngr', 'hữu nhi', 'rảnh', 'Động từ', '月 (Nguyệt/Nhục) (Mặt trăng hoặc các bộ phận thân thể người)', '有: 𠂇 (bàn tay) + 月 (Nguyệt/Nhục: cầm miếng thịt là có) • 空: 穴 (Huyệt: hang trống) + 工 (Công: đào rỗng) • 儿: Bộ 儿 (Nhi - nét cong, chữ độc thể)', 'Ghép 有 [bộ 月] + 空 [bộ 穴] + 儿 [bộ 儿] để nhớ từ 有空儿 (yǒu kòngr): "rảnh".', '我爸爸也很喜欢看书，他有空儿的时候就给我和弟弟讲故事。你弟弟喜欢什么？', 'Wǒ bàba yě hěn xǐhuan kànshū, tā yǒu kòngr de shíhou jiù gěi wǒ hé dìdi jiǎng gùshi. Nǐ dìdi xǐhuan shénme?', 'Bố tớ cũng rất thích đọc sách, lúc rảnh rỗi ông thường kể chuyện cho tớ và em trai nghe. Em trai cậu thích gì?', 22) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order) VALUES ('g14_1', 'lesson-14', '1. Câu chữ 有', 'Cấu trúc câu ngữ pháp trọng tâm', ' 我有一个哥哥和一个妹妹。 Wǒ yǒu yígè gēge hé yígè mèimei. Tôi có một anh trai và một em gái. 客厅里有三个人。 Kètīng li yǒu sān gèrén. Trong phòng khách có 3 người.', NULL, '[{"hanzi":"我有一个哥哥和一个妹妹。","pinyin":"Wǒ yǒu yígè gēge hé yígè mèimei.","meaning":"Tôi có một anh trai và một em gái."},{"hanzi":"客厅里有三个人。","pinyin":"Kètīng li yǒu sān gèrén.","meaning":"Trong phòng khách có 3 người."}]'::jsonb, 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order) VALUES ('g14_2', 'lesson-14', '2. 只 + Động từ', 'Cấu trúc câu ngữ pháp trọng tâm', ' 他们只关心自己。 Tāmen zhǐ guānxīn zìjǐ. Bọn họ chỉ quan tâm đến bản thân mình mà thôi. 我叔叔只有一个儿子。 Wǒ shūshu zhǐyǒu yígè érzi. Chú tôi chỉ có một người con trai.', NULL, '[{"hanzi":"他们只关心自己。","pinyin":"Tāmen zhǐ guānxīn zìjǐ.","meaning":"Bọn họ chỉ quan tâm đến bản thân mình mà thôi."},{"hanzi":"我叔叔只有一个儿子。","pinyin":"Wǒ shūshu zhǐyǒu yígè érzi.","meaning":"Chú tôi chỉ có một người con trai."}]'::jsonb, 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order) VALUES ('g14_3', 'lesson-14', '3. 呢', 'Cấu trúc câu ngữ pháp trọng tâm', ' 我伯伯今年五十六岁，你伯伯呢？ Wǒ bóbo jīnnián wǔshíliù suì, nǐ bóbo ne? Năm nay bác tôi 56 tuổi, bác cậu thì sao? 妈妈，我的衣服在哪儿呢？ Māma, wǒ de yīfu zài nǎr ne? Mẹ ơi, quần áo của con ở đâu nhỉ?', NULL, '[{"hanzi":"我伯伯今年五十六岁，你伯伯呢？","pinyin":"Wǒ bóbo jīnnián wǔshíliù suì, nǐ bóbo ne?","meaning":"Năm nay bác tôi 56 tuổi, bác cậu thì sao?"},{"hanzi":"妈妈，我的衣服在哪儿呢？","pinyin":"Māma, wǒ de yīfu zài nǎr ne?","meaning":"Mẹ ơi, quần áo của con ở đâu nhỉ?"}]'::jsonb, 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order) VALUES ('g14_4', 'lesson-14', '4. 这么 và 那么', 'Cấu trúc câu ngữ pháp trọng tâm', ' 我爸爸那么帅，所以我当然也很帅了。 Wǒ bàba nàme shuài, suǒyǐ wǒ dāngrán yě hěn shuài le. Bố tôi đẹp trai như vậy, nên đương nhiên tôi cũng đẹp trai rồi. 女儿，你的房间怎么这么乱啊？ Nǚ''ér, nǐ de fángjiān zěnme zhème luàn a? Con gái à, sao phòng con lại bừa bộn vậy?', NULL, '[{"hanzi":"我爸爸那么帅，所以我当然也很帅了。","pinyin":"Wǒ bàba nàme shuài, suǒyǐ wǒ dāngrán yě hěn shuài le.","meaning":"Bố tôi đẹp trai như vậy, nên đương nhiên tôi cũng đẹp trai rồi."},{"hanzi":"我爷爷真不喜欢吃面条。","pinyin":"Wǒ yéye zhēn bù xǐhuan chī miàntiáo.","meaning":"Ông nội tôi thật sự không thích ăn mì."}]'::jsonb, 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order;
INSERT INTO texts (id, lesson_id, title, description, sort_order) VALUES ('txt_14_1', 'lesson-14', 'Bài khoá #1: Hội thoại giáo trình — Sở thích của các thành viên', 'Hội thoại chuẩn giáo trình Bài 14. Từ vựng chưa học được chú thích phiên âm & nghĩa trong ngoặc.', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_14_1_1', 'txt_14_1', '马克', '小兰，你家人的爱好是什么？', '小兰，你家人的爱好是什么？', 'Xiǎo Lán, nǐ jiārén de àihào shì shénme?', 'Tiểu Lan, sở thích của những người trong gia đình cậu là gì?', 1) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_14_1_2', 'txt_14_1', '范玉兰', '我家有很多人，每个人的爱好都不一样。', '我家有很多人，每个人的爱好都不 (bù: không)一样。', 'Wǒ jiā yǒu hěn duō rén, měi gèrén de àihào dōu bù yíyàng.', 'Nhà tớ có rất nhiều người, sở thích của mỗi người đều khác nhau.', 2) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_14_1_3', 'txt_14_1', '马克', '你爸爸喜欢什么？', '你爸爸喜欢什么？', 'Nǐ bàba xǐhuan shénme?', 'Bố cậu thích gì?', 3) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_14_1_4', 'txt_14_1', '范玉兰', '我爸爸很喜欢种树，我家有一个小园子，园子里全都是花和树.', '我爸爸很喜欢种树，我家有一个小园子，园子里 (lǐ: trong)全都是花和树.', 'Wǒ bàba hěn xǐhuan zhòng shù, wǒjiā yǒu yígè xiǎo yuánzi, yuánzi li quán dōu shì huā hé shù.', 'Bố tớ rất thích trồng cây, nhà tớ có một khu vườn nhỏ, trong vườn toàn là hoa và cây cối.', 4) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_14_1_5', 'txt_14_1', '马克', '一定很漂亮！ 你妈妈呢？', '一定 (yīdìng: nhất định)很漂亮！ 你妈妈呢？', 'Yídìng hěn piàoliang! Nǐ māma ne?', 'Chắc chắn rất đẹp! Thế còn mẹ cậu?', 5) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_14_1_6', 'txt_14_1', '范玉兰', '我妈妈很喜欢唱歌和看书，她买了很多书。', '我妈妈很喜欢唱歌和看书，她买了很多书。', 'Wǒ māma hěn xǐhuan chàng gē hé kànshū, tā mǎi le hěnduō shū.', 'Mẹ tớ rất thích hát và đọc sách, bà mua rất nhiều sách.', 6) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_14_1_7', 'txt_14_1', '马克', '我爸爸也很喜欢看书，他有空儿的时候就给我和弟弟讲故事。你弟弟喜欢什么？', '我爸爸也很喜欢看书，他有空儿的时候就给我和弟弟讲故事。你弟弟喜欢什么？', 'Wǒ bàba yě hěn xǐhuan kànshū, tā yǒu kòngr de shíhou jiù gěi wǒ hé dìdi jiǎng gùshi. Nǐ dìdi xǐhuan shénme?', 'Bố tớ cũng rất thích đọc sách, lúc rảnh rỗi ông thường kể chuyện cho tớ và em trai nghe. Em trai cậu thích gì?', 7) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_14_1_8', 'txt_14_1', '范玉兰', '我弟弟今年 6 岁，他最喜欢画画儿。你看，这是他画的画儿，他画了爷爷的真容。', '我弟弟今 (jīn: hôm nay, nay)年 6 岁，他最喜欢画画儿。你看，这是他画的画儿，他画了爷爷的真容。', 'Wǒ dìdi jīnnián 6 suì, tā zuì xǐhuan huà huàr. Nǐ kàn，zhè shì tā huà de huàr, tā huà le yéye de zhēnróng.', 'Em trai tớ năm nay 6 tuổi, em ấy thích nhất là vẽ tranh. Cậu xem, đây là bức tranh em ấy vẽ, em ấy vẽ chân dung ông nội đấy.', 8) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_14_1_9', 'txt_14_1', '马克', '很好看！那你爷爷喜欢什么？', '很好看！那你爷爷喜欢什么？', 'Hěn hǎokàn! Nà nǐ yéye xǐhuan shénme?', 'Đẹp quá! Vậy ông nội cậu thích gì?', 9) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_14_1_10', 'txt_14_1', '范玉兰', '爷爷很喜欢散步和看报纸，他每天早上在家看报纸，下午去公园散步。你有什么爱好吗？', '爷爷很喜欢散步和看报纸，他每天 (tiān: ngày, trời)早上在家看报纸，下午去公园散步。你有什么爱好吗？', 'Yéye hěn xǐhuan sànbù hé kàn bàozhǐ, tā měitiān zǎoshang zài jiā kàn bàozhǐ, xiàwǔ qù gōngyuán sànbù. Nǐ yǒu shénme àihào ma?', 'Ông nội rất thích đi dạo và đọc báo, sáng nào ông cũng đọc báo ở nhà, chiều ra công viên đi dạo. Cậu có sở thích gì không?', 10) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_14_1_11', 'txt_14_1', '马克', '我最喜欢踢足球，如果学校有足球比赛, 我一定参加。', '我最喜欢踢足球，如果学校有足球 (zúqiú: bóng đá)比赛, 我一定 (yīdìng: nhất định)参加。', 'Wǒ zuì xǐhuan tī zúqiú, rúguǒ xuéxiào yǒu zúqiú bǐsài, wǒ yídìng cānjiā.', 'Tớ thích nhất đá bóng, nếu trường có giải bóng đá, tớ nhất định sẽ tham gia.', 11) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_14_1_12', 'txt_14_1', '范玉兰', '我也是。我家人都叫我足球迷。', '我也是。我家人都叫我足球迷。', 'Wǒ yěshì. Wǒ jiā rén dōu jiào wǒ zúqiúmí.', 'Tớ cũng vậy. Người nhà tớ đều gọi tớ là tín đồ bóng đá.', 12) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_14_1_1', 'lesson-14', 'txt_14_1', 'listening', 'listening', '小兰，你家人的爱好是什么？', NULL, 'Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Tiểu Lan, sở thích của những người trong gia đình cậu là gì?","Đây là sách của tôi.","Anh ta mời tôi ngày mai tới nhà dùng cơm.","người kia, người đó"]'::jsonb, 0, 'Nội dung nghe được: 小兰，你家人的爱好是什么？ (Xiǎo Lán, nǐ jiārén de àihào shì shénme?) → Tiểu Lan, sở thích của những người trong gia đình cậu là gì?', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_14_1_2', 'lesson-14', 'txt_14_1', 'listening', 'listening', '我家有很多人，每个人的爱好都不一样。', NULL, 'Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["我爸爸那么帅 (shuài: đẹp trai)，所以 (suǒyǐ: cho nên)我当然也很帅了。","晚 (wǎn: muộn, tối)饭以后 (yǐhòu: sau, lúc sau)我常常 (chángcháng: thường)去公园散步。","我正在吃饭。","我家有很多人，每个人的爱好都不 (bù: không)一样。"]'::jsonb, 3, 'Câu vừa đọc: 我家有很多人，每个人的爱好都不一样。 (Wǒ jiā yǒu hěn duō rén, měi gèrén de àihào dōu bù yíyàng.) → Nhà tớ có rất nhiều người, sở thích của mỗi người đều khác nhau.', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_14_1_3', 'lesson-14', 'txt_14_1', 'listening', 'listening', '你爸爸喜欢什么？', NULL, 'Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Bức tranh này vẽ đẹp thật đấy!","Cô ấy không phải Lan Lan.","Tôi làm phiên dịch ở Bộ Ngoại giao.","Bố cậu thích gì?"]'::jsonb, 3, 'Nội dung nghe được: 你爸爸喜欢什么？ (Nǐ bàba xǐhuan shénme?) → Bố cậu thích gì?', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_14_1_4', 'lesson-14', 'txt_14_1', 'listening', 'listening', '我爸爸很喜欢种树，我家有一个小园子，园子里全都是花和树.', NULL, 'Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["奶奶在看一个节目 (jiémù: chương trình)，你们别 (bié: đừng)闹了！","他们只关心自己。","你怎么现在才 (cái: mới)来 (lái: đến)啊，大家 (dàjiā: mọi người)都吃了。","我爸爸很喜欢种树，我家有一个小园子，园子里 (lǐ: trong)全都是花和树."]'::jsonb, 3, 'Câu vừa đọc: 我爸爸很喜欢种树，我家有一个小园子，园子里全都是花和树. (Wǒ bàba hěn xǐhuan zhòng shù, wǒjiā yǒu yígè xiǎo yuánzi, yuánzi li quán dōu shì huā hé shù.) → Bố tớ rất thích trồng cây, nhà tớ có một khu vườn nhỏ, trong vườn toàn là hoa và cây cối.', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO texts (id, lesson_id, title, description, sort_order) VALUES ('txt_14_2', 'lesson-14', 'Bài nghe tổng hợp: Ôn tập lũy tiến (Bài 1 – Bài 14)', 'Kết hợp từ vựng & mẫu câu đã học từ Bài 1 đến Bài 13 cùng trọng tâm Bài 14 để củng cố phản xạ nghe.', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_14_2_1', 'txt_14_2', 'Ôn Bài 13', '我在看书呢。', '我在看书呢。', 'Wǒ zài kànshū ne.', 'Tôi đang đọc sách.', 1) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_14_2_2', 'txt_14_2', 'Bài 14', '我有一个哥哥和一个妹妹。', '我有一个哥哥和一个妹妹。', 'Wǒ yǒu yígè gēge hé yígè mèimei.', 'Tôi có một anh trai và một em gái.', 2) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_14_2_3', 'txt_14_2', 'Ôn Bài 7', '现在的我们', '现在的我们', 'xiànzài de wǒmen', 'chúng tôi của hiện tại', 3) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_14_2_4', 'txt_14_2', 'Bài 14', '他们只关心自己。', '他们只关心自己。', 'Tāmen zhǐ guānxīn zìjǐ.', 'Bọn họ chỉ quan tâm đến bản thân mình mà thôi.', 4) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_14_2_5', 'txt_14_2', 'Ôn Bài 1', '我也是学生。', '我也是学生。', 'Wǒ yě shì xuéshēng.', 'Tôi cũng là học sinh.', 5) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_14_2_6', 'txt_14_2', 'Bài 14', '妈妈，我的衣服在哪儿呢？', '妈妈，我的衣服在哪儿呢？', 'Māma, wǒ de yīfu zài nǎr ne?', 'Mẹ ơi, quần áo của con ở đâu nhỉ?', 6) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_14_2_7', 'txt_14_2', 'Ôn Bài 2', '你说什么？', '你说什么？', 'Nǐ shuō shénme?', 'Cậu nói gì?', 7) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_14_2_8', 'txt_14_2', 'Bài 14', '我正在吃饭。', '我正在吃饭。', 'Wǒ zhèngzài chīfàn.', 'Tớ đang ăn cơm.', 8) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_14_2_1', 'lesson-14', 'txt_14_2', 'listening', 'listening', '我在看书呢。', NULL, '[Ôn tập Bài 13] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Tôi biết đá bóng.","Tôi đang đọc sách.","Mấy năm gần đây cô ấy càng ngày càng xinh đẹp.","Mẹ, thôi để con làm cho!"]'::jsonb, 1, 'Nội dung nghe được: 我在看书呢。 (Wǒ zài kànshū ne.) → Tôi đang đọc sách.', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_14_2_2', 'lesson-14', 'txt_14_2', 'listening', 'listening', '我有一个哥哥和一个妹妹。', NULL, '[Bài 14] Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["我叔叔 (shūshu: chú)只有一个儿子 (érzi: con trai)。","他们只关心自己。","我有一个哥哥和一个妹妹。","客厅 (kètīng: phòng khách)里 (lǐ: trong)有三个人。"]'::jsonb, 2, 'Câu vừa đọc: 我有一个哥哥和一个妹妹。 (Wǒ yǒu yígè gēge hé yígè mèimei.) → Tôi có một anh trai và một em gái.', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_14_2_3', 'lesson-14', 'txt_14_2', 'listening', 'listening', '现在的我们', NULL, '[Ôn tập Bài 7] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Chạy một chuyến","kế bên (của) cô ấy","Sao giờ cậu mới đến vậy, mọi người đều ăn cả rồi.","chúng tôi của hiện tại"]'::jsonb, 3, 'Nội dung nghe được: 现在的我们 (xiànzài de wǒmen) → chúng tôi của hiện tại', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_14_2_4', 'lesson-14', 'txt_14_2', 'listening', 'listening', '他们只关心自己。', NULL, '[Bài 14] Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["他们只关心自己。","你喜欢春天 (chūntiān: mùa xuân)还是夏天 (xiàtiān: mùa hè)？","你怎么又来 (lái: đến)了？","你爸爸喜欢什么？"]'::jsonb, 0, 'Câu vừa đọc: 他们只关心自己。 (Tāmen zhǐ guānxīn zìjǐ.) → Bọn họ chỉ quan tâm đến bản thân mình mà thôi.', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_14_2_5', 'lesson-14', 'txt_14_2', 'listening', 'listening', '我也是学生。', NULL, '[Ôn tập Bài 1] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Một con đường","Năm nay cháu 6 tuổi ạ.","Tôi cũng là học sinh.","Hình như tớ quen người này."]'::jsonb, 2, 'Nội dung nghe được: 我也是学生。 (Wǒ yě shì xuéshēng.) → Tôi cũng là học sinh.', 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO texts (id, lesson_id, title, description, sort_order) VALUES ('txt_14_3', 'lesson-14', 'Bài khoá mở rộng: Câu lạc bộ sở thích gia đình (Mở rộng)', 'Hội thoại tình huống mới xây dựng dựa trên từ vựng và ngữ pháp Bài 14 (không trùng lặp nguyên văn giáo trình).', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_14_3_1', 'txt_14_3', 'Lan', '日明，你们家人的爱好都一样吗？', '日明，你们家人的爱好都一样吗？', 'Rìmíng, nǐmen jiārén de àihào dōu yíyàng ma?', 'Nhật Minh, sở thích của mọi người trong nhà cậu có giống nhau không?', 1) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_14_3_2', 'txt_14_3', 'Minh', '不一样。爸爸喜欢看报纸和种花，妈妈喜欢听音乐唱歌。', '不 (bù: không)一样。爸爸喜欢看报纸和种花，妈妈喜欢听音乐唱歌。', 'Bù yíyàng. Bàba xǐhuan kàn bàozhǐ hé zhòng huā, māma xǐhuan tīng yīnyuè chànggē.', 'Không giống nhau. Bố thích đọc báo và trồng hoa, mẹ thích nghe nhạc và ca hát.', 2) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_14_3_3', 'txt_14_3', 'Lan', '那你弟弟呢？他也喜欢踢足球吗？', '那你弟弟呢？他也喜欢踢足球吗？', 'Nà nǐ dìdi ne? Tā yě xǐhuan tī zúqiú ma?', 'Vậy còn em trai cậu? Em ấy cũng thích đá bóng à?', 3) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_14_3_4', 'txt_14_3', 'Minh', '他最喜欢画画儿，我才是家里的足球迷。', '他最喜欢画画儿，我才 (cái: mới)是家里 (lǐ: trong)的足球迷。', 'Tā zuì xǐhuan huà huàr, wǒ cái shì jiālǐ de zúqiúmí.', 'Em ấy thích nhất vẽ tranh, còn tớ mới là tín đồ bóng đá của cả nhà.', 4) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_14_3_1', 'lesson-14', 'txt_14_3', 'listening', 'listening', '日明，你们家人的爱好都一样吗？ 不一样。爸爸喜欢看报纸和种花，妈妈喜欢听音乐唱歌。 那你弟弟呢？他也喜欢踢足球吗？ 他最喜欢画画儿，我才是家里的足球迷。', NULL, '[Nghe hiểu tình huống mới] Trong gia đình Nhật Minh, ai là người thích nhất môn vẽ tranh?', '["Bản thân Nhật Minh","Em trai của Nhật Minh (弟弟)","Mẹ của Nhật Minh","Bố của Nhật Minh"]'::jsonb, 1, 'Nhật Minh nói rõ: em trai ''最喜欢画画儿'' (thích nhất vẽ tranh).', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_14_3_2', 'lesson-14', 'txt_14_3', 'listening', 'listening', '日明，你们家人的爱好都一样吗？', NULL, '[Mở rộng] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Nhật Minh, sở thích của mọi người trong nhà cậu có giống nhau không?","Anh đã uống 2 chai rồi, đừng uống nữa!","Năm nay cháu 6 tuổi ạ.","Hôm nay là thứ tư."]'::jsonb, 0, 'Nội dung nghe được: 日明，你们家人的爱好都一样吗？ (Rìmíng, nǐmen jiārén de àihào dōu yíyàng ma?) → Nhật Minh, sở thích của mọi người trong nhà cậu có giống nhau không?', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_14_3_3', 'lesson-14', 'txt_14_3', 'listening', 'listening', '不一样。爸爸喜欢看报纸和种花，妈妈喜欢听音乐唱歌。', NULL, '[Mở rộng] Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["不 (bù: không)一样。爸爸喜欢看报纸和种花，妈妈喜欢听音乐唱歌。","我家有很多人，每个人的爱好都不 (bù: không)一样。","你明天再来 (lái: đến)跟 (gēn: cùng, với)姥姥 (lǎolao: bà ngoại)聊天儿吧！","你怎么现在才 (cái: mới)来 (lái: đến)啊，大家 (dàjiā: mọi người)都吃了。"]'::jsonb, 0, 'Câu vừa đọc: 不一样。爸爸喜欢看报纸和种花，妈妈喜欢听音乐唱歌。 (Bù yíyàng. Bàba xǐhuan kàn bàozhǐ hé zhòng huā, māma xǐhuan tīng yīnyuè chànggē.) → Không giống nhau. Bố thích đọc báo và trồng hoa, mẹ thích nghe nhạc và ca hát.', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_14_3_4', 'lesson-14', 'txt_14_3', 'listening', 'listening', '那你弟弟呢？他也喜欢踢足球吗？', NULL, '[Mở rộng] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Ngày mai chúng tôi sẽ đi leo núi.","Họ đã tốt nghiệp 2 năm rồi!","Vậy còn em trai cậu? Em ấy cũng thích đá bóng à?","Hôm nay lại mưa nữa rồi!"]'::jsonb, 2, 'Nội dung nghe được: 那你弟弟呢？他也喜欢踢足球吗？ (Nà nǐ dìdi ne? Tā yě xǐhuan tī zúqiú ma?) → Vậy còn em trai cậu? Em ấy cũng thích đá bóng à?', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss14_1', 'lesson-14', '爷爷的爱好是早上看报纸喝茶', '[Mở rộng] Sở thích của ông nội là buổi sáng đọc báo và uống trà.', 'Yéye de àihào shì zǎoshang kàn bàozhǐ, hē chá.', '["爷爷的","爱好是","早上","看","报纸","喝茶"]'::jsonb, NULL, 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss14_2', 'lesson-14', '妹妹最喜欢唱歌和画画儿', '[Mở rộng] Em gái thích nhất là ca hát và vẽ tranh.', 'Mèimei zuì xǐhuan chànggē hé huà huàr.', '["妹妹","最","喜欢","唱歌","和画","画儿"]'::jsonb, NULL, 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss14_3', 'lesson-14', '我有一个哥哥和一个妹妹', 'Tôi có một anh trai và một em gái.', 'Wǒ yǒu yígè gēge hé yígè mèimei.', '["我有","一个","哥哥","和一","个","妹妹"]'::jsonb, NULL, 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss14_4', 'lesson-14', '他们只关心自己', 'Bọn họ chỉ quan tâm đến bản thân mình mà thôi.', 'Tāmen zhǐ guānxīn zìjǐ.', '["他","们","只","关心","自己"]'::jsonb, NULL, 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss14_5', 'lesson-14', '安妮生活在这里吗', '[Ôn tập Bài 3] Annie sống ở đây phải không?', 'Ānnī shēnghuó zài zhèlǐ ma?', '["安妮","生活","在","这","里","吗"]'::jsonb, 'Từ chưa học: 里 (lǐ: trong)', 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss14_6', 'lesson-14', '这个木瓜很大也很便宜', '[Ôn tập Bài 8] Quả đu đủ này rất to mà giá cũng rất rẻ.', 'Zhège mùguā hěn dà, yě hěn piányi.', '["这个","木瓜","很大","也","很","便宜"]'::jsonb, 'Từ chưa học: 大 (dà: to, lớn)', 6) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss14_exp_1', 'lesson-14', '小兰你家人的爱好是什么', 'Tiểu Lan, sở thích của những người trong gia đình cậu là gì?', 'Xiǎo Lán, nǐ jiārén de àihào shì shénme?', '["小","兰","你","家人","的","爱好","是","什么"]'::jsonb, NULL, 7) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss14_exp_2', 'lesson-14', '我家有很多人每个人的爱好都不一样', 'Nhà tớ có rất nhiều người, sở thích của mỗi người đều khác nhau.', 'Wǒ jiā yǒu hěn duō rén, měi gèrén de àihào dōu bù yíyàng.', '["我","家","有","很","多","人","每","个","人","的","爱好","都","不","一样"]'::jsonb, NULL, 8) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss14_exp_3', 'lesson-14', '你爸爸喜欢什么', 'Bố cậu thích gì?', 'Nǐ bàba xǐhuan shénme?', '["你","爸爸","喜欢","什么"]'::jsonb, NULL, 9) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss14_exp_4', 'lesson-14', '我爸爸很喜欢种树我家有一个小园子园子里全都是花和树', 'Bố tớ rất thích trồng cây, nhà tớ có một khu vườn nhỏ, trong vườn toàn là hoa và cây cối.', 'Wǒ bàba hěn xǐhuan zhòng shù, wǒjiā yǒu yígè xiǎo yuánzi, yuánzi li quán dōu shì huā hé shù.', '["我","爸爸","很","喜欢","种","树","我","家","有","一","个","小","园子","园子","里","全","都","是","花","和","树"]'::jsonb, NULL, 10) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss14_exp_5', 'lesson-14', '一定很漂亮你妈妈呢', 'Chắc chắn rất đẹp! Thế còn mẹ cậu?', 'Yídìng hěn piàoliang! Nǐ māma ne?', '["一","定","很","漂亮","你","妈妈","呢"]'::jsonb, NULL, 11) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss14_exp_6', 'lesson-14', '我妈妈很喜欢唱歌和看书她买了很多书', 'Mẹ tớ rất thích hát và đọc sách, bà mua rất nhiều sách.', 'Wǒ māma hěn xǐhuan chàng gē hé kànshū, tā mǎi le hěnduō shū.', '["我","妈妈","很","喜欢","唱歌","和","看","书","她","买","了","很","多","书"]'::jsonb, NULL, 12) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss14_exp_7', 'lesson-14', '我爸爸也很喜欢看书他有空儿的时候就给我和弟弟讲故事你弟弟喜欢什么', 'Bố tớ cũng rất thích đọc sách, lúc rảnh rỗi ông thường kể chuyện cho tớ và em trai nghe. Em trai cậu thích gì?', 'Wǒ bàba yě hěn xǐhuan kànshū, tā yǒu kòngr de shíhou jiù gěi wǒ hé dìdi jiǎng gùshi. Nǐ dìdi xǐhuan shénme?', '["我","爸爸","也","很","喜欢","看","书","他","有空儿","的","时候","就","给","我","和","弟弟","讲故事","你","弟弟","喜欢","什么"]'::jsonb, NULL, 13) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss14_exp_8', 'lesson-14', '我弟弟今年岁他最喜欢画画儿你看这是他画的画儿他画了爷爷的真容', 'Em trai tớ năm nay 6 tuổi, em ấy thích nhất là vẽ tranh. Cậu xem, đây là bức tranh em ấy vẽ, em ấy vẽ chân dung ông nội đấy.', 'Wǒ dìdi jīnnián 6 suì, tā zuì xǐhuan huà huàr. Nǐ kàn，zhè shì tā huà de huàr, tā huà le yéye de zhēnróng.', '["我","弟弟","今","年","岁","他","最","喜欢","画","画儿","你","看","这","是","他","画","的","画儿","他","画","了","爷爷","的","真容"]'::jsonb, NULL, 14) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss14_exp_9', 'lesson-14', '很好看那你爷爷喜欢什么', 'Đẹp quá! Vậy ông nội cậu thích gì?', 'Hěn hǎokàn! Nà nǐ yéye xǐhuan shénme?', '["很","好看","那","你","爷爷","喜欢","什么"]'::jsonb, NULL, 15) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss14_exp_10', 'lesson-14', '爷爷很喜欢散步和看报纸他每天早上在家看报纸下午去公园散步你有什么爱好吗', 'Ông nội rất thích đi dạo và đọc báo, sáng nào ông cũng đọc báo ở nhà, chiều ra công viên đi dạo. Cậu có sở thích gì không?', 'Yéye hěn xǐhuan sànbù hé kàn bàozhǐ, tā měitiān zǎoshang zài jiā kàn bàozhǐ, xiàwǔ qù gōngyuán sànbù. Nǐ yǒu shénme àihào ma?', '["爷爷","很","喜欢","散步","和","看","报纸","他","每","天","早上","在","家","看","报纸","下午","去","公园","散步","你","有","什么","爱好","吗"]'::jsonb, NULL, 16) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss14_exp_11', 'lesson-14', '我最喜欢踢足球如果学校有足球比赛我一定参加', 'Tớ thích nhất đá bóng, nếu trường có giải bóng đá, tớ nhất định sẽ tham gia.', 'Wǒ zuì xǐhuan tī zúqiú, rúguǒ xuéxiào yǒu zúqiú bǐsài, wǒ yídìng cānjiā.', '["我","最","喜欢","踢足球","如果","学校","有","足","球","比赛","我","一","定","参加"]'::jsonb, NULL, 17) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss14_exp_12', 'lesson-14', '我也是我家人都叫我足球迷', 'Tớ cũng vậy. Người nhà tớ đều gọi tớ là tín đồ bóng đá.', 'Wǒ yěshì. Wǒ jiā rén dōu jiào wǒ zúqiúmí.', '["我","也","是","我","家人","都","叫","我","足球迷"]'::jsonb, NULL, 18) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss14_exp_13', 'lesson-14', '我在看书呢', 'Tôi đang đọc sách.', 'Wǒ zài kànshū ne.', '["我","在","看","书","呢"]'::jsonb, NULL, 19) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss14_exp_14', 'lesson-14', '现在的我们', 'chúng tôi của hiện tại', 'xiànzài de wǒmen', '["现在","的","我们"]'::jsonb, NULL, 20) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr14_vi_1', 'lesson-14', 'vi_to_zh', '[Mở rộng] Sở thích của ông nội là buổi sáng đọc báo và uống trà.', NULL, NULL, '爷爷的爱好是早上看报纸、喝茶。', NULL, 'yéye de àihào shì zǎoshang kàn bàozhǐ hē chá', '[]'::jsonb, 'Gợi ý Pinyin: Yéye de àihào shì zǎoshang kàn bàozhǐ, hē chá.', 'Sở thích của ông nội là buổi sáng đọc báo và uống trà. → 爷爷的爱好是早上看报纸、喝茶。 (Yéye de àihào shì zǎoshang kàn bàozhǐ, hē chá.)', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr14_vi_2', 'lesson-14', 'vi_to_zh', '[Mở rộng] Em gái thích nhất là ca hát và vẽ tranh.', NULL, NULL, '妹妹最喜欢唱歌和画画儿。', NULL, 'mèimei zuì xǐhuan chànggē hé huà huàr', '[]'::jsonb, 'Gợi ý Pinyin: Mèimei zuì xǐhuan chànggē hé huà huàr.', 'Em gái thích nhất là ca hát và vẽ tranh. → 妹妹最喜欢唱歌和画画儿。 (Mèimei zuì xǐhuan chànggē hé huà huàr.)', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr14_vi_3', 'lesson-14', 'vi_to_zh', 'Tôi có một anh trai và một em gái.', NULL, NULL, '我有一个哥哥和一个妹妹。', NULL, 'wǒ yǒu yígè gēge hé yígè mèimei', '[]'::jsonb, 'Gợi ý Pinyin: Wǒ yǒu yígè gēge hé yígè mèimei.', 'Tôi có một anh trai và một em gái. → 我有一个哥哥和一个妹妹。 (Wǒ yǒu yígè gēge hé yígè mèimei.)', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr14_vi_4', 'lesson-14', 'vi_to_zh', 'Bọn họ chỉ quan tâm đến bản thân mình mà thôi.', NULL, NULL, '他们只关心自己。', NULL, 'tāmen zhǐ guānxīn zìjǐ', '[]'::jsonb, 'Gợi ý Pinyin: Tāmen zhǐ guānxīn zìjǐ.', 'Bọn họ chỉ quan tâm đến bản thân mình mà thôi. → 他们只关心自己。 (Tāmen zhǐ guānxīn zìjǐ.)', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr14_vi_exp_1', 'lesson-14', 'vi_to_zh', 'Tiểu Lan, sở thích của những người trong gia đình cậu là gì?', NULL, NULL, '小兰，你家人的爱好是什么？', NULL, 'xiǎo lán nǐ jiārén de àihào shì shénme', '[]'::jsonb, 'Gợi ý Pinyin: Xiǎo Lán, nǐ jiārén de àihào shì shénme?', 'Tiểu Lan, sở thích của những người trong gia đình cậu là gì? → 小兰，你家人的爱好是什么？ (Xiǎo Lán, nǐ jiārén de àihào shì shénme?)', 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr14_vi_exp_2', 'lesson-14', 'vi_to_zh', 'Nhà tớ có rất nhiều người, sở thích của mỗi người đều khác nhau.', NULL, NULL, '我家有很多人，每个人的爱好都不一样。', NULL, 'wǒ jiā yǒu hěn duō rén měi gèrén de àihào dōu bù yíyàng', '[]'::jsonb, 'Gợi ý Pinyin: Wǒ jiā yǒu hěn duō rén, měi gèrén de àihào dōu bù yíyàng.', 'Nhà tớ có rất nhiều người, sở thích của mỗi người đều khác nhau. → 我家有很多人，每个人的爱好都不一样。 (Wǒ jiā yǒu hěn duō rén, měi gèrén de àihào dōu bù yíyàng.)', 6) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr14_vi_exp_3', 'lesson-14', 'vi_to_zh', 'Bố cậu thích gì?', NULL, NULL, '你爸爸喜欢什么？', NULL, 'nǐ bàba xǐhuan shénme', '[]'::jsonb, 'Gợi ý Pinyin: Nǐ bàba xǐhuan shénme?', 'Bố cậu thích gì? → 你爸爸喜欢什么？ (Nǐ bàba xǐhuan shénme?)', 7) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr14_vi_exp_4', 'lesson-14', 'vi_to_zh', 'Bố tớ rất thích trồng cây, nhà tớ có một khu vườn nhỏ, trong vườn toàn là hoa và cây cối.', NULL, NULL, '我爸爸很喜欢种树，我家有一个小园子，园子里全都是花和树.', NULL, 'wǒ bàba hěn xǐhuan zhòng shù wǒjiā yǒu yígè xiǎo yuánzi yuánzi li quán dōu shì huā hé shù', '[]'::jsonb, 'Gợi ý Pinyin: Wǒ bàba hěn xǐhuan zhòng shù, wǒjiā yǒu yígè xiǎo yuánzi, yuánzi li quán dōu shì huā hé shù.', 'Bố tớ rất thích trồng cây, nhà tớ có một khu vườn nhỏ, trong vườn toàn là hoa và cây cối. → 我爸爸很喜欢种树，我家有一个小园子，园子里全都是花和树. (Wǒ bàba hěn xǐhuan zhòng shù, wǒjiā yǒu yígè xiǎo yuánzi, yuánzi li quán dōu shì huā hé shù.)', 8) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr14_vi_exp_5', 'lesson-14', 'vi_to_zh', 'Chắc chắn rất đẹp! Thế còn mẹ cậu?', NULL, NULL, '一定很漂亮！ 你妈妈呢？', NULL, 'yídìng hěn piàoliang nǐ māma ne', '[]'::jsonb, 'Gợi ý Pinyin: Yídìng hěn piàoliang! Nǐ māma ne?', 'Chắc chắn rất đẹp! Thế còn mẹ cậu? → 一定很漂亮！ 你妈妈呢？ (Yídìng hěn piàoliang! Nǐ māma ne?)', 9) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr14_vi_exp_6', 'lesson-14', 'vi_to_zh', 'Mẹ tớ rất thích hát và đọc sách, bà mua rất nhiều sách.', NULL, NULL, '我妈妈很喜欢唱歌和看书，她买了很多书。', NULL, 'wǒ māma hěn xǐhuan chàng gē hé kànshū tā mǎi le hěnduō shū', '[]'::jsonb, 'Gợi ý Pinyin: Wǒ māma hěn xǐhuan chàng gē hé kànshū, tā mǎi le hěnduō shū.', 'Mẹ tớ rất thích hát và đọc sách, bà mua rất nhiều sách. → 我妈妈很喜欢唱歌和看书，她买了很多书。 (Wǒ māma hěn xǐhuan chàng gē hé kànshū, tā mǎi le hěnduō shū.)', 10) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr14_vi_exp_7', 'lesson-14', 'vi_to_zh', 'Bố tớ cũng rất thích đọc sách, lúc rảnh rỗi ông thường kể chuyện cho tớ và em trai nghe. Em trai cậu thích gì?', NULL, NULL, '我爸爸也很喜欢看书，他有空儿的时候就给我和弟弟讲故事。你弟弟喜欢什么？', NULL, 'wǒ bàba yě hěn xǐhuan kànshū tā yǒu kòngr de shíhou jiù gěi wǒ hé dìdi jiǎng gùshi nǐ dìdi xǐhuan shénme', '[]'::jsonb, 'Gợi ý Pinyin: Wǒ bàba yě hěn xǐhuan kànshū, tā yǒu kòngr de shíhou jiù gěi wǒ hé dìdi jiǎng gùshi. Nǐ dìdi xǐhuan shénme?', 'Bố tớ cũng rất thích đọc sách, lúc rảnh rỗi ông thường kể chuyện cho tớ và em trai nghe. Em trai cậu thích gì? → 我爸爸也很喜欢看书，他有空儿的时候就给我和弟弟讲故事。你弟弟喜欢什么？ (Wǒ bàba yě hěn xǐhuan kànshū, tā yǒu kòngr de shíhou jiù gěi wǒ hé dìdi jiǎng gùshi. Nǐ dìdi xǐhuan shénme?)', 11) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr14_vi_exp_8', 'lesson-14', 'vi_to_zh', 'Em trai tớ năm nay 6 tuổi, em ấy thích nhất là vẽ tranh. Cậu xem, đây là bức tranh em ấy vẽ, em ấy vẽ chân dung ông nội đấy.', NULL, NULL, '我弟弟今年 6 岁，他最喜欢画画儿。你看，这是他画的画儿，他画了爷爷的真容。', NULL, 'wǒ dìdi jīnnián 6 suì tā zuì xǐhuan huà huàr nǐ kàn zhè shì tā huà de huàr tā huà le yéye de zhēnróng', '[]'::jsonb, 'Gợi ý Pinyin: Wǒ dìdi jīnnián 6 suì, tā zuì xǐhuan huà huàr. Nǐ kàn，zhè shì tā huà de huàr, tā huà le yéye de zhēnróng.', 'Em trai tớ năm nay 6 tuổi, em ấy thích nhất là vẽ tranh. Cậu xem, đây là bức tranh em ấy vẽ, em ấy vẽ chân dung ông nội đấy. → 我弟弟今年 6 岁，他最喜欢画画儿。你看，这是他画的画儿，他画了爷爷的真容。 (Wǒ dìdi jīnnián 6 suì, tā zuì xǐhuan huà huàr. Nǐ kàn，zhè shì tā huà de huàr, tā huà le yéye de zhēnróng.)', 12) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr14_vi_exp_9', 'lesson-14', 'vi_to_zh', 'Đẹp quá! Vậy ông nội cậu thích gì?', NULL, NULL, '很好看！那你爷爷喜欢什么？', NULL, 'hěn hǎokàn nà nǐ yéye xǐhuan shénme', '[]'::jsonb, 'Gợi ý Pinyin: Hěn hǎokàn! Nà nǐ yéye xǐhuan shénme?', 'Đẹp quá! Vậy ông nội cậu thích gì? → 很好看！那你爷爷喜欢什么？ (Hěn hǎokàn! Nà nǐ yéye xǐhuan shénme?)', 13) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr14_vi_exp_10', 'lesson-14', 'vi_to_zh', 'Ông nội rất thích đi dạo và đọc báo, sáng nào ông cũng đọc báo ở nhà, chiều ra công viên đi dạo. Cậu có sở thích gì không?', NULL, NULL, '爷爷很喜欢散步和看报纸，他每天早上在家看报纸，下午去公园散步。你有什么爱好吗？', NULL, 'yéye hěn xǐhuan sànbù hé kàn bàozhǐ tā měitiān zǎoshang zài jiā kàn bàozhǐ xiàwǔ qù gōngyuán sànbù nǐ yǒu shénme àihào ma', '[]'::jsonb, 'Gợi ý Pinyin: Yéye hěn xǐhuan sànbù hé kàn bàozhǐ, tā měitiān zǎoshang zài jiā kàn bàozhǐ, xiàwǔ qù gōngyuán sànbù. Nǐ yǒu shénme àihào ma?', 'Ông nội rất thích đi dạo và đọc báo, sáng nào ông cũng đọc báo ở nhà, chiều ra công viên đi dạo. Cậu có sở thích gì không? → 爷爷很喜欢散步和看报纸，他每天早上在家看报纸，下午去公园散步。你有什么爱好吗？ (Yéye hěn xǐhuan sànbù hé kàn bàozhǐ, tā měitiān zǎoshang zài jiā kàn bàozhǐ, xiàwǔ qù gōngyuán sànbù. Nǐ yǒu shénme àihào ma?)', 14) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr14_zh_1', 'lesson-14', 'zh_to_vi', '[Mở rộng] 爸爸在园子里 (lǐ: trong)种了很多漂亮的花和树。', '爸爸在园子里种了很多漂亮的花和树。', 'Bàba zài yuánzi lǐ zhòng le hěnduō piàoliang de huā hé shù.', NULL, 'Bố trồng rất nhiều hoa đẹp và cây cối trong khu vườn.', NULL, '["Bố","trồng","rất"]'::jsonb, 'Pinyin: Bàba zài yuánzi lǐ zhòng le hěnduō piàoliang de huā hé shù.', '爸爸在园子里种了很多漂亮的花和树。 (Bàba zài yuánzi lǐ zhòng le hěnduō piàoliang de huā hé shù.) nghĩa là: Bố trồng rất nhiều hoa đẹp và cây cối trong khu vườn.', 15) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr14_zh_2', 'lesson-14', 'zh_to_vi', '[Mở rộng] 哥哥是个足球迷，喜欢看足球 (zúqiú: bóng đá)比赛。', '哥哥是个足球迷，喜欢看足球比赛。', 'Gēge shì gè zúqiúmí, xǐhuan kàn zúqiú bǐsài.', NULL, 'Anh trai là một tín đồ bóng đá, rất thích xem các trận đấu bóng đá.', NULL, '["Anh","trai","là"]'::jsonb, 'Pinyin: Gēge shì gè zúqiúmí, xǐhuan kàn zúqiú bǐsài.', '哥哥是个足球迷，喜欢看足球比赛。 (Gēge shì gè zúqiúmí, xǐhuan kàn zúqiú bǐsài.) nghĩa là: Anh trai là một tín đồ bóng đá, rất thích xem các trận đấu bóng đá.', 16) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr14_zh_3', 'lesson-14', 'zh_to_vi', '妈妈，我的衣服在哪儿呢？', '妈妈，我的衣服在哪儿呢？', 'Māma, wǒ de yīfu zài nǎr ne?', NULL, 'Mẹ ơi, quần áo của con ở đâu nhỉ?', NULL, '["Mẹ","ơi","quần"]'::jsonb, 'Pinyin: Māma, wǒ de yīfu zài nǎr ne?', '妈妈，我的衣服在哪儿呢？ (Māma, wǒ de yīfu zài nǎr ne?) nghĩa là: Mẹ ơi, quần áo của con ở đâu nhỉ?', 17) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
