INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr14_zh_exp_1', 'lesson-14', 'zh_to_vi', '我爷爷真不喜欢吃面条。', '我爷爷真不喜欢吃面条。', 'Wǒ yéye zhēn bù xǐhuan chī miàntiáo.', NULL, 'Ông nội tôi thật sự không thích ăn mì.', NULL, '["ông","nội","tôi","thật","sự","không","thích","ăn","mì"]'::jsonb, 'Pinyin: Wǒ yéye zhēn bù xǐhuan chī miàntiáo.', '我爷爷真不喜欢吃面条。 (Wǒ yéye zhēn bù xǐhuan chī miàntiáo.) nghĩa là: Ông nội tôi thật sự không thích ăn mì.', 19) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr14_zh_exp_2', 'lesson-14', 'zh_to_vi', '我爸爸那么帅，所以我当然也很帅了。', '我爸爸那么帅，所以我当然也很帅了。', 'Wǒ bàba nàme shuài, suǒyǐ wǒ dāngrán yě hěn shuài le.', NULL, 'Bố tôi đẹp trai như vậy, nên đương nhiên tôi cũng đẹp trai rồi.', NULL, '["bố","tôi","đẹp","trai","như","vậy","nên","đương","nhiên","tôi","cũng","đẹp","trai","rồi"]'::jsonb, 'Pinyin: Wǒ bàba nàme shuài, suǒyǐ wǒ dāngrán yě hěn shuài le.', '我爸爸那么帅，所以我当然也很帅了。 (Wǒ bàba nàme shuài, suǒyǐ wǒ dāngrán yě hěn shuài le.) nghĩa là: Bố tôi đẹp trai như vậy, nên đương nhiên tôi cũng đẹp trai rồi.', 20) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
