INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr14_zh_exp_6', 'lesson-14', 'zh_to_vi', '他最喜欢画画儿，我才是家里的足球迷。', '他最喜欢画画儿，我才是家里的足球迷。', 'Tā zuì xǐhuan huà huàr, wǒ cái shì jiālǐ de zúqiúmí.', NULL, 'Em ấy thích nhất vẽ tranh, còn tớ mới là tín đồ bóng đá của cả nhà.', NULL, '["em","ấy","thích","nhất","vẽ","tranh","còn","tớ","mới","là","tín","đồ","bóng","đá","của","cả","nhà"]'::jsonb, 'Pinyin: Tā zuì xǐhuan huà huàr, wǒ cái shì jiālǐ de zúqiúmí.', '他最喜欢画画儿，我才是家里的足球迷。 (Tā zuì xǐhuan huà huàr, wǒ cái shì jiālǐ de zúqiúmí.) nghĩa là: Em ấy thích nhất vẽ tranh, còn tớ mới là tín đồ bóng đá của cả nhà.', 24) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr14_zh_exp_7', 'lesson-14', 'zh_to_vi', '那你弟弟呢？他也喜欢踢足球吗？', '那你弟弟呢？他也喜欢踢足球吗？', 'Nà nǐ dìdi ne? Tā yě xǐhuan tī zúqiú ma?', NULL, 'Vậy còn em trai cậu? Em ấy cũng thích đá bóng à?', NULL, '["vậy","còn","em","trai","cậu","em","ấy","cũng","thích","đá","bóng"]'::jsonb, 'Pinyin: Nà nǐ dìdi ne? Tā yě xǐhuan tī zúqiú ma?', '那你弟弟呢？他也喜欢踢足球吗？ (Nà nǐ dìdi ne? Tā yě xǐhuan tī zúqiú ma?) nghĩa là: Vậy còn em trai cậu? Em ấy cũng thích đá bóng à?', 25) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr14_zh_exp_8', 'lesson-14', 'zh_to_vi', '不一样。爸爸喜欢看报纸和种花，妈妈喜欢听音乐唱歌。', '不一样。爸爸喜欢看报纸和种花，妈妈喜欢听音乐唱歌。', 'Bù yíyàng. Bàba xǐhuan kàn bàozhǐ hé zhòng huā, māma xǐhuan tīng yīnyuè chànggē.', NULL, 'Không giống nhau. Bố thích đọc báo và trồng hoa, mẹ thích nghe nhạc và ca hát.', NULL, '["không","giống","nhau","bố","thích","đọc","báo","và","trồng","hoa","mẹ","thích","nghe","nhạc","và","ca","hát"]'::jsonb, 'Pinyin: Bù yíyàng. Bàba xǐhuan kàn bàozhǐ hé zhòng huā, māma xǐhuan tīng yīnyuè chànggē.', '不一样。爸爸喜欢看报纸和种花，妈妈喜欢听音乐唱歌。 (Bù yíyàng. Bàba xǐhuan kàn bàozhǐ hé zhòng huā, māma xǐhuan tīng yīnyuè chànggē.) nghĩa là: Không giống nhau. Bố thích đọc báo và trồng hoa, mẹ thích nghe nhạc và ca hát.', 26) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
