INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq14_13', 'lesson-14', NULL, 'expanded_quiz', 'radical', NULL, NULL, 'Chữ Hán “家人” chứa bộ thủ nào sau đây?', '["雨 (Vũ) (Mưa, sương, tuyết, hiện tượng thời tiết)","凵 (Khảm) (Há miệng, hố trũng)","彡 (Sam) (Hoa văn, lông tóc, nét trang trí)","宀 (Miên) (Mái nhà, che chở, nơi ở)"]'::jsonb, 3, 'Chữ “家人” có bộ chính 宀 (Miên) (Mái nhà, che chở, nơi ở). Chiết tự: 家: 宀 (Miên: mái nhà) + 豕 (Thỉ: lợn nuôi dưới mái nhà) • 人: Bộ 人 (Nhân - dáng người đứng bước, chữ độc thể)', 13) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq14_14', 'lesson-14', NULL, 'expanded_quiz', 'radical', NULL, NULL, 'Chữ Hán “足球迷” chứa bộ thủ nào sau đây?', '["足/⻊ (Túc) (Bàn chân, bước chân, đá bóng, chạy)","斗 (Đẩu) (Cái đấu đong lường, chiến đấu)","石 (Thạch) (Hòn đá, vật cứng)","里 (Lý) (Làng xóm, bên trong, dặm đường)"]'::jsonb, 0, 'Chữ “足球迷” có bộ chính 足/⻊ (Túc) (Bàn chân, bước chân, đá bóng, chạy). Chiết tự: 足: Bộ 足 (Túc - đầu gối và bàn chân) • 球: 王 (Ngọc: quả cầu tròn như ngọc) + 求 (Cầu) • 迷: 米 (Mễ: hạt gạo vãi khắp) + 辶 (Sước: lạc lối / say mê)', 14) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq14_15', 'lesson-14', NULL, 'expanded_quiz', 'radical', NULL, NULL, 'Chữ Hán “爱好” chứa bộ thủ nào sau đây?', '["曰 (Viết) (Nói rằng, lời nói)","爪/爫 (Trảo) (Móng vuốt, bàn tay chụp lấy)","竹/⺮ (Trúc) (Tre trúc, đồ đan, sách vở)","门 (Môn) (Cánh cửa, lối ra vào)"]'::jsonb, 1, 'Chữ “爱好” có bộ chính 爪/爫 (Trảo) (Móng vuốt, bàn tay chụp lấy). Chiết tự: 爱: 爫 (Trảo: tay vuốt ve) + 冖 + 友 (Hựu: tình bạn yêu thương) • 好: 女 (Nữ: người mẹ) + 子 (Tử: đứa con)', 15) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq14_16', 'lesson-14', NULL, 'expanded_quiz', 'radical', NULL, NULL, 'Chữ Hán “园子” chứa bộ thủ nào sau đây?', '["香 (Hương) (Mùi thơm, hương vị)","厶 (Tư) (Riêng tư, cuộn tròn)","囗 (Vi) (Vây quanh, không gian kín, lãnh thổ)","方 (Phương) (Vuông vức, phương hướng)"]'::jsonb, 2, 'Chữ “园子” có bộ chính 囗 (Vi) (Vây quanh, không gian kín, lãnh thổ). Chiết tự: 园: 囗 (Vi: tường rào bao quanh) + 元 (Nguyên: khu vườn) • 子: Bộ 子 (Tử - đứa trẻ dang tay, chữ độc thể)', 16) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq14_17', 'lesson-14', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, '[Ôn tập Bài 12] Từ đã học “客人” (kèrén) có nghĩa là gì?', '["họ, quý tính, quý danh (cách nói lịch sử)","chơi bóng đá","khách","siêu thị"]'::jsonb, 2, 'Ôn tập Bài 12: “客人” (kèrén) nghĩa là: khách.', 17) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq14_18', 'lesson-14', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, '[Ôn tập Bài 3] Từ đã học “国家” (guójiā) có nghĩa là gì?', '["quốc gia, đất nước","mời, xin","thứ hai","chua"]'::jsonb, 0, 'Ôn tập Bài 3: “国家” (guójiā) nghĩa là: quốc gia, đất nước.', 18) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq14_19', 'lesson-14', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, '[Ôn tập Bài 5] Từ đã học “给 (给谁打电话)” (gěi gěi shéi dǎ diànhuà) có nghĩa là gì?', '["cho gọi điện thoại cho ai đó","dùng cuối câu, biểu thị ngữ khí cảm thán.","bên phải","nói cho"]'::jsonb, 0, 'Ôn tập Bài 5: “给 (给谁打电话)” (gěi gěi shéi dǎ diànhuà) nghĩa là: cho gọi điện thoại cho ai đó.', 19) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq14_20', 'lesson-14', NULL, 'expanded_quiz', 'reading', NULL, NULL, '[Mở rộng] Câu “爷爷的爱好是早上看报纸、喝茶。” có nghĩa tiếng Việt là gì?', '["Tôi thật lòng muốn đi cùng em.","Sở thích của ông nội là buổi sáng đọc báo và uống trà.","Năm nay hay năm sau cậu đi du học?","Anh ấy không tin vào vận mệnh, chỉ tin vào bản thân mình."]'::jsonb, 1, '爷爷的爱好是早上看报纸、喝茶。 (Yéye de àihào shì zǎoshang kàn bàozhǐ, hē chá.) → Sở thích của ông nội là buổi sáng đọc báo và uống trà.', 20) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq14_21', 'lesson-14', NULL, 'expanded_quiz', 'reading', NULL, NULL, '[Đọc hiểu mở rộng] Đọc đoạn hội thoại:
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq14_22', 'lesson-14', NULL, 'expanded_quiz', 'reading', NULL, NULL, 'Câu “我有一个哥哥和一个妹妹。” có nghĩa tiếng Việt là gì?', '["Ở đây chỉ có hai người chúng ta?","Anh ấy đã về nước từ tuần trước rồi.","Tôi có một anh trai và một em gái.","Tạm nói tới đây thôi, ngày mai nói tiếp nhé!"]'::jsonb, 2, '我有一个哥哥和一个妹妹。 (Wǒ yǒu yígè gēge hé yígè mèimei.) → Tôi có một anh trai và một em gái.', 22) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct14_1', 'lesson-14', NULL, 'comprehensive_test', 'listening', '我爸爸那么帅，所以我当然也很帅了。', NULL, 'Nghe đoạn ghi âm và chọn nghĩa tiếng Việt đúng:', '["Thầy giáo đang đợi bạn ở bên ngoài.","Cậu định tặng em ấy món quà gì?","Mark, sáng mai gặp lại nhé!","Bố tôi đẹp trai như vậy, nên đương nhiên tôi cũng đẹp trai rồi."]'::jsonb, 3, 'Nội dung nghe được: “我爸爸那么帅，所以我当然也很帅了。” (Wǒ bàba nàme shuài, suǒyǐ wǒ dāngrán yě hěn shuài le.) → Bố tôi đẹp trai như vậy, nên đương nhiên tôi cũng đẹp trai rồi.', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct14_2', 'lesson-14', NULL, 'comprehensive_test', 'listening', '我叔叔只有一个儿子。', NULL, 'Nghe đoạn ghi âm và chọn câu tiếng Trung khớp với nội dung vừa nghe:', '["小兰，你房间号码是多少？","明天上午我们一起去超市吧","我叔叔只有一个儿子。","我明天再来你家玩儿吧！"]'::jsonb, 2, 'Câu vừa đọc: “我叔叔只有一个儿子。” (Wǒ shūshu zhǐyǒu yígè érzi.) → Chú tôi chỉ có một người con trai.', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct14_3', 'lesson-14', NULL, 'comprehensive_test', 'listening', '我也是。我家人都叫我足球迷。', NULL, 'Nghe đoạn ghi âm và chọn nghĩa tiếng Việt đúng:', '["Chị gái bạn năm nay bao nhiêu tuổi? Chị ấy đi làm chưa?","Vương là người như thế nào, bạn giới thiệu cho tôi xíu đi.","Tớ cũng vậy. Người nhà tớ đều gọi tớ là tín đồ bóng đá.","Chị ấy đi ngân hàng rút tiền rồi."]'::jsonb, 2, 'Nội dung nghe được: “我也是。我家人都叫我足球迷。” (Wǒ yěshì. Wǒ jiā rén dōu jiào wǒ zúqiúmí.) → Tớ cũng vậy. Người nhà tớ đều gọi tớ là tín đồ bóng đá.', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct14_4', 'lesson-14', NULL, 'comprehensive_test', 'listening', '我家有很多人，每个人的爱好都不一样。', NULL, 'Nghe đoạn ghi âm và chọn câu tiếng Trung khớp với nội dung vừa nghe:', '["芒果酸吗？","我家有很多人，每个人的爱好都不一样。","昨天下午你去图书馆了吗","是星期几？"]'::jsonb, 1, 'Câu vừa đọc: “我家有很多人，每个人的爱好都不一样。” (Wǒ jiā yǒu hěn duō rén, měi gèrén de àihào dōu bù yíyàng.) → Nhà tớ có rất nhiều người, sở thích của mỗi người đều khác nhau.', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct14_5', 'lesson-14', NULL, 'comprehensive_test', 'listening', '那你弟弟呢？他也喜欢踢足球吗？', NULL, 'Nghe đoạn ghi âm và chọn nghĩa tiếng Việt đúng:', '["Cậu hỏi buổi sáng hay buổi chiều? 6 giờ sáng tớ đi thư viện học, buổi chiều cùng bạn Yamamoto và bạn Mark đến nhà Trương Phong.","Vậy còn em trai cậu? Em ấy cũng thích đá bóng à?","Em gái thích nhất là ca hát và vẽ tranh.","Thư viện của trường ở đâu vậy?"]'::jsonb, 1, 'Nội dung nghe được: “那你弟弟呢？他也喜欢踢足球吗？” (Nà nǐ dìdi ne? Tā yě xǐhuan tī zúqiú ma?) → Vậy còn em trai cậu? Em ấy cũng thích đá bóng à?', 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct14_6', 'lesson-14', NULL, 'comprehensive_test', 'listening', '他们只关心自己。', NULL, 'Nghe đoạn ghi âm và chọn câu tiếng Trung khớp với nội dung vừa nghe:', '["从宿舍到食堂怎么走","妈妈，我的衣服在哪儿呢？","你说什么？","他们只关心自己。"]'::jsonb, 3, 'Câu vừa đọc: “他们只关心自己。” (Tāmen zhǐ guānxīn zìjǐ.) → Bọn họ chỉ quan tâm đến bản thân mình mà thôi.', 6) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct14_7', 'lesson-14', NULL, 'comprehensive_test', 'listening', '安妮生活在这里吗', NULL, 'Nghe đoạn ghi âm và chọn nghĩa tiếng Việt đúng:', '["Cô ấy là giáo viên.","Tiểu Lan, sở thích của những người trong gia đình cậu là gì?","Annie sống ở đây phải không?","Thầy giáo đang đợi bạn ở bên ngoài."]'::jsonb, 2, 'Nội dung nghe được: “安妮生活在这里吗” (Ānnī shēnghuó zài zhèlǐ ma?) → Annie sống ở đây phải không?', 7) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
