INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct14_22', 'lesson-14', NULL, 'comprehensive_test', 'listening', '日明，你们家人的爱好都一样吗？ 不一样。爸爸喜欢看报纸和种花，妈妈喜欢听音乐唱歌。 那你弟弟呢？他也喜欢踢足球吗？ 他最喜欢画画儿，我才是家里的足球迷。', NULL, 'Trong gia đình Nhật Minh, ai là người thích nhất môn vẽ tranh?', '["Bản thân Nhật Minh","Em trai của Nhật Minh (弟弟)","Mẹ của Nhật Minh","Bố của Nhật Minh"]'::jsonb, 1, 'Nhật Minh nói rõ: em trai ''最喜欢画画儿'' (thích nhất vẽ tranh).', 22) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
