INSERT INTO lessons (id, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id) VALUES ('lesson-15', 'Bài 15: Thời tiết ở Bắc Kinh - Đơn nguyên 4: Thời tiết', 'Bài 15', 'Đơn nguyên 4: Thời tiết', 'Bốn mùa xuân hạ thu đông, nhiệt độ, mưa tuyết, khí hậu Bắc Kinh và câu hỏi với 怎么样.', '2026-11-14'::date, 15, TRUE, NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, date_added = EXCLUDED.date_added, sort_order = EXCLUDED.sort_order, is_system = TRUE, updated_at = NOW();
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v15_1', 'lesson-15', '北京', 'Běijīng', 'từ Hán ngữ', 'Bắc Kinh', 'Danh từ', '匕 (Chủy) (Cái thìa, dao găm)', '北: Hai người quay lưng vào nhau (sóng đôi ngược chiều) • 京: 亠 + 口 + 小 (lầu cao kinh thành)', 'Ghép 北 [bộ 匕] + 京 [bộ 亠] để nhớ từ 北京 (Běijīng): "Bắc Kinh".', '张风，北京有几个季节？', 'Zhāng Fēng, Běijīng yǒu jǐ gè jìjié?', 'Trương Phong, Bắc Kinh có mấy mùa?', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v15_2', 'lesson-15', '天气', 'tiānqì', 'thiên khí', 'thời tiết', 'Danh từ', '大 (Đại) (To lớn, vĩ đại)', '天: 一 (Nhất: bầu trời cao) + 大 (Đại: con người dang tay) • 气: Bộ 气 (Khí - làn hơi bốc lên, chữ độc thể)', 'Ghép 天 [bộ 大] + 气 [bộ 气] để nhớ từ 天气 (tiānqì): "thời tiết".', '今天天气怎么样？', 'Jīntiān tiānqì zěnmeyàng?', 'Hôm nay thời tiết như thế nào?', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v15_3', 'lesson-15', '大风', 'dàfēng', 'đại phong', 'gió to, gió lớn', 'Danh từ', '大 (Đại) (To lớn, vĩ đại)', '大: Bộ 大 (Đại - người dang rộng tay chân, chữ độc thể) • 风: Bộ 风 (Phong - khung gió và nét phẩy chấm, chữ độc thể)', 'Ghép 大 [bộ 大] + 风 [bộ 风] để nhớ từ 大风 (dàfēng): "gió to, gió lớn".', '北京的春天很暖和，不常下雨，有时候刮大风。', 'Běijīng de chūntiān hěn nuǎnhuo, bù cháng xiàyǔ, yǒushíhou guā dàfēng.', 'Mùa xuân ở Bắc Kinh rất ấm áp, ít khi mưa, thỉnh thoảng có gió lớn.', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v15_4', 'lesson-15', '雪', 'xuě', 'tuyết', 'tuyết', 'Danh từ', '雨 (Vũ) (Mưa, sương, tuyết, hiện tượng thời tiết)', '雪 = 雨 (Vũ: mưa) + 彐 (Kệ: kết thành bông tuyết).', 'Chữ 雪 (xuě) mang nghĩa "tuyết", bộ chính 雨 (Vũ); cấu tạo: 雨 (Vũ: mưa) + 彐 (Kệ: kết thành bông tuyết).', '常下雪吗？', 'Cháng xiàxuě ma?', 'Có hay có tuyết rơi không?', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v15_5', 'lesson-15', '季节', 'jìjié', 'quý tiết', 'mùa', 'Danh từ', '子 (Tử) (Đứa con, trẻ nhỏ, người trí thức)', '季: 禾 (Hòa: cây lúa non) + 子 (Tử: mùa màng non trẻ) • 节: 艹 (Thảo: đốt trúc/cỏ cây) + 卩 (Tiết)', 'Ghép 季 [bộ 子] + 节 [bộ 艹] để nhớ từ 季节 (jìjié): "mùa".', '张风，北京有几个季节？', 'Zhāng Fēng, Běijīng yǒu jǐ gè jìjié?', 'Trương Phong, Bắc Kinh có mấy mùa?', 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v15_6', 'lesson-15', '零下', 'língxià', 'hạ', 'dưới 0 độ', 'Cụm từ / Tên riêng', '雨 (Vũ) (Mưa, sương, tuyết, hiện tượng thời tiết)', '零: 雨 (Vũ: giọt mưa) + 令 (Lệnh) • 下: Nét ngang 一 phía trên nét sổ 丨 và chấm chỉ hướng xuống dưới', 'Ghép 零 [bộ 雨] + 下 [bộ 一] để nhớ từ 零下 (língxià): "dưới 0 độ".', '是。北京的冬天比较冷，最冷差不多零下二十二度。', 'Shì. Běijīng de dōngtiān bǐjiào lěng, zuì lěng chàbùduō língxià èrshíèr dù.', 'Đúng vậy. Mùa đông Bắc Kinh khá lạnh, lạnh nhất khoảng âm 22 độ.', 6) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v15_7', 'lesson-15', '春天', 'chūntiān', 'xuân thiên', 'mùa xuân', 'Danh từ', '日 (Nhật) (Mặt trời, ban ngày, thời gian, ánh sáng)', '春: 𡗗 (cây cỏ đâm chồi) + 日 (Nhật: nắng ấm mùa xuân) • 天: 一 (Nhất: bầu trời cao) + 大 (Đại: con người dang tay)', 'Ghép 春 [bộ 日] + 天 [bộ 大] để nhớ từ 春天 (chūntiān): "mùa xuân".', '北京有春天、夏天、秋天和冬天四个季节。', 'Běijīng yǒu chūntiān, xiàtiān, qiūtiān hé dōngtiān sì gè jìjié.', 'Bắc Kinh có bốn mùa: xuân, hạ, thu và đông.', 7) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v15_8', 'lesson-15', '夏天', 'xiàtiān', 'hạ thiên', 'mùa hè', 'Danh từ', '夂 (Trĩ) (Bước đi chậm, quay trở lại)', '夏: 一 + 自 (Tự) + 夂 (Trĩ) • 天: 一 (Nhất: bầu trời cao) + 大 (Đại: con người dang tay)', 'Ghép 夏 [bộ 夂] + 天 [bộ 大] để nhớ từ 夏天 (xiàtiān): "mùa hè".', '北京有春天、夏天、秋天和冬天四个季节。', 'Běijīng yǒu chūntiān, xiàtiān, qiūtiān hé dōngtiān sì gè jìjié.', 'Bắc Kinh có bốn mùa: xuân, hạ, thu và đông.', 8) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v15_9', 'lesson-15', '秋天', 'qiūtiān', 'thu thiên', 'mùa thu', 'Danh từ', '禾 (Hòa) (Cây lúa, ngũ cốc, thời vụ)', '秋: 禾 (Hòa: mùa lúa chín) + 火 (Hỏa: nắng gặt vàng rực) • 天: 一 (Nhất: bầu trời cao) + 大 (Đại: con người dang tay)', 'Ghép 秋 [bộ 禾] + 天 [bộ 大] để nhớ từ 秋天 (qiūtiān): "mùa thu".', '北京有春天、夏天、秋天和冬天四个季节。', 'Běijīng yǒu chūntiān, xiàtiān, qiūtiān hé dōngtiān sì gè jìjié.', 'Bắc Kinh có bốn mùa: xuân, hạ, thu và đông.', 9) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v15_10', 'lesson-15', '冬天', 'dōngtiān', 'đông thiên', 'mùa đông', 'Danh từ', '夂 (Trĩ) (Bước đi chậm, quay trở lại)', '冬: 夂 (Trĩ) + 冫 (Băng: giá lạnh mùa đông) • 天: 一 (Nhất: bầu trời cao) + 大 (Đại: con người dang tay)', 'Ghép 冬 [bộ 夂] + 天 [bộ 大] để nhớ từ 冬天 (dōngtiān): "mùa đông".', '北京有春天、夏天、秋天和冬天四个季节。', 'Běijīng yǒu chūntiān, xiàtiān, qiūtiān hé dōngtiān sì gè jìjié.', 'Bắc Kinh có bốn mùa: xuân, hạ, thu và đông.', 10) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v15_11', 'lesson-15', '度', 'dù', 'độ', 'độ', 'Danh từ', '广 (Nghiễm) (Mái nhà rộng, nơi công cộng)', '度 = 广 (Nghiễm) + 廿 + 又 (Hựu).', 'Chữ 度 (dù) mang nghĩa "độ", bộ chính 广 (Nghiễm); cấu tạo: 广 (Nghiễm) + 廿 + 又 (Hựu).', '是。北京的冬天比较冷，最冷差不多零下二十二度。', 'Shì. Běijīng de dōngtiān bǐjiào lěng, zuì lěng chàbùduō língxià èrshíèr dù.', 'Đúng vậy. Mùa đông Bắc Kinh khá lạnh, lạnh nhất khoảng âm 22 độ.', 11) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v15_12', 'lesson-15', '冷', 'lěng', 'lãnh', 'lạnh', 'Tính từ', '冫 (Băng) (Nước đá, lạnh giá)', '冷 = 冫 (Băng: nước đá) + 令 (Lệnh).', 'Chữ 冷 (lěng) mang nghĩa "lạnh", bộ chính 冫 (Băng); cấu tạo: 冫 (Băng: nước đá) + 令 (Lệnh).', '今天天气很冷。', 'Jīntiān tiānqì hěn lěng.', 'Hôm nay trời rất lạnh.', 12) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v15_13', 'lesson-15', '热', 'rè', 'nhiệt', 'nóng', 'Tính từ', '火/灬 (Hỏa) (Lửa, nhiệt độ, nấu nướng, nóng bức)', '热 = 执 (Chấp) + 灬 (Hỏa: ngọn lửa nóng rực).', 'Chữ 热 (rè) mang nghĩa "nóng", bộ chính 火/灬 (Hỏa); cấu tạo: 执 (Chấp) + 灬 (Hỏa: ngọn lửa nóng rực).', '今天比较热。', 'Jīntiān bǐjiào rè.', 'Hôm nay trời khá nóng.', 13) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v15_14', 'lesson-15', '舒服', 'shūfu', 'phục', 'thoải mái, dễ chịu', 'Tính từ', '舌 (Thiệt) (Cái lưỡi, lời nói, nếm vị)', '舒: 舍 (Xá) + 予 (Dư) • 服: 月 (Nguyệt) + 卩 + 又 (trang phục vừa vặn)', 'Ghép 舒 [bộ 舌] + 服 [bộ 月] để nhớ từ 舒服 (shūfu): "thoải mái, dễ chịu".', '北京的秋天不冷不热，很舒服，这是一年中最好的季节。', 'Běijīng de qiūtiān bù lěng bú rè, hěn shūfu, zhè shì yī nián zhōng zuì hǎo de jìjié.', 'Mùa thu Bắc Kinh không lạnh không nóng, rất dễ chịu, đây là mùa đẹp nhất trong năm.', 14) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v15_15', 'lesson-15', '暖和', 'nuǎnhuo', 'từ Hán ngữ', 'ấm áp', 'Tính từ', '日 (Nhật) (Mặt trời, ban ngày, thời gian, ánh sáng)', '暖: 日 (Nhật: ánh nắng) + 爰 (Viên: ấm áp) • 和: 禾 (Hòa: cây lúa) + 口 (Khẩu: ai cũng có cơm ăn là hòa bình)', 'Ghép 暖 [bộ 日] + 和 [bộ 口] để nhớ từ 暖和 (nuǎnhuo): "ấm áp".', '北京的春天很暖和，不常下雨，有时候刮大风。', 'Běijīng de chūntiān hěn nuǎnhuo, bù cháng xiàyǔ, yǒushíhou guā dàfēng.', 'Mùa xuân ở Bắc Kinh rất ấm áp, ít khi mưa, thỉnh thoảng có gió lớn.', 15) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v15_16', 'lesson-15', '刮 (风)', 'guā (fēng)', 'phong', 'thổi, nối (gió)', 'Động từ', '刀/刂 (Đao) (Con dao, cắt xẻ, phân chia)', '刮 = 舌 (Thiệt) + 刂 (Đao: lưỡi dao cạo/gió thổi rát).', 'Chữ 刮 (guā (fēng)) mang nghĩa "thổi, nối (gió)", bộ chính 刀/刂 (Đao); cấu tạo: 舌 (Thiệt) + 刂 (Đao: lưỡi dao cạo/gió thổi rát).', '这是关于“刮 (风)”的常用句子。', 'Zhè shì guānyú ''guā (fēng)'' de chángyòng jùzi.', 'Đây là câu ví dụ sử dụng từ ''刮 (风)'' (thổi, nối (gió)).', 16) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v15_17', 'lesson-15', '下雨', 'xià yǔ', 'hạ vũ', 'mưa', 'Động từ', '一 (Nhất) (Số một, nền tảng, nét ngang cơ bản)', '下: Nét ngang 一 phía trên nét sổ 丨 và chấm chỉ hướng xuống dưới • 雨: Bộ 雨 (Vũ - bầu trời và bốn giọt mưa rơi)', 'Ghép 下 [bộ 一] + 雨 [bộ 雨] để nhớ từ 下雨 (xià yǔ): "mưa".', '北京的春天很暖和，不常下雨，有时候刮大风。', 'Běijīng de chūntiān hěn nuǎnhuo, bù cháng xiàyǔ, yǒushíhou guā dàfēng.', 'Mùa xuân ở Bắc Kinh rất ấm áp, ít khi mưa, thỉnh thoảng có gió lớn.', 17) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v15_18', 'lesson-15', '下雪', 'xià xuě', 'hạ tuyết', 'tuyết rơi', 'Động từ', '一 (Nhất) (Số một, nền tảng, nét ngang cơ bản)', '下: Nét ngang 一 phía trên nét sổ 丨 và chấm chỉ hướng xuống dưới • 雪: 雨 (Vũ: mưa) + 彐 (Kệ: kết thành bông tuyết)', 'Ghép 下 [bộ 一] + 雪 [bộ 雨] để nhớ từ 下雪 (xià xuě): "tuyết rơi".', '常下雪吗？', 'Cháng xiàxuě ma?', 'Có hay có tuyết rơi không?', 18) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v15_19', 'lesson-15', '游泳', 'yóuyǒng', 'du', 'bơi', 'Động từ', '水/氵 (Thủy) (Nước, chất lỏng, sông ngòi)', '游: 氵 (Thủy: bơi lội trong nước) + 斿 • 泳: 氵 (Thủy: nước) + 永 (Vĩnh: bơi lội lâu dài)', 'Ghép 游 [bộ 氵] + 泳 [bộ 氵] để nhớ từ 游泳 (yóuyǒng): "bơi".', '我最喜欢夏天。因为我喜欢游泳。小明，你呢？', 'Wǒ zuì xǐhuan xiàtiān. Yīnwèi wǒ xǐhuan yóuyǒng. Xiǎomíng, nǐ ne?', 'Tôi thích mùa hè nhất. Vì tôi thích bơi lội. Còn bạn thì sao, Tiểu Minh?', 19) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v15_20', 'lesson-15', '滑雪', 'huáxuě', 'tuyết', 'trượt tuyết', 'Động từ', '水/氵 (Thủy) (Nước, chất lỏng, sông ngòi)', '滑: 氵 (Thủy: nước) + 骨 (Cốt: trơn trượt) • 雪: 雨 (Vũ: mưa) + 彐 (Kệ: kết thành bông tuyết)', 'Ghép 滑 [bộ 氵] + 雪 [bộ 雨] để nhớ từ 滑雪 (huáxuě): "trượt tuyết".', '常下雪。冬天的时候我经常跟朋友去滑冰、滑雪。特别好玩儿。', 'Cháng xiàxuě. Dōngtiān de shíhou wǒ jīngcháng gēn péngyou qù huábīng, huáxuě. Tèbié hǎowánr.', 'Thường hay có tuyết rơi. Vào mùa đông tôi hay đi trượt băng, trượt tuyết cùng bạn bè. Vui lắm.', 20) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v15_21', 'lesson-15', '滑冰', 'huábīng', 'từ Hán ngữ', 'trượt băng', 'Động từ', '水/氵 (Thủy) (Nước, chất lỏng, sông ngòi)', '滑: 氵 (Thủy: nước) + 骨 (Cốt: trơn trượt) • 冰: 冫 (Băng: kết tinh băng giá) + 水 (Thủy: nước)', 'Ghép 滑 [bộ 氵] + 冰 [bộ 冫] để nhớ từ 滑冰 (huábīng): "trượt băng".', '常下雪。冬天的时候我经常跟朋友去滑冰、滑雪。特别好玩儿。', 'Cháng xiàxuě. Dōngtiān de shíhou wǒ jīngcháng gēn péngyou qù huábīng, huáxuě. Tèbié hǎowánr.', 'Thường hay có tuyết rơi. Vào mùa đông tôi hay đi trượt băng, trượt tuyết cùng bạn bè. Vui lắm.', 21) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v15_22', 'lesson-15', '差不多', 'chàbuduō', 'sai đa', 'hầu hết, xấp xỉ', 'Phó từ', '工 (Công) (Công việc, kỹ thuật, thợ thủ công)', '差: 羊 (Dương biến thể) + 工 (Công) • 不: 一 (Nhất) + 丿 + 丨 + 丶 (chữ độc thể phủ định) • 多: 夕 (Tịch) + 夕 (Tịch: nhiều lớp chồng nhau)', 'Ghép 差 [bộ 工] + 不 [bộ 一] + 多 [bộ 夕] để nhớ từ 差不多 (chàbuduō): "hầu hết, xấp xỉ".', '是。北京的冬天比较冷，最冷差不多零下二十二度。', 'Shì. Běijīng de dōngtiān bǐjiào lěng, zuì lěng chàbùduō língxià èrshíèr dù.', 'Đúng vậy. Mùa đông Bắc Kinh khá lạnh, lạnh nhất khoảng âm 22 độ.', 22) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v15_23', 'lesson-15', '比较', 'bǐjiào', 'từ Hán ngữ', 'tương đối, khá', 'Phó từ', '比 (Tỷ) (So sánh, kề bên)', '比: Bộ 比 (Tỷ - hai người đứng cạnh so sánh) • 较: 车 (Xa: xe) + 交 (Giao)', 'Ghép 比 [bộ 比] + 较 [bộ 车] để nhớ từ 比较 (bǐjiào): "tương đối, khá".', '我比较累，想睡觉了！', 'Wǒ bǐjiào lèi, xiǎng shuìjiào le!', 'Tôi khá mệt, muốn đi ngủ rồi!', 23) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v15_24', 'lesson-15', '不常', 'bù cháng', 'từ Hán ngữ', 'không thường xuyên, ít khi', 'Phó từ', '一 (Nhất) (Số một, nền tảng, nét ngang cơ bản)', '不: 一 (Nhất) + 丿 + 丨 + 丶 (chữ độc thể phủ định) • 常: 尚 (Thượng) + 巾 (Cân: mảnh vải mặc thường ngày)', 'Ghép 不 [bộ 一] + 常 [bộ 巾] để nhớ từ 不常 (bù cháng): "không thường xuyên, ít khi".', '北京的春天很暖和，不常下雨，有时候刮大风。', 'Běijīng de chūntiān hěn nuǎnhuo, bù cháng xiàyǔ, yǒushíhou guā dàfēng.', 'Mùa xuân ở Bắc Kinh rất ấm áp, ít khi mưa, thỉnh thoảng có gió lớn.', 24) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v15_25', 'lesson-15', '不', 'bù', 'từ Hán ngữ', 'không (phó từ biểu thị sự phủ định)', 'Phó từ', '一 (Nhất) (Số một, nền tảng, nét ngang cơ bản)', '不 = 一 (Nhất) + 丿 + 丨 + 丶 (chữ độc thể phủ định).', 'Chữ 不 (bù) mang nghĩa "không (phó từ biểu thị sự phủ định)", bộ chính 一 (Nhất); cấu tạo: 一 (Nhất) + 丿 + 丨 + 丶 (chữ độc thể phủ định).', '他的考试成绩不怎么样。', 'Tā de kǎoshì chéngjì bù zěnmeyàng.', 'Thành tích kiểm tra của anh ấy chẳng ra làm sao. (Ý nói kết quả kém)', 25) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v15_26', 'lesson-15', '特别', 'tèbié', 'từ Hán ngữ', 'đặc biệt, cực kì', 'Phó từ', '牛/牜 (Ngưu) (Con trâu, bò, gia súc)', '特: 牜 (Ngưu: con bò tế lễ riêng) + 寺 (Tự) • 别: 口 (Khẩu) + 力 (Lực) + 刂 (Đao: cắt phân biệt)', 'Ghép 特 [bộ 牛] + 别 [bộ 刂] để nhớ từ 特别 (tèbié): "đặc biệt, cực kì".', '冬天是不是特别冷？', 'Dōngtiān shì bu shì tèbié lěng?', 'Mùa đông có phải rất lạnh không?', 26) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v15_27', 'lesson-15', '因为', 'yīnwèi', 'từ Hán ngữ', 'bởi vì', 'Liên từ', '囗 (Vi) (Vây quanh, không gian kín, lãnh thổ)', '因: 囗 (Vi: khung bao) + 大 (Đại: người nằm trong) • 为: 丶 + 丿 + 𠃌 + 丶 (làm việc, vì)', 'Ghép 因 [bộ 囗] + 为 [bộ 丶] để nhớ từ 因为 (yīnwèi): "bởi vì".', '我最喜欢夏天。因为我喜欢游泳。小明，你呢？', 'Wǒ zuì xǐhuan xiàtiān. Yīnwèi wǒ xǐhuan yóuyǒng. Xiǎomíng, nǐ ne?', 'Tôi thích mùa hè nhất. Vì tôi thích bơi lội. Còn bạn thì sao, Tiểu Minh?', 27) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order) VALUES ('g15_1', 'lesson-15', '1. Đại từ nghi vấn “怎么样” và câu vị ngữ tính từ', 'Cấu trúc:   Chủ ngữ + Tính từ', ' * 怎么样 Đại từ nghi vấn 怎么样 đặt ở cuối câu nghi vấn, dùng để hỏi về tình hình tính chất của một sự vật, sự việc như thời tiết, sức khỏe, học tập..., vật trừu tượng như cảm xúc, tâm trạng.... hoặc biểu thị ý trưng cầu ý kiến và cũng có thể đứng sau độn', NULL, '[{"hanzi":"今天天气怎么样？","pinyin":"Jīntiān tiānqì zěnmeyàng?","meaning":"Hôm nay thời tiết như thế nào?"},{"hanzi":"你现在觉得怎么样？","pinyin":"Nǐ xiànzài juéde zěnmeyàng?","meaning":"Bây giờ cậu cảm thấy thế nào?"}]'::jsonb, 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order) VALUES ('g15_2', 'lesson-15', '2. 比较', 'Cấu trúc câu ngữ pháp trọng tâm', ' 比较 vừa là phó từ vừa là động từ. * Trường hợp 1: 比较 là phó từ chỉ mức độ, mang nghĩa “khá, tương đối”, dùng trước tính từ biểu thị đánh giá mức độ. 我比较累，想睡觉了！ Wǒ bǐjiào lèi, xiǎng shuìjiào le! Tôi khá mệt, muốn đi ngủ rồi! 今天比较热。 Jīntiān bǐjiào rè. ', NULL, '[{"hanzi":"你身体怎么样了？","pinyin":"Nǐ shēntǐ zěnmeyàng le?","meaning":"Cơ thể con sao rồi?"},{"hanzi":"他的考试成绩不怎么样。","pinyin":"Tā de kǎoshì chéngjì bù zěnmeyàng.","meaning":"Thành tích kiểm tra của anh ấy chẳng ra làm sao. (Ý nói kết quả kém)"}]'::jsonb, 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order) VALUES ('g15_3', 'lesson-15', '3. 不......不......', 'Cấu trúc câu ngữ pháp trọng tâm', ' 不...... 不...... là cấu trúc biểu thị các nghĩa khác nhau: * Trường hợp 1: Biểu thị mức độ vừa phải, sau thường là hai tính từ có nghĩa trái ngược nhau. 这件衣服不大不小。 Zhè jiàn yīfu bú dà bù xiǎo. Bộ quần áo này không to cũng không nhỏ. 不早不晚，很准时！ Bù zǎo b', NULL, '[{"hanzi":"他是个不怎么样的人。","pinyin":"Tā shì gè bù zěnme yàng de rén.","meaning":"Anh ta là người chẳng ra gì."},{"hanzi":"今天天气很冷。","pinyin":"Jīntiān tiānqì hěn lěng.","meaning":"Hôm nay trời rất lạnh."}]'::jsonb, 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order;
INSERT INTO texts (id, lesson_id, title, description, sort_order) VALUES ('txt_15_1', 'lesson-15', 'Bài khoá #1: Hội thoại giáo trình — Thời tiết ở Bắc Kinh', 'Hội thoại chuẩn giáo trình Bài 15. Từ vựng chưa học được chú thích phiên âm & nghĩa trong ngoặc.', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_15_1_1', 'txt_15_1', '阮日明', '张风，北京有几个季节？', '张风，北京有几个季节？', 'Zhāng Fēng, Běijīng yǒu jǐ gè jìjié?', 'Trương Phong, Bắc Kinh có mấy mùa?', 1) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_15_1_2', 'txt_15_1', '张风', '北京有春天、夏天、秋天和冬天四个季节。', '北京有春天、夏天、秋天和冬天四个季节。', 'Běijīng yǒu chūntiān, xiàtiān, qiūtiān hé dōngtiān sì gè jìjié.', 'Bắc Kinh có bốn mùa: xuân, hạ, thu và đông.', 2) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_15_1_3', 'txt_15_1', '阮日明', '北京的春天怎么样？', '北京的春天怎么样？', 'Běijīng de chūntiān zěnmeyàng?', 'Mùa xuân ở Bắc Kinh thế nào?', 3) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_15_1_4', 'txt_15_1', '张风', '北京的春天很暖和，不常下雨，有时候刮大风。', '北京的春天很暖和，不常下雨，有时候刮大风。', 'Běijīng de chūntiān hěn nuǎnhuo, bù cháng xiàyǔ, yǒushíhou guā dàfēng.', 'Mùa xuân ở Bắc Kinh rất ấm áp, ít khi mưa, thỉnh thoảng có gió lớn.', 4) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_15_1_5', 'txt_15_1', '阮日明', '夏天怎么样？热么？', '夏天怎么样？热么？', 'Xiàtiān zěnmeyàng? Rè ma?', 'Mùa hạ thì sao? Có nóng không?', 5) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_15_1_6', 'txt_15_1', '张风', '夏天天气不太热。最热的时候是七月，七月和八月经常下雨。', '夏天天气不太热。最热的时候是七月，七月和八月经常下雨。', 'Xiàtiān tiānqì bú tài rè. Zuì rè de shíhou shì qī yuè, qī yuè hé bā yuè jīngcháng xià yǔ.', 'Thời tiết mùa hè không quá nóng. Nóng nhất là vào tháng 7, tháng 7 và tháng 8 thường hay mưa.', 6) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_15_1_7', 'txt_15_1', '阮日明', '秋天呢？', '秋天呢？', 'Qiūtiān ne?', 'Còn mùa thu thì sao?', 7) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_15_1_8', 'txt_15_1', '张风', '北京的秋天不冷不热，很舒服，这是一年中最好的季节。', '北京的秋天不冷不热，很舒服，这是一年中 (zhōng: giữa / trong)最好的季节。', 'Běijīng de qiūtiān bù lěng bú rè, hěn shūfu, zhè shì yī nián zhōng zuì hǎo de jìjié.', 'Mùa thu Bắc Kinh không lạnh không nóng, rất dễ chịu, đây là mùa đẹp nhất trong năm.', 8) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_15_1_9', 'txt_15_1', '阮日明', '冬天是不是特别冷？', '冬天是不是特别冷？', 'Dōngtiān shì bu shì tèbié lěng?', 'Mùa đông có phải rất lạnh không?', 9) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_15_1_10', 'txt_15_1', '张风', '是。北京的冬天比较冷，最冷差不多零下二十二度。', '是。北京的冬天比较冷，最冷差不多零下二十二度。', 'Shì. Běijīng de dōngtiān bǐjiào lěng, zuì lěng chàbùduō língxià èrshíèr dù.', 'Đúng vậy. Mùa đông Bắc Kinh khá lạnh, lạnh nhất khoảng âm 22 độ.', 10) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_15_1_11', 'txt_15_1', '阮日明', '常下雪吗？', '常下雪吗？', 'Cháng xiàxuě ma?', 'Có hay có tuyết rơi không?', 11) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_15_1_12', 'txt_15_1', '张风', '常下雪。冬天的时候我经常跟朋友去滑冰、滑雪。特别好玩儿。', '常下雪。冬天的时候我经常跟 (gēn: cùng, với)朋友去滑冰、滑雪。特别好玩儿。', 'Cháng xiàxuě. Dōngtiān de shíhou wǒ jīngcháng gēn péngyou qù huábīng, huáxuě. Tèbié hǎowánr.', 'Thường hay có tuyết rơi. Vào mùa đông tôi hay đi trượt băng, trượt tuyết cùng bạn bè. Vui lắm.', 12) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_15_1_13', 'txt_15_1', '阮日明', '你最喜欢哪个季节？', '你最喜欢哪个季节？', 'Nǐ zuì xǐhuan nǎge jìjié?', 'Bạn thích mùa nào nhất?', 13) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_15_1_14', 'txt_15_1', '张风', '我最喜欢夏天。因为我喜欢游泳。小明，你呢？', '我最喜欢夏天。因为我喜欢游泳。小明 (míng: ngày mai, sáng)，你呢？', 'Wǒ zuì xǐhuan xiàtiān. Yīnwèi wǒ xǐhuan yóuyǒng. Xiǎomíng, nǐ ne?', 'Tôi thích mùa hè nhất. Vì tôi thích bơi lội. Còn bạn thì sao, Tiểu Minh?', 14) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_15_1_15', 'txt_15_1', '阮日明', '我最喜欢春天。', '我最喜欢春天。', 'Wǒ zuì xǐhuan chūntiān.', 'Tôi thích mùa xuân nhất.', 15) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_15_1_1', 'lesson-15', 'txt_15_1', 'listening', 'listening', '张风，北京有几个季节？', NULL, 'Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Trương Phong, Bắc Kinh có mấy mùa?","Thời tiết dễ chịu quá!","Bạn nên nghe nhiều, nói nhiều, đọc nhiều và viết nhiều.","Nếu chăm chỉ học hành thì bạn sẽ có thể thi đỗ đại học."]'::jsonb, 0, 'Nội dung nghe được: 张风，北京有几个季节？ (Zhāng Fēng, Běijīng yǒu jǐ gè jìjié?) → Trương Phong, Bắc Kinh có mấy mùa?', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_15_1_2', 'lesson-15', 'txt_15_1', 'listening', 'listening', '北京有春天、夏天、秋天和冬天四个季节。', NULL, 'Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["我比较累 (lèi: mệt, mệt mỏi)，想睡 (shuì: ngủ)觉 (jiào: giấc ngủ)了！","不早 (zǎo: sớm)不晚 (wǎn: muộn, tối)，很准时 (zhǔnshí: đúng giờ)！","北京有春天、夏天、秋天和冬天四个季节。","今天天气怎么样？"]'::jsonb, 2, 'Câu vừa đọc: 北京有春天、夏天、秋天和冬天四个季节。 (Běijīng yǒu chūntiān, xiàtiān, qiūtiān hé dōngtiān sì gè jìjié.) → Bắc Kinh có bốn mùa: xuân, hạ, thu và đông.', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_15_1_3', 'lesson-15', 'txt_15_1', 'listening', 'listening', '北京的春天怎么样？', NULL, 'Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["quần jean","Mùa xuân ở Bắc Kinh thế nào?","anh em tốt","Sao sớm như thế này con đã dậy rồi?"]'::jsonb, 1, 'Nội dung nghe được: 北京的春天怎么样？ (Běijīng de chūntiān zěnmeyàng?) → Mùa xuân ở Bắc Kinh thế nào?', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_15_1_4', 'lesson-15', 'txt_15_1', 'listening', 'listening', '北京的春天很暖和，不常下雨，有时候刮大风。', NULL, 'Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["北京有春天、夏天、秋天和冬天四个季节。","北京的春天怎么样？","不醉不归！","北京的春天很暖和，不常下雨，有时候刮大风。"]'::jsonb, 3, 'Câu vừa đọc: 北京的春天很暖和，不常下雨，有时候刮大风。 (Běijīng de chūntiān hěn nuǎnhuo, bù cháng xiàyǔ, yǒushíhou guā dàfēng.) → Mùa xuân ở Bắc Kinh rất ấm áp, ít khi mưa, thỉnh thoảng có gió lớn.', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO texts (id, lesson_id, title, description, sort_order) VALUES ('txt_15_2', 'lesson-15', 'Bài nghe tổng hợp: Ôn tập lũy tiến (Bài 1 – Bài 15)', 'Kết hợp từ vựng & mẫu câu đã học từ Bài 1 đến Bài 14 cùng trọng tâm Bài 15 để củng cố phản xạ nghe.', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_15_2_1', 'txt_15_2', 'Ôn Bài 14', '我有一个哥哥和一个妹妹。', '我有一个哥哥和一个妹妹。', 'Wǒ yǒu yígè gēge hé yígè mèimei.', 'Tôi có một anh trai và một em gái.', 1) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_15_2_2', 'txt_15_2', 'Bài 15', '今天天气怎么样？', '今天天气怎么样？', 'Jīntiān tiānqì zěnmeyàng?', 'Hôm nay thời tiết như thế nào?', 2) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_15_2_3', 'txt_15_2', 'Ôn Bài 7', '那本词典', '那本词典', 'nà běn cídiǎn', 'quyển từ điển kia', 3) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_15_2_4', 'txt_15_2', 'Bài 15', '你现在觉得怎么样？', '你现在觉得怎么样？', 'Nǐ xiànzài juéde zěnmeyàng?', 'Bây giờ cậu cảm thấy thế nào?', 4) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_15_2_5', 'txt_15_2', 'Ôn Bài 1', '晚上好！', '晚上好！', 'Wǎnshang hǎo', 'Chào buổi tối!', 5) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_15_2_6', 'txt_15_2', 'Bài 15', '他是个不怎么样的人。', '他是个不怎么样的人。', 'Tā shì gè bù zěnme yàng de rén.', 'Anh ta là người chẳng ra gì.', 6) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_15_2_7', 'txt_15_2', 'Ôn Bài 12', '我真不喜欢！', '我真不喜欢！', 'Wǒ zhēn bù xǐhuan!', 'Tôi thực sự không thích!', 7) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_15_2_8', 'txt_15_2', 'Bài 15', '今天天气很冷。', '今天天气很冷。', 'Jīntiān tiānqì hěn lěng.', 'Hôm nay trời rất lạnh.', 8) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_15_2_1', 'lesson-15', 'txt_15_2', 'listening', 'listening', '我有一个哥哥和一个妹妹。', NULL, '[Ôn tập Bài 14] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Tôi có một anh trai và một em gái.","Một việc/chuyện","Kỳ học này tôi kiểm tra một lần rồi.","Cô ấy không phải là học sinh à?"]'::jsonb, 0, 'Nội dung nghe được: 我有一个哥哥和一个妹妹。 (Wǒ yǒu yígè gēge hé yígè mèimei.) → Tôi có một anh trai và một em gái.', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_15_2_2', 'lesson-15', 'txt_15_2', 'listening', 'listening', '今天天气怎么样？', NULL, '[Bài 15] Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["你身体 (shēntǐ: cơ thể)怎么样了？","他的考试 (kǎoshì: thi, kiểm tra)成绩 (chéngjì: thành tích)不怎么样。","一年有四个季节，你最喜欢哪个季节？","今天天气怎么样？"]'::jsonb, 3, 'Câu vừa đọc: 今天天气怎么样？ (Jīntiān tiānqì zěnmeyàng?) → Hôm nay thời tiết như thế nào?', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_15_2_3', 'lesson-15', 'txt_15_2', 'listening', 'listening', '那本词典', NULL, '[Ôn tập Bài 7] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Tôi so sánh đáp án với anh ấy.","Mùa thu ở Bắc Kinh mát mẻ hơn mùa hè nhiều.","Con bị ốm rồi, khó chịu quá! (Biểu thị sự thay đổi của trạng thái)","quyển từ điển kia"]'::jsonb, 3, 'Nội dung nghe được: 那本词典 (nà běn cídiǎn) → quyển từ điển kia', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_15_2_4', 'lesson-15', 'txt_15_2', 'listening', 'listening', '你现在觉得怎么样？', NULL, '[Bài 15] Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["北京的春天很暖和，不常下雨，有时候刮大风。","今天比较热。","你现在觉得怎么样？","这件 (jiàn: cái, chiếc (áo, việc))衣服不大 (dà: to, lớn)不小。"]'::jsonb, 2, 'Câu vừa đọc: 你现在觉得怎么样？ (Nǐ xiànzài juéde zěnmeyàng?) → Bây giờ cậu cảm thấy thế nào?', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_15_2_5', 'lesson-15', 'txt_15_2', 'listening', 'listening', '晚上好！', NULL, '[Ôn tập Bài 1] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Chào buổi tối!","Mùa xuân ở Bắc Kinh rất ấm áp, ít khi mưa, thỉnh thoảng có gió lớn.","Tớ bảo mình không phải người Hà Nội lúc nào? (Tớ là người Hà Nội)","Chạy một chuyến"]'::jsonb, 0, 'Nội dung nghe được: 晚上好！ (Wǎnshang hǎo) → Chào buổi tối!', 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO texts (id, lesson_id, title, description, sort_order) VALUES ('txt_15_3', 'lesson-15', 'Bài khoá mở rộng: Dự báo thời tiết cuối tuần ở Bắc Kinh (Mở rộng)', 'Hội thoại tình huống mới xây dựng dựa trên từ vựng và ngữ pháp Bài 15 (không trùng lặp nguyên văn giáo trình).', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_15_3_1', 'txt_15_3', 'Phong', '小雪，明天北京的天气怎么样？', '小雪 (Xiǎoxuě: Tiểu Tuyết)，明天北京的天气怎么样？', 'Xiǎoxuě, míngtiān Běijīng de tiānqì zěnmeyàng?', 'Tiểu Tuyết, ngày mai thời tiết ở Bắc Kinh thế nào?', 1) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_15_3_2', 'txt_15_3', 'Tuyết', '明天刮大风，也很冷，温度大概零下八度。', '明天刮大风，也很冷，温度大概 (dàgài: đại khái, khoảng)零下八度。', 'Míngtiān guā dàfēng, yě hěn lěng, wēndù dàgài língxià bā dù.', 'Ngày mai có gió lớn và rất lạnh, nhiệt độ khoảng âm 8 độ.', 2) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_15_3_3', 'txt_15_3', 'Phong', '会下雪吗？我想周末和朋友去滑雪。', '会 (huì: Phó, đtnn biết)下雪吗？我想周末和朋友去滑雪。', 'Huì xiàxuě ma? Wǒ xiǎng zhōumò hé péngyou qù huáxuě.', 'Có tuyết rơi không? Cuối tuần tớ muốn đi trượt tuyết cùng bạn bè.', 3) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_15_3_4', 'txt_15_3', 'Tuyết', '后天会下大雪，你们出去玩儿要多穿点儿大衣！', '后 (hòu: sau)天 (tiān: ngày, trời)会 (huì: Phó, đtnn biết)下 (xià: dưới / xuống)大 (dà: to, lớn)雪，你们出去 (chūqù: ra ngoài)玩儿要多穿 (chuān: mặc)点儿 (ér: con, (âm uốn lưỡi))大衣！', 'Hòutiān huì xià dàxuě, nǐmen chūqù wánr yào duō chuān diǎnr dàyī!', 'Ngày kia sẽ có tuyết rơi lớn, các cậu ra ngoài chơi nhớ mặc thêm áo khoác nhé!', 4) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_15_3_1', 'lesson-15', 'txt_15_3', 'listening', 'listening', '小雪，明天北京的天气怎么样？ 明天刮大风，也很冷，温度大概零下八度。 会下雪吗？我想周末和朋友去滑雪。 后天会下大雪，你们出去玩儿要多穿点儿大衣！', NULL, '[Nghe hiểu tình huống mới] Theo Tiểu Tuyết, thời tiết ngày mai ở Bắc Kinh sẽ như thế nào?', '["Nắng ấm dễ chịu khoảng 22 độ","Không gió, rất nóng","Mưa rào mùa hè","Có gió lớn, rất lạnh, khoảng âm 8 độ"]'::jsonb, 3, 'Tiểu Tuyết nói rõ: ''明天刮大风，也很冷，温度大概零下八度''.', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_15_3_2', 'lesson-15', 'txt_15_3', 'listening', 'listening', '小雪，明天北京的天气怎么样？', NULL, '[Mở rộng] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Phía sau (của) Lan","bên trái (của) trường học","Tiểu Tuyết, ngày mai thời tiết ở Bắc Kinh thế nào?","Học sinh trung học không được phép hút thuốc."]'::jsonb, 2, 'Nội dung nghe được: 小雪，明天北京的天气怎么样？ (Xiǎoxuě, míngtiān Běijīng de tiānqì zěnmeyàng?) → Tiểu Tuyết, ngày mai thời tiết ở Bắc Kinh thế nào?', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_15_3_3', 'lesson-15', 'txt_15_3', 'listening', 'listening', '明天刮大风，也很冷，温度大概零下八度。', NULL, '[Mở rộng] Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["今天刮大风，温度只有零下五度。","今天天气很冷。","北京的秋天比夏天凉快 (kuài: nhanh)得 (děi: phải)多。","明天刮大风，也很冷，温度大概 (dàgài: đại khái, khoảng)零下八度。"]'::jsonb, 3, 'Câu vừa đọc: 明天刮大风，也很冷，温度大概零下八度。 (Míngtiān guā dàfēng, yě hěn lěng, wēndù dàgài língxià bā dù.) → Ngày mai có gió lớn và rất lạnh, nhiệt độ khoảng âm 8 độ.', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_15_3_4', 'lesson-15', 'txt_15_3', 'listening', 'listening', '会下雪吗？我想周末和朋友去滑雪。', NULL, '[Mở rộng] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Có tuyết rơi không? Cuối tuần tớ muốn đi trượt tuyết cùng bạn bè.","Mùa thu Bắc Kinh không lạnh không nóng, rất dễ chịu, đây là mùa đẹp nhất trong năm.","đất nước (quốc gia) của chúng tôi","Lúc mẹ nấu cơm thì tôi đang tắm."]'::jsonb, 0, 'Nội dung nghe được: 会下雪吗？我想周末和朋友去滑雪。 (Huì xiàxuě ma? Wǒ xiǎng zhōumò hé péngyou qù huáxuě.) → Có tuyết rơi không? Cuối tuần tớ muốn đi trượt tuyết cùng bạn bè.', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss15_1', 'lesson-15', '我觉得春天的天气最暖和最舒服', '[Mở rộng] Tôi thấy thời tiết mùa xuân ấm áp và dễ chịu nhất.', 'Wǒ juéde chūntiān de tiānqì zuì nuǎnhuo, zuì shūfu.', '["我觉得","春天的","天气最","暖和","最","舒服"]'::jsonb, NULL, 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss15_2', 'lesson-15', '北京的冬天很冷常常下雪', '[Mở rộng] Mùa đông ở Bắc Kinh rất lạnh, thường xuyên có tuyết rơi.', 'Běijīng de dōngtiān hěn lěng, chángcháng xiàxuě.', '["北京的","冬天","很","冷","常常","下雪"]'::jsonb, 'Từ chưa học: 常常 (chángcháng: thường)', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss15_3', 'lesson-15', '今天天气怎么样', 'Hôm nay thời tiết như thế nào?', 'Jīntiān tiānqì zěnmeyàng?', '["今天","天气","怎么样"]'::jsonb, NULL, 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss15_4', 'lesson-15', '你现在觉得怎么样', 'Bây giờ cậu cảm thấy thế nào?', 'Nǐ xiànzài juéde zěnmeyàng?', '["你","现在","觉得","怎么样"]'::jsonb, NULL, 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss15_5', 'lesson-15', '安妮是我的好朋友', '[Ôn tập Bài 3] Annie là bạn thân của tôi.', 'Ānnī shì wǒ de hǎo péngyou.', '["安妮","是","我","的","好","朋友"]'::jsonb, NULL, 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss15_6', 'lesson-15', '图书馆前面是我常去的地方', '[Ôn tập Bài 4] Phía trước thư viện là nơi tôi thường đến.', 'Túshūguǎn qiánmian shì wǒ cháng qù de dìfang.', '["图书馆","前面","是我","常","去的","地方"]'::jsonb, NULL, 6) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss15_exp_1', 'lesson-15', '张风北京有几个季节', 'Trương Phong, Bắc Kinh có mấy mùa?', 'Zhāng Fēng, Běijīng yǒu jǐ gè jìjié?', '["张风","北京","有","几","个","季节"]'::jsonb, NULL, 7) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss15_exp_2', 'lesson-15', '北京有春天夏天秋天和冬天四个季节', 'Bắc Kinh có bốn mùa: xuân, hạ, thu và đông.', 'Běijīng yǒu chūntiān, xiàtiān, qiūtiān hé dōngtiān sì gè jìjié.', '["北京","有","春天","夏天","秋天","和","冬天","四","个","季节"]'::jsonb, NULL, 8) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss15_exp_3', 'lesson-15', '北京的春天怎么样', 'Mùa xuân ở Bắc Kinh thế nào?', 'Běijīng de chūntiān zěnmeyàng?', '["北京","的","春天","怎么样"]'::jsonb, NULL, 9) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss15_exp_4', 'lesson-15', '北京的春天很暖和不常下雨有时候刮大风', 'Mùa xuân ở Bắc Kinh rất ấm áp, ít khi mưa, thỉnh thoảng có gió lớn.', 'Běijīng de chūntiān hěn nuǎnhuo, bù cháng xiàyǔ, yǒushíhou guā dàfēng.', '["北京","的","春天","很","暖和","不常","下雨","有","时候","刮","大风"]'::jsonb, NULL, 10) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss15_exp_5', 'lesson-15', '夏天怎么样热么', 'Mùa hạ thì sao? Có nóng không?', 'Xiàtiān zěnmeyàng? Rè ma?', '["夏天","怎么样","热","么"]'::jsonb, NULL, 11) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss15_exp_6', 'lesson-15', '夏天天气不太热最热的时候是七月七月和八月经常下雨', 'Thời tiết mùa hè không quá nóng. Nóng nhất là vào tháng 7, tháng 7 và tháng 8 thường hay mưa.', 'Xiàtiān tiānqì bú tài rè. Zuì rè de shíhou shì qī yuè, qī yuè hé bā yuè jīngcháng xià yǔ.', '["夏天","天气","不","太","热","最","热","的","时候","是","七","月","七","月","和","八","月","经常","下雨"]'::jsonb, NULL, 12) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss15_exp_7', 'lesson-15', '秋天呢', 'Còn mùa thu thì sao?', 'Qiūtiān ne?', '["秋天","呢"]'::jsonb, NULL, 13) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss15_exp_8', 'lesson-15', '北京的秋天不冷不热很舒服这是一年中最好的季节', 'Mùa thu Bắc Kinh không lạnh không nóng, rất dễ chịu, đây là mùa đẹp nhất trong năm.', 'Běijīng de qiūtiān bù lěng bú rè, hěn shūfu, zhè shì yī nián zhōng zuì hǎo de jìjié.', '["北京","的","秋天","不","冷","不","热","很","舒服","这","是","一","年","中","最","好","的","季节"]'::jsonb, NULL, 14) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss15_exp_9', 'lesson-15', '冬天是不是特别冷', 'Mùa đông có phải rất lạnh không?', 'Dōngtiān shì bu shì tèbié lěng?', '["冬天","是","不是","特别","冷"]'::jsonb, NULL, 15) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss15_exp_10', 'lesson-15', '是北京的冬天比较冷最冷差不多零下二十二度', 'Đúng vậy. Mùa đông Bắc Kinh khá lạnh, lạnh nhất khoảng âm 22 độ.', 'Shì. Běijīng de dōngtiān bǐjiào lěng, zuì lěng chàbùduō língxià èrshíèr dù.', '["是","北京","的","冬天","比较","冷","最","冷","差不多","零下","二","十","二","度"]'::jsonb, NULL, 16) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss15_exp_11', 'lesson-15', '常下雪吗', 'Có hay có tuyết rơi không?', 'Cháng xiàxuě ma?', '["常","下雪","吗"]'::jsonb, NULL, 17) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss15_exp_12', 'lesson-15', '常下雪冬天的时候我经常跟朋友去滑冰滑雪特别好玩儿', 'Thường hay có tuyết rơi. Vào mùa đông tôi hay đi trượt băng, trượt tuyết cùng bạn bè. Vui lắm.', 'Cháng xiàxuě. Dōngtiān de shíhou wǒ jīngcháng gēn péngyou qù huábīng, huáxuě. Tèbié hǎowánr.', '["常","下雪","冬天","的","时候","我","经常","跟","朋友","去","滑冰","滑雪","特别","好","玩儿"]'::jsonb, NULL, 18) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss15_exp_13', 'lesson-15', '你最喜欢哪个季节', 'Bạn thích mùa nào nhất?', 'Nǐ zuì xǐhuan nǎge jìjié?', '["你","最","喜欢","哪","个","季节"]'::jsonb, NULL, 19) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss15_exp_14', 'lesson-15', '我最喜欢夏天因为我喜欢游泳小明你呢', 'Tôi thích mùa hè nhất. Vì tôi thích bơi lội. Còn bạn thì sao, Tiểu Minh?', 'Wǒ zuì xǐhuan xiàtiān. Yīnwèi wǒ xǐhuan yóuyǒng. Xiǎomíng, nǐ ne?', '["我","最","喜欢","夏天","因为","我","喜欢","游泳","小","明","你","呢"]'::jsonb, NULL, 20) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr15_vi_1', 'lesson-15', 'vi_to_zh', '[Mở rộng] Tôi thấy thời tiết mùa xuân ấm áp và dễ chịu nhất.', NULL, NULL, '我觉得春天的天气最暖和、最舒服。', NULL, 'wǒ juéde chūntiān de tiānqì zuì nuǎnhuo zuì shūfu', '[]'::jsonb, 'Gợi ý Pinyin: Wǒ juéde chūntiān de tiānqì zuì nuǎnhuo, zuì shūfu.', 'Tôi thấy thời tiết mùa xuân ấm áp và dễ chịu nhất. → 我觉得春天的天气最暖和、最舒服。 (Wǒ juéde chūntiān de tiānqì zuì nuǎnhuo, zuì shūfu.)', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
