INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr15_vi_exp_6', 'lesson-15', 'vi_to_zh', 'Thời tiết mùa hè không quá nóng. Nóng nhất là vào tháng 7, tháng 7 và tháng 8 thường hay mưa.', NULL, NULL, '夏天天气不太热。最热的时候是七月，七月和八月经常下雨。', NULL, 'xiàtiān tiānqì bú tài rè zuì rè de shíhou shì qī yuè qī yuè hé bā yuè jīngcháng xià yǔ', '[]'::jsonb, 'Gợi ý Pinyin: Xiàtiān tiānqì bú tài rè. Zuì rè de shíhou shì qī yuè, qī yuè hé bā yuè jīngcháng xià yǔ.', 'Thời tiết mùa hè không quá nóng. Nóng nhất là vào tháng 7, tháng 7 và tháng 8 thường hay mưa. → 夏天天气不太热。最热的时候是七月，七月和八月经常下雨。 (Xiàtiān tiānqì bú tài rè. Zuì rè de shíhou shì qī yuè, qī yuè hé bā yuè jīngcháng xià yǔ.)', 10) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr15_vi_exp_7', 'lesson-15', 'vi_to_zh', 'Còn mùa thu thì sao?', NULL, NULL, '秋天呢？', NULL, 'qiūtiān ne', '[]'::jsonb, 'Gợi ý Pinyin: Qiūtiān ne?', 'Còn mùa thu thì sao? → 秋天呢？ (Qiūtiān ne?)', 11) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr15_vi_exp_8', 'lesson-15', 'vi_to_zh', 'Mùa thu Bắc Kinh không lạnh không nóng, rất dễ chịu, đây là mùa đẹp nhất trong năm.', NULL, NULL, '北京的秋天不冷不热，很舒服，这是一年中最好的季节。', NULL, 'běijīng de qiūtiān bù lěng bú rè hěn shūfu zhè shì yī nián zhōng zuì hǎo de jìjié', '[]'::jsonb, 'Gợi ý Pinyin: Běijīng de qiūtiān bù lěng bú rè, hěn shūfu, zhè shì yī nián zhōng zuì hǎo de jìjié.', 'Mùa thu Bắc Kinh không lạnh không nóng, rất dễ chịu, đây là mùa đẹp nhất trong năm. → 北京的秋天不冷不热，很舒服，这是一年中最好的季节。 (Běijīng de qiūtiān bù lěng bú rè, hěn shūfu, zhè shì yī nián zhōng zuì hǎo de jìjié.)', 12) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr15_vi_exp_9', 'lesson-15', 'vi_to_zh', 'Mùa đông có phải rất lạnh không?', NULL, NULL, '冬天是不是特别冷？', NULL, 'dōngtiān shì bu shì tèbié lěng', '[]'::jsonb, 'Gợi ý Pinyin: Dōngtiān shì bu shì tèbié lěng?', 'Mùa đông có phải rất lạnh không? → 冬天是不是特别冷？ (Dōngtiān shì bu shì tèbié lěng?)', 13) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr15_vi_exp_10', 'lesson-15', 'vi_to_zh', 'Đúng vậy. Mùa đông Bắc Kinh khá lạnh, lạnh nhất khoảng âm 22 độ.', NULL, NULL, '是。北京的冬天比较冷，最冷差不多零下二十二度。', NULL, 'shì běijīng de dōngtiān bǐjiào lěng zuì lěng chàbùduō língxià èrshíèr dù', '[]'::jsonb, 'Gợi ý Pinyin: Shì. Běijīng de dōngtiān bǐjiào lěng, zuì lěng chàbùduō língxià èrshíèr dù.', 'Đúng vậy. Mùa đông Bắc Kinh khá lạnh, lạnh nhất khoảng âm 22 độ. → 是。北京的冬天比较冷，最冷差不多零下二十二度。 (Shì. Běijīng de dōngtiān bǐjiào lěng, zuì lěng chàbùduō língxià èrshíèr dù.)', 14) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
