INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr15_zh_exp_5', 'lesson-15', 'zh_to_vi', '后天会下大雪，你们出去玩儿要多穿点儿大衣！', '后天会下大雪，你们出去玩儿要多穿点儿大衣！', 'Hòutiān huì xià dàxuě, nǐmen chūqù wánr yào duō chuān diǎnr dàyī!', NULL, 'Ngày kia sẽ có tuyết rơi lớn, các cậu ra ngoài chơi nhớ mặc thêm áo khoác nhé!', NULL, '["ngày","kia","sẽ","có","tuyết","rơi","lớn","các","cậu","ra","ngoài","chơi","nhớ","mặc","thêm","áo","khoác","nhé"]'::jsonb, 'Pinyin: Hòutiān huì xià dàxuě, nǐmen chūqù wánr yào duō chuān diǎnr dàyī!', '后天会下大雪，你们出去玩儿要多穿点儿大衣！ (Hòutiān huì xià dàxuě, nǐmen chūqù wánr yào duō chuān diǎnr dàyī!) nghĩa là: Ngày kia sẽ có tuyết rơi lớn, các cậu ra ngoài chơi nhớ mặc thêm áo khoác nhé!', 23) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr15_zh_exp_6', 'lesson-15', 'zh_to_vi', '会下雪吗？我想周末和朋友去滑雪。', '会下雪吗？我想周末和朋友去滑雪。', 'Huì xiàxuě ma? Wǒ xiǎng zhōumò hé péngyou qù huáxuě.', NULL, 'Có tuyết rơi không? Cuối tuần tớ muốn đi trượt tuyết cùng bạn bè.', NULL, '["có","tuyết","rơi","không","cuối","tuần","tớ","muốn","đi","trượt","tuyết","cùng","bạn","bè"]'::jsonb, 'Pinyin: Huì xiàxuě ma? Wǒ xiǎng zhōumò hé péngyou qù huáxuě.', '会下雪吗？我想周末和朋友去滑雪。 (Huì xiàxuě ma? Wǒ xiǎng zhōumò hé péngyou qù huáxuě.) nghĩa là: Có tuyết rơi không? Cuối tuần tớ muốn đi trượt tuyết cùng bạn bè.', 24) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
