INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct15_23', 'lesson-15', NULL, 'comprehensive_test', 'listening', '秋天呢？
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct15_24', 'lesson-15', NULL, 'comprehensive_test', 'listening', '小雪，明天北京的天气怎么样？ 明天刮大风，也很冷，温度大概零下八度。 会下雪吗？我想周末和朋友去滑雪。 后天会下大雪，你们出去玩儿要多穿点儿大衣！', NULL, 'Theo Tiểu Tuyết, thời tiết ngày mai ở Bắc Kinh sẽ như thế nào?', '["Nắng ấm dễ chịu khoảng 22 độ","Không gió, rất nóng","Mưa rào mùa hè","Có gió lớn, rất lạnh, khoảng âm 8 độ"]'::jsonb, 3, 'Tiểu Tuyết nói rõ: ''明天刮大风，也很冷，温度大概零下八度''.', 24) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
