INSERT INTO lessons (id, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id) VALUES ('lesson-16', 'Bài 16: Cuối tuần - Đơn nguyên 5: Kỳ nghỉ', 'Bài 16', 'Đơn nguyên 5: Kỳ nghỉ', 'Lên kế hoạch vui chơi cuối tuần, xem phim, cà phê, dã ngoại, liên từ 因为... 所以...', '2026-11-14'::date, 16, TRUE, NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, date_added = EXCLUDED.date_added, sort_order = EXCLUDED.sort_order, is_system = TRUE, updated_at = NOW();
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v16_1', 'lesson-16', '假期', 'jiàqī', 'giả kỳ', 'kỳ nghỉ', 'Danh từ', '人/亻 (Nhân) (Con người, nhân loại, hành động)', '假: 亻 (Nhân đứng) + 叚 (Giả) • 期: 其 (Kỳ) + 月 (Nguyệt: chu kỳ trăng tròn)', 'Ghép 假 [bộ 亻] + 期 [bộ 月] để nhớ từ 假期 (jiàqī): "kỳ nghỉ".', '这是关于“假期”的常用句子。', 'Zhè shì guānyú ''jiàqī'' de chángyòng jùzi.', 'Đây là câu ví dụ sử dụng từ ''假期'' (kỳ nghỉ).', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v16_2', 'lesson-16', '健身房', 'jiànshēnfáng', 'kiện thân', 'phòng gym', 'Danh từ', '人/亻 (Nhân) (Con người, nhân loại, hành động)', '健: 亻 (Nhân đứng: con người) + 建 (Kiến: vững mạnh) • 身: Bộ 身 (Thân - thân người đứng thẳng) • 房: 户 (Hộ: cánh cửa nhà) + 方 (Phương: gian phòng vuông vức)', 'Ghép 健 [bộ 亻] + 身 [bộ 身] + 房 [bộ 户] để nhớ từ 健身房 (jiànshēnfáng): "phòng gym".', '可以去看电影，吃火锅，逛街，购物或者去健身房健身。', 'Kěyǐ qù kàn diànyǐng, chī huǒguō, guàngjiē, gòuwù huòzhě qù jiànshēnfáng jiànshēn.', 'Có thể đi xem phim, ăn lẩu, dạo phố, mua sắm hoặc đến phòng tập thể hình tập luyện.', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v16_3', 'lesson-16', '新闻', 'xīnwén', 'tân', 'tin tức', 'Danh từ', '斤 (Cân) (Cái rìu, đơn vị cân nặng)', '新: 立 + 木 (Tân) + 斤 (Cân: rìu chặt gỗ mới) • 闻: 门 (Môn: cánh cửa) + 耳 (Nhĩ: ghé tai nghe tin)', 'Ghép 新 [bộ 斤] + 闻 [bộ 门] để nhớ từ 新闻 (xīnwén): "tin tức".', '你很乖啊！如果没有什么做我就上网看新闻或者玩游戏。', 'Nǐ hěn guāi a! Rúguǒ méiyǒu shénme zuò wǒ jiù shàngwǎng kàn xīnwén huòzhě wán yóuxì.', 'Bạn ngoan thật đấy! Nếu không có việc gì làm thì tôi lên mạng đọc tin tức hoặc chơi game.', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v16_4', 'lesson-16', '作业', 'zuòyè', 'tác nghiệp', 'bài tập', 'Danh từ', '人/亻 (Nhân) (Con người, nhân loại, hành động)', '作: 亻 (Nhân đứng: người) + 乍 (Sạ: làm việc) • 业: 业 (hai cặp nhánh đứng trên vạch ngang: công việc, sự nghiệp)', 'Ghép 作 [bộ 亻] + 业 [bộ 一] để nhớ từ 作业 (zuòyè): "bài tập".', '周末的时候我在家休息休息，如果有作业我就做作业，如果妈妈要帮忙我就去帮忙。', 'Zhōumò de shíhou wǒ zài jiā xiūxi xiūxi, rúguǒ yǒu zuòyè wǒ jiù zuò zuòyè, rúguǒ māma yào bāngmáng wǒ jiù qù bāngmáng.', 'Cuối tuần tôi nghỉ ngơi ở nhà, nếu có bài tập thì làm bài tập, nếu mẹ cần giúp việc gì thì tôi giúp mẹ.', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v16_5', 'lesson-16', '事', 'shì', 'sự', 'việc, chuyện', 'Danh từ', '亅 (Quyết) (Nét móc đứng)', '事 = 一 + 口 + 彐 + 亅 (tay cầm sổ ghi công việc).', 'Chữ 事 (shì) mang nghĩa "việc, chuyện", bộ chính 亅 (Quyết); cấu tạo: 一 + 口 + 彐 + 亅 (tay cầm sổ ghi công việc).', '这是关于“事”的常用句子。', 'Zhè shì guānyú ''shì'' de chángyòng jùzi.', 'Đây là câu ví dụ sử dụng từ ''事'' (việc, chuyện).', 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v16_6', 'lesson-16', '功课', 'gōngkè', 'công', 'bài học', 'Danh từ', '力 (Lực) (Sức mạnh, động lực)', '功: 工 (Công: công việc) + 力 (Lực: bỏ sức ra) • 课: 讠 (Ngôn: lời giảng) + 果 (Quả: kết quả)', 'Ghép 功 [bộ 力] + 课 [bộ 讠] để nhớ từ 功课 (gōngkè): "bài học".', '那好，明天我在家复习功课吧，快要考试了。', 'Nà hǎo, míngtiān wǒ zài jiā fùxí gōngkè ba, kuàiyào kǎoshì le.', 'Thôi được, ngày mai tôi ở nhà ôn tập bài vở vậy, sắp thi rồi.', 6) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v16_7', 'lesson-16', '出去', 'chūqù', 'khứ', 'ra ngoài', 'Động từ', '凵 (Khảm) (Há miệng, hố trũng)', '出: 山 (Sơn) chồng hai tầng bước ra ngoài • 去: 土 (Thổ: đất) + 厶 (Tư)', 'Ghép 出 [bộ 凵] + 去 [bộ 厶] để nhớ từ 出去 (chūqù): "ra ngoài".', '我常常跟朋友出去玩儿，我非常喜欢去公园照相。', 'Wǒ chángcháng gēn péngyou chūqù wánr, wǒ fēicháng xǐhuan qù gōngyuán zhàoxiàng.', 'Tôi thường ra ngoài chơi với bạn bè, tôi rất thích ra công viên chụp ảnh.', 7) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v16_8', 'lesson-16', '吃火锅', 'chī huǒguō', 'ngật hỏa', 'ăn lẩu', 'Động từ', '口 (Khẩu) (Miệng, ăn uống, lời nói, âm thanh phát ra)', '吃: 口 (Khẩu: miệng) + 乞 (Khất) • 火: Bộ 火 (Hỏa - ngọn lửa bốc lên, chữ độc thể) • 锅: 钅 (Kim: nồi kim loại) + 咼 (Qua)', 'Ghép 吃 [bộ 口] + 火 [bộ 火] + 锅 [bộ 钅] để nhớ từ 吃火锅 (chī huǒguō): "ăn lẩu".', '可以去看电影，吃火锅，逛街，购物或者去健身房健身。', 'Kěyǐ qù kàn diànyǐng, chī huǒguō, guàngjiē, gòuwù huòzhě qù jiànshēnfáng jiànshēn.', 'Có thể đi xem phim, ăn lẩu, dạo phố, mua sắm hoặc đến phòng tập thể hình tập luyện.', 8) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v16_9', 'lesson-16', '看电影', 'kàn diànyǐng', 'khán điện ảnh', 'xem phim', 'Động từ', '目 (Mục) (Con mắt, nhìn ngắm, thị giác)', '看: 手 (Thủ biến thể: tay che trán) + 目 (Mục: mắt nhìn) • 电: 日/田 (biến thể) + 乚 (tia sét phóng xuống) • 影: 景 (Cảnh: ánh sáng) + 彡 (Sam: bóng rọi)', 'Ghép 看 [bộ 目] + 电 [bộ 田] + 影 [bộ 彡] để nhớ từ 看电影 (kàn diànyǐng): "xem phim".', '可以去看电影，吃火锅，逛街，购物或者去健身房健身。', 'Kěyǐ qù kàn diànyǐng, chī huǒguō, guàngjiē, gòuwù huòzhě qù jiànshēnfáng jiànshēn.', 'Có thể đi xem phim, ăn lẩu, dạo phố, mua sắm hoặc đến phòng tập thể hình tập luyện.', 9) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v16_10', 'lesson-16', '逛街', 'guàngjiē', 'từ Hán ngữ', 'dạo phố', 'Động từ', '辶 (Sước) (Bước đi, di chuyển, khoảng cách)', '逛: 狂 (Cuồng) + 辶 (Sước: đi dạo lang thang) • 街: 彳 (Xích) + 圭 (Khuê) + 亍 (trên đại lộ đường phố)', 'Ghép 逛 [bộ 辶] + 街 [bộ 行] để nhớ từ 逛街 (guàngjiē): "dạo phố".', '我想去逛逛街。', 'Wǒ xiǎng qù guàngguang jiē.', 'Tớ muốn đi dạo phố một lúc.', 10) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v16_11', 'lesson-16', '健身', 'jiànshēn', 'kiện thân', 'tập gym', 'Động từ', '人/亻 (Nhân) (Con người, nhân loại, hành động)', '健: 亻 (Nhân đứng: con người) + 建 (Kiến: vững mạnh) • 身: Bộ 身 (Thân - thân người đứng thẳng)', 'Ghép 健 [bộ 亻] + 身 [bộ 身] để nhớ từ 健身 (jiànshēn): "tập gym".', '可以去看电影，吃火锅，逛街，购物或者去健身房健身。', 'Kěyǐ qù kàn diànyǐng, chī huǒguō, guàngjiē, gòuwù huòzhě qù jiànshēnfáng jiànshēn.', 'Có thể đi xem phim, ăn lẩu, dạo phố, mua sắm hoặc đến phòng tập thể hình tập luyện.', 11) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v16_12', 'lesson-16', '照相', 'zhàoxiàng', 'từ Hán ngữ', 'chụp ảnh', 'Động từ', '火/灬 (Hỏa) (Lửa, nhiệt độ, nấu nướng, nóng bức)', '照: 昭 (Chiêu: ánh sáng) + 灬 (Hỏa: ngọn lửa soi chiếu) • 相: 木 (Mộc: cây) + 目 (Mục: mắt quan sát)', 'Ghép 照 [bộ 灬] + 相 [bộ 目] để nhớ từ 照相 (zhàoxiàng): "chụp ảnh".', '我常常跟朋友出去玩儿，我非常喜欢去公园照相。', 'Wǒ chángcháng gēn péngyou chūqù wánr, wǒ fēicháng xǐhuan qù gōngyuán zhàoxiàng.', 'Tôi thường ra ngoài chơi với bạn bè, tôi rất thích ra công viên chụp ảnh.', 12) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v16_13', 'lesson-16', '休息', 'xiūxi', 'từ Hán ngữ', 'nghỉ ngơi', 'Động từ', '人/亻 (Nhân) (Con người, nhân loại, hành động)', '休: 亻 (Nhân đứng: người) + 木 (Mộc: tựa gốc cây nghỉ ngơi) • 息: 自 (Tự: cái mũi thở) + 心 (Tâm: nhịp tim lắng xuống nghỉ ngơi)', 'Ghép 休 [bộ 亻] + 息 [bộ 心] để nhớ từ 休息 (xiūxi): "nghỉ ngơi".', '休息休息', 'xiūxi xiūxi', 'Nghỉ ngơi một chút', 13) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v16_14', 'lesson-16', '帮忙', 'bāng máng', 'từ Hán ngữ', 'giúp đỡ', 'Động từ', '巾 (Cân) (Khăn vải, mũ nón, vải vóc)', '帮: 邦 (Bang) + 巾 (Cân) • 忙: 忄 (Tâm đứng: lòng) + 亡 (Vong: lo tất bật, bận rộn)', 'Ghép 帮 [bộ 巾] + 忙 [bộ 忄] để nhớ từ 帮忙 (bāng máng): "giúp đỡ".', '周末的时候我在家休息休息，如果有作业我就做作业，如果妈妈要帮忙我就去帮忙。', 'Zhōumò de shíhou wǒ zài jiā xiūxi xiūxi, rúguǒ yǒu zuòyè wǒ jiù zuò zuòyè, rúguǒ māma yào bāngmáng wǒ jiù qù bāngmáng.', 'Cuối tuần tôi nghỉ ngơi ở nhà, nếu có bài tập thì làm bài tập, nếu mẹ cần giúp việc gì thì tôi giúp mẹ.', 14) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v16_15', 'lesson-16', '帮助', 'bāngzhù', 'từ Hán ngữ', 'giúp đỡ', 'Động từ', '巾 (Cân) (Khăn vải, mũ nón, vải vóc)', '帮: 邦 (Bang) + 巾 (Cân) • 助: 且 (Thả) + 力 (Lực: góp thêm sức giúp đỡ)', 'Ghép 帮 [bộ 巾] + 助 [bộ 力] để nhớ từ 帮助 (bāngzhù): "giúp đỡ".', '如果你有困难，我就帮助你。', 'Rúguǒ nǐ yǒu kùnnan, wǒ jiù bāngzhù nǐ.', 'Nếu cậu gặp khó khăn thì tớ sẽ giúp đỡ.', 15) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v16_16', 'lesson-16', '安排', 'ānpái', 'An', 'sắp xếp, thu xếp', 'Động từ', '宀 (Miên) (Mái nhà, che chở, nơi ở)', '安: 宀 (Miên: mái nhà) + 女 (Nữ: người phụ nữ bình yên trong nhà) • 排: 扌 (Thủ: bàn tay xếp hàng) + 非 (Phi)', 'Ghép 安 [bộ 宀] + 排 [bộ 扌] để nhớ từ 安排 (ānpái): "sắp xếp, thu xếp".', '这是关于“安排”的常用句子。', 'Zhè shì guānyú ''ānpái'' de chángyòng jùzi.', 'Đây là câu ví dụ sử dụng từ ''安排'' (sắp xếp, thu xếp).', 16) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v16_17', 'lesson-16', '复习', 'fùxí', 'tập', 'ôn bài', 'Động từ', '夂 (Trĩ) (Bước đi chậm, quay trở lại)', '复: 𠂉 + 日 (Nhật) + 夂 (Trĩ: quay lại làm lần nữa) • 习: 乛 (cánh chim) + 冫 (chim non tập bay nhiều lần)', 'Ghép 复 [bộ 夂] + 习 [bộ 乙] để nhớ từ 复习 (fùxí): "ôn bài".', '昨天晚上我复习了复习课文。', 'Zuótiān wǎnshàng wǒ fùxí le fùxí kèwén.', 'Tối hôm qua tôi đã ôn tập qua bài khóa rồi.', 17) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v16_18', 'lesson-16', '考试', 'kǎoshì', 'thí', 'thi, kiểm tra', 'Động từ / Danh từ', '老/耂 (Lão) (Người già, lâu năm, tôn kính)', '考: 耂 (Lão) + 丂 (Khảo) • 试: 讠 (Ngôn: lời hỏi) + 式 (Thức: phép thử)', 'Ghép 考 [bộ 耂] + 试 [bộ 讠] để nhớ từ 考试 (kǎoshì): "thi, kiểm tra".', '那好，明天我在家复习功课吧，快要考试了。', 'Nà hǎo, míngtiān wǒ zài jiā fùxí gōngkè ba, kuàiyào kǎoshì le.', 'Thôi được, ngày mai tôi ở nhà ôn tập bài vở vậy, sắp thi rồi.', 18) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v16_19', 'lesson-16', '浪费', 'làngfèi', 'từ Hán ngữ', 'lãng phí', 'Động từ / Tính từ', '水/氵 (Thủy) (Nước, chất lỏng, sông ngòi)', '浪: 氵 (Thủy: dòng nước) + 良 (Lương: sóng cuộn) • 费: 弗 (Phất) + 贝 (Bối: tiêu tốn tiền bạc)', 'Ghép 浪 [bộ 氵] + 费 [bộ 贝] để nhớ từ 浪费 (làngfèi): "lãng phí".', '你的周末很无聊，你看看, 这简直太浪费时间了吧！', 'Nǐ de zhōumò hěn wúliáo, nǐ kànkan, zhè jiǎnzhí tài làngfèi shíjiān le ba!', 'Cuối tuần của bạn nhàm chán quá, bạn xem đấy, như vậy thật quá lãng phí thời gian rồi!', 19) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v16_20', 'lesson-16', '无聊', 'wúliáo', 'từ Hán ngữ', 'nhàm chán, vô vị', 'Tính từ', '无 (Vô) (Không có, phủ định)', '无: Bộ 无 (Vô - không có gì) • 聊: 耳 (Nhĩ: tai nghe) + 卯 (Mão)', 'Ghép 无 [bộ 无] + 聊 [bộ 耳] để nhớ từ 无聊 (wúliáo): "nhàm chán, vô vị".', '你的周末很无聊，你看看, 这简直太浪费时间了吧！', 'Nǐ de zhōumò hěn wúliáo, nǐ kànkan, zhè jiǎnzhí tài làngfèi shíjiān le ba!', 'Cuối tuần của bạn nhàm chán quá, bạn xem đấy, như vậy thật quá lãng phí thời gian rồi!', 20) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v16_21', 'lesson-16', '乖', 'guāi', 'từ Hán ngữ', 'ngoan ngoãn', 'Tính từ', '丿 (Phiệt) (Nét phẩy nghiêng)', '乖 = 千 (Thiên) + 北 (Bắc: ngoan ngoãn, khéo léo).', 'Chữ 乖 (guāi) mang nghĩa "ngoan ngoãn", bộ chính 丿 (Phiệt); cấu tạo: 千 (Thiên) + 北 (Bắc: ngoan ngoãn, khéo léo).', '你很乖啊！如果没有什么做我就上网看新闻或者玩游戏。', 'Nǐ hěn guāi a! Rúguǒ méiyǒu shénme zuò wǒ jiù shàngwǎng kàn xīnwén huòzhě wán yóuxì.', 'Bạn ngoan thật đấy! Nếu không có việc gì làm thì tôi lên mạng đọc tin tức hoặc chơi game.', 21) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v16_22', 'lesson-16', '常常', 'chángcháng', 'từ Hán ngữ', 'thường', 'Phó từ', '巾 (Cân) (Khăn vải, mũ nón, vải vóc)', '常: 尚 (Thượng) + 巾 (Cân: mảnh vải mặc thường ngày) • 常: 尚 (Thượng) + 巾 (Cân: mảnh vải mặc thường ngày)', 'Ghép 常 [bộ 巾] + 常 [bộ 巾] để nhớ từ 常常 (chángcháng): "thường".', '很好，那你周末常常做什么？', 'Hěn hǎo, nà nǐ zhōumò chángcháng zuò shénme?', 'Hay đấy, thế cuối tuần bạn thường làm gì?', 22) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v16_23', 'lesson-16', '非常', 'fēicháng', 'từ Hán ngữ', 'cực kì', 'Phó từ', '非 (Phi) (Không phải, trái ngược)', '非: Bộ 非 (Phi - hai cánh quay ngược nhau) • 常: 尚 (Thượng) + 巾 (Cân: mảnh vải mặc thường ngày)', 'Ghép 非 [bộ 非] + 常 [bộ 巾] để nhớ từ 非常 (fēicháng): "cực kì".', '我常常跟朋友出去玩儿，我非常喜欢去公园照相。', 'Wǒ chángcháng gēn péngyou chūqù wánr, wǒ fēicháng xǐhuan qù gōngyuán zhàoxiàng.', 'Tôi thường ra ngoài chơi với bạn bè, tôi rất thích ra công viên chụp ảnh.', 23) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v16_24', 'lesson-16', '简直', 'jiǎnzhí', 'từ Hán ngữ', 'thật là, quả là,...', 'Phó từ', '竹/⺮ (Trúc) (Tre trúc, đồ đan, sách vở)', '简: ⺮ (Trúc: thẻ tre ghi chép) + 间 (Gian: giản lược) • 直: 十 (Thập) + 目 (Mục: mắt nhìn thẳng) + 乚', 'Ghép 简 [bộ 竹] + 直 [bộ 目] để nhớ từ 简直 (jiǎnzhí): "thật là, quả là,...".', '你的周末很无聊，你看看, 这简直太浪费时间了吧！', 'Nǐ de zhōumò hěn wúliáo, nǐ kànkan, zhè jiǎnzhí tài làngfèi shíjiān le ba!', 'Cuối tuần của bạn nhàm chán quá, bạn xem đấy, như vậy thật quá lãng phí thời gian rồi!', 24) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v16_25', 'lesson-16', '快要......了', 'kuàiyào… le', 'khoái yếu', 'sắp… rồi', 'Cụm từ / Tên riêng', '心/忄 (Tâm) (Trái tim, tình cảm, suy nghĩ, tâm lý)', '快: 忄 (Tâm đứng: cảm xúc) + 夬 (Quái: nhanh, vui) • 要: 覀 (Tây biến thể) + 女 (Nữ) • 了: Bộ 亅 (Quyết - nét móc kết thúc, chữ độc thể)', 'Ghép 快 [bộ 忄] + 要 [bộ 西] + 了 [bộ 亅] để nhớ từ 快要......了 (kuàiyào… le): "sắp… rồi".', '这是关于“快要......了”的常用句子。', 'Zhè shì guānyú ''kuàiyào… le'' de chángyòng jùzi.', 'Đây là câu ví dụ sử dụng từ ''快要......了'' (sắp… rồi).', 25) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v16_26', 'lesson-16', '如果......(的话), 就......', 'rúguǒ… (dehuà) jiù…', 'quả thoại', 'nếu… thì...', 'Cụm từ / Tên riêng', '女 (Nữ) (Phụ nữ, gia đình, tình cảm)', '如: 女 (Nữ) + 口 (Khẩu) • 果: 田 (Điền: trái tròn) + 木 (Mộc: trên ngọn cây) • 就: 京 (Kinh: kinh đô) + 尤 (Uông)', 'Ghép 如 [bộ 女] + 果 [bộ 木] + 就 [bộ 尢] để nhớ từ 如果......(的话), 就...... (rúguǒ… (dehuà) jiù…): "nếu… thì...".', '这是关于“如果......(的话), 就......”的常用句子。', 'Zhè shì guānyú ''rúguǒ… (dehuà) jiù…'' de chángyòng jùzi.', 'Đây là câu ví dụ sử dụng từ ''如果......(的话), 就......'' (nếu… thì...).', 26) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order) VALUES ('g16_1', 'lesson-16', '1. 如果…… 就……:  Nếu…thì…', '如果 + S + giả thiết + 就 + kết quả.', ' 如果……就…… là cấu trúc ngữ pháp dùng để đưa ra giả thuyết: nếu A thì B - Hai vế câu cùng chủ ngữ: 如果你好好学习，就能考上大学. /Rúguǒ nǐ hǎohào xuéxí, jiù néng kǎo shàng dàxué./ Nếu chăm chỉ học hành thì bạn sẽ có thể thi đỗ đại học. - Hai vế câu khác chủ ngữ: 如果 +', NULL, '[{"hanzi":"如果你好好学习，就能考上大学.","pinyin":"Rúguǒ nǐ hǎohào xuéxí, jiù néng kǎo shàng dàxué.","meaning":"Nếu chăm chỉ học hành thì bạn sẽ có thể thi đỗ đại học."},{"hanzi":"如果你有困难，我就帮助你。","pinyin":"Rúguǒ nǐ yǒu kùnnan, wǒ jiù bāngzhù nǐ.","meaning":"Nếu cậu gặp khó khăn thì tớ sẽ giúp đỡ."}]'::jsonb, 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order) VALUES ('g16_2', 'lesson-16', '2. 动词重叠 - Động từ lặp lại', '+ Khi hành động diễn ra ở hiện tại hay trong tương lai', ' a. Khái niệm Động từ trùng lặp được dùng khi muốn biểu thị ý nghĩa thời gian ngắn,  động tác xảy ra nhanh hoặc số lượng ít. Động từ lặp lại còn được dùng trong câu mệnh lệnh, khuyên nhủ, gợi ý, thử làm một việc gì đó, nhằm giảm ngữ khí ra lệnh, khiế', NULL, '[{"hanzi":"= 明天天气好的话，我们就去爬山。","pinyin":"Rúguǒ míngtiān tiānqì hǎo dehuà, wǒmen jiù qù páshān.","meaning":"Nếu ngày mai trời đẹp, chúng ta sẽ đi leo núi."},{"hanzi":"尝尝 = 尝一尝","pinyin":"chángchang = cháng yi cháng","meaning":"Thử qua một chút."}]'::jsonb, 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order) VALUES ('g16_3', 'lesson-16', '3. 离合动词 - Động từ li hợp (AB)', '*A + Tân ngữ + (的) B', ' a. Khái niệm Động từ li hợp là loại động từ có kết cấu đặc biệt, bản thân động từ này có kết cấu động tân, cách sử dụng cũng có điểm khác biệt so với động từ thường. b. Cách dùng - Trong câu có sử dụng động từ li hợp (AB) mà có mang tân ngữ thì tân ', NULL, '[{"hanzi":"找找 = 找一找","pinyin":"zhǎozhao = zhǎo yi zhǎo","meaning":"Tìm một chút, tìm qua."},{"hanzi":"等等 = 等一等","pinyin":"děngdeng = děng yi děng","meaning":"Đợi một chút."}]'::jsonb, 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order) VALUES ('g16_4', 'lesson-16', '1. 新年 xīnnián dt. năm mới', 'Cấu trúc câu ngữ pháp trọng tâm', 'Quy tắc ngữ pháp quan trọng trong Cuối tuần.', NULL, '[{"hanzi":"她看了看自己的长头发。","pinyin":"Tā kàn le kàn zìjǐ de cháng tóufa.","meaning":"Cô ấy ngắm qua mái tóc dài của mình."},{"hanzi":"妈妈拍了拍我的头。","pinyin":"Māma pāi le pāi wǒ de tóu.","meaning":"Mẹ gõ nhẹ vào đầu tôi."}]'::jsonb, 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order;
INSERT INTO texts (id, lesson_id, title, description, sort_order) VALUES ('txt_16_1', 'lesson-16', 'Bài khoá #1: Hội thoại giáo trình — Cuối tuần', 'Hội thoại chuẩn giáo trình Bài 16. Từ vựng chưa học được chú thích phiên âm & nghĩa trong ngoặc.', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_16_1_1', 'txt_16_1', '范玉兰', '明天是周末，我们不上课！', '明天是周末，我们不上课！', 'Míngtiān shì zhōumò, wǒmen bú shàngkè!', 'Ngày mai là cuối tuần rồi, chúng ta không phải lên lớp!', 1) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_16_1_2', 'txt_16_1', '白茹雪', '是啊！你觉得周末做什么比较好呢？', '是啊！你觉得周末做 (zuò: làm)什么比较好呢？', 'Shì a! Nǐ juéde zhōumò zuò shénme bǐjiào hǎo ne?', 'Đúng rồi! Bạn thấy cuối tuần làm gì thì hay nhỉ?', 2) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_16_1_3', 'txt_16_1', '范玉兰', '可以去看电影，吃火锅，逛街，购物或者去健身房健身。', '可以去看电影，吃火锅，逛街，购物或者去健身房健身。', 'Kěyǐ qù kàn diànyǐng, chī huǒguō, guàngjiē, gòuwù huòzhě qù jiànshēnfáng jiànshēn.', 'Có thể đi xem phim, ăn lẩu, dạo phố, mua sắm hoặc đến phòng tập thể hình tập luyện.', 3) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_16_1_4', 'txt_16_1', '白茹雪', '很好，那你周末常常做什么？', '很好，那你周末常常做 (zuò: làm)什么？', 'Hěn hǎo, nà nǐ zhōumò chángcháng zuò shénme?', 'Hay đấy, thế cuối tuần bạn thường làm gì?', 4) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_16_1_5', 'txt_16_1', '范玉兰', '我常常跟朋友出去玩儿，我非常喜欢去公园照相。', '我常常跟 (gēn: cùng, với)朋友出去玩儿，我非常喜欢去公园照相。', 'Wǒ chángcháng gēn péngyou chūqù wánr, wǒ fēicháng xǐhuan qù gōngyuán zhàoxiàng.', 'Tôi thường ra ngoài chơi với bạn bè, tôi rất thích ra công viên chụp ảnh.', 5) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_16_1_6', 'txt_16_1', '白茹雪', '周末的时候我在家休息休息，如果有作业我就做作业，如果妈妈要帮忙我就去帮忙。', '周末的时候我在家休息休息，如果有作业我就做 (zuò: làm)作业，如果妈妈要帮忙我就去帮忙。', 'Zhōumò de shíhou wǒ zài jiā xiūxi xiūxi, rúguǒ yǒu zuòyè wǒ jiù zuò zuòyè, rúguǒ māma yào bāngmáng wǒ jiù qù bāngmáng.', 'Cuối tuần tôi nghỉ ngơi ở nhà, nếu có bài tập thì làm bài tập, nếu mẹ cần giúp việc gì thì tôi giúp mẹ.', 6) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_16_1_7', 'txt_16_1', '范玉兰', '你很乖啊！如果没有什么做我就上网看新闻或者玩游戏。', '你很乖啊！如果没有 (méiyǒu: không có)什么做 (zuò: làm)我就上网看新闻或者玩 (wán: chơi)游戏 (yóuxì: trò chơi)。', 'Nǐ hěn guāi a! Rúguǒ méiyǒu shénme zuò wǒ jiù shàngwǎng kàn xīnwén huòzhě wán yóuxì.', 'Bạn ngoan thật đấy! Nếu không có việc gì làm thì tôi lên mạng đọc tin tức hoặc chơi game.', 7) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_16_1_8', 'txt_16_1', '白茹雪', '你的周末很无聊，你看看, 这简直太浪费时间了吧！', '你的周末很无聊，你看看, 这简直太浪费时间了吧！', 'Nǐ de zhōumò hěn wúliáo, nǐ kànkan, zhè jiǎnzhí tài làngfèi shíjiān le ba!', 'Cuối tuần của bạn nhàm chán quá, bạn xem đấy, như vậy thật quá lãng phí thời gian rồi!', 8) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_16_1_9', 'txt_16_1', '范玉兰', '那好，明天我在家复习功课吧，快要考试了。', '那好，明天我在家复习功课吧，快要考试了。', 'Nà hǎo, míngtiān wǒ zài jiā fùxí gōngkè ba, kuàiyào kǎoshì le.', 'Thôi được, ngày mai tôi ở nhà ôn tập bài vở vậy, sắp thi rồi.', 9) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_16_1_1', 'lesson-16', 'txt_16_1', 'listening', 'listening', '明天是周末，我们不上课！', NULL, 'Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Ngày mai là cuối tuần rồi, chúng ta không phải lên lớp!","Bạn cứ đi thẳng, sau đó rẽ phải là sẽ nhìn thấy bệnh viện ở bên trái của","Ở đây chỉ có hai người chúng ta?","Bố nhẹ nhàng vỗ vai tôi, lẳng lặng an ủi tôi."]'::jsonb, 0, 'Nội dung nghe được: 明天是周末，我们不上课！ (Míngtiān shì zhōumò, wǒmen bú shàngkè!) → Ngày mai là cuối tuần rồi, chúng ta không phải lên lớp!', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_16_1_2', 'lesson-16', 'txt_16_1', 'listening', 'listening', '是啊！你觉得周末做什么比较好呢？', NULL, 'Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["了解 (liǎojiě: hiểu rõ, biết rõ)了解","是啊！你觉得周末做 (zuò: làm)什么比较好呢？","她歌唱 (gēchàng: ca hát)得 (děi: phải)很好听 (tīng: nghe)！","= 明天天气好的话 (huà: lời nói)，我们就去爬山 (páshān: leo núi)。"]'::jsonb, 1, 'Câu vừa đọc: 是啊！你觉得周末做什么比较好呢？ (Shì a! Nǐ juéde zhōumò zuò shénme bǐjiào hǎo ne?) → Đúng rồi! Bạn thấy cuối tuần làm gì thì hay nhỉ?', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_16_1_3', 'lesson-16', 'txt_16_1', 'listening', 'listening', '可以去看电影，吃火锅，逛街，购物或者去健身房健身。', NULL, 'Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Có thể đi xem phim, ăn lẩu, dạo phố, mua sắm hoặc đến phòng tập thể hình tập luyện.","Mẹ ơi, quần áo của con ở đâu nhỉ?","Anh ta là người chẳng ra gì.","Một phần quà"]'::jsonb, 0, 'Nội dung nghe được: 可以去看电影，吃火锅，逛街，购物或者去健身房健身。 (Kěyǐ qù kàn diànyǐng, chī huǒguō, guàngjiē, gòuwù huòzhě qù jiànshēnfáng jiànshēn.) → Có thể đi xem phim, ăn lẩu, dạo phố, mua sắm hoặc đến phòng tập thể hình tập luyện.', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_16_1_4', 'lesson-16', 'txt_16_1', 'listening', 'listening', '很好，那你周末常常做什么？', NULL, 'Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["我早上打扫 (dǎsǎo: dọn dẹp, quét dọn)了打扫房间 (fángjiān: căn phòng)。","找找 = 找一找","很好，那你周末常常做 (zuò: làm)什么？","小兰刚 (gāng: vừa mới)跟 (gēn: cùng, với)朋友吵架 (chǎojià: cãi nhau)。"]'::jsonb, 2, 'Câu vừa đọc: 很好，那你周末常常做什么？ (Hěn hǎo, nà nǐ zhōumò chángcháng zuò shénme?) → Hay đấy, thế cuối tuần bạn thường làm gì?', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO texts (id, lesson_id, title, description, sort_order) VALUES ('txt_16_2', 'lesson-16', 'Bài nghe tổng hợp: Ôn tập lũy tiến (Bài 1 – Bài 16)', 'Kết hợp từ vựng & mẫu câu đã học từ Bài 1 đến Bài 15 cùng trọng tâm Bài 16 để củng cố phản xạ nghe.', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_16_2_1', 'txt_16_2', 'Ôn Bài 15', '他是个不怎么样的人。', '他是个不怎么样的人。', 'Tā shì gè bù zěnme yàng de rén.', 'Anh ta là người chẳng ra gì.', 1) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
