INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_16_2_3', 'txt_16_2', 'Ôn Bài 8', '一斤苹果多少钱？', '一斤苹果多少钱？', 'Yī jīn píngguǒ duōshao qián?', 'Nửa kg (1 cân) táo bao nhiêu tiền?', 3) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
