INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss16_exp_14', 'lesson-16', '我真不喜欢', 'Tôi thực sự không thích!', 'Wǒ zhēn bù xǐhuan!', '["我","真","不","喜欢"]'::jsonb, NULL, 20) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr16_vi_1', 'lesson-16', 'vi_to_zh', '[Mở rộng] Chủ nhật chúng ta đi dạo phố và ăn lẩu nhé!', NULL, NULL, '星期天我们去逛街、吃火锅吧！', NULL, 'xīngqītiān wǒmen qù guàngjiē chī huǒguō ba', '[]'::jsonb, 'Gợi ý Pinyin: Xīngqītiān wǒmen qù guàngjiē, chī huǒguō ba!', 'Chủ nhật chúng ta đi dạo phố và ăn lẩu nhé! → 星期天我们去逛街、吃火锅吧！ (Xīngqītiān wǒmen qù guàngjiē, chī huǒguō ba!)', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr16_vi_2', 'lesson-16', 'vi_to_zh', '[Mở rộng] Sau khi làm xong bài tập tôi muốn đi xem phim.', NULL, NULL, '做完功课以后我想去看电影。', NULL, 'zuòwán gōngkè yǐhòu wǒ xiǎng qù kàn diànyǐng', '[]'::jsonb, 'Gợi ý Pinyin: Zuòwán gōngkè yǐhòu wǒ xiǎng qù kàn diànyǐng. | Từ chưa học: 以后 (yǐhòu: sau, lúc sau), 做完 (zuòwán: làm xong)', 'Sau khi làm xong bài tập tôi muốn đi xem phim. → 做完功课以后我想去看电影。 (Zuòwán gōngkè yǐhòu wǒ xiǎng qù kàn diànyǐng.)', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr16_vi_3', 'lesson-16', 'vi_to_zh', 'Tìm một chút, tìm qua.', NULL, NULL, '找找 = 找一找', NULL, 'zhǎozhao  zhǎo yi zhǎo', '[]'::jsonb, 'Gợi ý Pinyin: zhǎozhao = zhǎo yi zhǎo', 'Tìm một chút, tìm qua. → 找找 = 找一找 (zhǎozhao = zhǎo yi zhǎo)', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr16_vi_4', 'lesson-16', 'vi_to_zh', 'Đợi một chút.', NULL, NULL, '等等 = 等一等', NULL, 'děngdeng  děng yi děng', '[]'::jsonb, 'Gợi ý Pinyin: děngdeng = děng yi děng', 'Đợi một chút. → 等等 = 等一等 (děngdeng = děng yi děng)', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr16_vi_exp_1', 'lesson-16', 'vi_to_zh', 'Ngày mai là cuối tuần rồi, chúng ta không phải lên lớp!', NULL, NULL, '明天是周末，我们不上课！', NULL, 'míngtiān shì zhōumò wǒmen bú shàngkè', '[]'::jsonb, 'Gợi ý Pinyin: Míngtiān shì zhōumò, wǒmen bú shàngkè!', 'Ngày mai là cuối tuần rồi, chúng ta không phải lên lớp! → 明天是周末，我们不上课！ (Míngtiān shì zhōumò, wǒmen bú shàngkè!)', 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr16_vi_exp_2', 'lesson-16', 'vi_to_zh', 'Đúng rồi! Bạn thấy cuối tuần làm gì thì hay nhỉ?', NULL, NULL, '是啊！你觉得周末做什么比较好呢？', NULL, 'shì a nǐ juéde zhōumò zuò shénme bǐjiào hǎo ne', '[]'::jsonb, 'Gợi ý Pinyin: Shì a! Nǐ juéde zhōumò zuò shénme bǐjiào hǎo ne?', 'Đúng rồi! Bạn thấy cuối tuần làm gì thì hay nhỉ? → 是啊！你觉得周末做什么比较好呢？ (Shì a! Nǐ juéde zhōumò zuò shénme bǐjiào hǎo ne?)', 6) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr16_vi_exp_3', 'lesson-16', 'vi_to_zh', 'Có thể đi xem phim, ăn lẩu, dạo phố, mua sắm hoặc đến phòng tập thể hình tập luyện.', NULL, NULL, '可以去看电影，吃火锅，逛街，购物或者去健身房健身。', NULL, 'kěyǐ qù kàn diànyǐng chī huǒguō guàngjiē gòuwù huòzhě qù jiànshēnfáng jiànshēn', '[]'::jsonb, 'Gợi ý Pinyin: Kěyǐ qù kàn diànyǐng, chī huǒguō, guàngjiē, gòuwù huòzhě qù jiànshēnfáng jiànshēn.', 'Có thể đi xem phim, ăn lẩu, dạo phố, mua sắm hoặc đến phòng tập thể hình tập luyện. → 可以去看电影，吃火锅，逛街，购物或者去健身房健身。 (Kěyǐ qù kàn diànyǐng, chī huǒguō, guàngjiē, gòuwù huòzhě qù jiànshēnfáng jiànshēn.)', 7) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr16_vi_exp_4', 'lesson-16', 'vi_to_zh', 'Hay đấy, thế cuối tuần bạn thường làm gì?', NULL, NULL, '很好，那你周末常常做什么？', NULL, 'hěn hǎo nà nǐ zhōumò chángcháng zuò shénme', '[]'::jsonb, 'Gợi ý Pinyin: Hěn hǎo, nà nǐ zhōumò chángcháng zuò shénme?', 'Hay đấy, thế cuối tuần bạn thường làm gì? → 很好，那你周末常常做什么？ (Hěn hǎo, nà nǐ zhōumò chángcháng zuò shénme?)', 8) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr16_vi_exp_5', 'lesson-16', 'vi_to_zh', 'Tôi thường ra ngoài chơi với bạn bè, tôi rất thích ra công viên chụp ảnh.', NULL, NULL, '我常常跟朋友出去玩儿，我非常喜欢去公园照相。', NULL, 'wǒ chángcháng gēn péngyou chūqù wánr wǒ fēicháng xǐhuan qù gōngyuán zhàoxiàng', '[]'::jsonb, 'Gợi ý Pinyin: Wǒ chángcháng gēn péngyou chūqù wánr, wǒ fēicháng xǐhuan qù gōngyuán zhàoxiàng.', 'Tôi thường ra ngoài chơi với bạn bè, tôi rất thích ra công viên chụp ảnh. → 我常常跟朋友出去玩儿，我非常喜欢去公园照相。 (Wǒ chángcháng gēn péngyou chūqù wánr, wǒ fēicháng xǐhuan qù gōngyuán zhàoxiàng.)', 9) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr16_vi_exp_6', 'lesson-16', 'vi_to_zh', 'Cuối tuần tôi nghỉ ngơi ở nhà, nếu có bài tập thì làm bài tập, nếu mẹ cần giúp việc gì thì tôi giúp mẹ.', NULL, NULL, '周末的时候我在家休息休息，如果有作业我就做作业，如果妈妈要帮忙我就去帮忙。', NULL, 'zhōumò de shíhou wǒ zài jiā xiūxi xiūxi rúguǒ yǒu zuòyè wǒ jiù zuò zuòyè rúguǒ māma yào bāngmáng wǒ jiù qù bāngmáng', '[]'::jsonb, 'Gợi ý Pinyin: Zhōumò de shíhou wǒ zài jiā xiūxi xiūxi, rúguǒ yǒu zuòyè wǒ jiù zuò zuòyè, rúguǒ māma yào bāngmáng wǒ jiù qù bāngmáng.', 'Cuối tuần tôi nghỉ ngơi ở nhà, nếu có bài tập thì làm bài tập, nếu mẹ cần giúp việc gì thì tôi giúp mẹ. → 周末的时候我在家休息休息，如果有作业我就做作业，如果妈妈要帮忙我就去帮忙。 (Zhōumò de shíhou wǒ zài jiā xiūxi xiūxi, rúguǒ yǒu zuòyè wǒ jiù zuò zuòyè, rúguǒ māma yào bāngmáng wǒ jiù qù bāngmáng.)', 10) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr16_vi_exp_7', 'lesson-16', 'vi_to_zh', 'Bạn ngoan thật đấy! Nếu không có việc gì làm thì tôi lên mạng đọc tin tức hoặc chơi game.', NULL, NULL, '你很乖啊！如果没有什么做我就上网看新闻或者玩游戏。', NULL, 'nǐ hěn guāi a rúguǒ méiyǒu shénme zuò wǒ jiù shàngwǎng kàn xīnwén huòzhě wán yóuxì', '[]'::jsonb, 'Gợi ý Pinyin: Nǐ hěn guāi a! Rúguǒ méiyǒu shénme zuò wǒ jiù shàngwǎng kàn xīnwén huòzhě wán yóuxì.', 'Bạn ngoan thật đấy! Nếu không có việc gì làm thì tôi lên mạng đọc tin tức hoặc chơi game. → 你很乖啊！如果没有什么做我就上网看新闻或者玩游戏。 (Nǐ hěn guāi a! Rúguǒ méiyǒu shénme zuò wǒ jiù shàngwǎng kàn xīnwén huòzhě wán yóuxì.)', 11) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr16_vi_exp_8', 'lesson-16', 'vi_to_zh', 'Cuối tuần của bạn nhàm chán quá, bạn xem đấy, như vậy thật quá lãng phí thời gian rồi!', NULL, NULL, '你的周末很无聊，你看看, 这简直太浪费时间了吧！', NULL, 'nǐ de zhōumò hěn wúliáo nǐ kànkan zhè jiǎnzhí tài làngfèi shíjiān le ba', '[]'::jsonb, 'Gợi ý Pinyin: Nǐ de zhōumò hěn wúliáo, nǐ kànkan, zhè jiǎnzhí tài làngfèi shíjiān le ba!', 'Cuối tuần của bạn nhàm chán quá, bạn xem đấy, như vậy thật quá lãng phí thời gian rồi! → 你的周末很无聊，你看看, 这简直太浪费时间了吧！ (Nǐ de zhōumò hěn wúliáo, nǐ kànkan, zhè jiǎnzhí tài làngfèi shíjiān le ba!)', 12) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr16_vi_exp_9', 'lesson-16', 'vi_to_zh', 'Thôi được, ngày mai tôi ở nhà ôn tập bài vở vậy, sắp thi rồi.', NULL, NULL, '那好，明天我在家复习功课吧，快要考试了。', NULL, 'nà hǎo míngtiān wǒ zài jiā fùxí gōngkè ba kuàiyào kǎoshì le', '[]'::jsonb, 'Gợi ý Pinyin: Nà hǎo, míngtiān wǒ zài jiā fùxí gōngkè ba, kuàiyào kǎoshì le.', 'Thôi được, ngày mai tôi ở nhà ôn tập bài vở vậy, sắp thi rồi. → 那好，明天我在家复习功课吧，快要考试了。 (Nà hǎo, míngtiān wǒ zài jiā fùxí gōngkè ba, kuàiyào kǎoshì le.)', 13) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
