INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr16_zh_1', 'lesson-16', 'zh_to_vi', '[Mở rộng] 谢谢你经常在学习 (xuéxí: học tập)上 (shàng: trên / lên)帮助我。', '谢谢你经常在学习上帮助我。', 'Xièxie nǐ jīngcháng zài xuéxí shàng bāngzhù wǒ.', NULL, 'Cảm ơn bạn thường xuyên giúp đỡ tôi trong việc học.', NULL, '["Cảm","ơn","bạn"]'::jsonb, 'Pinyin: Xièxie nǐ jīngcháng zài xuéxí shàng bāngzhù wǒ.', '谢谢你经常在学习上帮助我。 (Xièxie nǐ jīngcháng zài xuéxí shàng bāngzhù wǒ.) nghĩa là: Cảm ơn bạn thường xuyên giúp đỡ tôi trong việc học.', 15) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
