INSERT INTO lessons (id, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id) VALUES ('lesson-17', 'Bài 17: Tết - Đơn nguyên 5: Kỳ nghỉ', 'Bài 17', 'Đơn nguyên 5: Kỳ nghỉ', 'Phong tục Tết cổ truyền, gói sủi cảo, đón giao thừa, chúc Tết và lì xì.', '2026-11-14'::date, 17, TRUE, NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, date_added = EXCLUDED.date_added, sort_order = EXCLUDED.sort_order, is_system = TRUE, updated_at = NOW();
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v17_1', 'lesson-17', '新年', 'xīnnián', 'tân niên', 'năm mới', 'Danh từ', '斤 (Cân) (Cái rìu, đơn vị cân nặng)', '新: 立 + 木 (Tân) + 斤 (Cân: rìu chặt gỗ mới) • 年: 𠂉 + 干/土 (mùa màng thu hoạch một năm)', 'Ghép 新 [bộ 斤] + 年 [bộ 干] để nhớ từ 新年 (xīnnián): "năm mới".', '先准备好这些，然后到除夕，全家人团圆，一起吃年夜饭、放鞭炮，庆祝新年。', 'Xiān zhǔnbèi hǎo zhèxiē, ránhòu dào chúxī, quán jiārén tuányuán, yīqǐ chī niányèfàn, fàng biānpào, qìngzhù xīnnián.', 'Trước tiên chuẩn bị xong những thứ này, rồi đến đêm Giao thừa, cả nhà đoàn tụ cùng ăn bữa cơm tất niên, đốt pháo mừng năm mới.', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v17_2', 'lesson-17', '春节', 'Chūnjié', 'xuân tiết', 'Tết âm lịch', 'Danh từ', '日 (Nhật) (Mặt trời, ban ngày, thời gian, ánh sáng)', '春: 𡗗 (cây cỏ đâm chồi) + 日 (Nhật: nắng ấm mùa xuân) • 节: 艹 (Thảo: đốt trúc/cỏ cây) + 卩 (Tiết)', 'Ghép 春 [bộ 日] + 节 [bộ 艹] để nhớ từ 春节 (Chūnjié): "Tết âm lịch".', '我听几个朋友说快到春节了，春节是你们的一个节日，对吗？', 'Wǒ tīng jǐ gè péngyou shuō kuài dào Chūnjié le, Chūnjié shì nǐmen de yígè jiérì, duì ma?', 'Tôi nghe mấy người bạn nói sắp đến Tết Nguyên Đán rồi, Tết là một ngày lễ của các bạn đúng không?', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v17_3', 'lesson-17', '节日', 'jiérì', 'tiết nhật', 'ngày lễ', 'Danh từ', '艹 (Thảo) (Cỏ cây, hoa lá, thảo mộc)', '节: 艹 (Thảo: đốt trúc/cỏ cây) + 卩 (Tiết) • 日: Bộ 日 (Nhật - mặt trời, chữ độc thể)', 'Ghép 节 [bộ 艹] + 日 [bộ 日] để nhớ từ 节日 (jiérì): "ngày lễ".', '我听几个朋友说快到春节了，春节是你们的一个节日，对吗？', 'Wǒ tīng jǐ gè péngyou shuō kuài dào Chūnjié le, Chūnjié shì nǐmen de yígè jiérì, duì ma?', 'Tôi nghe mấy người bạn nói sắp đến Tết Nguyên Đán rồi, Tết là một ngày lễ của các bạn đúng không?', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v17_4', 'lesson-17', '除夕', 'chúxī', 'từ Hán ngữ', 'đêm giao thừa', 'Danh từ', '阝 (Phụ/Ấp) (Gò đất hoặc vùng đất, thành ấp)', '除: 阝 (Phụ: bậc thềm) + 余 (Dư: quét dọn loại trừ) • 夕: Bộ 夕 (Tịch - vầng trăng khuyết buổi chiều tối)', 'Ghép 除 [bộ 阝] + 夕 [bộ 夕] để nhớ từ 除夕 (chúxī): "đêm giao thừa".', '先准备好这些，然后到除夕，全家人团圆，一起吃年夜饭、放鞭炮，庆祝新年。', 'Xiān zhǔnbèi hǎo zhèxiē, ránhòu dào chúxī, quán jiārén tuányuán, yīqǐ chī niányèfàn, fàng biānpào, qìngzhù xīnnián.', 'Trước tiên chuẩn bị xong những thứ này, rồi đến đêm Giao thừa, cả nhà đoàn tụ cùng ăn bữa cơm tất niên, đốt pháo mừng năm mới.', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v17_5', 'lesson-17', '饺子', 'jiǎozi', 'từ Hán ngữ', 'sủi cảo', 'Danh từ', '食/饣 (Thực) (Đồ ăn, ẩm thực)', '饺: 饣 (Thực: thức ăn) + 交 (Giao: gói sủi cảo) • 子: Bộ 子 (Tử - đứa trẻ dang tay, chữ độc thể)', 'Ghép 饺 [bộ 饣] + 子 [bộ 子] để nhớ từ 饺子 (jiǎozi): "sủi cảo".', '要准备很多，比如打扫房子、买茶食、水果、贴春联、包饺子。', 'Yào zhǔnbèi hěnduō, bǐrú dǎsǎo fángzi, mǎi cháshi, shuǐguǒ, tiē chūnlián, bāo jiǎozi.', 'Phải chuẩn bị nhiều thứ lắm, ví dụ như dọn dẹp nhà cửa, mua bánh mứt, trái cây, dán câu đối Tết, gói sủi cảo.', 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v17_6', 'lesson-17', '粽子', 'zòngzi', 'từ Hán ngữ', 'bánh chưng', 'Danh từ', '米 (Mễ) (Hạt gạo, tinh bột)', '粽: 米 (Mễ: gạo nếp gói bánh) + 宗 (Tông) • 子: Bộ 子 (Tử - đứa trẻ dang tay, chữ độc thể)', 'Ghép 粽 [bộ 米] + 子 [bộ 子] để nhớ từ 粽子 (zòngzi): "bánh chưng".', '我们越南不包饺子，我们包粽子。', 'Wǒmen Yuènán bù bāo jiǎozi, wǒmen bāo zòngzi.', 'Việt Nam chúng tôi không gói sủi cảo, chúng tôi gói bánh chưng.', 6) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v17_7', 'lesson-17', '茶食', 'cháshi', 'trà thực', 'bánh kẹo (nói chung)', 'Danh từ', '艹 (Thảo) (Cỏ cây, hoa lá, thảo mộc)', '茶: 艹 (Thảo: lá chè) + 人 (Nhân) + 木 (Mộc: cây cỏ hái bởi người) • 食: Bộ 食 (Thực - mâm cơm, đồ ăn)', 'Ghép 茶 [bộ 艹] + 食 [bộ 食] để nhớ từ 茶食 (cháshi): "bánh kẹo (nói chung)".', '要准备很多，比如打扫房子、买茶食、水果、贴春联、包饺子。', 'Yào zhǔnbèi hěnduō, bǐrú dǎsǎo fángzi, mǎi cháshi, shuǐguǒ, tiē chūnlián, bāo jiǎozi.', 'Phải chuẩn bị nhiều thứ lắm, ví dụ như dọn dẹp nhà cửa, mua bánh mứt, trái cây, dán câu đối Tết, gói sủi cảo.', 7) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v17_8', 'lesson-17', '年夜饭', 'niányèfàn', 'niên', 'bữa cơm tất niên', 'Danh từ', '干 (Can) (Can thiệp, khô ráo, làm việc)', '年: 𠂉 + 干/土 (mùa màng thu hoạch một năm) • 夜: 亠 + 亻 + 夕 (Tịch: màn đêm tối) • 饭: 饣 (Thực: thức ăn) + 反 (Phản)', 'Ghép 年 [bộ 干] + 夜 [bộ 夕] + 饭 [bộ 饣] để nhớ từ 年夜饭 (niányèfàn): "bữa cơm tất niên".', '先准备好这些，然后到除夕，全家人团圆，一起吃年夜饭、放鞭炮，庆祝新年。', 'Xiān zhǔnbèi hǎo zhèxiē, ránhòu dào chúxī, quán jiārén tuányuán, yīqǐ chī niányèfàn, fàng biānpào, qìngzhù xīnnián.', 'Trước tiên chuẩn bị xong những thứ này, rồi đến đêm Giao thừa, cả nhà đoàn tụ cùng ăn bữa cơm tất niên, đốt pháo mừng năm mới.', 8) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v17_9', 'lesson-17', '红包', 'hóngbāo', 'hồng bao', 'bao lì xì', 'Danh từ', '糸/纟 (Mịch) (Sợi tơ, gắn kết, màu sắc)', '红: 纟 (Mịch: sợi tơ nhuộm đỏ) + 工 (Công) • 包: 勹 (Bao: bọc lại) + 巳 (Tỵ: thai nhi bên trong)', 'Ghép 红 [bộ 纟] + 包 [bộ 勹] để nhớ từ 红包 (hóngbāo): "bao lì xì".', '对，还有红包。我还记得我小时候去亲戚家拜年，他们给我很多红包，真开心，但是现在没有了。', 'Duì, hái yǒu hóngbāo. Wǒ hái jìde wǒ xiǎoshíhou qù qīnqi jiā bàinián, tāmen gěi wǒ hěnduō hóngbāo, zhēn kāixīn, dànshì xiànzài méiyǒu le.', 'Đúng rồi, còn có lì xì nữa. Tôi vẫn nhớ hồi nhỏ đi chúc Tết họ hàng, mọi người mừng tuổi tôi rất nhiều bao lì xì, vui lắm, nhưng bây giờ thì không còn nữa rồi.', 9) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v17_10', 'lesson-17', '春联', 'chūnlián', 'xuân', 'câu đối Tết', 'Danh từ', '日 (Nhật) (Mặt trời, ban ngày, thời gian, ánh sáng)', '春: 𡗗 (cây cỏ đâm chồi) + 日 (Nhật: nắng ấm mùa xuân) • 联: 耳 (Nhĩ) + 关 (Quan: nối liền kề)', 'Ghép 春 [bộ 日] + 联 [bộ 耳] để nhớ từ 春联 (chūnlián): "câu đối Tết".', '要准备很多，比如打扫房子、买茶食、水果、贴春联、包饺子。', 'Yào zhǔnbèi hěnduō, bǐrú dǎsǎo fángzi, mǎi cháshi, shuǐguǒ, tiē chūnlián, bāo jiǎozi.', 'Phải chuẩn bị nhiều thứ lắm, ví dụ như dọn dẹp nhà cửa, mua bánh mứt, trái cây, dán câu đối Tết, gói sủi cảo.', 10) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v17_11', 'lesson-17', '鞭炮', 'biānpào', 'từ Hán ngữ', 'pháo', 'Danh từ', '革 (Cách) (Da thú, thay đổi)', '鞭: 革 (Cách: dây da) + 便 (Tiện: roi/pháo nổ) • 炮: 火 (Hỏa: lửa châm ngòi nổ) + 包 (Bao)', 'Ghép 鞭 [bộ 革] + 炮 [bộ 火] để nhớ từ 鞭炮 (biānpào): "pháo".', '先准备好这些，然后到除夕，全家人团圆，一起吃年夜饭、放鞭炮，庆祝新年。', 'Xiān zhǔnbèi hǎo zhèxiē, ránhòu dào chúxī, quán jiārén tuányuán, yīqǐ chī niányèfàn, fàng biānpào, qìngzhù xīnnián.', 'Trước tiên chuẩn bị xong những thứ này, rồi đến đêm Giao thừa, cả nhà đoàn tụ cùng ăn bữa cơm tất niên, đốt pháo mừng năm mới.', 11) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v17_12', 'lesson-17', '房子', 'fángzi', 'từ Hán ngữ', 'nhà, nhà cửa', 'Danh từ', '户 (Hộ) (Cánh cửa, gia đình, nhà cửa)', '房: 户 (Hộ: cánh cửa nhà) + 方 (Phương: gian phòng vuông vức) • 子: Bộ 子 (Tử - đứa trẻ dang tay, chữ độc thể)', 'Ghép 房 [bộ 户] + 子 [bộ 子] để nhớ từ 房子 (fángzi): "nhà, nhà cửa".', '要准备很多，比如打扫房子、买茶食、水果、贴春联、包饺子。', 'Yào zhǔnbèi hěnduō, bǐrú dǎsǎo fángzi, mǎi cháshi, shuǐguǒ, tiē chūnlián, bāo jiǎozi.', 'Phải chuẩn bị nhiều thứ lắm, ví dụ như dọn dẹp nhà cửa, mua bánh mứt, trái cây, dán câu đối Tết, gói sủi cảo.', 12) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v17_13', 'lesson-17', '亲戚', 'qīnqi', 'từ Hán ngữ', 'người thân, họ hàng', 'Danh từ', '立 (Lập) (Đứng vững, thiết lập)', '亲: 立 (Lập) + 木 (Mộc: cây đứng gần bên, người thân) • 戚: 厂 (Hán) + 尗 + 戈 (Qua: họ hàng thân thích)', 'Ghép 亲 [bộ 立] + 戚 [bộ 戈] để nhớ từ 亲戚 (qīnqi): "người thân, họ hàng".', '对，还有红包。我还记得我小时候去亲戚家拜年，他们给我很多红包，真开心，但是现在没有了。', 'Duì, hái yǒu hóngbāo. Wǒ hái jìde wǒ xiǎoshíhou qù qīnqi jiā bàinián, tāmen gěi wǒ hěnduō hóngbāo, zhēn kāixīn, dànshì xiànzài méiyǒu le.', 'Đúng rồi, còn có lì xì nữa. Tôi vẫn nhớ hồi nhỏ đi chúc Tết họ hàng, mọi người mừng tuổi tôi rất nhiều bao lì xì, vui lắm, nhưng bây giờ thì không còn nữa rồi.', 13) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v17_14', 'lesson-17', '过年', 'guònián', 'niên', 'đón Tết', 'Động từ / Danh từ', '干 (Can) (Can thiệp, khô ráo, làm việc)', '过: 寸 (Thốn) + 辶 (Sước: bước đi qua) • 年: 𠂉 + 干/土 (mùa màng thu hoạch một năm)', 'Ghép 过 [bộ 辶] + 年 [bộ 干] để nhớ từ 过年 (guònián): "đón Tết".', '你们怎么准备过年？', 'Nǐmen zěnme zhǔnbèi guònián?', 'Các bạn chuẩn bị đón Tết thế nào?', 14) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v17_15', 'lesson-17', '庆祝', 'qìngzhù', 'chúc', 'chúc mừng', 'Động từ', '广 (Nghiễm) (Mái nhà rộng, nơi công cộng)', '庆: 广 (Nghiễm) + 大 (Đại: mở rộng lòng ăn mừng) • 祝: 礻 (Thị: cầu khấn thần linh) + 兄 (Huynh: miệng chúc phúc)', 'Ghép 庆 [bộ 广] + 祝 [bộ 礻] để nhớ từ 庆祝 (qìngzhù): "chúc mừng".', '先准备好这些，然后到除夕，全家人团圆，一起吃年夜饭、放鞭炮，庆祝新年。', 'Xiān zhǔnbèi hǎo zhèxiē, ránhòu dào chúxī, quán jiārén tuányuán, yīqǐ chī niányèfàn, fàng biānpào, qìngzhù xīnnián.', 'Trước tiên chuẩn bị xong những thứ này, rồi đến đêm Giao thừa, cả nhà đoàn tụ cùng ăn bữa cơm tất niên, đốt pháo mừng năm mới.', 15) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v17_16', 'lesson-17', '团圆', 'tuányuán', 'từ Hán ngữ', 'đoàn tụ, đoạn viên', 'Động từ', '囗 (Vi) (Vây quanh, không gian kín, lãnh thổ)', '团: 囗 (Vi: vòng tròn) + 才 (Tài: quây quần) • 圆: 囗 (Vi: vòng tròn ngoài) + 员 (Viên)', 'Ghép 团 [bộ 囗] + 圆 [bộ 囗] để nhớ từ 团圆 (tuányuán): "đoàn tụ, đoạn viên".', '先准备好这些，然后到除夕，全家人团圆，一起吃年夜饭、放鞭炮，庆祝新年。', 'Xiān zhǔnbèi hǎo zhèxiē, ránhòu dào chúxī, quán jiārén tuányuán, yīqǐ chī niányèfàn, fàng biānpào, qìngzhù xīnnián.', 'Trước tiên chuẩn bị xong những thứ này, rồi đến đêm Giao thừa, cả nhà đoàn tụ cùng ăn bữa cơm tất niên, đốt pháo mừng năm mới.', 16) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v17_17', 'lesson-17', '拜年', 'bàinián', 'niên', 'chúc Tết', 'Động từ', '手/扌 (Thủ) (Bàn tay, động tác, thao tác)', '拜: Hai bàn tay chắp vái lạy • 年: 𠂉 + 干/土 (mùa màng thu hoạch một năm)', 'Ghép 拜 [bộ 手] + 年 [bộ 干] để nhớ từ 拜年 (bàinián): "chúc Tết".', '对，还有红包。我还记得我小时候去亲戚家拜年，他们给我很多红包，真开心，但是现在没有了。', 'Duì, hái yǒu hóngbāo. Wǒ hái jìde wǒ xiǎoshíhou qù qīnqi jiā bàinián, tāmen gěi wǒ hěnduō hóngbāo, zhēn kāixīn, dànshì xiànzài méiyǒu le.', 'Đúng rồi, còn có lì xì nữa. Tôi vẫn nhớ hồi nhỏ đi chúc Tết họ hàng, mọi người mừng tuổi tôi rất nhiều bao lì xì, vui lắm, nhưng bây giờ thì không còn nữa rồi.', 17) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v17_18', 'lesson-17', '包', 'bāo', 'bao', 'gói (bánh)', 'Động từ', '勹 (Bao) (Bao bọc, ôm lấy)', '包 = 勹 (Bao: bọc lại) + 巳 (Tỵ: thai nhi bên trong).', 'Chữ 包 (bāo) mang nghĩa "gói (bánh)", bộ chính 勹 (Bao); cấu tạo: 勹 (Bao: bọc lại) + 巳 (Tỵ: thai nhi bên trong).', '要准备很多，比如打扫房子、买茶食、水果、贴春联、包饺子。', 'Yào zhǔnbèi hěnduō, bǐrú dǎsǎo fángzi, mǎi cháshi, shuǐguǒ, tiē chūnlián, bāo jiǎozi.', 'Phải chuẩn bị nhiều thứ lắm, ví dụ như dọn dẹp nhà cửa, mua bánh mứt, trái cây, dán câu đối Tết, gói sủi cảo.', 18) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v17_19', 'lesson-17', '打扫', 'dǎsǎo', 'từ Hán ngữ', 'dọn dẹp, quét dọn', 'Động từ', '手/扌 (Thủ) (Bàn tay, động tác, thao tác)', '打: 扌 (Thủ: bàn tay) + 丁 (Đinh) • 扫: 扌 (Thủ: tay cầm chổi) + 彐 (Kệ: đầu chổi quét)', 'Ghép 打 [bộ 扌] + 扫 [bộ 扌] để nhớ từ 打扫 (dǎsǎo): "dọn dẹp, quét dọn".', '要准备很多，比如打扫房子、买茶食、水果、贴春联、包饺子。', 'Yào zhǔnbèi hěnduō, bǐrú dǎsǎo fángzi, mǎi cháshi, shuǐguǒ, tiē chūnlián, bāo jiǎozi.', 'Phải chuẩn bị nhiều thứ lắm, ví dụ như dọn dẹp nhà cửa, mua bánh mứt, trái cây, dán câu đối Tết, gói sủi cảo.', 19) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v17_20', 'lesson-17', '贴', 'tiē', 'từ Hán ngữ', 'dán', 'Động từ', '贝 (Bối) (Vỏ sò, tiền bạc, giá trị)', '贴 = 贝 (Bối) + 占 (Chiếm: dán dính vào).', 'Chữ 贴 (tiē) mang nghĩa "dán", bộ chính 贝 (Bối); cấu tạo: 贝 (Bối) + 占 (Chiếm: dán dính vào).', '要准备很多，比如打扫房子、买茶食、水果、贴春联、包饺子。', 'Yào zhǔnbèi hěnduō, bǐrú dǎsǎo fángzi, mǎi cháshi, shuǐguǒ, tiē chūnlián, bāo jiǎozi.', 'Phải chuẩn bị nhiều thứ lắm, ví dụ như dọn dẹp nhà cửa, mua bánh mứt, trái cây, dán câu đối Tết, gói sủi cảo.', 20) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v17_21', 'lesson-17', '放', 'fàng', 'từ Hán ngữ', 'đốt (pháo)', 'Động từ', '攴/攵 (Phộc) (Đánh khẽ, hành động, dạy dỗ)', '放 = 方 (Phương) + 攵 (Phộc: buông thả ra).', 'Chữ 放 (fàng) mang nghĩa "đốt (pháo)", bộ chính 攴/攵 (Phộc); cấu tạo: 方 (Phương) + 攵 (Phộc: buông thả ra).', '你放心吧！', 'Nǐ fàngxīn ba!', 'Cậu yên tâm đi!', 21) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v17_22', 'lesson-17', '传统', 'chuántǒng', 'từ Hán ngữ', 'truyền thống', 'Tính từ / Danh từ', '人/亻 (Nhân) (Con người, nhân loại, hành động)', '传: 亻 (Nhân đứng: người) + 专 (Chuyên: truyền lại) • 统: 纟 (Mịch: sợi dây xâu chuỗi) + 充 (Sung)', 'Ghép 传 [bộ 亻] + 统 [bộ 纟] để nhớ từ 传统 (chuántǒng): "truyền thống".', '对，春节是中国的一个重要传统节日。', 'Duì, Chūnjié shì Zhōngguó de yígè zhòngyào chuántǒng jiérì.', 'Đúng vậy, Tết Nguyên Đán là một ngày lễ truyền thống quan trọng của Trung Quốc.', 22) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v17_23', 'lesson-17', '重要', 'zhòngyào', 'yếu', 'quan trọng', 'Tính từ', '里 (Lý) (Làng xóm, bên trong, dặm đường)', '重: 千 (Thiên) + 里 (Lý: nặng nề, trùng lặp) • 要: 覀 (Tây biến thể) + 女 (Nữ)', 'Ghép 重 [bộ 里] + 要 [bộ 西] để nhớ từ 重要 (zhòngyào): "quan trọng".', '对，春节是中国的一个重要传统节日。', 'Duì, Chūnjié shì Zhōngguó de yígè zhòngyào chuántǒng jiérì.', 'Đúng vậy, Tết Nguyên Đán là một ngày lễ truyền thống quan trọng của Trung Quốc.', 23) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v17_24', 'lesson-17', '开心', 'kāixīn', 'từ Hán ngữ', 'vui vẻ, hạnh phúc', 'Tính từ', '廾 (Củng) (Hai tay chắp, nâng đỡ)', '开: 一 + 廾 (Củng: hai tay mở rộng) • 心: Bộ 心 (Tâm - hình trái tim)', 'Ghép 开 [bộ 廾] + 心 [bộ 心] để nhớ từ 开心 (kāixīn): "vui vẻ, hạnh phúc".', '对，还有红包。我还记得我小时候去亲戚家拜年，他们给我很多红包，真开心，但是现在没有了。', 'Duì, hái yǒu hóngbāo. Wǒ hái jìde wǒ xiǎoshíhou qù qīnqi jiā bàinián, tāmen gěi wǒ hěnduō hóngbāo, zhēn kāixīn, dànshì xiànzài méiyǒu le.', 'Đúng rồi, còn có lì xì nữa. Tôi vẫn nhớ hồi nhỏ đi chúc Tết họ hàng, mọi người mừng tuổi tôi rất nhiều bao lì xì, vui lắm, nhưng bây giờ thì không còn nữa rồi.', 24) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v17_25', 'lesson-17', '有意思', 'yǒuyìsi', 'hữu', 'thú vị, có ý nghĩa', 'Tính từ', '月 (Nguyệt/Nhục) (Mặt trăng hoặc các bộ phận thân thể người)', '有: 𠂇 (bàn tay) + 月 (Nguyệt/Nhục: cầm miếng thịt là có) • 意: 音 (Âm: tiếng nói) + 心 (Tâm: ý nghĩ trong lòng) • 思: 田 (Điền: hộp sọ/não) + 心 (Tâm: trái tim suy nghĩ)', 'Ghép 有 [bộ 月] + 意 [bộ 心] + 思 [bộ 心] để nhớ từ 有意思 (yǒuyìsi): "thú vị, có ý nghĩa".', '哇！春节真有意思！我也想过春节。', 'Wa! Chūnjié zhēn yǒuyìsi! Wǒ yě xiǎngguò chūnjié.', 'Chà! Tết thú vị thật đấy! Tôi cũng muốn đón Tết.', 25) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v17_26', 'lesson-17', '新年快乐', 'xīnnián kuàilè', 'tân niên khoái lạc', 'chúc mừng năm mới', 'Cụm từ / Tên riêng', '斤 (Cân) (Cái rìu, đơn vị cân nặng)', '新: 立 + 木 (Tân) + 斤 (Cân: rìu chặt gỗ mới) • 年: 𠂉 + 干/土 (mùa màng thu hoạch một năm) • 快: 忄 (Tâm đứng: cảm xúc) + 夬 (Quái: nhanh, vui) • 乐: Nét phẩy trên nhạc cụ dây/trống gỗ (vui vẻ, âm nhạc)', 'Ghép 新 [bộ 斤] + 年 [bộ 干] + 快 [bộ 忄] + 乐 [bộ 丿] để nhớ từ 新年快乐 (xīnnián kuàilè): "chúc mừng năm mới".', '这是关于“新年快乐”的常用句子。', 'Zhè shì guānyú ''xīnnián kuàilè'' de chángyòng jùzi.', 'Đây là câu ví dụ sử dụng từ ''新年快乐'' (chúc mừng năm mới).', 26) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v17_27', 'lesson-17', '好好儿', 'hǎohāor', 'hảo hảo nhi', 'chăm chỉ, cố gắng, thỏa sức...', 'Tính từ / Phó từ', '女 (Nữ) (Phụ nữ, gia đình, tình cảm)', '好: 女 (Nữ: người mẹ) + 子 (Tử: đứa con) • 好: 女 (Nữ: người mẹ) + 子 (Tử: đứa con) • 儿: Bộ 儿 (Nhi - nét cong, chữ độc thể)', 'Ghép 好 [bộ 女] + 好 [bộ 女] + 儿 [bộ 儿] để nhớ từ 好好儿 (hǎohāor): "chăm chỉ, cố gắng, thỏa sức...".', '你好好儿读书吧！', 'Nǐ hǎohāor dúshū ba!', 'Con cố gắng học hành đi!', 27) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v17_28', 'lesson-17', '在一块儿', 'zài yíkuàir', 'tại khối nhi', 'ở bên nhau', 'Cụm từ / Tên riêng', '土 (Thổ) (Đất đai, vị trí, công trình)', '在: 𠂇 + 土 (Thổ: tồn tại trên mặt đất) • 一: Bộ 一 (Nhất - 1 nét ngang, số 1) • 块: 土 (Thổ: cục đất) + 夬 (Quái) • 儿: Bộ 儿 (Nhi - nét cong, chữ độc thể)', 'Ghép 在 [bộ 土] + 一 [bộ 一] + 块 [bộ 土] + 儿 [bộ 儿] để nhớ từ 在一块儿 (zài yíkuàir): "ở bên nhau".', '那么今年春节请你们到我们家做客，我们在一块儿好好儿过年，一定会很快乐。', 'Nàme jīnnián Chūnjié qǐng nǐmen dào wǒmen jiā zuòkè, wǒmen zài yíkuàir hǎohāor guònián, yídìng huì hěn kuàilè.', 'Vậy Tết năm nay mời các bạn đến nhà chúng tôi chơi, chúng ta cùng nhau đón Tết thật vui vẻ, chắc chắn sẽ rất hạnh phúc.', 28) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v17_29', 'lesson-17', '先...... 然后......', 'xiān... ránhòu...', 'hậu', 'đầu tiên... sau đó...', 'Cụm từ / Tên riêng', '儿 (Nhi) (Trẻ nhỏ, phần chân nâng đỡ)', '先: 𠂉 + 土 + 儿 (Nhi: người bước đi trước) • 然: 肰 (Nhiên) + 灬 (Hỏa: ngọn lửa đốt) • 后: 厂 + 一 + 口 (Khẩu: phía sau)', 'Ghép 先 [bộ 儿] + 然 [bộ 灬] + 后 [bộ 口] để nhớ từ 先...... 然后...... (xiān... ránhòu...): "đầu tiên... sau đó...".', '这是关于“先...... 然后......”的常用句子。', 'Zhè shì guānyú ''xiān... ránhòu...'' de chángyòng jùzi.', 'Đây là câu ví dụ sử dụng từ ''先...... 然后......'' (đầu tiên... sau đó...).', 29) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order) VALUES ('g17_1', 'lesson-17', '1. 祈使句 – Câu cầu khiến', 'Cấu trúc câu ngữ pháp trọng tâm', ' Là câu có chủ ngữ ở ngôi thứ 2 hoặc ngôi thứ nhất số nhiều, có thể dùng để biểu thị mệnh lệnh, thỉnh cầu, kiến nghị… Cuối câu thường kết hợp với trợ từ ngữ khí “吧” 你去吃饭吧！ Nǐ qù chīfàn ba! Cậu đi ăn cơm đi! 你放心吧！ Nǐ fàngxīn ba! Cậu yên tâm đi! 你好好儿读书', NULL, '[{"hanzi":"你去吃饭吧！","pinyin":"Nǐ qù chīfàn ba!","meaning":"Cậu đi ăn cơm đi!"},{"hanzi":"你放心吧！","pinyin":"Nǐ fàngxīn ba!","meaning":"Cậu yên tâm đi!"}]'::jsonb, 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order) VALUES ('g17_2', 'lesson-17', '2. 好好儿', 'Cấu trúc câu ngữ pháp trọng tâm', ' a) Là tính từ - tốt lành, ổn Diễn tả tình hình vẫn ổn, bình thường 手机刚才还好好儿的，怎么就坏了。 Shǒujī gāngcái hái hǎohāor de, zěnme jiù huài le. Điện thoại vừa nãy còn tốt lắm mà, sao đã hỏng rồi. 这棵树活了 50 年，现在还好好儿的。 Zhè kē shù huó le 50 nián, xiànzài hái hǎoh', NULL, '[{"hanzi":"你好好儿读书吧！","pinyin":"Nǐ hǎohāor dúshū ba!","meaning":"Con cố gắng học hành đi!"},{"hanzi":"你别哭了！","pinyin":"Nǐ bié kū le!","meaning":"Cậu đừng khóc nữa!"}]'::jsonb, 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order) VALUES ('g17_3', 'lesson-17', '3. 先......，然后......:Đầu tiên..., sau đó…', 'Cấu trúc câu ngữ pháp trọng tâm', ' Biểu thị thứ tự về thời gian trước sau của động tác. 我先去银行取钱，然后去商店买东西。 Wǒ xiān qù yínháng qǔ qián, ránhòu qù shāngdiàn mǎi dōngxi. Tớ đến ngân hàng rút tiền trước rồi sau đó đi mua đồ. 他先回家洗澡，然后过来接我。 Tā xiān huí jiā xǐzǎo, ránhòu guòlái jiē wǒ. Anh ', NULL, '[{"hanzi":"你不要走！好不好？","pinyin":"Nǐ búyào zǒu! Hǎo bu hǎo?","meaning":"Anh đừng đi! Có được không?"},{"hanzi":"你已经喝了两瓶了，别喝了！","pinyin":"Nǐ yǐjīng hē le liǎng píng le, bié hē le!","meaning":"Anh đã uống 2 chai rồi, đừng uống nữa!"}]'::jsonb, 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order) VALUES ('g17_4', 'lesson-17', '4. 兼语句 – câu kiêm ngữ', 'Chủ ngữ + Động từ1 + Từ kiêm ngữ + Động từ2/Tính từ + Tân ngữ', ' a) Khái niệm: Câu kiêm ngữ là câu vị ngữ có hai động từ, tân ngữ của động từ thứ nhất là chủ ngữ của động từ thứ 2 (tân ngữ còn gọi là từ kiêm ngữ) b) Cấu trúc: c) Câu kiêm ngữ cầu khiến: 命令、......Đối với loại câu này, khi phủ định thì ta thêm phó t', NULL, '[{"hanzi":"手机刚才还好好儿的，怎么就坏了。","pinyin":"Shǒujī gāngcái hái hǎohāor de, zěnme jiù huài le.","meaning":"Điện thoại vừa nãy còn tốt lắm mà, sao đã hỏng rồi."},{"hanzi":"你再好好儿想一想。","pinyin":"Nǐ zài hǎohāor xiǎng yī xiǎng.","meaning":"Cậu hãy cố gắng nghĩ nữa đi."}]'::jsonb, 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order;
INSERT INTO texts (id, lesson_id, title, description, sort_order) VALUES ('txt_17_1', 'lesson-17', 'Bài khoá #1: Hội thoại giáo trình — Tết', 'Hội thoại chuẩn giáo trình Bài 17. Từ vựng chưa học được chú thích phiên âm & nghĩa trong ngoặc.', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_17_1_1', 'txt_17_1', '安妮', '我听几个朋友说快到春节了，春节是你们的一个节日，对吗？', '我听 (tīng: nghe)几个朋友说快 (kuài: nhanh)到春节了，春节是你们的一个节日，对吗？', 'Wǒ tīng jǐ gè péngyou shuō kuài dào Chūnjié le, Chūnjié shì nǐmen de yígè jiérì, duì ma?', 'Tôi nghe mấy người bạn nói sắp đến Tết Nguyên Đán rồi, Tết là một ngày lễ của các bạn đúng không?', 1) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_17_1_2', 'txt_17_1', '白茹雪', '对，春节是中国的一个重要传统节日。', '对，春节是中国 (Zhōngguó: Trung Quốc)的一个重要传统节日。', 'Duì, Chūnjié shì Zhōngguó de yígè zhòngyào chuántǒng jiérì.', 'Đúng vậy, Tết Nguyên Đán là một ngày lễ truyền thống quan trọng của Trung Quốc.', 2) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_17_1_3', 'txt_17_1', '范玉兰', '我们越南人也有春节，和中国的春节差不多。', '我们越南人也有春节，和中国 (Zhōngguó: Trung Quốc)的春节差不多。', 'Wǒmen Yuènán rén yě yǒu Chūnjié, hé Zhōngguó de Chūnjié chàbuduō.', 'Người Việt Nam chúng tôi cũng có Tết Nguyên Đán, khá giống Tết ở Trung Quốc.', 3) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_17_1_4', 'txt_17_1', '安妮', '你们怎么准备过年？', '你们怎么准备过年？', 'Nǐmen zěnme zhǔnbèi guònián?', 'Các bạn chuẩn bị đón Tết thế nào?', 4) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_17_1_5', 'txt_17_1', '白茹雪', '要准备很多，比如打扫房子、买茶食、水果、贴春联、包饺子。', '要准备很多，比如打扫房子、买茶食、水果、贴春联、包饺子。', 'Yào zhǔnbèi hěnduō, bǐrú dǎsǎo fángzi, mǎi cháshi, shuǐguǒ, tiē chūnlián, bāo jiǎozi.', 'Phải chuẩn bị nhiều thứ lắm, ví dụ như dọn dẹp nhà cửa, mua bánh mứt, trái cây, dán câu đối Tết, gói sủi cảo.', 5) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_17_1_6', 'txt_17_1', '范玉兰', '我们越南不包饺子，我们包粽子。', '我们越南不包饺子，我们包粽子。', 'Wǒmen Yuènán bù bāo jiǎozi, wǒmen bāo zòngzi.', 'Việt Nam chúng tôi không gói sủi cảo, chúng tôi gói bánh chưng.', 6) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_17_1_7', 'txt_17_1', '妮妮', '然后呢？', '然后呢？', 'Ránhòu ne?', 'Sau đó thì sao?', 7) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_17_1_8', 'txt_17_1', '白茹雪', '先准备好这些，然后到除夕，全家人团圆，一起吃年夜饭、放鞭炮，庆祝新年。', '先准备好这些 (xiē: vài, một ít)，然后到除夕，全家人团圆，一起吃年夜饭、放鞭炮，庆祝新年。', 'Xiān zhǔnbèi hǎo zhèxiē, ránhòu dào chúxī, quán jiārén tuányuán, yīqǐ chī niányèfàn, fàng biānpào, qìngzhù xīnnián.', 'Trước tiên chuẩn bị xong những thứ này, rồi đến đêm Giao thừa, cả nhà đoàn tụ cùng ăn bữa cơm tất niên, đốt pháo mừng năm mới.', 8) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_17_1_9', 'txt_17_1', '范玉兰', '对，还有红包。我还记得我小时候去亲戚家拜年，他们给我很多红包，真开心，但是现在没有了。', '对，还有红包。我还记 (jì: nhớ, ghi)得 (děi: phải)我小时 (xiǎoshí: tiếng, giờ đồng hồ)候去亲戚家拜年，他们给我很多红包，真开心，但是现在没有 (méiyǒu: không có)了。', 'Duì, hái yǒu hóngbāo. Wǒ hái jìde wǒ xiǎoshíhou qù qīnqi jiā bàinián, tāmen gěi wǒ hěnduō hóngbāo, zhēn kāixīn, dànshì xiànzài méiyǒu le.', 'Đúng rồi, còn có lì xì nữa. Tôi vẫn nhớ hồi nhỏ đi chúc Tết họ hàng, mọi người mừng tuổi tôi rất nhiều bao lì xì, vui lắm, nhưng bây giờ thì không còn nữa rồi.', 9) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_17_1_10', 'txt_17_1', '妮妮', '哇！春节真有意思！我也想过春节。', '哇 (wa: oa, chà (cảm thán))！春节真有意思！我也想过 (guò: từng, qua)春节。', 'Wa! Chūnjié zhēn yǒuyìsi! Wǒ yě xiǎngguò chūnjié.', 'Chà! Tết thú vị thật đấy! Tôi cũng muốn đón Tết.', 10) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_17_1_11', 'txt_17_1', '白茹雪', '那么今年春节请你们到我们家做客，我们在一块儿好好儿过年，一定会很快乐。', '那么今 (jīn: hôm nay, nay)年春节请你们到我们家做客，我们在一块儿好好儿过年，一定 (yīdìng: nhất định)会 (huì: Phó, đtnn biết)很快乐。', 'Nàme jīnnián Chūnjié qǐng nǐmen dào wǒmen jiā zuòkè, wǒmen zài yíkuàir hǎohāor guònián, yídìng huì hěn kuàilè.', 'Vậy Tết năm nay mời các bạn đến nhà chúng tôi chơi, chúng ta cùng nhau đón Tết thật vui vẻ, chắc chắn sẽ rất hạnh phúc.', 11) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_17_1_12', 'txt_17_1', '妮妮', '好！玉兰我们一起去吧！你才过越南春节，还没有过中国春节，对吗？', '好！玉兰我们一起去吧！你才 (cái: mới)过 (guò: từng, qua)越南春节，还没有 (méiyǒu: không có)过中国 (Zhōngguó: Trung Quốc)春节，对吗？', 'Hǎo! Yùlán wǒmen yīqǐ qù ba! Nǐ cái guò Yuènán Chūnjié, hái méiyǒu guò Zhōngguó Chūnjié, duì ma?', 'Được! Ngọc Lan chúng ta cùng đi nhé! Cậu mới đón Tết Việt Nam thôi, chưa từng đón Tết Trung Quốc đúng không?', 12) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_17_1_13', 'txt_17_1', '范玉兰', '嗯。到那时候我们一定要好好儿玩。', '嗯 (èn: ừ, ừm)。到那时候我们一定 (yīdìng: nhất định)要好好儿玩 (wán: chơi)。', 'Ēn. Dào nàge shíhou wǒmen yídìng yào hǎohāor wán.', 'Ừ. Đến lúc đó chúng ta nhất định phải chơi thật vui.', 13) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_17_1_1', 'lesson-17', 'txt_17_1', 'listening', 'listening', '我听几个朋友说快到春节了，春节是你们的一个节日，对吗？', NULL, 'Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Đây là sách của ai?","Tôi là Trần Anh.","Tôi nghe mấy người bạn nói sắp đến Tết Nguyên Đán rồi, Tết là một ngày lễ của các bạn đúng không?","Phía dưới bàn"]'::jsonb, 2, 'Nội dung nghe được: 我听几个朋友说快到春节了，春节是你们的一个节日，对吗？ (Wǒ tīng jǐ gè péngyou shuō kuài dào Chūnjié le, Chūnjié shì nǐmen de yígè jiérì, duì ma?) → Tôi nghe mấy người bạn nói sắp đến Tết Nguyên Đán rồi, Tết là một ngày lễ của các bạn đúng không?', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_17_1_2', 'lesson-17', 'txt_17_1', 'listening', 'listening', '对，春节是中国的一个重要传统节日。', NULL, 'Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["对，春节是中国 (Zhōngguó: Trung Quốc)的一个重要传统节日。","我听 (tīng: nghe)几个朋友说快 (kuài: nhanh)到春节了，春节是你们的一个节日，对吗？","我一定 (yīdìng: nhất định)要好好儿学习 (xuéxí: học tập)。","越南人过年的时候常包粽子和买花。"]'::jsonb, 0, 'Câu vừa đọc: 对，春节是中国的一个重要传统节日。 (Duì, Chūnjié shì Zhōngguó de yígè zhòngyào chuántǒng jiérì.) → Đúng vậy, Tết Nguyên Đán là một ngày lễ truyền thống quan trọng của Trung Quốc.', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_17_1_3', 'lesson-17', 'txt_17_1', 'listening', 'listening', '我们越南人也有春节，和中国的春节差不多。', NULL, 'Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Mỗi ngày anh ấy đều đến thư viện mượn sách.","Bạn tên là gì?","Em bé đang bị sốt.","Người Việt Nam chúng tôi cũng có Tết Nguyên Đán, khá giống Tết ở Trung Quốc."]'::jsonb, 3, 'Nội dung nghe được: 我们越南人也有春节，和中国的春节差不多。 (Wǒmen Yuènán rén yě yǒu Chūnjié, hé Zhōngguó de Chūnjié chàbuduō.) → Người Việt Nam chúng tôi cũng có Tết Nguyên Đán, khá giống Tết ở Trung Quốc.', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_17_1_4', 'lesson-17', 'txt_17_1', 'listening', 'listening', '你们怎么准备过年？', NULL, 'Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["越南人过年的时候常包粽子和买花。","今天他让 (ràng: bảo, khiến)我下 (xià: dưới / xuống)个月出国 (chūguó: ra nước ngoài)。","他请我明天去他家吃饭。","你们怎么准备过年？"]'::jsonb, 3, 'Câu vừa đọc: 你们怎么准备过年？ (Nǐmen zěnme zhǔnbèi guònián?) → Các bạn chuẩn bị đón Tết thế nào?', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO texts (id, lesson_id, title, description, sort_order) VALUES ('txt_17_2', 'lesson-17', 'Bài nghe tổng hợp: Ôn tập lũy tiến (Bài 1 – Bài 17)', 'Kết hợp từ vựng & mẫu câu đã học từ Bài 1 đến Bài 16 cùng trọng tâm Bài 17 để củng cố phản xạ nghe.', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_17_2_1', 'txt_17_2', 'Ôn Bài 16', '找找 = 找一找', '找找 = 找一找', 'zhǎozhao = zhǎo yi zhǎo', 'Tìm một chút, tìm qua.', 1) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_17_2_2', 'txt_17_2', 'Bài 17', '你去吃饭吧！', '你去吃饭吧！', 'Nǐ qù chīfàn ba!', 'Cậu đi ăn cơm đi!', 2) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_17_2_3', 'txt_17_2', 'Ôn Bài 8', '二十五个', '二十五个', 'èrshíwǔ gè', 'Hai mươi lăm cái', 3) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_17_2_4', 'txt_17_2', 'Bài 17', '你不要走！好不好？', '你不要走！好不好？', 'Nǐ búyào zǒu! Hǎo bu hǎo?', 'Anh đừng đi! Có được không?', 4) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_17_2_5', 'txt_17_2', 'Ôn Bài 1', '下午好！', '下午好！', 'Xiàwǔ hǎo', 'Chào buổi chiều!', 5) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_17_2_6', 'txt_17_2', 'Bài 17', '你再好好儿想一想。', '你再好好儿想一想。', 'Nǐ zài hǎohāor xiǎng yī xiǎng.', 'Cậu hãy cố gắng nghĩ nữa đi.', 6) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_17_2_7', 'txt_17_2', 'Ôn Bài 10', '天气太舒服了！', '天气太舒服了！', 'Tiānqì tài shūfu le!', 'Thời tiết dễ chịu quá!', 7) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_17_2_8', 'txt_17_2', 'Bài 17', '他请我明天去他家吃饭。', '他请我明天去他家吃饭。', 'Tā qǐng wǒ míngtiān qù tā jiā chīfàn.', 'Anh ta mời tôi ngày mai tới nhà dùng cơm.', 8) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_17_2_1', 'lesson-17', 'txt_17_2', 'listening', 'listening', '找找 = 找一找', NULL, '[Ôn tập Bài 16] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Tối hôm qua tôi đã ôn tập qua bài khóa rồi.","đất nước (quốc gia) của chúng tôi","Tìm một chút, tìm qua.","Nhà cậu có bao nhiêu người?"]'::jsonb, 2, 'Nội dung nghe được: 找找 = 找一找 (zhǎozhao = zhǎo yi zhǎo) → Tìm một chút, tìm qua.', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_17_2_2', 'lesson-17', 'txt_17_2', 'listening', 'listening', '你去吃饭吧！', NULL, '[Bài 17] Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["他先回家洗澡 (xǐzǎo: tắm rửa)，然后过 (guò: từng, qua)来 (lái: đến)接 (jiē: đón, nhận)我。","他不让 (ràng: bảo, khiến)我走。","你去吃饭吧！","我一定 (yīdìng: nhất định)要好好儿学习 (xuéxí: học tập)。"]'::jsonb, 2, 'Câu vừa đọc: 你去吃饭吧！ (Nǐ qù chīfàn ba!) → Cậu đi ăn cơm đi!', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_17_2_3', 'lesson-17', 'txt_17_2', 'listening', 'listening', '二十五个', NULL, '[Ôn tập Bài 8] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Một trang giấy","Hai mươi lăm cái","Tôi có mắt, tôi có thể nhìn. Tôi có tai, tôi có thể nghe.","Anh ấy là ai?"]'::jsonb, 1, 'Nội dung nghe được: 二十五个 (èrshíwǔ gè) → Hai mươi lăm cái', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_17_2_4', 'lesson-17', 'txt_17_2', 'listening', 'listening', '你不要走！好不好？', NULL, '[Bài 17] Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["你不要走！好不好？","你去吃饭吧！","你再好好儿想一想。","你们怎么准备过年？"]'::jsonb, 0, 'Câu vừa đọc: 你不要走！好不好？ (Nǐ búyào zǒu! Hǎo bu hǎo?) → Anh đừng đi! Có được không?', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_17_2_5', 'lesson-17', 'txt_17_2', 'listening', 'listening', '下午好！', NULL, '[Ôn tập Bài 1] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Ngày mai có lẽ là ngày nắng.","Bạn đã chuẩn bị đầy đủ đồ đạc để đi du lịch chưa?","Tôi dọn đồ xong sẽ đi.","Chào buổi chiều!"]'::jsonb, 3, 'Nội dung nghe được: 下午好！ (Xiàwǔ hǎo) → Chào buổi chiều!', 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO texts (id, lesson_id, title, description, sort_order) VALUES ('txt_17_3', 'lesson-17', 'Bài khoá mở rộng: Đón giao thừa cùng bạn bè (Mở rộng)', 'Hội thoại tình huống mới xây dựng dựa trên từ vựng và ngữ pháp Bài 17 (không trùng lặp nguyên văn giáo trình).', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_17_3_1', 'txt_17_3', 'Phong', '今年的除夕夜，欢迎你来我家过春节！', '今 (jīn: hôm nay, nay)年的除夕夜，欢迎你来 (lái: đến)我家过 (guò: từng, qua)春节！', 'Jīnnián de chúxī yè, huānyíng nǐ lái wǒ jiā guò Chūnjié!', 'Đêm Giao thừa năm nay mời cậu sang nhà tớ đón Tết nhé!', 1) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_17_3_2', 'txt_17_3', 'Lan', '谢谢！中国春节和越南春节都要大扫除、贴春联吧？', '谢谢！中国 (Zhōngguó: Trung Quốc)春节和越南春节都要大 (dà: to, lớn)扫除、贴春联吧？', 'Xièxie! Zhōngguó Chūnjié hé Yuènán Chūnjié dōu yào dàsǎochú, tiē chūnlián ba?', 'Cảm ơn cậu! Tết Trung Quốc và Tết Việt Nam đều dọn dẹp nhà cửa và dán câu đối đúng không?', 2) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_17_3_3', 'txt_17_3', 'Phong', '是的，除夕晚上全家一起吃年夜饭、放鞭炮，还会包饺子。', '是的，除夕晚上全家一起吃年夜饭、放鞭炮，还会 (huì: Phó, đtnn biết)包饺子。', 'Shì de, chúxī wǎnshang quán jiā yīqǐ chī niányèfàn, fàng biānpào, hái huì bāo jiǎozi.', 'Đúng rồi, tối Giao thừa cả nhà cùng ăn cơm tất niên, đốt pháo và còn gói sủi cảo nữa.', 3) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_17_3_4', 'txt_17_3', 'Lan', '太热闹了！我也想学怎么包饺子。', '太热闹了！我也想学 (xué: học)怎么包饺子。', 'Tài rènao le! Wǒ yě xiǎng xué zěnme bāo jiǎozi.', 'Náo nhiệt quá! Tớ cũng muốn học cách gói sủi cảo.', 4) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_17_3_1', 'lesson-17', 'txt_17_3', 'listening', 'listening', '今年的除夕夜，欢迎你来我家过春节！ 谢谢！中国春节和越南春节都要大扫除、贴春联吧？ 是的，除夕晚上全家一起吃年夜饭、放鞭炮，还会包饺子。 太热闹了！我也想学怎么包饺子。', NULL, '[Nghe hiểu tình huống mới] Điểm khác biệt trong hoạt động ngày Tết được nhắc đến là gì?', '["Chỉ ăn bánh mì vào đêm Giao thừa","Không dán câu đối ngày Tết","Ngọc Lan muốn học gói sủi cảo (包饺子) cùng gia đình Trương Phong đêm Giao thừa","Hai nước không tổ chức Tết"]'::jsonb, 2, 'Phong mời Lan sang ăn cơm tất niên, đốt pháo, gói sủi cảo và Lan nói ''我也想学怎么包饺子''.', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_17_3_2', 'lesson-17', 'txt_17_3', 'listening', 'listening', '今年的除夕夜，欢迎你来我家过春节！', NULL, '[Mở rộng] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Chạy một chuyến","Đêm Giao thừa năm nay mời cậu sang nhà tớ đón Tết nhé!","Mỗi học sinh đều đi học bằng xe buýt.","Tôi làm phiên dịch ở Bộ Ngoại giao."]'::jsonb, 1, 'Nội dung nghe được: 今年的除夕夜，欢迎你来我家过春节！ (Jīnnián de chúxī yè, huānyíng nǐ lái wǒ jiā guò Chūnjié!) → Đêm Giao thừa năm nay mời cậu sang nhà tớ đón Tết nhé!', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_17_3_3', 'lesson-17', 'txt_17_3', 'listening', 'listening', '谢谢！中国春节和越南春节都要大扫除、贴春联吧？', NULL, '[Mở rộng] Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["你要好好儿跟 (gēn: cùng, với)他谈 (tán: nói, bàn)，别 (bié: đừng)着急 (zháojí: lo lắng, sốt ruột)。","谢谢！中国 (Zhōngguó: Trung Quốc)春节和越南春节都要大 (dà: to, lớn)扫除、贴春联吧？","手机刚才 (gāngcái: vừa nãy)还好好儿的，怎么就坏 (huài: xấu, hỏng)了。","我先去银行 (xíng: được)取 (qǔ: lấy)钱，然后去商店买东西。"]'::jsonb, 1, 'Câu vừa đọc: 谢谢！中国春节和越南春节都要大扫除、贴春联吧？ (Xièxie! Zhōngguó Chūnjié hé Yuènán Chūnjié dōu yào dàsǎochú, tiē chūnlián ba?) → Cảm ơn cậu! Tết Trung Quốc và Tết Việt Nam đều dọn dẹp nhà cửa và dán câu đối đúng không?', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_17_3_4', 'lesson-17', 'txt_17_3', 'listening', 'listening', '是的，除夕晚上全家一起吃年夜饭、放鞭炮，还会包饺子。', NULL, '[Mở rộng] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Cậu đi gì đến siêu thị thế?","Em trai tôi chơi trong vườn hoa.","bút bi của cô ấy","Đúng rồi, tối Giao thừa cả nhà cùng ăn cơm tất niên, đốt pháo và còn gói sủi cảo nữa."]'::jsonb, 3, 'Nội dung nghe được: 是的，除夕晚上全家一起吃年夜饭、放鞭炮，还会包饺子。 (Shì de, chúxī wǎnshang quán jiā yīqǐ chī niányèfàn, fàng biānpào, hái huì bāo jiǎozi.) → Đúng rồi, tối Giao thừa cả nhà cùng ăn cơm tất niên, đốt pháo và còn gói sủi cảo nữa.', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss17_1', 'lesson-17', '爷爷奶奶给我和弟弟发了大红包', '[Mở rộng] Ông bà nội đã lì xì cho tôi và em trai bao lì xì lớn.', 'Yéye nǎinai gěi wǒ hé dìdi fā le dà hóngbāo.', '["爷爷","奶奶","给我和","弟弟","发了大","红包"]'::jsonb, 'Từ chưa học: 大 (dà: to, lớn)', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss17_2', 'lesson-17', '春节期间我去看望了很多亲戚', '[Mở rộng] Trong dịp Tết tôi đã đi thăm hỏi rất nhiều họ hàng.', 'Chūnjié qījiān wǒ qù kànwàng le hěnduō qīnqi.', '["春节","期间","我去看","望了","很多","亲戚"]'::jsonb, NULL, 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss17_3', 'lesson-17', '你去吃饭吧', 'Cậu đi ăn cơm đi!', 'Nǐ qù chīfàn ba!', '["你","去","吃","饭","吧"]'::jsonb, NULL, 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss17_4', 'lesson-17', '你再好好儿想一想', 'Cậu hãy cố gắng nghĩ nữa đi.', 'Nǐ zài hǎohāor xiǎng yī xiǎng.', '["你","再","好好儿","想","一","想"]'::jsonb, NULL, 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss17_5', 'lesson-17', '张风也是学校的学生', '[Ôn tập Bài 2] Trương Phong cũng là học sinh của trường.', 'Zhāng Fēng yě shì xuéxiào de xuésheng.', '["张风","也","是","学校","的","学生"]'::jsonb, NULL, 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss17_6', 'lesson-17', '我的朋友在食堂吃饭', '[Ôn tập Bài 4] Bạn của tôi đang ăn cơm ở nhà ăn.', 'Wǒ de péngyou zài shítáng chīfàn.', '["我的","朋友","在","食堂","吃","饭"]'::jsonb, NULL, 6) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss17_exp_1', 'lesson-17', '我听几个朋友说快到春节了春节是你们的一个节日对吗', 'Tôi nghe mấy người bạn nói sắp đến Tết Nguyên Đán rồi, Tết là một ngày lễ của các bạn đúng không?', 'Wǒ tīng jǐ gè péngyou shuō kuài dào Chūnjié le, Chūnjié shì nǐmen de yígè jiérì, duì ma?', '["我","听","几","个","朋友","说","快","到","春节","了","春节","是","你们","的","一","个","节日","对","吗"]'::jsonb, NULL, 7) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss17_exp_2', 'lesson-17', '对春节是中国的一个重要传统节日', 'Đúng vậy, Tết Nguyên Đán là một ngày lễ truyền thống quan trọng của Trung Quốc.', 'Duì, Chūnjié shì Zhōngguó de yígè zhòngyào chuántǒng jiérì.', '["对","春节","是","中国","的","一","个","重要","传统","节日"]'::jsonb, NULL, 8) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss17_exp_3', 'lesson-17', '我们越南人也有春节和中国的春节差不多', 'Người Việt Nam chúng tôi cũng có Tết Nguyên Đán, khá giống Tết ở Trung Quốc.', 'Wǒmen Yuènán rén yě yǒu Chūnjié, hé Zhōngguó de Chūnjié chàbuduō.', '["我们","越南","人","也","有","春节","和","中国","的","春节","差不多"]'::jsonb, NULL, 9) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss17_exp_4', 'lesson-17', '你们怎么准备过年', 'Các bạn chuẩn bị đón Tết thế nào?', 'Nǐmen zěnme zhǔnbèi guònián?', '["你们","怎么","准备","过年"]'::jsonb, NULL, 10) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss17_exp_5', 'lesson-17', '要准备很多比如打扫房子买茶食水果贴春联包饺子', 'Phải chuẩn bị nhiều thứ lắm, ví dụ như dọn dẹp nhà cửa, mua bánh mứt, trái cây, dán câu đối Tết, gói sủi cảo.', 'Yào zhǔnbèi hěnduō, bǐrú dǎsǎo fángzi, mǎi cháshi, shuǐguǒ, tiē chūnlián, bāo jiǎozi.', '["要","准备","很","多","比如","打扫","房子","买","茶食","水果","贴","春联","包","饺子"]'::jsonb, NULL, 11) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss17_exp_6', 'lesson-17', '我们越南不包饺子我们包粽子', 'Việt Nam chúng tôi không gói sủi cảo, chúng tôi gói bánh chưng.', 'Wǒmen Yuènán bù bāo jiǎozi, wǒmen bāo zòngzi.', '["我们","越南","不","包","饺子","我们","包","粽子"]'::jsonb, NULL, 12) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss17_exp_7', 'lesson-17', '然后呢', 'Sau đó thì sao?', 'Ránhòu ne?', '["然","后","呢"]'::jsonb, NULL, 13) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss17_exp_8', 'lesson-17', '先准备好这些然后到除夕全家人团圆一起吃年夜饭放鞭炮庆祝新年', 'Trước tiên chuẩn bị xong những thứ này, rồi đến đêm Giao thừa, cả nhà đoàn tụ cùng ăn bữa cơm tất niên, đốt pháo mừng năm mới.', 'Xiān zhǔnbèi hǎo zhèxiē, ránhòu dào chúxī, quán jiārén tuányuán, yīqǐ chī niányèfàn, fàng biānpào, qìngzhù xīnnián.', '["先","准备","好","这","些","然","后","到","除夕","全家","人","团圆","一起","吃","年夜饭","放","鞭炮","庆祝","新年"]'::jsonb, NULL, 14) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss17_exp_9', 'lesson-17', '对还有红包我还记得我小时候去亲戚家拜年他们给我很多红包真开心但是现在没有了', 'Đúng rồi, còn có lì xì nữa. Tôi vẫn nhớ hồi nhỏ đi chúc Tết họ hàng, mọi người mừng tuổi tôi rất nhiều bao lì xì, vui lắm, nhưng bây giờ thì không còn nữa rồi.', 'Duì, hái yǒu hóngbāo. Wǒ hái jìde wǒ xiǎoshíhou qù qīnqi jiā bàinián, tāmen gěi wǒ hěnduō hóngbāo, zhēn kāixīn, dànshì xiànzài méiyǒu le.', '["对","还","有","红包","我","还","记","得","我","小","时候","去","亲戚","家","拜年","他们","给","我","很","多","红包","真","开心","但是","现在","没有","了"]'::jsonb, NULL, 15) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss17_exp_10', 'lesson-17', '哇春节真有意思我也想过春节', 'Chà! Tết thú vị thật đấy! Tôi cũng muốn đón Tết.', 'Wa! Chūnjié zhēn yǒuyìsi! Wǒ yě xiǎngguò chūnjié.', '["哇","春节","真","有意思","我","也","想","过","春节"]'::jsonb, NULL, 16) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss17_exp_11', 'lesson-17', '那么今年春节请你们到我们家做客我们在一块儿好好儿过年一定会很快乐', 'Vậy Tết năm nay mời các bạn đến nhà chúng tôi chơi, chúng ta cùng nhau đón Tết thật vui vẻ, chắc chắn sẽ rất hạnh phúc.', 'Nàme jīnnián Chūnjié qǐng nǐmen dào wǒmen jiā zuòkè, wǒmen zài yíkuàir hǎohāor guònián, yídìng huì hěn kuàilè.', '["那么","今","年","春节","请","你们","到","我们","家","做客","我们","在一块儿","好好儿","过年","一","定","会","很","快乐"]'::jsonb, NULL, 17) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss17_exp_12', 'lesson-17', '好玉兰我们一起去吧你才过越南春节还没有过中国春节对吗', 'Được! Ngọc Lan chúng ta cùng đi nhé! Cậu mới đón Tết Việt Nam thôi, chưa từng đón Tết Trung Quốc đúng không?', 'Hǎo! Yùlán wǒmen yīqǐ qù ba! Nǐ cái guò Yuènán Chūnjié, hái méiyǒu guò Zhōngguó Chūnjié, duì ma?', '["好","玉","兰","我们","一起","去","吧","你","才","过","越南","春节","还","没有","过","中国","春节","对","吗"]'::jsonb, NULL, 18) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss17_exp_13', 'lesson-17', '嗯到那时候我们一定要好好儿玩', 'Ừ. Đến lúc đó chúng ta nhất định phải chơi thật vui.', 'Ēn. Dào nàge shíhou wǒmen yídìng yào hǎohāor wán.', '["嗯","到","那","时候","我们","一","定","要","好好儿","玩"]'::jsonb, NULL, 19) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss17_exp_14', 'lesson-17', '找找找一找', 'Tìm một chút, tìm qua.', 'zhǎozhao = zhǎo yi zhǎo', '["找","找","找","一","找"]'::jsonb, NULL, 20) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr17_vi_1', 'lesson-17', 'vi_to_zh', '[Mở rộng] Người Việt Nam dịp Tết thường gói bánh chưng và mua hoa.', NULL, NULL, '越南人过年的时候常包粽子和买花。', NULL, 'yuènán rén guònián de shíhou cháng bāo zòngzi hé mǎi huā', '[]'::jsonb, 'Gợi ý Pinyin: Yuènán rén guònián de shíhou cháng bāo zòngzi hé mǎi huā.', 'Người Việt Nam dịp Tết thường gói bánh chưng và mua hoa. → 越南人过年的时候常包粽子和买花。 (Yuènán rén guònián de shíhou cháng bāo zòngzi hé mǎi huā.)', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr17_vi_2', 'lesson-17', 'vi_to_zh', '[Mở rộng] Chúng tôi dán câu đối và đốt pháo trước nhà để mừng năm mới.', NULL, NULL, '我们在房子前面贴春联、放鞭炮庆祝新年。', NULL, 'wǒmen zài fángzi qiánmian tiē chūnlián fàng biānpào qìngzhù xīnnián', '[]'::jsonb, 'Gợi ý Pinyin: Wǒmen zài fángzi qiánmian tiē chūnlián, fàng biānpào qìngzhù xīnnián.', 'Chúng tôi dán câu đối và đốt pháo trước nhà để mừng năm mới. → 我们在房子前面贴春联、放鞭炮庆祝新年。 (Wǒmen zài fángzi qiánmian tiē chūnlián, fàng biānpào qìngzhù xīnnián.)', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr17_vi_3', 'lesson-17', 'vi_to_zh', 'Cậu đi ăn cơm đi!', NULL, NULL, '你去吃饭吧！', NULL, 'nǐ qù chīfàn ba', '[]'::jsonb, 'Gợi ý Pinyin: Nǐ qù chīfàn ba!', 'Cậu đi ăn cơm đi! → 你去吃饭吧！ (Nǐ qù chīfàn ba!)', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr17_vi_4', 'lesson-17', 'vi_to_zh', 'Anh đừng đi! Có được không?', NULL, NULL, '你不要走！好不好？', NULL, 'nǐ búyào zǒu hǎo bu hǎo', '[]'::jsonb, 'Gợi ý Pinyin: Nǐ búyào zǒu! Hǎo bu hǎo?', 'Anh đừng đi! Có được không? → 你不要走！好不好？ (Nǐ búyào zǒu! Hǎo bu hǎo?)', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr17_vi_exp_1', 'lesson-17', 'vi_to_zh', 'Tôi nghe mấy người bạn nói sắp đến Tết Nguyên Đán rồi, Tết là một ngày lễ của các bạn đúng không?', NULL, NULL, '我听几个朋友说快到春节了，春节是你们的一个节日，对吗？', NULL, 'wǒ tīng jǐ gè péngyou shuō kuài dào chūnjié le chūnjié shì nǐmen de yígè jiérì duì ma', '[]'::jsonb, 'Gợi ý Pinyin: Wǒ tīng jǐ gè péngyou shuō kuài dào Chūnjié le, Chūnjié shì nǐmen de yígè jiérì, duì ma?', 'Tôi nghe mấy người bạn nói sắp đến Tết Nguyên Đán rồi, Tết là một ngày lễ của các bạn đúng không? → 我听几个朋友说快到春节了，春节是你们的一个节日，对吗？ (Wǒ tīng jǐ gè péngyou shuō kuài dào Chūnjié le, Chūnjié shì nǐmen de yígè jiérì, duì ma?)', 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
