INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr17_vi_exp_3', 'lesson-17', 'vi_to_zh', 'Người Việt Nam chúng tôi cũng có Tết Nguyên Đán, khá giống Tết ở Trung Quốc.', NULL, NULL, '我们越南人也有春节，和中国的春节差不多。', NULL, 'wǒmen yuènán rén yě yǒu chūnjié hé zhōngguó de chūnjié chàbuduō', '[]'::jsonb, 'Gợi ý Pinyin: Wǒmen Yuènán rén yě yǒu Chūnjié, hé Zhōngguó de Chūnjié chàbuduō.', 'Người Việt Nam chúng tôi cũng có Tết Nguyên Đán, khá giống Tết ở Trung Quốc. → 我们越南人也有春节，和中国的春节差不多。 (Wǒmen Yuènán rén yě yǒu Chūnjié, hé Zhōngguó de Chūnjié chàbuduō.)', 7) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr17_vi_exp_4', 'lesson-17', 'vi_to_zh', 'Các bạn chuẩn bị đón Tết thế nào?', NULL, NULL, '你们怎么准备过年？', NULL, 'nǐmen zěnme zhǔnbèi guònián', '[]'::jsonb, 'Gợi ý Pinyin: Nǐmen zěnme zhǔnbèi guònián?', 'Các bạn chuẩn bị đón Tết thế nào? → 你们怎么准备过年？ (Nǐmen zěnme zhǔnbèi guònián?)', 8) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr17_vi_exp_5', 'lesson-17', 'vi_to_zh', 'Phải chuẩn bị nhiều thứ lắm, ví dụ như dọn dẹp nhà cửa, mua bánh mứt, trái cây, dán câu đối Tết, gói sủi cảo.', NULL, NULL, '要准备很多，比如打扫房子、买茶食、水果、贴春联、包饺子。', NULL, 'yào zhǔnbèi hěnduō bǐrú dǎsǎo fángzi mǎi cháshi shuǐguǒ tiē chūnlián bāo jiǎozi', '[]'::jsonb, 'Gợi ý Pinyin: Yào zhǔnbèi hěnduō, bǐrú dǎsǎo fángzi, mǎi cháshi, shuǐguǒ, tiē chūnlián, bāo jiǎozi.', 'Phải chuẩn bị nhiều thứ lắm, ví dụ như dọn dẹp nhà cửa, mua bánh mứt, trái cây, dán câu đối Tết, gói sủi cảo. → 要准备很多，比如打扫房子、买茶食、水果、贴春联、包饺子。 (Yào zhǔnbèi hěnduō, bǐrú dǎsǎo fángzi, mǎi cháshi, shuǐguǒ, tiē chūnlián, bāo jiǎozi.)', 9) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr17_vi_exp_6', 'lesson-17', 'vi_to_zh', 'Việt Nam chúng tôi không gói sủi cảo, chúng tôi gói bánh chưng.', NULL, NULL, '我们越南不包饺子，我们包粽子。', NULL, 'wǒmen yuènán bù bāo jiǎozi wǒmen bāo zòngzi', '[]'::jsonb, 'Gợi ý Pinyin: Wǒmen Yuènán bù bāo jiǎozi, wǒmen bāo zòngzi.', 'Việt Nam chúng tôi không gói sủi cảo, chúng tôi gói bánh chưng. → 我们越南不包饺子，我们包粽子。 (Wǒmen Yuènán bù bāo jiǎozi, wǒmen bāo zòngzi.)', 10) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr17_vi_exp_7', 'lesson-17', 'vi_to_zh', 'Sau đó thì sao?', NULL, NULL, '然后呢？', NULL, 'ránhòu ne', '[]'::jsonb, 'Gợi ý Pinyin: Ránhòu ne?', 'Sau đó thì sao? → 然后呢？ (Ránhòu ne?)', 11) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr17_vi_exp_8', 'lesson-17', 'vi_to_zh', 'Trước tiên chuẩn bị xong những thứ này, rồi đến đêm Giao thừa, cả nhà đoàn tụ cùng ăn bữa cơm tất niên, đốt pháo mừng năm mới.', NULL, NULL, '先准备好这些，然后到除夕，全家人团圆，一起吃年夜饭、放鞭炮，庆祝新年。', NULL, 'xiān zhǔnbèi hǎo zhèxiē ránhòu dào chúxī quán jiārén tuányuán yīqǐ chī niányèfàn fàng biānpào qìngzhù xīnnián', '[]'::jsonb, 'Gợi ý Pinyin: Xiān zhǔnbèi hǎo zhèxiē, ránhòu dào chúxī, quán jiārén tuányuán, yīqǐ chī niányèfàn, fàng biānpào, qìngzhù xīnnián.', 'Trước tiên chuẩn bị xong những thứ này, rồi đến đêm Giao thừa, cả nhà đoàn tụ cùng ăn bữa cơm tất niên, đốt pháo mừng năm mới. → 先准备好这些，然后到除夕，全家人团圆，一起吃年夜饭、放鞭炮，庆祝新年。 (Xiān zhǔnbèi hǎo zhèxiē, ránhòu dào chúxī, quán jiārén tuányuán, yīqǐ chī niányèfàn, fàng biānpào, qìngzhù xīnnián.)', 12) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr17_vi_exp_9', 'lesson-17', 'vi_to_zh', 'Đúng rồi, còn có lì xì nữa. Tôi vẫn nhớ hồi nhỏ đi chúc Tết họ hàng, mọi người mừng tuổi tôi rất nhiều bao lì xì, vui lắm, nhưng bây giờ thì không còn nữa rồi.', NULL, NULL, '对，还有红包。我还记得我小时候去亲戚家拜年，他们给我很多红包，真开心，但是现在没有了。', NULL, 'duì hái yǒu hóngbāo wǒ hái jìde wǒ xiǎoshíhou qù qīnqi jiā bàinián tāmen gěi wǒ hěnduō hóngbāo zhēn kāixīn dànshì xiànzài méiyǒu le', '[]'::jsonb, 'Gợi ý Pinyin: Duì, hái yǒu hóngbāo. Wǒ hái jìde wǒ xiǎoshíhou qù qīnqi jiā bàinián, tāmen gěi wǒ hěnduō hóngbāo, zhēn kāixīn, dànshì xiànzài méiyǒu le.', 'Đúng rồi, còn có lì xì nữa. Tôi vẫn nhớ hồi nhỏ đi chúc Tết họ hàng, mọi người mừng tuổi tôi rất nhiều bao lì xì, vui lắm, nhưng bây giờ thì không còn nữa rồi. → 对，还有红包。我还记得我小时候去亲戚家拜年，他们给我很多红包，真开心，但是现在没有了。 (Duì, hái yǒu hóngbāo. Wǒ hái jìde wǒ xiǎoshíhou qù qīnqi jiā bàinián, tāmen gěi wǒ hěnduō hóngbāo, zhēn kāixīn, dànshì xiànzài méiyǒu le.)', 13) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr17_vi_exp_10', 'lesson-17', 'vi_to_zh', 'Chà! Tết thú vị thật đấy! Tôi cũng muốn đón Tết.', NULL, NULL, '哇！春节真有意思！我也想过春节。', NULL, 'wa chūnjié zhēn yǒuyìsi wǒ yě xiǎngguò chūnjié', '[]'::jsonb, 'Gợi ý Pinyin: Wa! Chūnjié zhēn yǒuyìsi! Wǒ yě xiǎngguò chūnjié.', 'Chà! Tết thú vị thật đấy! Tôi cũng muốn đón Tết. → 哇！春节真有意思！我也想过春节。 (Wa! Chūnjié zhēn yǒuyìsi! Wǒ yě xiǎngguò chūnjié.)', 14) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr17_zh_1', 'lesson-17', 'zh_to_vi', '[Mở rộng] 春节是中国 (Zhōngguó: Trung Quốc)最重要、最热闹的传统节日。', '春节是中国最重要、最热闹的传统节日。', 'Chūnjié shì Zhōngguó zuì zhòngyào, zuì rènao de chuántǒng jiérì.', NULL, 'Tết Nguyên Đán là ngày lễ truyền thống quan trọng và náo nhiệt nhất của Trung Quốc.', NULL, '["Tết","Nguyên","Đán"]'::jsonb, 'Pinyin: Chūnjié shì Zhōngguó zuì zhòngyào, zuì rènao de chuántǒng jiérì.', '春节是中国最重要、最热闹的传统节日。 (Chūnjié shì Zhōngguó zuì zhòngyào, zuì rènao de chuántǒng jiérì.) nghĩa là: Tết Nguyên Đán là ngày lễ truyền thống quan trọng và náo nhiệt nhất của Trung Quốc.', 15) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr17_zh_2', 'lesson-17', 'zh_to_vi', '[Mở rộng] 除夕夜全家人一起包饺子、吃年夜饭。', '除夕夜全家人一起包饺子、吃年夜饭。', 'Chúxī yè quán jiārén yìqǐ bāo jiǎozi, chī niányèfàn.', NULL, 'Đêm Giao thừa cả gia đình cùng nhau gói sủi cảo và ăn cơm tất niên.', NULL, '["Đêm","Giao","thừa"]'::jsonb, 'Pinyin: Chúxī yè quán jiārén yìqǐ bāo jiǎozi, chī niányèfàn.', '除夕夜全家人一起包饺子、吃年夜饭。 (Chúxī yè quán jiārén yìqǐ bāo jiǎozi, chī niányèfàn.) nghĩa là: Đêm Giao thừa cả gia đình cùng nhau gói sủi cảo và ăn cơm tất niên.', 16) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
