INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr17_zh_exp_7', 'lesson-17', 'zh_to_vi', '是的，除夕晚上全家一起吃年夜饭、放鞭炮，还会包饺子。', '是的，除夕晚上全家一起吃年夜饭、放鞭炮，还会包饺子。', 'Shì de, chúxī wǎnshang quán jiā yīqǐ chī niányèfàn, fàng biānpào, hái huì bāo jiǎozi.', NULL, 'Đúng rồi, tối Giao thừa cả nhà cùng ăn cơm tất niên, đốt pháo và còn gói sủi cảo nữa.', NULL, '["đúng","rồi","tối","giao","thừa","cả","nhà","cùng","ăn","cơm","tất","niên","đốt","pháo","và","còn","gói","sủi","cảo","nữa"]'::jsonb, 'Pinyin: Shì de, chúxī wǎnshang quán jiā yīqǐ chī niányèfàn, fàng biānpào, hái huì bāo jiǎozi.', '是的，除夕晚上全家一起吃年夜饭、放鞭炮，还会包饺子。 (Shì de, chúxī wǎnshang quán jiā yīqǐ chī niányèfàn, fàng biānpào, hái huì bāo jiǎozi.) nghĩa là: Đúng rồi, tối Giao thừa cả nhà cùng ăn cơm tất niên, đốt pháo và còn gói sủi cảo nữa.', 25) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr17_zh_exp_8', 'lesson-17', 'zh_to_vi', '谢谢！中国春节和越南春节都要大扫除、贴春联吧？', '谢谢！中国春节和越南春节都要大扫除、贴春联吧？', 'Xièxie! Zhōngguó Chūnjié hé Yuènán Chūnjié dōu yào dàsǎochú, tiē chūnlián ba?', NULL, 'Cảm ơn cậu! Tết Trung Quốc và Tết Việt Nam đều dọn dẹp nhà cửa và dán câu đối đúng không?', NULL, '["cảm","ơn","cậu","tết","trung","quốc","và","tết","việt","nam","đều","dọn","dẹp","nhà","cửa","và","dán","câu","đối","đúng","không"]'::jsonb, 'Pinyin: Xièxie! Zhōngguó Chūnjié hé Yuènán Chūnjié dōu yào dàsǎochú, tiē chūnlián ba?', '谢谢！中国春节和越南春节都要大扫除、贴春联吧？ (Xièxie! Zhōngguó Chūnjié hé Yuènán Chūnjié dōu yào dàsǎochú, tiē chūnlián ba?) nghĩa là: Cảm ơn cậu! Tết Trung Quốc và Tết Việt Nam đều dọn dẹp nhà cửa và dán câu đối đúng không?', 26) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
