INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq17_8', 'lesson-17', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, 'Phiên âm Pinyin chính xác của “先...... 然后......” là gì?', '["xiān... ránhòu...","xīnnián","jiérì","niányèfàn"]'::jsonb, 0, '“先...... 然后......” đọc là: xiān... ránhòu... (đầu tiên... sau đó...).', 8) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq17_9', 'lesson-17', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, 'Phiên âm Pinyin chính xác của “在一块儿” là gì?', '["qìngzhù","Chūnjié","xiān... ránhòu...","zài yíkuàir"]'::jsonb, 3, '“在一块儿” đọc là: zài yíkuàir (ở bên nhau).', 9) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq17_10', 'lesson-17', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, 'Phiên âm Pinyin chính xác của “好好儿” là gì?', '["chúxī","hǎohāor","zòngzi","xīnnián kuàilè"]'::jsonb, 1, '“好好儿” đọc là: hǎohāor (chăm chỉ, cố gắng, thỏa sức...).', 10) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq17_11', 'lesson-17', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, 'Phiên âm Pinyin chính xác của “新年快乐” là gì?', '["biānpào","xīnnián kuàilè","chúxī","bàinián"]'::jsonb, 1, '“新年快乐” đọc là: xīnnián kuàilè (chúc mừng năm mới).', 11) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq17_12', 'lesson-17', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, 'Phiên âm Pinyin chính xác của “有意思” là gì?', '["niányèfàn","cháshi","qìngzhù","yǒuyìsi"]'::jsonb, 3, '“有意思” đọc là: yǒuyìsi (thú vị, có ý nghĩa).', 12) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq17_13', 'lesson-17', NULL, 'expanded_quiz', 'radical', NULL, NULL, 'Chữ Hán “新年” chứa bộ thủ nào sau đây?', '["田 (Điền) (Ruộng đất, khu vực, mặt)","斤 (Cân) (Cái rìu, đơn vị cân nặng)","豆 (Đậu) (Hạt đậu, chén cổ)","齐 (Tề) (Đều đặn, ngay ngắn)"]'::jsonb, 1, 'Chữ “新年” có bộ chính 斤 (Cân) (Cái rìu, đơn vị cân nặng). Chiết tự: 新: 立 + 木 (Tân) + 斤 (Cân: rìu chặt gỗ mới) • 年: 𠂉 + 干/土 (mùa màng thu hoạch một năm)', 13) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq17_14', 'lesson-17', NULL, 'expanded_quiz', 'radical', NULL, NULL, 'Chữ Hán “春节” chứa bộ thủ nào sau đây?', '["士 (Sĩ) (Người học thức, kẻ sĩ)","月 (Nguyệt/Nhục) (Mặt trăng hoặc các bộ phận thân thể người)","日 (Nhật) (Mặt trời, ban ngày, thời gian, ánh sáng)","竹/⺮ (Trúc) (Tre trúc, đồ đan, sách vở)"]'::jsonb, 2, 'Chữ “春节” có bộ chính 日 (Nhật) (Mặt trời, ban ngày, thời gian, ánh sáng). Chiết tự: 春: 𡗗 (cây cỏ đâm chồi) + 日 (Nhật: nắng ấm mùa xuân) • 节: 艹 (Thảo: đốt trúc/cỏ cây) + 卩 (Tiết)', 14) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq17_15', 'lesson-17', NULL, 'expanded_quiz', 'radical', NULL, NULL, 'Chữ Hán “节日” chứa bộ thủ nào sau đây?', '["艹 (Thảo) (Cỏ cây, hoa lá, thảo mộc)","疒 (Nạch) (Bệnh tật, đau ốm, sức khỏe)","走 (Tẩu) (Chạy, đi lại, rời đi)","丶 (Chủ) (Điểm chấm, khởi đầu)"]'::jsonb, 0, 'Chữ “节日” có bộ chính 艹 (Thảo) (Cỏ cây, hoa lá, thảo mộc). Chiết tự: 节: 艹 (Thảo: đốt trúc/cỏ cây) + 卩 (Tiết) • 日: Bộ 日 (Nhật - mặt trời, chữ độc thể)', 15) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq17_16', 'lesson-17', NULL, 'expanded_quiz', 'radical', NULL, NULL, 'Chữ Hán “除夕” chứa bộ thủ nào sau đây?', '["手/扌 (Thủ) (Bàn tay, động tác, thao tác)","皮 (Bì) (Da dẻ, vỏ ngoài)","阝 (Phụ/Ấp) (Gò đất hoặc vùng đất, thành ấp)","足/⻊ (Túc) (Bàn chân, bước chân, đá bóng, chạy)"]'::jsonb, 2, 'Chữ “除夕” có bộ chính 阝 (Phụ/Ấp) (Gò đất hoặc vùng đất, thành ấp). Chiết tự: 除: 阝 (Phụ: bậc thềm) + 余 (Dư: quét dọn loại trừ) • 夕: Bộ 夕 (Tịch - vầng trăng khuyết buổi chiều tối)', 16) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq17_17', 'lesson-17', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, '[Ôn tập Bài 7] Từ đã học “好看” (hǎokàn) có nghĩa là gì?', '["à, ư, hả... (đặt ở cuối câu nghi vấn)","đẹp, dễ nhìn, hay, thú vị","màu xanh lá","pháo"]'::jsonb, 1, 'Ôn tập Bài 7: “好看” (hǎokàn) nghĩa là: đẹp, dễ nhìn, hay, thú vị.', 17) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq17_18', 'lesson-17', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, '[Ôn tập Bài 4] Từ đã học “右边” (yòubian) có nghĩa là gì?', '["bên phải","dùng cuối câu, biểu thị ngữ khí cảm thán.","thịt bò","Sao thế, như thế nào"]'::jsonb, 0, 'Ôn tập Bài 4: “右边” (yòubian) nghĩa là: bên phải.', 18) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq17_19', 'lesson-17', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, '[Ôn tập Bài 11] Từ đã học “矮” (ǎi) có nghĩa là gì?', '["nếu, nếu như","thấp","bố","chân dung"]'::jsonb, 1, 'Ôn tập Bài 11: “矮” (ǎi) nghĩa là: thấp.', 19) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq17_20', 'lesson-17', NULL, 'expanded_quiz', 'reading', NULL, NULL, '[Mở rộng] Câu “越南人过年的时候常包粽子和买花。” có nghĩa tiếng Việt là gì?', '["Bố mẹ tôi đã kết hôn được 25 năm rồi!","Bạn ơi, bạn có thể giúp tôi một chút không?","Người Việt Nam dịp Tết thường gói bánh chưng và mua hoa.","Cậu đừng khóc nữa!"]'::jsonb, 2, '越南人过年的时候常包粽子和买花。 (Yuènán rén guònián de shíhou cháng bāo zòngzi hé mǎi huā.) → Người Việt Nam dịp Tết thường gói bánh chưng và mua hoa.', 20) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq17_21', 'lesson-17', NULL, 'expanded_quiz', 'reading', NULL, NULL, '[Đọc hiểu mở rộng] Đọc đoạn hội thoại:
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq17_22', 'lesson-17', NULL, 'expanded_quiz', 'reading', NULL, NULL, 'Câu “你去吃饭吧！” có nghĩa tiếng Việt là gì?', '["Tôi muốn mời anh ấy đi du lịch cùng tôi.","Cậu đi ăn cơm đi!","Tìm hiểu một chút","Kỳ học này tôi kiểm tra một lần rồi."]'::jsonb, 1, '你去吃饭吧！ (Nǐ qù chīfàn ba!) → Cậu đi ăn cơm đi!', 22) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct17_1', 'lesson-17', NULL, 'comprehensive_test', 'listening', '春节期间我去看望了很多亲戚', NULL, 'Nghe đoạn ghi âm và chọn nghĩa tiếng Việt đúng:', '["Trong dịp Tết tôi đã đi thăm hỏi rất nhiều họ hàng.","Táo ngọt lắm, một cân 2 tệ. Cháu muốn mua mấy cân?","Em ấy thích nhất vẽ tranh, còn tớ mới là tín đồ bóng đá của cả nhà.","Nhật Minh, sở thích của mọi người trong nhà cậu có giống nhau không?"]'::jsonb, 0, 'Nội dung nghe được: “春节期间我去看望了很多亲戚” (Chūnjié qījiān wǒ qù kànwàng le hěnduō qīnqi.) → Trong dịp Tết tôi đã đi thăm hỏi rất nhiều họ hàng.', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct17_2', 'lesson-17', NULL, 'comprehensive_test', 'listening', '好！玉兰我们一起去吧！你才过越南春节，还没有过中国春节，对吗？', NULL, 'Nghe đoạn ghi âm và chọn câu tiếng Trung khớp với nội dung vừa nghe:', '["爷爷的爱好是早上看报纸喝茶","这个会议，你去还是小明去？","老师您好！","好！玉兰我们一起去吧！你才过越南春节，还没有过中国春节，对吗？"]'::jsonb, 3, 'Câu vừa đọc: “好！玉兰我们一起去吧！你才过越南春节，还没有过中国春节，对吗？” (Hǎo! Yùlán wǒmen yīqǐ qù ba! Nǐ cái guò Yuènán Chūnjié, hái méiyǒu guò Zhōngguó Chūnjié, duì ma?) → Được! Ngọc Lan chúng ta cùng đi nhé! Cậu mới đón Tết Việt Nam thôi, chưa từng đón Tết Trung Quốc đúng không?', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct17_3', 'lesson-17', NULL, 'comprehensive_test', 'listening', '越南人过年的时候常包粽子和买花。', NULL, 'Nghe đoạn ghi âm và chọn nghĩa tiếng Việt đúng:', '["Người Việt Nam dịp Tết thường gói bánh chưng và mua hoa.","Thứ Bảy tuần sau là sinh nhật em gái tôi.","Tớ thấy không đắt đâu, rất rẻ!","Tôi có một anh trai và một em gái."]'::jsonb, 0, 'Nội dung nghe được: “越南人过年的时候常包粽子和买花。” → Người Việt Nam dịp Tết thường gói bánh chưng và mua hoa.', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct17_4', 'lesson-17', NULL, 'comprehensive_test', 'listening', '找找 = 找一找', NULL, 'Nghe đoạn ghi âm và chọn câu tiếng Trung khớp với nội dung vừa nghe:', '["如果你好好学习，就能考上大学.","三点一刻。你什么时候去？","北京的春天怎么样？","找找 = 找一找"]'::jsonb, 3, 'Câu vừa đọc: “找找 = 找一找” (zhǎozhao = zhǎo yi zhǎo) → Tìm một chút, tìm qua.', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct17_5', 'lesson-17', NULL, 'comprehensive_test', 'listening', '你们怎么准备过年？', NULL, 'Nghe đoạn ghi âm và chọn nghĩa tiếng Việt đúng:', '["Cậu mua đi!","Bắc Kinh có bốn mùa: xuân, hạ, thu và đông.","Bức tranh này có lịch sử mấy nghìn năm rồi?","Các bạn chuẩn bị đón Tết thế nào?"]'::jsonb, 3, 'Nội dung nghe được: “你们怎么准备过年？” (Nǐmen zěnme zhǔnbèi guònián?) → Các bạn chuẩn bị đón Tết thế nào?', 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct17_6', 'lesson-17', NULL, 'comprehensive_test', 'listening', '下午好！', NULL, 'Nghe đoạn ghi âm và chọn câu tiếng Trung khớp với nội dung vừa nghe:', '["下午好！","范玉兰是留学生吗","周末你有什么打算？去逛街看电影吗？","你很乖啊！如果没有什么做我就上网看新闻或者玩游戏。"]'::jsonb, 0, 'Câu vừa đọc: “下午好！” (Xiàwǔ hǎo) → Chào buổi chiều!', 6) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct17_7', 'lesson-17', NULL, 'comprehensive_test', 'listening', '二十五个', NULL, 'Nghe đoạn ghi âm và chọn nghĩa tiếng Việt đúng:', '["Đây là bạn thân của tôi, cậu ấy tên là Mark.","Thầy Lưu là giáo viên của trường.","Cô ấy ngắm qua mái tóc dài của mình.","Hai mươi lăm cái"]'::jsonb, 3, 'Nội dung nghe được: “二十五个” (èrshíwǔ gè) → Hai mươi lăm cái', 7) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct17_8', 'lesson-17', NULL, 'comprehensive_test', 'listening', '谢谢！中国春节和越南春节都要大扫除、贴春联吧？', NULL, 'Nghe đoạn ghi âm và chọn câu tiếng Trung khớp với nội dung vừa nghe:', '["谢谢！中国春节和越南春节都要大扫除、贴春联吧？","这个会议，你去还是小明去？","可以去看电影，吃火锅，逛街，购物或者去健身房健身。","好！玉兰我们一起去吧！你才过越南春节，还没有过中国春节，对吗？"]'::jsonb, 0, 'Câu vừa đọc: “谢谢！中国春节和越南春节都要大扫除、贴春联吧？” (Xièxie! Zhōngguó Chūnjié hé Yuènán Chūnjié dōu yào dàsǎochú, tiē chūnlián ba?) → Cảm ơn cậu! Tết Trung Quốc và Tết Việt Nam đều dọn dẹp nhà cửa và dán câu đối đúng không?', 8) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
