INSERT INTO lessons (id, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id) VALUES ('lesson-18', 'Bài 18: Du lịch - Đơn nguyên 5: Kỳ nghỉ', 'Bài 18', 'Đơn nguyên 5: Kỳ nghỉ', 'Chuẩn bị hành lý, đặt vé máy bay, phòng khách sạn, tham quan danh lam thắng cảnh.', '2026-11-14'::date, 18, TRUE, NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, date_added = EXCLUDED.date_added, sort_order = EXCLUDED.sort_order, is_system = TRUE, updated_at = NOW();
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v18_1', 'lesson-18', '中国', 'Zhōngguó', 'trung quốc', 'Trung Quốc', 'Danh từ', '丨 (Cổn) (Nét sổ thẳng, xuyên suốt)', '中: 口 (Khẩu: khung vuông) + 丨 (Cổn: vạch chính giữa) • 国: 囗 (Vi: biên giới) + 玉 (Ngọc: báu vật quốc gia)', 'Ghép 中 [bộ 丨] + 国 [bộ 囗] để nhớ từ 中国 (Zhōngguó): "Trung Quốc".', '对。万里长城非常雄伟壮丽，是中国人历史和文化的象征。', 'Duì. Wànlǐ Chángchéng fēicháng xióngwěi zhuànglì, shì Zhōngguó rén lìshǐ hé wénhuà de xiàngzhēng.', 'Đúng vậy. Vạn Lý Trường Thành vô cùng hùng vĩ tráng lệ, là biểu tượng lịch sử và văn hóa của người Trung Quốc.', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v18_2', 'lesson-18', '象征', 'xiàngzhēng', 'từ Hán ngữ', 'tượng trưng', 'Danh từ', '豕 (Thỉ) (Con lợn, loài heo)', '象: ⺈ + 口 + 豕 (hình dáng con voi) • 征: 彳 (Xích: bước đi) + 正 (Chính: đi chinh phục)', 'Ghép 象 [bộ 豕] + 征 [bộ 彳] để nhớ từ 象征 (xiàngzhēng): "tượng trưng".', '对。万里长城非常雄伟壮丽，是中国人历史和文化的象征。', 'Duì. Wànlǐ Chángchéng fēicháng xióngwěi zhuànglì, shì Zhōngguó rén lìshǐ hé wénhuà de xiàngzhēng.', 'Đúng vậy. Vạn Lý Trường Thành vô cùng hùng vĩ tráng lệ, là biểu tượng lịch sử và văn hóa của người Trung Quốc.', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v18_3', 'lesson-18', '景点', 'jǐngdiǎn', 'điểm', 'địa điểm, danh lam thắng cảnh', 'Danh từ', '日 (Nhật) (Mặt trời, ban ngày, thời gian, ánh sáng)', '景: 日 (Nhật: mặt trời chiếu) + 京 (Kinh: phong cảnh) • 点: 占 (Chiếm) + 灬 (Hỏa: ngọn lửa chấm sáng)', 'Ghép 景 [bộ 日] + 点 [bộ 灬] để nhớ từ 景点 (jǐngdiǎn): "địa điểm, danh lam thắng cảnh".', '当然了。北京特别美，有很多有名的景点，比如：万里长城、颐和园、故宫和天安门。', 'Dāngrán le. Běijīng tèbié měi, yǒu hěnduō yǒumíng de jǐngdiǎn, bǐrú: Wànlǐ Chángchéng, Yíhéyuán, Gùgōng hé Tiān''ānmén.', 'Tất nhiên rồi. Bắc Kinh vô cùng đẹp, có rất nhiều danh thắng nổi tiếng như: Vạn Lý Trường Thành, Di Hòa Viên, Cố Cung và Thiên An Môn.', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v18_4', 'lesson-18', '颐和园', 'Yíhéyuán', 'từ Hán ngữ', 'Di Hòa Viên', 'Cụm từ / Tên riêng', '页 (Hiệt) (Đầu mặt, trang giấy)', '颐: 𦣞 + 页 (Hiệt: khuôn mặt, dưỡng sinh) • 和: 禾 (Hòa: cây lúa) + 口 (Khẩu: ai cũng có cơm ăn là hòa bình) • 园: 囗 (Vi: tường rào bao quanh) + 元 (Nguyên: khu vườn)', 'Ghép 颐 [bộ 页] + 和 [bộ 口] + 园 [bộ 囗] để nhớ từ 颐和园 (Yíhéyuán): "Di Hòa Viên".', '当然了。北京特别美，有很多有名的景点，比如：万里长城、颐和园、故宫和天安门。', 'Dāngrán le. Běijīng tèbié měi, yǒu hěnduō yǒumíng de jǐngdiǎn, bǐrú: Wànlǐ Chángchéng, Yíhéyuán, Gùgōng hé Tiān''ānmén.', 'Tất nhiên rồi. Bắc Kinh vô cùng đẹp, có rất nhiều danh thắng nổi tiếng như: Vạn Lý Trường Thành, Di Hòa Viên, Cố Cung và Thiên An Môn.', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v18_5', 'lesson-18', '故宫', 'Gùgōng', 'từ Hán ngữ', 'Cố Cung', 'Cụm từ / Tên riêng', '攴/攵 (Phộc) (Đánh khẽ, hành động, dạy dỗ)', '故: 古 (Cổ: chuyện xưa) + 攵 (Phộc) • 宫: 宀 (Miên: mái cung điện) + 吕 (Lữ: hai gian nối nhau)', 'Ghép 故 [bộ 攵] + 宫 [bộ 宀] để nhớ từ 故宫 (Gùgōng): "Cố Cung".', '当然了。北京特别美，有很多有名的景点，比如：万里长城、颐和园、故宫和天安门。', 'Dāngrán le. Běijīng tèbié měi, yǒu hěnduō yǒumíng de jǐngdiǎn, bǐrú: Wànlǐ Chángchéng, Yíhéyuán, Gùgōng hé Tiān''ānmén.', 'Tất nhiên rồi. Bắc Kinh vô cùng đẹp, có rất nhiều danh thắng nổi tiếng như: Vạn Lý Trường Thành, Di Hòa Viên, Cố Cung và Thiên An Môn.', 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v18_6', 'lesson-18', '万里长城', 'Wànlǐ Chángchéng', 'trường', 'Vạn Lý Trường Thành', 'Cụm từ / Tên riêng', '一 (Nhất) (Số một, nền tảng, nét ngang cơ bản)', '万: 一 + 𠃌 + 丿 (con số hàng vạn) • 里: 日 (Nhật) + 土 (Thổ: ruộng đất làng xóm) • 长: Bộ 长 (Trường - mái tóc dài, kéo dài) • 城: 土 (Thổ: tường đất đắp thành) + 成 (Thành)', 'Ghép 万 [bộ 一] + 里 [bộ 里] + 长 [bộ 长] + 城 [bộ 土] để nhớ từ 万里长城 (Wànlǐ Chángchéng): "Vạn Lý Trường Thành".', '当然了。北京特别美，有很多有名的景点，比如：万里长城、颐和园、故宫和天安门。', 'Dāngrán le. Běijīng tèbié měi, yǒu hěnduō yǒumíng de jǐngdiǎn, bǐrú: Wànlǐ Chángchéng, Yíhéyuán, Gùgōng hé Tiān''ānmén.', 'Tất nhiên rồi. Bắc Kinh vô cùng đẹp, có rất nhiều danh thắng nổi tiếng như: Vạn Lý Trường Thành, Di Hòa Viên, Cố Cung và Thiên An Môn.', 6) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v18_7', 'lesson-18', '天安门', 'Tiān''ānmén', 'thiên An môn', 'Thiên An Môn', 'Cụm từ / Tên riêng', '大 (Đại) (To lớn, vĩ đại)', '天: 一 (Nhất: bầu trời cao) + 大 (Đại: con người dang tay) • 安: 宀 (Miên: mái nhà) + 女 (Nữ: người phụ nữ bình yên trong nhà) • 门: Bộ 门 (Môn - hình hai cánh cửa)', 'Ghép 天 [bộ 大] + 安 [bộ 宀] + 门 [bộ 门] để nhớ từ 天安门 (Tiān''ānmén): "Thiên An Môn".', '当然了。北京特别美，有很多有名的景点，比如：万里长城、颐和园、故宫和天安门。', 'Dāngrán le. Běijīng tèbié měi, yǒu hěnduō yǒumíng de jǐngdiǎn, bǐrú: Wànlǐ Chángchéng, Yíhéyuán, Gùgōng hé Tiān''ānmén.', 'Tất nhiên rồi. Bắc Kinh vô cùng đẹp, có rất nhiều danh thắng nổi tiếng như: Vạn Lý Trường Thành, Di Hòa Viên, Cố Cung và Thiên An Môn.', 7) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v18_8', 'lesson-18', '菜', 'cài', 'từ Hán ngữ', 'món ăn, đồ ăn, rau', 'Danh từ', '艹 (Thảo) (Cỏ cây, hoa lá, thảo mộc)', '菜 = 艹 (Thảo: rau cỏ) + 采 (Thái: hái rau).', 'Chữ 菜 (cài) mang nghĩa "món ăn, đồ ăn, rau", bộ chính 艹 (Thảo); cấu tạo: 艹 (Thảo: rau cỏ) + 采 (Thái: hái rau).', '我还去爬山、拍照、购物和尝尝北京的菜。', 'Wǒ hái qù páshān, pāizhào, gòuwù hé chángchang Běijīng de cài.', 'Tôi còn đi leo núi, chụp ảnh, mua sắm và thưởng thức các món ăn Bắc Kinh.', 8) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v18_9', 'lesson-18', '烤鸭', 'kǎoyā', 'từ Hán ngữ', 'vịt quay', 'Danh từ', '火/灬 (Hỏa) (Lửa, nhiệt độ, nấu nướng, nóng bức)', '烤: 火 (Hỏa: lửa nướng) + 考 (Khảo) • 鸭: 甲 (Giáp) + 鸟 (Điểu: loài chim vịt)', 'Ghép 烤 [bộ 火] + 鸭 [bộ 鸟] để nhớ từ 烤鸭 (kǎoyā): "vịt quay".', '不但很好吃而且也比较便宜，特别是北京烤鸭。', 'Búdàn hěn hǎo chī érqiě yě bǐjiào piányi, tèbié shì Běijīng kǎoyā.', 'Không những rất ngon mà giá cũng khá rẻ, đặc biệt là món vịt quay Bắc Kinh.', 9) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v18_10', 'lesson-18', '历史', 'lìshǐ', 'từ Hán ngữ', 'lịch sử', 'Danh từ', '厂 (Hán) (Vách đá, mái che, công xưởng)', '历: 厂 (Hán) + 力 (Lực: trải qua lịch sử) • 史: 口 + 又 biến thể (bàn tay cầm bút chép sử)', 'Ghép 历 [bộ 厂] + 史 [bộ 口] để nhớ từ 历史 (lìshǐ): "lịch sử".', '对。万里长城非常雄伟壮丽，是中国人历史和文化的象征。', 'Duì. Wànlǐ Chángchéng fēicháng xióngwěi zhuànglì, shì Zhōngguó rén lìshǐ hé wénhuà de xiàngzhēng.', 'Đúng vậy. Vạn Lý Trường Thành vô cùng hùng vĩ tráng lệ, là biểu tượng lịch sử và văn hóa của người Trung Quốc.', 10) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v18_11', 'lesson-18', '文化', 'wénhuà', 'từ Hán ngữ', 'văn hóa', 'Danh từ', '文 (Văn) (Văn chương, chữ viết, hoa văn)', '文: Bộ 文 (Văn - nét giao chéo tạo chữ nghĩa) • 化: 亻 (Nhân đứng) + 匕 (Chủy: người thay đổi biến hóa)', 'Ghép 文 [bộ 文] + 化 [bộ 匕] để nhớ từ 文化 (wénhuà): "văn hóa".', '对。万里长城非常雄伟壮丽，是中国人历史和文化的象征。', 'Duì. Wànlǐ Chángchéng fēicháng xióngwěi zhuànglì, shì Zhōngguó rén lìshǐ hé wénhuà de xiàngzhēng.', 'Đúng vậy. Vạn Lý Trường Thành vô cùng hùng vĩ tráng lệ, là biểu tượng lịch sử và văn hóa của người Trung Quốc.', 11) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v18_12', 'lesson-18', '明年', 'míngnián', 'minh niên', 'năm sau', 'Danh từ', '日 (Nhật) (Mặt trời, ban ngày, thời gian, ánh sáng)', '明: 日 (Nhật: mặt trời) + 月 (Nguyệt: mặt trăng) • 年: 𠂉 + 干/土 (mùa màng thu hoạch một năm)', 'Ghép 明 [bộ 日] + 年 [bộ 干] để nhớ từ 明年 (míngnián): "năm sau".', '我决定了，今年去中国，明年去日本！', 'Wǒ juédìng le, jīnnián qù Zhōngguó, míngnián qù Rìběn!', 'Tôi quyết định rồi, năm nay đi Trung Quốc, năm sau đi Nhật Bản!', 12) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v18_13', 'lesson-18', '暑假', 'shǔjià', 'giả', 'kỳ nghỉ hè', 'Danh từ', '日 (Nhật) (Mặt trời, ban ngày, thời gian, ánh sáng)', '暑: 日 (Nhật: nắng nóng) + 者 (Giả: mùa hè oi bức) • 假: 亻 (Nhân đứng) + 叚 (Giả)', 'Ghép 暑 [bộ 日] + 假 [bộ 亻] để nhớ từ 暑假 (shǔjià): "kỳ nghỉ hè".', '马克，去年暑假你去哪儿旅行？', 'Mǎkè, qùnián shǔjià nǐ qù nǎr lǚxíng?', 'Mark, kỳ nghỉ hè năm ngoái bạn đi du lịch ở đâu?', 13) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v18_14', 'lesson-18', '旅行', 'lǚxíng', 'lữ hành', 'du lịch', 'Động từ', '方 (Phương) (Vuông vức, phương hướng)', '旅: 方 (Phương: lá cờ) + 从 (lữ đoàn đi xa) • 行: Bộ 行 (Hành - ngã tư đường đi lại)', 'Ghép 旅 [bộ 方] + 行 [bộ 行] để nhớ từ 旅行 (lǚxíng): "du lịch".', '马克，去年暑假你去哪儿旅行？', 'Mǎkè, qùnián shǔjià nǐ qù nǎr lǚxíng?', 'Mark, kỳ nghỉ hè năm ngoái bạn đi du lịch ở đâu?', 14) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v18_15', 'lesson-18', '旅游', 'lǚyóu', 'lữ du', 'du ngoạn; du lịch', 'Động từ', '方 (Phương) (Vuông vức, phương hướng)', '旅: 方 (Phương: lá cờ) + 从 (lữ đoàn đi xa) • 游: 氵 (Thủy: bơi lội trong nước) + 斿', 'Ghép 旅 [bộ 方] + 游 [bộ 氵] để nhớ từ 旅游 (lǚyóu): "du ngoạn; du lịch".', '这是关于“旅游”的常用句子。', 'Zhè shì guānyú ''lǚyóu'' de chángyòng jùzi.', 'Đây là câu ví dụ sử dụng từ ''旅游'' (du ngoạn; du lịch).', 15) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v18_16', 'lesson-18', '爬山', 'páshān', 'từ Hán ngữ', 'leo núi', 'Động từ', '爪/爫 (Trảo) (Móng vuốt, bàn tay chụp lấy)', '爬: 爪 (Trảo: tay chân bám víu) + 巴 (Ba: trèo leo) • 山: Bộ 山 (Sơn - ba ngọn núi nhấp nhô)', 'Ghép 爬 [bộ 爪] + 山 [bộ 山] để nhớ từ 爬山 (páshān): "leo núi".', '明天我们会去爬山。', 'Míngtiān wǒmen huì qù páshān.', 'Ngày mai chúng tôi sẽ đi leo núi.', 16) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v18_17', 'lesson-18', '拍照', 'pāizhào', 'từ Hán ngữ', 'chụp ảnh', 'Động từ', '手/扌 (Thủ) (Bàn tay, động tác, thao tác)', '拍: 扌 (Thủ: tay) + 白 (Bạch: vỗ, chụp ảnh) • 照: 昭 (Chiêu: ánh sáng) + 灬 (Hỏa: ngọn lửa soi chiếu)', 'Ghép 拍 [bộ 扌] + 照 [bộ 灬] để nhớ từ 拍照 (pāizhào): "chụp ảnh".', '我还去爬山、拍照、购物和尝尝北京的菜。', 'Wǒ hái qù páshān, pāizhào, gòuwù hé chángchang Běijīng de cài.', 'Tôi còn đi leo núi, chụp ảnh, mua sắm và thưởng thức các món ăn Bắc Kinh.', 17) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v18_18', 'lesson-18', '会', 'huì', 'từ Hán ngữ', 'Phó,đtnn biết, sẽ', 'Động từ', '人/亻 (Nhân) (Con người, nhân loại, hành động)', '会 = 人 (Nhân: mái tụ họp) + 云 (Vân).', 'Chữ 会 (huì) mang nghĩa "Phó,đtnn biết, sẽ", bộ chính 人/亻 (Nhân); cấu tạo: 人 (Nhân: mái tụ họp) + 云 (Vân).', '明天我们会去爬山。', 'Míngtiān wǒmen huì qù páshān.', 'Ngày mai chúng tôi sẽ đi leo núi.', 18) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v18_19', 'lesson-18', '羡慕', 'xiànmù', 'từ Hán ngữ', 'ngưỡng mộ, hâm mộ', 'Động từ', '羊 (Dương) (Con dê, cừu, tốt đẹp)', '羡: 羊 (Dương) + 次 (Thứ: thèm muốn ngưỡng mộ) • 慕: 艹 + 日 + 大 + 㣺 (Tâm nhỏ: tấm lòng ngưỡng mộ)', 'Ghép 羡 [bộ 羊] + 慕 [bộ 心] để nhớ từ 羡慕 (xiànmù): "ngưỡng mộ, hâm mộ".', '好羡慕你啊！今年暑假我也会去北京旅行。', 'Hǎo xiànmù nǐ a! Jīnnián shǔjià wǒ yě huì qù Běijīng lǚxíng.', 'Ghen tị với bạn quá đi! Kỳ nghỉ hè năm nay tôi cũng sẽ đi du lịch Bắc Kinh.', 19) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v18_20', 'lesson-18', '美', 'měi', 'Mỹ', 'đẹp', 'Tính từ', '羊 (Dương) (Con dê, cừu, tốt đẹp)', '美 = 羊 (Dương: cừu béo) + 大 (Đại: to lớn là đẹp).', 'Chữ 美 (měi) mang nghĩa "đẹp", bộ chính 羊 (Dương); cấu tạo: 羊 (Dương: cừu béo) + 大 (Đại: to lớn là đẹp).', '北京美吗？', 'Běijīng měi ma?', 'Bắc Kinh có đẹp không?', 20) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v18_21', 'lesson-18', '有名', 'yǒumíng', 'hữu danh', 'nổi tiếng', 'Tính từ', '月 (Nguyệt/Nhục) (Mặt trăng hoặc các bộ phận thân thể người)', '有: 𠂇 (bàn tay) + 月 (Nguyệt/Nhục: cầm miếng thịt là có) • 名: 夕 (Tịch: chiều tối) + 口 (Khẩu: gọi tên trong đêm)', 'Ghép 有 [bộ 月] + 名 [bộ 口] để nhớ từ 有名 (yǒumíng): "nổi tiếng".', '当然了。北京特别美，有很多有名的景点，比如：万里长城、颐和园、故宫和天安门。', 'Dāngrán le. Běijīng tèbié měi, yǒu hěnduō yǒumíng de jǐngdiǎn, bǐrú: Wànlǐ Chángchéng, Yíhéyuán, Gùgōng hé Tiān''ānmén.', 'Tất nhiên rồi. Bắc Kinh vô cùng đẹp, có rất nhiều danh thắng nổi tiếng như: Vạn Lý Trường Thành, Di Hòa Viên, Cố Cung và Thiên An Môn.', 21) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v18_22', 'lesson-18', '雄伟', 'xióngwěi', 'từ Hán ngữ', 'hùng vĩ, to lớn', 'Tính từ', '隹 (Chuy) (Chim đuôi ngắn)', '雄: 厷 (Quăng) + 隹 (Chuy: chim trống mạnh mẽ) • 伟: 亻 (Nhân đứng: người) + 韦 (Vi: vĩ đại)', 'Ghép 雄 [bộ 隹] + 伟 [bộ 亻] để nhớ từ 雄伟 (xióngwěi): "hùng vĩ, to lớn".', '哇，我挺喜欢万里长城。它很雄伟，对吗？', 'Wa, wǒ tǐng xǐhuan Wànlǐ Chángchéng. Tā hěn xióngwěi duì ma?', 'Chà, tôi rất thích Vạn Lý Trường Thành. Nó rất hùng vĩ đúng không?', 22) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v18_23', 'lesson-18', '壮丽', 'zhuànglì', 'từ Hán ngữ', 'tráng lệ', 'Tính từ', '士 (Sĩ) (Người học thức, kẻ sĩ)', '壮: 丬 + 士 (Sĩ: tráng sĩ cường tráng) • 丽: 一 + nét song song cân đối (đẹp đẽ, tráng lệ)', 'Ghép 壮 [bộ 士] + 丽 [bộ 一] để nhớ từ 壮丽 (zhuànglì): "tráng lệ".', '对。万里长城非常雄伟壮丽，是中国人历史和文化的象征。', 'Duì. Wànlǐ Chángchéng fēicháng xióngwěi zhuànglì, shì Zhōngguó rén lìshǐ hé wénhuà de xiàngzhēng.', 'Đúng vậy. Vạn Lý Trường Thành vô cùng hùng vĩ tráng lệ, là biểu tượng lịch sử và văn hóa của người Trung Quốc.', 23) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v18_24', 'lesson-18', '好客', 'hàokè', 'hảo khách', 'hiếu khách', 'Tính từ', '女 (Nữ) (Phụ nữ, gia đình, tình cảm)', '好: 女 (Nữ: người mẹ) + 子 (Tử: đứa con) • 客: 宀 (Miên: mái nhà) + 各 (Các: người tới nhà)', 'Ghép 好 [bộ 女] + 客 [bộ 宀] để nhớ từ 好客 (hàokè): "hiếu khách".', '很热情和好客，我还认识了一个很好的朋友。', 'Hěn rèqíng hé hàokè, wǒ hái rènshi le yí gè hěn hǎo de péngyou.', 'Rất nhiệt tình và hiếu khách, tôi còn kết quen được một người bạn rất tốt.', 24) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v18_25', 'lesson-18', '不但……而且……', 'búdàn... érqiě...', 'từ Hán ngữ', 'không những... mà còn...', 'Cụm từ / Tên riêng', '一 (Nhất) (Số một, nền tảng, nét ngang cơ bản)', '不: 一 (Nhất) + 丿 + 丨 + 丶 (chữ độc thể phủ định) • 但: 亻 (Nhân đứng) + 旦 (Đán) • 而: Bộ 而 (Nhi - chòm râu, liên từ nối ý) • 且: Khung chồng tầng (vả lại, hơn nữa)', 'Ghép 不 [bộ 一] + 但 [bộ 亻] + 而 [bộ 而] + 且 [bộ 一] để nhớ từ 不但……而且…… (búdàn... érqiě...): "không những... mà còn...".', '这是关于“不但……而且……”的常用句子。', 'Zhè shì guānyú ''búdàn... érqiě...'' de chángyòng jùzi.', 'Đây là câu ví dụ sử dụng từ ''不但……而且……'' (không những... mà còn...).', 25) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order) VALUES ('g18_1', 'lesson-18', '1.会', 'Cấu trúc câu ngữ pháp trọng tâm', ' 会 vừa là phó từ, vừa là động từ. Trường hợp 1: 会 vừa là phó từ đứng trước động từ mang nghĩa “sẽ”, biểu thị sự việc xảy ra trong tương lai hoặc biểu thị lời hứa sẽ thực hiện. 明天我们会去爬山。 Míngtiān wǒmen huì qù páshān. Ngày mai chúng tôi sẽ đi leo núi. ', NULL, '[{"hanzi":"明天我们会去爬山。","pinyin":"Míngtiān wǒmen huì qù páshān.","meaning":"Ngày mai chúng tôi sẽ đi leo núi."},{"hanzi":"你帮我，然后我会帮你，好吗？","pinyin":"Nǐ bāng wǒ, ránhòu wǒ huì bāng nǐ, hǎo ma?","meaning":"Cậu giúp tới rồi tớ sẽ giúp cậu, có được không?"}]'::jsonb, 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order) VALUES ('g18_2', 'lesson-18', '2. 反问句 – Câu phản vấn', '●       V + 什么？', ' a) Khái niệm Câu phản vấn là câu nhấn mạnh hoặc phủ định một chuyện nào đó bằng hình thức câu hỏi. ●       不是...... 吗？ 不是我们昨天已经见面了吗？ Búshì wǒmen zuótiān yǐjīng jiànmiàn le ma? Không phải hôm qua chúng ta đã gặp nhau rồi sao? (Khẳng định hôm qua chún', NULL, '[{"hanzi":"我会踢足球。","pinyin":"Wǒ huì tī zúqiú.","meaning":"Tôi biết đá bóng."},{"hanzi":"她会说汉语。","pinyin":"Tā huì shuō Hànyǔ.","meaning":"Cô ấy biết nói tiếng Trung."}]'::jsonb, 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order) VALUES ('g18_3', 'lesson-18', '1.药 yào  dt. thuốc', 'Cấu trúc câu ngữ pháp trọng tâm', 'Quy tắc ngữ pháp quan trọng trong Du lịch.', NULL, '[{"hanzi":"他会开车。","pinyin":"Tā huì kāichē","meaning":"Anh ấy biết lái xe."},{"hanzi":"你知道他在哪儿吗？","pinyin":"Nǐ zhīdào tā zài nǎr ma?","meaning":"Bạn biết anh ấy ở đâu không?"}]'::jsonb, 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order;
INSERT INTO texts (id, lesson_id, title, description, sort_order) VALUES ('txt_18_1', 'lesson-18', 'Bài khoá #1: Hội thoại giáo trình — Du lịch', 'Hội thoại chuẩn giáo trình Bài 18. Từ vựng chưa học được chú thích phiên âm & nghĩa trong ngoặc.', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_18_1_1', 'txt_18_1', '安妮', '马克，去年暑假你去哪儿旅行？', '马克，去年暑假你去哪儿旅行？', 'Mǎkè, qùnián shǔjià nǐ qù nǎr lǚxíng?', 'Mark, kỳ nghỉ hè năm ngoái bạn đi du lịch ở đâu?', 1) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_18_1_2', 'txt_18_1', '马克', '我去北京旅行。', '我去北京旅行。', 'Wǒ qù Běijīng lǚxíng.', 'Tôi đi du lịch Bắc Kinh.', 2) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_18_1_3', 'txt_18_1', '安妮', '北京美吗？', '北京美吗？', 'Běijīng měi ma?', 'Bắc Kinh có đẹp không?', 3) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_18_1_4', 'txt_18_1', '马克', '当然了。北京特别美，有很多有名的景点，比如：万里长城、颐和园、故宫和天安门。', '当然了。北京特别美，有很多有名的景点，比如：万里长城、颐和园、故宫和天安门。', 'Dāngrán le. Běijīng tèbié měi, yǒu hěnduō yǒumíng de jǐngdiǎn, bǐrú: Wànlǐ Chángchéng, Yíhéyuán, Gùgōng hé Tiān''ānmén.', 'Tất nhiên rồi. Bắc Kinh vô cùng đẹp, có rất nhiều danh thắng nổi tiếng như: Vạn Lý Trường Thành, Di Hòa Viên, Cố Cung và Thiên An Môn.', 4) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_18_1_5', 'txt_18_1', '安妮', '哇，我挺喜欢万里长城。它很雄伟，对吗？', '哇 (wa: oa, chà (cảm thán))，我挺喜欢万里长城。它很雄伟，对吗？', 'Wa, wǒ tǐng xǐhuan Wànlǐ Chángchéng. Tā hěn xióngwěi duì ma?', 'Chà, tôi rất thích Vạn Lý Trường Thành. Nó rất hùng vĩ đúng không?', 5) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_18_1_6', 'txt_18_1', '马克', '对。万里长城非常雄伟壮丽，是中国人历史和文化的象征。', '对。万里长城非常雄伟壮丽，是中国人历史和文化的象征。', 'Duì. Wànlǐ Chángchéng fēicháng xióngwěi zhuànglì, shì Zhōngguó rén lìshǐ hé wénhuà de xiàngzhēng.', 'Đúng vậy. Vạn Lý Trường Thành vô cùng hùng vĩ tráng lệ, là biểu tượng lịch sử và văn hóa của người Trung Quốc.', 6) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_18_1_7', 'txt_18_1', '安妮', '你还去哪儿玩儿？', '你还去哪儿玩儿？', 'Nǐ hái qù nǎr wánr?', 'Bạn còn đi đâu chơi nữa không?', 7) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_18_1_8', 'txt_18_1', '马克', '我还去爬山、拍照、购物和尝尝北京的菜。', '我还去爬山、拍照、购物和尝尝 (chángchang: nếm thử)北京的菜。', 'Wǒ hái qù páshān, pāizhào, gòuwù hé chángchang Běijīng de cài.', 'Tôi còn đi leo núi, chụp ảnh, mua sắm và thưởng thức các món ăn Bắc Kinh.', 8) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_18_1_9', 'txt_18_1', '安妮', '北京的菜怎么样？', '北京的菜怎么样？', 'Běijīng de cài zěnmeyàng?', 'Món ăn Bắc Kinh thế nào?', 9) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_18_1_10', 'txt_18_1', '马克', '不但很好吃而且也比较便宜，特别是北京烤鸭。', '不但很好吃而且也比较便宜，特别是北京烤鸭。', 'Búdàn hěn hǎo chī érqiě yě bǐjiào piányi, tèbié shì Běijīng kǎoyā.', 'Không những rất ngon mà giá cũng khá rẻ, đặc biệt là món vịt quay Bắc Kinh.', 10) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_18_1_11', 'txt_18_1', '安妮', '北京人呢？', '北京人呢？', 'Běijīng rén ne?', 'Người Bắc Kinh thì sao?', 11) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_18_1_12', 'txt_18_1', '马克', '很热情和好客，我还认识了一个很好的朋友。', '很热情和好客，我还认识了一个很好的朋友。', 'Hěn rèqíng hé hàokè, wǒ hái rènshi le yí gè hěn hǎo de péngyou.', 'Rất nhiệt tình và hiếu khách, tôi còn kết quen được một người bạn rất tốt.', 12) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_18_1_13', 'txt_18_1', '安妮', '好羡慕你啊！今年暑假我也会去北京旅行。', '好羡慕你啊！今 (jīn: hôm nay, nay)年暑假我也会去北京旅行。', 'Hǎo xiànmù nǐ a! Jīnnián shǔjià wǒ yě huì qù Běijīng lǚxíng.', 'Ghen tị với bạn quá đi! Kỳ nghỉ hè năm nay tôi cũng sẽ đi du lịch Bắc Kinh.', 13) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_18_1_14', 'txt_18_1', '马克', '你不是说今年要去日本旅行吗？', '你不是说今 (jīn: hôm nay, nay)年要去日 (rì: ngày)本旅行吗？', 'Nǐ búshì shuō jīnnián yào qù Rìběn lǚxíng ma?', 'Không phải bạn nói năm nay sẽ đi du lịch Nhật Bản sao?', 14) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_18_1_15', 'txt_18_1', '安妮', '我决定了，今年去中国，明年去日本！', '我决定了，今 (jīn: hôm nay, nay)年去中国，明年去日 (rì: ngày)本！', 'Wǒ juédìng le, jīnnián qù Zhōngguó, míngnián qù Rìběn!', 'Tôi quyết định rồi, năm nay đi Trung Quốc, năm sau đi Nhật Bản!', 15) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_18_1_1', 'lesson-18', 'txt_18_1', 'listening', 'listening', '马克，去年暑假你去哪儿旅行？', NULL, 'Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Mark, kỳ nghỉ hè năm ngoái bạn đi du lịch ở đâu?","sách của tôi","thành tích kiểm tra","Rất nhiệt tình và hiếu khách, tôi còn kết quen được một người bạn rất tốt."]'::jsonb, 0, 'Nội dung nghe được: 马克，去年暑假你去哪儿旅行？ (Mǎkè, qùnián shǔjià nǐ qù nǎr lǚxíng?) → Mark, kỳ nghỉ hè năm ngoái bạn đi du lịch ở đâu?', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_18_1_2', 'lesson-18', 'txt_18_1', 'listening', 'listening', '我去北京旅行。', NULL, 'Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["你知道他在哪儿吗？","她会说汉语。","我去北京旅行。","对。万里长城非常雄伟壮丽，是中国人历史和文化的象征。"]'::jsonb, 2, 'Câu vừa đọc: 我去北京旅行。 (Wǒ qù Běijīng lǚxíng.) → Tôi đi du lịch Bắc Kinh.', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_18_1_3', 'lesson-18', 'txt_18_1', 'listening', 'listening', '北京美吗？', NULL, 'Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Một con bò","mẹ của tôi","Cậu mua đi!","Bắc Kinh có đẹp không?"]'::jsonb, 3, 'Nội dung nghe được: 北京美吗？ (Běijīng měi ma?) → Bắc Kinh có đẹp không?', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_18_1_4', 'lesson-18', 'txt_18_1', 'listening', 'listening', '当然了。北京特别美，有很多有名的景点，比如：万里长城、颐和园、故宫和天安门。', NULL, 'Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["当然了。北京特别美，有很多有名的景点，比如：万里长城、颐和园、故宫和天安门。","不是我们昨天已经 (yǐjīng: đã)见面 (miàn: mặt, phía)了吗？","你知道他在哪儿吗？","马克，去年暑假你去哪儿旅行？"]'::jsonb, 0, 'Câu vừa đọc: 当然了。北京特别美，有很多有名的景点，比如：万里长城、颐和园、故宫和天安门。 (Dāngrán le. Běijīng tèbié měi, yǒu hěnduō yǒumíng de jǐngdiǎn, bǐrú: Wànlǐ Chángchéng, Yíhéyuán, Gùgōng hé Tiān''ānmén.) → Tất nhiên rồi. Bắc Kinh vô cùng đẹp, có rất nhiều danh thắng nổi tiếng như: Vạn Lý Trường Thành, Di Hòa Viên, Cố Cung và Thiên An Môn.', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO texts (id, lesson_id, title, description, sort_order) VALUES ('txt_18_2', 'lesson-18', 'Bài nghe tổng hợp: Ôn tập lũy tiến (Bài 1 – Bài 18)', 'Kết hợp từ vựng & mẫu câu đã học từ Bài 1 đến Bài 17 cùng trọng tâm Bài 18 để củng cố phản xạ nghe.', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_18_2_1', 'txt_18_2', 'Ôn Bài 17', '你再好好儿想一想。', '你再好好儿想一想。', 'Nǐ zài hǎohāor xiǎng yī xiǎng.', 'Cậu hãy cố gắng nghĩ nữa đi.', 1) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_18_2_2', 'txt_18_2', 'Bài 18', '明天我们会去爬山。', '明天我们会去爬山。', 'Míngtiān wǒmen huì qù páshān.', 'Ngày mai chúng tôi sẽ đi leo núi.', 2) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_18_2_3', 'txt_18_2', 'Ôn Bài 9', '我们下午去吧！', '我们下午去吧！', 'Wǒmen xiàwǔ qù ba!', 'Buổi chiều chúng ta đi nhé!', 3) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_18_2_4', 'txt_18_2', 'Bài 18', '我会踢足球。', '我会踢足球。', 'Wǒ huì tī zúqiú.', 'Tôi biết đá bóng.', 4) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_18_2_5', 'txt_18_2', 'Ôn Bài 1', '老师您好！', '老师您好！', 'Lǎoshī nín hǎo', 'Em chào thầy/cô ạ', 5) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_18_2_6', 'txt_18_2', 'Bài 18', '她会说汉语。', '她会说汉语。', 'Tā huì shuō Hànyǔ.', 'Cô ấy biết nói tiếng Trung.', 6) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_18_2_7', 'txt_18_2', 'Ôn Bài 11', '他正在听音乐呢。', '他正在听音乐呢。', 'Tā zhèngzài tīng yīnyuè ne.', 'Anh ấy đang nghe nhạc.', 7) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_18_2_8', 'txt_18_2', 'Bài 18', '你知道他在哪儿吗？', '你知道他在哪儿吗？', 'Nǐ zhīdào tā zài nǎr ma?', 'Bạn biết anh ấy ở đâu không?', 8) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_18_2_1', 'lesson-18', 'txt_18_2', 'listening', 'listening', '你再好好儿想一想。', NULL, '[Ôn tập Bài 17] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Cậu hãy cố gắng nghĩ nữa đi.","Cô bé, năm nay cháu mấy tuổi rồi?","Tôi đứng xem ti vi.","Một đôi tình nhân"]'::jsonb, 0, 'Nội dung nghe được: 你再好好儿想一想。 (Nǐ zài hǎohāor xiǎng yī xiǎng.) → Cậu hãy cố gắng nghĩ nữa đi.', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_18_2_2', 'lesson-18', 'txt_18_2', 'listening', 'listening', '明天我们会去爬山。', NULL, '[Bài 18] Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["我去北京旅行。","不是我们昨天已经 (yǐjīng: đã)见面 (miàn: mặt, phía)了吗？","明天我们会去爬山。","你不告诉我，我怎么知道呢？"]'::jsonb, 2, 'Câu vừa đọc: 明天我们会去爬山。 (Míngtiān wǒmen huì qù páshān.) → Ngày mai chúng tôi sẽ đi leo núi.', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_18_2_3', 'lesson-18', 'txt_18_2', 'listening', 'listening', '我们下午去吧！', NULL, '[Ôn tập Bài 9] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Tớ biết bơi, còn biết trượt băng.","Buổi chiều chúng ta đi nhé!","Điện thoại vừa nãy còn tốt lắm mà, sao đã hỏng rồi.","Mẹ bảo tôi ăn cơm xong thì giúp mẹ quét dọn nhà cửa."]'::jsonb, 1, 'Nội dung nghe được: 我们下午去吧！ (Wǒmen xiàwǔ qù ba!) → Buổi chiều chúng ta đi nhé!', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_18_2_4', 'lesson-18', 'txt_18_2', 'listening', 'listening', '我会踢足球。', NULL, '[Bài 18] Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["你知道他在哪儿吗？","我什么时候说我不是河内 (Hénèi: Hà Nội)人？","我会踢足球。","不是我们昨天已经 (yǐjīng: đã)见面 (miàn: mặt, phía)了吗？"]'::jsonb, 2, 'Câu vừa đọc: 我会踢足球。 (Wǒ huì tī zúqiú.) → Tôi biết đá bóng.', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_18_2_5', 'lesson-18', 'txt_18_2', 'listening', 'listening', '老师您好！', NULL, '[Ôn tập Bài 1] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Em chào thầy/cô ạ","Mỗi ngày anh ấy đều đến thư viện mượn sách.","Cậu ấy là người Nhật Bản.","Annie không đang ôn bài."]'::jsonb, 0, 'Nội dung nghe được: 老师您好！ (Lǎoshī nín hǎo) → Em chào thầy/cô ạ', 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO texts (id, lesson_id, title, description, sort_order) VALUES ('txt_18_3', 'lesson-18', 'Bài khoá mở rộng: Chuyến du lịch Bắc Kinh đáng nhớ (Mở rộng)', 'Hội thoại tình huống mới xây dựng dựa trên từ vựng và ngữ pháp Bài 18 (không trùng lặp nguyên văn giáo trình).', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_18_3_1', 'txt_18_3', 'Lan', '马克，去年暑假你去北京旅游去了哪些景点？', '马克，去年暑假你去北京旅游去了哪些 (xiē: vài, một ít)景点？', 'Mǎkè, qùnián shǔjià nǐ qù Běijīng lǚyóu qù le nǎxiē jǐngdiǎn?', 'Mark, kỳ nghỉ hè năm ngoái đi du lịch Bắc Kinh bạn đã tới những thắng cảnh nào?', 1) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_18_3_2', 'txt_18_3', 'Mark', '我去了故宫、颐和园和万里长城，了解了好多中国历史文化。', '我去了故宫、颐和园和万里长城，了解 (liǎojiě: hiểu rõ, biết rõ)了好多中国历史文化。', 'Wǒ qù le Gùgōng, Yíhéyuán hé Wànlǐ Chángchéng, liǎojiě le hǎoduō Zhōngguó lìshǐ wénhuà.', 'Tôi đã đi Cố Cung, Di Hòa Viên và Vạn Lý Trường Thành, hiểu thêm rất nhiều về lịch sử văn hóa Trung Quốc.', 2) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_18_3_3', 'txt_18_3', 'Lan', '北京的菜好吃吗？', '北京的菜好吃吗？', 'Běijīng de cài hǎochī ma?', 'Món ăn ở Bắc Kinh có ngon không?', 3) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_18_3_4', 'txt_18_3', 'Mark', '特别好吃！北京烤鸭真香，明年我还要再去一次。', '特别好吃！北京烤鸭真香 (xiāng: thơm)，明年我还要再去一次 (cì: lần)。', 'Tèbié hǎochī! Běijīng kǎoyā zhēn xiāng, míngnián wǒ hái yào zài qù yí cì.', 'Đặc biệt ngon! Vịt quay Bắc Kinh thơm lắm, năm sau tôi muốn đi lại lần nữa.', 4) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_18_3_1', 'lesson-18', 'txt_18_3', 'listening', 'listening', '马克，去年暑假你去北京旅游去了哪些景点？ 我去了故宫、颐和园和万里长城，了解了好多中国历史文化。 北京的菜好吃吗？ 特别好吃！北京烤鸭真香，明年我还要再去一次。', NULL, '[Nghe hiểu tình huống mới] Món ăn nào ở Bắc Kinh khiến Mark ấn tượng nhất và muốn quay lại?', '["Bánh chưng","Cháo thịt","Đậu phụ thối","Vịt quay Bắc Kinh (北京烤鸭)"]'::jsonb, 3, 'Mark khen ngợi: ''北京烤鸭真香，明年我还要再去一次''.', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_18_3_2', 'lesson-18', 'txt_18_3', 'listening', 'listening', '马克，去年暑假你去北京旅游去了哪些景点？', NULL, '[Mở rộng] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Anh ấy hát rất hay.","Tôi không biết người này là nam hay là nữ nữa.","Cậu nói gì vậy?","Mark, kỳ nghỉ hè năm ngoái đi du lịch Bắc Kinh bạn đã tới những thắng cảnh nào?"]'::jsonb, 3, 'Nội dung nghe được: 马克，去年暑假你去北京旅游去了哪些景点？ (Mǎkè, qùnián shǔjià nǐ qù Běijīng lǚyóu qù le nǎxiē jǐngdiǎn?) → Mark, kỳ nghỉ hè năm ngoái đi du lịch Bắc Kinh bạn đã tới những thắng cảnh nào?', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_18_3_3', 'lesson-18', 'txt_18_3', 'listening', 'listening', '我去了故宫、颐和园和万里长城，了解了好多中国历史文化。', NULL, '[Mở rộng] Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["北京美吗？","去颐和园旅行的时候我们拍 (pāi: chụp, vỗ)了很多照片。","我什么时候说我不是河内 (Hénèi: Hà Nội)人？","我去了故宫、颐和园和万里长城，了解 (liǎojiě: hiểu rõ, biết rõ)了好多中国历史文化。"]'::jsonb, 3, 'Câu vừa đọc: 我去了故宫、颐和园和万里长城，了解了好多中国历史文化。 (Wǒ qù le Gùgōng, Yíhéyuán hé Wànlǐ Chángchéng, liǎojiě le hǎoduō Zhōngguó lìshǐ wénhuà.) → Tôi đã đi Cố Cung, Di Hòa Viên và Vạn Lý Trường Thành, hiểu thêm rất nhiều về lịch sử văn hóa Trung Quốc.', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_18_3_4', 'lesson-18', 'txt_18_3', 'listening', 'listening', '北京的菜好吃吗？', NULL, '[Mở rộng] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["hai cô gái kia","Bệnh viện ở bên phải trường học của chúng ta.","Kỳ học này tôi kiểm tra một lần rồi.","Món ăn ở Bắc Kinh có ngon không?"]'::jsonb, 3, 'Nội dung nghe được: 北京的菜好吃吗？ (Běijīng de cài hǎochī ma?) → Món ăn ở Bắc Kinh có ngon không?', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss18_1', 'lesson-18', '我很喜欢了解中国的历史和文化', '[Mở rộng] Tôi rất thích tìm hiểu lịch sử và văn hóa Trung Quốc.', 'Wǒ hěn xǐhuan liǎojiě Zhōngguó de lìshǐ hé wénhuà.', '["我很","喜欢","了解","中国的","历史和","文化"]'::jsonb, 'Từ chưa học: 了解 (liǎojiě: hiểu rõ, biết rõ)', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss18_2', 'lesson-18', '故宫是中国古代文化的重要象征', '[Mở rộng] Cố Cung là biểu tượng quan trọng của văn hóa cổ đại Trung Quốc.', 'Gùgōng shì Zhōngguó gǔdài wénhuà de zhòngyào xiàngzhēng.', '["故宫是","中国","古代","文化的","重要","象征"]'::jsonb, NULL, 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss18_3', 'lesson-18', '明天我们会去爬山', 'Ngày mai chúng tôi sẽ đi leo núi.', 'Míngtiān wǒmen huì qù páshān.', '["明天","我们","会","去","爬山"]'::jsonb, NULL, 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss18_4', 'lesson-18', '我会踢足球', 'Tôi biết đá bóng.', 'Wǒ huì tī zúqiú.', '["我","会","踢足球"]'::jsonb, NULL, 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss18_5', 'lesson-18', '你认识阮日明吗', '[Ôn tập Bài 3] Bạn có quen biết Nguyễn Nhật Minh không?', 'Nǐ rènshi Ruǎn Rìmíng ma?', '["你","认识","阮日明","吗"]'::jsonb, NULL, 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss18_6', 'lesson-18', '电影院在美术馆的东边', '[Ôn tập Bài 6] Rạp chiếu phim nằm ở phía đông bảo tàng mỹ thuật.', 'Diànyǐngyuàn zài měishùguǎn de dōngbian.', '["电影院","在","美术馆","的","东边"]'::jsonb, NULL, 6) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss18_exp_1', 'lesson-18', '马克去年暑假你去哪儿旅行', 'Mark, kỳ nghỉ hè năm ngoái bạn đi du lịch ở đâu?', 'Mǎkè, qùnián shǔjià nǐ qù nǎr lǚxíng?', '["马克","去","年","暑假","你","去","哪儿","旅行"]'::jsonb, NULL, 7) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss18_exp_2', 'lesson-18', '我去北京旅行', 'Tôi đi du lịch Bắc Kinh.', 'Wǒ qù Běijīng lǚxíng.', '["我","去","北京","旅行"]'::jsonb, NULL, 8) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss18_exp_3', 'lesson-18', '北京美吗', 'Bắc Kinh có đẹp không?', 'Běijīng měi ma?', '["北京","美","吗"]'::jsonb, NULL, 9) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss18_exp_4', 'lesson-18', '当然了北京特别美有很多有名的景点比如万里长城颐和园故宫和天安门', 'Tất nhiên rồi. Bắc Kinh vô cùng đẹp, có rất nhiều danh thắng nổi tiếng như: Vạn Lý Trường Thành, Di Hòa Viên, Cố Cung và Thiên An Môn.', 'Dāngrán le. Běijīng tèbié měi, yǒu hěnduō yǒumíng de jǐngdiǎn, bǐrú: Wànlǐ Chángchéng, Yíhéyuán, Gùgōng hé Tiān''ānmén.', '["当然","了","北京","特别","美","有","很","多","有名","的","景点","比如","万里长城","颐和园","故宫","和","天安门"]'::jsonb, NULL, 10) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss18_exp_5', 'lesson-18', '哇我挺喜欢万里长城它很雄伟对吗', 'Chà, tôi rất thích Vạn Lý Trường Thành. Nó rất hùng vĩ đúng không?', 'Wa, wǒ tǐng xǐhuan Wànlǐ Chángchéng. Tā hěn xióngwěi duì ma?', '["哇","我","挺","喜欢","万里长城","它","很","雄伟","对","吗"]'::jsonb, NULL, 11) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss18_exp_6', 'lesson-18', '对万里长城非常雄伟壮丽是中国人历史和文化的象征', 'Đúng vậy. Vạn Lý Trường Thành vô cùng hùng vĩ tráng lệ, là biểu tượng lịch sử và văn hóa của người Trung Quốc.', 'Duì. Wànlǐ Chángchéng fēicháng xióngwěi zhuànglì, shì Zhōngguó rén lìshǐ hé wénhuà de xiàngzhēng.', '["对","万里长城","非常","雄伟","壮丽","是","中国","人","历史","和","文化","的","象征"]'::jsonb, NULL, 12) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss18_exp_7', 'lesson-18', '你还去哪儿玩儿', 'Bạn còn đi đâu chơi nữa không?', 'Nǐ hái qù nǎr wánr?', '["你","还","去","哪儿","玩儿"]'::jsonb, NULL, 13) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss18_exp_8', 'lesson-18', '我还去爬山拍照购物和尝尝北京的菜', 'Tôi còn đi leo núi, chụp ảnh, mua sắm và thưởng thức các món ăn Bắc Kinh.', 'Wǒ hái qù páshān, pāizhào, gòuwù hé chángchang Běijīng de cài.', '["我","还","去","爬山","拍照","购物","和","尝","尝","北京","的","菜"]'::jsonb, NULL, 14) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss18_exp_9', 'lesson-18', '北京的菜怎么样', 'Món ăn Bắc Kinh thế nào?', 'Běijīng de cài zěnmeyàng?', '["北京","的","菜","怎么样"]'::jsonb, NULL, 15) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss18_exp_10', 'lesson-18', '不但很好吃而且也比较便宜特别是北京烤鸭', 'Không những rất ngon mà giá cũng khá rẻ, đặc biệt là món vịt quay Bắc Kinh.', 'Búdàn hěn hǎo chī érqiě yě bǐjiào piányi, tèbié shì Běijīng kǎoyā.', '["不","但","很","好吃","而","且","也","比较","便宜","特别","是","北京","烤鸭"]'::jsonb, NULL, 16) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss18_exp_11', 'lesson-18', '北京人呢', 'Người Bắc Kinh thì sao?', 'Běijīng rén ne?', '["北京","人","呢"]'::jsonb, NULL, 17) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss18_exp_12', 'lesson-18', '很热情和好客我还认识了一个很好的朋友', 'Rất nhiệt tình và hiếu khách, tôi còn kết quen được một người bạn rất tốt.', 'Hěn rèqíng hé hàokè, wǒ hái rènshi le yí gè hěn hǎo de péngyou.', '["很","热情","和","好客","我","还","认识","了","一","个","很","好","的","朋友"]'::jsonb, NULL, 18) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss18_exp_13', 'lesson-18', '好羡慕你啊今年暑假我也会去北京旅行', 'Ghen tị với bạn quá đi! Kỳ nghỉ hè năm nay tôi cũng sẽ đi du lịch Bắc Kinh.', 'Hǎo xiànmù nǐ a! Jīnnián shǔjià wǒ yě huì qù Běijīng lǚxíng.', '["好","羡慕","你","啊","今","年","暑假","我","也","会","去","北京","旅行"]'::jsonb, NULL, 19) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss18_exp_14', 'lesson-18', '你不是说今年要去日本旅行吗', 'Không phải bạn nói năm nay sẽ đi du lịch Nhật Bản sao?', 'Nǐ búshì shuō jīnnián yào qù Rìběn lǚxíng ma?', '["你","不是","说","今","年","要","去","日","本","旅行","吗"]'::jsonb, NULL, 20) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr18_vi_1', 'lesson-18', 'vi_to_zh', '[Mở rộng] Kỳ nghỉ hè năm sau tôi dự định đi du lịch Trung Quốc một tháng.', NULL, NULL, '明年暑假我打算去中国旅游一个月。', NULL, 'míngnián shǔjià wǒ dǎsuan qù zhōngguó lǚyóu yígè yuè', '[]'::jsonb, 'Gợi ý Pinyin: Míngnián shǔjià wǒ dǎsuan qù Zhōngguó lǚyóu yígè yuè.', 'Kỳ nghỉ hè năm sau tôi dự định đi du lịch Trung Quốc một tháng. → 明年暑假我打算去中国旅游一个月。 (Míngnián shǔjià wǒ dǎsuan qù Zhōngguó lǚyóu yígè yuè.)', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
