INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr18_vi_3', 'lesson-18', 'vi_to_zh', 'Ngày mai chúng tôi sẽ đi leo núi.', NULL, NULL, '明天我们会去爬山。', NULL, 'míngtiān wǒmen huì qù páshān', '[]'::jsonb, 'Gợi ý Pinyin: Míngtiān wǒmen huì qù páshān.', 'Ngày mai chúng tôi sẽ đi leo núi. → 明天我们会去爬山。 (Míngtiān wǒmen huì qù páshān.)', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
