INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr18_vi_exp_1', 'lesson-18', 'vi_to_zh', 'Mark, kỳ nghỉ hè năm ngoái bạn đi du lịch ở đâu?', NULL, NULL, '马克，去年暑假你去哪儿旅行？', NULL, 'mǎkè qùnián shǔjià nǐ qù nǎr lǚxíng', '[]'::jsonb, 'Gợi ý Pinyin: Mǎkè, qùnián shǔjià nǐ qù nǎr lǚxíng?', 'Mark, kỳ nghỉ hè năm ngoái bạn đi du lịch ở đâu? → 马克，去年暑假你去哪儿旅行？ (Mǎkè, qùnián shǔjià nǐ qù nǎr lǚxíng?)', 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr18_vi_exp_2', 'lesson-18', 'vi_to_zh', 'Tôi đi du lịch Bắc Kinh.', NULL, NULL, '我去北京旅行。', NULL, 'wǒ qù běijīng lǚxíng', '[]'::jsonb, 'Gợi ý Pinyin: Wǒ qù Běijīng lǚxíng.', 'Tôi đi du lịch Bắc Kinh. → 我去北京旅行。 (Wǒ qù Běijīng lǚxíng.)', 6) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr18_vi_exp_3', 'lesson-18', 'vi_to_zh', 'Bắc Kinh có đẹp không?', NULL, NULL, '北京美吗？', NULL, 'běijīng měi ma', '[]'::jsonb, 'Gợi ý Pinyin: Běijīng měi ma?', 'Bắc Kinh có đẹp không? → 北京美吗？ (Běijīng měi ma?)', 7) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr18_vi_exp_4', 'lesson-18', 'vi_to_zh', 'Tất nhiên rồi. Bắc Kinh vô cùng đẹp, có rất nhiều danh thắng nổi tiếng như: Vạn Lý Trường Thành, Di Hòa Viên, Cố Cung và Thiên An Môn.', NULL, NULL, '当然了。北京特别美，有很多有名的景点，比如：万里长城、颐和园、故宫和天安门。', NULL, 'dāngrán le běijīng tèbié měi yǒu hěnduō yǒumíng de jǐngdiǎn bǐrú wànlǐ chángchéng yíhéyuán gùgōng hé tiān ānmén', '[]'::jsonb, 'Gợi ý Pinyin: Dāngrán le. Běijīng tèbié měi, yǒu hěnduō yǒumíng de jǐngdiǎn, bǐrú: Wànlǐ Chángchéng, Yíhéyuán, Gùgōng hé Tiān''ānmén.', 'Tất nhiên rồi. Bắc Kinh vô cùng đẹp, có rất nhiều danh thắng nổi tiếng như: Vạn Lý Trường Thành, Di Hòa Viên, Cố Cung và Thiên An Môn. → 当然了。北京特别美，有很多有名的景点，比如：万里长城、颐和园、故宫和天安门。 (Dāngrán le. Běijīng tèbié měi, yǒu hěnduō yǒumíng de jǐngdiǎn, bǐrú: Wànlǐ Chángchéng, Yíhéyuán, Gùgōng hé Tiān''ānmén.)', 8) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr18_vi_exp_5', 'lesson-18', 'vi_to_zh', 'Chà, tôi rất thích Vạn Lý Trường Thành. Nó rất hùng vĩ đúng không?', NULL, NULL, '哇，我挺喜欢万里长城。它很雄伟，对吗？', NULL, 'wa wǒ tǐng xǐhuan wànlǐ chángchéng tā hěn xióngwěi duì ma', '[]'::jsonb, 'Gợi ý Pinyin: Wa, wǒ tǐng xǐhuan Wànlǐ Chángchéng. Tā hěn xióngwěi duì ma?', 'Chà, tôi rất thích Vạn Lý Trường Thành. Nó rất hùng vĩ đúng không? → 哇，我挺喜欢万里长城。它很雄伟，对吗？ (Wa, wǒ tǐng xǐhuan Wànlǐ Chángchéng. Tā hěn xióngwěi duì ma?)', 9) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr18_vi_exp_6', 'lesson-18', 'vi_to_zh', 'Đúng vậy. Vạn Lý Trường Thành vô cùng hùng vĩ tráng lệ, là biểu tượng lịch sử và văn hóa của người Trung Quốc.', NULL, NULL, '对。万里长城非常雄伟壮丽，是中国人历史和文化的象征。', NULL, 'duì wànlǐ chángchéng fēicháng xióngwěi zhuànglì shì zhōngguó rén lìshǐ hé wénhuà de xiàngzhēng', '[]'::jsonb, 'Gợi ý Pinyin: Duì. Wànlǐ Chángchéng fēicháng xióngwěi zhuànglì, shì Zhōngguó rén lìshǐ hé wénhuà de xiàngzhēng.', 'Đúng vậy. Vạn Lý Trường Thành vô cùng hùng vĩ tráng lệ, là biểu tượng lịch sử và văn hóa của người Trung Quốc. → 对。万里长城非常雄伟壮丽，是中国人历史和文化的象征。 (Duì. Wànlǐ Chángchéng fēicháng xióngwěi zhuànglì, shì Zhōngguó rén lìshǐ hé wénhuà de xiàngzhēng.)', 10) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr18_vi_exp_7', 'lesson-18', 'vi_to_zh', 'Bạn còn đi đâu chơi nữa không?', NULL, NULL, '你还去哪儿玩儿？', NULL, 'nǐ hái qù nǎr wánr', '[]'::jsonb, 'Gợi ý Pinyin: Nǐ hái qù nǎr wánr?', 'Bạn còn đi đâu chơi nữa không? → 你还去哪儿玩儿？ (Nǐ hái qù nǎr wánr?)', 11) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr18_vi_exp_8', 'lesson-18', 'vi_to_zh', 'Tôi còn đi leo núi, chụp ảnh, mua sắm và thưởng thức các món ăn Bắc Kinh.', NULL, NULL, '我还去爬山、拍照、购物和尝尝北京的菜。', NULL, 'wǒ hái qù páshān pāizhào gòuwù hé chángchang běijīng de cài', '[]'::jsonb, 'Gợi ý Pinyin: Wǒ hái qù páshān, pāizhào, gòuwù hé chángchang Běijīng de cài.', 'Tôi còn đi leo núi, chụp ảnh, mua sắm và thưởng thức các món ăn Bắc Kinh. → 我还去爬山、拍照、购物和尝尝北京的菜。 (Wǒ hái qù páshān, pāizhào, gòuwù hé chángchang Běijīng de cài.)', 12) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
