INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr18_zh_exp_3', 'lesson-18', 'zh_to_vi', '特别好吃！北京烤鸭真香，明年我还要再去一次。', '特别好吃！北京烤鸭真香，明年我还要再去一次。', 'Tèbié hǎochī! Běijīng kǎoyā zhēn xiāng, míngnián wǒ hái yào zài qù yí cì.', NULL, 'Đặc biệt ngon! Vịt quay Bắc Kinh thơm lắm, năm sau tôi muốn đi lại lần nữa.', NULL, '["đặc","biệt","ngon","vịt","quay","bắc","kinh","thơm","lắm","năm","sau","tôi","muốn","đi","lại","lần","nữa"]'::jsonb, 'Pinyin: Tèbié hǎochī! Běijīng kǎoyā zhēn xiāng, míngnián wǒ hái yào zài qù yí cì.', '特别好吃！北京烤鸭真香，明年我还要再去一次。 (Tèbié hǎochī! Běijīng kǎoyā zhēn xiāng, míngnián wǒ hái yào zài qù yí cì.) nghĩa là: Đặc biệt ngon! Vịt quay Bắc Kinh thơm lắm, năm sau tôi muốn đi lại lần nữa.', 21) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
