INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr18_zh_exp_5', 'lesson-18', 'zh_to_vi', '我去了故宫、颐和园和万里长城，了解了好多中国历史文化。', '我去了故宫、颐和园和万里长城，了解了好多中国历史文化。', 'Wǒ qù le Gùgōng, Yíhéyuán hé Wànlǐ Chángchéng, liǎojiě le hǎoduō Zhōngguó lìshǐ wénhuà.', NULL, 'Tôi đã đi Cố Cung, Di Hòa Viên và Vạn Lý Trường Thành, hiểu thêm rất nhiều về lịch sử văn hóa Trung Quốc.', NULL, '["tôi","đã","đi","cố","cung","di","hòa","viên","và","vạn","lý","trường","thành","hiểu","thêm","rất","nhiều","về","lịch","sử","văn","hóa","trung","quốc"]'::jsonb, 'Pinyin: Wǒ qù le Gùgōng, Yíhéyuán hé Wànlǐ Chángchéng, liǎojiě le hǎoduō Zhōngguó lìshǐ wénhuà.', '我去了故宫、颐和园和万里长城，了解了好多中国历史文化。 (Wǒ qù le Gùgōng, Yíhéyuán hé Wànlǐ Chángchéng, liǎojiě le hǎoduō Zhōngguó lìshǐ wénhuà.) nghĩa là: Tôi đã đi Cố Cung, Di Hòa Viên và Vạn Lý Trường Thành, hiểu thêm rất nhiều về lịch sử văn hóa Trung Quốc.', 23) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
