INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq18_6', 'lesson-18', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, 'Từ Hán tự “万里长城” có nghĩa tiếng Việt là gì?', '["Vạn Lý Trường Thành","Di Hòa Viên","lịch sử","địa điểm, danh lam thắng cảnh"]'::jsonb, 0, '“万里长城” (Wànlǐ Chángchéng) là Cụm từ / Tên riêng, nghĩa là: Vạn Lý Trường Thành.', 6) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq18_7', 'lesson-18', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, 'Từ Hán tự “天安门” có nghĩa tiếng Việt là gì?', '["du ngoạn; du lịch","nổi tiếng","Trung Quốc","Thiên An Môn"]'::jsonb, 3, '“天安门” (Tiān''ānmén) là Cụm từ / Tên riêng, nghĩa là: Thiên An Môn.', 7) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq18_8', 'lesson-18', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, 'Phiên âm Pinyin chính xác của “不但……而且……” là gì?', '["búdàn... érqiě...","wénhuà","míngnián","Gùgōng"]'::jsonb, 0, '“不但……而且……” đọc là: búdàn... érqiě... (không những... mà còn...).', 8) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq18_9', 'lesson-18', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, 'Phiên âm Pinyin chính xác của “好客” là gì?', '["lìshǐ","Wànlǐ Chángchéng","míngnián","hàokè"]'::jsonb, 3, '“好客” đọc là: hàokè (hiếu khách).', 9) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq18_10', 'lesson-18', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, 'Phiên âm Pinyin chính xác của “壮丽” là gì?', '["míngnián","zhuànglì","hàokè","měi"]'::jsonb, 1, '“壮丽” đọc là: zhuànglì (tráng lệ).', 10) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq18_11', 'lesson-18', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, 'Phiên âm Pinyin chính xác của “雄伟” là gì?', '["huì","xióngwěi","wénhuà","jǐngdiǎn"]'::jsonb, 1, '“雄伟” đọc là: xióngwěi (hùng vĩ, to lớn).', 11) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq18_12', 'lesson-18', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, 'Phiên âm Pinyin chính xác của “有名” là gì?', '["měi","Tiān''ānmén","hàokè","yǒumíng"]'::jsonb, 3, '“有名” đọc là: yǒumíng (nổi tiếng).', 12) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq18_13', 'lesson-18', NULL, 'expanded_quiz', 'radical', NULL, NULL, 'Chữ Hán “中国” chứa bộ thủ nào sau đây?', '["彳 (Xích) (Bước chân trái, con đường, hành động)","丨 (Cổn) (Nét sổ thẳng, xuyên suốt)","田 (Điền) (Ruộng đất, khu vực, mặt)","豆 (Đậu) (Hạt đậu, chén cổ)"]'::jsonb, 1, 'Chữ “中国” có bộ chính 丨 (Cổn) (Nét sổ thẳng, xuyên suốt). Chiết tự: 中: 口 (Khẩu: khung vuông) + 丨 (Cổn: vạch chính giữa) • 国: 囗 (Vi: biên giới) + 玉 (Ngọc: báu vật quốc gia)', 13) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq18_14', 'lesson-18', NULL, 'expanded_quiz', 'radical', NULL, NULL, 'Chữ Hán “象征” chứa bộ thủ nào sau đây?', '["疋/⺪ (Thất) (Cuộn vải, bàn chân)","贝 (Bối) (Vỏ sò, tiền bạc, giá trị)","丨 (Cổn) (Nét sổ thẳng, xuyên suốt)","豕 (Thỉ) (Con lợn, loài heo)"]'::jsonb, 3, 'Chữ “象征” có bộ chính 豕 (Thỉ) (Con lợn, loài heo). Chiết tự: 象: ⺈ + 口 + 豕 (hình dáng con voi) • 征: 彳 (Xích: bước đi) + 正 (Chính: đi chinh phục)', 14) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq18_15', 'lesson-18', NULL, 'expanded_quiz', 'radical', NULL, NULL, 'Chữ Hán “景点” chứa bộ thủ nào sau đây?', '["犬/犭 (Khuyển) (Con chó, loài thú)","色 (Sắc) (Màu sắc, vẻ mặt)","高 (Cao) (Cao lớn, tầng cao)","日 (Nhật) (Mặt trời, ban ngày, thời gian, ánh sáng)"]'::jsonb, 3, 'Chữ “景点” có bộ chính 日 (Nhật) (Mặt trời, ban ngày, thời gian, ánh sáng). Chiết tự: 景: 日 (Nhật: mặt trời chiếu) + 京 (Kinh: phong cảnh) • 点: 占 (Chiếm) + 灬 (Hỏa: ngọn lửa chấm sáng)', 15) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq18_16', 'lesson-18', NULL, 'expanded_quiz', 'radical', NULL, NULL, 'Chữ Hán “颐和园” chứa bộ thủ nào sau đây?', '["页 (Hiệt) (Đầu mặt, trang giấy)","儿 (Nhi) (Trẻ nhỏ, phần chân nâng đỡ)","幺 (Yêu) (Nhỏ bé, sợi tơ nhỏ)","玉/王 (Ngọc) (Đá quý, châu báu)"]'::jsonb, 0, 'Chữ “颐和园” có bộ chính 页 (Hiệt) (Đầu mặt, trang giấy). Chiết tự: 颐: 𦣞 + 页 (Hiệt: khuôn mặt, dưỡng sinh) • 和: 禾 (Hòa: cây lúa) + 口 (Khẩu: ai cũng có cơm ăn là hòa bình) • 园: 囗 (Vi: tường rào bao quanh) + 元 (Nguyên: khu vườn)', 16) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq18_17', 'lesson-18', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, '[Ôn tập Bài 11] Từ đã học “照片” (zhàopiàn) có nghĩa là gì?', '["cô ấy, bà ấy, chị ấy,... (ngôi thứ ba số ít chỉ nữ)","bánh chưng","Lưu (họ người)","ảnh"]'::jsonb, 3, 'Ôn tập Bài 11: “照片” (zhàopiàn) nghĩa là: ảnh.', 17) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq18_18', 'lesson-18', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, '[Ôn tập Bài 2] Từ đã học “上课” (shàng kè) có nghĩa là gì?', '["thế, nhé, nhỉ, cơ (dùng ở cuối câu trần thuật hoặc nghi vấn)","vào học, lên lớp","quan tâm, chú ý","màu sắc"]'::jsonb, 1, 'Ôn tập Bài 2: “上课” (shàng kè) nghĩa là: vào học, lên lớp.', 18) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq18_19', 'lesson-18', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, '[Ôn tập Bài 6] Từ đã học “米” (mǐ) có nghĩa là gì?', '["mét (m)","ảnh","đẹp, xinh đẹp","cà phê"]'::jsonb, 0, 'Ôn tập Bài 6: “米” (mǐ) nghĩa là: mét (m).', 19) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq18_20', 'lesson-18', NULL, 'expanded_quiz', 'reading', NULL, NULL, '[Mở rộng] Câu “明年暑假我打算去中国旅游一个月。” có nghĩa tiếng Việt là gì?', '["Cậu hãy cố gắng nghĩ nữa đi.","Điện thoại vừa nãy còn tốt lắm mà, sao đã hỏng rồi.","Hôm nay tôi đã tắm qua rồi.","Kỳ nghỉ hè năm sau tôi dự định đi du lịch Trung Quốc một tháng."]'::jsonb, 3, '明年暑假我打算去中国旅游一个月。 (Míngnián shǔjià wǒ dǎsuan qù Zhōngguó lǚyóu yígè yuè.) → Kỳ nghỉ hè năm sau tôi dự định đi du lịch Trung Quốc một tháng.', 20) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq18_21', 'lesson-18', NULL, 'expanded_quiz', 'reading', NULL, NULL, '[Đọc hiểu mở rộng] Đọc đoạn hội thoại:
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq18_22', 'lesson-18', NULL, 'expanded_quiz', 'reading', NULL, NULL, 'Câu “明天我们会去爬山。” có nghĩa tiếng Việt là gì?', '["Anh ta không cho tôi đi.","Ngày mai chúng tôi sẽ đi leo núi.","Ai bảo chúng tôi đã chia tay rồi? (Chúng tôi chưa chia tay)","Anh ta không thích tôi, tôi còn đi làm gì? (Tôi không đi)"]'::jsonb, 1, '明天我们会去爬山。 (Míngtiān wǒmen huì qù páshān.) → Ngày mai chúng tôi sẽ đi leo núi.', 22) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct18_1', 'lesson-18', NULL, 'comprehensive_test', 'listening', '对。万里长城非常雄伟壮丽，是中国人历史和文化的象征。', NULL, 'Nghe đoạn ghi âm và chọn nghĩa tiếng Việt đúng:', '["Tôi biết đá bóng.","Anh ấy đến từ đất nước nào?","Cảm ơn cậu! Tết Trung Quốc và Tết Việt Nam đều dọn dẹp nhà cửa và dán câu đối đúng không?","Đúng vậy. Vạn Lý Trường Thành vô cùng hùng vĩ tráng lệ, là biểu tượng lịch sử và văn hóa của người Trung Quốc."]'::jsonb, 3, 'Nội dung nghe được: “对。万里长城非常雄伟壮丽，是中国人历史和文化的象征。” (Duì. Wànlǐ Chángchéng fēicháng xióngwěi zhuànglì, shì Zhōngguó rén lìshǐ hé wénhuà de xiàngzhēng.) → Đúng vậy. Vạn Lý Trường Thành vô cùng hùng vĩ tráng lệ, là biểu tượng lịch sử và văn hóa của người Trung Quốc.', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct18_2', 'lesson-18', NULL, 'comprehensive_test', 'listening', '我还去爬山、拍照、购物和尝尝北京的菜。', NULL, 'Nghe đoạn ghi âm và chọn câu tiếng Trung khớp với nội dung vừa nghe:', '["我还去爬山、拍照、购物和尝尝北京的菜。","你一直往北走，到十字路口往右拐就到了。","谢谢你们！","客厅里有三个人。"]'::jsonb, 0, 'Câu vừa đọc: “我还去爬山、拍照、购物和尝尝北京的菜。” (Wǒ hái qù páshān, pāizhào, gòuwù hé chángchang Běijīng de cài.) → Tôi còn đi leo núi, chụp ảnh, mua sắm và thưởng thức các món ăn Bắc Kinh.', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct18_3', 'lesson-18', NULL, 'comprehensive_test', 'listening', '马克，去年暑假你去哪儿旅行？', NULL, 'Nghe đoạn ghi âm và chọn nghĩa tiếng Việt đúng:', '["Được chứ.","Mark, kỳ nghỉ hè năm ngoái bạn đi du lịch ở đâu?","Tất nhiên rồi.","Annie là bạn thân của tôi."]'::jsonb, 1, 'Nội dung nghe được: “马克，去年暑假你去哪儿旅行？” (Mǎkè, qùnián shǔjià nǐ qù nǎr lǚxíng?) → Mark, kỳ nghỉ hè năm ngoái bạn đi du lịch ở đâu?', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct18_4', 'lesson-18', NULL, 'comprehensive_test', 'listening', '你知道他在哪儿吗？', NULL, 'Nghe đoạn ghi âm và chọn câu tiếng Trung khớp với nội dung vừa nghe:', '["你知道他在哪儿吗？","北京有春天、夏天、秋天和冬天四个季节。","昨天下午你去图书馆了吗","老师好"]'::jsonb, 0, 'Câu vừa đọc: “你知道他在哪儿吗？” (Nǐ zhīdào tā zài nǎr ma?) → Bạn biết anh ấy ở đâu không?', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct18_5', 'lesson-18', NULL, 'comprehensive_test', 'listening', '万里长城和故宫都是北京很有名的景点。', NULL, 'Nghe đoạn ghi âm và chọn nghĩa tiếng Việt đúng:', '["Hôm nay là thứ mấy thế?","Vạn Lý Trường Thành và Cố Cung đều là những thắng cảnh rất nổi tiếng ở Bắc Kinh.","Cô ấy là học sinh trường nào?","Chào buổi sáng!"]'::jsonb, 1, 'Nội dung nghe được: “万里长城和故宫都是北京很有名的景点。” → Vạn Lý Trường Thành và Cố Cung đều là những thắng cảnh rất nổi tiếng ở Bắc Kinh.', 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct18_6', 'lesson-18', NULL, 'comprehensive_test', 'listening', '你帮我，然后我会帮你，好吗？', NULL, 'Nghe đoạn ghi âm và chọn câu tiếng Trung khớp với nội dung vừa nghe:', '["那今天下午四点我在学校门口等你。我们一起去，好吗？","周末你有什么打算？去逛街看电影吗？","上午要上课，下午不上。","你帮我，然后我会帮你，好吗？"]'::jsonb, 3, 'Câu vừa đọc: “你帮我，然后我会帮你，好吗？” (Nǐ bāng wǒ, ránhòu wǒ huì bāng nǐ, hǎo ma?) → Cậu giúp tới rồi tớ sẽ giúp cậu, có được không?', 6) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct18_7', 'lesson-18', NULL, 'comprehensive_test', 'listening', '我们下午去吧！', NULL, 'Nghe đoạn ghi âm và chọn nghĩa tiếng Việt đúng:', '["Buổi chiều chúng ta đi nhé!","Bắc Kinh có đẹp không?","Nếu chăm chỉ học hành thì bạn sẽ có thể thi đỗ đại học.","Tớ đang chọn quà sinh nhật."]'::jsonb, 0, 'Nội dung nghe được: “我们下午去吧！” (Wǒmen xiàwǔ qù ba!) → Buổi chiều chúng ta đi nhé!', 7) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
