INSERT INTO lessons (id, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id) VALUES ('lesson-19', 'Bài 19: Bị ốm - Đơn nguyên 6: Sức khoẻ', 'Bài 19', 'Đơn nguyên 6: Sức khoẻ', 'Triệu chứng cảm cúm, sốt, đau đầu, uống thuốc, nghỉ ngơi và đi khám bác sĩ.', '2026-11-14'::date, 19, TRUE, NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, date_added = EXCLUDED.date_added, sort_order = EXCLUDED.sort_order, is_system = TRUE, updated_at = NOW();
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v19_1', 'lesson-19', '药', 'yào', 'dược', 'thuốc', 'Danh từ', '艹 (Thảo) (Cỏ cây, hoa lá, thảo mộc)', '药 = 艹 (Thảo: cỏ cây thảo mộc) + 约 (Ước: phần biểu âm).', 'Chữ 药 (yào) mang nghĩa "thuốc", bộ chính 艹 (Thảo); cấu tạo: 艹 (Thảo: cỏ cây thảo mộc) + 约 (Ước: phần biểu âm).', '你还这样说！我现在去药店给你买药。对了， 听说感冒应该吃肉粥，这样很快就恢复了。我顺便给你买一碗粥吧！', 'Nǐ hái zhèyàng shuō! Wǒ xiànzài qù yàodiàn gěi nǐ mǎi yào. Duì le, tīngshuō gǎnmào yīnggāi chī ròu zhōu, zhèyàng hěn kuài jiù huīfù le. Wǒ shùnbiàn gěi nǐ mǎi yī wǎn zhōu ba!', 'Cậu vẫn còn nói thế được à! Giờ tớ ra hiệu thuốc mua thuốc cho cậu. À đúng rồi, nghe nói bị cảm nên ăn cháo thịt để mau hồi phục. Tớ tiện đường mua cho cậu một bát cháo nhé!', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v19_2', 'lesson-19', '肉粥', 'ròuzhōu', 'từ Hán ngữ', 'cháo thịt', 'Danh từ', '肉/月 (Nhục) (Thịt, bộ phận cơ thể)', '肉: Bộ 肉 (Nhục - miếng thịt có thớ) • 粥: 弓 (Cung) + 米 (Mễ: hạt gạo nấu nhừ ở giữa) + 弓 (Cung)', 'Ghép 肉 [bộ 肉] + 粥 [bộ 米] để nhớ từ 肉粥 (ròuzhōu): "cháo thịt".', '你还这样说！我现在去药店给你买药。对了， 听说感冒应该吃肉粥，这样很快就恢复了。我顺便给你买一碗粥吧！', 'Nǐ hái zhèyàng shuō! Wǒ xiànzài qù yàodiàn gěi nǐ mǎi yào. Duì le, tīngshuō gǎnmào yīnggāi chī ròu zhōu, zhèyàng hěn kuài jiù huīfù le. Wǒ shùnbiàn gěi nǐ mǎi yī wǎn zhōu ba!', 'Cậu vẫn còn nói thế được à! Giờ tớ ra hiệu thuốc mua thuốc cho cậu. À đúng rồi, nghe nói bị cảm nên ăn cháo thịt để mau hồi phục. Tớ tiện đường mua cho cậu một bát cháo nhé!', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v19_3', 'lesson-19', '药店', 'yàodiàn', 'dược điếm', 'hiệu thuốc', 'Danh từ', '艹 (Thảo) (Cỏ cây, hoa lá, thảo mộc)', '药: 艹 (Thảo: cỏ cây thảo mộc) + 约 (Ước: phần biểu âm) • 店: 广 (Nghiễm: mái hiên) + 占 (Chiếm: quầy hàng)', 'Ghép 药 [bộ 艹] + 店 [bộ 广] để nhớ từ 药店 (yàodiàn): "hiệu thuốc".', '你还这样说！我现在去药店给你买药。对了， 听说感冒应该吃肉粥，这样很快就恢复了。我顺便给你买一碗粥吧！', 'Nǐ hái zhèyàng shuō! Wǒ xiànzài qù yàodiàn gěi nǐ mǎi yào. Duì le, tīngshuō gǎnmào yīnggāi chī ròu zhōu, zhèyàng hěn kuài jiù huīfù le. Wǒ shùnbiàn gěi nǐ mǎi yī wǎn zhōu ba!', 'Cậu vẫn còn nói thế được à! Giờ tớ ra hiệu thuốc mua thuốc cho cậu. À đúng rồi, nghe nói bị cảm nên ăn cháo thịt để mau hồi phục. Tớ tiện đường mua cho cậu một bát cháo nhé!', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v19_4', 'lesson-19', '脸色', 'liǎnsè', 'sắc', 'sắc mặt', 'Danh từ', '月 (Nguyệt/Nhục) (Mặt trăng hoặc các bộ phận thân thể người)', '脸: 月 (Nhục: cơ thể) + 佥 (Thiêm: khuôn mặt) • 色: Bộ 色 (Sắc - ⺈ + 巴, sắc mặt, màu sắc)', 'Ghép 脸 [bộ 月] + 色 [bộ 色] để nhớ từ 脸色 (liǎnsè): "sắc mặt".', '小兰，你的脸色不太好，是不是生病了？', 'Xiǎo Lán, nǐ de liǎnsè bú tài hǎo, shì bu shì shēngbìng le?', 'Tiểu Lan, sắc mặt cậu không tốt lắm, có phải bị ốm rồi không?', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v19_5', 'lesson-19', '冰水', 'bīngshuǐ', 'thủy', 'nước đá', 'Danh từ', '冫 (Băng) (Nước đá, lạnh giá)', '冰: 冫 (Băng: kết tinh băng giá) + 水 (Thủy: nước) • 水: Bộ 水 (Thủy - dòng nước chảy, chữ độc thể)', 'Ghép 冰 [bộ 冫] + 水 [bộ 水] để nhớ từ 冰水 (bīngshuǐ): "nước đá".', '你是不是又喝冰水了？你的喉咙经常发炎,你还不戒除冰水。', 'Nǐ shì bu shì yòu hē bīngshuǐ le? Nǐ de hóulong jīngcháng fāyán, nǐ hái bù jièchú bīngshuǐ.', 'Có phải cậu lại uống nước đá rồi không? Cổ họng cậu hay bị viêm mà cậu vẫn chưa bỏ uống nước đá.', 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v19_6', 'lesson-19', '生病', 'shēngbìng', 'sinh bệnh', 'bị ốm, bị bệnh, ốm', 'Động từ', '生 (Sinh) (Sinh sôi, sự sống, mới mẻ)', '生: Bộ 生 (Sinh - mầm cây nảy từ đất, chữ độc thể) • 病: 疒 (Nạch: nằm giường bệnh) + 丙 (Bính)', 'Ghép 生 [bộ 生] + 病 [bộ 疒] để nhớ từ 生病 (shēngbìng): "bị ốm, bị bệnh, ốm".', '小兰，你的脸色不太好，是不是生病了？', 'Xiǎo Lán, nǐ de liǎnsè bú tài hǎo, shì bu shì shēngbìng le?', 'Tiểu Lan, sắc mặt cậu không tốt lắm, có phải bị ốm rồi không?', 6) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v19_7', 'lesson-19', '感冒', 'gǎnmào', 'cảm mạo', 'cảm cúm', 'Động từ', '心/忄 (Tâm) (Trái tim, tình cảm, suy nghĩ, tâm lý)', '感: 咸 (Hàm) + 心 (Tâm: rung động trong lòng) • 冒: 曰 (Viết/che) + 目 (Mục)', 'Ghép 感 [bộ 心] + 冒 [bộ 目] để nhớ từ 感冒 (gǎnmào): "cảm cúm".', '我觉得头很疼，上午还发烧和咳嗽， 好像感冒了。', 'Wǒ juéde tóu hěn téng, shàngwǔ hái fāshāo hé késou, hǎoxiàng gǎnmào le.', 'Tớ thấy rất đau đầu, buổi sáng còn bị sốt và ho, hình như cảm lạnh rồi.', 7) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v19_8', 'lesson-19', '头疼', 'tóuténg', 'đông', 'đau đầu', 'Động từ', '疒 (Nạch) (Bệnh tật, đau ốm, sức khỏe)', '头: 丷 + 大 (Đại: phần đầu phía trên) • 疼: 疒 (Nạch: bệnh tật) + 冬 (Đông: đau nhức buốt)', 'Ghép 头 [bộ 大] + 疼 [bộ 疒] để nhớ từ 头疼 (tóuténg): "đau đầu".', '这是关于“头疼”的常用句子。', 'Zhè shì guānyú ''tóuténg'' de chángyòng jùzi.', 'Đây là câu ví dụ sử dụng từ ''头疼'' (đau đầu).', 8) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v19_9', 'lesson-19', '发烧', 'fāshāo', 'phát thiêu', 'sốt', 'Động từ', '又 (Hựu) (Bàn tay phải, lặp lại, lại nữa)', '发: 𠃋 + 又 (Hựu: phóng ra, phát sinh) • 烧: 火 (Hỏa: lửa nóng) + 尧 (Nghiêu: đốt cháy, sốt cao)', 'Ghép 发 [bộ 又] + 烧 [bộ 火] để nhớ từ 发烧 (fāshāo): "sốt".', '孩子发烧了，最好带她去看医生吧。', 'Háizi fāshāo le, zuì hǎo dài tā qù kàn yīshēng ba.', 'Con bị ốm rồi, tốt nhất là đưa con đi khám bác sĩ đi.', 9) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v19_10', 'lesson-19', '咳嗽', 'késou', 'từ Hán ngữ', 'ho', 'Động từ', '口 (Khẩu) (Miệng, ăn uống, lời nói, âm thanh phát ra)', '咳: 口 (Khẩu: miệng ho) + 亥 (Hợi) • 嗽: 口 (Khẩu: miệng) + 束 (Thúc) + 欠 (Khiếm: bật hơi ra)', 'Ghép 咳 [bộ 口] + 嗽 [bộ 口] để nhớ từ 咳嗽 (késou): "ho".', '你咳嗽了，最好别抽烟了。', 'Nǐ késou le, zuì hǎo bié chōuyān le.', 'Anh bị ho rồi, tốt nhất đừng hút thuốc nữa.', 10) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v19_11', 'lesson-19', '喉咙发炎', 'hóulong fāyán', 'phát', 'viêm họng', 'Động từ', '口 (Khẩu) (Miệng, ăn uống, lời nói, âm thanh phát ra)', '喉: 口 (Khẩu: cổ họng) + 侯 (Hầu) • 咙: 口 (Khẩu: cuống họng) + 龙 (Long) • 发: 𠃋 + 又 (Hựu: phóng ra, phát sinh) • 炎: 火 (Hỏa) + 火 (Hỏa: hai ngọn lửa chồng lên gây nóng/viêm)', 'Ghép 喉 [bộ 口] + 咙 [bộ 口] + 发 [bộ 又] + 炎 [bộ 火] để nhớ từ 喉咙发炎 (hóulong fāyán): "viêm họng".', '这是关于“喉咙发炎”的常用句子。', 'Zhè shì guānyú ''hóulong fāyán'' de chángyòng jùzi.', 'Đây là câu ví dụ sử dụng từ ''喉咙发炎'' (viêm họng).', 11) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v19_12', 'lesson-19', '累', 'lèi', 'từ Hán ngữ', 'mệt, mệt mỏi', 'Tính từ', '糸/纟 (Mịch) (Sợi tơ, gắn kết, màu sắc)', '累 = 田 (Điền: ruộng đồng) + 糸 (Mịch: vất vả mệt mỏi).', 'Chữ 累 (lèi) mang nghĩa "mệt, mệt mỏi", bộ chính 糸/纟 (Mịch); cấu tạo: 田 (Điền: ruộng đồng) + 糸 (Mịch: vất vả mệt mỏi).', '这是关于“累”的常用句子。', 'Zhè shì guānyú ''lèi'' de chángyòng jùzi.', 'Đây là câu ví dụ sử dụng từ ''累'' (mệt, mệt mỏi).', 12) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v19_13', 'lesson-19', '戒除', 'jièchú', 'từ Hán ngữ', 'cai, bỏ, chừa', 'Động từ', '戈 (Qua) (Cây giáo, vũ khí, chiến tranh)', '戒: 戈 (Qua: vũ khí) + 廾 (Củng: hai tay giữ gìn, kiêng cữ) • 除: 阝 (Phụ: bậc thềm) + 余 (Dư: quét dọn loại trừ)', 'Ghép 戒 [bộ 戈] + 除 [bộ 阝] để nhớ từ 戒除 (jièchú): "cai, bỏ, chừa".', '你是不是又喝冰水了？你的喉咙经常发炎,你还不戒除冰水。', 'Nǐ shì bu shì yòu hē bīngshuǐ le? Nǐ de hóulong jīngcháng fāyán, nǐ hái bù jièchú bīngshuǐ.', 'Có phải cậu lại uống nước đá rồi không? Cổ họng cậu hay bị viêm mà cậu vẫn chưa bỏ uống nước đá.', 13) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v19_14', 'lesson-19', '得了', 'dé le', 'từ Hán ngữ', 'bị (cảm cúm)', 'Động từ', '彳 (Xích) (Bước chân trái, con đường, hành động)', '得: 彳 (Xích: bước đi) + 旦 (Đán) + 寸 (Thốn: tay nắm được) • 了: Bộ 亅 (Quyết - nét móc kết thúc, chữ độc thể)', 'Ghép 得 [bộ 彳] + 了 [bộ 亅] để nhớ từ 得了 (dé le): "bị (cảm cúm)".', '没事儿， 只得了感冒而已， 不要紧。', 'Méishìr, zhǐ déle gǎnmào éryǐ, bú yàojǐn.', 'Không sao đâu, chỉ bị cảm nhẹ thôi mà, không đáng ngại đâu.', 14) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v19_15', 'lesson-19', '恢复', 'huīfù', 'từ Hán ngữ', 'hồi phục', 'Động từ', '心/忄 (Tâm) (Trái tim, tình cảm, suy nghĩ, tâm lý)', '恢: 忄 (Tâm đứng: tinh thần) + 灰 (Hôi: tàn tro gồm 厂 + 火) • 复: 𠂉 + 日 (Nhật) + 夂 (Trĩ: quay lại làm lần nữa)', 'Ghép 恢 [bộ 忄] + 复 [bộ 夂] để nhớ từ 恢复 (huīfù): "hồi phục".', '你还这样说！我现在去药店给你买药。对了， 听说感冒应该吃肉粥，这样很快就恢复了。我顺便给你买一碗粥吧！', 'Nǐ hái zhèyàng shuō! Wǒ xiànzài qù yàodiàn gěi nǐ mǎi yào. Duì le, tīngshuō gǎnmào yīnggāi chī ròu zhōu, zhèyàng hěn kuài jiù huīfù le. Wǒ shùnbiàn gěi nǐ mǎi yī wǎn zhōu ba!', 'Cậu vẫn còn nói thế được à! Giờ tớ ra hiệu thuốc mua thuốc cho cậu. À đúng rồi, nghe nói bị cảm nên ăn cháo thịt để mau hồi phục. Tớ tiện đường mua cho cậu một bát cháo nhé!', 15) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v19_16', 'lesson-19', '辛苦', 'xīnkǔ', 'từ Hán ngữ', 'mệt, vất vả', 'Động từ / Tính từ', '辛 (Tân) (Cay đắng, vất vả)', '辛: Bộ 辛 (Tân - cái dùi xăm, vất vả cay đắng) • 苦: 艹 (Thảo: cây cỏ đắng) + 古 (Cổ)', 'Ghép 辛 [bộ 辛] + 苦 [bộ 艹] để nhớ từ 辛苦 (xīnkǔ): "mệt, vất vả".', '谢谢！你辛苦了！', 'Xièxie! Nǐ xīnkǔ le!', 'Cảm ơn cậu! Làm phiền cậu quá!', 16) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v19_17', 'lesson-19', '听说', 'tīngshuō', 'thính thuyết', 'nghe nói', 'Động từ', '口 (Khẩu) (Miệng, ăn uống, lời nói, âm thanh phát ra)', '听: 口 (Khẩu) + 斤 (Cân) • 说: 讠 (Ngôn: lời nói) + 兑 (Đoài)', 'Ghép 听 [bộ 口] + 说 [bộ 讠] để nhớ từ 听说 (tīngshuō): "nghe nói".', '你还这样说！我现在去药店给你买药。对了， 听说感冒应该吃肉粥，这样很快就恢复了。我顺便给你买一碗粥吧！', 'Nǐ hái zhèyàng shuō! Wǒ xiànzài qù yàodiàn gěi nǐ mǎi yào. Duì le, tīngshuō gǎnmào yīnggāi chī ròu zhōu, zhèyàng hěn kuài jiù huīfù le. Wǒ shùnbiàn gěi nǐ mǎi yī wǎn zhōu ba!', 'Cậu vẫn còn nói thế được à! Giờ tớ ra hiệu thuốc mua thuốc cho cậu. À đúng rồi, nghe nói bị cảm nên ăn cháo thịt để mau hồi phục. Tớ tiện đường mua cho cậu một bát cháo nhé!', 17) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v19_18', 'lesson-19', '好像', 'hǎoxiàng', 'hảo', 'hình như', 'Phó từ', '女 (Nữ) (Phụ nữ, gia đình, tình cảm)', '好: 女 (Nữ: người mẹ) + 子 (Tử: đứa con) • 像: 亻 (Nhân đứng: người) + 象 (Tượng: hình dáng)', 'Ghép 好 [bộ 女] + 像 [bộ 亻] để nhớ từ 好像 (hǎoxiàng): "hình như".', '我觉得头很疼，上午还发烧和咳嗽， 好像感冒了。', 'Wǒ juéde tóu hěn téng, shàngwǔ hái fāshāo hé késou, hǎoxiàng gǎnmào le.', 'Tớ thấy rất đau đầu, buổi sáng còn bị sốt và ho, hình như cảm lạnh rồi.', 18) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v19_19', 'lesson-19', '要紧', 'yàojǐn', 'yếu', 'nghiêm trọng', 'Tính từ', '西/覀 (Tây) (Phương tây, che đậy)', '要: 覀 (Tây biến thể) + 女 (Nữ) • 紧: 臤 (Hiền rút gọn) + 糸 (Mịch: sợi dây kéo căng)', 'Ghép 要 [bộ 西] + 紧 [bộ 糸] để nhớ từ 要紧 (yàojǐn): "nghiêm trọng".', '没事儿， 只得了感冒而已， 不要紧。', 'Méishìr, zhǐ déle gǎnmào éryǐ, bú yàojǐn.', 'Không sao đâu, chỉ bị cảm nhẹ thôi mà, không đáng ngại đâu.', 19) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v19_20', 'lesson-19', '快', 'kuài', 'khoái', 'nhanh', 'Tính từ', '心/忄 (Tâm) (Trái tim, tình cảm, suy nghĩ, tâm lý)', '快 = 忄 (Tâm đứng: cảm xúc) + 夬 (Quái: nhanh, vui).', 'Chữ 快 (kuài) mang nghĩa "nhanh", bộ chính 心/忄 (Tâm); cấu tạo: 忄 (Tâm đứng: cảm xúc) + 夬 (Quái: nhanh, vui).', '你还这样说！我现在去药店给你买药。对了， 听说感冒应该吃肉粥，这样很快就恢复了。我顺便给你买一碗粥吧！', 'Nǐ hái zhèyàng shuō! Wǒ xiànzài qù yàodiàn gěi nǐ mǎi yào. Duì le, tīngshuō gǎnmào yīnggāi chī ròu zhōu, zhèyàng hěn kuài jiù huīfù le. Wǒ shùnbiàn gěi nǐ mǎi yī wǎn zhōu ba!', 'Cậu vẫn còn nói thế được à! Giờ tớ ra hiệu thuốc mua thuốc cho cậu. À đúng rồi, nghe nói bị cảm nên ăn cháo thịt để mau hồi phục. Tớ tiện đường mua cho cậu một bát cháo nhé!', 20) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v19_21', 'lesson-19', '顺便', 'shùnbiàn', 'tiện', 'thuận tiện, tiện thể', 'Phó từ', '页 (Hiệt) (Đầu mặt, trang giấy)', '顺: 川 (Xuyên: dòng chảy suôn sẻ) + 页 (Hiệt) • 便: 亻 (Nhân đứng) + 更 (Canh)', 'Ghép 顺 [bộ 页] + 便 [bộ 亻] để nhớ từ 顺便 (shùnbiàn): "thuận tiện, tiện thể".', '你还这样说！我现在去药店给你买药。对了， 听说感冒应该吃肉粥，这样很快就恢复了。我顺便给你买一碗粥吧！', 'Nǐ hái zhèyàng shuō! Wǒ xiànzài qù yàodiàn gěi nǐ mǎi yào. Duì le, tīngshuō gǎnmào yīnggāi chī ròu zhōu, zhèyàng hěn kuài jiù huīfù le. Wǒ shùnbiàn gěi nǐ mǎi yī wǎn zhōu ba!', 'Cậu vẫn còn nói thế được à! Giờ tớ ra hiệu thuốc mua thuốc cho cậu. À đúng rồi, nghe nói bị cảm nên ăn cháo thịt để mau hồi phục. Tớ tiện đường mua cho cậu một bát cháo nhé!', 21) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v19_22', 'lesson-19', '而已', 'éryǐ', 'từ Hán ngữ', 'mà thôi', 'Trợ từ', '而 (Nhi) (Mà, râu ria)', '而: Bộ 而 (Nhi - chòm râu, liên từ nối ý) • 已: Bộ 己 (Kỷ - biến thể khép nửa, đã xong)', 'Ghép 而 [bộ 而] + 已 [bộ 己] để nhớ từ 而已 (éryǐ): "mà thôi".', '没事儿， 只得了感冒而已， 不要紧。', 'Méishìr, zhǐ déle gǎnmào éryǐ, bú yàojǐn.', 'Không sao đâu, chỉ bị cảm nhẹ thôi mà, không đáng ngại đâu.', 22) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v19_23', 'lesson-19', '没事儿', 'méishìr', 'một sự nhi', 'không sao', 'Cụm từ / Tên riêng', '水/氵 (Thủy) (Nước, chất lỏng, sông ngòi)', '没: 氵 (Thủy: nước) + 殳 (Thù: chìm mất, không có) • 事: 一 + 口 + 彐 + 亅 (tay cầm sổ ghi công việc) • 儿: Bộ 儿 (Nhi - nét cong, chữ độc thể)', 'Ghép 没 [bộ 氵] + 事 [bộ 亅] + 儿 [bộ 儿] để nhớ từ 没事儿 (méishìr): "không sao".', '没事儿， 只得了感冒而已， 不要紧。', 'Méishìr, zhǐ déle gǎnmào éryǐ, bú yàojǐn.', 'Không sao đâu, chỉ bị cảm nhẹ thôi mà, không đáng ngại đâu.', 23) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v19_24', 'lesson-19', '没想到', 'méixiǎngdào', 'một tưởng đáo', 'không ngờ (rằng)', 'Cụm từ / Tên riêng', '水/氵 (Thủy) (Nước, chất lỏng, sông ngòi)', '没: 氵 (Thủy: nước) + 殳 (Thù: chìm mất, không có) • 想: 相 (Tương: hình ảnh) + 心 (Tâm: lòng suy nghĩ) • 到: 至 (Chí: đi tới) + 刂 (Đao)', 'Ghép 没 [bộ 氵] + 想 [bộ 心] + 到 [bộ 刂] để nhớ từ 没想到 (méixiǎngdào): "không ngờ (rằng)".', '我只喝了一口，  没想到……', 'Wǒ zhǐ hē le yī kǒu, méixiǎngdào…', 'Tớ chỉ uống có một ngụm thôi, không ngờ…', 24) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order) VALUES ('g19_1', 'lesson-19', '1. 能: có thể', 'Cấu trúc câu ngữ pháp trọng tâm', ' Biểu thị có khả năng/năng lực làm gì đó. ●      Phủ định 不能: không thể 早餐他能吃十个包子。 Zǎocān tā néng chī shí gè bāozi. Bữa sáng cậu ấy có thể ăn 10 cái bánh bao. 我的头很疼，不能上课。 Wǒ de tóu hěn téng, bù néng shàngkè. Tớ rất đau đầu, không thể đi học được. 我明天', NULL, '[{"hanzi":"早餐他能吃十个包子。","pinyin":"Zǎocān tā néng chī shí gè bāozi.","meaning":"Bữa sáng cậu ấy có thể ăn 10 cái bánh bao."},{"hanzi":"我的头很疼，不能上课。","pinyin":"Wǒ de tóu hěn téng, bù néng shàngkè.","meaning":"Tớ rất đau đầu, không thể đi học được."}]'::jsonb, 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order) VALUES ('g19_2', 'lesson-19', '2. 最好 – tốt nhất', 'Cấu trúc câu ngữ pháp trọng tâm', ' Dùng trước động từ, biểu thị đề xuất, kiến nghị. 你咳嗽了，最好别抽烟了。 Nǐ késou le, zuì hǎo bié chōuyān le. Anh bị ho rồi, tốt nhất đừng hút thuốc nữa. 你感冒了，最好休息一天吧。 Nǐ gǎnmào le, zuì hǎo xiūxi yī tiān ba. Cậu bị cảm rồi, tốt nhất hãy nghỉ ngơi một ngày đi. ', NULL, '[{"hanzi":"我明天要考试了，不能跟你去。","pinyin":"Wǒ míngtiān yào kǎoshì le, bù néng gēn nǐ qù.","meaning":"Mai tớ thi rồi, không thể đi cùng cậu được."},{"hanzi":"你咳嗽了，最好别抽烟了。","pinyin":"Nǐ késou le, zuì hǎo bié chōuyān le.","meaning":"Anh bị ho rồi, tốt nhất đừng hút thuốc nữa."}]'::jsonb, 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order) VALUES ('g19_3', 'lesson-19', '3. Trợ từ ngữ khí 吧', 'Cấu trúc câu ngữ pháp trọng tâm', ' Trợ từ ngữ khí, dùng ở cuối câu, biểu thị phỏng đoán, suy đoán, ước lượng, không dám khẳng định. 她不来了吧。 Tā bù lái le ba. Chắc là cô đấy không đến nữa. 今天会下雨吧。 Jīntiān huì xià yǔ ba. Hôm nay chắc sẽ mưa đấy nhỉ. 第二十课：锻炼身体 Bài 20: Tập thể dục I. 词语表 –', NULL, '[{"hanzi":"孩子发烧了，最好带她去看医生吧。","pinyin":"Háizi fāshāo le, zuì hǎo dài tā qù kàn yīshēng ba.","meaning":"Con bị ốm rồi, tốt nhất là đưa con đi khám bác sĩ đi."},{"hanzi":"她不来了吧。","pinyin":"Tā bù lái le ba.","meaning":"Chắc là cô đấy không đến nữa."}]'::jsonb, 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order) VALUES ('g19_4', 'lesson-19', '1.身体 shēntǐ dt. cơ thể', 'Cấu trúc câu ngữ pháp trọng tâm', 'Quy tắc ngữ pháp quan trọng trong Bị ốm.', NULL, '[{"hanzi":"今天会下雨吧。","pinyin":"Jīntiān huì xià yǔ ba.","meaning":"Hôm nay chắc sẽ mưa đấy nhỉ."}]'::jsonb, 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order;
INSERT INTO texts (id, lesson_id, title, description, sort_order) VALUES ('txt_19_1', 'lesson-19', 'Bài khoá #1: Hội thoại giáo trình — Bị ốm', 'Hội thoại chuẩn giáo trình Bài 19. Từ vựng chưa học được chú thích phiên âm & nghĩa trong ngoặc.', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_19_1_1', 'txt_19_1', '阮日明', '小兰，你的脸色不太好，是不是生病了？', '小兰，你的脸色不太好，是不是生病了？', 'Xiǎo Lán, nǐ de liǎnsè bú tài hǎo, shì bu shì shēngbìng le?', 'Tiểu Lan, sắc mặt cậu không tốt lắm, có phải bị ốm rồi không?', 1) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_19_1_2', 'txt_19_1', '范玉兰', '我觉得头很疼，上午还发烧和咳嗽， 好像感冒了。', '我觉得头 (tóu: con (trâu, bò) / đầu)很疼 (téng: đau)，上午还发烧和咳嗽， 好像感冒了。', 'Wǒ juéde tóu hěn téng, shàngwǔ hái fāshāo hé késou, hǎoxiàng gǎnmào le.', 'Tớ thấy rất đau đầu, buổi sáng còn bị sốt và ho, hình như cảm lạnh rồi.', 2) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_19_1_3', 'txt_19_1', '阮日明', '你是不是又喝冰水了？你的喉咙经常发炎,你还不戒除冰水。', '你是不是又喝冰水了？你的喉咙 (hóulong: cổ họng)经常发炎 (fāyán: bị viêm),你还不戒除冰水。', 'Nǐ shì bu shì yòu hē bīngshuǐ le? Nǐ de hóulong jīngcháng fāyán, nǐ hái bù jièchú bīngshuǐ.', 'Có phải cậu lại uống nước đá rồi không? Cổ họng cậu hay bị viêm mà cậu vẫn chưa bỏ uống nước đá.', 3) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_19_1_4', 'txt_19_1', '范玉兰', '我只喝了一口，  没想到……', '我只喝了一口，  没想到……', 'Wǒ zhǐ hē le yī kǒu, méixiǎngdào…', 'Tớ chỉ uống có một ngụm thôi, không ngờ…', 4) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_19_1_5', 'txt_19_1', '阮日明', '今天下午有课，你这样一定不能上课了。 最好回家休息吧！', '今天下午有课 (kè: tiết học, bài học)，你这样一定 (yīdìng: nhất định)不能上课了。 最好回家休息吧！', 'Jīntiān xiàwǔ yǒu kè, nǐ zhèyàng yídìng bùnéng shàngkè le. Zuì hǎo huí jiā xiūxi ba!', 'Chiều nay có tiết học, cậu thế này chắc chắn không đi học được rồi. Tốt nhất là về nhà nghỉ ngơi đi!', 5) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_19_1_6', 'txt_19_1', '范玉兰', '那你帮我跟刘老师说一声， 我生病不能上课了！', '那你帮 (bāng: giúp đỡ)我跟 (gēn: cùng, với)刘老师说一声 (shēng: tiếng)， 我生病不能上课了！', 'Nà nǐ bāng wǒ gēn Liú lǎoshī shuō yī shēng, wǒ shēngbìng bùnéng shàngkè le!', 'Vậy cậu nói giúp tớ với cô Lưu một tiếng là tớ bị ốm không thể lên lớp được nhé!', 6) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_19_1_7', 'txt_19_1', '阮日明', '好的！我现在有空儿，还能帮你做什么吗？', '好的！我现在有空儿，还能帮 (bāng: giúp đỡ)你做 (zuò: làm)什么吗？', 'Hǎo de! Wǒ xiànzài yǒu kòngr, hái néng bāng nǐ zuò shénme ma?', 'Được rồi! Giờ tớ đang rảnh, còn giúp được gì cho cậu nữa không?', 7) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_19_1_8', 'txt_19_1', '范玉兰', '没事儿， 只得了感冒而已， 不要紧。', '没事儿， 只得了感冒而已， 不要紧。', 'Méishìr, zhǐ déle gǎnmào éryǐ, bú yàojǐn.', 'Không sao đâu, chỉ bị cảm nhẹ thôi mà, không đáng ngại đâu.', 8) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_19_1_9', 'txt_19_1', '阮日明', '你还这样说！我现在去药店给你买药。对了， 听说感冒应该吃肉粥，这样很快就恢复了。我顺便给你买一碗粥吧！', '你还这样说！我现在去药店给你买药。对了， 听说感冒应该 (yīnggāi: nên, có vẻ như)吃肉粥，这样很快就恢复了。我顺便给你买一碗 (wǎn: cái bát)粥 (zhōu: cháo)吧！', 'Nǐ hái zhèyàng shuō! Wǒ xiànzài qù yàodiàn gěi nǐ mǎi yào. Duì le, tīngshuō gǎnmào yīnggāi chī ròu zhōu, zhèyàng hěn kuài jiù huīfù le. Wǒ shùnbiàn gěi nǐ mǎi yī wǎn zhōu ba!', 'Cậu vẫn còn nói thế được à! Giờ tớ ra hiệu thuốc mua thuốc cho cậu. À đúng rồi, nghe nói bị cảm nên ăn cháo thịt để mau hồi phục. Tớ tiện đường mua cho cậu một bát cháo nhé!', 9) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_19_1_10', 'txt_19_1', '范玉兰', '谢谢！你辛苦了！', '谢谢！你辛苦了！', 'Xièxie! Nǐ xīnkǔ le!', 'Cảm ơn cậu! Làm phiền cậu quá!', 10) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_19_1_1', 'lesson-19', 'txt_19_1', 'listening', 'listening', '小兰，你的脸色不太好，是不是生病了？', NULL, 'Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Lúc tôi gọi điện thoại cho bạn thì bố đang nhìn tôi.","Tiểu Lan, sắc mặt cậu không tốt lắm, có phải bị ốm rồi không?","Hôm qua trời lạnh quá, hình như tôi bị cảm cúm rồi.","Anh ấy giận tôi rồi!"]'::jsonb, 1, 'Nội dung nghe được: 小兰，你的脸色不太好，是不是生病了？ (Xiǎo Lán, nǐ de liǎnsè bú tài hǎo, shì bu shì shēngbìng le?) → Tiểu Lan, sắc mặt cậu không tốt lắm, có phải bị ốm rồi không?', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_19_1_2', 'lesson-19', 'txt_19_1', 'listening', 'listening', '我觉得头很疼，上午还发烧和咳嗽， 好像感冒了。', NULL, 'Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["我明天要考试了，不能跟 (gēn: cùng, với)你去。","多喝温水，过 (guò: từng, qua)几天 (tiān: ngày, trời)身体 (shēntǐ: cơ thể)就会恢复。","谢谢！你辛苦了！","我觉得头 (tóu: con (trâu, bò) / đầu)很疼 (téng: đau)，上午还发烧和咳嗽， 好像感冒了。"]'::jsonb, 3, 'Câu vừa đọc: 我觉得头很疼，上午还发烧和咳嗽， 好像感冒了。 (Wǒ juéde tóu hěn téng, shàngwǔ hái fāshāo hé késou, hǎoxiàng gǎnmào le.) → Tớ thấy rất đau đầu, buổi sáng còn bị sốt và ho, hình như cảm lạnh rồi.', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_19_1_3', 'lesson-19', 'txt_19_1', 'listening', 'listening', '你是不是又喝冰水了？你的喉咙经常发炎,你还不戒除冰水。', NULL, 'Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Có phải cậu lại uống nước đá rồi không? Cổ họng cậu hay bị viêm mà cậu vẫn chưa bỏ uống nước đá.","Cậu vẫn còn nói thế được à! Giờ tớ ra hiệu thuốc mua thuốc cho cậu. À đúng rồi, nghe nói bị cảm nên ăn cháo thịt để mau hồi phục. Tớ tiện đường mua cho cậu một bát cháo nhé!","Hôm nay là thứ mấy?","hai cô gái kia"]'::jsonb, 0, 'Nội dung nghe được: 你是不是又喝冰水了？你的喉咙经常发炎,你还不戒除冰水。 (Nǐ shì bu shì yòu hē bīngshuǐ le? Nǐ de hóulong jīngcháng fāyán, nǐ hái bù jièchú bīngshuǐ.) → Có phải cậu lại uống nước đá rồi không? Cổ họng cậu hay bị viêm mà cậu vẫn chưa bỏ uống nước đá.', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_19_1_4', 'lesson-19', 'txt_19_1', 'listening', 'listening', '我只喝了一口，  没想到……', NULL, 'Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["那你帮 (bāng: giúp đỡ)我跟 (gēn: cùng, với)刘老师说一声 (shēng: tiếng)， 我生病不能上课了！","你太累了，喝完 (wán: xong, hết)这碗 (wǎn: cái bát)肉粥就好好休息吧。","我的头 (tóu: con (trâu, bò) / đầu)很疼 (téng: đau)，不能上课。","我只喝了一口，  没想到……"]'::jsonb, 3, 'Câu vừa đọc: 我只喝了一口，  没想到…… (Wǒ zhǐ hē le yī kǒu, méixiǎngdào…) → Tớ chỉ uống có một ngụm thôi, không ngờ…', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO texts (id, lesson_id, title, description, sort_order) VALUES ('txt_19_2', 'lesson-19', 'Bài nghe tổng hợp: Ôn tập lũy tiến (Bài 1 – Bài 19)', 'Kết hợp từ vựng & mẫu câu đã học từ Bài 1 đến Bài 18 cùng trọng tâm Bài 19 để củng cố phản xạ nghe.', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_19_2_1', 'txt_19_2', 'Ôn Bài 18', '她会说汉语。', '她会说汉语。', 'Tā huì shuō Hànyǔ.', 'Cô ấy biết nói tiếng Trung.', 1) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_19_2_2', 'txt_19_2', 'Bài 19', '今天会下雨吧。', '今天会下雨吧。', 'Jīntiān huì xià yǔ ba.', 'Hôm nay chắc sẽ mưa đấy nhỉ.', 2) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_19_2_3', 'txt_19_2', 'Ôn Bài 9', '我们下午去吧！', '我们下午去吧！', 'Wǒmen xiàwǔ qù ba!', 'Buổi chiều chúng ta đi nhé!', 3) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_19_2_4', 'txt_19_2', 'Bài 19', '小兰，你的脸色不太好，是不是生病了？', '小兰，你的脸色不太好，是不是生病了？', 'Xiǎo Lán, nǐ de liǎnsè bú tài hǎo, shì bu shì shēngbìng le?', 'Tiểu Lan, sắc mặt cậu không tốt lắm, có phải bị ốm rồi không?', 4) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_19_2_5', 'txt_19_2', 'Ôn Bài 1', '老师们', '老师们', 'lǎoshīmen', 'Các thầy cô giáo', 5) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_19_2_6', 'txt_19_2', 'Bài 19', '我只喝了一口，  没想到……', '我只喝了一口，  没想到……', 'Wǒ zhǐ hē le yī kǒu, méixiǎngdào…', 'Tớ chỉ uống có một ngụm thôi, không ngờ…', 6) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_19_2_7', 'txt_19_2', 'Ôn Bài 11', '他们只关心自己。', '他们只关心自己。', 'Tāmen zhǐ guānxīn zìjǐ.', 'Bọn họ chỉ quan tâm đến bản thân mình mà thôi.', 7) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_19_2_8', 'txt_19_2', 'Bài 19', '没事儿， 只得了感冒而已， 不要紧。', '没事儿， 只得了感冒而已， 不要紧。', 'Méishìr, zhǐ déle gǎnmào éryǐ, bú yàojǐn.', 'Không sao đâu, chỉ bị cảm nhẹ thôi mà, không đáng ngại đâu.', 8) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_19_2_1', 'lesson-19', 'txt_19_2', 'listening', 'listening', '她会说汉语。', NULL, '[Ôn tập Bài 18] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Tôi sẽ không về nhà cùng với anh ta đâu.","hai quyển sách","Em bé đang bị sốt.","Cô ấy biết nói tiếng Trung."]'::jsonb, 3, 'Nội dung nghe được: 她会说汉语。 (Tā huì shuō Hànyǔ.) → Cô ấy biết nói tiếng Trung.', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_19_2_2', 'lesson-19', 'txt_19_2', 'listening', 'listening', '今天会下雨吧。', NULL, '[Bài 19] Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["我明天要考试了，不能跟 (gēn: cùng, với)你去。","今天会下雨吧。","你得 (děi: phải)多锻炼 (duànliàn: tập luyện, tập)了。","她不来 (lái: đến)了吧。"]'::jsonb, 1, 'Câu vừa đọc: 今天会下雨吧。 (Jīntiān huì xià yǔ ba.) → Hôm nay chắc sẽ mưa đấy nhỉ.', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_19_2_3', 'lesson-19', 'txt_19_2', 'listening', 'listening', '我们下午去吧！', NULL, '[Ôn tập Bài 9] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Con đang ăn nè.","Buổi chiều chúng ta đi nhé!","cây thước kẻ của anh ấy","chúng tôi của hiện tại"]'::jsonb, 1, 'Nội dung nghe được: 我们下午去吧！ (Wǒmen xiàwǔ qù ba!) → Buổi chiều chúng ta đi nhé!', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_19_2_4', 'lesson-19', 'txt_19_2', 'listening', 'listening', '小兰，你的脸色不太好，是不是生病了？', NULL, '[Bài 19] Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["今天下午有课 (kè: tiết học, bài học)，你这样一定 (yīdìng: nhất định)不能上课了。 最好回家休息吧！","你还这样说！我现在去药店给你买药。对了， 听说感冒应该 (yīnggāi: nên, có vẻ như)吃肉粥，这样很快就恢复了。我顺便给你买一碗 (wǎn: cái bát)粥 (zhōu: cháo)吧！","小兰，你的脸色不太好，是不是生病了？","你咳嗽了，最好别 (bié: đừng)抽烟 (chōuyān: hút thuốc)了。"]'::jsonb, 2, 'Câu vừa đọc: 小兰，你的脸色不太好，是不是生病了？ (Xiǎo Lán, nǐ de liǎnsè bú tài hǎo, shì bu shì shēngbìng le?) → Tiểu Lan, sắc mặt cậu không tốt lắm, có phải bị ốm rồi không?', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_19_2_5', 'lesson-19', 'txt_19_2', 'listening', 'listening', '老师们', NULL, '[Ôn tập Bài 1] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Các thầy cô giáo","Tớ muốn đến công viên chạy bộ.","Tôi vẫn chưa nghĩ xong nên mặc váy màu đỏ hay là váy màu xanh nữa.","Xin hỏi đến siêu thị đi thế nào vậy?"]'::jsonb, 0, 'Nội dung nghe được: 老师们 (lǎoshīmen) → Các thầy cô giáo', 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO texts (id, lesson_id, title, description, sort_order) VALUES ('txt_19_3', 'lesson-19', 'Bài khoá mở rộng: Chăm sóc bạn bị cảm sốt (Mở rộng)', 'Hội thoại tình huống mới xây dựng dựa trên từ vựng và ngữ pháp Bài 19 (không trùng lặp nguyên văn giáo trình).', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_19_3_1', 'txt_19_3', 'Minh', '小兰，你脸色不太好，是不是感冒发烧了？', '小兰，你脸色不太好，是不是感冒发烧了？', 'Xiǎolán, nǐ liǎnsè bú tài hǎo, shì bu shì gǎnmào fāshāo le?', 'Tiểu Lan, sắc mặt cậu không tốt lắm, có phải bị cảm sốt rồi không?', 1) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_19_3_2', 'txt_19_3', 'Lan', '嗯，我头很疼，还有点儿咳嗽、喉咙发炎。', '嗯 (èn: ừ, ừm)，我头 (tóu: con (trâu, bò) / đầu)很疼 (téng: đau)，还有点儿咳嗽、喉咙发炎。', 'Ēn, wǒ tóu hěn téng, hái yǒudiǎnr késou, hóulong fāyán.', 'Ừ, tớ đau đầu quá, lại hơi ho và viêm họng nữa.', 2) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_19_3_3', 'txt_19_3', 'Minh', '你以后得戒除冰水了。我已经去药店给你买了药和一碗肉粥。', '你以后 (yǐhòu: sau, lúc sau)得 (děi: phải)戒除冰水了。我已经 (yǐjīng: đã)去药店给你买了药和一碗 (wǎn: cái bát)肉粥。', 'Nǐ yǐhòu děi jièchú bīngshuǐ le. Wǒ yǐjīng qù yàodiàn gěi nǐ mǎi le yào hé yì wǎn ròuzhōu.', 'Sau này cậu phải bỏ uống nước đá đi nhé. Tớ đã ra hiệu thuốc mua thuốc và một bát cháo thịt cho cậu rồi.', 3) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_19_3_4', 'txt_19_3', 'Lan', '太谢谢你了，喝完粥吃药我一定会很快恢复！', '太谢谢你了，喝完 (wán: xong, hết)粥 (zhōu: cháo)吃药我一定 (yīdìng: nhất định)会很快恢复！', 'Tài xièxie nǐ le, hēwán zhōu chī yào wǒ yídìng huì hěn kuài huīfù!', 'Cảm ơn cậu nhiều lắm, ăn cháo uống thuốc xong tớ nhất định sẽ mau khỏi!', 4) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_19_3_1', 'lesson-19', 'txt_19_3', 'listening', 'listening', '小兰，你脸色不太好，是不是感冒发烧了？ 嗯，我头很疼，还有点儿咳嗽、喉咙发炎。 你以后得戒除冰水了。我已经去药店给你买了药和一碗肉粥。 太谢谢你了，喝完粥吃药我一定会很快恢复！', NULL, '[Nghe hiểu tình huống mới] Minh đã mua những gì cho Tiểu Lan khi cô ấy bị ốm?', '["Mua thuốc ở hiệu thuốc và một bát cháo thịt","Mua một cốc nước đá và trái cây","Mua vé đi du lịch","Mua sách và bút bi"]'::jsonb, 0, 'Minh nói ''我已经去药店给你买了药和一碗肉粥''.', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_19_3_2', 'lesson-19', 'txt_19_3', 'listening', 'listening', '小兰，你脸色不太好，是不是感冒发烧了？', NULL, '[Mở rộng] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Hiệu sách phía trước","Bộ quần áo này là hàng thật, không phải hàng giả đâu.","Bạn bè tốt đã mời tôi, tôi đâu thể không đi được? (Tôi nhất định sẽ đi)","Tiểu Lan, sắc mặt cậu không tốt lắm, có phải bị cảm sốt rồi không?"]'::jsonb, 3, 'Nội dung nghe được: 小兰，你脸色不太好，是不是感冒发烧了？ (Xiǎolán, nǐ liǎnsè bú tài hǎo, shì bu shì gǎnmào fāshāo le?) → Tiểu Lan, sắc mặt cậu không tốt lắm, có phải bị cảm sốt rồi không?', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_19_3_3', 'lesson-19', 'txt_19_3', 'listening', 'listening', '嗯，我头很疼，还有点儿咳嗽、喉咙发炎。', NULL, '[Mở rộng] Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["嗯 (èn: ừ, ừm)，我头 (tóu: con (trâu, bò) / đầu)很疼 (téng: đau)，还有点儿咳嗽、喉咙发炎。","我今天头疼、发烧，还一直咳嗽。","我觉得头 (tóu: con (trâu, bò) / đầu)很疼 (téng: đau)，上午还发烧和咳嗽， 好像感冒了。","她不来 (lái: đến)了吧。"]'::jsonb, 0, 'Câu vừa đọc: 嗯，我头很疼，还有点儿咳嗽、喉咙发炎。 (Ēn, wǒ tóu hěn téng, hái yǒudiǎnr késou, hóulong fāyán.) → Ừ, tớ đau đầu quá, lại hơi ho và viêm họng nữa.', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_19_3_4', 'lesson-19', 'txt_19_3', 'listening', 'listening', '你以后得戒除冰水了。我已经去药店给你买了药和一碗肉粥。', NULL, '[Mở rộng] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Sau này cậu phải bỏ uống nước đá đi nhé. Tớ đã ra hiệu thuốc mua thuốc và một bát cháo thịt cho cậu rồi.","Em trai vui đến nổi nhảy cẫng lên.","Anh bị ho rồi, tốt nhất đừng hút thuốc nữa.","Tám giờ sáng ngày mai tớ đi học."]'::jsonb, 0, 'Nội dung nghe được: 你以后得戒除冰水了。我已经去药店给你买了药和一碗肉粥。 (Nǐ yǐhòu děi jièchú bīngshuǐ le. Wǒ yǐjīng qù yàodiàn gěi nǐ mǎi le yào hé yì wǎn ròuzhōu.) → Sau này cậu phải bỏ uống nước đá đi nhé. Tớ đã ra hiệu thuốc mua thuốc và một bát cháo thịt cho cậu rồi.', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss19_1', 'lesson-19', '昨天天气太冷我好像得了感冒', '[Mở rộng] Hôm qua trời lạnh quá, hình như tôi bị cảm cúm rồi.', 'Zuótiān tiānqì tài lěng, wǒ hǎoxiàng dé le gǎnmào.', '["昨天","天气","太冷我","好像","得了","感冒"]'::jsonb, NULL, 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss19_2', 'lesson-19', '我今天头疼发烧还一直咳嗽', '[Mở rộng] Hôm nay tôi bị đau đầu, sốt, lại còn ho liên tục.', 'Wǒ jīntiān tóuténg, fāshāo, hái yìzhí késou.', '["我今天","头疼","发烧","还","一直","咳嗽"]'::jsonb, NULL, 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss19_3', 'lesson-19', '今天会下雨吧', 'Hôm nay chắc sẽ mưa đấy nhỉ.', 'Jīntiān huì xià yǔ ba.', '["今天","会","下雨","吧"]'::jsonb, NULL, 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss19_4', 'lesson-19', '我只喝了一口没想到……', 'Tớ chỉ uống có một ngụm thôi, không ngờ…', 'Wǒ zhǐ hē le yī kǒu, méixiǎngdào…', '["我只","喝了","一口","没想到","…","…"]'::jsonb, NULL, 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss19_5', 'lesson-19', '阿姨今天的苹果甜不甜', '[Ôn tập Bài 8] Cô ơi, táo hôm nay có ngọt không ạ?', 'Āyí, jīntiān de píngguǒ tián bu tián?', '["阿姨","今天的","苹果","甜","不","甜"]'::jsonb, NULL, 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss19_6', 'lesson-19', '我觉得春天的天气最暖和最舒服', '[Ôn tập Bài 15] Tôi thấy thời tiết mùa xuân ấm áp và dễ chịu nhất.', 'Wǒ juéde chūntiān de tiānqì zuì nuǎnhuo, zuì shūfu.', '["我觉得","春天的","天气最","暖和","最","舒服"]'::jsonb, NULL, 6) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss19_exp_1', 'lesson-19', '小兰你的脸色不太好是不是生病了', 'Tiểu Lan, sắc mặt cậu không tốt lắm, có phải bị ốm rồi không?', 'Xiǎo Lán, nǐ de liǎnsè bú tài hǎo, shì bu shì shēngbìng le?', '["小","兰","你","的","脸色","不","太","好","是","不是","生病","了"]'::jsonb, NULL, 7) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss19_exp_2', 'lesson-19', '我觉得头很疼上午还发烧和咳嗽好像感冒了', 'Tớ thấy rất đau đầu, buổi sáng còn bị sốt và ho, hình như cảm lạnh rồi.', 'Wǒ juéde tóu hěn téng, shàngwǔ hái fāshāo hé késou, hǎoxiàng gǎnmào le.', '["我","觉得","头","很","疼","上午","还","发烧","和","咳嗽","好像","感冒","了"]'::jsonb, NULL, 8) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss19_exp_3', 'lesson-19', '你是不是又喝冰水了你的喉咙经常发炎你还不戒除冰水', 'Có phải cậu lại uống nước đá rồi không? Cổ họng cậu hay bị viêm mà cậu vẫn chưa bỏ uống nước đá.', 'Nǐ shì bu shì yòu hē bīngshuǐ le? Nǐ de hóulong jīngcháng fāyán, nǐ hái bù jièchú bīngshuǐ.', '["你","是","不是","又","喝","冰水","了","你","的","喉","咙","经常","发","炎","你","还","不","戒除","冰水"]'::jsonb, NULL, 9) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss19_exp_4', 'lesson-19', '今天下午有课你这样一定不能上课了最好回家休息吧', 'Chiều nay có tiết học, cậu thế này chắc chắn không đi học được rồi. Tốt nhất là về nhà nghỉ ngơi đi!', 'Jīntiān xiàwǔ yǒu kè, nǐ zhèyàng yídìng bùnéng shàngkè le. Zuì hǎo huí jiā xiūxi ba!', '["今天","下午","有","课","你","这样","一","定","不","能","上课","了","最","好","回","家","休息","吧"]'::jsonb, NULL, 10) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss19_exp_5', 'lesson-19', '那你帮我跟刘老师说一声我生病不能上课了', 'Vậy cậu nói giúp tớ với cô Lưu một tiếng là tớ bị ốm không thể lên lớp được nhé!', 'Nà nǐ bāng wǒ gēn Liú lǎoshī shuō yī shēng, wǒ shēngbìng bùnéng shàngkè le!', '["那","你","帮","我","跟","刘","老师","说","一","声","我","生病","不","能","上课","了"]'::jsonb, NULL, 11) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss19_exp_6', 'lesson-19', '好的我现在有空儿还能帮你做什么吗', 'Được rồi! Giờ tớ đang rảnh, còn giúp được gì cho cậu nữa không?', 'Hǎo de! Wǒ xiànzài yǒu kòngr, hái néng bāng nǐ zuò shénme ma?', '["好","的","我","现在","有空儿","还","能","帮","你","做","什么","吗"]'::jsonb, NULL, 12) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss19_exp_7', 'lesson-19', '没事儿只得了感冒而已不要紧', 'Không sao đâu, chỉ bị cảm nhẹ thôi mà, không đáng ngại đâu.', 'Méishìr, zhǐ déle gǎnmào éryǐ, bú yàojǐn.', '["没事儿","只","得了","感冒","而已","不","要紧"]'::jsonb, NULL, 13) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss19_exp_8', 'lesson-19', '你还这样说我现在去药店给你买药对了听说感冒应该吃肉粥这样很快就恢复了我顺便给你买一碗粥吧', 'Cậu vẫn còn nói thế được à! Giờ tớ ra hiệu thuốc mua thuốc cho cậu. À đúng rồi, nghe nói bị cảm nên ăn cháo thịt để mau hồi phục. Tớ tiện đường mua cho cậu một bát cháo nhé!', 'Nǐ hái zhèyàng shuō! Wǒ xiànzài qù yàodiàn gěi nǐ mǎi yào. Duì le, tīngshuō gǎnmào yīnggāi chī ròu zhōu, zhèyàng hěn kuài jiù huīfù le. Wǒ shùnbiàn gěi nǐ mǎi yī wǎn zhōu ba!', '["你","还","这样","说","我","现在","去","药店","给","你","买","药","对","了","听说","感冒","应","该","吃","肉粥","这样","很","快","就","恢复","了","我","顺便","给","你","买","一","碗","粥","吧"]'::jsonb, NULL, 14) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss19_exp_9', 'lesson-19', '谢谢你辛苦了', 'Cảm ơn cậu! Làm phiền cậu quá!', 'Xièxie! Nǐ xīnkǔ le!', '["谢谢","你","辛苦","了"]'::jsonb, NULL, 15) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
