INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss19_exp_13', 'lesson-19', '他们只关心自己', 'Bọn họ chỉ quan tâm đến bản thân mình mà thôi.', 'Tāmen zhǐ guānxīn zìjǐ.', '["他们","只","关心","自己"]'::jsonb, NULL, 19) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss19_exp_14', 'lesson-19', '小兰你脸色不太好是不是感冒发烧了', 'Tiểu Lan, sắc mặt cậu không tốt lắm, có phải bị cảm sốt rồi không?', 'Xiǎolán, nǐ liǎnsè bú tài hǎo, shì bu shì gǎnmào fāshāo le?', '["小","兰","你","脸色","不","太","好","是","不是","感冒","发烧","了"]'::jsonb, NULL, 20) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr19_vi_1', 'lesson-19', 'vi_to_zh', '[Mở rộng] Hôm qua trời lạnh quá, hình như tôi bị cảm cúm rồi.', NULL, NULL, '昨天天气太冷，我好像得了感冒。', NULL, 'zuótiān tiānqì tài lěng wǒ hǎoxiàng dé le gǎnmào', '[]'::jsonb, 'Gợi ý Pinyin: Zuótiān tiānqì tài lěng, wǒ hǎoxiàng dé le gǎnmào.', 'Hôm qua trời lạnh quá, hình như tôi bị cảm cúm rồi. → 昨天天气太冷，我好像得了感冒。 (Zuótiān tiānqì tài lěng, wǒ hǎoxiàng dé le gǎnmào.)', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr19_vi_2', 'lesson-19', 'vi_to_zh', '[Mở rộng] Hôm nay tôi bị đau đầu, sốt, lại còn ho liên tục.', NULL, NULL, '我今天头疼、发烧，还一直咳嗽。', NULL, 'wǒ jīntiān tóuténg fāshāo hái yìzhí késou', '[]'::jsonb, 'Gợi ý Pinyin: Wǒ jīntiān tóuténg, fāshāo, hái yìzhí késou.', 'Hôm nay tôi bị đau đầu, sốt, lại còn ho liên tục. → 我今天头疼、发烧，还一直咳嗽。 (Wǒ jīntiān tóuténg, fāshāo, hái yìzhí késou.)', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr19_vi_3', 'lesson-19', 'vi_to_zh', 'Hôm nay chắc sẽ mưa đấy nhỉ.', NULL, NULL, '今天会下雨吧。', NULL, 'jīntiān huì xià yǔ ba', '[]'::jsonb, 'Gợi ý Pinyin: Jīntiān huì xià yǔ ba.', 'Hôm nay chắc sẽ mưa đấy nhỉ. → 今天会下雨吧。 (Jīntiān huì xià yǔ ba.)', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr19_vi_4', 'lesson-19', 'vi_to_zh', 'Mai tớ thi rồi, không thể đi cùng cậu được.', NULL, NULL, '我明天要考试了，不能跟你去。', NULL, 'wǒ míngtiān yào kǎoshì le bù néng gēn nǐ qù', '[]'::jsonb, 'Gợi ý Pinyin: Wǒ míngtiān yào kǎoshì le, bù néng gēn nǐ qù. | Từ chưa học: 跟 (gēn: cùng, với)', 'Mai tớ thi rồi, không thể đi cùng cậu được. → 我明天要考试了，不能跟你去。 (Wǒ míngtiān yào kǎoshì le, bù néng gēn nǐ qù.)', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr19_vi_exp_1', 'lesson-19', 'vi_to_zh', 'Tiểu Lan, sắc mặt cậu không tốt lắm, có phải bị ốm rồi không?', NULL, NULL, '小兰，你的脸色不太好，是不是生病了？', NULL, 'xiǎo lán nǐ de liǎnsè bú tài hǎo shì bu shì shēngbìng le', '[]'::jsonb, 'Gợi ý Pinyin: Xiǎo Lán, nǐ de liǎnsè bú tài hǎo, shì bu shì shēngbìng le?', 'Tiểu Lan, sắc mặt cậu không tốt lắm, có phải bị ốm rồi không? → 小兰，你的脸色不太好，是不是生病了？ (Xiǎo Lán, nǐ de liǎnsè bú tài hǎo, shì bu shì shēngbìng le?)', 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr19_vi_exp_2', 'lesson-19', 'vi_to_zh', 'Tớ thấy rất đau đầu, buổi sáng còn bị sốt và ho, hình như cảm lạnh rồi.', NULL, NULL, '我觉得头很疼，上午还发烧和咳嗽， 好像感冒了。', NULL, 'wǒ juéde tóu hěn téng shàngwǔ hái fāshāo hé késou hǎoxiàng gǎnmào le', '[]'::jsonb, 'Gợi ý Pinyin: Wǒ juéde tóu hěn téng, shàngwǔ hái fāshāo hé késou, hǎoxiàng gǎnmào le.', 'Tớ thấy rất đau đầu, buổi sáng còn bị sốt và ho, hình như cảm lạnh rồi. → 我觉得头很疼，上午还发烧和咳嗽， 好像感冒了。 (Wǒ juéde tóu hěn téng, shàngwǔ hái fāshāo hé késou, hǎoxiàng gǎnmào le.)', 6) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr19_vi_exp_3', 'lesson-19', 'vi_to_zh', 'Có phải cậu lại uống nước đá rồi không? Cổ họng cậu hay bị viêm mà cậu vẫn chưa bỏ uống nước đá.', NULL, NULL, '你是不是又喝冰水了？你的喉咙经常发炎,你还不戒除冰水。', NULL, 'nǐ shì bu shì yòu hē bīngshuǐ le nǐ de hóulong jīngcháng fāyán nǐ hái bù jièchú bīngshuǐ', '[]'::jsonb, 'Gợi ý Pinyin: Nǐ shì bu shì yòu hē bīngshuǐ le? Nǐ de hóulong jīngcháng fāyán, nǐ hái bù jièchú bīngshuǐ.', 'Có phải cậu lại uống nước đá rồi không? Cổ họng cậu hay bị viêm mà cậu vẫn chưa bỏ uống nước đá. → 你是不是又喝冰水了？你的喉咙经常发炎,你还不戒除冰水。 (Nǐ shì bu shì yòu hē bīngshuǐ le? Nǐ de hóulong jīngcháng fāyán, nǐ hái bù jièchú bīngshuǐ.)', 7) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr19_vi_exp_4', 'lesson-19', 'vi_to_zh', 'Tớ chỉ uống có một ngụm thôi, không ngờ…', NULL, NULL, '我只喝了一口， 没想到……', NULL, 'wǒ zhǐ hē le yī kǒu méixiǎngdào…', '[]'::jsonb, 'Gợi ý Pinyin: Wǒ zhǐ hē le yī kǒu, méixiǎngdào…', 'Tớ chỉ uống có một ngụm thôi, không ngờ… → 我只喝了一口， 没想到…… (Wǒ zhǐ hē le yī kǒu, méixiǎngdào…)', 8) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr19_vi_exp_5', 'lesson-19', 'vi_to_zh', 'Chiều nay có tiết học, cậu thế này chắc chắn không đi học được rồi. Tốt nhất là về nhà nghỉ ngơi đi!', NULL, NULL, '今天下午有课，你这样一定不能上课了。 最好回家休息吧！', NULL, 'jīntiān xiàwǔ yǒu kè nǐ zhèyàng yídìng bùnéng shàngkè le zuì hǎo huí jiā xiūxi ba', '[]'::jsonb, 'Gợi ý Pinyin: Jīntiān xiàwǔ yǒu kè, nǐ zhèyàng yídìng bùnéng shàngkè le. Zuì hǎo huí jiā xiūxi ba!', 'Chiều nay có tiết học, cậu thế này chắc chắn không đi học được rồi. Tốt nhất là về nhà nghỉ ngơi đi! → 今天下午有课，你这样一定不能上课了。 最好回家休息吧！ (Jīntiān xiàwǔ yǒu kè, nǐ zhèyàng yídìng bùnéng shàngkè le. Zuì hǎo huí jiā xiūxi ba!)', 9) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr19_vi_exp_6', 'lesson-19', 'vi_to_zh', 'Vậy cậu nói giúp tớ với cô Lưu một tiếng là tớ bị ốm không thể lên lớp được nhé!', NULL, NULL, '那你帮我跟刘老师说一声， 我生病不能上课了！', NULL, 'nà nǐ bāng wǒ gēn liú lǎoshī shuō yī shēng wǒ shēngbìng bùnéng shàngkè le', '[]'::jsonb, 'Gợi ý Pinyin: Nà nǐ bāng wǒ gēn Liú lǎoshī shuō yī shēng, wǒ shēngbìng bùnéng shàngkè le!', 'Vậy cậu nói giúp tớ với cô Lưu một tiếng là tớ bị ốm không thể lên lớp được nhé! → 那你帮我跟刘老师说一声， 我生病不能上课了！ (Nà nǐ bāng wǒ gēn Liú lǎoshī shuō yī shēng, wǒ shēngbìng bùnéng shàngkè le!)', 10) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr19_vi_exp_7', 'lesson-19', 'vi_to_zh', 'Được rồi! Giờ tớ đang rảnh, còn giúp được gì cho cậu nữa không?', NULL, NULL, '好的！我现在有空儿，还能帮你做什么吗？', NULL, 'hǎo de wǒ xiànzài yǒu kòngr hái néng bāng nǐ zuò shénme ma', '[]'::jsonb, 'Gợi ý Pinyin: Hǎo de! Wǒ xiànzài yǒu kòngr, hái néng bāng nǐ zuò shénme ma?', 'Được rồi! Giờ tớ đang rảnh, còn giúp được gì cho cậu nữa không? → 好的！我现在有空儿，还能帮你做什么吗？ (Hǎo de! Wǒ xiànzài yǒu kòngr, hái néng bāng nǐ zuò shénme ma?)', 11) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr19_vi_exp_8', 'lesson-19', 'vi_to_zh', 'Không sao đâu, chỉ bị cảm nhẹ thôi mà, không đáng ngại đâu.', NULL, NULL, '没事儿， 只得了感冒而已， 不要紧。', NULL, 'méishìr zhǐ déle gǎnmào éryǐ bú yàojǐn', '[]'::jsonb, 'Gợi ý Pinyin: Méishìr, zhǐ déle gǎnmào éryǐ, bú yàojǐn.', 'Không sao đâu, chỉ bị cảm nhẹ thôi mà, không đáng ngại đâu. → 没事儿， 只得了感冒而已， 不要紧。 (Méishìr, zhǐ déle gǎnmào éryǐ, bú yàojǐn.)', 12) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr19_vi_exp_9', 'lesson-19', 'vi_to_zh', 'Cậu vẫn còn nói thế được à! Giờ tớ ra hiệu thuốc mua thuốc cho cậu. À đúng rồi, nghe nói bị cảm nên ăn cháo thịt để mau hồi phục. Tớ tiện đường mua cho cậu một bát cháo nhé!', NULL, NULL, '你还这样说！我现在去药店给你买药。对了， 听说感冒应该吃肉粥，这样很快就恢复了。我顺便给你买一碗粥吧！', NULL, 'nǐ hái zhèyàng shuō wǒ xiànzài qù yàodiàn gěi nǐ mǎi yào duì le tīngshuō gǎnmào yīnggāi chī ròu zhōu zhèyàng hěn kuài jiù huīfù le wǒ shùnbiàn gěi nǐ mǎi yī wǎn zhōu ba', '[]'::jsonb, 'Gợi ý Pinyin: Nǐ hái zhèyàng shuō! Wǒ xiànzài qù yàodiàn gěi nǐ mǎi yào. Duì le, tīngshuō gǎnmào yīnggāi chī ròu zhōu, zhèyàng hěn kuài jiù huīfù le. Wǒ shùnbiàn gěi nǐ mǎi yī wǎn zhōu ba!', 'Cậu vẫn còn nói thế được à! Giờ tớ ra hiệu thuốc mua thuốc cho cậu. À đúng rồi, nghe nói bị cảm nên ăn cháo thịt để mau hồi phục. Tớ tiện đường mua cho cậu một bát cháo nhé! → 你还这样说！我现在去药店给你买药。对了， 听说感冒应该吃肉粥，这样很快就恢复了。我顺便给你买一碗粥吧！ (Nǐ hái zhèyàng shuō! Wǒ xiànzài qù yàodiàn gěi nǐ mǎi yào. Duì le, tīngshuō gǎnmào yīnggāi chī ròu zhōu, zhèyàng hěn kuài jiù huīfù le. Wǒ shùnbiàn gěi nǐ mǎi yī wǎn zhōu ba!)', 13) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr19_vi_exp_10', 'lesson-19', 'vi_to_zh', 'Cảm ơn cậu! Làm phiền cậu quá!', NULL, NULL, '谢谢！你辛苦了！', NULL, 'xièxie nǐ xīnkǔ le', '[]'::jsonb, 'Gợi ý Pinyin: Xièxie! Nǐ xīnkǔ le!', 'Cảm ơn cậu! Làm phiền cậu quá! → 谢谢！你辛苦了！ (Xièxie! Nǐ xīnkǔ le!)', 14) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr19_zh_1', 'lesson-19', 'zh_to_vi', '[Mở rộng] 我去药店给你买一些感冒药。', '我去药店给你买一些感冒药。', 'Wǒ qù yàodiàn gěi nǐ mǎi yìxiē gǎnmàoyào.', NULL, 'Tôi ra hiệu thuốc mua cho bạn một ít thuốc cảm nhé.', NULL, '["Tôi","ra","hiệu"]'::jsonb, 'Pinyin: Wǒ qù yàodiàn gěi nǐ mǎi yìxiē gǎnmàoyào.', '我去药店给你买一些感冒药。 (Wǒ qù yàodiàn gěi nǐ mǎi yìxiē gǎnmàoyào.) nghĩa là: Tôi ra hiệu thuốc mua cho bạn một ít thuốc cảm nhé.', 15) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr19_zh_2', 'lesson-19', 'zh_to_vi', '[Mở rộng] 你太累了，喝完 (wán: xong, hết)这碗 (wǎn: cái bát)肉粥就好好休息吧。', '你太累了，喝完这碗肉粥就好好休息吧。', 'Nǐ tài lèi le, hēwán zhè wǎn ròuzhōu jiù hǎohāo xiūxi ba.', NULL, 'Bạn mệt quá rồi, ăn hết bát cháo thịt này rồi nghỉ ngơi cho khỏe nhé.', NULL, '["Bạn","mệt","quá"]'::jsonb, 'Pinyin: Nǐ tài lèi le, hēwán zhè wǎn ròuzhōu jiù hǎohāo xiūxi ba.', '你太累了，喝完这碗肉粥就好好休息吧。 (Nǐ tài lèi le, hēwán zhè wǎn ròuzhōu jiù hǎohāo xiūxi ba.) nghĩa là: Bạn mệt quá rồi, ăn hết bát cháo thịt này rồi nghỉ ngơi cho khỏe nhé.', 16) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
