INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr19_zh_exp_1', 'lesson-19', 'zh_to_vi', '孩子发烧了，最好带她去看医生吧。', '孩子发烧了，最好带她去看医生吧。', 'Háizi fāshāo le, zuì hǎo dài tā qù kàn yīshēng ba.', NULL, 'Con bị ốm rồi, tốt nhất là đưa con đi khám bác sĩ đi.', NULL, '["con","bị","ốm","rồi","tốt","nhất","là","đưa","con","đi","khám","bác","sĩ","đi"]'::jsonb, 'Pinyin: Háizi fāshāo le, zuì hǎo dài tā qù kàn yīshēng ba.', '孩子发烧了，最好带她去看医生吧。 (Háizi fāshāo le, zuì hǎo dài tā qù kàn yīshēng ba.) nghĩa là: Con bị ốm rồi, tốt nhất là đưa con đi khám bác sĩ đi.', 19) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
