INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr19_zh_exp_6', 'lesson-19', 'zh_to_vi', '太谢谢你了，喝完粥吃药我一定会很快恢复！', '太谢谢你了，喝完粥吃药我一定会很快恢复！', 'Tài xièxie nǐ le, hēwán zhōu chī yào wǒ yídìng huì hěn kuài huīfù!', NULL, 'Cảm ơn cậu nhiều lắm, ăn cháo uống thuốc xong tớ nhất định sẽ mau khỏi!', NULL, '["cảm","ơn","cậu","nhiều","lắm","ăn","cháo","uống","thuốc","xong","tớ","nhất","định","sẽ","mau","khỏi"]'::jsonb, 'Pinyin: Tài xièxie nǐ le, hēwán zhōu chī yào wǒ yídìng huì hěn kuài huīfù!', '太谢谢你了，喝完粥吃药我一定会很快恢复！ (Tài xièxie nǐ le, hēwán zhōu chī yào wǒ yídìng huì hěn kuài huīfù!) nghĩa là: Cảm ơn cậu nhiều lắm, ăn cháo uống thuốc xong tớ nhất định sẽ mau khỏi!', 24) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr19_zh_exp_7', 'lesson-19', 'zh_to_vi', '你以后得戒除冰水了。我已经去药店给你买了药和一碗肉粥。', '你以后得戒除冰水了。我已经去药店给你买了药和一碗肉粥。', 'Nǐ yǐhòu děi jièchú bīngshuǐ le. Wǒ yǐjīng qù yàodiàn gěi nǐ mǎi le yào hé yì wǎn ròuzhōu.', NULL, 'Sau này cậu phải bỏ uống nước đá đi nhé. Tớ đã ra hiệu thuốc mua thuốc và một bát cháo thịt cho cậu rồi.', NULL, '["sau","này","cậu","phải","bỏ","uống","nước","đá","đi","nhé","tớ","đã","ra","hiệu","thuốc","mua","thuốc","và","một","bát","cháo","thịt","cho","cậu","rồi"]'::jsonb, 'Pinyin: Nǐ yǐhòu děi jièchú bīngshuǐ le. Wǒ yǐjīng qù yàodiàn gěi nǐ mǎi le yào hé yì wǎn ròuzhōu.', '你以后得戒除冰水了。我已经去药店给你买了药和一碗肉粥。 (Nǐ yǐhòu děi jièchú bīngshuǐ le. Wǒ yǐjīng qù yàodiàn gěi nǐ mǎi le yào hé yì wǎn ròuzhōu.) nghĩa là: Sau này cậu phải bỏ uống nước đá đi nhé. Tớ đã ra hiệu thuốc mua thuốc và một bát cháo thịt cho cậu rồi.', 25) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr19_zh_exp_8', 'lesson-19', 'zh_to_vi', '嗯，我头很疼，还有点儿咳嗽、喉咙发炎。', '嗯，我头很疼，还有点儿咳嗽、喉咙发炎。', 'Ēn, wǒ tóu hěn téng, hái yǒudiǎnr késou, hóulong fāyán.', NULL, 'Ừ, tớ đau đầu quá, lại hơi ho và viêm họng nữa.', NULL, '["tớ","đau","đầu","quá","lại","hơi","ho","và","viêm","họng","nữa"]'::jsonb, 'Pinyin: Ēn, wǒ tóu hěn téng, hái yǒudiǎnr késou, hóulong fāyán.', '嗯，我头很疼，还有点儿咳嗽、喉咙发炎。 (Ēn, wǒ tóu hěn téng, hái yǒudiǎnr késou, hóulong fāyán.) nghĩa là: Ừ, tớ đau đầu quá, lại hơi ho và viêm họng nữa.', 26) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr19_zh_exp_9', 'lesson-19', 'zh_to_vi', '小兰，你脸色不太好，是不是感冒发烧了？', '小兰，你脸色不太好，是不是感冒发烧了？', 'Xiǎolán, nǐ liǎnsè bú tài hǎo, shì bu shì gǎnmào fāshāo le?', NULL, 'Tiểu Lan, sắc mặt cậu không tốt lắm, có phải bị cảm sốt rồi không?', NULL, '["tiểu","lan","sắc","mặt","cậu","không","tốt","lắm","có","phải","bị","cảm","sốt","rồi","không"]'::jsonb, 'Pinyin: Xiǎolán, nǐ liǎnsè bú tài hǎo, shì bu shì gǎnmào fāshāo le?', '小兰，你脸色不太好，是不是感冒发烧了？ (Xiǎolán, nǐ liǎnsè bú tài hǎo, shì bu shì gǎnmào fāshāo le?) nghĩa là: Tiểu Lan, sắc mặt cậu không tốt lắm, có phải bị cảm sốt rồi không?', 27) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
