INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct19_19', 'lesson-19', NULL, 'comprehensive_test', 'listening', '你还这样说！我现在去药店给你买药。对了， 听说感冒应该吃肉粥，这样很快就恢复了。我顺便给你买一碗粥吧！
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct19_20', 'lesson-19', NULL, 'comprehensive_test', 'listening', '嗯，我头很疼，还有点儿咳嗽、喉咙发炎。
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct19_21', 'lesson-19', NULL, 'comprehensive_test', 'listening', '好的！我现在有空儿，还能帮你做什么吗？
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct19_22', 'lesson-19', NULL, 'comprehensive_test', 'listening', '小兰，你脸色不太好，是不是感冒发烧了？ 嗯，我头很疼，还有点儿咳嗽、喉咙发炎。 你以后得戒除冰水了。我已经去药店给你买了药和一碗肉粥。 太谢谢你了，喝完粥吃药我一定会很快恢复！', NULL, 'Minh đã mua những gì cho Tiểu Lan khi cô ấy bị ốm?', '["Mua thuốc ở hiệu thuốc và một bát cháo thịt","Mua một cốc nước đá và trái cây","Mua vé đi du lịch","Mua sách và bút bi"]'::jsonb, 0, 'Minh nói ''我已经去药店给你买了药和一碗肉粥''.', 22) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
