INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v20_1', 'lesson-20', '身体', 'shēntǐ', 'thân thể', 'cơ thể', 'Danh từ', '身 (Thân) (Thân thể, vóc dáng)', '身: Bộ 身 (Thân - thân người đứng thẳng) • 体: 亻 (Nhân đứng: người) + 本 (Bản: gốc thân thể)', 'Ghép 身 [bộ 身] + 体 [bộ 亻] để nhớ từ 身体 (shēntǐ): "cơ thể".', '如果要减肥，你可以多锻炼身体。', 'Rúguǒ yào jiǎnféi, nǐ kěyǐ duō duànliàn shēntǐ.', 'Nếu muốn giảm cân, cậu có thể tập thể dục nhiều hơn', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v20_2', 'lesson-20', '疾病', 'jíbìng', 'bệnh', 'bệnh, bệnh tật,  đau ốm', 'Danh từ', '疒 (Nạch) (Bệnh tật, đau ốm, sức khỏe)', '疾: 疒 (Nạch: bệnh tật) + 矢 (Thỉ: mũi tên đâm nhanh) • 病: 疒 (Nạch: nằm giường bệnh) + 丙 (Bính)', 'Ghép 疾 [bộ 疒] + 病 [bộ 疒] để nhớ từ 疾病 (jíbìng): "bệnh, bệnh tật,  đau ốm".', '你这样对身体不好，也很容易生病。你得多多锻炼身体。锻炼身体还可以预防疾病。', 'Nǐ zhèyàng duì shēntǐ bù hǎo, yě hěn róngyì shēngbìng. Nǐ děi duōduō duànliàn shēntǐ. Duànliàn shēntǐ hái kěyǐ yùfáng jíbìng.', 'Cậu sống như vậy không tốt cho sức khỏe đâu, rất dễ bị ốm đấy. Cậu phải rèn luyện sức khỏe nhiều lên. Tập thể dục còn giúp phòng ngừa bệnh tật nữa.', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v20_3', 'lesson-20', '空气', 'kōngqì', 'khí', 'không khí', 'Danh từ', '穴 (Huyệt) (Hang động, khoảng trống, nơi ở)', '空: 穴 (Huyệt: hang trống) + 工 (Công: đào rỗng) • 气: Bộ 气 (Khí - làn hơi bốc lên, chữ độc thể)', 'Ghép 空 [bộ 穴] + 气 [bộ 气] để nhớ từ 空气 (kōngqì): "không khí".', '早上跑步不但可以享受新鲜的空气，而且对身体也有很多好处。', 'Zǎoshang pǎobù búdàn kěyǐ xiǎngshòu xīnxiān de kōngqì,  érqiě duì shēntǐ yě yǒu hěn duō hǎochu.', 'Chạy bộ buổi sáng không những được hít thở không khí trong lành mà còn có rất nhiều lợi ích cho sức khỏe.', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v20_4', 'lesson-20', '小时', 'xiǎoshí', 'tiểu thời', 'tiếng, giờ đồng hồ', 'Danh từ', '小 (Tiểu) (Nhỏ bé, ít ỏi)', '小: Bộ 小 (Tiểu - hạt cát nhỏ bé) • 时: 日 (Nhật: mặt trời) + 寸 (Thốn: đo thời gian)', 'Ghép 小 [bộ 小] + 时 [bộ 日] để nhớ từ 小时 (xiǎoshí): "tiếng, giờ đồng hồ".', '大概跑半个小时。', 'Dàgài pǎo bàn gè xiǎoshí.', 'Chạy khoảng nửa tiếng.', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v20_5', 'lesson-20', '好处', 'hǎochù', 'hảo', 'lợi ích', 'Danh từ', '女 (Nữ) (Phụ nữ, gia đình, tình cảm)', '好: 女 (Nữ: người mẹ) + 子 (Tử: đứa con) • 处: 夂 (Trĩ) + 卜 (Bốc)', 'Ghép 好 [bộ 女] + 处 [bộ 夂] để nhớ từ 好处 (hǎochù): "lợi ích".', '早上跑步不但可以享受新鲜的空气，而且对身体也有很多好处。', 'Zǎoshang pǎobù búdàn kěyǐ xiǎngshòu xīnxiān de kōngqì,  érqiě duì shēntǐ yě yǒu hěn duō hǎochu.', 'Chạy bộ buổi sáng không những được hít thở không khí trong lành mà còn có rất nhiều lợi ích cho sức khỏe.', 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v20_6', 'lesson-20', '体育馆', 'tǐyùguǎn', 'thể quán', 'cung thể thao', 'Danh từ', '人/亻 (Nhân) (Con người, nhân loại, hành động)', '体: 亻 (Nhân đứng: người) + 本 (Bản: gốc thân thể) • 育: 亠 + 厶 + 月 (Nhục: nuôi dưỡng con lớn lên) • 馆: 饣 (Thực) + 官 (Quan: nơi công cộng)', 'Ghép 体 [bộ 亻] + 育 [bộ 月] + 馆 [bộ 饣] để nhớ từ 体育馆 (tǐyùguǎn): "cung thể thao".', '对。每天下午我都去体育馆游泳，打篮球、打网球和武术。周末如果天气好我就跟几个朋友去爬山。我觉得你的身体太弱，可能是因为不经常锻炼身体。', 'Duì. Měi tiān xiàwǔ wǒ dōu qù tǐyùguǎn yóuyǒng, dǎ lánqiú, dǎ wǎngqiú hé wǔshù. Zhōumò rúguǒ tiānqì hǎo wǒ jiù gēn jǐ gè péngyou qù páshān. Wǒ juéde nǐ de shēntǐ tài ruò, kěnéng shì yīnwèi bù jīngcháng duànliàn shēntǐ.', 'Đúng vậy. Chiều nào mình cũng đến nhà thi đấu bơi lội, chơi bóng rổ, đánh tennis và tập võ. Cuối tuần nếu thời tiết đẹp mình đi leo núi cùng vài người bạn. Mình thấy sức khỏe cậu hơi yếu, có lẽ vì ít rèn luyện thể thao đấy.', 6) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v20_7', 'lesson-20', '篮球', 'lánqiú', 'cầu', 'Bóng rổ', 'Danh từ', '竹/⺮ (Trúc) (Tre trúc, đồ đan, sách vở)', '篮: ⺮ (Trúc: giỏ đan bằng tre) + 监 (Giám) • 球: 王 (Ngọc: quả cầu tròn như ngọc) + 求 (Cầu)', 'Ghép 篮 [bộ 竹] + 球 [bộ 王] để nhớ từ 篮球 (lánqiú): "Bóng rổ".', '对。每天下午我都去体育馆游泳，打篮球、打网球和武术。周末如果天气好我就跟几个朋友去爬山。我觉得你的身体太弱，可能是因为不经常锻炼身体。', 'Duì. Měi tiān xiàwǔ wǒ dōu qù tǐyùguǎn yóuyǒng, dǎ lánqiú, dǎ wǎngqiú hé wǔshù. Zhōumò rúguǒ tiānqì hǎo wǒ jiù gēn jǐ gè péngyou qù páshān. Wǒ juéde nǐ de shēntǐ tài ruò, kěnéng shì yīnwèi bù jīngcháng duànliàn shēntǐ.', 'Đúng vậy. Chiều nào mình cũng đến nhà thi đấu bơi lội, chơi bóng rổ, đánh tennis và tập võ. Cuối tuần nếu thời tiết đẹp mình đi leo núi cùng vài người bạn. Mình thấy sức khỏe cậu hơi yếu, có lẽ vì ít rèn luyện thể thao đấy.', 7) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v20_8', 'lesson-20', '网球', 'wǎngqiú', 'võng cầu', 'Tennis', 'Danh từ', '网/罒 (Võng) (Tấm lưới, che phủ)', '网: Bộ 网 (Võng - mắt lưới đan chéo) • 球: 王 (Ngọc: quả cầu tròn như ngọc) + 求 (Cầu)', 'Ghép 网 [bộ 网] + 球 [bộ 王] để nhớ từ 网球 (wǎngqiú): "Tennis".', '对。每天下午我都去体育馆游泳，打篮球、打网球和武术。周末如果天气好我就跟几个朋友去爬山。我觉得你的身体太弱，可能是因为不经常锻炼身体。', 'Duì. Měi tiān xiàwǔ wǒ dōu qù tǐyùguǎn yóuyǒng, dǎ lánqiú, dǎ wǎngqiú hé wǔshù. Zhōumò rúguǒ tiānqì hǎo wǒ jiù gēn jǐ gè péngyou qù páshān. Wǒ juéde nǐ de shēntǐ tài ruò, kěnéng shì yīnwèi bù jīngcháng duànliàn shēntǐ.', 'Đúng vậy. Chiều nào mình cũng đến nhà thi đấu bơi lội, chơi bóng rổ, đánh tennis và tập võ. Cuối tuần nếu thời tiết đẹp mình đi leo núi cùng vài người bạn. Mình thấy sức khỏe cậu hơi yếu, có lẽ vì ít rèn luyện thể thao đấy.', 8) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v20_9', 'lesson-20', '武术', 'wǔshù', 'từ Hán ngữ', 'võ thuật', 'Danh từ', '止 (Chỉ) (Dừng lại, bàn chân bước)', '武: 一 + 止 (Chỉ: dừng lại) + 弋 (Dặc: vũ khí dừng chiến) • 术: 木 (Mộc: cây cối) + 丶 (Chủ)', 'Ghép 武 [bộ 止] + 术 [bộ 木] để nhớ từ 武术 (wǔshù): "võ thuật".', '对。每天下午我都去体育馆游泳，打篮球、打网球和武术。周末如果天气好我就跟几个朋友去爬山。我觉得你的身体太弱，可能是因为不经常锻炼身体。', 'Duì. Měi tiān xiàwǔ wǒ dōu qù tǐyùguǎn yóuyǒng, dǎ lánqiú, dǎ wǎngqiú hé wǔshù. Zhōumò rúguǒ tiānqì hǎo wǒ jiù gēn jǐ gè péngyou qù páshān. Wǒ juéde nǐ de shēntǐ tài ruò, kěnéng shì yīnwèi bù jīngcháng duànliàn shēntǐ.', 'Đúng vậy. Chiều nào mình cũng đến nhà thi đấu bơi lội, chơi bóng rổ, đánh tennis và tập võ. Cuối tuần nếu thời tiết đẹp mình đi leo núi cùng vài người bạn. Mình thấy sức khỏe cậu hơi yếu, có lẽ vì ít rèn luyện thể thao đấy.', 9) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v20_10', 'lesson-20', '跑步', 'pǎobù', 'bào bộ', 'chạy bộ, chạy', 'Động từ', '足/⻊ (Túc) (Bàn chân, bước chân, đá bóng, chạy)', '跑: ⻊ (Túc: bàn chân) + 包 (Bao: chạy nhanh) • 步: 止 (Chỉ: bước chân trên) + 少 biến thể (bước chân dưới)', 'Ghép 跑 [bộ 足] + 步 [bộ 止] để nhớ từ 跑步 (pǎobù): "chạy bộ, chạy".', '阿明，我看你每天早上都跑步，你是不是常常锻炼身体？', 'Āmíng, wǒ kàn nǐ měi tiān zǎoshang dōu pǎobù, nǐ shì bu shì chángcháng duànliàn shēntǐ?', 'A Minh, mình thấy sáng nào cậu cũng chạy bộ, cậu có thường xuyên rèn luyện sức khỏe không?', 10) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v20_11', 'lesson-20', '锻炼', 'duànliàn', 'đoán luyện', 'tập luyện, tập', 'Động từ', '金/钅 (Kim) (Kim loại, tiền bạc, đồ dùng kim khí)', '锻: 钅 (Kim: rèn kim loại) + 段 (Đoạn) • 炼: 火 (Hỏa: lửa nung rèn luyện) + 东 biến thể', 'Ghép 锻 [bộ 钅] + 炼 [bộ 火] để nhớ từ 锻炼 (duànliàn): "tập luyện, tập".', '你得多锻炼了。', 'Nǐ děi duō duànliàn le.', 'Bạn cần phải luyện tập nhiều hơn nữa.', 11) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v20_12', 'lesson-20', '运动', 'yùndòng', 'từ Hán ngữ', 'vận động, hoạt động thể thao', 'Động từ / Danh từ', '辶 (Sước) (Bước đi, di chuyển, khoảng cách)', '运: 云 (Vân) + 辶 (Sước: di chuyển vận động) • 动: 云 (Vân) + 力 (Lực: dùng sức chuyển động)', 'Ghép 运 [bộ 辶] + 动 [bộ 力] để nhớ từ 运动 (yùndòng): "vận động, hoạt động thể thao".', '我看你的身体真棒。你一定很喜欢体育运动吧？', 'Wǒ kàn nǐ de shēntǐ zhēn bàng. Nǐ yídìng hěn xǐhuān tǐyù yùndòng ba?', 'Mình thấy thể lực của cậu tốt thật đấy. Chắc cậu rất thích thể dục thể thao nhỉ?', 12) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v20_13', 'lesson-20', '享受', 'xiǎngshòu', 'từ Hán ngữ', 'hưởng thụ', 'Động từ', '亠 (Đầu) (Nóc, đỉnh đầu)', '享: 亠 + 口 + 子 (dâng lễ hưởng thụ) • 受: 爫 (Trảo: tay đưa) + 冖 + 又 (Hựu: tay nhận lấy)', 'Ghép 享 [bộ 亠] + 受 [bộ 又] để nhớ từ 享受 (xiǎngshòu): "hưởng thụ".', '早上跑步不但可以享受新鲜的空气，而且对身体也有很多好处。', 'Zǎoshang pǎobù búdàn kěyǐ xiǎngshòu xīnxiān de kōngqì,  érqiě duì shēntǐ yě yǒu hěn duō hǎochu.', 'Chạy bộ buổi sáng không những được hít thở không khí trong lành mà còn có rất nhiều lợi ích cho sức khỏe.', 13) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v20_14', 'lesson-20', '预防', 'yùfáng', 'từ Hán ngữ', 'ngăn chặn, ngăn ngừa', 'Động từ', '页 (Hiệt) (Đầu mặt, trang giấy)', '预: 予 (Dư) + 页 (Hiệt: tính toán chuẩn bị trước) • 防: 阝 (Phụ: lũy đất phòng thủ) + 方 (Phương)', 'Ghép 预 [bộ 页] + 防 [bộ 阝] để nhớ từ 预防 (yùfáng): "ngăn chặn, ngăn ngừa".', '你这样对身体不好，也很容易生病。你得多多锻炼身体。锻炼身体还可以预防疾病。', 'Nǐ zhèyàng duì shēntǐ bù hǎo, yě hěn róngyì shēngbìng. Nǐ děi duōduō duànliàn shēntǐ. Duànliàn shēntǐ hái kěyǐ yùfáng jíbìng.', 'Cậu sống như vậy không tốt cho sức khỏe đâu, rất dễ bị ốm đấy. Cậu phải rèn luyện sức khỏe nhiều lên. Tập thể dục còn giúp phòng ngừa bệnh tật nữa.', 14) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v20_15', 'lesson-20', '起床', 'qǐchuáng', 'từ Hán ngữ', 'ngủ dậy, thức dậy', 'Động từ', '走 (Tẩu) (Chạy, đi lại, rời đi)', '起: 走 (Tẩu: bước chạy) + 己 (Kỷ: tự đứng dậy) • 床: 广 (Nghiễm: mái nhà) + 木 (Mộc: giường bằng gỗ)', 'Ghép 起 [bộ 走] + 床 [bộ 广] để nhớ từ 起床 (qǐchuáng): "ngủ dậy, thức dậy".', '早点儿睡吧，明天还要早点儿起床呢！', 'Zǎodiǎnr shuì ba, míngtiān hái yào zǎodiǎnr qǐchuáng ne!', 'Ngủ sớm đi, ngày mai còn phải dậy sớm nữa.', 15) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v20_16', 'lesson-20', '睡', 'shuì', 'từ Hán ngữ', 'ngủ', 'Động từ', '目 (Mục) (Con mắt, nhìn ngắm, thị giác)', '睡 = 目 (Mục: mắt nhắm rủ xuống) + 垂 (Thùy).', 'Chữ 睡 (shuì) mang nghĩa "ngủ", bộ chính 目 (Mục); cấu tạo: 目 (Mục: mắt nhắm rủ xuống) + 垂 (Thùy).', '早点儿睡吧，明天还要早点儿起床呢！', 'Zǎodiǎnr shuì ba, míngtiān hái yào zǎodiǎnr qǐchuáng ne!', 'Ngủ sớm đi, ngày mai còn phải dậy sớm nữa.', 16) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v20_17', 'lesson-20', '新鲜', 'xīnxiān', 'tân', 'tươi, trong lành, mới mẻ', 'Tính từ', '斤 (Cân) (Cái rìu, đơn vị cân nặng)', '新: 立 + 木 (Tân) + 斤 (Cân: rìu chặt gỗ mới) • 鲜: 鱼 (Ngư: cá) + 羊 (Dương: thịt dê tươi ngon)', 'Ghép 新 [bộ 斤] + 鲜 [bộ 鱼] để nhớ từ 新鲜 (xīnxiān): "tươi, trong lành, mới mẻ".', '早上跑步不但可以享受新鲜的空气，而且对身体也有很多好处。', 'Zǎoshang pǎobù búdàn kěyǐ xiǎngshòu xīnxiān de kōngqì,  érqiě duì shēntǐ yě yǒu hěn duō hǎochu.', 'Chạy bộ buổi sáng không những được hít thở không khí trong lành mà còn có rất nhiều lợi ích cho sức khỏe.', 17) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v20_18', 'lesson-20', '认真', 'rènzhēn', 'nhận', 'nghiêm túc, chăm chỉ, hẳn hoi', 'Tính từ', '言/讠 (Ngôn) (Lời nói, ngôn ngữ, giao tiếp)', '认: 讠 (Ngôn: lời nói) + 人 (Nhân: con người) • 真: 十 (Thập) + 目 (Mục) + 一 + 八 (mắt nhìn thật rõ)', 'Ghép 认 [bộ 讠] + 真 [bộ 目] để nhớ từ 认真 (rènzhēn): "nghiêm túc, chăm chỉ, hẳn hoi".', '你好认真啊！', 'Nǐ hǎo rènzhēn a!', 'Cậu chăm chỉ thật đấy!', 18) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v20_19', 'lesson-20', '坚持', 'jiānchí', 'từ Hán ngữ', 'kiên trì, giữ vững', 'Tính từ', '土 (Thổ) (Đất đai, vị trí, công trình)', '坚: 刂 + 又 + 土 (Thổ: nền đất cứng chắc) • 持: 扌 (Thủ: bàn tay giữ vững) + 寺 (Tự)', 'Ghép 坚 [bộ 土] + 持 [bộ 扌] để nhớ từ 坚持 (jiānchí): "kiên trì, giữ vững".', '我知道了，明天你跑步的时候能叫我吗？我决定要跟你一样坚持锻炼身体。', 'Wǒ zhīdào le, míngtiān nǐ pǎobù de shíhou néng jiào wǒ ma? Wǒ juédìng yào gēn nǐ yíyàng jiānchí duànliàn shēntǐ.', 'Mình biết rồi, ngày mai lúc đi chạy bộ cậu gọi mình với nhé? Mình quyết định sẽ kiên trì tập luyện giống cậu.', 19) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v20_20', 'lesson-20', '棒', 'bàng', 'từ Hán ngữ', 'khỏe, tốt', 'Tính từ', '木 (Mộc) (Cây cối, gỗ, thực vật)', '棒 = 木 (Mộc: gậy gỗ) + 奉 (Phụng: tuyệt vời, vững vàng).', 'Chữ 棒 (bàng) mang nghĩa "khỏe, tốt", bộ chính 木 (Mộc); cấu tạo: 木 (Mộc: gậy gỗ) + 奉 (Phụng: tuyệt vời, vững vàng).', '我看你的身体真棒。你一定很喜欢体育运动吧？', 'Wǒ kàn nǐ de shēntǐ zhēn bàng. Nǐ yídìng hěn xǐhuān tǐyù yùndòng ba?', 'Mình thấy thể lực của cậu tốt thật đấy. Chắc cậu rất thích thể dục thể thao nhỉ?', 20) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v20_21', 'lesson-20', '弱', 'ruò', 'từ Hán ngữ', 'yếu, yếu sức', 'Tính từ', '弓 (Cung) (Cây cung, độ căng, uốn cong)', '弱 = 弓 (Cung) + 冫 + 弓 (Cung) + 冫 (hai cây cung mềm yếu).', 'Chữ 弱 (ruò) mang nghĩa "yếu, yếu sức", bộ chính 弓 (Cung); cấu tạo: 弓 (Cung) + 冫 + 弓 (Cung) + 冫 (hai cây cung mềm yếu).', '对。每天下午我都去体育馆游泳，打篮球、打网球和武术。周末如果天气好我就跟几个朋友去爬山。我觉得你的身体太弱，可能是因为不经常锻炼身体。', 'Duì. Měi tiān xiàwǔ wǒ dōu qù tǐyùguǎn yóuyǒng, dǎ lánqiú, dǎ wǎngqiú hé wǔshù. Zhōumò rúguǒ tiānqì hǎo wǒ jiù gēn jǐ gè péngyou qù páshān. Wǒ juéde nǐ de shēntǐ tài ruò, kěnéng shì yīnwèi bù jīngcháng duànliàn shēntǐ.', 'Đúng vậy. Chiều nào mình cũng đến nhà thi đấu bơi lội, chơi bóng rổ, đánh tennis và tập võ. Cuối tuần nếu thời tiết đẹp mình đi leo núi cùng vài người bạn. Mình thấy sức khỏe cậu hơi yếu, có lẽ vì ít rèn luyện thể thao đấy.', 21) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v20_22', 'lesson-20', '健康', 'jiànkāng', 'kiện khang', 'khỏe mạnh, tráng kiện, sức khỏe', 'Tính từ / Danh từ', '人/亻 (Nhân) (Con người, nhân loại, hành động)', '健: 亻 (Nhân đứng: con người) + 建 (Kiến: vững mạnh) • 康: 广 (Nghiễm) + 隶 (Lệ: thóc gạo đầy đủ, khỏe mạnh)', 'Ghép 健 [bộ 亻] + 康 [bộ 广] để nhớ từ 健康 (jiànkāng): "khỏe mạnh, tráng kiện, sức khỏe".', '这是关于“健康”的常用句子。', 'Zhè shì guānyú ''jiànkāng'' de chángyòng jùzi.', 'Đây là câu ví dụ sử dụng từ ''健康'' (khỏe mạnh, tráng kiện, sức khỏe).', 22) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v20_23', 'lesson-20', '大概', 'dàgài', 'đại', 'đại khái, khoảng', 'Phó từ', '大 (Đại) (To lớn, vĩ đại)', '大: Bộ 大 (Đại - người dang rộng tay chân, chữ độc thể) • 概: 木 (Mộc: thanh gạt đong thóc) + 既 (Ký)', 'Ghép 大 [bộ 大] + 概 [bộ 木] để nhớ từ 大概 (dàgài): "đại khái, khoảng".', '大概跑半个小时。', 'Dàgài pǎo bàn gè xiǎoshí.', 'Chạy khoảng nửa tiếng.', 23) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v20_24', 'lesson-20', '得', 'děi', 'từ Hán ngữ', 'phải', 'Động từ năng nguyện', '彳 (Xích) (Bước chân trái, con đường, hành động)', '得 = 彳 (Xích: bước đi) + 旦 (Đán) + 寸 (Thốn: tay nắm được).', 'Chữ 得 (děi) mang nghĩa "phải", bộ chính 彳 (Xích); cấu tạo: 彳 (Xích: bước đi) + 旦 (Đán) + 寸 (Thốn: tay nắm được).', '你得多锻炼了。', 'Nǐ děi duō duànliàn le.', 'Bạn cần phải luyện tập nhiều hơn nữa.', 24) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v20_25', 'lesson-20', '可能', 'kěnéng', 'từ Hán ngữ', 'khả năng, có thể', 'Động từ năng nguyện', '口 (Khẩu) (Miệng, ăn uống, lời nói, âm thanh phát ra)', '可: 丁 (Đinh) + 口 (Khẩu: đồng ý) • 能: 厶 + 月 (Nhục) + 匕 + 匕 (gấu mạnh mẽ có khả năng)', 'Ghép 可 [bộ 口] + 能 [bộ 月] để nhớ từ 可能 (kěnéng): "khả năng, có thể".', '天可能要下雨。', 'Tiān kěnéng yào xià yǔ.', 'Trời có thể sắp mưa.', 25) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v20_26', 'lesson-20', '应该', 'yīnggāi', 'ứng', 'nên, có vẻ như', 'Động từ năng nguyện', '广 (Nghiễm) (Mái nhà rộng, nơi công cộng)', '应: 广 (Nghiễm) + ⺍ + 一 (ứng đáp) • 该: 讠 (Ngôn: lời nói) + 亥 (Hợi)', 'Ghép 应 [bộ 广] + 该 [bộ 讠] để nhớ từ 应该 (yīnggāi): "nên, có vẻ như".', '你应该多听，多说，多读，多写。', 'Nǐ yīnggāi duō tīng, duō shuō, duō dú, duō xiě.', 'Bạn nên nghe nhiều, nói nhiều, đọc nhiều và viết nhiều.', 26) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order) VALUES ('g20_1', 'lesson-20', '1. 多 + Động từ', 'Cấu trúc câu ngữ pháp trọng tâm', ' Nghĩa là làm gì đó nhiều hơn, mang sắc thái nghĩa tích cực. 你得多锻炼了。 Nǐ děi duō duànliàn le. Bạn cần phải luyện tập nhiều hơn nữa. 你应该多听，多说，多读，多写。 Nǐ yīnggāi duō tīng, duō shuō, duō dú, duō xiě. Bạn nên nghe nhiều, nói nhiều, đọc nhiều và viết nhiều.', NULL, '[{"hanzi":"你得多锻炼了。","pinyin":"Nǐ děi duō duànliàn le.","meaning":"Bạn cần phải luyện tập nhiều hơn nữa."},{"hanzi":"你应该多听，多说，多读，多写。","pinyin":"Nǐ yīnggāi duō tīng, duō shuō, duō dú, duō xiě.","meaning":"Bạn nên nghe nhiều, nói nhiều, đọc nhiều và viết nhiều."}]'::jsonb, 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order) VALUES ('g20_2', 'lesson-20', '2. Động từ năng nguyên', 'Cấu trúc câu ngữ pháp trọng tâm', 'Quy tắc ngữ pháp quan trọng trong Tập thể dục.', NULL, '[{"hanzi":"你是不是累了？多休息吧！","pinyin":"Nǐ shì bu shì lèi le? Duō xiūxi ba!","meaning":"Bạn mệt à? Nghỉ ngơi thêm chút đi!"},{"hanzi":"她会中文。","pinyin":"Tā huì Zhōngwén.","meaning":"Cô ấy biết tiếng Trung."}]'::jsonb, 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order) VALUES ('g20_3', 'lesson-20', '2.1. 会', 'Cấu trúc câu ngữ pháp trọng tâm', ' a) Sẽ, biểu thị sự việc xảy ra trong tương lai hoặc biểu thị lời hứa sẽ thực hiện 下次我会请你吃饭！ Xià cì wǒ huì qǐng nǐ chīfàn！ Lần sau tớ sẽ mời cậu đi ăn cơm! 你放心，明天我会准时来！ Nǐ fàngxīn, míngtiān wǒ huì zhǔnshí lái！ Cậu yên tâm, ngày mai tớ sẽ đến đúng giờ', NULL, '[{"hanzi":"我会打羽毛球。","pinyin":"Wǒ huì dǎ yǔmáoqiú.","meaning":"Tôi biết đánh cầu lông."},{"hanzi":"我可以做好这件事。","pinyin":"Wǒ kěyǐ zuò hǎo zhè jiàn shì.","meaning":"Tôi có thể làm tốt việc này"}]'::jsonb, 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order) VALUES ('g20_4', 'lesson-20', '2.2. 可以', 'Cấu trúc câu ngữ pháp trọng tâm', ' a) Có thể, biểu thị năng lực đạt đến một trình độ nhất định 我可以做好这件事。 Wǒ kěyǐ zuò hǎo zhè jiàn shì. Tôi có thể làm tốt việc này b) Có thể, biểu thị điều kiện khách quan cho phép thực hiện một việc gì đó 明天是国庆节，我们可以去买东西。 Míngtiān shì Guóqìng jié, wǒm', NULL, '[{"hanzi":"明天是国庆节，我们可以去买东西。","pinyin":"Míngtiān shì Guóqìng jié, wǒmen kěyǐ qù mǎi dōngxi.","meaning":"Ngày mai là lễ Quốc khánh, chúng ta có thể đi mua sắm."},{"hanzi":"妈妈，做完作业以后，我可以看电影吗？","pinyin":"Māma, zuò wán zuòyè yǐhòu, wǒ kěyǐ kàn diànyǐng ma?","meaning":"Mẹ ơi, sau khi làm xong bài tập về nhà con có thể xem phim không ạ?"}]'::jsonb, 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order;
INSERT INTO texts (id, lesson_id, title, description, sort_order) VALUES ('txt_20_1', 'lesson-20', 'Bài khoá #1: Hội thoại giáo trình — Tập thể dục', 'Hội thoại chuẩn giáo trình Bài 20. Từ vựng chưa học được chú thích phiên âm & nghĩa trong ngoặc.', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_20_1_1', 'txt_20_1', '安妮', '阿明，我看你每天早上都跑步，你是不是常常锻炼身体？', '阿明 (Āmíng: A Minh)，我看你每天 (tiān: ngày, trời)早上都跑步，你是不是常常锻炼身体？', 'Āmíng, wǒ kàn nǐ měi tiān zǎoshang dōu pǎobù, nǐ shì bu shì chángcháng duànliàn shēntǐ?', 'A Minh, mình thấy sáng nào cậu cũng chạy bộ, cậu có thường xuyên rèn luyện sức khỏe không?', 1) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_20_1_2', 'txt_20_1', '阮日明', '是。我每天早上六点都起来跑步。', '是。我每天 (tiān: ngày, trời)早上六点都起来 (qǐlái: lên (bổ ngữ))跑步。', 'Shì. Wǒ měitiān zǎoshang liù diǎn dōu qǐlai pǎobù.', 'Có. Sáng nào 6 giờ mình cũng dậy chạy bộ.', 2) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_20_1_3', 'txt_20_1', '安妮', '你每天跑多长时间？', '你每天 (tiān: ngày, trời)跑 (pǎo: chạy)多长 (cháng: dài)时间？', 'Nǐ měi tiān pǎo duō cháng shíjiān?', 'Mỗi ngày cậu chạy bao lâu?', 3) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_20_1_4', 'txt_20_1', '阮日明', '大概跑半个小时。', '大概跑 (pǎo: chạy)半个小时。', 'Dàgài pǎo bàn gè xiǎoshí.', 'Chạy khoảng nửa tiếng.', 4) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_20_1_5', 'txt_20_1', '安妮', '你好认真啊！', '你好认真啊！', 'Nǐ hǎo rènzhēn a!', 'Cậu chăm chỉ thật đấy!', 5) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_20_1_6', 'txt_20_1', '阮日明', '早上跑步不但可以享受新鲜的空气，而且对身体也有很多好处。', '早上跑步不但可以享受新鲜的空气，而且对身体也有很多好处。', 'Zǎoshang pǎobù búdàn kěyǐ xiǎngshòu xīnxiān de kōngqì,  érqiě duì shēntǐ yě yǒu hěn duō hǎochu.', 'Chạy bộ buổi sáng không những được hít thở không khí trong lành mà còn có rất nhiều lợi ích cho sức khỏe.', 6) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_20_1_7', 'txt_20_1', '安妮', '我看你的身体真棒。你一定很喜欢体育运动吧？', '我看你的身体真棒。你一定 (yīdìng: nhất định)很喜欢体育 (tǐyù: thể dục)运动吧？', 'Wǒ kàn nǐ de shēntǐ zhēn bàng. Nǐ yídìng hěn xǐhuān tǐyù yùndòng ba?', 'Mình thấy thể lực của cậu tốt thật đấy. Chắc cậu rất thích thể dục thể thao nhỉ?', 7) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_20_1_8', 'txt_20_1', '阮日明', '对。每天下午我都去体育馆游泳，打篮球、打网球和武术。周末如果天气好我就跟几个朋友去爬山。我觉得你的身体太弱，可能是因为不经常锻炼身体。', '对。每天 (tiān: ngày, trời)下午我都去体育馆游泳，打 (dǎ: đánh, gọi, chơi)篮球、打网球和武术。周末如果天气好我就跟 (gēn: cùng, với)几个朋友去爬山。我觉得你的身体太弱，可能是因为不经常锻炼身体。', 'Duì. Měi tiān xiàwǔ wǒ dōu qù tǐyùguǎn yóuyǒng, dǎ lánqiú, dǎ wǎngqiú hé wǔshù. Zhōumò rúguǒ tiānqì hǎo wǒ jiù gēn jǐ gè péngyou qù páshān. Wǒ juéde nǐ de shēntǐ tài ruò, kěnéng shì yīnwèi bù jīngcháng duànliàn shēntǐ.', 'Đúng vậy. Chiều nào mình cũng đến nhà thi đấu bơi lội, chơi bóng rổ, đánh tennis và tập võ. Cuối tuần nếu thời tiết đẹp mình đi leo núi cùng vài người bạn. Mình thấy sức khỏe cậu hơi yếu, có lẽ vì ít rèn luyện thể thao đấy.', 8) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_20_1_9', 'txt_20_1', '安妮', '我每天都晚睡晚起，也不太喜欢体育运动。', '我每天 (tiān: ngày, trời)都晚 (wǎn: muộn, tối)睡晚起 (wǎnqǐ: dậy muộn)，也不太喜欢体育 (tǐyù: thể dục)运动。', 'Wǒ měitiān dōu wǎn shuì wǎn qǐ, yě bú tài xǐhuan tǐyù yùndòng.', 'Ngày nào mình cũng thức khuya dậy muộn, lại không thích vận động thể thao lắm.', 9) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_20_1_10', 'txt_20_1', '阮日明', '你这样对身体不好，也很容易生病。你得多多锻炼身体。锻炼身体还可以预防疾病。', '你这样对身体不好，也很容易生病。你得多多锻炼身体。锻炼身体还可以预防疾病。', 'Nǐ zhèyàng duì shēntǐ bù hǎo, yě hěn róngyì shēngbìng. Nǐ děi duōduō duànliàn shēntǐ. Duànliàn shēntǐ hái kěyǐ yùfáng jíbìng.', 'Cậu sống như vậy không tốt cho sức khỏe đâu, rất dễ bị ốm đấy. Cậu phải rèn luyện sức khỏe nhiều lên. Tập thể dục còn giúp phòng ngừa bệnh tật nữa.', 10) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_20_1_11', 'txt_20_1', '安妮', '我知道了，明天你跑步的时候能叫我吗？我决定要跟你一样坚持锻炼身体。', '我知道了，明天你跑步的时候能叫我吗？我决定要跟 (gēn: cùng, với)你一样坚持锻炼身体。', 'Wǒ zhīdào le, míngtiān nǐ pǎobù de shíhou néng jiào wǒ ma? Wǒ juédìng yào gēn nǐ yíyàng jiānchí duànliàn shēntǐ.', 'Mình biết rồi, ngày mai lúc đi chạy bộ cậu gọi mình với nhé? Mình quyết định sẽ kiên trì tập luyện giống cậu.', 11) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_20_1_12', 'txt_20_1', '阮日明', '好啊！', '好啊！', 'Hǎo a!', 'Được chứ!', 12) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_20_1_1', 'lesson-20', 'txt_20_1', 'listening', 'listening', '阿明，我看你每天早上都跑步，你是不是常常锻炼身体？', NULL, 'Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Bây giờ cậu cảm thấy thế nào?","A Minh, mình thấy sáng nào cậu cũng chạy bộ, cậu có thường xuyên rèn luyện sức khỏe không?","Các thầy cô giáo","Cậu mua mấy quả dưa hấu thế?"]'::jsonb, 1, 'Nội dung nghe được: 阿明，我看你每天早上都跑步，你是不是常常锻炼身体？ (Āmíng, wǒ kàn nǐ měi tiān zǎoshang dōu pǎobù, nǐ shì bu shì chángcháng duànliàn shēntǐ?) → A Minh, mình thấy sáng nào cậu cũng chạy bộ, cậu có thường xuyên rèn luyện sức khỏe không?', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_20_1_2', 'lesson-20', 'txt_20_1', 'listening', 'listening', '是。我每天早上六点都起来跑步。', NULL, 'Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["是。我每天 (tiān: ngày, trời)早上六点都起来 (qǐlái: lên (bổ ngữ))跑步。","阿明 (Āmíng: A Minh)，我看你每天 (tiān: ngày, trời)早上都跑步，你是不是常常锻炼身体？","她会中文 (Zhōngwén: tiếng Trung)。","我要学 (xué: học)游泳。"]'::jsonb, 0, 'Câu vừa đọc: 是。我每天早上六点都起来跑步。 (Shì. Wǒ měitiān zǎoshang liù diǎn dōu qǐlai pǎobù.) → Có. Sáng nào 6 giờ mình cũng dậy chạy bộ.', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_20_1_3', 'lesson-20', 'txt_20_1', 'listening', 'listening', '你每天跑多长时间？', NULL, 'Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Mỗi ngày cậu chạy bao lâu?","Tôi không hay (không thường) liên lạc với Lý Quân.","Ngủ sớm dậy sớm là một thói quen sinh hoạt rất tốt.","Hội nghị này, cậu đi hay Minh đi?"]'::jsonb, 0, 'Nội dung nghe được: 你每天跑多长时间？ (Nǐ měi tiān pǎo duō cháng shíjiān?) → Mỗi ngày cậu chạy bao lâu?', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_20_1_4', 'lesson-20', 'txt_20_1', 'listening', 'listening', '大概跑半个小时。', NULL, 'Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["我可以做 (zuò: làm)好这件 (jiàn: cái, chiếc (áo, việc))事。","如果要减肥 (jiǎnféi: giảm cân)，你可以多锻炼身体。","大概跑 (pǎo: chạy)半个小时。","明天我想去图书馆看书。"]'::jsonb, 2, 'Câu vừa đọc: 大概跑半个小时。 (Dàgài pǎo bàn gè xiǎoshí.) → Chạy khoảng nửa tiếng.', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO texts (id, lesson_id, title, description, sort_order) VALUES ('txt_20_2', 'lesson-20', 'Bài nghe tổng hợp: Ôn tập lũy tiến (Bài 1 – Bài 20)', 'Kết hợp từ vựng & mẫu câu đã học từ Bài 1 đến Bài 19 cùng trọng tâm Bài 20 để củng cố phản xạ nghe.', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_20_2_1', 'txt_20_2', 'Ôn Bài 19', '今天会下雨吧。', '今天会下雨吧。', 'Jīntiān huì xià yǔ ba.', 'Hôm nay chắc sẽ mưa đấy nhỉ.', 1) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_20_2_2', 'txt_20_2', 'Bài 20', '你得多锻炼了。', '你得多锻炼了。', 'Nǐ děi duō duànliàn le.', 'Bạn cần phải luyện tập nhiều hơn nữa.', 2) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
