INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_20_2_4', 'txt_20_2', 'Bài 20', '你是不是累了？多休息吧！', '你是不是累了？多休息吧！', 'Nǐ shì bu shì lèi le? Duō xiūxi ba!', 'Bạn mệt à? Nghỉ ngơi thêm chút đi!', 4) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_20_2_5', 'txt_20_2', 'Ôn Bài 1', '老师们', '老师们', 'lǎoshīmen', 'Các thầy cô giáo', 5) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_20_2_6', 'txt_20_2', 'Bài 20', '明天我想去图书馆看书。', '明天我想去图书馆看书。', 'Míngtiān wǒ xiǎng qù túshū guǎn kànshū.', 'Ngày mai tôi muốn đi thư viện đọc sách.', 6) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_20_2_7', 'txt_20_2', 'Ôn Bài 18', '她会说汉语。', '她会说汉语。', 'Tā huì shuō Hànyǔ.', 'Cô ấy biết nói tiếng Trung.', 7) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_20_2_8', 'txt_20_2', 'Bài 20', '你好认真啊！', '你好认真啊！', 'Nǐ hǎo rènzhēn a!', 'Cậu chăm chỉ thật đấy!', 8) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_20_2_1', 'lesson-20', 'txt_20_2', 'listening', 'listening', '今天会下雨吧。', NULL, '[Ôn tập Bài 19] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Cậu nói gì vậy?","tóc dài (mang sự dễ thương)","Hôm nay chắc sẽ mưa đấy nhỉ.","Không phải hôm qua chúng ta đã gặp nhau rồi sao? (Khẳng định hôm"]'::jsonb, 2, 'Nội dung nghe được: 今天会下雨吧。 (Jīntiān huì xià yǔ ba.) → Hôm nay chắc sẽ mưa đấy nhỉ.', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_20_2_2', 'lesson-20', 'txt_20_2', 'listening', 'listening', '你得多锻炼了。', NULL, '[Bài 20] Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["天 (tiān: ngày, trời)可能要下雨。","坚持运动可以帮助我们预防很多疾病。","你得多锻炼了。","你每天 (tiān: ngày, trời)几点起床去学 (xué: học)武术？"]'::jsonb, 2, 'Câu vừa đọc: 你得多锻炼了。 (Nǐ děi duō duànliàn le.) → Bạn cần phải luyện tập nhiều hơn nữa.', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_20_2_3', 'lesson-20', 'txt_20_2', 'listening', 'listening', '天气太舒服了！', NULL, '[Ôn tập Bài 10] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Thời tiết dễ chịu quá!","Cậu có biết chữ này viết như thế nào không?","Tháng sau anh ấy mới về nước.","Tớ biết bơi, còn biết trượt băng."]'::jsonb, 0, 'Nội dung nghe được: 天气太舒服了！ (Tiānqì tài shūfu le!) → Thời tiết dễ chịu quá!', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_20_2_4', 'lesson-20', 'txt_20_2', 'listening', 'listening', '你是不是累了？多休息吧！', NULL, '[Bài 20] Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["是。我每天 (tiān: ngày, trời)早上六点都起来 (qǐlái: lên (bổ ngữ))跑步。","你是不是累了？多休息吧！","中 (zhōng: giữa / trong)学生不可以抽烟 (chōuyān: hút thuốc)。","她会中文 (Zhōngwén: tiếng Trung)。"]'::jsonb, 1, 'Câu vừa đọc: 你是不是累了？多休息吧！ (Nǐ shì bu shì lèi le? Duō xiūxi ba!) → Bạn mệt à? Nghỉ ngơi thêm chút đi!', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_20_2_5', 'lesson-20', 'txt_20_2', 'listening', 'listening', '老师们', NULL, '[Ôn tập Bài 1] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Các thầy cô giáo","Anh ấy đã về nước từ tuần trước rồi.","Hiệu sách ở bên phải rất lớn.","Cậu mua mấy quả dưa hấu thế?"]'::jsonb, 0, 'Nội dung nghe được: 老师们 (lǎoshīmen) → Các thầy cô giáo', 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO texts (id, lesson_id, title, description, sort_order) VALUES ('txt_20_3', 'lesson-20', 'Bài khoá mở rộng: Thói quen rèn luyện thể thao (Mở rộng)', 'Hội thoại tình huống mới xây dựng dựa trên từ vựng và ngữ pháp Bài 20 (không trùng lặp nguyên văn giáo trình).', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_20_3_1', 'txt_20_3', 'Mark', '阿明，你每天几点起床锻炼身体？', '阿明 (Āmíng: A Minh)，你每天 (tiān: ngày, trời)几点起床锻炼身体？', 'Āmíng, nǐ měitiān jǐ diǎn qǐchuáng duànliàn shēntǐ?', 'A Minh, mỗi ngày mấy giờ cậu thức dậy rèn luyện sức khỏe?', 1) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_20_3_2', 'txt_20_3', 'A Minh', '我每天早上六点起床去公园跑步，下午去体育馆打篮球或武术。', '我每天 (tiān: ngày, trời)早上六点起床去公园跑步，下午去体育馆打 (dǎ: đánh, gọi, chơi)篮球或武术。', 'Wǒ měitiān zǎoshang liù diǎn qǐchuáng qù gōngyuán pǎobù, xiàwǔ qù tǐyùguǎn dǎ lánqiú huò wǔshù.', 'Sáng nào 6 giờ mình cũng dậy ra công viên chạy bộ, chiều đến nhà thi đấu chơi bóng rổ hoặc tập võ.', 2) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_20_3_3', 'txt_20_3', 'Mark', '坚持运动真的有很多好处吗？', '坚持运动真的有很多好处吗？', 'Jiānchí yùndòng zhēn de yǒu hěnduō hǎochu ma?', 'Kiên trì vận động thực sự có nhiều lợi ích vậy sao?', 3) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_20_3_4', 'txt_20_3', 'A Minh', '当然，不仅让人精神好，还能预防疾病呢！', '当然，不仅让 (ràng: bảo, khiến)人精神好，还能预防疾病呢！', 'Dāngrán, bùjǐn ràng rén jīngshen hǎo, hái néng yùfáng jíbìng ne!', 'Tất nhiên rồi, không chỉ giúp tinh thần minh mẫn mà còn phòng ngừa bệnh tật nữa đấy!', 4) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_20_3_1', 'lesson-20', 'txt_20_3', 'listening', 'listening', '阿明，你每天几点起床锻炼身体？ 我每天早上六点起床去公园跑步，下午去体育馆打篮球或武术。 坚持运动真的有很多好处吗？ 当然，不仅让人精神好，还能预防疾病呢！', NULL, '[Nghe hiểu tình huống mới] Theo A Minh, buổi sáng cậu ấy tập môn thể thao gì và ở đâu?', '["Ngủ nướng đến trưa","Đá bóng trên sân thượng","Chạy bộ ở công viên lúc 6 giờ sáng","Chơi tennis trong ký túc xá"]'::jsonb, 2, 'A Minh trả lời ''每天早上六点起床去公园跑步''.', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_20_3_2', 'lesson-20', 'txt_20_3', 'listening', 'listening', '阿明，你每天几点起床锻炼身体？', NULL, '[Mở rộng] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Một cái ghế","Tôi đợi các bạn ở cổng trường.","A Minh, mỗi ngày mấy giờ cậu thức dậy rèn luyện sức khỏe?","Tôi vừa nghe nhạc vừa đọc sách."]'::jsonb, 2, 'Nội dung nghe được: 阿明，你每天几点起床锻炼身体？ (Āmíng, nǐ měitiān jǐ diǎn qǐchuáng duànliàn shēntǐ?) → A Minh, mỗi ngày mấy giờ cậu thức dậy rèn luyện sức khỏe?', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_20_3_3', 'lesson-20', 'txt_20_3', 'listening', 'listening', '我每天早上六点起床去公园跑步，下午去体育馆打篮球或武术。', NULL, '[Mở rộng] Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["你得多锻炼了。","我喜欢在公园一边 (biān: bên, phía)锻炼一边享受新鲜空气。","我每天 (tiān: ngày, trời)早上六点起床去公园跑步，下午去体育馆打 (dǎ: đánh, gọi, chơi)篮球或武术。","妈妈，做完 (zuòwán: làm xong)作业以后 (yǐhòu: sau, lúc sau)，我可以看电影吗？"]'::jsonb, 2, 'Câu vừa đọc: 我每天早上六点起床去公园跑步，下午去体育馆打篮球或武术。 (Wǒ měitiān zǎoshang liù diǎn qǐchuáng qù gōngyuán pǎobù, xiàwǔ qù tǐyùguǎn dǎ lánqiú huò wǔshù.) → Sáng nào 6 giờ mình cũng dậy ra công viên chạy bộ, chiều đến nhà thi đấu chơi bóng rổ hoặc tập võ.', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_20_3_4', 'lesson-20', 'txt_20_3', 'listening', 'listening', '坚持运动真的有很多好处吗？', NULL, '[Mở rộng] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Kiên trì vận động thực sự có nhiều lợi ích vậy sao?","Tôi không biết người này là nam hay là nữ nữa.","Hình như tớ quen người này.","Anh ta không cho tôi đi."]'::jsonb, 0, 'Nội dung nghe được: 坚持运动真的有很多好处吗？ (Jiānchí yùndòng zhēn de yǒu hěnduō hǎochu ma?) → Kiên trì vận động thực sự có nhiều lợi ích vậy sao?', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss20_1', 'lesson-20', '下午我去体育馆打篮球和打网球', '[Mở rộng] Buổi chiều tôi đến nhà thi đấu chơi bóng rổ và đánh tennis.', 'Xiàwǔ wǒ qù tǐyùguǎn dǎ lánqiú hé dǎ wǎngqiú.', '["下午","我去","体育馆","打篮球","和打","网球"]'::jsonb, 'Từ chưa học: 打 (dǎ: đánh, gọi, chơi)', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss20_2', 'lesson-20', '你每天几点起床去学武术', '[Mở rộng] Mỗi ngày mấy giờ bạn thức dậy đi học võ thuật?', 'Nǐ měitiān jǐ diǎn qǐchuáng qù xué wǔshù?', '["你每","天几","点","起床","去学","武术"]'::jsonb, 'Từ chưa học: 天 (tiān: ngày, trời), 学 (xué: học)', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss20_3', 'lesson-20', '你得多锻炼了', 'Bạn cần phải luyện tập nhiều hơn nữa.', 'Nǐ děi duō duànliàn le.', '["你","得","多","锻炼","了"]'::jsonb, NULL, 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss20_4', 'lesson-20', '明天我想去图书馆看书', 'Ngày mai tôi muốn đi thư viện đọc sách.', 'Míngtiān wǒ xiǎng qù túshū guǎn kànshū.', '["明天","我想","去","图书馆","看","书"]'::jsonb, NULL, 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss20_5', 'lesson-20', '谢谢你经常在学习上帮助我', '[Ôn tập Bài 16] Cảm ơn bạn thường xuyên giúp đỡ tôi trong việc học.', 'Xièxie nǐ jīngcháng zài xuéxí shàng bāngzhù wǒ.', '["谢谢你","经常在","学习","上","帮助","我"]'::jsonb, 'Từ chưa học: 上 (shàng: trên / lên), 学习 (xuéxí: học tập)', 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss20_6', 'lesson-20', '我喜欢一边喝水一边听音乐', '[Ôn tập Bài 12] Tôi thích vừa uống nước vừa nghe nhạc.', 'Wǒ xǐhuan yìbiān hē shuǐ yìbiān tīng yīnyuè.', '["我","喜欢","一边","喝水","一边","听音乐"]'::jsonb, 'Từ chưa học: 边 (biān: bên, phía)', 6) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss20_exp_1', 'lesson-20', '阿明我看你每天早上都跑步你是不是常常锻炼身体', 'A Minh, mình thấy sáng nào cậu cũng chạy bộ, cậu có thường xuyên rèn luyện sức khỏe không?', 'Āmíng, wǒ kàn nǐ měi tiān zǎoshang dōu pǎobù, nǐ shì bu shì chángcháng duànliàn shēntǐ?', '["阿","明","我","看","你","每","天","早上","都","跑步","你","是","不是","常常","锻炼","身体"]'::jsonb, NULL, 7) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss20_exp_2', 'lesson-20', '是我每天早上六点都起来跑步', 'Có. Sáng nào 6 giờ mình cũng dậy chạy bộ.', 'Shì. Wǒ měitiān zǎoshang liù diǎn dōu qǐlai pǎobù.', '["是","我","每","天","早上","六","点","都","起","来","跑步"]'::jsonb, NULL, 8) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss20_exp_3', 'lesson-20', '你每天跑多长时间', 'Mỗi ngày cậu chạy bao lâu?', 'Nǐ měi tiān pǎo duō cháng shíjiān?', '["你","每","天","跑","多","长","时间"]'::jsonb, NULL, 9) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss20_exp_4', 'lesson-20', '大概跑半个小时', 'Chạy khoảng nửa tiếng.', 'Dàgài pǎo bàn gè xiǎoshí.', '["大概","跑","半","个","小时"]'::jsonb, NULL, 10) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss20_exp_5', 'lesson-20', '你好认真啊', 'Cậu chăm chỉ thật đấy!', 'Nǐ hǎo rènzhēn a!', '["你好","认真","啊"]'::jsonb, NULL, 11) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss20_exp_6', 'lesson-20', '早上跑步不但可以享受新鲜的空气而且对身体也有很多好处', 'Chạy bộ buổi sáng không những được hít thở không khí trong lành mà còn có rất nhiều lợi ích cho sức khỏe.', 'Zǎoshang pǎobù búdàn kěyǐ xiǎngshòu xīnxiān de kōngqì, érqiě duì shēntǐ yě yǒu hěn duō hǎochu.', '["早上","跑步","不","但","可以","享受","新鲜","的","空气","而","且","对","身体","也","有","很","多","好处"]'::jsonb, NULL, 12) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss20_exp_7', 'lesson-20', '我看你的身体真棒你一定很喜欢体育运动吧', 'Mình thấy thể lực của cậu tốt thật đấy. Chắc cậu rất thích thể dục thể thao nhỉ?', 'Wǒ kàn nǐ de shēntǐ zhēn bàng. Nǐ yídìng hěn xǐhuān tǐyù yùndòng ba?', '["我","看","你","的","身体","真","棒","你","一","定","很","喜欢","体","育","运动","吧"]'::jsonb, NULL, 13) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss20_exp_8', 'lesson-20', '对每天下午我都去体育馆游泳打篮球打网球和武术周末如果天气好我就跟几个朋友去爬山我觉得你的身体太弱可能是因为不经常锻炼身体', 'Đúng vậy. Chiều nào mình cũng đến nhà thi đấu bơi lội, chơi bóng rổ, đánh tennis và tập võ. Cuối tuần nếu thời tiết đẹp mình đi leo núi cùng vài người bạn. Mình thấy sức khỏe cậu hơi yếu, có lẽ vì ít rèn luyện thể thao đấy.', 'Duì. Měi tiān xiàwǔ wǒ dōu qù tǐyùguǎn yóuyǒng, dǎ lánqiú, dǎ wǎngqiú hé wǔshù. Zhōumò rúguǒ tiānqì hǎo wǒ jiù gēn jǐ gè péngyou qù páshān. Wǒ juéde nǐ de shēntǐ tài ruò, kěnéng shì yīnwèi bù jīngcháng duànliàn shēntǐ.', '["对","每","天","下午","我","都","去","体育馆","游泳","打","篮球","打","网球","和","武术","周末","如果","天气","好","我","就","跟","几","个","朋友","去","爬山","我","觉得","你","的","身体","太","弱","可能","是","因为","不","经常","锻炼","身体"]'::jsonb, NULL, 14) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss20_exp_9', 'lesson-20', '我每天都晚睡晚起也不太喜欢体育运动', 'Ngày nào mình cũng thức khuya dậy muộn, lại không thích vận động thể thao lắm.', 'Wǒ měitiān dōu wǎn shuì wǎn qǐ, yě bú tài xǐhuan tǐyù yùndòng.', '["我","每","天","都","晚","睡","晚","起","也","不","太","喜欢","体","育","运动"]'::jsonb, NULL, 15) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss20_exp_10', 'lesson-20', '你这样对身体不好也很容易生病你得多多锻炼身体锻炼身体还可以预防疾病', 'Cậu sống như vậy không tốt cho sức khỏe đâu, rất dễ bị ốm đấy. Cậu phải rèn luyện sức khỏe nhiều lên. Tập thể dục còn giúp phòng ngừa bệnh tật nữa.', 'Nǐ zhèyàng duì shēntǐ bù hǎo, yě hěn róngyì shēngbìng. Nǐ děi duōduō duànliàn shēntǐ. Duànliàn shēntǐ hái kěyǐ yùfáng jíbìng.', '["你","这样","对","身体","不","好","也","很","容易","生病","你","得","多","多","锻炼","身体","锻炼","身体","还","可以","预防","疾病"]'::jsonb, NULL, 16) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss20_exp_11', 'lesson-20', '我知道了明天你跑步的时候能叫我吗我决定要跟你一样坚持锻炼身体', 'Mình biết rồi, ngày mai lúc đi chạy bộ cậu gọi mình với nhé? Mình quyết định sẽ kiên trì tập luyện giống cậu.', 'Wǒ zhīdào le, míngtiān nǐ pǎobù de shíhou néng jiào wǒ ma? Wǒ juédìng yào gēn nǐ yíyàng jiānchí duànliàn shēntǐ.', '["我","知道","了","明天","你","跑步","的","时候","能","叫","我","吗","我","决定","要","跟","你","一样","坚持","锻炼","身体"]'::jsonb, NULL, 17) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss20_exp_12', 'lesson-20', '今天会下雨吧', 'Hôm nay chắc sẽ mưa đấy nhỉ.', 'Jīntiān huì xià yǔ ba.', '["今天","会","下雨","吧"]'::jsonb, NULL, 18) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss20_exp_13', 'lesson-20', '天气太舒服了', 'Thời tiết dễ chịu quá!', 'Tiānqì tài shūfu le!', '["天气","太","舒服","了"]'::jsonb, NULL, 19) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss20_exp_14', 'lesson-20', '你是不是累了多休息吧', 'Bạn mệt à? Nghỉ ngơi thêm chút đi!', 'Nǐ shì bu shì lèi le? Duō xiūxi ba!', '["你","是","不是","累","了","多","休息","吧"]'::jsonb, NULL, 20) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr20_vi_1', 'lesson-20', 'vi_to_zh', '[Mở rộng] Kiên trì vận động có thể giúp chúng ta phòng ngừa nhiều bệnh tật.', NULL, NULL, '坚持运动可以帮助我们预防很多疾病。', NULL, 'jiānchí yùndòng kěyǐ bāngzhù wǒmen yùfáng hěnduō jíbìng', '[]'::jsonb, 'Gợi ý Pinyin: Jiānchí yùndòng kěyǐ bāngzhù wǒmen yùfáng hěnduō jíbìng.', 'Kiên trì vận động có thể giúp chúng ta phòng ngừa nhiều bệnh tật. → 坚持运动可以帮助我们预防很多疾病。 (Jiānchí yùndòng kěyǐ bāngzhù wǒmen yùfáng hěnduō jíbìng.)', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr20_vi_2', 'lesson-20', 'vi_to_zh', '[Mở rộng] Sáng nào cũng chạy bộ nửa tiếng rất tốt cho sức khỏe.', NULL, NULL, '每天早上跑步半个小时对身体有很多好处。', NULL, 'měitiān zǎoshang pǎobù bàn gè xiǎoshí duì shēntǐ yǒu hěnduō hǎochu', '[]'::jsonb, 'Gợi ý Pinyin: Měitiān zǎoshang pǎobù bàn gè xiǎoshí duì shēntǐ yǒu hěnduō hǎochu. | Từ chưa học: 天 (tiān: ngày, trời)', 'Sáng nào cũng chạy bộ nửa tiếng rất tốt cho sức khỏe. → 每天早上跑步半个小时对身体有很多好处。 (Měitiān zǎoshang pǎobù bàn gè xiǎoshí duì shēntǐ yǒu hěnduō hǎochu.)', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr20_vi_3', 'lesson-20', 'vi_to_zh', 'Bạn cần phải luyện tập nhiều hơn nữa.', NULL, NULL, '你得多锻炼了。', NULL, 'nǐ děi duō duànliàn le', '[]'::jsonb, 'Gợi ý Pinyin: Nǐ děi duō duànliàn le.', 'Bạn cần phải luyện tập nhiều hơn nữa. → 你得多锻炼了。 (Nǐ děi duō duànliàn le.)', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr20_vi_4', 'lesson-20', 'vi_to_zh', 'Bạn mệt à? Nghỉ ngơi thêm chút đi!', NULL, NULL, '你是不是累了？多休息吧！', NULL, 'nǐ shì bu shì lèi le duō xiūxi ba', '[]'::jsonb, 'Gợi ý Pinyin: Nǐ shì bu shì lèi le? Duō xiūxi ba!', 'Bạn mệt à? Nghỉ ngơi thêm chút đi! → 你是不是累了？多休息吧！ (Nǐ shì bu shì lèi le? Duō xiūxi ba!)', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr20_vi_exp_1', 'lesson-20', 'vi_to_zh', 'A Minh, mình thấy sáng nào cậu cũng chạy bộ, cậu có thường xuyên rèn luyện sức khỏe không?', NULL, NULL, '阿明，我看你每天早上都跑步，你是不是常常锻炼身体？', NULL, 'āmíng wǒ kàn nǐ měi tiān zǎoshang dōu pǎobù nǐ shì bu shì chángcháng duànliàn shēntǐ', '[]'::jsonb, 'Gợi ý Pinyin: Āmíng, wǒ kàn nǐ měi tiān zǎoshang dōu pǎobù, nǐ shì bu shì chángcháng duànliàn shēntǐ?', 'A Minh, mình thấy sáng nào cậu cũng chạy bộ, cậu có thường xuyên rèn luyện sức khỏe không? → 阿明，我看你每天早上都跑步，你是不是常常锻炼身体？ (Āmíng, wǒ kàn nǐ měi tiān zǎoshang dōu pǎobù, nǐ shì bu shì chángcháng duànliàn shēntǐ?)', 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr20_vi_exp_2', 'lesson-20', 'vi_to_zh', 'Có. Sáng nào 6 giờ mình cũng dậy chạy bộ.', NULL, NULL, '是。我每天早上六点都起来跑步。', NULL, 'shì wǒ měitiān zǎoshang liù diǎn dōu qǐlai pǎobù', '[]'::jsonb, 'Gợi ý Pinyin: Shì. Wǒ měitiān zǎoshang liù diǎn dōu qǐlai pǎobù.', 'Có. Sáng nào 6 giờ mình cũng dậy chạy bộ. → 是。我每天早上六点都起来跑步。 (Shì. Wǒ měitiān zǎoshang liù diǎn dōu qǐlai pǎobù.)', 6) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr20_vi_exp_3', 'lesson-20', 'vi_to_zh', 'Mỗi ngày cậu chạy bao lâu?', NULL, NULL, '你每天跑多长时间？', NULL, 'nǐ měi tiān pǎo duō cháng shíjiān', '[]'::jsonb, 'Gợi ý Pinyin: Nǐ měi tiān pǎo duō cháng shíjiān?', 'Mỗi ngày cậu chạy bao lâu? → 你每天跑多长时间？ (Nǐ měi tiān pǎo duō cháng shíjiān?)', 7) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr20_vi_exp_4', 'lesson-20', 'vi_to_zh', 'Chạy khoảng nửa tiếng.', NULL, NULL, '大概跑半个小时。', NULL, 'dàgài pǎo bàn gè xiǎoshí', '[]'::jsonb, 'Gợi ý Pinyin: Dàgài pǎo bàn gè xiǎoshí.', 'Chạy khoảng nửa tiếng. → 大概跑半个小时。 (Dàgài pǎo bàn gè xiǎoshí.)', 8) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr20_vi_exp_5', 'lesson-20', 'vi_to_zh', 'Cậu chăm chỉ thật đấy!', NULL, NULL, '你好认真啊！', NULL, 'nǐ hǎo rènzhēn a', '[]'::jsonb, 'Gợi ý Pinyin: Nǐ hǎo rènzhēn a!', 'Cậu chăm chỉ thật đấy! → 你好认真啊！ (Nǐ hǎo rènzhēn a!)', 9) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr20_vi_exp_6', 'lesson-20', 'vi_to_zh', 'Chạy bộ buổi sáng không những được hít thở không khí trong lành mà còn có rất nhiều lợi ích cho sức khỏe.', NULL, NULL, '早上跑步不但可以享受新鲜的空气，而且对身体也有很多好处。', NULL, 'zǎoshang pǎobù búdàn kěyǐ xiǎngshòu xīnxiān de kōngqì érqiě duì shēntǐ yě yǒu hěn duō hǎochu', '[]'::jsonb, 'Gợi ý Pinyin: Zǎoshang pǎobù búdàn kěyǐ xiǎngshòu xīnxiān de kōngqì, érqiě duì shēntǐ yě yǒu hěn duō hǎochu.', 'Chạy bộ buổi sáng không những được hít thở không khí trong lành mà còn có rất nhiều lợi ích cho sức khỏe. → 早上跑步不但可以享受新鲜的空气，而且对身体也有很多好处。 (Zǎoshang pǎobù búdàn kěyǐ xiǎngshòu xīnxiān de kōngqì, érqiě duì shēntǐ yě yǒu hěn duō hǎochu.)', 10) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr20_vi_exp_7', 'lesson-20', 'vi_to_zh', 'Mình thấy thể lực của cậu tốt thật đấy. Chắc cậu rất thích thể dục thể thao nhỉ?', NULL, NULL, '我看你的身体真棒。你一定很喜欢体育运动吧？', NULL, 'wǒ kàn nǐ de shēntǐ zhēn bàng nǐ yídìng hěn xǐhuān tǐyù yùndòng ba', '[]'::jsonb, 'Gợi ý Pinyin: Wǒ kàn nǐ de shēntǐ zhēn bàng. Nǐ yídìng hěn xǐhuān tǐyù yùndòng ba?', 'Mình thấy thể lực của cậu tốt thật đấy. Chắc cậu rất thích thể dục thể thao nhỉ? → 我看你的身体真棒。你一定很喜欢体育运动吧？ (Wǒ kàn nǐ de shēntǐ zhēn bàng. Nǐ yídìng hěn xǐhuān tǐyù yùndòng ba?)', 11) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr20_vi_exp_8', 'lesson-20', 'vi_to_zh', 'Đúng vậy. Chiều nào mình cũng đến nhà thi đấu bơi lội, chơi bóng rổ, đánh tennis và tập võ. Cuối tuần nếu thời tiết đẹp mình đi leo núi cùng vài người bạn. Mình thấy sức khỏe cậu hơi yếu, có lẽ vì ít rèn luyện thể thao đấy.', NULL, NULL, '对。每天下午我都去体育馆游泳，打篮球、打网球和武术。周末如果天气好我就跟几个朋友去爬山。我觉得你的身体太弱，可能是因为不经常锻炼身体。', NULL, 'duì měi tiān xiàwǔ wǒ dōu qù tǐyùguǎn yóuyǒng dǎ lánqiú dǎ wǎngqiú hé wǔshù zhōumò rúguǒ tiānqì hǎo wǒ jiù gēn jǐ gè péngyou qù páshān wǒ juéde nǐ de shēntǐ tài ruò kěnéng shì yīnwèi bù jīngcháng duànliàn shēntǐ', '[]'::jsonb, 'Gợi ý Pinyin: Duì. Měi tiān xiàwǔ wǒ dōu qù tǐyùguǎn yóuyǒng, dǎ lánqiú, dǎ wǎngqiú hé wǔshù. Zhōumò rúguǒ tiānqì hǎo wǒ jiù gēn jǐ gè péngyou qù páshān. Wǒ juéde nǐ de shēntǐ tài ruò, kěnéng shì yīnwèi bù jīngcháng duànliàn shēntǐ.', 'Đúng vậy. Chiều nào mình cũng đến nhà thi đấu bơi lội, chơi bóng rổ, đánh tennis và tập võ. Cuối tuần nếu thời tiết đẹp mình đi leo núi cùng vài người bạn. Mình thấy sức khỏe cậu hơi yếu, có lẽ vì ít rèn luyện thể thao đấy. → 对。每天下午我都去体育馆游泳，打篮球、打网球和武术。周末如果天气好我就跟几个朋友去爬山。我觉得你的身体太弱，可能是因为不经常锻炼身体。 (Duì. Měi tiān xiàwǔ wǒ dōu qù tǐyùguǎn yóuyǒng, dǎ lánqiú, dǎ wǎngqiú hé wǔshù. Zhōumò rúguǒ tiānqì hǎo wǒ jiù gēn jǐ gè péngyou qù páshān. Wǒ juéde nǐ de shēntǐ tài ruò, kěnéng shì yīnwèi bù jīngcháng duànliàn shēntǐ.)', 12) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr20_vi_exp_9', 'lesson-20', 'vi_to_zh', 'Ngày nào mình cũng thức khuya dậy muộn, lại không thích vận động thể thao lắm.', NULL, NULL, '我每天都晚睡晚起，也不太喜欢体育运动。', NULL, 'wǒ měitiān dōu wǎn shuì wǎn qǐ yě bú tài xǐhuan tǐyù yùndòng', '[]'::jsonb, 'Gợi ý Pinyin: Wǒ měitiān dōu wǎn shuì wǎn qǐ, yě bú tài xǐhuan tǐyù yùndòng.', 'Ngày nào mình cũng thức khuya dậy muộn, lại không thích vận động thể thao lắm. → 我每天都晚睡晚起，也不太喜欢体育运动。 (Wǒ měitiān dōu wǎn shuì wǎn qǐ, yě bú tài xǐhuan tǐyù yùndòng.)', 13) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr20_vi_exp_10', 'lesson-20', 'vi_to_zh', 'Cậu sống như vậy không tốt cho sức khỏe đâu, rất dễ bị ốm đấy. Cậu phải rèn luyện sức khỏe nhiều lên. Tập thể dục còn giúp phòng ngừa bệnh tật nữa.', NULL, NULL, '你这样对身体不好，也很容易生病。你得多多锻炼身体。锻炼身体还可以预防疾病。', NULL, 'nǐ zhèyàng duì shēntǐ bù hǎo yě hěn róngyì shēngbìng nǐ děi duōduō duànliàn shēntǐ duànliàn shēntǐ hái kěyǐ yùfáng jíbìng', '[]'::jsonb, 'Gợi ý Pinyin: Nǐ zhèyàng duì shēntǐ bù hǎo, yě hěn róngyì shēngbìng. Nǐ děi duōduō duànliàn shēntǐ. Duànliàn shēntǐ hái kěyǐ yùfáng jíbìng.', 'Cậu sống như vậy không tốt cho sức khỏe đâu, rất dễ bị ốm đấy. Cậu phải rèn luyện sức khỏe nhiều lên. Tập thể dục còn giúp phòng ngừa bệnh tật nữa. → 你这样对身体不好，也很容易生病。你得多多锻炼身体。锻炼身体还可以预防疾病。 (Nǐ zhèyàng duì shēntǐ bù hǎo, yě hěn róngyì shēngbìng. Nǐ děi duōduō duànliàn shēntǐ. Duànliàn shēntǐ hái kěyǐ yùfáng jíbìng.)', 14) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr20_zh_1', 'lesson-20', 'zh_to_vi', '[Mở rộng] 我喜欢在公园一边 (biān: bên, phía)锻炼一边享受新鲜空气。', '我喜欢在公园一边锻炼一边享受新鲜空气。', 'Wǒ xǐhuan zài gōngyuán yìbiān duànliàn yìbiān xiǎngshòu xīnxiān kōngqì.', NULL, 'Tôi thích vừa tập thể dục vừa hít thở không khí trong lành ở công viên.', NULL, '["Tôi","thích","vừa"]'::jsonb, 'Pinyin: Wǒ xǐhuan zài gōngyuán yìbiān duànliàn yìbiān xiǎngshòu xīnxiān kōngqì.', '我喜欢在公园一边锻炼一边享受新鲜空气。 (Wǒ xǐhuan zài gōngyuán yìbiān duànliàn yìbiān xiǎngshòu xīnxiān kōngqì.) nghĩa là: Tôi thích vừa tập thể dục vừa hít thở không khí trong lành ở công viên.', 15) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr20_zh_2', 'lesson-20', 'zh_to_vi', '[Mở rộng] 下午我去体育馆打 (dǎ: đánh, gọi, chơi)篮球和打网球。', '下午我去体育馆打篮球和打网球。', 'Xiàwǔ wǒ qù tǐyùguǎn dǎ lánqiú hé dǎ wǎngqiú.', NULL, 'Buổi chiều tôi đến nhà thi đấu chơi bóng rổ và đánh tennis.', NULL, '["Buổi","chiều","tôi"]'::jsonb, 'Pinyin: Xiàwǔ wǒ qù tǐyùguǎn dǎ lánqiú hé dǎ wǎngqiú.', '下午我去体育馆打篮球和打网球。 (Xiàwǔ wǒ qù tǐyùguǎn dǎ lánqiú hé dǎ wǎngqiú.) nghĩa là: Buổi chiều tôi đến nhà thi đấu chơi bóng rổ và đánh tennis.', 16) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
