INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr20_zh_exp_2', 'lesson-20', 'zh_to_vi', '早点儿睡吧，明天还要早点儿起床呢！', '早点儿睡吧，明天还要早点儿起床呢！', 'Zǎodiǎnr shuì ba, míngtiān hái yào zǎodiǎnr qǐchuáng ne!', NULL, 'Ngủ sớm đi, ngày mai còn phải dậy sớm nữa.', NULL, '["ngủ","sớm","đi","ngày","mai","còn","phải","dậy","sớm","nữa"]'::jsonb, 'Pinyin: Zǎodiǎnr shuì ba, míngtiān hái yào zǎodiǎnr qǐchuáng ne!', '早点儿睡吧，明天还要早点儿起床呢！ (Zǎodiǎnr shuì ba, míngtiān hái yào zǎodiǎnr qǐchuáng ne!) nghĩa là: Ngủ sớm đi, ngày mai còn phải dậy sớm nữa.', 20) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
