INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr20_zh_exp_4', 'lesson-20', 'zh_to_vi', '妈妈，做完作业以后，我可以看电影吗？', '妈妈，做完作业以后，我可以看电影吗？', 'Māma, zuò wán zuòyè yǐhòu, wǒ kěyǐ kàn diànyǐng ma?', NULL, 'Mẹ ơi, sau khi làm xong bài tập về nhà con có thể xem phim không ạ?', NULL, '["mẹ","ơi","sau","khi","làm","xong","bài","tập","về","nhà","con","có","thể","xem","phim","không"]'::jsonb, 'Pinyin: Māma, zuò wán zuòyè yǐhòu, wǒ kěyǐ kàn diànyǐng ma?', '妈妈，做完作业以后，我可以看电影吗？ (Māma, zuò wán zuòyè yǐhòu, wǒ kěyǐ kàn diànyǐng ma?) nghĩa là: Mẹ ơi, sau khi làm xong bài tập về nhà con có thể xem phim không ạ?', 22) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr20_zh_exp_5', 'lesson-20', 'zh_to_vi', '明天是国庆节，我们可以去买东西。', '明天是国庆节，我们可以去买东西。', 'Míngtiān shì Guóqìng jié, wǒmen kěyǐ qù mǎi dōngxi.', NULL, 'Ngày mai là lễ Quốc khánh, chúng ta có thể đi mua sắm.', NULL, '["ngày","mai","là","lễ","quốc","khánh","chúng","ta","có","thể","đi","mua","sắm"]'::jsonb, 'Pinyin: Míngtiān shì Guóqìng jié, wǒmen kěyǐ qù mǎi dōngxi.', '明天是国庆节，我们可以去买东西。 (Míngtiān shì Guóqìng jié, wǒmen kěyǐ qù mǎi dōngxi.) nghĩa là: Ngày mai là lễ Quốc khánh, chúng ta có thể đi mua sắm.', 23) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
