INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr20_zh_exp_10', 'lesson-20', 'zh_to_vi', '当然，不仅让人精神好，还能预防疾病呢！', '当然，不仅让人精神好，还能预防疾病呢！', 'Dāngrán, bùjǐn ràng rén jīngshen hǎo, hái néng yùfáng jíbìng ne!', NULL, 'Tất nhiên rồi, không chỉ giúp tinh thần minh mẫn mà còn phòng ngừa bệnh tật nữa đấy!', NULL, '["tất","nhiên","rồi","không","chỉ","giúp","tinh","thần","minh","mẫn","mà","còn","phòng","ngừa","bệnh","tật","nữa","đấy"]'::jsonb, 'Pinyin: Dāngrán, bùjǐn ràng rén jīngshen hǎo, hái néng yùfáng jíbìng ne!', '当然，不仅让人精神好，还能预防疾病呢！ (Dāngrán, bùjǐn ràng rén jīngshen hǎo, hái néng yùfáng jíbìng ne!) nghĩa là: Tất nhiên rồi, không chỉ giúp tinh thần minh mẫn mà còn phòng ngừa bệnh tật nữa đấy!', 28) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
