INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq20_13', 'lesson-20', NULL, 'expanded_quiz', 'radical', NULL, NULL, 'Chữ Hán “身体” chứa bộ thủ nào sau đây?', '["囗 (Vi) (Vây quanh, không gian kín, lãnh thổ)","无 (Vô) (Không có, phủ định)","禾 (Hòa) (Cây lúa, ngũ cốc, thời vụ)","身 (Thân) (Thân thể, vóc dáng)"]'::jsonb, 3, 'Chữ “身体” có bộ chính 身 (Thân) (Thân thể, vóc dáng). Chiết tự: 身: Bộ 身 (Thân - thân người đứng thẳng) • 体: 亻 (Nhân đứng: người) + 本 (Bản: gốc thân thể)', 13) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq20_14', 'lesson-20', NULL, 'expanded_quiz', 'radical', NULL, NULL, 'Chữ Hán “疾病” chứa bộ thủ nào sau đây?', '["疒 (Nạch) (Bệnh tật, đau ốm, sức khỏe)","竹/⺮ (Trúc) (Tre trúc, đồ đan, sách vở)","门 (Môn) (Cánh cửa, lối ra vào)","冖 (Mịch) (Khăn phủ, mái che)"]'::jsonb, 0, 'Chữ “疾病” có bộ chính 疒 (Nạch) (Bệnh tật, đau ốm, sức khỏe). Chiết tự: 疾: 疒 (Nạch: bệnh tật) + 矢 (Thỉ: mũi tên đâm nhanh) • 病: 疒 (Nạch: nằm giường bệnh) + 丙 (Bính)', 14) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq20_15', 'lesson-20', NULL, 'expanded_quiz', 'radical', NULL, NULL, 'Chữ Hán “空气” chứa bộ thủ nào sau đây?', '["音 (Âm) (Âm thanh, tiếng vang)","匕 (Chủy) (Cái thìa, dao găm)","戈 (Qua) (Cây giáo, vũ khí, chiến tranh)","穴 (Huyệt) (Hang động, khoảng trống, nơi ở)"]'::jsonb, 3, 'Chữ “空气” có bộ chính 穴 (Huyệt) (Hang động, khoảng trống, nơi ở). Chiết tự: 空: 穴 (Huyệt: hang trống) + 工 (Công: đào rỗng) • 气: Bộ 气 (Khí - làn hơi bốc lên, chữ độc thể)', 15) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq20_16', 'lesson-20', NULL, 'expanded_quiz', 'radical', NULL, NULL, 'Chữ Hán “小时” chứa bộ thủ nào sau đây?', '["小 (Tiểu) (Nhỏ bé, ít ỏi)","斤 (Cân) (Cái rìu, đơn vị cân nặng)","示/礻 (Thị) (Thần linh, nghi lễ, tỏ bày)","酉 (Dậu) (Bình rượu, lên men, chưng cất)"]'::jsonb, 0, 'Chữ “小时” có bộ chính 小 (Tiểu) (Nhỏ bé, ít ỏi). Chiết tự: 小: Bộ 小 (Tiểu - hạt cát nhỏ bé) • 时: 日 (Nhật: mặt trời) + 寸 (Thốn: đo thời gian)', 16) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
