INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct20_45', 'lesson-20', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ Hán tự “可能” (khả năng, có thể) có phiên âm Pinyin đúng là gì?', '["jièshào","shì","xià yǔ","kěnéng"]'::jsonb, 3, '“可能” đọc là “kěnéng”, nghĩa là: khả năng, có thể.', 45) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
