INSERT INTO lessons (id, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id) VALUES ('lesson-21', 'Bài 21: Kiểm tra sức khoẻ - Đơn nguyên 6: Sức khoẻ', 'Bài 21', 'Đơn nguyên 6: Sức khoẻ', 'Khám sức khỏe định kỳ, bảo hiểm y tế, chỉ số sức khỏe và tổng kết đơn nguyên 6.', '2026-11-14'::date, 21, TRUE, NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, date_added = EXCLUDED.date_added, sort_order = EXCLUDED.sort_order, is_system = TRUE, updated_at = NOW();
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v21_1', 'lesson-21', '医院', 'yīyuàn', 'y viện', 'bệnh viện', 'Danh từ', '匚 (Phương) (Hộp đựng, vật chứa)', '医: 匚 (Phương: hộp đựng dụng cụ) + 矢 (Thỉ: mũi tên chữa thương) • 院: 阝 (Phụ: tường thành) + 完 (Hoàn: khu nhà khép kín)', 'Ghép 医 [bộ 匚] + 院 [bộ 阝] để nhớ từ 医院 (yīyuàn): "bệnh viện".', '马克，我下午想去医院检查身体， 你可以陪我去吗？', 'Mǎkè, wǒ xiàwǔ xiǎng qù yīyuàn jiǎnchá shēntǐ, nǐ kěyǐ péi wǒ qù ma?', 'Mark, chiều nay tôi muốn đi bệnh viện kiểm tra sức khỏe, bạn đi cùng tôi được không?', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v21_2', 'lesson-21', '医生', 'yīshēng', 'y sinh', 'bác sĩ', 'Danh từ', '匚 (Phương) (Hộp đựng, vật chứa)', '医: 匚 (Phương: hộp đựng dụng cụ) + 矢 (Thỉ: mũi tên chữa thương) • 生: Bộ 生 (Sinh - mầm cây nảy từ đất, chữ độc thể)', 'Ghép 医 [bộ 匚] + 生 [bộ 生] để nhớ từ 医生 (yīshēng): "bác sĩ".', '那现在怎么治病呢, 医生？', 'Nà xiànzài zěnme zhì bìng ne, yīshēng?', 'Vậy bây giờ điều trị thế nào ạ, thưa bác sĩ?', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v21_3', 'lesson-21', '护士', 'hùshi', 'từ Hán ngữ', 'y tá, hộ sĩ', 'Danh từ', '手/扌 (Thủ) (Bàn tay, động tác, thao tác)', '护: 扌 (Thủ: bàn tay) + 户 (Hộ: che chở bảo vệ) • 士: Bộ 士 (Sĩ - nét trên dài hơn nét dưới, người có học)', 'Ghép 护 [bộ 扌] + 士 [bộ 士] để nhớ từ 护士 (hùshi): "y tá, hộ sĩ".', '其实没有什么要紧的。 我让护士给你打个针并开给你一个处方，你回家吃完饭再吃药和多喝水，过几天身体就恢复了。', 'Qíshí méiyǒu shénme yàojǐn de. Wǒ ràng hùshì gěi nǐ dǎ gè zhēn bìng kāi gěi nǐ yí gè chǔfāng, nǐ huí jiā chī wán fàn zài chī yào hé duō hē shuǐ, guò jǐ tiān shēntǐ jiù huīfù le.', 'Thực ra không có gì nghiêm trọng đâu. Tôi bảo y tá tiêm cho bạn một mũi và kê đơn thuốc, bạn về nhà ăn cơm xong uống thuốc và uống nhiều nước, vài ngày sau sức khỏe sẽ hồi phục thôi.', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v21_4', 'lesson-21', '病人', 'bìngrén', 'bệnh nhân', 'bệnh nhân', 'Danh từ', '疒 (Nạch) (Bệnh tật, đau ốm, sức khỏe)', '病: 疒 (Nạch: nằm giường bệnh) + 丙 (Bính) • 人: Bộ 人 (Nhân - dáng người đứng bước, chữ độc thể)', 'Ghép 病 [bộ 疒] + 人 [bộ 人] để nhớ từ 病人 (bìngrén): "bệnh nhân".', '大多数病人都买医疗保险，它很重要，你应该买一个!', 'Dàduōshù bìngrén dōu mǎi yīliáo bǎoxiǎn, tā hěn zhòngyào, nǐ yīnggāi mǎi yígè!', 'Đa số bệnh nhân đều mua bảo hiểm y tế, nó rất quan trọng, bạn nên mua một cái nhé!', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v21_5', 'lesson-21', '医疗保险', 'yīliáo bǎoxiǎn', 'y', 'bảo hiểm y tế', 'Danh từ', '匚 (Phương) (Hộp đựng, vật chứa)', '医: 匚 (Phương: hộp đựng dụng cụ) + 矢 (Thỉ: mũi tên chữa thương) • 疗: 疒 (Nạch: bệnh tật) + 了 (Liễu: chữa cho khỏi) • 保: 亻 (Nhân đứng: người lớn) + 呆 (bồng ẵm bảo vệ) • 险: 阝 (Phụ: vách núi hiểm trở) + 佥 (Thiêm)', 'Ghép 医 [bộ 匚] + 疗 [bộ 疒] + 保 [bộ 亻] + 险 [bộ 阝] để nhớ từ 医疗保险 (yīliáo bǎoxiǎn): "bảo hiểm y tế".', '对了，你有没有医疗保险？如果有的话就可以减少检查费用。', 'Duì le, nǐ yǒu méiyǒu yīliáo bǎoxiǎn? Rúguǒ yǒu de huà jiù kěyǐ jiǎnshǎo jiǎnchá fèiyòng.', 'À đúng rồi, bạn có bảo hiểm y tế không? Nếu có thì có thể giảm bớt chi phí khám bệnh đấy.', 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v21_6', 'lesson-21', '费用', 'fèiyòng', 'từ Hán ngữ', 'chi phí', 'Danh từ', '贝 (Bối) (Vỏ sò, tiền bạc, giá trị)', '费: 弗 (Phất) + 贝 (Bối: tiêu tốn tiền bạc) • 用: Bộ 用 (Dụng - chiếc gàu/đồ dùng có ích)', 'Ghép 费 [bộ 贝] + 用 [bộ 用] để nhớ từ 费用 (fèiyòng): "chi phí".', '对了，你有没有医疗保险？如果有的话就可以减少检查费用。', 'Duì le, nǐ yǒu méiyǒu yīliáo bǎoxiǎn? Rúguǒ yǒu de huà jiù kěyǐ jiǎnshǎo jiǎnchá fèiyòng.', 'À đúng rồi, bạn có bảo hiểm y tế không? Nếu có thì có thể giảm bớt chi phí khám bệnh đấy.', 6) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v21_7', 'lesson-21', '胃口', 'wèikǒu', 'khẩu', 'ăn uống, khẩu vị', 'Danh từ', '月 (Nguyệt/Nhục) (Mặt trăng hoặc các bộ phận thân thể người)', '胃: 田 (Điền: túi chứa thức ăn) + 月 (Nhục: cơ quan dạ dày) • 口: Bộ 口 (Khẩu - hình cái miệng mở, chữ độc thể)', 'Ghép 胃 [bộ 月] + 口 [bộ 口] để nhớ từ 胃口 (wèikǒu): "ăn uống, khẩu vị".', '我经常觉得头晕，吃什么都过敏。 最近胃口和睡眠都不好。', 'Wǒ jīngcháng juéde tóuyūn, chī shénme dōu guòmǐn. Zuìjìn wèikǒu hé shuìmián dōu bù hǎo.', 'Tôi hay bị chóng mặt, ăn gì cũng bị dị ứng. Dạo này ăn uống và giấc ngủ đều kém.', 7) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v21_8', 'lesson-21', '睡眠', 'shuìmián', 'từ Hán ngữ', 'giấc ngủ', 'Danh từ', '目 (Mục) (Con mắt, nhìn ngắm, thị giác)', '睡: 目 (Mục: mắt nhắm rủ xuống) + 垂 (Thùy) • 眠: 目 (Mục: mắt nhắm) + 民 (Dân: ngủ yên)', 'Ghép 睡 [bộ 目] + 眠 [bộ 目] để nhớ từ 睡眠 (shuìmián): "giấc ngủ".', '我经常觉得头晕，吃什么都过敏。 最近胃口和睡眠都不好。', 'Wǒ jīngcháng juéde tóuyūn, chī shénme dōu guòmǐn. Zuìjìn wèikǒu hé shuìmián dōu bù hǎo.', 'Tôi hay bị chóng mặt, ăn gì cũng bị dị ứng. Dạo này ăn uống và giấc ngủ đều kém.', 8) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v21_9', 'lesson-21', '重病', 'zhòngbìng', 'bệnh', 'trọng bệnh, bệnh nặng', 'Danh từ', '里 (Lý) (Làng xóm, bên trong, dặm đường)', '重: 千 (Thiên) + 里 (Lý: nặng nề, trùng lặp) • 病: 疒 (Nạch: nằm giường bệnh) + 丙 (Bính)', 'Ghép 重 [bộ 里] + 病 [bộ 疒] để nhớ từ 重病 (zhòngbìng): "trọng bệnh, bệnh nặng".', '我是不是得了重病？', 'Wǒ shì bu shì dé le zhòngbìng?', 'Có phải tôi mắc bệnh nặng rồi không?', 9) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v21_10', 'lesson-21', '症状', 'zhèngzhuàng', 'từ Hán ngữ', 'triệu chứng', 'Danh từ', '疒 (Nạch) (Bệnh tật, đau ốm, sức khỏe)', '症: 疒 (Nạch: bệnh) + 正 (Chính: triệu chứng bệnh) • 状: 丬 + 犬 (Khuyển: hình dáng, trạng thái)', 'Ghép 症 [bộ 疒] + 状 [bộ 犬] để nhớ từ 症状 (zhèngzhuàng): "triệu chứng".', '你有什么症状？', 'Nǐ yǒu shénme zhèngzhuàng?', 'Bạn có triệu chứng gì?', 10) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v21_11', 'lesson-21', '头晕', 'tóuyūn', 'từ Hán ngữ', 'chóng mặt', 'Tính từ', '日 (Nhật) (Mặt trời, ban ngày, thời gian, ánh sáng)', '头: 丷 + 大 (Đại: phần đầu phía trên) • 晕: 日 (Nhật: mặt trời chói) + 军 (Quân: quay cuồng chóng mặt)', 'Ghép 头 [bộ 大] + 晕 [bộ 日] để nhớ từ 头晕 (tóuyūn): "chóng mặt".', '我经常觉得头晕，吃什么都过敏。 最近胃口和睡眠都不好。', 'Wǒ jīngcháng juéde tóuyūn, chī shénme dōu guòmǐn. Zuìjìn wèikǒu hé shuìmián dōu bù hǎo.', 'Tôi hay bị chóng mặt, ăn gì cũng bị dị ứng. Dạo này ăn uống và giấc ngủ đều kém.', 11) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v21_12', 'lesson-21', '过敏', 'guòmǐn', 'từ Hán ngữ', 'dị ứng', 'Động từ', '攴/攵 (Phộc) (Đánh khẽ, hành động, dạy dỗ)', '过: 寸 (Thốn) + 辶 (Sước: bước đi qua) • 敏: 每 (Mỗi) + 攵 (Phộc: phản ứng nhanh nhạy)', 'Ghép 过 [bộ 辶] + 敏 [bộ 攵] để nhớ từ 过敏 (guòmǐn): "dị ứng".', '我经常觉得头晕，吃什么都过敏。 最近胃口和睡眠都不好。', 'Wǒ jīngcháng juéde tóuyūn, chī shénme dōu guòmǐn. Zuìjìn wèikǒu hé shuìmián dōu bù hǎo.', 'Tôi hay bị chóng mặt, ăn gì cũng bị dị ứng. Dạo này ăn uống và giấc ngủ đều kém.', 12) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v21_13', 'lesson-21', '最近', 'zuìjìn', 'từ Hán ngữ', 'gần đây', 'Phó từ', '日 (Nhật) (Mặt trời, ban ngày, thời gian, ánh sáng)', '最: 日 (Nhật) + 取 (Thủ: đoạt giải nhất) • 近: 斤 (Cân) + 辶 (Sước: đi lại gần)', 'Ghép 最 [bộ 日] + 近 [bộ 辶] để nhớ từ 最近 (zuìjìn): "gần đây".', '是的，最近觉得身体不太好，所以想去医院看看得了什么病。', 'Shì de, zuìjìn juéde shēntǐ bù tài hǎo, suǒyǐ xiǎng qù yīyuàn kànkan déle shénme bìng.', 'Đúng vậy, dạo này thấy người không khỏe lắm, nên muốn đi bệnh viện khám xem bị bệnh gì.', 13) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v21_14', 'lesson-21', '看病', 'kànbìng', 'khán bệnh', 'khám bệnh', 'Động từ', '目 (Mục) (Con mắt, nhìn ngắm, thị giác)', '看: 手 (Thủ biến thể: tay che trán) + 目 (Mục: mắt nhìn) • 病: 疒 (Nạch: nằm giường bệnh) + 丙 (Bính)', 'Ghép 看 [bộ 目] + 病 [bộ 疒] để nhớ từ 看病 (kànbìng): "khám bệnh".', '好的。 我陪你去看病。', 'Hǎo de. Wǒ péi nǐ qù kànbìng.', 'Được thôi. Tôi sẽ đi khám bệnh cùng bạn.', 14) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v21_15', 'lesson-21', '检查', 'jiǎnchá', 'tra', 'kiểm tra', 'Động từ', '木 (Mộc) (Cây cối, gỗ, thực vật)', '检: 木 (Mộc: hòm thẻ gỗ kiểm tra) + 佥 (Thiêm) • 查: 木 (Mộc) + 旦 (Đán: rà soát kiểm tra)', 'Ghép 检 [bộ 木] + 查 [bộ 木] để nhớ từ 检查 (jiǎnchá): "kiểm tra".', '马克，我下午想去医院检查身体， 你可以陪我去吗？', 'Mǎkè, wǒ xiàwǔ xiǎng qù yīyuàn jiǎnchá shēntǐ, nǐ kěyǐ péi wǒ qù ma?', 'Mark, chiều nay tôi muốn đi bệnh viện kiểm tra sức khỏe, bạn đi cùng tôi được không?', 15) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v21_16', 'lesson-21', '治病', 'zhìbìng', 'bệnh', 'trị bệnh', 'Động từ', '水/氵 (Thủy) (Nước, chất lỏng, sông ngòi)', '治: 氵 (Thủy: trị thủy) + 台 (Đài: quản lý, chữa trị) • 病: 疒 (Nạch: nằm giường bệnh) + 丙 (Bính)', 'Ghép 治 [bộ 氵] + 病 [bộ 疒] để nhớ từ 治病 (zhìbìng): "trị bệnh".', '那现在怎么治病呢, 医生？', 'Nà xiànzài zěnme zhì bìng ne, yīshēng?', 'Vậy bây giờ điều trị thế nào ạ, thưa bác sĩ?', 16) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v21_17', 'lesson-21', '打针', 'dǎzhēn', 'từ Hán ngữ', 'tiêm', 'Động từ', '手/扌 (Thủ) (Bàn tay, động tác, thao tác)', '打: 扌 (Thủ: bàn tay) + 丁 (Đinh) • 针: 钅 (Kim: kim loại nhọn) + 十 (Thập: cây kim)', 'Ghép 打 [bộ 扌] + 针 [bộ 钅] để nhớ từ 打针 (dǎzhēn): "tiêm".', '这是关于“打针”的常用句子。', 'Zhè shì guānyú ''dǎzhēn'' de chángyòng jùzi.', 'Đây là câu ví dụ sử dụng từ ''打针'' (tiêm).', 17) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v21_18', 'lesson-21', '开处方', 'kāi chǔfāng', 'từ Hán ngữ', 'kê đơn thuốc', 'Động từ', '廾 (Củng) (Hai tay chắp, nâng đỡ)', '开: 一 + 廾 (Củng: hai tay mở rộng) • 处: 夂 (Trĩ) + 卜 (Bốc) • 方: Bộ 方 (Phương - hình vuông, phương hướng)', 'Ghép 开 [bộ 廾] + 处 [bộ 夂] + 方 [bộ 方] để nhớ từ 开处方 (kāi chǔfāng): "kê đơn thuốc".', '这是关于“开处方”的常用句子。', 'Zhè shì guānyú ''kāi chǔfāng'' de chángyòng jùzi.', 'Đây là câu ví dụ sử dụng từ ''开处方'' (kê đơn thuốc).', 18) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v21_19', 'lesson-21', '陪', 'péi', 'từ Hán ngữ', 'đi cùng', 'Động từ', '阝 (Phụ/Ấp) (Gò đất hoặc vùng đất, thành ấp)', '陪 = 阝 (Phụ) + 咅 (Thôi: đứng cạnh bầu bạn).', 'Chữ 陪 (péi) mang nghĩa "đi cùng", bộ chính 阝 (Phụ/Ấp); cấu tạo: 阝 (Phụ) + 咅 (Thôi: đứng cạnh bầu bạn).', '马克，我下午想去医院检查身体， 你可以陪我去吗？', 'Mǎkè, wǒ xiàwǔ xiǎng qù yīyuàn jiǎnchá shēntǐ, nǐ kěyǐ péi wǒ qù ma?', 'Mark, chiều nay tôi muốn đi bệnh viện kiểm tra sức khỏe, bạn đi cùng tôi được không?', 19) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v21_20', 'lesson-21', '减少', 'jiǎnshǎo', 'thiểu', 'giảm', 'Động từ', '冫 (Băng) (Nước đá, lạnh giá)', '减: 冫 (Băng) + 咸 (Hàm: giảm bớt đi) • 少: 小 (Tiểu: nhỏ) + 丿 (Phiệt: cắt bớt còn ít)', 'Ghép 减 [bộ 冫] + 少 [bộ 小] để nhớ từ 减少 (jiǎnshǎo): "giảm".', '对了，你有没有医疗保险？如果有的话就可以减少检查费用。', 'Duì le, nǐ yǒu méiyǒu yīliáo bǎoxiǎn? Rúguǒ yǒu de huà jiù kěyǐ jiǎnshǎo jiǎnchá fèiyòng.', 'À đúng rồi, bạn có bảo hiểm y tế không? Nếu có thì có thể giảm bớt chi phí khám bệnh đấy.', 20) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v21_21', 'lesson-21', '明白', 'míngbai', 'minh bạch', 'hiểu', 'Động từ', '日 (Nhật) (Mặt trời, ban ngày, thời gian, ánh sáng)', '明: 日 (Nhật: mặt trời) + 月 (Nguyệt: mặt trăng) • 白: Bộ 白 (Bạch - ánh sáng trắng, chữ độc thể)', 'Ghép 明 [bộ 日] + 白 [bộ 白] để nhớ từ 明白 (míngbai): "hiểu".', '我明白了。 谢谢您！', 'Wǒ míngbai le. Xièxie nín!', 'Tôi hiểu rồi. Cảm ơn ông ạ!', 21) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v21_22', 'lesson-21', '其实', 'qíshí', 'từ Hán ngữ', 'thực ra', 'Phó từ', '八 (Bát) (Số tám, phân chia, mở rộng)', '其: 甘 biến thể + 一 + 八 (cái sàng, đại từ chỉ định) • 实: 宀 (Miên: mái nhà) + 头 (Đầu: đầy đủ chân thật)', 'Ghép 其 [bộ 八] + 实 [bộ 宀] để nhớ từ 其实 (qíshí): "thực ra".', '其实没有什么要紧的。 我让护士给你打个针并开给你一个处方，你回家吃完饭再吃药和多喝水，过几天身体就恢复了。', 'Qíshí méiyǒu shénme yàojǐn de. Wǒ ràng hùshì gěi nǐ dǎ gè zhēn bìng kāi gěi nǐ yí gè chǔfāng, nǐ huí jiā chī wán fàn zài chī yào hé duō hē shuǐ, guò jǐ tiān shēntǐ jiù huīfù le.', 'Thực ra không có gì nghiêm trọng đâu. Tôi bảo y tá tiêm cho bạn một mũi và kê đơn thuốc, bạn về nhà ăn cơm xong uống thuốc và uống nhiều nước, vài ngày sau sức khỏe sẽ hồi phục thôi.', 22) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v21_23', 'lesson-21', '并', 'bìng', 'từ Hán ngữ', 'và', 'Liên từ', '干 (Can) (Can thiệp, khô ráo, làm việc)', '并 = 丷 + 开 (hai thứ gộp chung lại).', 'Chữ 并 (bìng) mang nghĩa "và", bộ chính 干 (Can); cấu tạo: 丷 + 开 (hai thứ gộp chung lại).', '其实没有什么要紧的。 我让护士给你打个针并开给你一个处方，你回家吃完饭再吃药和多喝水，过几天身体就恢复了。', 'Qíshí méiyǒu shénme yàojǐn de. Wǒ ràng hùshì gěi nǐ dǎ gè zhēn bìng kāi gěi nǐ yí gè chǔfāng, nǐ huí jiā chī wán fàn zài chī yào hé duō hē shuǐ, guò jǐ tiān shēntǐ jiù huīfù le.', 'Thực ra không có gì nghiêm trọng đâu. Tôi bảo y tá tiêm cho bạn một mũi và kê đơn thuốc, bạn về nhà ăn cơm xong uống thuốc và uống nhiều nước, vài ngày sau sức khỏe sẽ hồi phục thôi.', 23) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order) VALUES ('g21_1', 'lesson-21', '1. 最好', 'Cấu trúc câu ngữ pháp trọng tâm', ' 你最好继续锻炼身体吧！ Nǐ zuì hǎo jìxù duànliàn shēntǐ ba! Tốt nhất bạn nên tiếp tục rèn luyện sức khỏe đi! 最好的办法是什么都不要说，保持安静！ Zuì hǎo de bànfǎ shì shénme dōu búyào shuō, bǎochí ānjìng! Cách tốt nhất đó chính là không nói gì cả và giữ im lặng!', NULL, '[{"hanzi":"你最好继续锻炼身体吧！","pinyin":"Nǐ zuì hǎo jìxù duànliàn shēntǐ ba!","meaning":"Tốt nhất bạn nên tiếp tục rèn luyện sức khỏe đi!"},{"hanzi":"最好的办法是什么都不要说，保持安静！","pinyin":"Zuì hǎo de bànfǎ shì shénme dōu búyào shuō, bǎochí ānjìng!","meaning":"Cách tốt nhất đó chính là không nói gì cả và giữ im lặng!"}]'::jsonb, 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order) VALUES ('g21_2', 'lesson-21', '2. 吧', 'Cấu trúc câu ngữ pháp trọng tâm', ' 你这么努力，肯定很累吧？ Nǐ zhème nǔlì, kěndìng hěn lèi ba? Bạn cố gắng như vậy, nhất định rất mệt nhỉ? 他可能同意了吧？ Tā kěnéng tóngyì le ba? Hẳn là anh ấy đồng ý rồi?', NULL, '[{"hanzi":"你这么努力，肯定很累吧？","pinyin":"Nǐ zhème nǔlì, kěndìng hěn lèi ba?","meaning":"Bạn cố gắng như vậy, nhất định rất mệt nhỉ?"},{"hanzi":"他可能同意了吧？","pinyin":"Tā kěnéng tóngyì le ba?","meaning":"Hẳn là anh ấy đồng ý rồi?"}]'::jsonb, 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order) VALUES ('g21_3', 'lesson-21', '3. 多 + Động  từ', 'Cấu trúc câu ngữ pháp trọng tâm', ' 你多吃点儿蔬菜吧，对身体有好处！ Nǐ duō chī diǎnr shūcài ba, duì shēntǐ yǒu hǎochù! Con ăn nhiều rau chút, có lợi cho sức khỏe! 你多运动运动吧！ Nǐ duō yùndòng yùndòng ba! Con vận động nhiều hơn đi!', NULL, '[{"hanzi":"你多吃点儿蔬菜吧，对身体有好处！","pinyin":"Nǐ duō chī diǎnr shūcài ba, duì shēntǐ yǒu hǎochù!","meaning":"Con ăn nhiều rau chút, có lợi cho sức khỏe!"},{"hanzi":"你多运动运动吧！","pinyin":"Nǐ duō yùndòng yùndòng ba!","meaning":"Con vận động nhiều hơn đi!"}]'::jsonb, 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order) VALUES ('g21_4', 'lesson-21', '4. Động từ năng nguyện', 'Cấu trúc câu ngữ pháp trọng tâm', ' 我会游泳，也会滑冰。 Wǒ huì yóuyǒng, yě huì huábīng. Tớ biết bơi, còn biết trượt băng. 你能给我倒杯水吗？ Nǐ néng gěi wǒ dào bēi shuǐ ma? Cậu có thể rót cho tớ cốc nước không? 可能快要下雪了！ Kěnéng kuàiyào xià xuě le! Có lẽ sắp có tuyết rơi rồi! 我想去公园跑步。 Wǒ xiǎng qù gōngyuá', NULL, '[{"hanzi":"我会游泳，也会滑冰。","pinyin":"Wǒ huì yóuyǒng, yě huì huábīng.","meaning":"Tớ biết bơi, còn biết trượt băng."},{"hanzi":"你能给我倒杯水吗？","pinyin":"Nǐ néng gěi wǒ dào bēi shuǐ ma?","meaning":"Cậu có thể rót cho tớ cốc nước không?"}]'::jsonb, 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order;
INSERT INTO texts (id, lesson_id, title, description, sort_order) VALUES ('txt_21_1', 'lesson-21', 'Bài khoá #1: Hội thoại giáo trình — Kiểm tra sức khoẻ', 'Hội thoại chuẩn giáo trình Bài 21. Từ vựng chưa học được chú thích phiên âm & nghĩa trong ngoặc.', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_21_1_1', 'txt_21_1', '白茹雪', '马克，我下午想去医院检查身体， 你可以陪我去吗？', '马克，我下午想去医院检查身体， 你可以陪我去吗？', 'Mǎkè, wǒ xiàwǔ xiǎng qù yīyuàn jiǎnchá shēntǐ, nǐ kěyǐ péi wǒ qù ma?', 'Mark, chiều nay tôi muốn đi bệnh viện kiểm tra sức khỏe, bạn đi cùng tôi được không?', 1) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_21_1_2', 'txt_21_1', '马克', '你怎么了? 身体不好吗？', '你怎么了? 身体不好吗？', 'Nǐ zěnme le? Shēntǐ bù hǎo ma?', 'Bạn làm sao thế? Trong người không khỏe à?', 2) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_21_1_3', 'txt_21_1', '白茹雪', '是的，最近觉得身体不太好，所以想去医院看看得了什么病。', '是的，最近觉得身体不太好，所以 (suǒyǐ: cho nên)想去医院看看得了什么病 (bìng: bệnh)。', 'Shì de, zuìjìn juéde shēntǐ bù tài hǎo, suǒyǐ xiǎng qù yīyuàn kànkan déle shénme bìng.', 'Đúng vậy, dạo này thấy người không khỏe lắm, nên muốn đi bệnh viện khám xem bị bệnh gì.', 3) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_21_1_4', 'txt_21_1', '马克', '好的。 我陪你去看病。', '好的。 我陪你去看病。', 'Hǎo de. Wǒ péi nǐ qù kànbìng.', 'Được thôi. Tôi sẽ đi khám bệnh cùng bạn.', 4) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_21_1_5', 'txt_21_1', '医生', '你有什么症状？', '你有什么症状？', 'Nǐ yǒu shénme zhèngzhuàng?', 'Bạn có triệu chứng gì?', 5) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_21_1_6', 'txt_21_1', '白茹雪', '我经常觉得头晕，吃什么都过敏。 最近胃口和睡眠都不好。', '我经常觉得头晕，吃什么都过敏。 最近胃口和睡眠都不好。', 'Wǒ jīngcháng juéde tóuyūn, chī shénme dōu guòmǐn. Zuìjìn wèikǒu hé shuìmián dōu bù hǎo.', 'Tôi hay bị chóng mặt, ăn gì cũng bị dị ứng. Dạo này ăn uống và giấc ngủ đều kém.', 6) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_21_1_7', 'txt_21_1', '医生', '好的，我们现在给你检查检查。', '好的，我们现在给你检查检查。', 'Hǎo de，wǒmen xiànzài gěi nǐ jiǎnchá jiǎnchá.', 'Được rồi, bây giờ chúng tôi sẽ kiểm tra cho bạn.', 7) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_21_1_8', 'txt_21_1', '白茹雪', '我是不是得了重病？', '我是不是得了重病？', 'Wǒ shì bu shì dé le zhòngbìng?', 'Có phải tôi mắc bệnh nặng rồi không?', 8) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_21_1_9', 'txt_21_1', '医生', '你学习和工作太累了， 所以才有那样的症状。', '你学习 (xuéxí: học tập)和工作 (gōngzuò: nghề nghiệp, công việc)太累了， 所以 (suǒyǐ: cho nên)才 (cái: mới)有那样 (yàng: kiểu, dáng)的症状。', 'Nǐ xuéxí hé gōngzuò tài lèi le, suǒyǐ cái yǒu nàyàng de zhèngzhuàng.', 'Bạn học tập và làm việc quá mệt mỏi, nên mới xuất hiện những triệu chứng như vậy.', 9) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_21_1_10', 'txt_21_1', '白茹雪', '那现在怎么治病呢, 医生？', '那现在怎么治病呢, 医生？', 'Nà xiànzài zěnme zhì bìng ne, yīshēng?', 'Vậy bây giờ điều trị thế nào ạ, thưa bác sĩ?', 10) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_21_1_11', 'txt_21_1', '医生', '其实没有什么要紧的。 我让护士给你打个针并开给你一个处方，你回家吃完饭再吃药和多喝水，过几天身体就恢复了。', '其实没有 (méiyǒu: không có)什么要紧的。 我让 (ràng: bảo, khiến)护士给你打 (dǎ: đánh, gọi, chơi)个针 (zhēn: kim tiêm)并开 (kāi: mở, lái)给你一个处方 (chǔfāng: đơn thuốc)，你回家吃完 (wán: xong, hết)饭再吃药和多喝水，过 (guò: từng, qua)几天 (tiān: ngày, trời)身体就恢复了。', 'Qíshí méiyǒu shénme yàojǐn de. Wǒ ràng hùshì gěi nǐ dǎ gè zhēn bìng kāi gěi nǐ yí gè chǔfāng, nǐ huí jiā chī wán fàn zài chī yào hé duō hē shuǐ, guò jǐ tiān shēntǐ jiù huīfù le.', 'Thực ra không có gì nghiêm trọng đâu. Tôi bảo y tá tiêm cho bạn một mũi và kê đơn thuốc, bạn về nhà ăn cơm xong uống thuốc và uống nhiều nước, vài ngày sau sức khỏe sẽ hồi phục thôi.', 11) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_21_1_12', 'txt_21_1', '白茹雪', '谢谢医生！', '谢谢医生！', 'Xièxie yīshēng!', 'Cảm ơn bác sĩ ạ!', 12) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_21_1_13', 'txt_21_1', '医生', '对了，你有没有医疗保险？如果有的话就可以减少检查费用。', '对了，你有没有 (méiyǒu: không có)医疗保险？如果有的话 (huà: lời nói)就可以减少检查费用。', 'Duì le, nǐ yǒu méiyǒu yīliáo bǎoxiǎn? Rúguǒ yǒu de huà jiù kěyǐ jiǎnshǎo jiǎnchá fèiyòng.', 'À đúng rồi, bạn có bảo hiểm y tế không? Nếu có thì có thể giảm bớt chi phí khám bệnh đấy.', 13) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_21_1_14', 'txt_21_1', '白茹雪', '我没有医疗保险。', '我没有 (méiyǒu: không có)医疗保险。', 'Wǒ méiyǒu yīliáo bǎoxiǎn.', 'Tôi chưa có bảo hiểm y tế ạ.', 14) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_21_1_15', 'txt_21_1', '医生', '大多数病人都买医疗保险，它很重要，你应该买一个!', '大 (dà: to, lớn)多数病人都买医疗保险，它很重要，你应该买一个!', 'Dàduōshù bìngrén dōu mǎi yīliáo bǎoxiǎn, tā hěn zhòngyào, nǐ yīnggāi mǎi yígè!', 'Đa số bệnh nhân đều mua bảo hiểm y tế, nó rất quan trọng, bạn nên mua một cái nhé!', 15) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_21_1_16', 'txt_21_1', '白茹雪', '我明白了。 谢谢您！', '我明白了。 谢谢您！', 'Wǒ míngbai le. Xièxie nín!', 'Tôi hiểu rồi. Cảm ơn ông ạ!', 16) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_21_1_1', 'lesson-21', 'txt_21_1', 'listening', 'listening', '马克，我下午想去医院检查身体， 你可以陪我去吗？', NULL, 'Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Anh ấy không phải giáo viên.","Mark, chiều nay tôi muốn đi bệnh viện kiểm tra sức khỏe, bạn đi cùng tôi được không?","Anh ta lại đến rồi!","Bạn đã làm xong bài tập hôm nay chưa?"]'::jsonb, 1, 'Nội dung nghe được: 马克，我下午想去医院检查身体， 你可以陪我去吗？ (Mǎkè, wǒ xiàwǔ xiǎng qù yīyuàn jiǎnchá shēntǐ, nǐ kěyǐ péi wǒ qù ma?) → Mark, chiều nay tôi muốn đi bệnh viện kiểm tra sức khỏe, bạn đi cùng tôi được không?', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_21_1_2', 'lesson-21', 'txt_21_1', 'listening', 'listening', '你怎么了? 身体不好吗？', NULL, 'Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["你怎么了? 身体不好吗？","护士告诉我这只是小毛病 (bìng: bệnh)，不是重病。","你这么努力 (nǔlì: cố gắng, nỗ lực)，肯定 (kěndìng: khẳng định, chắc chắn)很累吧？","是的，最近觉得身体不太好，所以 (suǒyǐ: cho nên)想去医院看看得了什么病 (bìng: bệnh)。"]'::jsonb, 0, 'Câu vừa đọc: 你怎么了? 身体不好吗？ (Nǐ zěnme le? Shēntǐ bù hǎo ma?) → Bạn làm sao thế? Trong người không khỏe à?', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_21_1_3', 'lesson-21', 'txt_21_1', 'listening', 'listening', '是的，最近觉得身体不太好，所以想去医院看看得了什么病。', NULL, 'Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Tớ định đi xe buýt.","Đúng vậy, dạo này thấy người không khỏe lắm, nên muốn đi bệnh viện khám xem bị bệnh gì.","Bạn cứ đi thẳng, sau đó rẽ phải là sẽ nhìn thấy bệnh viện ở bên trái của","Bạn mệt à? Nghỉ ngơi thêm chút đi!"]'::jsonb, 1, 'Nội dung nghe được: 是的，最近觉得身体不太好，所以想去医院看看得了什么病。 (Shì de, zuìjìn juéde shēntǐ bù tài hǎo, suǒyǐ xiǎng qù yīyuàn kànkan déle shénme bìng.) → Đúng vậy, dạo này thấy người không khỏe lắm, nên muốn đi bệnh viện khám xem bị bệnh gì.', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_21_1_4', 'lesson-21', 'txt_21_1', 'listening', 'listening', '好的。 我陪你去看病。', NULL, 'Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["病人对这种水果有点儿过敏。","我下午陪奶奶去医院看病。","医生仔细检查了我的身体和症状。","好的。 我陪你去看病。"]'::jsonb, 3, 'Câu vừa đọc: 好的。 我陪你去看病。 (Hǎo de. Wǒ péi nǐ qù kànbìng.) → Được thôi. Tôi sẽ đi khám bệnh cùng bạn.', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO texts (id, lesson_id, title, description, sort_order) VALUES ('txt_21_2', 'lesson-21', 'Bài nghe tổng hợp: Ôn tập lũy tiến (Bài 1 – Bài 21)', 'Kết hợp từ vựng & mẫu câu đã học từ Bài 1 đến Bài 20 cùng trọng tâm Bài 21 để củng cố phản xạ nghe.', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_21_2_1', 'txt_21_2', 'Ôn Bài 20', '明天我想去图书馆看书。', '明天我想去图书馆看书。', 'Míngtiān wǒ xiǎng qù túshū guǎn kànshū.', 'Ngày mai tôi muốn đi thư viện đọc sách.', 1) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_21_2_2', 'txt_21_2', 'Bài 21', '你多运动运动吧！', '你多运动运动吧！', 'Nǐ duō yùndòng yùndòng ba!', 'Con vận động nhiều hơn đi!', 2) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_21_2_3', 'txt_21_2', 'Ôn Bài 10', '这本书是我的。', '这本书是我的。', 'Zhè běn shū shì wǒ de.', 'Quyển sách này là sách của tôi.', 3) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_21_2_4', 'txt_21_2', 'Bài 21', '我会游泳，也会滑冰。', '我会游泳，也会滑冰。', 'Wǒ huì yóuyǒng, yě huì huábīng.', 'Tớ biết bơi, còn biết trượt băng.', 4) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_21_2_5', 'txt_21_2', 'Ôn Bài 1', '老师好', '老师好', 'Lǎoshī hǎo', 'Chào thầy/Chào cô', 5) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_21_2_6', 'txt_21_2', 'Bài 21', '可能快要下雪了！', '可能快要下雪了！', 'Kěnéng kuàiyào xià xuě le!', 'Có lẽ sắp có tuyết rơi rồi!', 6) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_21_2_7', 'txt_21_2', 'Ôn Bài 18', '你知道他在哪儿吗？', '你知道他在哪儿吗？', 'Nǐ zhīdào tā zài nǎr ma?', 'Bạn biết anh ấy ở đâu không?', 7) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_21_2_8', 'txt_21_2', 'Bài 21', '我想去公园跑步。', '我想去公园跑步。', 'Wǒ xiǎng qù gōngyuán pǎobù.', 'Tớ muốn đến công viên chạy bộ.', 8) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_21_2_1', 'lesson-21', 'txt_21_2', 'listening', 'listening', '明天我想去图书馆看书。', NULL, '[Ôn tập Bài 20] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Mẹ bảo tôi ăn cơm xong thì giúp mẹ quét dọn nhà cửa.","chi phí sinh hoạt","Tôi có thể làm tốt việc này","Ngày mai tôi muốn đi thư viện đọc sách."]'::jsonb, 3, 'Nội dung nghe được: 明天我想去图书馆看书。 (Míngtiān wǒ xiǎng qù túshū guǎn kànshū.) → Ngày mai tôi muốn đi thư viện đọc sách.', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_21_2_2', 'lesson-21', 'txt_21_2', 'listening', 'listening', '你多运动运动吧！', NULL, '[Bài 21] Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["你多运动运动吧！","如果有医疗保险，看病费用可以减少很多。","他可能同意 (tóngyì: đồng ý)了吧？","我想去公园跑步。"]'::jsonb, 0, 'Câu vừa đọc: 你多运动运动吧！ (Nǐ duō yùndòng yùndòng ba!) → Con vận động nhiều hơn đi!', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_21_2_3', 'lesson-21', 'txt_21_2', 'listening', 'listening', '这本书是我的。', NULL, '[Ôn tập Bài 10] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Tớ biết bơi, còn biết trượt băng.","Bộ quần áo này không to cũng không nhỏ.","Một bộ quần áo","Quyển sách này là sách của tôi."]'::jsonb, 3, 'Nội dung nghe được: 这本书是我的。 (Zhè běn shū shì wǒ de.) → Quyển sách này là sách của tôi.', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_21_2_4', 'lesson-21', 'txt_21_2', 'listening', 'listening', '我会游泳，也会滑冰。', NULL, '[Bài 21] Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["我下午陪奶奶去医院看病。","我经常觉得头晕，吃什么都过敏。 最近胃口和睡眠都不好。","如果有医疗保险，看病费用可以减少很多。","我会游泳，也会滑冰。"]'::jsonb, 3, 'Câu vừa đọc: 我会游泳，也会滑冰。 (Wǒ huì yóuyǒng, yě huì huábīng.) → Tớ biết bơi, còn biết trượt băng.', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_21_2_5', 'lesson-21', 'txt_21_2', 'listening', 'listening', '老师好', NULL, '[Ôn tập Bài 1] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Em trai vui đến nổi nhảy cẫng lên.","Chào thầy/Chào cô","Lúc tôi gọi điện thoại cho bạn thì bố đang nhìn tôi.","Trời mưa rồi mà tôi không mang ô, chỉ đành đợi ở trường."]'::jsonb, 1, 'Nội dung nghe được: 老师好 (Lǎoshī hǎo) → Chào thầy/Chào cô', 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO texts (id, lesson_id, title, description, sort_order) VALUES ('txt_21_3', 'lesson-21', 'Bài khoá mở rộng: Đi khám kiểm tra sức khỏe (Mở rộng)', 'Hội thoại tình huống mới xây dựng dựa trên từ vựng và ngữ pháp Bài 21 (không trùng lặp nguyên văn giáo trình).', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_21_3_1', 'txt_21_3', 'Bác sĩ', '你最近有什么症状，哪里不舒服？', '你最近有什么症状，哪里不舒服？', 'Nǐ zuìjìn yǒu shénme zhèngzhuàng, nǎlǐ bù shūfu?', 'Dạo này bạn có triệu chứng gì, thấy khó chịu ở đâu?', 1) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_21_3_2', 'txt_21_3', 'Bệnh nhân', '医生，我头晕、睡眠不好，对有些食物还会过敏。', '医生，我头晕、睡眠不好，对有些 (xiē: vài, một ít)食物还会过敏。', 'Yīshēng, wǒ tóuyūn, shuìmián bù hǎo, duì yǒuxiē shíwù hái huì guòmǐn.', 'Thưa bác sĩ, tôi bị chóng mặt, ngủ không ngon giấc, lại còn dị ứng với vài món ăn.', 2) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_21_3_3', 'txt_21_3', 'Bác sĩ', '别担心，检查结果正常，没有重病，只是太累了。', '别 (bié: đừng)担心 (dānxīn: lo lắng)，检查结果正 (zhèng: đang)常，没有 (méiyǒu: không có)重病，只是太累了。', 'Bié dānxīn, jiǎnchá jiéguǒ zhèngcháng, méiyǒu zhòngbìng, zhǐshì tài lèi le.', 'Đừng lo, kết quả kiểm tra bình thường, không có bệnh nặng đâu, chỉ là làm việc quá mệt thôi.', 3) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_21_3_4', 'txt_21_3', 'Bệnh nhân', '还好我有医疗保险，费用减轻了不少，谢谢医生和护士！', '还好我有医疗保险，费用减轻了不少 (shǎo: ít)，谢谢医生和护士！', 'Háihǎo wǒ yǒu yīliáo bǎoxiǎn, fèiyòng jiǎnqīng le bùshǎo, xièxie yīshēng hé hùshi!', 'May quá tôi có bảo hiểm y tế nên chi phí giảm đi nhiều, cảm ơn bác sĩ và y tá!', 4) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_21_3_1', 'lesson-21', 'txt_21_3', 'listening', 'listening', '你最近有什么症状，哪里不舒服？ 医生，我头晕、睡眠不好，对有些食物还会过敏。 别担心，检查结果正常，没有重病，只是太累了。 还好我有医疗保险，费用减轻了不少，谢谢医生和护士！', NULL, '[Nghe hiểu tình huống mới] Bác sĩ kết luận tình trạng của bệnh nhân sau khi kiểm tra là gì?', '["Bị gãy chân khi chạy bộ","Cần đổi bảo hiểm y tế","Mắc bệnh nặng phải nhập viện ngay","Không mắc bệnh nặng, chỉ do làm việc quá mệt mỏi"]'::jsonb, 3, 'Bác sĩ trấn an: ''检查结果正常，没有重病，只是太累了''.', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_21_3_2', 'lesson-21', 'txt_21_3', 'listening', 'listening', '你最近有什么症状，哪里不舒服？', NULL, '[Mở rộng] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Bọn họ chỉ quan tâm đến bản thân mình mà thôi.","Một câu chuyện","Anh ta không cho tôi đi.","Dạo này bạn có triệu chứng gì, thấy khó chịu ở đâu?"]'::jsonb, 3, 'Nội dung nghe được: 你最近有什么症状，哪里不舒服？ (Nǐ zuìjìn yǒu shénme zhèngzhuàng, nǎlǐ bù shūfu?) → Dạo này bạn có triệu chứng gì, thấy khó chịu ở đâu?', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_21_3_3', 'lesson-21', 'txt_21_3', 'listening', 'listening', '医生，我头晕、睡眠不好，对有些食物还会过敏。', NULL, '[Mở rộng] Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["如果八点我还没 (méi: chưa, không có)回来 (lái: đến)，你就不用 (yòng: dùng)等我了。","病人对这种水果有点儿过敏。","如果有医疗保险，看病费用可以减少很多。","医生，我头晕、睡眠不好，对有些 (xiē: vài, một ít)食物还会过敏。"]'::jsonb, 3, 'Câu vừa đọc: 医生，我头晕、睡眠不好，对有些食物还会过敏。 (Yīshēng, wǒ tóuyūn, shuìmián bù hǎo, duì yǒuxiē shíwù hái huì guòmǐn.) → Thưa bác sĩ, tôi bị chóng mặt, ngủ không ngon giấc, lại còn dị ứng với vài món ăn.', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_21_3_4', 'lesson-21', 'txt_21_3', 'listening', 'listening', '别担心，检查结果正常，没有重病，只是太累了。', NULL, '[Mở rộng] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Cô ấy là học sinh trường nào?","một câu chuyện","Lúc tôi về nhà, bố đang xem ti vi.","Đừng lo, kết quả kiểm tra bình thường, không có bệnh nặng đâu, chỉ là làm việc quá mệt thôi."]'::jsonb, 3, 'Nội dung nghe được: 别担心，检查结果正常，没有重病，只是太累了。 (Bié dānxīn, jiǎnchá jiéguǒ zhèngcháng, méiyǒu zhòngbìng, zhǐshì tài lèi le.) → Đừng lo, kết quả kiểm tra bình thường, không có bệnh nặng đâu, chỉ là làm việc quá mệt thôi.', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss21_1', 'lesson-21', '病人对这种水果有点儿过敏', '[Mở rộng] Bệnh nhân hơi bị dị ứng với loại trái cây này.', 'Bìngrén duì zhè zhǒng shuǐguǒ yǒudiǎnr guòmǐn.', '["病人","对这","种","水果","有点儿","过敏"]'::jsonb, NULL, 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss21_2', 'lesson-21', '我下午陪奶奶去医院看病', '[Mở rộng] Chiều nay tôi đưa bà nội đi bệnh viện khám bệnh.', 'Wǒ xiàwǔ péi nǎinai qù yīyuàn kànbìng.', '["我下午","陪","奶奶","去","医院","看病"]'::jsonb, NULL, 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss21_3', 'lesson-21', '你多运动运动吧', 'Con vận động nhiều hơn đi!', 'Nǐ duō yùndòng yùndòng ba!', '["你","多","运动","运动","吧"]'::jsonb, NULL, 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss21_4', 'lesson-21', '我会游泳也会滑冰', 'Tớ biết bơi, còn biết trượt băng.', 'Wǒ huì yóuyǒng, yě huì huábīng.', '["我","会","游泳","也","会","滑冰"]'::jsonb, NULL, 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss21_5', 'lesson-21', '请告诉我这副眼镜多少钱', '[Ôn tập Bài 10] Làm ơn cho tôi biết cặp kính mắt này bao nhiêu tiền.', 'Qǐng gàosu wǒ zhè fù yǎnjìng duōshao qián.', '["请告诉","我这","副","眼镜","多少","钱"]'::jsonb, NULL, 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss21_6', 'lesson-21', '马克明天早上见', '[Ôn tập Bài 2] Mark, sáng mai gặp lại nhé!', 'Mǎkè, míngtiān zǎoshang jiàn!', '["马克","明天","早上","见"]'::jsonb, NULL, 6) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss21_exp_1', 'lesson-21', '马克我下午想去医院检查身体你可以陪我去吗', 'Mark, chiều nay tôi muốn đi bệnh viện kiểm tra sức khỏe, bạn đi cùng tôi được không?', 'Mǎkè, wǒ xiàwǔ xiǎng qù yīyuàn jiǎnchá shēntǐ, nǐ kěyǐ péi wǒ qù ma?', '["马克","我","下午","想","去","医院","检查","身体","你","可以","陪","我","去","吗"]'::jsonb, NULL, 7) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss21_exp_2', 'lesson-21', '你怎么了身体不好吗', 'Bạn làm sao thế? Trong người không khỏe à?', 'Nǐ zěnme le? Shēntǐ bù hǎo ma?', '["你","怎么了","身体","不","好","吗"]'::jsonb, NULL, 8) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss21_exp_3', 'lesson-21', '是的最近觉得身体不太好所以想去医院看看得了什么病', 'Đúng vậy, dạo này thấy người không khỏe lắm, nên muốn đi bệnh viện khám xem bị bệnh gì.', 'Shì de, zuìjìn juéde shēntǐ bù tài hǎo, suǒyǐ xiǎng qù yīyuàn kànkan déle shénme bìng.', '["是","的","最近","觉得","身体","不","太","好","所以","想","去","医院","看","看","得了","什么","病"]'::jsonb, NULL, 9) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss21_exp_4', 'lesson-21', '好的我陪你去看病', 'Được thôi. Tôi sẽ đi khám bệnh cùng bạn.', 'Hǎo de. Wǒ péi nǐ qù kànbìng.', '["好","的","我","陪","你","去","看病"]'::jsonb, NULL, 10) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss21_exp_5', 'lesson-21', '你有什么症状', 'Bạn có triệu chứng gì?', 'Nǐ yǒu shénme zhèngzhuàng?', '["你","有","什么","症状"]'::jsonb, NULL, 11) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss21_exp_6', 'lesson-21', '我经常觉得头晕吃什么都过敏最近胃口和睡眠都不好', 'Tôi hay bị chóng mặt, ăn gì cũng bị dị ứng. Dạo này ăn uống và giấc ngủ đều kém.', 'Wǒ jīngcháng juéde tóuyūn, chī shénme dōu guòmǐn. Zuìjìn wèikǒu hé shuìmián dōu bù hǎo.', '["我","经常","觉得","头晕","吃","什么","都","过敏","最近","胃口","和","睡眠","都","不","好"]'::jsonb, NULL, 12) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss21_exp_7', 'lesson-21', '好的我们现在给你检查检查', 'Được rồi, bây giờ chúng tôi sẽ kiểm tra cho bạn.', 'Hǎo de，wǒmen xiànzài gěi nǐ jiǎnchá jiǎnchá.', '["好","的","我们","现在","给","你","检查","检查"]'::jsonb, NULL, 13) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss21_exp_8', 'lesson-21', '我是不是得了重病', 'Có phải tôi mắc bệnh nặng rồi không?', 'Wǒ shì bu shì dé le zhòngbìng?', '["我","是","不是","得了","重病"]'::jsonb, NULL, 14) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss21_exp_9', 'lesson-21', '你学习和工作太累了所以才有那样的症状', 'Bạn học tập và làm việc quá mệt mỏi, nên mới xuất hiện những triệu chứng như vậy.', 'Nǐ xuéxí hé gōngzuò tài lèi le, suǒyǐ cái yǒu nàyàng de zhèngzhuàng.', '["你","学","习","和","工作","太","累","了","所以","才","有","那","样","的","症状"]'::jsonb, NULL, 15) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss21_exp_10', 'lesson-21', '那现在怎么治病呢医生', 'Vậy bây giờ điều trị thế nào ạ, thưa bác sĩ?', 'Nà xiànzài zěnme zhì bìng ne, yīshēng?', '["那","现在","怎么","治病","呢","医生"]'::jsonb, NULL, 16) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss21_exp_11', 'lesson-21', '其实没有什么要紧的我让护士给你打个针并开给你一个处方你回家吃完饭再吃药和多喝水过几天身体就恢复了', 'Thực ra không có gì nghiêm trọng đâu. Tôi bảo y tá tiêm cho bạn một mũi và kê đơn thuốc, bạn về nhà ăn cơm xong uống thuốc và uống nhiều nước, vài ngày sau sức khỏe sẽ hồi phục thôi.', 'Qíshí méiyǒu shénme yàojǐn de. Wǒ ràng hùshì gěi nǐ dǎ gè zhēn bìng kāi gěi nǐ yí gè chǔfāng, nǐ huí jiā chī wán fàn zài chī yào hé duō hē shuǐ, guò jǐ tiān shēntǐ jiù huīfù le.', '["其实","没有","什么","要紧","的","我","让","护士","给","你","打","个","针","并","开","给","你","一","个","处","方","你","回","家","吃","完","饭","再","吃","药","和","多","喝","水","过","几","天","身体","就","恢复","了"]'::jsonb, NULL, 17) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss21_exp_12', 'lesson-21', '谢谢医生', 'Cảm ơn bác sĩ ạ!', 'Xièxie yīshēng!', '["谢谢","医生"]'::jsonb, NULL, 18) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss21_exp_13', 'lesson-21', '对了你有没有医疗保险如果有的话就可以减少检查费用', 'À đúng rồi, bạn có bảo hiểm y tế không? Nếu có thì có thể giảm bớt chi phí khám bệnh đấy.', 'Duì le, nǐ yǒu méiyǒu yīliáo bǎoxiǎn? Rúguǒ yǒu de huà jiù kěyǐ jiǎnshǎo jiǎnchá fèiyòng.', '["对","了","你","有","没有","医疗保险","如果","有","的","话","就","可以","减少","检查","费用"]'::jsonb, NULL, 19) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss21_exp_14', 'lesson-21', '我没有医疗保险', 'Tôi chưa có bảo hiểm y tế ạ.', 'Wǒ méiyǒu yīliáo bǎoxiǎn.', '["我","没有","医疗保险"]'::jsonb, NULL, 20) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr21_vi_1', 'lesson-21', 'vi_to_zh', '[Mở rộng] Dạo này tôi hay bị chóng mặt, ăn uống và giấc ngủ đều không tốt lắm.', NULL, NULL, '最近我常常头晕，胃口和睡眠都不太好。', NULL, 'zuìjìn wǒ chángcháng tóuyūn wèikǒu hé shuìmián dōu bú tài hǎo', '[]'::jsonb, 'Gợi ý Pinyin: Zuìjìn wǒ chángcháng tóuyūn, wèikǒu hé shuìmián dōu bú tài hǎo.', 'Dạo này tôi hay bị chóng mặt, ăn uống và giấc ngủ đều không tốt lắm. → 最近我常常头晕，胃口和睡眠都不太好。 (Zuìjìn wǒ chángcháng tóuyūn, wèikǒu hé shuìmián dōu bú tài hǎo.)', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr21_vi_2', 'lesson-21', 'vi_to_zh', '[Mở rộng] Nếu có bảo hiểm y tế, chi phí khám bệnh có thể giảm đi rất nhiều.', NULL, NULL, '如果有医疗保险，看病费用可以减少很多。', NULL, 'rúguǒ yǒu yīliáo bǎoxiǎn kànbìng fèiyòng kěyǐ jiǎnshǎo hěnduō', '[]'::jsonb, 'Gợi ý Pinyin: Rúguǒ yǒu yīliáo bǎoxiǎn, kànbìng fèiyòng kěyǐ jiǎnshǎo hěnduō.', 'Nếu có bảo hiểm y tế, chi phí khám bệnh có thể giảm đi rất nhiều. → 如果有医疗保险，看病费用可以减少很多。 (Rúguǒ yǒu yīliáo bǎoxiǎn, kànbìng fèiyòng kěyǐ jiǎnshǎo hěnduō.)', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr21_vi_3', 'lesson-21', 'vi_to_zh', 'Con vận động nhiều hơn đi!', NULL, NULL, '你多运动运动吧！', NULL, 'nǐ duō yùndòng yùndòng ba', '[]'::jsonb, 'Gợi ý Pinyin: Nǐ duō yùndòng yùndòng ba!', 'Con vận động nhiều hơn đi! → 你多运动运动吧！ (Nǐ duō yùndòng yùndòng ba!)', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr21_vi_4', 'lesson-21', 'vi_to_zh', 'Tớ biết bơi, còn biết trượt băng.', NULL, NULL, '我会游泳，也会滑冰。', NULL, 'wǒ huì yóuyǒng yě huì huábīng', '[]'::jsonb, 'Gợi ý Pinyin: Wǒ huì yóuyǒng, yě huì huábīng.', 'Tớ biết bơi, còn biết trượt băng. → 我会游泳，也会滑冰。 (Wǒ huì yóuyǒng, yě huì huábīng.)', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr21_vi_exp_1', 'lesson-21', 'vi_to_zh', 'Mark, chiều nay tôi muốn đi bệnh viện kiểm tra sức khỏe, bạn đi cùng tôi được không?', NULL, NULL, '马克，我下午想去医院检查身体， 你可以陪我去吗？', NULL, 'mǎkè wǒ xiàwǔ xiǎng qù yīyuàn jiǎnchá shēntǐ nǐ kěyǐ péi wǒ qù ma', '[]'::jsonb, 'Gợi ý Pinyin: Mǎkè, wǒ xiàwǔ xiǎng qù yīyuàn jiǎnchá shēntǐ, nǐ kěyǐ péi wǒ qù ma?', 'Mark, chiều nay tôi muốn đi bệnh viện kiểm tra sức khỏe, bạn đi cùng tôi được không? → 马克，我下午想去医院检查身体， 你可以陪我去吗？ (Mǎkè, wǒ xiàwǔ xiǎng qù yīyuàn jiǎnchá shēntǐ, nǐ kěyǐ péi wǒ qù ma?)', 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr21_vi_exp_2', 'lesson-21', 'vi_to_zh', 'Bạn làm sao thế? Trong người không khỏe à?', NULL, NULL, '你怎么了? 身体不好吗？', NULL, 'nǐ zěnme le shēntǐ bù hǎo ma', '[]'::jsonb, 'Gợi ý Pinyin: Nǐ zěnme le? Shēntǐ bù hǎo ma?', 'Bạn làm sao thế? Trong người không khỏe à? → 你怎么了? 身体不好吗？ (Nǐ zěnme le? Shēntǐ bù hǎo ma?)', 6) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr21_vi_exp_3', 'lesson-21', 'vi_to_zh', 'Đúng vậy, dạo này thấy người không khỏe lắm, nên muốn đi bệnh viện khám xem bị bệnh gì.', NULL, NULL, '是的，最近觉得身体不太好，所以想去医院看看得了什么病。', NULL, 'shì de zuìjìn juéde shēntǐ bù tài hǎo suǒyǐ xiǎng qù yīyuàn kànkan déle shénme bìng', '[]'::jsonb, 'Gợi ý Pinyin: Shì de, zuìjìn juéde shēntǐ bù tài hǎo, suǒyǐ xiǎng qù yīyuàn kànkan déle shénme bìng.', 'Đúng vậy, dạo này thấy người không khỏe lắm, nên muốn đi bệnh viện khám xem bị bệnh gì. → 是的，最近觉得身体不太好，所以想去医院看看得了什么病。 (Shì de, zuìjìn juéde shēntǐ bù tài hǎo, suǒyǐ xiǎng qù yīyuàn kànkan déle shénme bìng.)', 7) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr21_vi_exp_4', 'lesson-21', 'vi_to_zh', 'Được thôi. Tôi sẽ đi khám bệnh cùng bạn.', NULL, NULL, '好的。 我陪你去看病。', NULL, 'hǎo de wǒ péi nǐ qù kànbìng', '[]'::jsonb, 'Gợi ý Pinyin: Hǎo de. Wǒ péi nǐ qù kànbìng.', 'Được thôi. Tôi sẽ đi khám bệnh cùng bạn. → 好的。 我陪你去看病。 (Hǎo de. Wǒ péi nǐ qù kànbìng.)', 8) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr21_vi_exp_5', 'lesson-21', 'vi_to_zh', 'Bạn có triệu chứng gì?', NULL, NULL, '你有什么症状？', NULL, 'nǐ yǒu shénme zhèngzhuàng', '[]'::jsonb, 'Gợi ý Pinyin: Nǐ yǒu shénme zhèngzhuàng?', 'Bạn có triệu chứng gì? → 你有什么症状？ (Nǐ yǒu shénme zhèngzhuàng?)', 9) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr21_vi_exp_6', 'lesson-21', 'vi_to_zh', 'Tôi hay bị chóng mặt, ăn gì cũng bị dị ứng. Dạo này ăn uống và giấc ngủ đều kém.', NULL, NULL, '我经常觉得头晕，吃什么都过敏。 最近胃口和睡眠都不好。', NULL, 'wǒ jīngcháng juéde tóuyūn chī shénme dōu guòmǐn zuìjìn wèikǒu hé shuìmián dōu bù hǎo', '[]'::jsonb, 'Gợi ý Pinyin: Wǒ jīngcháng juéde tóuyūn, chī shénme dōu guòmǐn. Zuìjìn wèikǒu hé shuìmián dōu bù hǎo.', 'Tôi hay bị chóng mặt, ăn gì cũng bị dị ứng. Dạo này ăn uống và giấc ngủ đều kém. → 我经常觉得头晕，吃什么都过敏。 最近胃口和睡眠都不好。 (Wǒ jīngcháng juéde tóuyūn, chī shénme dōu guòmǐn. Zuìjìn wèikǒu hé shuìmián dōu bù hǎo.)', 10) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr21_vi_exp_7', 'lesson-21', 'vi_to_zh', 'Được rồi, bây giờ chúng tôi sẽ kiểm tra cho bạn.', NULL, NULL, '好的，我们现在给你检查检查。', NULL, 'hǎo de wǒmen xiànzài gěi nǐ jiǎnchá jiǎnchá', '[]'::jsonb, 'Gợi ý Pinyin: Hǎo de，wǒmen xiànzài gěi nǐ jiǎnchá jiǎnchá.', 'Được rồi, bây giờ chúng tôi sẽ kiểm tra cho bạn. → 好的，我们现在给你检查检查。 (Hǎo de，wǒmen xiànzài gěi nǐ jiǎnchá jiǎnchá.)', 11) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr21_vi_exp_8', 'lesson-21', 'vi_to_zh', 'Có phải tôi mắc bệnh nặng rồi không?', NULL, NULL, '我是不是得了重病？', NULL, 'wǒ shì bu shì dé le zhòngbìng', '[]'::jsonb, 'Gợi ý Pinyin: Wǒ shì bu shì dé le zhòngbìng?', 'Có phải tôi mắc bệnh nặng rồi không? → 我是不是得了重病？ (Wǒ shì bu shì dé le zhòngbìng?)', 12) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr21_vi_exp_9', 'lesson-21', 'vi_to_zh', 'Bạn học tập và làm việc quá mệt mỏi, nên mới xuất hiện những triệu chứng như vậy.', NULL, NULL, '你学习和工作太累了， 所以才有那样的症状。', NULL, 'nǐ xuéxí hé gōngzuò tài lèi le suǒyǐ cái yǒu nàyàng de zhèngzhuàng', '[]'::jsonb, 'Gợi ý Pinyin: Nǐ xuéxí hé gōngzuò tài lèi le, suǒyǐ cái yǒu nàyàng de zhèngzhuàng.', 'Bạn học tập và làm việc quá mệt mỏi, nên mới xuất hiện những triệu chứng như vậy. → 你学习和工作太累了， 所以才有那样的症状。 (Nǐ xuéxí hé gōngzuò tài lèi le, suǒyǐ cái yǒu nàyàng de zhèngzhuàng.)', 13) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
