INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr21_zh_exp_5', 'lesson-21', 'zh_to_vi', '最好的办法是什么都不要说，保持安静！', '最好的办法是什么都不要说，保持安静！', 'Zuì hǎo de bànfǎ shì shénme dōu búyào shuō, bǎochí ānjìng!', NULL, 'Cách tốt nhất đó chính là không nói gì cả và giữ im lặng!', NULL, '["cách","tốt","nhất","đó","chính","là","không","nói","gì","cả","và","giữ","im","lặng"]'::jsonb, 'Pinyin: Zuì hǎo de bànfǎ shì shénme dōu búyào shuō, bǎochí ānjìng!', '最好的办法是什么都不要说，保持安静！ (Zuì hǎo de bànfǎ shì shénme dōu búyào shuō, bǎochí ānjìng!) nghĩa là: Cách tốt nhất đó chính là không nói gì cả và giữ im lặng!', 23) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr21_zh_exp_6', 'lesson-21', 'zh_to_vi', '你最好继续锻炼身体吧！', '你最好继续锻炼身体吧！', 'Nǐ zuì hǎo jìxù duànliàn shēntǐ ba!', NULL, 'Tốt nhất bạn nên tiếp tục rèn luyện sức khỏe đi!', NULL, '["tốt","nhất","bạn","nên","tiếp","tục","rèn","luyện","sức","khỏe","đi"]'::jsonb, 'Pinyin: Nǐ zuì hǎo jìxù duànliàn shēntǐ ba!', '你最好继续锻炼身体吧！ (Nǐ zuì hǎo jìxù duànliàn shēntǐ ba!) nghĩa là: Tốt nhất bạn nên tiếp tục rèn luyện sức khỏe đi!', 24) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr21_zh_exp_7', 'lesson-21', 'zh_to_vi', '还好我有医疗保险，费用减轻了不少，谢谢医生和护士！', '还好我有医疗保险，费用减轻了不少，谢谢医生和护士！', 'Háihǎo wǒ yǒu yīliáo bǎoxiǎn, fèiyòng jiǎnqīng le bùshǎo, xièxie yīshēng hé hùshi!', NULL, 'May quá tôi có bảo hiểm y tế nên chi phí giảm đi nhiều, cảm ơn bác sĩ và y tá!', NULL, '["may","quá","tôi","có","bảo","hiểm","tế","nên","chi","phí","giảm","đi","nhiều","cảm","ơn","bác","sĩ","và","tá"]'::jsonb, 'Pinyin: Háihǎo wǒ yǒu yīliáo bǎoxiǎn, fèiyòng jiǎnqīng le bùshǎo, xièxie yīshēng hé hùshi!', '还好我有医疗保险，费用减轻了不少，谢谢医生和护士！ (Háihǎo wǒ yǒu yīliáo bǎoxiǎn, fèiyòng jiǎnqīng le bùshǎo, xièxie yīshēng hé hùshi!) nghĩa là: May quá tôi có bảo hiểm y tế nên chi phí giảm đi nhiều, cảm ơn bác sĩ và y tá!', 25) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr21_zh_exp_8', 'lesson-21', 'zh_to_vi', '别担心，检查结果正常，没有重病，只是太累了。', '别担心，检查结果正常，没有重病，只是太累了。', 'Bié dānxīn, jiǎnchá jiéguǒ zhèngcháng, méiyǒu zhòngbìng, zhǐshì tài lèi le.', NULL, 'Đừng lo, kết quả kiểm tra bình thường, không có bệnh nặng đâu, chỉ là làm việc quá mệt thôi.', NULL, '["đừng","lo","kết","quả","kiểm","tra","bình","thường","không","có","bệnh","nặng","đâu","chỉ","là","làm","việc","quá","mệt","thôi"]'::jsonb, 'Pinyin: Bié dānxīn, jiǎnchá jiéguǒ zhèngcháng, méiyǒu zhòngbìng, zhǐshì tài lèi le.', '别担心，检查结果正常，没有重病，只是太累了。 (Bié dānxīn, jiǎnchá jiéguǒ zhèngcháng, méiyǒu zhòngbìng, zhǐshì tài lèi le.) nghĩa là: Đừng lo, kết quả kiểm tra bình thường, không có bệnh nặng đâu, chỉ là làm việc quá mệt thôi.', 26) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr21_zh_exp_9', 'lesson-21', 'zh_to_vi', '医生，我头晕、睡眠不好，对有些食物还会过敏。', '医生，我头晕、睡眠不好，对有些食物还会过敏。', 'Yīshēng, wǒ tóuyūn, shuìmián bù hǎo, duì yǒuxiē shíwù hái huì guòmǐn.', NULL, 'Thưa bác sĩ, tôi bị chóng mặt, ngủ không ngon giấc, lại còn dị ứng với vài món ăn.', NULL, '["thưa","bác","sĩ","tôi","bị","chóng","mặt","ngủ","không","ngon","giấc","lại","còn","dị","ứng","với","vài","món","ăn"]'::jsonb, 'Pinyin: Yīshēng, wǒ tóuyūn, shuìmián bù hǎo, duì yǒuxiē shíwù hái huì guòmǐn.', '医生，我头晕、睡眠不好，对有些食物还会过敏。 (Yīshēng, wǒ tóuyūn, shuìmián bù hǎo, duì yǒuxiē shíwù hái huì guòmǐn.) nghĩa là: Thưa bác sĩ, tôi bị chóng mặt, ngủ không ngon giấc, lại còn dị ứng với vài món ăn.', 27) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
