INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq21_13', 'lesson-21', NULL, 'expanded_quiz', 'radical', NULL, NULL, 'Chữ Hán “医院” chứa bộ thủ nào sau đây?', '["尤/尢 (Uông) (Đặc biệt, khuyết tật)","气 (Khí) (Hơi thở, không khí, thời tiết)","匚 (Phương) (Hộp đựng, vật chứa)","耳 (Nhĩ) (Cái tai, lắng nghe)"]'::jsonb, 2, 'Chữ “医院” có bộ chính 匚 (Phương) (Hộp đựng, vật chứa). Chiết tự: 医: 匚 (Phương: hộp đựng dụng cụ) + 矢 (Thỉ: mũi tên chữa thương) • 院: 阝 (Phụ: tường thành) + 完 (Hoàn: khu nhà khép kín)', 13) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq21_14', 'lesson-21', NULL, 'expanded_quiz', 'radical', NULL, NULL, 'Chữ Hán “医生” chứa bộ thủ nào sau đây?', '["瓦 (Ngõa) (Ngói, đồ gốm sứ)","西/覀 (Tây) (Phương tây, che đậy)","黑 (Hắc) (Màu đen, tối tăm)","匚 (Phương) (Hộp đựng, vật chứa)"]'::jsonb, 3, 'Chữ “医生” có bộ chính 匚 (Phương) (Hộp đựng, vật chứa). Chiết tự: 医: 匚 (Phương: hộp đựng dụng cụ) + 矢 (Thỉ: mũi tên chữa thương) • 生: Bộ 生 (Sinh - mầm cây nảy từ đất, chữ độc thể)', 14) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq21_15', 'lesson-21', NULL, 'expanded_quiz', 'radical', NULL, NULL, 'Chữ Hán “护士” chứa bộ thủ nào sau đây?', '["衣/衤 (Y) (Áo quần, y phục)","黄 (Hoàng) (Màu vàng)","手/扌 (Thủ) (Bàn tay, động tác, thao tác)","夕 (Tịch) (Buổi chiều tối, đêm tối)"]'::jsonb, 2, 'Chữ “护士” có bộ chính 手/扌 (Thủ) (Bàn tay, động tác, thao tác). Chiết tự: 护: 扌 (Thủ: bàn tay) + 户 (Hộ: che chở bảo vệ) • 士: Bộ 士 (Sĩ - nét trên dài hơn nét dưới, người có học)', 15) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq21_16', 'lesson-21', NULL, 'expanded_quiz', 'radical', NULL, NULL, 'Chữ Hán “病人” chứa bộ thủ nào sau đây?', '["疒 (Nạch) (Bệnh tật, đau ốm, sức khỏe)","矢 (Thỉ) (Mũi tên, thẳng thắn, hiểu biết)","辶 (Sước) (Bước đi, di chuyển, khoảng cách)","亠 (Đầu) (Nóc, đỉnh đầu)"]'::jsonb, 0, 'Chữ “病人” có bộ chính 疒 (Nạch) (Bệnh tật, đau ốm, sức khỏe). Chiết tự: 病: 疒 (Nạch: nằm giường bệnh) + 丙 (Bính) • 人: Bộ 人 (Nhân - dáng người đứng bước, chữ độc thể)', 16) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq21_17', 'lesson-21', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, '[Ôn tập Bài 10] Từ đã học “上网” (shàngwǎng) có nghĩa là gì?', '["giảm","ho","lên mạng","đôi (đũa, dép,...)"]'::jsonb, 2, 'Ôn tập Bài 10: “上网” (shàngwǎng) nghĩa là: lên mạng.', 17) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq21_18', 'lesson-21', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, '[Ôn tập Bài 18] Từ đã học “颐和园” (Yíhéyuán) có nghĩa là gì?', '["bác sĩ","trẻ tuổi","Di Hòa Viên","bao nhiêu"]'::jsonb, 2, 'Ôn tập Bài 18: “颐和园” (Yíhéyuán) nghĩa là: Di Hòa Viên.', 18) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq21_19', 'lesson-21', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, '[Ôn tập Bài 6] Từ đã học “东边” (dōngbian) có nghĩa là gì?', '["Việt Nam","quen biết, biết","sách vở (nói chung)","hướng đông"]'::jsonb, 3, 'Ôn tập Bài 6: “东边” (dōngbian) nghĩa là: hướng đông.', 19) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq21_20', 'lesson-21', NULL, 'expanded_quiz', 'reading', NULL, NULL, '[Mở rộng] Câu “最近我常常头晕，胃口和睡眠都不太好。” có nghĩa tiếng Việt là gì?', '["Bạn cố gắng như vậy, nhất định rất mệt nhỉ?","Mẹ ơi, sau khi làm xong bài tập về nhà con có thể xem phim không ạ?","Cách tốt nhất đó chính là không nói gì cả và giữ im lặng!","Dạo này tôi hay bị chóng mặt, ăn uống và giấc ngủ đều không tốt lắm."]'::jsonb, 3, '最近我常常头晕，胃口和睡眠都不太好。 (Zuìjìn wǒ chángcháng tóuyūn, wèikǒu hé shuìmián dōu bú tài hǎo.) → Dạo này tôi hay bị chóng mặt, ăn uống và giấc ngủ đều không tốt lắm.', 20) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq21_21', 'lesson-21', NULL, 'expanded_quiz', 'reading', NULL, NULL, '[Đọc hiểu mở rộng] Đọc đoạn hội thoại:
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq21_22', 'lesson-21', NULL, 'expanded_quiz', 'reading', NULL, NULL, 'Câu “你多运动运动吧！” có nghĩa tiếng Việt là gì?', '["Con vận động nhiều hơn đi!","Cậu có thể rót cho tớ cốc nước không?","Chắc là cô đấy không đến nữa.","Trời có thể sắp mưa."]'::jsonb, 0, '你多运动运动吧！ (Nǐ duō yùndòng yùndòng ba!) → Con vận động nhiều hơn đi!', 22) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct21_1', 'lesson-21', NULL, 'comprehensive_test', 'listening', '如果有医疗保险，看病费用可以减少很多。', NULL, 'Nghe đoạn ghi âm và chọn nghĩa tiếng Việt đúng:', '["Nếu có bảo hiểm y tế, chi phí khám bệnh có thể giảm đi rất nhiều.","Hôm nay chắc sẽ mưa đấy nhỉ.","Đúng vậy, Tết Nguyên Đán là một ngày lễ truyền thống quan trọng của Trung Quốc.","Chào mừng mọi người đến nhà mình chơi! Mời ngồi tự nhiên nhé!"]'::jsonb, 0, 'Nội dung nghe được: “如果有医疗保险，看病费用可以减少很多。” → Nếu có bảo hiểm y tế, chi phí khám bệnh có thể giảm đi rất nhiều.', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct21_2', 'lesson-21', NULL, 'comprehensive_test', 'listening', '你知道他在哪儿吗？', NULL, 'Nghe đoạn ghi âm và chọn câu tiếng Trung khớp với nội dung vừa nghe:', '["你买吧！","你问上午还是下午？上午六点我去图书馆学习，下午跟 山本同学、马克同学到张风家。","好的。 我陪你去看病。","你知道他在哪儿吗？"]'::jsonb, 3, 'Câu vừa đọc: “你知道他在哪儿吗？” (Nǐ zhīdào tā zài nǎr ma?) → Bạn biết anh ấy ở đâu không?', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct21_3', 'lesson-21', NULL, 'comprehensive_test', 'listening', '你有什么症状？', NULL, 'Nghe đoạn ghi âm và chọn nghĩa tiếng Việt đúng:', '["Sở thích của ông nội là buổi sáng đọc báo và uống trà.","Ngày mai chúng tôi sẽ đi leo núi.","A Minh, mình thấy sáng nào cậu cũng chạy bộ, cậu có thường xuyên rèn luyện sức khỏe không?","Bạn có triệu chứng gì?"]'::jsonb, 3, 'Nội dung nghe được: “你有什么症状？” (Nǐ yǒu shénme zhèngzhuàng?) → Bạn có triệu chứng gì?', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct21_4', 'lesson-21', NULL, 'comprehensive_test', 'listening', '还好我有医疗保险，费用减轻了不少，谢谢医生和护士！', NULL, 'Nghe đoạn ghi âm và chọn câu tiếng Trung khớp với nội dung vừa nghe:', '["后面的那座楼是宿舍，食堂在宿舍的左边。","还好我有医疗保险，费用减轻了不少，谢谢医生和护士！","你以后得戒除冰水了。我已经去药店给你买了药和一碗肉粥。","我来自越南。"]'::jsonb, 1, 'Câu vừa đọc: “还好我有医疗保险，费用减轻了不少，谢谢医生和护士！” (Háihǎo wǒ yǒu yīliáo bǎoxiǎn, fèiyòng jiǎnqīng le bùshǎo, xièxie yīshēng hé hùshi!) → May quá tôi có bảo hiểm y tế nên chi phí giảm đi nhiều, cảm ơn bác sĩ và y tá!', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct21_5', 'lesson-21', NULL, 'comprehensive_test', 'listening', '马克，我下午想去医院检查身体， 你可以陪我去吗？', NULL, 'Nghe đoạn ghi âm và chọn nghĩa tiếng Việt đúng:', '["Mark, chiều nay tôi muốn đi bệnh viện kiểm tra sức khỏe, bạn đi cùng tôi được không?","Chiều nay có tiết học, cậu thế này chắc chắn không đi học được rồi. Tốt nhất là về nhà nghỉ ngơi đi!","Cô ơi, cho cháu hỏi dưa hấu và thanh long bán thế nào ạ?","Ngày kia sẽ có tuyết rơi lớn, các cậu ra ngoài chơi nhớ mặc thêm áo khoác nhé!"]'::jsonb, 0, 'Nội dung nghe được: “马克，我下午想去医院检查身体， 你可以陪我去吗？” (Mǎkè, wǒ xiàwǔ xiǎng qù yīyuàn jiǎnchá shēntǐ, nǐ kěyǐ péi wǒ qù ma?) → Mark, chiều nay tôi muốn đi bệnh viện kiểm tra sức khỏe, bạn đi cùng tôi được không?', 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct21_6', 'lesson-21', NULL, 'comprehensive_test', 'listening', '好的，我们现在给你检查检查。', NULL, 'Nghe đoạn ghi âm và chọn câu tiếng Trung khớp với nội dung vừa nghe:', '["你得多锻炼了。","好的，我们现在给你检查检查。","妈妈，做完作业以后，我可以看电影吗？","我叫陈英。"]'::jsonb, 1, 'Câu vừa đọc: “好的，我们现在给你检查检查。” (Hǎo de，wǒmen xiànzài gěi nǐ jiǎnchá jiǎnchá.) → Được rồi, bây giờ chúng tôi sẽ kiểm tra cho bạn.', 6) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct21_7', 'lesson-21', NULL, 'comprehensive_test', 'listening', '其实没有什么要紧的。 我让护士给你打个针并开给你一个处方，你回家吃完饭再吃药和多喝水，过几天身体就恢复了。', NULL, 'Nghe đoạn ghi âm và chọn nghĩa tiếng Việt đúng:', '["Bố tớ cũng rất thích đọc sách, lúc rảnh rỗi ông thường kể chuyện cho tớ và em trai nghe. Em trai cậu thích gì?","Thực ra không có gì nghiêm trọng đâu. Tôi bảo y tá tiêm cho bạn một mũi và kê đơn thuốc, bạn về nhà ăn cơm xong uống thuốc và uống nhiều nước, vài ngày sau sức khỏe sẽ hồi phục thôi.","Nhật Minh, vị này là bạn tôi, cậu ấy tên là Mark.","Có, nhà ăn nằm ở bên phải tòa nhà giảng đường."]'::jsonb, 1, 'Nội dung nghe được: “其实没有什么要紧的。 我让护士给你打个针并开给你一个处方，你回家吃完饭再吃药和多喝水，过几天身体就恢复了。” (Qíshí méiyǒu shénme yàojǐn de. Wǒ ràng hùshì gěi nǐ dǎ gè zhēn bìng kāi gěi nǐ yí gè chǔfāng, nǐ huí jiā chī wán fàn zài chī yào hé duō hē shuǐ, guò jǐ tiān shēntǐ jiù huīfù le.) → Thực ra không có gì nghiêm trọng đâu. Tôi bảo y tá tiêm cho bạn một mũi và kê đơn thuốc, bạn về nhà ăn cơm xong uống thuốc và uống nhiều nước, vài ngày sau sức khỏe sẽ hồi phục thôi.', 7) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
