INSERT INTO lessons (id, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id) VALUES ('lesson-22', 'Bài 22: Thích nghi - Đơn nguyên 7: Du học Trung Quốc', 'Bài 22', 'Đơn nguyên 7: Du học Trung Quốc', 'Cuộc sống mới tại trường đại học Trung Quốc, giải tỏa áp lực, kết bạn và thích nghi văn hóa.', '2026-11-14'::date, 22, TRUE, NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, date_added = EXCLUDED.date_added, sort_order = EXCLUDED.sort_order, is_system = TRUE, updated_at = NOW();
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v22_1', 'lesson-22', '压力', 'yālì', 'lực', 'áp lực', 'Danh từ', '厂 (Hán) (Vách đá, mái che, công xưởng)', '压: 厂 (Hán: vách đá) + 土 (Thổ) + 丶 (đè nặng xuống) • 力: Bộ 力 (Lực - bắp tay/cái cày thể hiện sức mạnh, chữ độc thể)', 'Ghép 压 [bộ 厂] + 力 [bộ 力] để nhớ từ 压力 (yālì): "áp lực".', '都是留学生经常遇到的困难，比如文化不同、生活环境不同等等。我们留学生的压力很大。', 'Dōu shì liúxuéshēng jīngcháng yùdào de kùnnan, bǐrú wénhuà bùtóng, shēnghuó huánjìng bùtóng děngděng. Wǒmen liúxuéshēng de yālì hěn dà.', 'Đều là những khó khăn mà du học sinh hay gặp phải thôi, như khác biệt văn hóa, môi trường sống khác nhau, v.v. Áp lực của du học sinh bọn tớ lớn lắm.', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v22_2', 'lesson-22', '困难', 'kùnnan', 'từ Hán ngữ', 'khó khăn', 'Danh từ', '囗 (Vi) (Vây quanh, không gian kín, lãnh thổ)', '困: 囗 (Vi: vây kín) + 木 (Mộc: cây bị nhốt trong khung là khốn khó) • 难: 又 (Hựu) + 隹 (Chuy)', 'Ghép 困 [bộ 囗] + 难 [bộ 隹] để nhớ từ 困难 (kùnnan): "khó khăn".', '怎么了？你还有什么困难，告诉我吧！我会帮你解决。', 'Zěnmele? Nǐ hái yǒu shén me kùnnan, gàosù wǒ ba! Wǒ huì bāng nǐ jiějué.', 'Sao vậy? Cậu còn gặp khó khăn gì cứ nói với tớ! Tớ sẽ giúp cậu giải quyết.', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v22_3', 'lesson-22', '问题', 'wèntí', 'vấn', 'vấn đề, câu hỏi', 'Danh từ', '门 (Môn) (Cánh cửa, lối ra vào)', '问: 门 (Môn: cánh cửa) + 口 (Khẩu: mở miệng hỏi ngoài cửa) • 题: 是 (Thị) + 页 (Hiệt: trán, đầu đề câu hỏi)', 'Ghép 问 [bộ 门] + 题 [bộ 页] để nhớ từ 问题 (wèntí): "vấn đề, câu hỏi".', '那些困难我都能自己适应，自己解决。最糟糕的要说到学习问题。刚来中国的时候，因为不习惯这里的学习方法，所以我做什么事都很难。虽然在国内已经学汉语了，但是到中国以后，有很多时候你们说的我听不懂。考试又有很多，要抓紧时间练习。我一点儿也不习惯，哭了很多次。', 'Nàxiē kùnnan wǒ dōu néng zìjǐ shìyìng, zìjǐ jiějué. Zuì zāogāo de yāo shuō dào xuéxí wèntí. Gāng lái Zhōngguó de shíhou, yīn wèi bù xíguàn zhèli de xuéxí fāngfǎ, suǒ yǐ wǒ zuò shénme shì dōu hěn nán. Suīrán zài guónèi yǐjīng xué Hànyǔ le, dànshì dào Zhōngguó yǐhòu, yǒu hěnduō shíhou nǐmen shuō de wǒ tīng bù dǒng. Kǎoshì yòu yǒu hěnduō, yào zhuā jǐn shíjiān liànxí. Wǒ yīdiǎnr yě bù xíguàn, kūle hěnduō cì.', 'Những khó khăn đó tớ đều có thể tự thích nghi và tự giải quyết. Tệ nhất phải nói đến chuyện học tập. Hồi mới sang Trung Quốc, vì chưa quen phương pháp học ở đây nên làm việc gì cũng thấy khó. Dù ở trong nước đã học tiếng Trung rồi, nhưng sang đây có nhiều lúc các bạn nói tớ nghe không hiểu. Thi cử lại nhiều, phải tranh thủ thời gian luyện tập. Tớ chẳng quen chút nào, đã khóc rất nhiều lần.', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v22_4', 'lesson-22', '方法', 'fāngfǎ', 'Pháp', 'phương pháp, cách làm', 'Danh từ', '方 (Phương) (Vuông vức, phương hướng)', '方: Bộ 方 (Phương - hình vuông, phương hướng) • 法: 氵 (Thủy: dòng nước phẳng bằng) + 去 (Khứ: phép tắc, phương pháp)', 'Ghép 方 [bộ 方] + 法 [bộ 氵] để nhớ từ 方法 (fāngfǎ): "phương pháp, cách làm".', '那些困难我都能自己适应，自己解决。最糟糕的要说到学习问题。刚来中国的时候，因为不习惯这里的学习方法，所以我做什么事都很难。虽然在国内已经学汉语了，但是到中国以后，有很多时候你们说的我听不懂。考试又有很多，要抓紧时间练习。我一点儿也不习惯，哭了很多次。', 'Nàxiē kùnnan wǒ dōu néng zìjǐ shìyìng, zìjǐ jiějué. Zuì zāogāo de yāo shuō dào xuéxí wèntí. Gāng lái Zhōngguó de shíhou, yīn wèi bù xíguàn zhèli de xuéxí fāngfǎ, suǒ yǐ wǒ zuò shénme shì dōu hěn nán. Suīrán zài guónèi yǐjīng xué Hànyǔ le, dànshì dào Zhōngguó yǐhòu, yǒu hěnduō shíhou nǐmen shuō de wǒ tīng bù dǒng. Kǎoshì yòu yǒu hěnduō, yào zhuā jǐn shíjiān liànxí. Wǒ yīdiǎnr yě bù xíguàn, kūle hěnduō cì.', 'Những khó khăn đó tớ đều có thể tự thích nghi và tự giải quyết. Tệ nhất phải nói đến chuyện học tập. Hồi mới sang Trung Quốc, vì chưa quen phương pháp học ở đây nên làm việc gì cũng thấy khó. Dù ở trong nước đã học tiếng Trung rồi, nhưng sang đây có nhiều lúc các bạn nói tớ nghe không hiểu. Thi cử lại nhiều, phải tranh thủ thời gian luyện tập. Tớ chẳng quen chút nào, đã khóc rất nhiều lần.', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v22_5', 'lesson-22', '气候', 'qìhòu', 'khí hậu', 'khí hậu', 'Danh từ', '气 (Khí) (Hơi thở, không khí, thời tiết)', '气: Bộ 气 (Khí - làn hơi bốc lên, chữ độc thể) • 候: 亻 (Nhân đứng) + 丨 + 矢 (Thỉ)', 'Ghép 气 [bộ 气] + 候 [bộ 亻] để nhớ từ 气候 (qìhòu): "khí hậu".', '你还没习惯这里的气候吗？', 'Nǐ hái méi xíguàn zhèli de qìhòu ma?', 'Cậu vẫn chưa quen với khí hậu ở đây à?', 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v22_6', 'lesson-22', '环境', 'huánjìng', 'từ Hán ngữ', 'môi trường, hoàn cảnh', 'Danh từ', '玉/王 (Ngọc) (Đá quý, vua chúa)', '环: 王 (Ngọc: vòng ngọc tròn) + 不 (Bất) • 境: 土 (Thổ: vùng đất) + 竟 (Cánh: ranh giới, hoàn cảnh)', 'Ghép 环 [bộ 王] + 境 [bộ 土] để nhớ từ 环境 (huánjìng): "môi trường, hoàn cảnh".', '都是留学生经常遇到的困难，比如文化不同、生活环境不同等等。我们留学生的压力很大。', 'Dōu shì liúxuéshēng jīngcháng yùdào de kùnnan, bǐrú wénhuà bùtóng, shēnghuó huánjìng bùtóng děngděng. Wǒmen liúxuéshēng de yālì hěn dà.', 'Đều là những khó khăn mà du học sinh hay gặp phải thôi, như khác biệt văn hóa, môi trường sống khác nhau, v.v. Áp lực của du học sinh bọn tớ lớn lắm.', 6) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v22_7', 'lesson-22', '以前', 'yǐqián', 'tiền', 'trước, lúc trước', 'Danh từ', '人/亻 (Nhân) (Con người, nhân loại, hành động)', '以: 乚 + 丶 + 人 (Nhân) • 前: 丷 + 一 + 月 (Nguyệt/Thuyền) + 刂 (Đao)', 'Ghép 以 [bộ 人] + 前 [bộ 刂] để nhớ từ 以前 (yǐqián): "trước, lúc trước".', '其实这些事我出国以前我奶奶已经跟我说了。她年轻的时候也去国外留学，很有经验。', 'Qíshí zhèxiē shì wǒ chūguó yǐqián wǒ nǎinai yǐjīng gēn wǒ shuō le. Tā niánqīng de shíhou yě qù guówài liúxué, hěn yǒu jīngyàn.', 'Thực ra những chuyện này trước khi ra nước ngoài bà nội tớ đã dặn dò tớ hết rồi. Thời trẻ bà cũng từng đi du học nên rất có kinh nghiệm.', 7) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v22_8', 'lesson-22', '以后', 'yǐhòu', 'hậu', 'sau, lúc sau', 'Danh từ', '人/亻 (Nhân) (Con người, nhân loại, hành động)', '以: 乚 + 丶 + 人 (Nhân) • 后: 厂 + 一 + 口 (Khẩu: phía sau)', 'Ghép 以 [bộ 人] + 后 [bộ 口] để nhớ từ 以后 (yǐhòu): "sau, lúc sau".', '那些困难我都能自己适应，自己解决。最糟糕的要说到学习问题。刚来中国的时候，因为不习惯这里的学习方法，所以我做什么事都很难。虽然在国内已经学汉语了，但是到中国以后，有很多时候你们说的我听不懂。考试又有很多，要抓紧时间练习。我一点儿也不习惯，哭了很多次。', 'Nàxiē kùnnan wǒ dōu néng zìjǐ shìyìng, zìjǐ jiějué. Zuì zāogāo de yāo shuō dào xuéxí wèntí. Gāng lái Zhōngguó de shíhou, yīn wèi bù xíguàn zhèli de xuéxí fāngfǎ, suǒ yǐ wǒ zuò shénme shì dōu hěn nán. Suīrán zài guónèi yǐjīng xué Hànyǔ le, dànshì dào Zhōngguó yǐhòu, yǒu hěnduō shíhou nǐmen shuō de wǒ tīng bù dǒng. Kǎoshì yòu yǒu hěnduō, yào zhuā jǐn shíjiān liànxí. Wǒ yīdiǎnr yě bù xíguàn, kūle hěnduō cì.', 'Những khó khăn đó tớ đều có thể tự thích nghi và tự giải quyết. Tệ nhất phải nói đến chuyện học tập. Hồi mới sang Trung Quốc, vì chưa quen phương pháp học ở đây nên làm việc gì cũng thấy khó. Dù ở trong nước đã học tiếng Trung rồi, nhưng sang đây có nhiều lúc các bạn nói tớ nghe không hiểu. Thi cử lại nhiều, phải tranh thủ thời gian luyện tập. Tớ chẳng quen chút nào, đã khóc rất nhiều lần.', 8) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v22_9', 'lesson-22', '家乡', 'jiāxiāng', 'gia', 'quê hương', 'Danh từ', '宀 (Miên) (Mái nhà, che chở, nơi ở)', '家: 宀 (Miên: mái nhà) + 豕 (Thỉ: lợn nuôi dưới mái nhà) • 乡: 𠂋 + 𠂋 + 丿 (quê hương)', 'Ghép 家 [bộ 宀] + 乡 [bộ 乙] để nhớ từ 家乡 (jiāxiāng): "quê hương".', '还没习惯，因为我家乡冬天不太冷，也不下雪。', 'Hái méi xíguàn, yīnwèi wǒ jiāxiāng dōngtiān bú tài lěng, yě bú xià xuě.', 'Vẫn chưa quen, vì mùa đông quê tớ không quá lạnh, cũng không có tuyết rơi.', 9) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v22_10', 'lesson-22', '年纪', 'niánjì', 'niên', 'tuổi, tuổi tác', 'Danh từ', '干 (Can) (Can thiệp, khô ráo, làm việc)', '年: 𠂉 + 干/土 (mùa màng thu hoạch một năm) • 纪: 纟 (Mịch: đầu mối sợi tơ) + 己 (Kỷ)', 'Ghép 年 [bộ 干] + 纪 [bộ 纟] để nhớ từ 年纪 (niánjì): "tuổi, tuổi tác".', '您今年多大年纪？', 'Nín jīnnián duōdà niánjì?', 'Năm nay bác bao nhiêu tuổi rồi ạ?', 10) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v22_11', 'lesson-22', '出国', 'chūguó', 'quốc', 'ra nước ngoài', 'Động từ', '凵 (Khảm) (Há miệng, hố trũng)', '出: 山 (Sơn) chồng hai tầng bước ra ngoài • 国: 囗 (Vi: biên giới) + 玉 (Ngọc: báu vật quốc gia)', 'Ghép 出 [bộ 凵] + 国 [bộ 囗] để nhớ từ 出国 (chūguó): "ra nước ngoài".', '我也希望是这样。出国留学真是不容易啊！', 'Wǒ yě xīwàng shì zhèyàng. Chūguó liúxué zhēnshì bù róngyì a!', 'Tớ cũng hy vọng là thế. Đi du học nước ngoài thật sự không dễ dàng chút nào!', 11) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v22_12', 'lesson-22', '遇到', 'yù dào', 'đáo', 'gặp phải', 'Động từ', '辶 (Sước) (Bước đi, di chuyển, khoảng cách)', '遇: 禺 (Ngu) + 辶 (Sước: đi trên đường gặp gỡ) • 到: 至 (Chí: đi tới) + 刂 (Đao)', 'Ghép 遇 [bộ 辶] + 到 [bộ 刂] để nhớ từ 遇到 (yù dào): "gặp phải".', '都是留学生经常遇到的困难，比如文化不同、生活环境不同等等。我们留学生的压力很大。', 'Dōu shì liúxuéshēng jīngcháng yùdào de kùnnan, bǐrú wénhuà bùtóng, shēnghuó huánjìng bùtóng děngděng. Wǒmen liúxuéshēng de yālì hěn dà.', 'Đều là những khó khăn mà du học sinh hay gặp phải thôi, như khác biệt văn hóa, môi trường sống khác nhau, v.v. Áp lực của du học sinh bọn tớ lớn lắm.', 12) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v22_13', 'lesson-22', '适应', 'shìyìng', 'thích ứng', 'thích nghi, thích ứng', 'Động từ', '辶 (Sước) (Bước đi, di chuyển, khoảng cách)', '适: 舌 (Thiệt) + 辶 (Sước: đi đến nơi phù hợp) • 应: 广 (Nghiễm) + ⺍ + 一 (ứng đáp)', 'Ghép 适 [bộ 辶] + 应 [bộ 广] để nhớ từ 适应 (shìyìng): "thích nghi, thích ứng".', '那些困难我都能自己适应，自己解决。最糟糕的要说到学习问题。刚来中国的时候，因为不习惯这里的学习方法，所以我做什么事都很难。虽然在国内已经学汉语了，但是到中国以后，有很多时候你们说的我听不懂。考试又有很多，要抓紧时间练习。我一点儿也不习惯，哭了很多次。', 'Nàxiē kùnnan wǒ dōu néng zìjǐ shìyìng, zìjǐ jiějué. Zuì zāogāo de yāo shuō dào xuéxí wèntí. Gāng lái Zhōngguó de shíhou, yīn wèi bù xíguàn zhèli de xuéxí fāngfǎ, suǒ yǐ wǒ zuò shénme shì dōu hěn nán. Suīrán zài guónèi yǐjīng xué Hànyǔ le, dànshì dào Zhōngguó yǐhòu, yǒu hěnduō shíhou nǐmen shuō de wǒ tīng bù dǒng. Kǎoshì yòu yǒu hěnduō, yào zhuā jǐn shíjiān liànxí. Wǒ yīdiǎnr yě bù xíguàn, kūle hěnduō cì.', 'Những khó khăn đó tớ đều có thể tự thích nghi và tự giải quyết. Tệ nhất phải nói đến chuyện học tập. Hồi mới sang Trung Quốc, vì chưa quen phương pháp học ở đây nên làm việc gì cũng thấy khó. Dù ở trong nước đã học tiếng Trung rồi, nhưng sang đây có nhiều lúc các bạn nói tớ nghe không hiểu. Thi cử lại nhiều, phải tranh thủ thời gian luyện tập. Tớ chẳng quen chút nào, đã khóc rất nhiều lần.', 13) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v22_14', 'lesson-22', '练习', 'liànxí', 'luyện tập', 'luyện tập', 'Động từ', '糸/纟 (Mịch) (Sợi tơ, gắn kết, màu sắc)', '练: 纟 (Mịch: sợi tơ) + 东 biến thể (rèn luyện) • 习: 乛 (cánh chim) + 冫 (chim non tập bay nhiều lần)', 'Ghép 练 [bộ 纟] + 习 [bộ 乙] để nhớ từ 练习 (liànxí): "luyện tập".', '那些困难我都能自己适应，自己解决。最糟糕的要说到学习问题。刚来中国的时候，因为不习惯这里的学习方法，所以我做什么事都很难。虽然在国内已经学汉语了，但是到中国以后，有很多时候你们说的我听不懂。考试又有很多，要抓紧时间练习。我一点儿也不习惯，哭了很多次。', 'Nàxiē kùnnan wǒ dōu néng zìjǐ shìyìng, zìjǐ jiějué. Zuì zāogāo de yāo shuō dào xuéxí wèntí. Gāng lái Zhōngguó de shíhou, yīn wèi bù xíguàn zhèli de xuéxí fāngfǎ, suǒ yǐ wǒ zuò shénme shì dōu hěn nán. Suīrán zài guónèi yǐjīng xué Hànyǔ le, dànshì dào Zhōngguó yǐhòu, yǒu hěnduō shíhou nǐmen shuō de wǒ tīng bù dǒng. Kǎoshì yòu yǒu hěnduō, yào zhuā jǐn shíjiān liànxí. Wǒ yīdiǎnr yě bù xíguàn, kūle hěnduō cì.', 'Những khó khăn đó tớ đều có thể tự thích nghi và tự giải quyết. Tệ nhất phải nói đến chuyện học tập. Hồi mới sang Trung Quốc, vì chưa quen phương pháp học ở đây nên làm việc gì cũng thấy khó. Dù ở trong nước đã học tiếng Trung rồi, nhưng sang đây có nhiều lúc các bạn nói tớ nghe không hiểu. Thi cử lại nhiều, phải tranh thủ thời gian luyện tập. Tớ chẳng quen chút nào, đã khóc rất nhiều lần.', 14) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v22_15', 'lesson-22', '懂', 'dǒng', 'từ Hán ngữ', 'hiểu', 'Động từ', '心/忄 (Tâm) (Trái tim, tình cảm, suy nghĩ, tâm lý)', '懂 = 忄 (Tâm đứng: tâm trí) + 董 (Đổng: hiểu thấu).', 'Chữ 懂 (dǒng) mang nghĩa "hiểu", bộ chính 心/忄 (Tâm); cấu tạo: 忄 (Tâm đứng: tâm trí) + 董 (Đổng: hiểu thấu).', '那些困难我都能自己适应，自己解决。最糟糕的要说到学习问题。刚来中国的时候，因为不习惯这里的学习方法，所以我做什么事都很难。虽然在国内已经学汉语了，但是到中国以后，有很多时候你们说的我听不懂。考试又有很多，要抓紧时间练习。我一点儿也不习惯，哭了很多次。', 'Nàxiē kùnnan wǒ dōu néng zìjǐ shìyìng, zìjǐ jiějué. Zuì zāogāo de yāo shuō dào xuéxí wèntí. Gāng lái Zhōngguó de shíhou, yīn wèi bù xíguàn zhèli de xuéxí fāngfǎ, suǒ yǐ wǒ zuò shénme shì dōu hěn nán. Suīrán zài guónèi yǐjīng xué Hànyǔ le, dànshì dào Zhōngguó yǐhòu, yǒu hěnduō shíhou nǐmen shuō de wǒ tīng bù dǒng. Kǎoshì yòu yǒu hěnduō, yào zhuā jǐn shíjiān liànxí. Wǒ yīdiǎnr yě bù xíguàn, kūle hěnduō cì.', 'Những khó khăn đó tớ đều có thể tự thích nghi và tự giải quyết. Tệ nhất phải nói đến chuyện học tập. Hồi mới sang Trung Quốc, vì chưa quen phương pháp học ở đây nên làm việc gì cũng thấy khó. Dù ở trong nước đã học tiếng Trung rồi, nhưng sang đây có nhiều lúc các bạn nói tớ nghe không hiểu. Thi cử lại nhiều, phải tranh thủ thời gian luyện tập. Tớ chẳng quen chút nào, đã khóc rất nhiều lần.', 15) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v22_16', 'lesson-22', '哭', 'kū', 'từ Hán ngữ', 'khóc', 'Động từ', '口 (Khẩu) (Miệng, ăn uống, lời nói, âm thanh phát ra)', '哭 = 口 + 口 (hai mắt) + 犬 (Khuyển: khóc nức nở).', 'Chữ 哭 (kū) mang nghĩa "khóc", bộ chính 口 (Khẩu); cấu tạo: 口 + 口 (hai mắt) + 犬 (Khuyển: khóc nức nở).', '那些困难我都能自己适应，自己解决。最糟糕的要说到学习问题。刚来中国的时候，因为不习惯这里的学习方法，所以我做什么事都很难。虽然在国内已经学汉语了，但是到中国以后，有很多时候你们说的我听不懂。考试又有很多，要抓紧时间练习。我一点儿也不习惯，哭了很多次。', 'Nàxiē kùnnan wǒ dōu néng zìjǐ shìyìng, zìjǐ jiějué. Zuì zāogāo de yāo shuō dào xuéxí wèntí. Gāng lái Zhōngguó de shíhou, yīn wèi bù xíguàn zhèli de xuéxí fāngfǎ, suǒ yǐ wǒ zuò shénme shì dōu hěn nán. Suīrán zài guónèi yǐjīng xué Hànyǔ le, dànshì dào Zhōngguó yǐhòu, yǒu hěnduō shíhou nǐmen shuō de wǒ tīng bù dǒng. Kǎoshì yòu yǒu hěnduō, yào zhuā jǐn shíjiān liànxí. Wǒ yīdiǎnr yě bù xíguàn, kūle hěnduō cì.', 'Những khó khăn đó tớ đều có thể tự thích nghi và tự giải quyết. Tệ nhất phải nói đến chuyện học tập. Hồi mới sang Trung Quốc, vì chưa quen phương pháp học ở đây nên làm việc gì cũng thấy khó. Dù ở trong nước đã học tiếng Trung rồi, nhưng sang đây có nhiều lúc các bạn nói tớ nghe không hiểu. Thi cử lại nhiều, phải tranh thủ thời gian luyện tập. Tớ chẳng quen chút nào, đã khóc rất nhiều lần.', 16) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v22_17', 'lesson-22', '希望', 'xīwàng', 'hy vọng', 'hi vọng, mong, niềm hi vọng', 'Động từ / Danh từ', '巾 (Cân) (Khăn vải, mũ nón, vải vóc)', '希: 乂 (Ngải) + 布 biến thể (mong ước) • 望: 亡 (Vong) + 月 (Nguyệt: ngắm trăng) + 王 (Vương: mong ngóng)', 'Ghép 希 [bộ 巾] + 望 [bộ 月] để nhớ từ 希望 (xīwàng): "hi vọng, mong, niềm hi vọng".', '我也希望是这样。出国留学真是不容易啊！', 'Wǒ yě xīwàng shì zhèyàng. Chūguó liúxué zhēnshì bù róngyì a!', 'Tớ cũng hy vọng là thế. Đi du học nước ngoài thật sự không dễ dàng chút nào!', 17) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v22_18', 'lesson-22', '相信', 'xiāngxìn', 'từ Hán ngữ', 'tin, tin tưởng', 'Động từ', '目 (Mục) (Con mắt, nhìn ngắm, thị giác)', '相: 木 (Mộc: cây) + 目 (Mục: mắt quan sát) • 信: 亻 (Nhân đứng: người) + 言 (Ngôn: lời nói giữ chữ tín)', 'Ghép 相 [bộ 目] + 信 [bộ 亻] để nhớ từ 相信 (xiāngxìn): "tin, tin tưởng".', '没关系！我只要继续努力，相信自己就好。再说，虽然我不说，但是你们也帮助我很多。能到中国，跟你们交朋友，我很幸福。', 'Méiguānxi! Wǒ zhǐyào jìxù nǔlì, xiāngxìn zìjǐ jiù hǎo. Zàishuō, suīrán wǒ bù shuō, dànshì nǐmen yě bāngzhù wǒ hěnduō. Néng dào Zhōngguó, gēn nǐmen jiāo péngyou, wǒ hěn xìngfú.', 'Không sao đâu! Chỉ cần tớ tiếp tục cố gắng, tin vào bản thân là được. Hơn nữa, dù tớ không nói ra nhưng các bạn cũng giúp đỡ tớ rất nhiều. Được đến Trung Quốc và kết bạn với các bạn, tớ thấy rất hạnh phúc.', 18) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v22_19', 'lesson-22', '习惯', 'xíguàn', 'tập quán', 'quen , thói quen', 'Động từ / Danh từ', '乙 (Ất) (Uốn cong, số thứ tự, chồi non)', '习: 乛 (cánh chim) + 冫 (chim non tập bay nhiều lần) • 惯: 忄 (Tâm đứng: thói quen tâm lý) + 贯 (Quán: quen suốt)', 'Ghép 习 [bộ 乙] + 惯 [bộ 忄] để nhớ từ 习惯 (xíguàn): "quen , thói quen".', '你还没习惯这里的气候吗？', 'Nǐ hái méi xíguàn zhèli de qìhòu ma?', 'Cậu vẫn chưa quen với khí hậu ở đây à?', 19) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v22_20', 'lesson-22', '抓紧', 'zhuājǐn', 'từ Hán ngữ', 'nắm bắt, nắm chặt', 'Động từ', '手/扌 (Thủ) (Bàn tay, động tác, thao tác)', '抓: 扌 (Thủ: bàn tay) + 爪 (Trảo: móng vuốt nắm bắt) • 紧: 臤 (Hiền rút gọn) + 糸 (Mịch: sợi dây kéo căng)', 'Ghép 抓 [bộ 扌] + 紧 [bộ 糸] để nhớ từ 抓紧 (zhuājǐn): "nắm bắt, nắm chặt".', '那些困难我都能自己适应，自己解决。最糟糕的要说到学习问题。刚来中国的时候，因为不习惯这里的学习方法，所以我做什么事都很难。虽然在国内已经学汉语了，但是到中国以后，有很多时候你们说的我听不懂。考试又有很多，要抓紧时间练习。我一点儿也不习惯，哭了很多次。', 'Nàxiē kùnnan wǒ dōu néng zìjǐ shìyìng, zìjǐ jiějué. Zuì zāogāo de yāo shuō dào xuéxí wèntí. Gāng lái Zhōngguó de shíhou, yīn wèi bù xíguàn zhèli de xuéxí fāngfǎ, suǒ yǐ wǒ zuò shénme shì dōu hěn nán. Suīrán zài guónèi yǐjīng xué Hànyǔ le, dànshì dào Zhōngguó yǐhòu, yǒu hěnduō shíhou nǐmen shuō de wǒ tīng bù dǒng. Kǎoshì yòu yǒu hěnduō, yào zhuā jǐn shíjiān liànxí. Wǒ yīdiǎnr yě bù xíguàn, kūle hěnduō cì.', 'Những khó khăn đó tớ đều có thể tự thích nghi và tự giải quyết. Tệ nhất phải nói đến chuyện học tập. Hồi mới sang Trung Quốc, vì chưa quen phương pháp học ở đây nên làm việc gì cũng thấy khó. Dù ở trong nước đã học tiếng Trung rồi, nhưng sang đây có nhiều lúc các bạn nói tớ nghe không hiểu. Thi cử lại nhiều, phải tranh thủ thời gian luyện tập. Tớ chẳng quen chút nào, đã khóc rất nhiều lần.', 20) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v22_21', 'lesson-22', '继续', 'jìxù', 'từ Hán ngữ', 'tiếp tục', 'Động từ', '糸/纟 (Mịch) (Sợi tơ, gắn kết, màu sắc)', '继: 纟 (Mịch: sợi tơ nối dài) + 㡭 • 续: 纟 (Mịch: sợi dây nối tiếp) + 卖 (Mại)', 'Ghép 继 [bộ 纟] + 续 [bộ 纟] để nhớ từ 继续 (jìxù): "tiếp tục".', '没关系！我只要继续努力，相信自己就好。再说，虽然我不说，但是你们也帮助我很多。能到中国，跟你们交朋友，我很幸福。', 'Méiguānxi! Wǒ zhǐyào jìxù nǔlì, xiāngxìn zìjǐ jiù hǎo. Zàishuō, suīrán wǒ bù shuō, dànshì nǐmen yě bāngzhù wǒ hěnduō. Néng dào Zhōngguó, gēn nǐmen jiāo péngyou, wǒ hěn xìngfú.', 'Không sao đâu! Chỉ cần tớ tiếp tục cố gắng, tin vào bản thân là được. Hơn nữa, dù tớ không nói ra nhưng các bạn cũng giúp đỡ tớ rất nhiều. Được đến Trung Quốc và kết bạn với các bạn, tớ thấy rất hạnh phúc.', 21) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v22_22', 'lesson-22', '解决', 'jiějué', 'từ Hán ngữ', 'giải quyết', 'Động từ', '刀/刂 (Đao) (Con dao, cắt xẻ, phân chia)', '解: 角 (Giác: sừng) + 刀 (Đao: dao) + 牛 (Ngưu: mổ phân tích) • 决: 冫 (Băng) + 夬 (Quái)', 'Ghép 解 [bộ 刀] + 决 [bộ 冫] để nhớ từ 解决 (jiějué): "giải quyết".', '怎么了？你还有什么困难，告诉我吧！我会帮你解决。', 'Zěnmele? Nǐ hái yǒu shén me kùnnan, gàosù wǒ ba! Wǒ huì bāng nǐ jiějué.', 'Sao vậy? Cậu còn gặp khó khăn gì cứ nói với tớ! Tớ sẽ giúp cậu giải quyết.', 22) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v22_23', 'lesson-22', '努力', 'nǔlì', 'nỗ lực', 'cố gắng, nỗ lực', 'Động từ / Tính từ', '力 (Lực) (Sức mạnh, động lực)', '努: 奴 (Nô) + 力 (Lực: dốc hết sức lực) • 力: Bộ 力 (Lực - bắp tay/cái cày thể hiện sức mạnh, chữ độc thể)', 'Ghép 努 [bộ 力] + 力 [bộ 力] để nhớ từ 努力 (nǔlì): "cố gắng, nỗ lực".', '没关系！我只要继续努力，相信自己就好。再说，虽然我不说，但是你们也帮助我很多。能到中国，跟你们交朋友，我很幸福。', 'Méiguānxi! Wǒ zhǐyào jìxù nǔlì, xiāngxìn zìjǐ jiù hǎo. Zàishuō, suīrán wǒ bù shuō, dànshì nǐmen yě bāngzhù wǒ hěnduō. Néng dào Zhōngguó, gēn nǐmen jiāo péngyou, wǒ hěn xìngfú.', 'Không sao đâu! Chỉ cần tớ tiếp tục cố gắng, tin vào bản thân là được. Hơn nữa, dù tớ không nói ra nhưng các bạn cũng giúp đỡ tớ rất nhiều. Được đến Trung Quốc và kết bạn với các bạn, tớ thấy rất hạnh phúc.', 23) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v22_24', 'lesson-22', '难过', 'nánguò', 'từ Hán ngữ', 'buồn', 'Tính từ', '隹 (Chuy) (Chim đuôi ngắn)', '难: 又 (Hựu) + 隹 (Chuy) • 过: 寸 (Thốn) + 辶 (Sước: bước đi qua)', 'Ghép 难 [bộ 隹] + 过 [bộ 辶] để nhớ từ 难过 (nánguò): "buồn".', '你怎么不跟我们说啊？那时候你一定很难过。', 'Nǐ zěnme bù gēn wǒmen shuō a? Nà shíhou nǐ yídìng hěn nánguò.', 'Sao cậu không kể với bọn tớ? Lúc đó chắc cậu buồn lắm.', 24) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v22_25', 'lesson-22', '幸福', 'xìngfú', 'từ Hán ngữ', 'hạnh phúc', 'Tính từ / Danh từ', '干 (Can) (Can thiệp, khô ráo, làm việc)', '幸: 土 (Thổ) + 丷 + 干 (may mắn, hạnh phúc) • 福: 礻 (Thị: thần ban lộc) + 畐 (Phúc: nhà đầy đủ)', 'Ghép 幸 [bộ 干] + 福 [bộ 礻] để nhớ từ 幸福 (xìngfú): "hạnh phúc".', '没关系！我只要继续努力，相信自己就好。再说，虽然我不说，但是你们也帮助我很多。能到中国，跟你们交朋友，我很幸福。', 'Méiguānxi! Wǒ zhǐyào jìxù nǔlì, xiāngxìn zìjǐ jiù hǎo. Zàishuō, suīrán wǒ bù shuō, dànshì nǐmen yě bāngzhù wǒ hěnduō. Néng dào Zhōngguó, gēn nǐmen jiāo péngyou, wǒ hěn xìngfú.', 'Không sao đâu! Chỉ cần tớ tiếp tục cố gắng, tin vào bản thân là được. Hơn nữa, dù tớ không nói ra nhưng các bạn cũng giúp đỡ tớ rất nhiều. Được đến Trung Quốc và kết bạn với các bạn, tớ thấy rất hạnh phúc.', 25) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v22_26', 'lesson-22', '糟糕', 'zāogāo', 'cao', 'tồi tệ, gay go', 'Tính từ', '米 (Mễ) (Hạt gạo, tinh bột)', '糟: 米 (Mễ: gạo ủ bã rượu) + 曹 (Tào) • 糕: 米 (Mễ: bột gạo làm bánh) + 羔 (Cao)', 'Ghép 糟 [bộ 米] + 糕 [bộ 米] để nhớ từ 糟糕 (zāogāo): "tồi tệ, gay go".', '那些困难我都能自己适应，自己解决。最糟糕的要说到学习问题。刚来中国的时候，因为不习惯这里的学习方法，所以我做什么事都很难。虽然在国内已经学汉语了，但是到中国以后，有很多时候你们说的我听不懂。考试又有很多，要抓紧时间练习。我一点儿也不习惯，哭了很多次。', 'Nàxiē kùnnan wǒ dōu néng zìjǐ shìyìng, zìjǐ jiějué. Zuì zāogāo de yāo shuō dào xuéxí wèntí. Gāng lái Zhōngguó de shíhou, yīn wèi bù xíguàn zhèli de xuéxí fāngfǎ, suǒ yǐ wǒ zuò shénme shì dōu hěn nán. Suīrán zài guónèi yǐjīng xué Hànyǔ le, dànshì dào Zhōngguó yǐhòu, yǒu hěnduō shíhou nǐmen shuō de wǒ tīng bù dǒng. Kǎoshì yòu yǒu hěnduō, yào zhuā jǐn shíjiān liànxí. Wǒ yīdiǎnr yě bù xíguàn, kūle hěnduō cì.', 'Những khó khăn đó tớ đều có thể tự thích nghi và tự giải quyết. Tệ nhất phải nói đến chuyện học tập. Hồi mới sang Trung Quốc, vì chưa quen phương pháp học ở đây nên làm việc gì cũng thấy khó. Dù ở trong nước đã học tiếng Trung rồi, nhưng sang đây có nhiều lúc các bạn nói tớ nghe không hiểu. Thi cử lại nhiều, phải tranh thủ thời gian luyện tập. Tớ chẳng quen chút nào, đã khóc rất nhiều lần.', 26) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v22_27', 'lesson-22', '不同', 'bùtóng', 'đồng', 'khác biệt, bất đồng, không giống nhau', 'Tính từ', '一 (Nhất) (Số một, nền tảng, nét ngang cơ bản)', '不: 一 (Nhất) + 丿 + 丨 + 丶 (chữ độc thể phủ định) • 同: 冂 (Quynh: khung bao) + 一 + 口 (Khẩu: cùng chung một tiếng)', 'Ghép 不 [bộ 一] + 同 [bộ 口] để nhớ từ 不同 (bùtóng): "khác biệt, bất đồng, không giống nhau".', '都是留学生经常遇到的困难，比如文化不同、生活环境不同等等。我们留学生的压力很大。', 'Dōu shì liúxuéshēng jīngcháng yùdào de kùnnan, bǐrú wénhuà bùtóng, shēnghuó huánjìng bùtóng děngděng. Wǒmen liúxuéshēng de yālì hěn dà.', 'Đều là những khó khăn mà du học sinh hay gặp phải thôi, như khác biệt văn hóa, môi trường sống khác nhau, v.v. Áp lực của du học sinh bọn tớ lớn lắm.', 27) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v22_28', 'lesson-22', '难', 'nán', 'từ Hán ngữ', 'khó', 'Tính từ', '隹 (Chuy) (Chim đuôi ngắn)', '难 = 又 (Hựu) + 隹 (Chuy).', 'Chữ 难 (nán) mang nghĩa "khó", bộ chính 隹 (Chuy); cấu tạo: 又 (Hựu) + 隹 (Chuy).', '怎么了？你还有什么困难，告诉我吧！我会帮你解决。', 'Zěnmele? Nǐ hái yǒu shén me kùnnan, gàosù wǒ ba! Wǒ huì bāng nǐ jiějué.', 'Sao vậy? Cậu còn gặp khó khăn gì cứ nói với tớ! Tớ sẽ giúp cậu giải quyết.', 28) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v22_29', 'lesson-22', '有经验', 'yǒu jīngyàn', 'hữu', 'có kinh nghiệm', 'Cụm từ / Tên riêng', '月 (Nguyệt/Nhục) (Mặt trăng hoặc các bộ phận thân thể người)', '有: 𠂇 (bàn tay) + 月 (Nguyệt/Nhục: cầm miếng thịt là có) • 经: 纟 (Mịch: sợi dọc khung cửi) + 圣 • 验: 马 (Mã: xem xét ngựa) + 佥 (Thiêm: kiểm nghiệm)', 'Ghép 有 [bộ 月] + 经 [bộ 纟] + 验 [bộ 马] để nhớ từ 有经验 (yǒu jīngyàn): "có kinh nghiệm".', '其实这些事我出国以前我奶奶已经跟我说了。她年轻的时候也去国外留学，很有经验。', 'Qíshí zhèxiē shì wǒ chūguó yǐqián wǒ nǎinai yǐjīng gēn wǒ shuō le. Tā niánqīng de shíhou yě qù guówài liúxué, hěn yǒu jīngyàn.', 'Thực ra những chuyện này trước khi ra nước ngoài bà nội tớ đã dặn dò tớ hết rồi. Thời trẻ bà cũng từng đi du học nên rất có kinh nghiệm.', 29) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v22_30', 'lesson-22', '已经', 'yǐjīng', 'từ Hán ngữ', 'đã', 'Phó từ', '己 (Kỷ) (Bản thân, chính mình)', '已: Bộ 己 (Kỷ - biến thể khép nửa, đã xong) • 经: 纟 (Mịch: sợi dọc khung cửi) + 圣', 'Ghép 已 [bộ 己] + 经 [bộ 纟] để nhớ từ 已经 (yǐjīng): "đã".', '那些困难我都能自己适应，自己解决。最糟糕的要说到学习问题。刚来中国的时候，因为不习惯这里的学习方法，所以我做什么事都很难。虽然在国内已经学汉语了，但是到中国以后，有很多时候你们说的我听不懂。考试又有很多，要抓紧时间练习。我一点儿也不习惯，哭了很多次。', 'Nàxiē kùnnan wǒ dōu néng zìjǐ shìyìng, zìjǐ jiějué. Zuì zāogāo de yāo shuō dào xuéxí wèntí. Gāng lái Zhōngguó de shíhou, yīn wèi bù xíguàn zhèli de xuéxí fāngfǎ, suǒ yǐ wǒ zuò shénme shì dōu hěn nán. Suīrán zài guónèi yǐjīng xué Hànyǔ le, dànshì dào Zhōngguó yǐhòu, yǒu hěnduō shíhou nǐmen shuō de wǒ tīng bù dǒng. Kǎoshì yòu yǒu hěnduō, yào zhuā jǐn shíjiān liànxí. Wǒ yīdiǎnr yě bù xíguàn, kūle hěnduō cì.', 'Những khó khăn đó tớ đều có thể tự thích nghi và tự giải quyết. Tệ nhất phải nói đến chuyện học tập. Hồi mới sang Trung Quốc, vì chưa quen phương pháp học ở đây nên làm việc gì cũng thấy khó. Dù ở trong nước đã học tiếng Trung rồi, nhưng sang đây có nhiều lúc các bạn nói tớ nghe không hiểu. Thi cử lại nhiều, phải tranh thủ thời gian luyện tập. Tớ chẳng quen chút nào, đã khóc rất nhiều lần.', 30) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v22_31', 'lesson-22', '慢慢', 'mànmàn', 'mạn mạn', 'từ từ, dần dần', 'Phó từ', '心/忄 (Tâm) (Trái tim, tình cảm, suy nghĩ, tâm lý)', '慢: 忄 (Tâm đứng: tâm trạng) + 曼 (Mạn: từ tốn chậm rãi) • 慢: 忄 (Tâm đứng: tâm trạng) + 曼 (Mạn: từ tốn chậm rãi)', 'Ghép 慢 [bộ 忄] + 慢 [bộ 忄] để nhớ từ 慢慢 (mànmàn): "từ từ, dần dần".', '慢慢就会习惯了。', 'Mànmàn jiù huì xíguàn le.', 'Dần dần rồi sẽ quen thôi.', 31) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v22_32', 'lesson-22', '再说', 'zàishuō', 'thuyết', 'ngoài ra, hơn nữa', 'Liên từ', '冂 (Quynh) (Vùng biên giới, khung bao)', '再: 一 + 冂 (Quynh) + 土 (Thổ) • 说: 讠 (Ngôn: lời nói) + 兑 (Đoài)', 'Ghép 再 [bộ 冂] + 说 [bộ 讠] để nhớ từ 再说 (zàishuō): "ngoài ra, hơn nữa".', '好了，我同意，你别再说了！', 'Hǎole, wǒ tóngyì, nǐ bié zài shuōle!', 'Được rồi, tôi đồng ý, cậu đừng nói lại nữa!', 32) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v22_33', 'lesson-22', '虽然...... 但是......', 'suīrán...dànshì...', 'thị', 'mặc dù... nhưng...', 'Cụm từ / Tên riêng', '虫 (Trùng) (Côn trùng, sâu bọ, bò sát)', '虽: 口 (Khẩu) + 虫 (Trùng) • 然: 肰 (Nhiên) + 灬 (Hỏa: ngọn lửa đốt) • 但: 亻 (Nhân đứng) + 旦 (Đán) • 是: 日 (Nhật: sáng rõ) + 𤴓 (biến thể của 正/疋: ngay thẳng)', 'Ghép 虽 [bộ 虫] + 然 [bộ 灬] + 但 [bộ 亻] + 是 [bộ 日] để nhớ từ 虽然...... 但是...... (suīrán...dànshì...): "mặc dù... nhưng...".', '这是关于“虽然...... 但是......”的常用句子。', 'Zhè shì guānyú ''suīrán...dànshì...'' de chángyòng jùzi.', 'Đây là câu ví dụ sử dụng từ ''虽然...... 但是......'' (mặc dù... nhưng...).', 33) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v22_34', 'lesson-22', '没关系', 'méiguānxi', 'một', 'không sao', 'Cụm từ / Tên riêng', '水/氵 (Thủy) (Nước, chất lỏng, sông ngòi)', '没: 氵 (Thủy: nước) + 殳 (Thù: chìm mất, không có) • 关: 丷 + 天 (Thiên: then cài cửa) • 系: 丿 (Phiệt) + 糸 (Mịch: sợi dây liên hệ)', 'Ghép 没 [bộ 氵] + 关 [bộ 八] + 系 [bộ 糸] để nhớ từ 没关系 (méiguānxi): "không sao".', '没关系！我只要继续努力，相信自己就好。再说，虽然我不说，但是你们也帮助我很多。能到中国，跟你们交朋友，我很幸福。', 'Méiguānxi! Wǒ zhǐyào jìxù nǔlì, xiāngxìn zìjǐ jiù hǎo. Zàishuō, suīrán wǒ bù shuō, dànshì nǐmen yě bāngzhù wǒ hěnduō. Néng dào Zhōngguó, gēn nǐmen jiāo péngyou, wǒ hěn xìngfú.', 'Không sao đâu! Chỉ cần tớ tiếp tục cố gắng, tin vào bản thân là được. Hơn nữa, dù tớ không nói ra nhưng các bạn cũng giúp đỡ tớ rất nhiều. Được đến Trung Quốc và kết bạn với các bạn, tớ thấy rất hạnh phúc.', 34) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order) VALUES ('g22_1', 'lesson-22', '1. Trợ từ ngữ khí 了', 'Chủ ngữ + Động từ + (Tân ngữ) + 了', ' Trợ từ ngữ khí 了 dùng ở cuối câu để biểu thị ngữ khí khẳng định, có sự thay đổi hoặc biểu thị ý khuyên ngăn, than thở. - Hình thức khẳng định: 我吃饭了。 Wǒ chīfàn le. Tôi ăn cơm rồi. 我的病好了。 Wǒ de bìng hǎo le. Tớ khỏi bệnh rồi. 好了，我同意，你别再说了！ Hǎole, wǒ tó', NULL, '[{"hanzi":"我吃饭了。","pinyin":"Wǒ chīfàn le.","meaning":"Tôi ăn cơm rồi."},{"hanzi":"好了，我同意，你别再说了！","pinyin":"Hǎole, wǒ tóngyì, nǐ bié zài shuōle!","meaning":"Được rồi, tôi đồng ý, cậu đừng nói lại nữa!"}]'::jsonb, 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order) VALUES ('g22_2', 'lesson-22', '2. 年龄的表达 - Cách biểu đạt tuổi tác', 'Chủ ngữ + （今年）几岁（了）？', ' - Có ba cách để hỏi về tuổi tác như sau: * Cách 1: Dùng cho trường hợp trẻ em dưới 10 tuổi. 你今年几岁了？ Nǐ jīnnián jǐ suì le? Năm nay cháu mấy tuổi rồi? * Cách 2: Thường dùng để hỏi tuổi của người lớn tuổi. Chủ ngữ （今年）多大年纪（了）？ 您今年多大年纪？ Nín jīnnián duōd', NULL, '[{"hanzi":"我没吃饭。","pinyin":"Wǒ méi chīfàn.","meaning":"Tôi chưa ăn cơm."},{"hanzi":"我的病还没好。","pinyin":"Wǒ de bìng hái méi hǎo.","meaning":"Bệnh của tôi vẫn chưa khỏi."}]'::jsonb, 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order;
INSERT INTO texts (id, lesson_id, title, description, sort_order) VALUES ('txt_22_1', 'lesson-22', 'Bài khoá #1: Hội thoại giáo trình — Thích nghi', 'Hội thoại chuẩn giáo trình Bài 22. Từ vựng chưa học được chú thích phiên âm & nghĩa trong ngoặc.', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_22_1_1', 'txt_22_1', '白茹雪', '玉兰，你怎么了？生病了吗？', '玉兰，你怎么了？生病了吗？', 'Yùlán, nǐ zěnmele? Shēngbìngle ma?', 'Ngọc Lan, cậu sao thế? Bị ốm à?', 1) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_22_1_2', 'txt_22_1', '范玉兰', '昨天下雪了，天挺冷的，所以我好像感冒了。', '昨天下雪了，天 (tiān: ngày, trời)挺冷的，所以 (suǒyǐ: cho nên)我好像感冒了。', 'Zuótiān xià xuěle, tiān tǐng lěng de, suǒyǐ wǒ hǎoxiàng gǎnmào le.', 'Hôm qua trời có tuyết rơi, lạnh lắm, nên hình như tớ bị cảm rồi.', 2) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_22_1_3', 'txt_22_1', '白茹雪', '你还没习惯这里的气候吗？', '你还没 (méi: chưa, không có)习惯这里 (lǐ: trong)的气候吗？', 'Nǐ hái méi xíguàn zhèli de qìhòu ma?', 'Cậu vẫn chưa quen với khí hậu ở đây à?', 3) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_22_1_4', 'txt_22_1', '范玉兰', '还没习惯，因为我家乡冬天不太冷，也不下雪。', '还没 (méi: chưa, không có)习惯，因为我家乡冬天不太冷，也不下雪。', 'Hái méi xíguàn, yīnwèi wǒ jiāxiāng dōngtiān bú tài lěng, yě bú xià xuě.', 'Vẫn chưa quen, vì mùa đông quê tớ không quá lạnh, cũng không có tuyết rơi.', 4) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_22_1_5', 'txt_22_1', '白茹雪', '慢慢就会习惯了。', '慢慢就会习惯了。', 'Mànmàn jiù huì xíguàn le.', 'Dần dần rồi sẽ quen thôi.', 5) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_22_1_6', 'txt_22_1', '范玉兰', '我也希望是这样。出国留学真是不容易啊！', '我也希望是这样。出国留学 (liúxué: du học)真是不容易啊！', 'Wǒ yě xīwàng shì zhèyàng. Chūguó liúxué zhēnshì bù róngyì a!', 'Tớ cũng hy vọng là thế. Đi du học nước ngoài thật sự không dễ dàng chút nào!', 6) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_22_1_7', 'txt_22_1', '白茹雪', '怎么了？你还有什么困难，告诉我吧！我会帮你解决。', '怎么了？你还有什么困难，告诉我吧！我会帮 (bāng: giúp đỡ)你解决。', 'Zěnmele? Nǐ hái yǒu shén me kùnnan, gàosù wǒ ba! Wǒ huì bāng nǐ jiějué.', 'Sao vậy? Cậu còn gặp khó khăn gì cứ nói với tớ! Tớ sẽ giúp cậu giải quyết.', 7) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_22_1_8', 'txt_22_1', '范玉兰', '都是留学生经常遇到的困难，比如文化不同、生活环境不同等等。我们留学生的压力很大。', '都是留学生经常遇到的困难，比如文化不同、生活环境不同等等。我们留学生的压力很大 (dà: to, lớn)。', 'Dōu shì liúxuéshēng jīngcháng yùdào de kùnnan, bǐrú wénhuà bùtóng, shēnghuó huánjìng bùtóng děngděng. Wǒmen liúxuéshēng de yālì hěn dà.', 'Đều là những khó khăn mà du học sinh hay gặp phải thôi, như khác biệt văn hóa, môi trường sống khác nhau, v.v. Áp lực của du học sinh bọn tớ lớn lắm.', 8) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_22_1_9', 'txt_22_1', '白茹雪', '我现在才知道。你们辛苦了。', '我现在才 (cái: mới)知道。你们辛苦了。', 'Wǒ xiànzài cái zhīdao. Nǐmen xīnkǔle.', 'Bây giờ tớ mới biết đấy. Các cậu vất vả quá.', 9) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_22_1_10', 'txt_22_1', '范玉兰', '那些困难我都能自己适应，自己解决。最糟糕的要说到学习问题。刚来中国的时候，因为不习惯这里的学习方法，所以我做什么事都很难。虽然在国内已经学汉语了，但是到中国以后，有很多时候你们说的我听不懂。考试又有很多，要抓紧时间练习。我一点儿也不习惯，哭了很多次。', '那些 (xiē: vài, một ít)困难我都能自己适应，自己解决。最糟糕的要说到学习 (xuéxí: học tập)问题。刚 (gāng: vừa mới)来 (lái: đến)中国的时候，因为不习惯这里 (lǐ: trong)的学习方法，所以 (suǒyǐ: cho nên)我做 (zuò: làm)什么事都很难。虽然在国内 (guónèi: trong nước)已经学 (xué: học)汉语了，但是到中国以后，有很多时候你们说的我听 (tīng: nghe)不懂。考试又有很多，要抓紧时间练习。我一点儿 (ér: con, (âm uốn lưỡi))也不习惯，哭了很多次 (cì: lần)。', 'Nàxiē kùnnan wǒ dōu néng zìjǐ shìyìng, zìjǐ jiějué. Zuì zāogāo de yāo shuō dào xuéxí wèntí. Gāng lái Zhōngguó de shíhou, yīn wèi bù xíguàn zhèli de xuéxí fāngfǎ, suǒ yǐ wǒ zuò shénme shì dōu hěn nán. Suīrán zài guónèi yǐjīng xué Hànyǔ le, dànshì dào Zhōngguó yǐhòu, yǒu hěnduō shíhou nǐmen shuō de wǒ tīng bù dǒng. Kǎoshì yòu yǒu hěnduō, yào zhuā jǐn shíjiān liànxí. Wǒ yīdiǎnr yě bù xíguàn, kūle hěnduō cì.', 'Những khó khăn đó tớ đều có thể tự thích nghi và tự giải quyết. Tệ nhất phải nói đến chuyện học tập. Hồi mới sang Trung Quốc, vì chưa quen phương pháp học ở đây nên làm việc gì cũng thấy khó. Dù ở trong nước đã học tiếng Trung rồi, nhưng sang đây có nhiều lúc các bạn nói tớ nghe không hiểu. Thi cử lại nhiều, phải tranh thủ thời gian luyện tập. Tớ chẳng quen chút nào, đã khóc rất nhiều lần.', 10) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_22_1_11', 'txt_22_1', '白茹雪', '你怎么不跟我们说啊？那时候你一定很难过。', '你怎么不跟 (gēn: cùng, với)我们说啊？那时候你一定 (yīdìng: nhất định)很难过。', 'Nǐ zěnme bù gēn wǒmen shuō a? Nà shíhou nǐ yídìng hěn nánguò.', 'Sao cậu không kể với bọn tớ? Lúc đó chắc cậu buồn lắm.', 11) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_22_1_12', 'txt_22_1', '范玉兰', '没关系！我只要继续努力，相信自己就好。再说，虽然我不说，但是你们也帮助我很多。能到中国，跟你们交朋友，我很幸福。', '没关系！我只要继续努力，相信自己就好。再说，虽然我不说，但是你们也帮助我很多。能到中国，跟 (gēn: cùng, với)你们交 (jiāo: nộp, kết bạn)朋友，我很幸福。', 'Méiguānxi! Wǒ zhǐyào jìxù nǔlì, xiāngxìn zìjǐ jiù hǎo. Zàishuō, suīrán wǒ bù shuō, dànshì nǐmen yě bāngzhù wǒ hěnduō. Néng dào Zhōngguó, gēn nǐmen jiāo péngyou, wǒ hěn xìngfú.', 'Không sao đâu! Chỉ cần tớ tiếp tục cố gắng, tin vào bản thân là được. Hơn nữa, dù tớ không nói ra nhưng các bạn cũng giúp đỡ tớ rất nhiều. Được đến Trung Quốc và kết bạn với các bạn, tớ thấy rất hạnh phúc.', 12) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_22_1_13', 'txt_22_1', '白茹雪', '哪有啊！都是你自己解决，我们没有做什么。', '哪有啊！都是你自己解决，我们没有 (méiyǒu: không có)做 (zuò: làm)什么。', 'Nǎ yǒu a! Dōu shì nǐ zìjǐ jiějué, wǒmen méiyǒu zuò shénme.', 'Đâu có đâu! Đều do cậu tự vượt qua cả, bọn tớ có làm gì đâu.', 13) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_22_1_14', 'txt_22_1', '范玉兰', '其实这些事我出国以前我奶奶已经跟我说了。她年轻的时候也去国外留学，很有经验。', '其实这些 (xiē: vài, một ít)事我出国以前我奶奶已经跟 (gēn: cùng, với)我说了。她年轻的时候也去国外 (guówài: nước ngoài)留学 (liúxué: du học)，很有经验。', 'Qíshí zhèxiē shì wǒ chūguó yǐqián wǒ nǎinai yǐjīng gēn wǒ shuō le. Tā niánqīng de shíhou yě qù guówài liúxué, hěn yǒu jīngyàn.', 'Thực ra những chuyện này trước khi ra nước ngoài bà nội tớ đã dặn dò tớ hết rồi. Thời trẻ bà cũng từng đi du học nên rất có kinh nghiệm.', 14) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_22_1_15', 'txt_22_1', '白茹雪', '到中国留学的时候你多大？', '到中国留学 (liúxué: du học)的时候你多大？', 'Dào Zhōngguó liúxué de shíhou nǐ duōdà?', 'Lúc sang Trung Quốc du học cậu bao nhiêu tuổi?', 15) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_22_1_16', 'txt_22_1', '范玉兰', '十八岁。', '十八岁。', 'Shíbā suì.', 'Mười tám tuổi.', 16) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_22_1_17', 'txt_22_1', '白茹雪', '你奶奶呢？', '你奶奶呢？', 'Nǐ nǎinai ne?', 'Còn bà nội cậu thì sao?', 17) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_22_1_18', 'txt_22_1', '范玉兰', '那时候她才十六岁。', '那时候她才 (cái: mới)十六岁。', 'Nà shíhou tā cái shíliù suì.', 'Lúc đó bà mới mười sáu tuổi thôi.', 18) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_22_1_19', 'txt_22_1', '白茹雪', '这么年轻！你奶奶真棒！你也真棒！对了，你奶奶今年多大年纪了？', '这么年轻！你奶奶真棒！你也真棒！对了，你奶奶今 (jīn: hôm nay, nay)年多大年纪了？', 'Zhème niánqīng! Nǐ nǎinai zhēn bàng! Nǐ yě zhēn bàng! Duìle, nǐ nǎinai jīnnián duōdà niánjì le?', 'Trẻ thế cơ à! Bà nội cậu giỏi thật! Cậu cũng rất giỏi! À, năm nay bà nội cậu bao nhiêu tuổi rồi?', 19) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_22_1_20', 'txt_22_1', '范玉兰', '她今年七十三岁。', '她今 (jīn: hôm nay, nay)年七十三岁。', 'Tā jīnnián qīshísān suì.', 'Năm nay bà 73 tuổi rồi.', 20) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_22_1_21', 'txt_22_1', '白茹雪', '奶奶身体好吗？', '奶奶身体好吗？', 'Nǎinai shēntǐ hǎo ma?', 'Sức khỏe của bà có tốt không?', 21) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_22_1_22', 'txt_22_1', '范玉兰', '她的身体很好。', '她的身体很好。', 'Tā de shēntǐ hěn hǎo.', 'Sức khỏe của bà rất tốt.', 22) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_22_1_1', 'lesson-22', 'txt_22_1', 'listening', 'listening', '玉兰，你怎么了？生病了吗？', NULL, 'Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["học sinh tốt, học sinh giỏi","Ngoài trời mưa đã tạnh chưa? Tớ không mang theo ô.","Ngọc Lan, cậu sao thế? Bị ốm à?","con đường này"]'::jsonb, 2, 'Nội dung nghe được: 玉兰，你怎么了？生病了吗？ (Yùlán, nǐ zěnmele? Shēngbìngle ma?) → Ngọc Lan, cậu sao thế? Bị ốm à?', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_22_1_2', 'lesson-22', 'txt_22_1', 'listening', 'listening', '昨天下雪了，天挺冷的，所以我好像感冒了。', NULL, 'Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["我二十三岁。","还没 (méi: chưa, không có)习惯，因为我家乡冬天不太冷，也不下雪。","昨天下雪了，天 (tiān: ngày, trời)挺冷的，所以 (suǒyǐ: cho nên)我好像感冒了。","我今 (jīn: hôm nay, nay)年六岁。"]'::jsonb, 2, 'Câu vừa đọc: 昨天下雪了，天挺冷的，所以我好像感冒了。 (Zuótiān xià xuěle, tiān tǐng lěng de, suǒyǐ wǒ hǎoxiàng gǎnmào le.) → Hôm qua trời có tuyết rơi, lạnh lắm, nên hình như tớ bị cảm rồi.', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_22_1_3', 'lesson-22', 'txt_22_1', 'listening', 'listening', '你还没习惯这里的气候吗？', NULL, 'Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Lúc sang Trung Quốc du học cậu bao nhiêu tuổi?","Cậu vẫn chưa quen với khí hậu ở đây à?","Năm nay bác bao nhiêu tuổi rồi ạ?","Cậu có thể rót cho tớ cốc nước không?"]'::jsonb, 1, 'Nội dung nghe được: 你还没习惯这里的气候吗？ (Nǐ hái méi xíguàn zhèli de qìhòu ma?) → Cậu vẫn chưa quen với khí hậu ở đây à?', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_22_1_4', 'lesson-22', 'txt_22_1', 'listening', 'listening', '还没习惯，因为我家乡冬天不太冷，也不下雪。', NULL, 'Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["只要多练习听 (tīng: nghe)力，以后就会听懂的。","你还没 (méi: chưa, không có)习惯这里 (lǐ: trong)的气候吗？","我今 (jīn: hôm nay, nay)年六岁。","还没 (méi: chưa, không có)习惯，因为我家乡冬天不太冷，也不下雪。"]'::jsonb, 3, 'Câu vừa đọc: 还没习惯，因为我家乡冬天不太冷，也不下雪。 (Hái méi xíguàn, yīnwèi wǒ jiāxiāng dōngtiān bú tài lěng, yě bú xià xuě.) → Vẫn chưa quen, vì mùa đông quê tớ không quá lạnh, cũng không có tuyết rơi.', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO texts (id, lesson_id, title, description, sort_order) VALUES ('txt_22_2', 'lesson-22', 'Bài nghe tổng hợp: Ôn tập lũy tiến (Bài 1 – Bài 22)', 'Kết hợp từ vựng & mẫu câu đã học từ Bài 1 đến Bài 21 cùng trọng tâm Bài 22 để củng cố phản xạ nghe.', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_22_2_1', 'txt_22_2', 'Ôn Bài 21', '你多运动运动吧！', '你多运动运动吧！', 'Nǐ duō yùndòng yùndòng ba!', 'Con vận động nhiều hơn đi!', 1) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_22_2_2', 'txt_22_2', 'Bài 22', '我吃饭了。', '我吃饭了。', 'Wǒ chīfàn le.', 'Tôi ăn cơm rồi.', 2) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_22_2_3', 'txt_22_2', 'Ôn Bài 11', '他真的这么说。', '他真的这么说。', 'Tā zhēn de zhème shuō.', 'Anh ta thật sự nói như thế.', 3) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_22_2_4', 'txt_22_2', 'Bài 22', '我二十三岁。', '我二十三岁。', 'Wǒ èrshísān suì.', 'Tôi 23 tuổi.', 4) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_22_2_5', 'txt_22_2', 'Ôn Bài 1', '她不是学生吗？', '她不是学生吗？', 'Tā bú shì xuésheng ma?', 'Cô ấy không phải là học sinh à?', 5) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_22_2_6', 'txt_22_2', 'Bài 22', '玉兰，你怎么了？生病了吗？', '玉兰，你怎么了？生病了吗？', 'Yùlán, nǐ zěnmele? Shēngbìngle ma?', 'Ngọc Lan, cậu sao thế? Bị ốm à?', 6) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_22_2_7', 'txt_22_2', 'Ôn Bài 8', '二十五个', '二十五个', 'èrshíwǔ gè', 'Hai mươi lăm cái', 7) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_22_2_8', 'txt_22_2', 'Bài 22', '慢慢就会习惯了。', '慢慢就会习惯了。', 'Mànmàn jiù huì xíguàn le.', 'Dần dần rồi sẽ quen thôi.', 8) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_22_2_1', 'lesson-22', 'txt_22_2', 'listening', 'listening', '你多运动运动吧！', NULL, '[Ôn tập Bài 21] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Chào buổi trưa!","Hai người họ dường như là bạn bè thân thiết đã nhiều năm rồi.","Con vận động nhiều hơn đi!","Hẹn gặp lại vào ngày mai! (Hoặc “Mai gặp nhé!”)"]'::jsonb, 2, 'Nội dung nghe được: 你多运动运动吧！ (Nǐ duō yùndòng yùndòng ba!) → Con vận động nhiều hơn đi!', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_22_2_2', 'lesson-22', 'txt_22_2', 'listening', 'listening', '我吃饭了。', NULL, '[Bài 22] Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["玉兰，你怎么了？生病了吗？","我也希望是这样。出国留学 (liúxué: du học)真是不容易啊！","我今 (jīn: hôm nay, nay)年六十岁了。","我吃饭了。"]'::jsonb, 3, 'Câu vừa đọc: 我吃饭了。 (Wǒ chīfàn le.) → Tôi ăn cơm rồi.', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_22_2_3', 'lesson-22', 'txt_22_2', 'listening', 'listening', '他真的这么说。', NULL, '[Ôn tập Bài 11] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Cậu là Nhật Minh phải không?","Bệnh viện ở bên phải trường học của chúng ta.","Nếu ngày mai mưa thì chúng tôi sẽ không đi chơi nữa.","Anh ta thật sự nói như thế."]'::jsonb, 3, 'Nội dung nghe được: 他真的这么说。 (Tā zhēn de zhème shuō.) → Anh ta thật sự nói như thế.', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_22_2_4', 'lesson-22', 'txt_22_2', 'listening', 'listening', '我二十三岁。', NULL, '[Bài 22] Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["我二十三岁。","老师教 (jiāo: Dạy)给了我一个很有效的学习 (xuéxí: học tập)方法。","他昨天没 (méi: chưa, không có)来 (lái: đến)。","你今 (jīn: hôm nay, nay)年多大？"]'::jsonb, 0, 'Câu vừa đọc: 我二十三岁。 (Wǒ èrshísān suì.) → Tôi 23 tuổi.', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_22_2_5', 'lesson-22', 'txt_22_2', 'listening', 'listening', '她不是学生吗？', NULL, '[Ôn tập Bài 1] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Hội nghị này, cậu đi hay Minh đi?","Sáng nay cậu gặp anh ấy chưa?","Lúc sang Trung Quốc du học cậu bao nhiêu tuổi?","Cô ấy không phải là học sinh à?"]'::jsonb, 3, 'Nội dung nghe được: 她不是学生吗？ (Tā bú shì xuésheng ma?) → Cô ấy không phải là học sinh à?', 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO texts (id, lesson_id, title, description, sort_order) VALUES ('txt_22_3', 'lesson-22', 'Bài khoá mở rộng: Vượt qua khó khăn khi mới du học (Mở rộng)', 'Hội thoại tình huống mới xây dựng dựa trên từ vựng và ngữ pháp Bài 22 (không trùng lặp nguyên văn giáo trình).', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_22_3_1', 'txt_22_3', 'Lan', '刚来中国的时候，我对这里的气候和学习方法都不太适应。', '刚 (gāng: vừa mới)来 (lái: đến)中国的时候，我对这里 (lǐ: trong)的气候和学习 (xuéxí: học tập)方法都不太适应。', 'Gāng lái Zhōngguó de shíhou, wǒ duì zhèlǐ de qìhòu hé xuéxí fāngfǎ dōu bú tài shìyìng.', 'Hồi mới sang Trung Quốc, tôi đều chưa quen lắm với khí hậu và phương pháp học ở đây.', 1) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_22_3_2', 'txt_22_3', 'Minh', '遇到那些困难的时候，你的压力很大吧？', '遇到那些 (xiē: vài, một ít)困难的时候，你的压力很大 (dà: to, lớn)吧？', 'Yùdào nàxiē kùnnan de shíhou, nǐ de yālì hěn dà ba?', 'Khi gặp những khó khăn đó, chắc áp lực của cậu lớn lắm nhỉ?', 2) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_22_3_3', 'txt_22_3', 'Lan', '是的，不过有朋友鼓励，我也每天努力练习，现在都能听懂了。', '是的，不过 (búguò: nhưng, tuy nhiên)有朋友鼓励，我也每天 (tiān: ngày, trời)努力练习，现在都能听 (tīng: nghe)懂了。', 'Shì de, búguò yǒu péngyou gǔlì, wǒ yě měitiān nǔlì liànxí, xiànzài dōu néng tīng dǒng le.', 'Đúng vậy, nhưng nhờ bạn bè động viên và ngày nào tôi cũng chăm chỉ luyện tập, giờ đã nghe hiểu hết rồi.', 3) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_22_3_4', 'txt_22_3', 'Minh', '太棒了！以后我们还会更加习惯这里的生活。', '太棒了！以后我们还会更 (gèng: càng)加习惯这里 (lǐ: trong)的生活。', 'Tài bàng le! Yǐhòu wǒmen hái huì gèngjiā xíguàn zhèlǐ de shēnghuó.', 'Tuyệt vời! Sau này chúng ta sẽ còn quen với cuộc sống ở đây hơn nữa.', 4) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_22_3_1', 'lesson-22', 'txt_22_3', 'listening', 'listening', '刚来中国的时候，我对这里的气候和学习方法都不太适应。 遇到那些困难的时候，你的压力很大吧？ 是的，不过有朋友鼓励，我也每天努力练习，现在都能听懂了。 太棒了！以后我们还会更加习惯这里的生活。', NULL, '[Nghe hiểu tình huống mới] Nhờ đâu Ngọc Lan đã vượt qua khó khăn nghe giảng không hiểu lúc mới du học?', '["Nhờ bạn bè động viên và chăm chỉ luyện tập mỗi ngày","Vì bỏ hết các tiết học trên lớp","Vì chuyển về quê nhà học","Vì khí hậu bỗng nhiên thay đổi"]'::jsonb, 0, 'Lan chia sẻ: ''有朋友鼓励，我也每天努力练习，现在都能听懂了''.', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_22_3_2', 'lesson-22', 'txt_22_3', 'listening', 'listening', '刚来中国的时候，我对这里的气候和学习方法都不太适应。', NULL, '[Mở rộng] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["người Trung Quốc","ba cây bút chì","Hồi mới sang Trung Quốc, tôi đều chưa quen lắm với khí hậu và phương pháp học ở đây.","Ai đấy?"]'::jsonb, 2, 'Nội dung nghe được: 刚来中国的时候，我对这里的气候和学习方法都不太适应。 (Gāng lái Zhōngguó de shíhou, wǒ duì zhèlǐ de qìhòu hé xuéxí fāngfǎ dōu bú tài shìyìng.) → Hồi mới sang Trung Quốc, tôi đều chưa quen lắm với khí hậu và phương pháp học ở đây.', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_22_3_3', 'lesson-22', 'txt_22_3', 'listening', 'listening', '遇到那些困难的时候，你的压力很大吧？', NULL, '[Mở rộng] Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["你姥姥 (lǎolao: bà ngoại)今 (jīn: hôm nay, nay)年多大年纪？","遇到那些 (xiē: vài, một ít)困难的时候，你的压力很大 (dà: to, lớn)吧？","好了，我同意 (tóngyì: đồng ý)，你别 (bié: đừng)再说了！","我吃饭了。"]'::jsonb, 1, 'Câu vừa đọc: 遇到那些困难的时候，你的压力很大吧？ (Yùdào nàxiē kùnnan de shíhou, nǐ de yālì hěn dà ba?) → Khi gặp những khó khăn đó, chắc áp lực của cậu lớn lắm nhỉ?', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_22_3_4', 'lesson-22', 'txt_22_3', 'listening', 'listening', '是的，不过有朋友鼓励，我也每天努力练习，现在都能听懂了。', NULL, '[Mở rộng] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["cuộc sống hạnh phúc","Bên trái tôi không phải là tòa giảng đường.","Hội nghị này, cậu đi hay Minh đi?","Đúng vậy, nhưng nhờ bạn bè động viên và ngày nào tôi cũng chăm chỉ luyện tập, giờ đã nghe hiểu hết rồi."]'::jsonb, 3, 'Nội dung nghe được: 是的，不过有朋友鼓励，我也每天努力练习，现在都能听懂了。 (Shì de, búguò yǒu péngyou gǔlì, wǒ yě měitiān nǔlì liànxí, xiànzài dōu néng tīng dǒng le.) → Đúng vậy, nhưng nhờ bạn bè động viên và ngày nào tôi cũng chăm chỉ luyện tập, giờ đã nghe hiểu hết rồi.', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss22_1', 'lesson-22', '只要多练习听力以后就会听懂的', '[Mở rộng] Chỉ cần luyện nghe nhiều thì sau này sẽ nghe hiểu thôi.', 'Zhǐyào duō liànxí tīnglì, yǐhòu jiù huì tīng dǒng de.', '["只要多","练习","听力","以后","就会听","懂的"]'::jsonb, 'Từ chưa học: 听 (tīng: nghe)', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss22_2', 'lesson-22', '我吃饭了', 'Tôi ăn cơm rồi.', 'Wǒ chīfàn le.', '["我","吃","饭","了"]'::jsonb, NULL, 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss22_3', 'lesson-22', '我二十三岁', 'Tôi 23 tuổi.', 'Wǒ èrshísān suì.', '["我","二","十","三","岁"]'::jsonb, NULL, 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss22_4', 'lesson-22', '慢慢就会习惯了', 'Dần dần rồi sẽ quen thôi.', 'Mànmàn jiù huì xíguàn le.', '["慢慢","就","会","习惯","了"]'::jsonb, NULL, 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss22_5', 'lesson-22', '用手机上网购物非常方便', '[Ôn tập Bài 10] Dùng điện thoại lên mạng mua sắm vô cùng tiện lợi.', 'Yòng shǒujī shàngwǎng gòuwù fēicháng fāngbiàn.', '["用","手机","上网","购物","非常","方便"]'::jsonb, 'Từ chưa học: 用 (yòng: dùng)', 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss22_6', 'lesson-22', '我姓范叫范玉兰', '[Ôn tập Bài 2] Tôi họ Phạm, tên là Phạm Ngọc Lan.', 'Wǒ xìng Fàn, jiào Fàn Yùlán.', '["我","姓","范","叫","范玉兰"]'::jsonb, NULL, 6) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss22_exp_1', 'lesson-22', '玉兰你怎么了生病了吗', 'Ngọc Lan, cậu sao thế? Bị ốm à?', 'Yùlán, nǐ zěnmele? Shēngbìngle ma?', '["玉","兰","你","怎么了","生病","了","吗"]'::jsonb, NULL, 7) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss22_exp_2', 'lesson-22', '昨天下雪了天挺冷的所以我好像感冒了', 'Hôm qua trời có tuyết rơi, lạnh lắm, nên hình như tớ bị cảm rồi.', 'Zuótiān xià xuěle, tiān tǐng lěng de, suǒyǐ wǒ hǎoxiàng gǎnmào le.', '["昨天","下雪","了","天","挺","冷","的","所以","我","好像","感冒","了"]'::jsonb, NULL, 8) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss22_exp_3', 'lesson-22', '你还没习惯这里的气候吗', 'Cậu vẫn chưa quen với khí hậu ở đây à?', 'Nǐ hái méi xíguàn zhèli de qìhòu ma?', '["你","还","没","习惯","这里","的","气候","吗"]'::jsonb, NULL, 9) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss22_exp_4', 'lesson-22', '还没习惯因为我家乡冬天不太冷也不下雪', 'Vẫn chưa quen, vì mùa đông quê tớ không quá lạnh, cũng không có tuyết rơi.', 'Hái méi xíguàn, yīnwèi wǒ jiāxiāng dōngtiān bú tài lěng, yě bú xià xuě.', '["还","没","习惯","因为","我","家乡","冬天","不","太","冷","也","不","下雪"]'::jsonb, NULL, 10) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss22_exp_5', 'lesson-22', '我也希望是这样出国留学真是不容易啊', 'Tớ cũng hy vọng là thế. Đi du học nước ngoài thật sự không dễ dàng chút nào!', 'Wǒ yě xīwàng shì zhèyàng. Chūguó liúxué zhēnshì bù róngyì a!', '["我","也","希望","是","这样","出国","留","学","真","是","不","容易","啊"]'::jsonb, NULL, 11) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss22_exp_6', 'lesson-22', '怎么了你还有什么困难告诉我吧我会帮你解决', 'Sao vậy? Cậu còn gặp khó khăn gì cứ nói với tớ! Tớ sẽ giúp cậu giải quyết.', 'Zěnmele? Nǐ hái yǒu shén me kùnnan, gàosù wǒ ba! Wǒ huì bāng nǐ jiějué.', '["怎么了","你","还","有","什么","困难","告诉","我","吧","我","会","帮","你","解决"]'::jsonb, NULL, 12) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss22_exp_7', 'lesson-22', '都是留学生经常遇到的困难比如文化不同生活环境不同等等我们留学生的压力很大', 'Đều là những khó khăn mà du học sinh hay gặp phải thôi, như khác biệt văn hóa, môi trường sống khác nhau, v.v. Áp lực của du học sinh bọn tớ lớn lắm.', 'Dōu shì liúxuéshēng jīngcháng yùdào de kùnnan, bǐrú wénhuà bùtóng, shēnghuó huánjìng bùtóng děngděng. Wǒmen liúxuéshēng de yālì hěn dà.', '["都","是","留学生","经常","遇到","的","困难","比如","文化","不同","生活","环境","不同","等等","我们","留学生","的","压力","很","大"]'::jsonb, NULL, 13) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss22_exp_8', 'lesson-22', '我现在才知道你们辛苦了', 'Bây giờ tớ mới biết đấy. Các cậu vất vả quá.', 'Wǒ xiànzài cái zhīdao. Nǐmen xīnkǔle.', '["我","现在","才","知道","你们","辛苦","了"]'::jsonb, NULL, 14) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss22_exp_9', 'lesson-22', '那些困难我都能自己适应自己解决最糟糕的要说到学习问题刚来中国的时候因为不习惯这里的学习方法所以我做什么事都很难虽然在国内已经学汉语了但是到中国以后有很多时候你们说的我听不懂考试又有很多要抓紧时间练习我一点儿也不习惯哭了很多次', 'Những khó khăn đó tớ đều có thể tự thích nghi và tự giải quyết. Tệ nhất phải nói đến chuyện học tập. Hồi mới sang Trung Quốc, vì chưa quen phương pháp học ở đây nên làm việc gì cũng thấy khó. Dù ở trong nước đã học tiếng Trung rồi, nhưng sang đây có nhiều lúc các bạn nói tớ nghe không hiểu. Thi cử lại nhiều, phải tranh thủ thời gian luyện tập. Tớ chẳng quen chút nào, đã khóc rất nhiều lần.', 'Nàxiē kùnnan wǒ dōu néng zìjǐ shìyìng, zìjǐ jiějué. Zuì zāogāo de yāo shuō dào xuéxí wèntí. Gāng lái Zhōngguó de shíhou, yīn wèi bù xíguàn zhèli de xuéxí fāngfǎ, suǒ yǐ wǒ zuò shénme shì dōu hěn nán. Suīrán zài guónèi yǐjīng xué Hànyǔ le, dànshì dào Zhōngguó yǐhòu, yǒu hěnduō shíhou nǐmen shuō de wǒ tīng bù dǒng. Kǎoshì yòu yǒu hěnduō, yào zhuā jǐn shíjiān liànxí. Wǒ yīdiǎnr yě bù xíguàn, kūle hěnduō cì.', '["那","些","困难","我","都","能","自己","适应","自己","解决","最","糟糕","的","要","说","到","学","习","问题","刚","来","中国","的","时候","因为","不","习惯","这里","的","学","习","方法","所以","我","做","什么","事","都","很","难","虽然","在","国","内","已经","学","汉语","了","但是","到","中国","以后","有","很","多","时候","你们","说","的","我","听","不","懂","考试","又","有","很","多","要","抓紧","时间","练习","我","一点儿","也","不","习惯","哭","了","很","多","次"]'::jsonb, NULL, 15) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss22_exp_10', 'lesson-22', '你怎么不跟我们说啊那时候你一定很难过', 'Sao cậu không kể với bọn tớ? Lúc đó chắc cậu buồn lắm.', 'Nǐ zěnme bù gēn wǒmen shuō a? Nà shíhou nǐ yídìng hěn nánguò.', '["你","怎么","不","跟","我们","说","啊","那","时候","你","一","定","很","难过"]'::jsonb, NULL, 16) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss22_exp_11', 'lesson-22', '没关系我只要继续努力相信自己就好再说虽然我不说但是你们也帮助我很多能到中国跟你们交朋友我很幸福', 'Không sao đâu! Chỉ cần tớ tiếp tục cố gắng, tin vào bản thân là được. Hơn nữa, dù tớ không nói ra nhưng các bạn cũng giúp đỡ tớ rất nhiều. Được đến Trung Quốc và kết bạn với các bạn, tớ thấy rất hạnh phúc.', 'Méiguānxi! Wǒ zhǐyào jìxù nǔlì, xiāngxìn zìjǐ jiù hǎo. Zàishuō, suīrán wǒ bù shuō, dànshì nǐmen yě bāngzhù wǒ hěnduō. Néng dào Zhōngguó, gēn nǐmen jiāo péngyou, wǒ hěn xìngfú.', '["没关系","我","只","要","继续","努力","相信","自己","就","好","再说","虽然","我","不","说","但是","你们","也","帮助","我","很","多","能","到","中国","跟","你们","交","朋友","我","很","幸福"]'::jsonb, NULL, 17) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss22_exp_12', 'lesson-22', '哪有啊都是你自己解决我们没有做什么', 'Đâu có đâu! Đều do cậu tự vượt qua cả, bọn tớ có làm gì đâu.', 'Nǎ yǒu a! Dōu shì nǐ zìjǐ jiějué, wǒmen méiyǒu zuò shénme.', '["哪","有","啊","都","是","你","自己","解决","我们","没有","做","什么"]'::jsonb, NULL, 18) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss22_exp_13', 'lesson-22', '其实这些事我出国以前我奶奶已经跟我说了她年轻的时候也去国外留学很有经验', 'Thực ra những chuyện này trước khi ra nước ngoài bà nội tớ đã dặn dò tớ hết rồi. Thời trẻ bà cũng từng đi du học nên rất có kinh nghiệm.', 'Qíshí zhèxiē shì wǒ chūguó yǐqián wǒ nǎinai yǐjīng gēn wǒ shuō le. Tā niánqīng de shíhou yě qù guówài liúxué, hěn yǒu jīngyàn.', '["其实","这","些","事","我","出国","以前","我","奶奶","已经","跟","我","说","了","她","年轻","的","时候","也","去","国","外","留","学","很","有经验"]'::jsonb, NULL, 19) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss22_exp_14', 'lesson-22', '到中国留学的时候你多大', 'Lúc sang Trung Quốc du học cậu bao nhiêu tuổi?', 'Dào Zhōngguó liúxué de shíhou nǐ duōdà?', '["到","中国","留","学","的","时候","你","多大"]'::jsonb, NULL, 20) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr22_vi_1', 'lesson-22', 'vi_to_zh', '[Mở rộng] Sau khi dần thích nghi với môi trường mới, áp lực của tôi giảm đi nhiều rồi.', NULL, NULL, '慢慢适应新环境以后，我的压力小多了。', NULL, 'mànmàn shìyìng xīn huánjìng yǐhòu wǒ de yālì xiǎo duō le', '[]'::jsonb, 'Gợi ý Pinyin: Mànmàn shìyìng xīn huánjìng yǐhòu, wǒ de yālì xiǎo duō le.', 'Sau khi dần thích nghi với môi trường mới, áp lực của tôi giảm đi nhiều rồi. → 慢慢适应新环境以后，我的压力小多了。 (Mànmàn shìyìng xīn huánjìng yǐhòu, wǒ de yālì xiǎo duō le.)', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr22_vi_2', 'lesson-22', 'vi_to_zh', '[Mở rộng] Khi gặp vấn đề, bạn có thể tìm bạn bè cùng nhau giải quyết.', NULL, NULL, '遇到问题时，你可以找朋友一起解决。', NULL, 'yùdào wèntí shí nǐ kěyǐ zhǎo péngyou yìqǐ jiějué', '[]'::jsonb, 'Gợi ý Pinyin: Yùdào wèntí shí, nǐ kěyǐ zhǎo péngyou yìqǐ jiějué. | Từ chưa học: 时 (shí: lúc, khi)', 'Khi gặp vấn đề, bạn có thể tìm bạn bè cùng nhau giải quyết. → 遇到问题时，你可以找朋友一起解决。 (Yùdào wèntí shí, nǐ kěyǐ zhǎo péngyou yìqǐ jiějué.)', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr22_vi_3', 'lesson-22', 'vi_to_zh', 'Tôi ăn cơm rồi.', NULL, NULL, '我吃饭了。', NULL, 'wǒ chīfàn le', '[]'::jsonb, 'Gợi ý Pinyin: Wǒ chīfàn le.', 'Tôi ăn cơm rồi. → 我吃饭了。 (Wǒ chīfàn le.)', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr22_vi_4', 'lesson-22', 'vi_to_zh', 'Tôi 23 tuổi.', NULL, NULL, '我二十三岁。', NULL, 'wǒ èrshísān suì', '[]'::jsonb, 'Gợi ý Pinyin: Wǒ èrshísān suì.', 'Tôi 23 tuổi. → 我二十三岁。 (Wǒ èrshísān suì.)', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr22_vi_exp_1', 'lesson-22', 'vi_to_zh', 'Ngọc Lan, cậu sao thế? Bị ốm à?', NULL, NULL, '玉兰，你怎么了？生病了吗？', NULL, 'yùlán nǐ zěnmele shēngbìngle ma', '[]'::jsonb, 'Gợi ý Pinyin: Yùlán, nǐ zěnmele? Shēngbìngle ma?', 'Ngọc Lan, cậu sao thế? Bị ốm à? → 玉兰，你怎么了？生病了吗？ (Yùlán, nǐ zěnmele? Shēngbìngle ma?)', 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr22_vi_exp_2', 'lesson-22', 'vi_to_zh', 'Hôm qua trời có tuyết rơi, lạnh lắm, nên hình như tớ bị cảm rồi.', NULL, NULL, '昨天下雪了，天挺冷的，所以我好像感冒了。', NULL, 'zuótiān xià xuěle tiān tǐng lěng de suǒyǐ wǒ hǎoxiàng gǎnmào le', '[]'::jsonb, 'Gợi ý Pinyin: Zuótiān xià xuěle, tiān tǐng lěng de, suǒyǐ wǒ hǎoxiàng gǎnmào le.', 'Hôm qua trời có tuyết rơi, lạnh lắm, nên hình như tớ bị cảm rồi. → 昨天下雪了，天挺冷的，所以我好像感冒了。 (Zuótiān xià xuěle, tiān tǐng lěng de, suǒyǐ wǒ hǎoxiàng gǎnmào le.)', 6) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr22_vi_exp_3', 'lesson-22', 'vi_to_zh', 'Cậu vẫn chưa quen với khí hậu ở đây à?', NULL, NULL, '你还没习惯这里的气候吗？', NULL, 'nǐ hái méi xíguàn zhèli de qìhòu ma', '[]'::jsonb, 'Gợi ý Pinyin: Nǐ hái méi xíguàn zhèli de qìhòu ma?', 'Cậu vẫn chưa quen với khí hậu ở đây à? → 你还没习惯这里的气候吗？ (Nǐ hái méi xíguàn zhèli de qìhòu ma?)', 7) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr22_vi_exp_4', 'lesson-22', 'vi_to_zh', 'Vẫn chưa quen, vì mùa đông quê tớ không quá lạnh, cũng không có tuyết rơi.', NULL, NULL, '还没习惯，因为我家乡冬天不太冷，也不下雪。', NULL, 'hái méi xíguàn yīnwèi wǒ jiāxiāng dōngtiān bú tài lěng yě bú xià xuě', '[]'::jsonb, 'Gợi ý Pinyin: Hái méi xíguàn, yīnwèi wǒ jiāxiāng dōngtiān bú tài lěng, yě bú xià xuě.', 'Vẫn chưa quen, vì mùa đông quê tớ không quá lạnh, cũng không có tuyết rơi. → 还没习惯，因为我家乡冬天不太冷，也不下雪。 (Hái méi xíguàn, yīnwèi wǒ jiāxiāng dōngtiān bú tài lěng, yě bú xià xuě.)', 8) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr22_vi_exp_5', 'lesson-22', 'vi_to_zh', 'Dần dần rồi sẽ quen thôi.', NULL, NULL, '慢慢就会习惯了。', NULL, 'mànmàn jiù huì xíguàn le', '[]'::jsonb, 'Gợi ý Pinyin: Mànmàn jiù huì xíguàn le.', 'Dần dần rồi sẽ quen thôi. → 慢慢就会习惯了。 (Mànmàn jiù huì xíguàn le.)', 9) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr22_vi_exp_6', 'lesson-22', 'vi_to_zh', 'Tớ cũng hy vọng là thế. Đi du học nước ngoài thật sự không dễ dàng chút nào!', NULL, NULL, '我也希望是这样。出国留学真是不容易啊！', NULL, 'wǒ yě xīwàng shì zhèyàng chūguó liúxué zhēnshì bù róngyì a', '[]'::jsonb, 'Gợi ý Pinyin: Wǒ yě xīwàng shì zhèyàng. Chūguó liúxué zhēnshì bù róngyì a!', 'Tớ cũng hy vọng là thế. Đi du học nước ngoài thật sự không dễ dàng chút nào! → 我也希望是这样。出国留学真是不容易啊！ (Wǒ yě xīwàng shì zhèyàng. Chūguó liúxué zhēnshì bù róngyì a!)', 10) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr22_vi_exp_7', 'lesson-22', 'vi_to_zh', 'Sao vậy? Cậu còn gặp khó khăn gì cứ nói với tớ! Tớ sẽ giúp cậu giải quyết.', NULL, NULL, '怎么了？你还有什么困难，告诉我吧！我会帮你解决。', NULL, 'zěnmele nǐ hái yǒu shén me kùnnan gàosù wǒ ba wǒ huì bāng nǐ jiějué', '[]'::jsonb, 'Gợi ý Pinyin: Zěnmele? Nǐ hái yǒu shén me kùnnan, gàosù wǒ ba! Wǒ huì bāng nǐ jiějué.', 'Sao vậy? Cậu còn gặp khó khăn gì cứ nói với tớ! Tớ sẽ giúp cậu giải quyết. → 怎么了？你还有什么困难，告诉我吧！我会帮你解决。 (Zěnmele? Nǐ hái yǒu shén me kùnnan, gàosù wǒ ba! Wǒ huì bāng nǐ jiějué.)', 11) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr22_vi_exp_8', 'lesson-22', 'vi_to_zh', 'Đều là những khó khăn mà du học sinh hay gặp phải thôi, như khác biệt văn hóa, môi trường sống khác nhau, v.v. Áp lực của du học sinh bọn tớ lớn lắm.', NULL, NULL, '都是留学生经常遇到的困难，比如文化不同、生活环境不同等等。我们留学生的压力很大。', NULL, 'dōu shì liúxuéshēng jīngcháng yùdào de kùnnan bǐrú wénhuà bùtóng shēnghuó huánjìng bùtóng děngděng wǒmen liúxuéshēng de yālì hěn dà', '[]'::jsonb, 'Gợi ý Pinyin: Dōu shì liúxuéshēng jīngcháng yùdào de kùnnan, bǐrú wénhuà bùtóng, shēnghuó huánjìng bùtóng děngděng. Wǒmen liúxuéshēng de yālì hěn dà.', 'Đều là những khó khăn mà du học sinh hay gặp phải thôi, như khác biệt văn hóa, môi trường sống khác nhau, v.v. Áp lực của du học sinh bọn tớ lớn lắm. → 都是留学生经常遇到的困难，比如文化不同、生活环境不同等等。我们留学生的压力很大。 (Dōu shì liúxuéshēng jīngcháng yùdào de kùnnan, bǐrú wénhuà bùtóng, shēnghuó huánjìng bùtóng děngděng. Wǒmen liúxuéshēng de yālì hěn dà.)', 12) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr22_vi_exp_9', 'lesson-22', 'vi_to_zh', 'Bây giờ tớ mới biết đấy. Các cậu vất vả quá.', NULL, NULL, '我现在才知道。你们辛苦了。', NULL, 'wǒ xiànzài cái zhīdao nǐmen xīnkǔle', '[]'::jsonb, 'Gợi ý Pinyin: Wǒ xiànzài cái zhīdao. Nǐmen xīnkǔle.', 'Bây giờ tớ mới biết đấy. Các cậu vất vả quá. → 我现在才知道。你们辛苦了。 (Wǒ xiànzài cái zhīdao. Nǐmen xīnkǔle.)', 13) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr22_vi_exp_10', 'lesson-22', 'vi_to_zh', 'Những khó khăn đó tớ đều có thể tự thích nghi và tự giải quyết. Tệ nhất phải nói đến chuyện học tập. Hồi mới sang Trung Quốc, vì chưa quen phương pháp học ở đây nên làm việc gì cũng thấy khó. Dù ở trong nước đã học tiếng Trung rồi, nhưng sang đây có nhiều lúc các bạn nói tớ nghe không hiểu. Thi cử lại nhiều, phải tranh thủ thời gian luyện tập. Tớ chẳng quen chút nào, đã khóc rất nhiều lần.', NULL, NULL, '那些困难我都能自己适应，自己解决。最糟糕的要说到学习问题。刚来中国的时候，因为不习惯这里的学习方法，所以我做什么事都很难。虽然在国内已经学汉语了，但是到中国以后，有很多时候你们说的我听不懂。考试又有很多，要抓紧时间练习。我一点儿也不习惯，哭了很多次。', NULL, 'nàxiē kùnnan wǒ dōu néng zìjǐ shìyìng zìjǐ jiějué zuì zāogāo de yāo shuō dào xuéxí wèntí gāng lái zhōngguó de shíhou yīn wèi bù xíguàn zhèli de xuéxí fāngfǎ suǒ yǐ wǒ zuò shénme shì dōu hěn nán suīrán zài guónèi yǐjīng xué hànyǔ le dànshì dào zhōngguó yǐhòu yǒu hěnduō shíhou nǐmen shuō de wǒ tīng bù dǒng kǎoshì yòu yǒu hěnduō yào zhuā jǐn shíjiān liànxí wǒ yīdiǎnr yě bù xíguàn kūle hěnduō cì', '[]'::jsonb, 'Gợi ý Pinyin: Nàxiē kùnnan wǒ dōu néng zìjǐ shìyìng, zìjǐ jiějué. Zuì zāogāo de yāo shuō dào xuéxí wèntí. Gāng lái Zhōngguó de shíhou, yīn wèi bù xíguàn zhèli de xuéxí fāngfǎ, suǒ yǐ wǒ zuò shénme shì dōu hěn nán. Suīrán zài guónèi yǐjīng xué Hànyǔ le, dànshì dào Zhōngguó yǐhòu, yǒu hěnduō shíhou nǐmen shuō de wǒ tīng bù dǒng. Kǎoshì yòu yǒu hěnduō, yào zhuā jǐn shíjiān liànxí. Wǒ yīdiǎnr yě bù xíguàn, kūle hěnduō cì.', 'Những khó khăn đó tớ đều có thể tự thích nghi và tự giải quyết. Tệ nhất phải nói đến chuyện học tập. Hồi mới sang Trung Quốc, vì chưa quen phương pháp học ở đây nên làm việc gì cũng thấy khó. Dù ở trong nước đã học tiếng Trung rồi, nhưng sang đây có nhiều lúc các bạn nói tớ nghe không hiểu. Thi cử lại nhiều, phải tranh thủ thời gian luyện tập. Tớ chẳng quen chút nào, đã khóc rất nhiều lần. → 那些困难我都能自己适应，自己解决。最糟糕的要说到学习问题。刚来中国的时候，因为不习惯这里的学习方法，所以我做什么事都很难。虽然在国内已经学汉语了，但是到中国以后，有很多时候你们说的我听不懂。考试又有很多，要抓紧时间练习。我一点儿也不习惯，哭了很多次。 (Nàxiē kùnnan wǒ dōu néng zìjǐ shìyìng, zìjǐ jiějué. Zuì zāogāo de yāo shuō dào xuéxí wèntí. Gāng lái Zhōngguó de shíhou, yīn wèi bù xíguàn zhèli de xuéxí fāngfǎ, suǒ yǐ wǒ zuò shénme shì dōu hěn nán. Suīrán zài guónèi yǐjīng xué Hànyǔ le, dànshì dào Zhōngguó yǐhòu, yǒu hěnduō shíhou nǐmen shuō de wǒ tīng bù dǒng. Kǎoshì yòu yǒu hěnduō, yào zhuā jǐn shíjiān liànxí. Wǒ yīdiǎnr yě bù xíguàn, kūle hěnduō cì.)', 14) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr22_zh_1', 'lesson-22', 'zh_to_vi', '[Mở rộng] 刚 (gāng: vừa mới)出国留学 (liúxué: du học)的时候，我遇到了一些生活困难。', '刚出国留学的时候，我遇到了一些生活困难。', 'Gāng chūguó liúxué de shíhou, wǒ yùdào le yìxiē shēnghuó kùnnan.', NULL, 'Hồi mới ra nước ngoài du học, tôi gặp một vài khó khăn trong cuộc sống.', NULL, '["Hồi","mới","ra"]'::jsonb, 'Pinyin: Gāng chūguó liúxué de shíhou, wǒ yùdào le yìxiē shēnghuó kùnnan.', '刚出国留学的时候，我遇到了一些生活困难。 (Gāng chūguó liúxué de shíhou, wǒ yùdào le yìxiē shēnghuó kùnnan.) nghĩa là: Hồi mới ra nước ngoài du học, tôi gặp một vài khó khăn trong cuộc sống.', 15) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr22_zh_2', 'lesson-22', 'zh_to_vi', '[Mở rộng] 我非常想念家乡的菜和那里 (lǐ: trong)的气候。', '我非常想念家乡的菜和那里的气候。', 'Wǒ fēicháng xiǎngniàn jiāxiāng de cài hé nàlǐ de qìhòu.', NULL, 'Tôi rất nhớ những món ăn quê nhà và khí hậu ở đó.', NULL, '["Tôi","rất","nhớ"]'::jsonb, 'Pinyin: Wǒ fēicháng xiǎngniàn jiāxiāng de cài hé nàlǐ de qìhòu.', '我非常想念家乡的菜和那里的气候。 (Wǒ fēicháng xiǎngniàn jiāxiāng de cài hé nàlǐ de qìhòu.) nghĩa là: Tôi rất nhớ những món ăn quê nhà và khí hậu ở đó.', 16) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr22_zh_3', 'lesson-22', 'zh_to_vi', '我没 (méi: chưa, không có)吃饭。', '我没吃饭。', 'Wǒ méi chīfàn.', NULL, 'Tôi chưa ăn cơm.', NULL, '["Tôi","chưa","ăn"]'::jsonb, 'Pinyin: Wǒ méi chīfàn.', '我没吃饭。 (Wǒ méi chīfàn.) nghĩa là: Tôi chưa ăn cơm.', 17) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr22_zh_4', 'lesson-22', 'zh_to_vi', '[Ôn tập Bài 11] 他正在听音乐呢。', '他正在听音乐呢。', 'Tā zhèngzài tīng yīnyuè ne.', NULL, 'Anh ấy đang nghe nhạc.', NULL, '["Anh","ấy","đang"]'::jsonb, 'Pinyin: Tā zhèngzài tīng yīnyuè ne.', '他正在听音乐呢。 (Tā zhèngzài tīng yīnyuè ne.) nghĩa là: Anh ấy đang nghe nhạc.', 18) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr22_zh_exp_1', 'lesson-22', 'zh_to_vi', '您今年多大年纪？', '您今年多大年纪？', 'Nín jīnnián duōdà niánjì?', NULL, 'Năm nay bác bao nhiêu tuổi rồi ạ?', NULL, '["năm","nay","bác","bao","nhiêu","tuổi","rồi"]'::jsonb, 'Pinyin: Nín jīnnián duōdà niánjì?', '您今年多大年纪？ (Nín jīnnián duōdà niánjì?) nghĩa là: Năm nay bác bao nhiêu tuổi rồi ạ?', 19) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr22_zh_exp_2', 'lesson-22', 'zh_to_vi', '我的病还没好。', '我的病还没好。', 'Wǒ de bìng hái méi hǎo.', NULL, 'Bệnh của tôi vẫn chưa khỏi.', NULL, '["bệnh","của","tôi","vẫn","chưa","khỏi"]'::jsonb, 'Pinyin: Wǒ de bìng hái méi hǎo.', '我的病还没好。 (Wǒ de bìng hái méi hǎo.) nghĩa là: Bệnh của tôi vẫn chưa khỏi.', 20) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr22_zh_exp_3', 'lesson-22', 'zh_to_vi', '好了，我同意，你别再说了！', '好了，我同意，你别再说了！', 'Hǎole, wǒ tóngyì, nǐ bié zài shuōle!', NULL, 'Được rồi, tôi đồng ý, cậu đừng nói lại nữa!', NULL, '["được","rồi","tôi","đồng","cậu","đừng","nói","lại","nữa"]'::jsonb, 'Pinyin: Hǎole, wǒ tóngyì, nǐ bié zài shuōle!', '好了，我同意，你别再说了！ (Hǎole, wǒ tóngyì, nǐ bié zài shuōle!) nghĩa là: Được rồi, tôi đồng ý, cậu đừng nói lại nữa!', 21) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr22_zh_exp_4', 'lesson-22', 'zh_to_vi', '太棒了！以后我们还会更加习惯这里的生活。', '太棒了！以后我们还会更加习惯这里的生活。', 'Tài bàng le! Yǐhòu wǒmen hái huì gèngjiā xíguàn zhèlǐ de shēnghuó.', NULL, 'Tuyệt vời! Sau này chúng ta sẽ còn quen với cuộc sống ở đây hơn nữa.', NULL, '["tuyệt","vời","sau","này","chúng","ta","sẽ","còn","quen","với","cuộc","sống","đây","hơn","nữa"]'::jsonb, 'Pinyin: Tài bàng le! Yǐhòu wǒmen hái huì gèngjiā xíguàn zhèlǐ de shēnghuó.', '太棒了！以后我们还会更加习惯这里的生活。 (Tài bàng le! Yǐhòu wǒmen hái huì gèngjiā xíguàn zhèlǐ de shēnghuó.) nghĩa là: Tuyệt vời! Sau này chúng ta sẽ còn quen với cuộc sống ở đây hơn nữa.', 22) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr22_zh_exp_5', 'lesson-22', 'zh_to_vi', '是的，不过有朋友鼓励，我也每天努力练习，现在都能听懂了。', '是的，不过有朋友鼓励，我也每天努力练习，现在都能听懂了。', 'Shì de, búguò yǒu péngyou gǔlì, wǒ yě měitiān nǔlì liànxí, xiànzài dōu néng tīng dǒng le.', NULL, 'Đúng vậy, nhưng nhờ bạn bè động viên và ngày nào tôi cũng chăm chỉ luyện tập, giờ đã nghe hiểu hết rồi.', NULL, '["đúng","vậy","nhưng","nhờ","bạn","bè","động","viên","và","ngày","nào","tôi","cũng","chăm","chỉ","luyện","tập","giờ","đã","nghe","hiểu","hết","rồi"]'::jsonb, 'Pinyin: Shì de, búguò yǒu péngyou gǔlì, wǒ yě měitiān nǔlì liànxí, xiànzài dōu néng tīng dǒng le.', '是的，不过有朋友鼓励，我也每天努力练习，现在都能听懂了。 (Shì de, búguò yǒu péngyou gǔlì, wǒ yě měitiān nǔlì liànxí, xiànzài dōu néng tīng dǒng le.) nghĩa là: Đúng vậy, nhưng nhờ bạn bè động viên và ngày nào tôi cũng chăm chỉ luyện tập, giờ đã nghe hiểu hết rồi.', 23) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr22_zh_exp_6', 'lesson-22', 'zh_to_vi', '遇到那些困难的时候，你的压力很大吧？', '遇到那些困难的时候，你的压力很大吧？', 'Yùdào nàxiē kùnnan de shíhou, nǐ de yālì hěn dà ba?', NULL, 'Khi gặp những khó khăn đó, chắc áp lực của cậu lớn lắm nhỉ?', NULL, '["khi","gặp","những","khó","khăn","đó","chắc","áp","lực","của","cậu","lớn","lắm","nhỉ"]'::jsonb, 'Pinyin: Yùdào nàxiē kùnnan de shíhou, nǐ de yālì hěn dà ba?', '遇到那些困难的时候，你的压力很大吧？ (Yùdào nàxiē kùnnan de shíhou, nǐ de yālì hěn dà ba?) nghĩa là: Khi gặp những khó khăn đó, chắc áp lực của cậu lớn lắm nhỉ?', 24) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr22_zh_exp_7', 'lesson-22', 'zh_to_vi', '刚来中国的时候，我对这里的气候和学习方法都不太适应。', '刚来中国的时候，我对这里的气候和学习方法都不太适应。', 'Gāng lái Zhōngguó de shíhou, wǒ duì zhèlǐ de qìhòu hé xuéxí fāngfǎ dōu bú tài shìyìng.', NULL, 'Hồi mới sang Trung Quốc, tôi đều chưa quen lắm với khí hậu và phương pháp học ở đây.', NULL, '["hồi","mới","sang","trung","quốc","tôi","đều","chưa","quen","lắm","với","khí","hậu","và","phương","pháp","học","đây"]'::jsonb, 'Pinyin: Gāng lái Zhōngguó de shíhou, wǒ duì zhèlǐ de qìhòu hé xuéxí fāngfǎ dōu bú tài shìyìng.', '刚来中国的时候，我对这里的气候和学习方法都不太适应。 (Gāng lái Zhōngguó de shíhou, wǒ duì zhèlǐ de qìhòu hé xuéxí fāngfǎ dōu bú tài shìyìng.) nghĩa là: Hồi mới sang Trung Quốc, tôi đều chưa quen lắm với khí hậu và phương pháp học ở đây.', 25) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
