INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct23_14', 'lesson-23', NULL, 'comprehensive_test', 'listening', '他高高兴兴地对我讲故事。', NULL, 'Nghe đoạn ghi âm và cho biết nhận định sau ĐÚNG hay SAI:
