INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct23_16', 'lesson-23', NULL, 'comprehensive_test', 'listening', '中国北方人习惯吃饺子，南方人喜欢吃年糕。春节是一年最快乐的时候。家人开开心心地坐在一起，一起包饺子，煮饺子。
