INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct23_18', 'lesson-23', NULL, 'comprehensive_test', 'listening', '春节快到了，春节的时候中国人常吃什么？
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct23_19', 'lesson-23', NULL, 'comprehensive_test', 'listening', '中国人常喝啤酒、白酒、红酒还有茶。如果你到中国人家里去做客，他们就会请你喝酒。
