INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct23_22', 'lesson-23', NULL, 'comprehensive_test', 'listening', '真的！南方主食多是米饭和年糕，北方人爱吃馒头和面条。
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct23_23', 'lesson-23', NULL, 'comprehensive_test', 'listening', '我不能吃辣的，我每次吃辣都会过敏。
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct23_24', 'lesson-23', NULL, 'comprehensive_test', 'listening', '听说中国南方和北方的饮食习惯不太一样，是真的吗？ 真的！南方主食多是米饭和年糕，北方人爱吃馒头和面条。 那你敢吃臭豆腐或者特别辣的菜吗？ 臭豆腐我还没试过，但是辣菜配冰饮料可香了！', NULL, 'Theo Trương Phong, lương thực chính quen thuộc của người miền Bắc Trung Quốc là gì?', '["Chỉ uống rượu vang đỏ","Màn thầu và mì sợi (馒头和面条)","Cơm trắng và bánh chưng","Chỉ ăn đậu phụ thối"]'::jsonb, 1, 'Phong nói ''北方人爱吃馒头和面条''.', 24) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
