INSERT INTO lessons (id, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id) VALUES ('lesson-24', 'Bài 24: Giao thông của Trung Quốc - Đơn nguyên 7: Du học Trung Quốc', 'Bài 24', 'Đơn nguyên 7: Du học Trung Quốc', 'Tàu cao tốc (高铁), tàu điện ngầm, xe buýt, xe đạp công cộng và tiện ích đi lại.', '2026-11-14'::date, 24, TRUE, NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, date_added = EXCLUDED.date_added, sort_order = EXCLUDED.sort_order, is_system = TRUE, updated_at = NOW();
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v24_1', 'lesson-24', '交通', 'jiāotōng', 'giao thông', 'giao thông', 'Danh từ', '亠 (Đầu) (Nóc, đỉnh đầu)', '交: 亠 + 父 (giao chéo, trao đổi qua lại) • 通: 甬 (Dũng) + 辶 (Sước: đi thông suốt)', 'Ghép 交 [bộ 亠] + 通 [bộ 辶] để nhớ từ 交通 (jiāotōng): "giao thông".', '小兰， 你来中国留学快要一年了，中国的交通你习惯了吗？', 'Xiǎolán, nǐ lái Zhōngguó liúxué kuàiyào yī nián le, Zhōngguó de jiāotōng nǐ xíguàn le ma?', 'Tiểu Lan, cậu sang Trung Quốc du học gần một năm rồi, cậu đã quen với giao thông ở Trung Quốc chưa?', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v24_2', 'lesson-24', '自行车', 'zìxíngchē', 'hành xa', 'xe đạp', 'Danh từ', '自 (Tự) (Cái mũi, bản thân, tự mình)', '自: Bộ 自 (Tự - hình cái mũi, chỉ bản thân) • 行: Bộ 行 (Hành - ngã tư đường đi lại) • 车: Bộ 车 (Xa - khung xe và trục bánh xe)', 'Ghép 自 [bộ 自] + 行 [bộ 行] + 车 [bộ 车] để nhớ từ 自行车 (zìxíngchē): "xe đạp".', '我会骑自行车和摩托车，我爸爸刚买了一辆汽车，  所以我正在学开车。学会的时候我就开车去玩儿。', 'Wǒ huì qí zìxíngchē hé mótuōchē, wǒ bàba gāng mǎi le yí liàng qìchē, suǒyǐ wǒ zhèngzài xué kāichē. Xuéhuì de shíhou wǒ jiù kāichē qù wánr.', 'Tớ biết đi xe đạp và xe máy, bố tớ vừa mua một chiếc ô tô nên tớ đang học lái xe. Khi nào học xong tớ sẽ lái xe đi chơi.', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v24_3', 'lesson-24', '摩托车', 'mótuōchē', 'xa', 'xe máy', 'Danh từ', '手/扌 (Thủ) (Bàn tay, động tác, thao tác)', '摩: 麻 (Ma) + 手 (Thủ: tay xoa bóp / phiên âm mô) • 托: 扌 (Thủ: tay đỡ) + 乇 (Thác) • 车: Bộ 车 (Xa - khung xe và trục bánh xe)', 'Ghép 摩 [bộ 手] + 托 [bộ 扌] + 车 [bộ 车] để nhớ từ 摩托车 (mótuōchē): "xe máy".', '我会骑自行车和摩托车，我爸爸刚买了一辆汽车，  所以我正在学开车。学会的时候我就开车去玩儿。', 'Wǒ huì qí zìxíngchē hé mótuōchē, wǒ bàba gāng mǎi le yí liàng qìchē, suǒyǐ wǒ zhèngzài xué kāichē. Xuéhuì de shíhou wǒ jiù kāichē qù wánr.', 'Tớ biết đi xe đạp và xe máy, bố tớ vừa mua một chiếc ô tô nên tớ đang học lái xe. Khi nào học xong tớ sẽ lái xe đi chơi.', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v24_4', 'lesson-24', '汽车', 'qìchē', 'khí xa', 'xe hơi', 'Danh từ', '水/氵 (Thủy) (Nước, chất lỏng, sông ngòi)', '汽: 氵 (Thủy: hơi nước) + 气 (Khí: khí hơi) • 车: Bộ 车 (Xa - khung xe và trục bánh xe)', 'Ghép 汽 [bộ 氵] + 车 [bộ 车] để nhớ từ 汽车 (qìchē): "xe hơi".', '我会骑自行车和摩托车，我爸爸刚买了一辆汽车，  所以我正在学开车。学会的时候我就开车去玩儿。', 'Wǒ huì qí zìxíngchē hé mótuōchē, wǒ bàba gāng mǎi le yí liàng qìchē, suǒyǐ wǒ zhèngzài xué kāichē. Xuéhuì de shíhou wǒ jiù kāichē qù wánr.', 'Tớ biết đi xe đạp và xe máy, bố tớ vừa mua một chiếc ô tô nên tớ đang học lái xe. Khi nào học xong tớ sẽ lái xe đi chơi.', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v24_5', 'lesson-24', '火车', 'huǒchē', 'hỏa xa', 'tàu hỏa', 'Danh từ', '火/灬 (Hỏa) (Lửa, nhiệt độ, nấu nướng, nóng bức)', '火: Bộ 火 (Hỏa - ngọn lửa bốc lên, chữ độc thể) • 车: Bộ 车 (Xa - khung xe và trục bánh xe)', 'Ghép 火 [bộ 火] + 车 [bộ 车] để nhớ từ 火车 (huǒchē): "tàu hỏa".', '火车马上就开。', 'Huǒchē mǎshàng jiù kāi.', 'Tàu hỏa sắp chạy ngay bây giờ.', 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v24_6', 'lesson-24', '出租车', 'chūzūchē', 'xa', 'xe taxi', 'Danh từ', '凵 (Khảm) (Há miệng, hố trũng)', '出: 山 (Sơn) chồng hai tầng bước ra ngoài • 租: 禾 (Hòa: thóc thuế thuê ruộng) + 且 (Thả) • 车: Bộ 车 (Xa - khung xe và trục bánh xe)', 'Ghép 出 [bộ 凵] + 租 [bộ 禾] + 车 [bộ 车] để nhớ từ 出租车 (chūzūchē): "xe taxi".', '如果要去比较近的地方，你可以走路或者骑自行车。较远的地方可以坐火车、出租车或者公共汽车， 但公共汽车上的乘客比较多。', 'Rúguǒ yào qù bǐjiào jìn de dìfang, nǐ kěyǐ zǒulù huòzhě qí zìxíngchē. Jiào yuǎn de dìfang kěyǐ zuò huǒchē, chūzūchē huòzhě gōnggòng qìchē, dàn gōnggòng qìchē shàng de chéngkè bǐjiào duō.', 'Nếu đi chỗ gần, cậu có thể đi bộ hoặc đạp xe. Chỗ xa hơn có thể đi tàu hỏa, taxi hoặc xe buýt, nhưng hành khách trên xe buýt khá đông.', 6) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v24_7', 'lesson-24', '公共汽车', 'gōnggòng qìchē', 'công cộng khí xa', 'xe buýt', 'Danh từ', '八 (Bát) (Số tám, phân chia, mở rộng)', '公: 八 (Bát: chia đều) + 厶 (Tư: không giữ riêng, công cộng) • 共: 廿 (Nhấp) + 一 + 八 (Bát: hai tay cùng nâng) • 汽: 氵 (Thủy: hơi nước) + 气 (Khí: khí hơi) • 车: Bộ 车 (Xa - khung xe và trục bánh xe)', 'Ghép 公 [bộ 八] + 共 [bộ 八] + 汽 [bộ 氵] + 车 [bộ 车] để nhớ từ 公共汽车 (gōnggòng qìchē): "xe buýt".', '如果要去比较近的地方，你可以走路或者骑自行车。较远的地方可以坐火车、出租车或者公共汽车， 但公共汽车上的乘客比较多。', 'Rúguǒ yào qù bǐjiào jìn de dìfang, nǐ kěyǐ zǒulù huòzhě qí zìxíngchē. Jiào yuǎn de dìfang kěyǐ zuò huǒchē, chūzūchē huòzhě gōnggòng qìchē, dàn gōnggòng qìchē shàng de chéngkè bǐjiào duō.', 'Nếu đi chỗ gần, cậu có thể đi bộ hoặc đạp xe. Chỗ xa hơn có thể đi tàu hỏa, taxi hoặc xe buýt, nhưng hành khách trên xe buýt khá đông.', 7) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v24_8', 'lesson-24', '司机', 'sījī', 'cơ', 'tài xế', 'Danh từ', '口 (Khẩu) (Miệng, ăn uống, lời nói, âm thanh phát ra)', '司: 𠃌 + 一 + 口 (Khẩu: người điều hành, cầm lái) • 机: 木 (Mộc: khung máy) + 几 (Kỷ)', 'Ghép 司 [bộ 口] + 机 [bộ 木] để nhớ từ 司机 (sījī): "tài xế".', '是的，我昨天坐公共汽车去上课，车上很拥挤。所以司机开车开得挺慢，我坐车坐了一个小时才到学校。', 'Shì de, wǒ zuótiān zuò gōnggòng qìchē qù shàngkè, chē shàng hěn yōngjǐ. Suǒyǐ sījī kāichē kāi de tǐng màn, wǒ zuòchē zuòle yígè xiǎoshí cái dào xuéxiào.', 'Đúng thế, hôm qua tớ đi xe buýt đến lớp, trên xe rất đông đúc. Vì vậy tài xế lái khá chậm, tớ ngồi xe mất một tiếng mới tới trường.', 8) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v24_9', 'lesson-24', '警察', 'jǐngchá', 'từ Hán ngữ', 'cảnh sát', 'Danh từ', '言/讠 (Ngôn) (Lời nói, ngôn ngữ, giao tiếp)', '警: 敬 (Kính: cẩn trọng) + 言 (Ngôn: lời cảnh báo) • 察: 宀 (Miên) + 祭 (Tế: quan sát kỹ lưỡng)', 'Ghép 警 [bộ 言] + 察 [bộ 宀] để nhớ từ 警察 (jǐngchá): "cảnh sát".', '最好应该骑摩托车，但是要有安全帽，红绿灯的红灯亮了要停车，因为路上都有交通警察。', 'Zuì hǎo yīnggāi qí mótuōchē, dànshì yào yǒu ānquán mào, hónglǜdēng de hóngdēng liàngle yào tíngchē, yīnwèi lùshang dōu yǒu jiāotōng jǐngchá.', 'Tốt nhất là nên đi xe máy, nhưng phải đội mũ bảo hiểm, đèn đỏ bật sáng là phải dừng xe vì trên đường đều có cảnh sát giao thông.', 9) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v24_10', 'lesson-24', '乘客', 'chéngkè', 'khách', 'hành khách', 'Danh từ', '丿 (Phiệt) (Nét phẩy nghiêng)', '乘: 禾 + 北 biến thể (leo lên xe/ngựa) • 客: 宀 (Miên: mái nhà) + 各 (Các: người tới nhà)', 'Ghép 乘 [bộ 丿] + 客 [bộ 宀] để nhớ từ 乘客 (chéngkè): "hành khách".', '如果要去比较近的地方，你可以走路或者骑自行车。较远的地方可以坐火车、出租车或者公共汽车， 但公共汽车上的乘客比较多。', 'Rúguǒ yào qù bǐjiào jìn de dìfang, nǐ kěyǐ zǒulù huòzhě qí zìxíngchē. Jiào yuǎn de dìfang kěyǐ zuò huǒchē, chūzūchē huòzhě gōnggòng qìchē, dàn gōnggòng qìchē shàng de chéngkè bǐjiào duō.', 'Nếu đi chỗ gần, cậu có thể đi bộ hoặc đạp xe. Chỗ xa hơn có thể đi tàu hỏa, taxi hoặc xe buýt, nhưng hành khách trên xe buýt khá đông.', 10) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v24_11', 'lesson-24', '安全帽', 'ānquán mào', 'An', 'mũ bảo hiểm', 'Danh từ', '宀 (Miên) (Mái nhà, che chở, nơi ở)', '安: 宀 (Miên: mái nhà) + 女 (Nữ: người phụ nữ bình yên trong nhà) • 全: 人 (Nhân: mái che) + 王 (Ngọc: viên ngọc nguyên vẹn) • 帽: 巾 (Cân: khăn vải) + 冒 (Mạo: đội lên đầu)', 'Ghép 安 [bộ 宀] + 全 [bộ 人] + 帽 [bộ 巾] để nhớ từ 安全帽 (ānquán mào): "mũ bảo hiểm".', '最好应该骑摩托车，但是要有安全帽，红绿灯的红灯亮了要停车，因为路上都有交通警察。', 'Zuì hǎo yīnggāi qí mótuōchē, dànshì yào yǒu ānquán mào, hónglǜdēng de hóngdēng liàngle yào tíngchē, yīnwèi lùshang dōu yǒu jiāotōng jǐngchá.', 'Tốt nhất là nên đi xe máy, nhưng phải đội mũ bảo hiểm, đèn đỏ bật sáng là phải dừng xe vì trên đường đều có cảnh sát giao thông.', 11) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v24_12', 'lesson-24', '地图', 'dìtú', 'địa đồ', 'bản đồ', 'Danh từ', '土 (Thổ) (Đất đai, vị trí, công trình)', '地: 土 (Thổ: đất) + 也 (Dã) • 图: 囗 (Vi: khung tranh) + 冬 (Đông: bản vẽ bên trong)', 'Ghép 地 [bộ 土] + 图 [bộ 囗] để nhớ từ 地图 (dìtú): "bản đồ".', '不会啊，如果不知道的话，我就看地图或者可以看路上的标志。', 'Bú huì a, rúguǒ bù zhīdao dehuà, wǒ jiù kàn dìtú huòzhě kěyǐ kàn lùshang de biāozhì.', 'Không đâu, nếu không biết đường thì tớ xem bản đồ hoặc nhìn biển báo chỉ đường.', 12) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v24_13', 'lesson-24', '红绿灯', 'hónglǜdēng', 'hồng lục', 'đèn giao thông', 'Danh từ', '糸/纟 (Mịch) (Sợi tơ, gắn kết, màu sắc)', '红: 纟 (Mịch: sợi tơ nhuộm đỏ) + 工 (Công) • 绿: 纟 (Mịch: sợi tơ nhuộm màu) + 录 (Lục) • 灯: 火 (Hỏa: ánh lửa đèn) + 丁 (Đinh)', 'Ghép 红 [bộ 纟] + 绿 [bộ 纟] + 灯 [bộ 火] để nhớ từ 红绿灯 (hónglǜdēng): "đèn giao thông".', '最好应该骑摩托车，但是要有安全帽，红绿灯的红灯亮了要停车，因为路上都有交通警察。', 'Zuì hǎo yīnggāi qí mótuōchē, dànshì yào yǒu ānquán mào, hónglǜdēng de hóngdēng liàngle yào tíngchē, yīnwèi lùshang dōu yǒu jiāotōng jǐngchá.', 'Tốt nhất là nên đi xe máy, nhưng phải đội mũ bảo hiểm, đèn đỏ bật sáng là phải dừng xe vì trên đường đều có cảnh sát giao thông.', 13) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v24_14', 'lesson-24', '标志', 'biāozhì', 'từ Hán ngữ', 'biển báo hiệu', 'Danh từ', '木 (Mộc) (Cây cối, gỗ, thực vật)', '标: 木 (Mộc: cột mốc gỗ) + 示 (Thị: chỉ dấu hiệu) • 志: 士 (Sĩ) + 心 (Tâm: chí hướng, ký hiệu)', 'Ghép 标 [bộ 木] + 志 [bộ 心] để nhớ từ 标志 (biāozhì): "biển báo hiệu".', '不会啊，如果不知道的话，我就看地图或者可以看路上的标志。', 'Bú huì a, rúguǒ bù zhīdao dehuà, wǒ jiù kàn dìtú huòzhě kěyǐ kàn lùshang de biāozhì.', 'Không đâu, nếu không biết đường thì tớ xem bản đồ hoặc nhìn biển báo chỉ đường.', 14) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v24_15', 'lesson-24', '交通规则', 'jiāotōng guīzé', 'giao thông', 'quy tắc giao thông', 'Cụm từ / Tên riêng', '亠 (Đầu) (Nóc, đỉnh đầu)', '交: 亠 + 父 (giao chéo, trao đổi qua lại) • 通: 甬 (Dũng) + 辶 (Sước: đi thông suốt) • 规: 夫 (Phu) + 见 (Kiến: thước đo chuẩn mực) • 则: 贝 (Bối) + 刂 (Đao: quy tắc định sẵn)', 'Ghép 交 [bộ 亠] + 通 [bộ 辶] + 规 [bộ 见] + 则 [bộ 刂] để nhớ từ 交通规则 (jiāotōng guīzé): "quy tắc giao thông".', '是啊! 大部分中国人都遵守交通规则。', 'Shì a! Dàbùfen Zhōngguó rén dōu zūnshǒu jiāotōng guīzé.', 'Đúng vậy! Phần lớn người Trung Quốc đều tuân thủ luật giao thông.', 15) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v24_16', 'lesson-24', '高峰时间', 'gāofēng shíjiān', 'cao thời gian', 'giờ cao điểm', 'Cụm từ / Tên riêng', '高 (Cao) (Cao lớn, tầng cao)', '高: Bộ 高 (Cao - tháp lầu nhiều tầng cao) • 峰: 山 (Sơn: đỉnh núi) + 夆 (Phong) • 时: 日 (Nhật: mặt trời) + 寸 (Thốn: đo thời gian) • 间: 门 (Môn: khe cửa) + 日 (Nhật: ánh nắng lọt qua)', 'Ghép 高 [bộ 高] + 峰 [bộ 山] + 时 [bộ 日] + 间 [bộ 门] để nhớ từ 高峰时间 (gāofēng shíjiān): "giờ cao điểm".', '我习惯了。 中国的交通很好，高峰时间很少堵车。', 'Wǒ xíguàn le. Zhōngguó de jiāotōng hěn hǎo, gāofēng shíjiān hěn shǎo dǔchē.', 'Tớ quen rồi. Giao thông ở Trung Quốc rất tốt, giờ cao điểm cũng ít khi tắc đường.', 16) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v24_17', 'lesson-24', '开车', 'kāichē', 'xa', 'lái xe(ô tô, taxi,..)', 'Động từ', '廾 (Củng) (Hai tay chắp, nâng đỡ)', '开: 一 + 廾 (Củng: hai tay mở rộng) • 车: Bộ 车 (Xa - khung xe và trục bánh xe)', 'Ghép 开 [bộ 廾] + 车 [bộ 车] để nhớ từ 开车 (kāichē): "lái xe(ô tô, taxi,..)".', '我会骑自行车和摩托车，我爸爸刚买了一辆汽车，  所以我正在学开车。学会的时候我就开车去玩儿。', 'Wǒ huì qí zìxíngchē hé mótuōchē, wǒ bàba gāng mǎi le yí liàng qìchē, suǒyǐ wǒ zhèngzài xué kāichē. Xuéhuì de shíhou wǒ jiù kāichē qù wánr.', 'Tớ biết đi xe đạp và xe máy, bố tớ vừa mua một chiếc ô tô nên tớ đang học lái xe. Khi nào học xong tớ sẽ lái xe đi chơi.', 17) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v24_18', 'lesson-24', '骑车', 'qíchē', 'kỵ xa', 'lái xe (xe đạp, xe máy..)', 'Động từ', '马 (Mã) (Con ngựa, chạy nhanh)', '骑: 马 (Mã: con ngựa) + 奇 (Kỳ: cưỡi ngựa/xe) • 车: Bộ 车 (Xa - khung xe và trục bánh xe)', 'Ghép 骑 [bộ 马] + 车 [bộ 车] để nhớ từ 骑车 (qíchē): "lái xe (xe đạp, xe máy..)".', '这是关于“骑车”的常用句子。', 'Zhè shì guānyú ''qíchē'' de chángyòng jùzi.', 'Đây là câu ví dụ sử dụng từ ''骑车'' (lái xe (xe đạp, xe máy..)).', 18) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v24_19', 'lesson-24', '坐车', 'zuòchē', 'tọa xa', 'ngồi xe', 'Động từ', '土 (Thổ) (Đất đai, vị trí, công trình)', '坐: 从 (hai người) + 土 (Thổ: hai người ngồi trên đất) • 车: Bộ 车 (Xa - khung xe và trục bánh xe)', 'Ghép 坐 [bộ 土] + 车 [bộ 车] để nhớ từ 坐车 (zuòchē): "ngồi xe".', '是的，我昨天坐公共汽车去上课，车上很拥挤。所以司机开车开得挺慢，我坐车坐了一个小时才到学校。', 'Shì de, wǒ zuótiān zuò gōnggòng qìchē qù shàngkè, chē shàng hěn yōngjǐ. Suǒyǐ sījī kāichē kāi de tǐng màn, wǒ zuòchē zuòle yígè xiǎoshí cái dào xuéxiào.', 'Đúng thế, hôm qua tớ đi xe buýt đến lớp, trên xe rất đông đúc. Vì vậy tài xế lái khá chậm, tớ ngồi xe mất một tiếng mới tới trường.', 19) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v24_20', 'lesson-24', '走路', 'zǒulù', 'từ Hán ngữ', 'đi bộ', 'Động từ', '走 (Tẩu) (Chạy, đi lại, rời đi)', '走: 土 (Thổ) + 龰 (Chân bước nhanh trên đất) • 路: ⻊ (Túc: bàn chân bước đi) + 各 (Các)', 'Ghép 走 [bộ 走] + 路 [bộ 足] để nhớ từ 走路 (zǒulù): "đi bộ".', '如果要去比较近的地方，你可以走路或者骑自行车。较远的地方可以坐火车、出租车或者公共汽车， 但公共汽车上的乘客比较多。', 'Rúguǒ yào qù bǐjiào jìn de dìfang, nǐ kěyǐ zǒulù huòzhě qí zìxíngchē. Jiào yuǎn de dìfang kěyǐ zuò huǒchē, chūzūchē huòzhě gōnggòng qìchē, dàn gōnggòng qìchē shàng de chéngkè bǐjiào duō.', 'Nếu đi chỗ gần, cậu có thể đi bộ hoặc đạp xe. Chỗ xa hơn có thể đi tàu hỏa, taxi hoặc xe buýt, nhưng hành khách trên xe buýt khá đông.', 20) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v24_21', 'lesson-24', '遵守', 'zūnshǒu', 'từ Hán ngữ', 'tuân thủ', 'Động từ', '辶 (Sước) (Bước đi, di chuyển, khoảng cách)', '遵: 尊 (Tôn: tôn trọng) + 辶 (Sước: đi theo đúng phép tắc) • 守: 宀 (Miên: mái nhà) + 寸 (Thốn: giữ gìn tuân thủ)', 'Ghép 遵 [bộ 辶] + 守 [bộ 宀] để nhớ từ 遵守 (zūnshǒu): "tuân thủ".', '是啊! 大部分中国人都遵守交通规则。', 'Shì a! Dàbùfen Zhōngguó rén dōu zūnshǒu jiāotōng guīzé.', 'Đúng vậy! Phần lớn người Trung Quốc đều tuân thủ luật giao thông.', 21) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v24_22', 'lesson-24', '迷路', 'mílù', 'từ Hán ngữ', 'lạc đường', 'Động từ', '辶 (Sước) (Bước đi, di chuyển, khoảng cách)', '迷: 米 (Mễ: hạt gạo vãi khắp) + 辶 (Sước: lạc lối / say mê) • 路: ⻊ (Túc: bàn chân bước đi) + 各 (Các)', 'Ghép 迷 [bộ 辶] + 路 [bộ 足] để nhớ từ 迷路 (mílù): "lạc đường".', '你很棒啊！你会不会迷路?', 'Nǐ hěn bàng a! Nǐ huì bu huì mílù?', 'Cậu giỏi thế! Cậu có hay bị lạc đường không?', 22) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v24_23', 'lesson-24', '堵车', 'dǔchē', 'xa', 'tắc đường, kẹt xe', 'Động từ', '土 (Thổ) (Đất đai, vị trí, công trình)', '堵: 土 (Thổ: đắp tường đất chặn) + 者 (Giả) • 车: Bộ 车 (Xa - khung xe và trục bánh xe)', 'Ghép 堵 [bộ 土] + 车 [bộ 车] để nhớ từ 堵车 (dǔchē): "tắc đường, kẹt xe".', '我习惯了。 中国的交通很好，高峰时间很少堵车。', 'Wǒ xíguàn le. Zhōngguó de jiāotōng hěn hǎo, gāofēng shíjiān hěn shǎo dǔchē.', 'Tớ quen rồi. Giao thông ở Trung Quốc rất tốt, giờ cao điểm cũng ít khi tắc đường.', 23) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v24_24', 'lesson-24', '停', 'tíng', 'từ Hán ngữ', 'dừng', 'Động từ', '人/亻 (Nhân) (Con người, nhân loại, hành động)', '停 = 亻 (Nhân đứng: người) + 亭 (Đình: dừng nghỉ ở đình trạm).', 'Chữ 停 (tíng) mang nghĩa "dừng", bộ chính 人/亻 (Nhân); cấu tạo: 亻 (Nhân đứng: người) + 亭 (Đình: dừng nghỉ ở đình trạm).', '最好应该骑摩托车，但是要有安全帽，红绿灯的红灯亮了要停车，因为路上都有交通警察。', 'Zuì hǎo yīnggāi qí mótuōchē, dànshì yào yǒu ānquán mào, hónglǜdēng de hóngdēng liàngle yào tíngchē, yīnwèi lùshang dōu yǒu jiāotōng jǐngchá.', 'Tốt nhất là nên đi xe máy, nhưng phải đội mũ bảo hiểm, đèn đỏ bật sáng là phải dừng xe vì trên đường đều có cảnh sát giao thông.', 24) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v24_25', 'lesson-24', '拥挤', 'yōngjǐ', 'từ Hán ngữ', 'chen chúc, chật chội', 'Tính từ', '手/扌 (Thủ) (Bàn tay, động tác, thao tác)', '拥: 扌 (Thủ: tay ôm giữ) + 用 (Dụng) • 挤: 扌 (Thủ: tay xô đẩy) + 齐 (Tề: chen chúc)', 'Ghép 拥 [bộ 扌] + 挤 [bộ 扌] để nhớ từ 拥挤 (yōngjǐ): "chen chúc, chật chội".', '是的，我昨天坐公共汽车去上课，车上很拥挤。所以司机开车开得挺慢，我坐车坐了一个小时才到学校。', 'Shì de, wǒ zuótiān zuò gōnggòng qìchē qù shàngkè, chē shàng hěn yōngjǐ. Suǒyǐ sījī kāichē kāi de tǐng màn, wǒ zuòchē zuòle yígè xiǎoshí cái dào xuéxiào.', 'Đúng thế, hôm qua tớ đi xe buýt đến lớp, trên xe rất đông đúc. Vì vậy tài xế lái khá chậm, tớ ngồi xe mất một tiếng mới tới trường.', 25) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v24_26', 'lesson-24', '慢', 'màn', 'mạn', 'chậm', 'Tính từ', '心/忄 (Tâm) (Trái tim, tình cảm, suy nghĩ, tâm lý)', '慢 = 忄 (Tâm đứng: tâm trạng) + 曼 (Mạn: từ tốn chậm rãi).', 'Chữ 慢 (màn) mang nghĩa "chậm", bộ chính 心/忄 (Tâm); cấu tạo: 忄 (Tâm đứng: tâm trạng) + 曼 (Mạn: từ tốn chậm rãi).', '是的，我昨天坐公共汽车去上课，车上很拥挤。所以司机开车开得挺慢，我坐车坐了一个小时才到学校。', 'Shì de, wǒ zuótiān zuò gōnggòng qìchē qù shàngkè, chē shàng hěn yōngjǐ. Suǒyǐ sījī kāichē kāi de tǐng màn, wǒ zuòchē zuòle yígè xiǎoshí cái dào xuéxiào.', 'Đúng thế, hôm qua tớ đi xe buýt đến lớp, trên xe rất đông đúc. Vì vậy tài xế lái khá chậm, tớ ngồi xe mất một tiếng mới tới trường.', 26) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v24_27', 'lesson-24', '辆', 'liàng', 'từ Hán ngữ', 'chiếc, cái ( xe)', 'Lượng từ', '车 (Xa) (Xe cộ, phương tiện giao thông)', '辆 = 车 (Xa: xe cộ) + 两 (Lưỡng: lượng từ xe).', 'Chữ 辆 (liàng) mang nghĩa "chiếc, cái ( xe)", bộ chính 车 (Xa); cấu tạo: 车 (Xa: xe cộ) + 两 (Lưỡng: lượng từ xe).', '我会骑自行车和摩托车，我爸爸刚买了一辆汽车，  所以我正在学开车。学会的时候我就开车去玩儿。', 'Wǒ huì qí zìxíngchē hé mótuōchē, wǒ bàba gāng mǎi le yí liàng qìchē, suǒyǐ wǒ zhèngzài xué kāichē. Xuéhuì de shíhou wǒ jiù kāichē qù wánr.', 'Tớ biết đi xe đạp và xe máy, bố tớ vừa mua một chiếc ô tô nên tớ đang học lái xe. Khi nào học xong tớ sẽ lái xe đi chơi.', 27) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order) VALUES ('g24_1', 'lesson-24', '1. 了', 'Động từ + 了 + thời gian (+ O): Dùng để biểu thị thời gian duy trì động tác đã', ' hoàn thành. 他睡觉睡了九个小时。 Tā shuìjiào shuìle jiǔ gè xiǎoshí. Cậu ấy ngủ suốt chín tiếng đồng hồ. 我看了一个上午的书了。 Wǒ kànle yígè shàngwǔ de shū le. Tôi đã đọc sách hết một buổi sáng. 我学汉语学了三年。 Wǒ xué Hànyǔ xué le sān nián. Tôi học tiếng Hán được 3 năm.', NULL, '[{"hanzi":"他睡觉睡了九个小时。","pinyin":"Tā shuìjiào shuìle jiǔ gè xiǎoshí.","meaning":"Cậu ấy ngủ suốt chín tiếng đồng hồ."},{"hanzi":"我看了一个上午的书了。","pinyin":"Wǒ kànle yígè shàngwǔ de shū le.","meaning":"Tôi đã đọc sách hết một buổi sáng."}]'::jsonb, 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order) VALUES ('g24_2', 'lesson-24', '2. 结果补语:  Bổ ngữ kết quả', 'Chủ ngữ + Động từ + BNKQ + (Tân ngữ)', ' Bổ ngữ chỉ kết quả dùng sau động từ, để chỉ ra kết quả của hành động, động tác. Thường do động từ hoặc tính từ đảm nhiệm. *Khẳng định: Một vài bổ ngữ kết quả thường gặp 完，到，见，好，清楚，干净，懂，…… 我学会了太极拳了。 Wǒ xuéhuìle tàijí quánle. Tớ học được môn Thái cực ', NULL, '[{"hanzi":"我学汉语学了三年。","pinyin":"Wǒ xué Hànyǔ xué le sān nián.","meaning":"Tôi học tiếng Hán được 3 năm."},{"hanzi":"我学会了太极拳了。","pinyin":"Wǒ xuéhuìle tàijí quánle.","meaning":"Tớ học được môn Thái cực quyền rồi."}]'::jsonb, 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order;
INSERT INTO texts (id, lesson_id, title, description, sort_order) VALUES ('txt_24_1', 'lesson-24', 'Bài khoá #1: Hội thoại giáo trình — Giao thông của Trung Quốc', 'Hội thoại chuẩn giáo trình Bài 24. Từ vựng chưa học được chú thích phiên âm & nghĩa trong ngoặc.', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_24_1_1', 'txt_24_1', '白茹雪', '小兰， 你来中国留学快要一年了，中国的交通你习惯了吗？', '小兰， 你来 (lái: đến)中国留学 (liúxué: du học)快要一年了，中国的交通你习惯了吗？', 'Xiǎolán, nǐ lái Zhōngguó liúxué kuàiyào yī nián le, Zhōngguó de jiāotōng nǐ xíguàn le ma?', 'Tiểu Lan, cậu sang Trung Quốc du học gần một năm rồi, cậu đã quen với giao thông ở Trung Quốc chưa?', 1) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_24_1_2', 'txt_24_1', '范玉兰', '我习惯了。 中国的交通很好，高峰时间很少堵车。', '我习惯了。 中国的交通很好，高峰时间很少 (shǎo: ít)堵车。', 'Wǒ xíguàn le. Zhōngguó de jiāotōng hěn hǎo, gāofēng shíjiān hěn shǎo dǔchē.', 'Tớ quen rồi. Giao thông ở Trung Quốc rất tốt, giờ cao điểm cũng ít khi tắc đường.', 2) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_24_1_3', 'txt_24_1', '白茹雪', '是啊! 大部分中国人都遵守交通规则。', '是啊! 大 (dà: to, lớn)部分中国人都遵守交通规则。', 'Shì a! Dàbùfen Zhōngguó rén dōu zūnshǒu jiāotōng guīzé.', 'Đúng vậy! Phần lớn người Trung Quốc đều tuân thủ luật giao thông.', 3) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_24_1_4', 'txt_24_1', '范玉兰', '你会骑什么车？', '你会骑 (qí: cưỡi, đi (xe đạp/máy))什么车 (chē: xe)？', 'Nǐ huì qí shénme chē?', 'Cậu biết đi xe gì?', 4) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_24_1_5', 'txt_24_1', '白茹雪', '我会骑自行车和摩托车，我爸爸刚买了一辆汽车，  所以我正在学开车。学会的时候我就开车去玩儿。', '我会骑 (qí: cưỡi, đi (xe đạp/máy))自行车和摩托车，我爸爸刚 (gāng: vừa mới)买了一辆汽车，  所以 (suǒyǐ: cho nên)我正在学 (xué: học)开车。学会的时候我就开车去玩儿。', 'Wǒ huì qí zìxíngchē hé mótuōchē, wǒ bàba gāng mǎi le yí liàng qìchē, suǒyǐ wǒ zhèngzài xué kāichē. Xuéhuì de shíhou wǒ jiù kāichē qù wánr.', 'Tớ biết đi xe đạp và xe máy, bố tớ vừa mua một chiếc ô tô nên tớ đang học lái xe. Khi nào học xong tớ sẽ lái xe đi chơi.', 5) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_24_1_6', 'txt_24_1', '范玉兰', '你很棒啊！你会不会迷路?', '你很棒啊！你会不会迷路?', 'Nǐ hěn bàng a! Nǐ huì bu huì mílù?', 'Cậu giỏi thế! Cậu có hay bị lạc đường không?', 6) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_24_1_7', 'txt_24_1', '白茹雪', '不会啊，如果不知道的话，我就看地图或者可以看路上的标志。', '不会啊，如果不知道的话 (huà: lời nói)，我就看地图或者可以看路上 (lùshang: trên đường)的标志。', 'Bú huì a, rúguǒ bù zhīdao dehuà, wǒ jiù kàn dìtú huòzhě kěyǐ kàn lùshang de biāozhì.', 'Không đâu, nếu không biết đường thì tớ xem bản đồ hoặc nhìn biển báo chỉ đường.', 7) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_24_1_8', 'txt_24_1', '范玉兰', '你觉得在中国坐什么车比较方便？', '你觉得在中国坐 (zuò: ngồi)什么车 (chē: xe)比较方便？', 'Nǐ juéde zài Zhōngguó zuò shénme chē bǐjiào fāngbiàn?', 'Cậu thấy ở Trung Quốc đi phương tiện gì thì tiện hơn?', 8) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_24_1_9', 'txt_24_1', '白茹雪', '如果要去比较近的地方，你可以走路或者骑自行车。较远的地方可以坐火车、出租车或者公共汽车， 但公共汽车上的乘客比较多。', '如果要去比较近的地方，你可以走路或者骑 (qí: cưỡi, đi (xe đạp/máy))自行车。较远的地方可以坐 (zuò: ngồi)火车、出租车或者公共汽车， 但 (dàn: nhưng)公共汽车上 (shàng: trên / lên)的乘客比较多。', 'Rúguǒ yào qù bǐjiào jìn de dìfang, nǐ kěyǐ zǒulù huòzhě qí zìxíngchē. Jiào yuǎn de dìfang kěyǐ zuò huǒchē, chūzūchē huòzhě gōnggòng qìchē, dàn gōnggòng qìchē shàng de chéngkè bǐjiào duō.', 'Nếu đi chỗ gần, cậu có thể đi bộ hoặc đạp xe. Chỗ xa hơn có thể đi tàu hỏa, taxi hoặc xe buýt, nhưng hành khách trên xe buýt khá đông.', 9) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_24_1_10', 'txt_24_1', '范玉兰', '是的，我昨天坐公共汽车去上课，车上很拥挤。所以司机开车开得挺慢，我坐车坐了一个小时才到学校。', '是的，我昨天坐 (zuò: ngồi)公共汽车去上课，车 (chē: xe)上 (shàng: trên / lên)很拥挤。所以 (suǒyǐ: cho nên)司机开车开 (kāi: mở, lái)得挺慢，我坐车坐了一个小时才 (cái: mới)到学校。', 'Shì de, wǒ zuótiān zuò gōnggòng qìchē qù shàngkè, chē shàng hěn yōngjǐ. Suǒyǐ sījī kāichē kāi de tǐng màn, wǒ zuòchē zuòle yígè xiǎoshí cái dào xuéxiào.', 'Đúng thế, hôm qua tớ đi xe buýt đến lớp, trên xe rất đông đúc. Vì vậy tài xế lái khá chậm, tớ ngồi xe mất một tiếng mới tới trường.', 10) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_24_1_11', 'txt_24_1', '白茹雪', '最好应该骑摩托车，但是要有安全帽，红绿灯的红灯亮了要停车，因为路上都有交通警察。', '最好应该骑 (qí: cưỡi, đi (xe đạp/máy))摩托车，但是要有安全帽，红绿灯的红灯 (hóngdēng: đèn đỏ)亮 (liàng: sáng)了要停车 (chē: xe)，因为路上 (lùshang: trên đường)都有交通警察。', 'Zuì hǎo yīnggāi qí mótuōchē, dànshì yào yǒu ānquán mào, hónglǜdēng de hóngdēng liàngle yào tíngchē, yīnwèi lùshang dōu yǒu jiāotōng jǐngchá.', 'Tốt nhất là nên đi xe máy, nhưng phải đội mũ bảo hiểm, đèn đỏ bật sáng là phải dừng xe vì trên đường đều có cảnh sát giao thông.', 11) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_24_1_12', 'txt_24_1', '范玉兰', '是的！', '是的！', 'Shì de!', 'Đúng vậy!', 12) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_24_1_1', 'lesson-24', 'txt_24_1', 'listening', 'listening', '小兰， 你来中国留学快要一年了，中国的交通你习惯了吗？', NULL, 'Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Tiểu Lan, cậu sang Trung Quốc du học gần một năm rồi, cậu đã quen với giao thông ở Trung Quốc chưa?","Một đôi tay","Con còn chưa rửa tay đã đòi ăn cái gì? (Con không được ăn)","Anh ấy nói tiếng Trung không tốt."]'::jsonb, 0, 'Nội dung nghe được: 小兰， 你来中国留学快要一年了，中国的交通你习惯了吗？ (Xiǎolán, nǐ lái Zhōngguó liúxué kuàiyào yī nián le, Zhōngguó de jiāotōng nǐ xíguàn le ma?) → Tiểu Lan, cậu sang Trung Quốc du học gần một năm rồi, cậu đã quen với giao thông ở Trung Quốc chưa?', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_24_1_2', 'lesson-24', 'txt_24_1', 'listening', 'listening', '我习惯了。 中国的交通很好，高峰时间很少堵车。', NULL, 'Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["我习惯了。 中国的交通很好，高峰时间很少 (shǎo: ít)堵车。","高峰时间公共汽车上 (shàng: trên / lên)的乘客非常多。","他就是我的弟弟。","我学 (xué: học)汉语学了三年。"]'::jsonb, 0, 'Câu vừa đọc: 我习惯了。 中国的交通很好，高峰时间很少堵车。 (Wǒ xíguàn le. Zhōngguó de jiāotōng hěn hǎo, gāofēng shíjiān hěn shǎo dǔchē.) → Tớ quen rồi. Giao thông ở Trung Quốc rất tốt, giờ cao điểm cũng ít khi tắc đường.', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_24_1_3', 'lesson-24', 'txt_24_1', 'listening', 'listening', '是啊! 大部分中国人都遵守交通规则。', NULL, 'Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Đúng vậy! Phần lớn người Trung Quốc đều tuân thủ luật giao thông.","quyển sách này","chúng tôi của hiện tại","Đây là sách của ai?"]'::jsonb, 0, 'Nội dung nghe được: 是啊! 大部分中国人都遵守交通规则。 (Shì a! Dàbùfen Zhōngguó rén dōu zūnshǒu jiāotōng guīzé.) → Đúng vậy! Phần lớn người Trung Quốc đều tuân thủ luật giao thông.', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_24_1_4', 'lesson-24', 'txt_24_1', 'listening', 'listening', '你会骑什么车？', NULL, 'Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["小明 (míng: ngày mai, sáng)做完 (zuòwán: làm xong)作业就去看电视 (diànshì: tivi)。","如果担心 (dānxīn: lo lắng)迷路，你可以先看看手机地图。","你会骑 (qí: cưỡi, đi (xe đạp/máy))什么车 (chē: xe)？","火车马上 (mǎshàng: ngay lập tức)就开 (kāi: mở, lái)。"]'::jsonb, 2, 'Câu vừa đọc: 你会骑什么车？ (Nǐ huì qí shénme chē?) → Cậu biết đi xe gì?', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO texts (id, lesson_id, title, description, sort_order) VALUES ('txt_24_2', 'lesson-24', 'Bài nghe tổng hợp: Ôn tập lũy tiến (Bài 1 – Bài 24)', 'Kết hợp từ vựng & mẫu câu đã học từ Bài 1 đến Bài 23 cùng trọng tâm Bài 24 để củng cố phản xạ nghe.', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_24_2_1', 'txt_24_2', 'Ôn Bài 23', '昨天我去了超市和书店。 （你去哪儿了？）', '昨天我去了超市和书店。 （你去哪儿了？）', 'Zuótiān wǒ qù le chāoshì hé shūdiàn. (Nǐ qù nǎr le?)', 'Hôm qua tôi đã đi đến siêu thị và hiệu sách. (Bạn đã đi đâu thế?)', 1) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_24_2_2', 'txt_24_2', 'Bài 24', '我看了一个上午的书了。', '我看了一个上午的书了。', 'Wǒ kànle yígè shàngwǔ de shū le.', 'Tôi đã đọc sách hết một buổi sáng.', 2) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_24_2_3', 'txt_24_2', 'Ôn Bài 12', '你累了，还是去休息吧！', '你累了，还是去休息吧！', 'Nǐ lèile, háishi qù xiūxi ba!', 'Mẹ mệt rồi, mẹ cứ đi nghỉ ngơi đi!', 3) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_24_2_4', 'txt_24_2', 'Bài 24', '去旅游的东西你准备好了吗？', '去旅游的东西你准备好了吗？', 'Qù lǚyóu de dōngxi nǐ zhǔnbèi hǎo le ma?', 'Bạn đã chuẩn bị đầy đủ đồ đạc để đi du lịch chưa?', 4) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_24_2_5', 'txt_24_2', 'Ôn Bài 1', '中午好！', '中午好！', 'Zhōngwǔ hǎo', 'Chào buổi trưa!', 5) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_24_2_6', 'txt_24_2', 'Bài 24', '他就是我的弟弟。', '他就是我的弟弟。', 'Tā jiùshì wǒ de dìdi.', 'Nó chính là em trai của tôi.', 6) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_24_2_7', 'txt_24_2', 'Ôn Bài 3', '这是我的书。', '这是我的书。', 'Zhè shì wǒ de shū.', 'Đây là sách của tôi.', 7) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_24_2_8', 'txt_24_2', 'Bài 24', '如果有什么不知道，你就问我。', '如果有什么不知道，你就问我。', 'Rúguǒ yǒu shénme bù zhīdào, nǐ jiù wèn wǒ.', 'Nếu có gì không biết thì cậu cứ hỏi tớ.', 8) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_24_2_1', 'lesson-24', 'txt_24_2', 'listening', 'listening', '昨天我去了超市和书店。 （你去哪儿了？）', NULL, '[Ôn tập Bài 23] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Tôi không biết người này là nam hay là nữ nữa.","Hôm qua tôi đã đi đến siêu thị và hiệu sách. (Bạn đã đi đâu thế?)","Cậu ấy ngủ suốt chín tiếng đồng hồ.","Nhà ăn ở cạnh giảng đường."]'::jsonb, 1, 'Nội dung nghe được: 昨天我去了超市和书店。 （你去哪儿了？） (Zuótiān wǒ qù le chāoshì hé shūdiàn. (Nǐ qù nǎr le?)) → Hôm qua tôi đã đi đến siêu thị và hiệu sách. (Bạn đã đi đâu thế?)', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_24_2_2', 'lesson-24', 'txt_24_2', 'listening', 'listening', '我看了一个上午的书了。', NULL, '[Bài 24] Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["他睡觉 (jiào: giấc ngủ)睡了九个小时。","我看了一个上午的书了。","今天的作业你做完 (zuòwán: làm xong)了吗？","大家 (dàjiā: mọi người)都要遵守交通规则，注意 (zhùyì: chú ý)红绿灯标志。"]'::jsonb, 1, 'Câu vừa đọc: 我看了一个上午的书了。 (Wǒ kànle yígè shàngwǔ de shū le.) → Tôi đã đọc sách hết một buổi sáng.', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_24_2_3', 'lesson-24', 'txt_24_2', 'listening', 'listening', '你累了，还是去休息吧！', NULL, '[Ôn tập Bài 12] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Anh ấy về nhà tắm trước, sau đó qua đón tớ.","Hẹn gặp lại vào ngày mai! (Hoặc “Mai gặp nhé!”)","Mọi người đều phải tuân thủ luật giao thông và chú ý biển báo đèn giao thông.","Mẹ mệt rồi, mẹ cứ đi nghỉ ngơi đi!"]'::jsonb, 3, 'Nội dung nghe được: 你累了，还是去休息吧！ (Nǐ lèile, háishi qù xiūxi ba!) → Mẹ mệt rồi, mẹ cứ đi nghỉ ngơi đi!', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_24_2_4', 'lesson-24', 'txt_24_2', 'listening', 'listening', '去旅游的东西你准备好了吗？', NULL, '[Bài 24] Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["去旅游的东西你准备好了吗？","我一定 (yīdìng: nhất định)要学 (xué: học)好汉语，不学好我就不回国 (huíguó: về nước)。","这位 (wèi: vị)出租车司机开车开 (kāi: mở, lái)得很稳、很快。","他说的话 (huà: lời nói)我没 (méi: chưa, không có)听 (tīng: nghe)见。"]'::jsonb, 0, 'Câu vừa đọc: 去旅游的东西你准备好了吗？ (Qù lǚyóu de dōngxi nǐ zhǔnbèi hǎo le ma?) → Bạn đã chuẩn bị đầy đủ đồ đạc để đi du lịch chưa?', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_24_2_5', 'lesson-24', 'txt_24_2', 'listening', 'listening', '中午好！', NULL, '[Ôn tập Bài 1] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Anh đừng đi! Có được không?","Tôi chưa ăn cơm.","Chào buổi trưa!","Lớp cậu có bao nhiêu học sinh?"]'::jsonb, 2, 'Nội dung nghe được: 中午好！ (Zhōngwǔ hǎo) → Chào buổi trưa!', 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO texts (id, lesson_id, title, description, sort_order) VALUES ('txt_24_3', 'lesson-24', 'Bài khoá mở rộng: Đi lại an toàn trên đường phố (Mở rộng)', 'Hội thoại tình huống mới xây dựng dựa trên từ vựng và ngữ pháp Bài 24 (không trùng lặp nguyên văn giáo trình).', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_24_3_1', 'txt_24_3', 'Lan', '从学校去火车站坐公共汽车还是坐出租车方便？', '从学校去火车站 (zhàn: đứng / trạm)坐 (zuò: ngồi)公共汽车还是坐出租车方便？', 'Cóng xuéxiào qù huǒchēzhàn zuò gōnggòng qìchē háishi zuò chūzūchē fāngbiàn?', 'Từ trường ra ga tàu hỏa thì đi xe buýt hay taxi tiện hơn?', 1) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_24_3_2', 'txt_24_3', 'Minh', '早上乘客多、容易堵车，坐地铁或者提早出门打车比较好。', '早上乘客多、容易堵车，坐 (zuò: ngồi)地铁或者提早 (zǎo: sớm)出门打 (dǎ: đánh, gọi, chơi)车 (chē: xe)比较好。', 'Zǎoshang chéngkè duō, róngyì dǔchē, zuò dìtiě huòzhě tízǎo chūmén dǎchē bǐjiào hǎo.', 'Buổi sáng hành khách đông, dễ tắc đường, đi tàu điện ngầm hoặc ra sớm bắt taxi thì tốt hơn.', 2) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_24_3_3', 'txt_24_3', 'Lan', '对了，我看大家骑摩托车都戴安全帽，也很注意红绿灯。', '对了，我看大家 (dàjiā: mọi người)骑 (qí: cưỡi, đi (xe đạp/máy))摩托车都戴安全帽，也很注意 (zhùyì: chú ý)红绿灯。', 'Duì le, wǒ kàn dàjiā qí mótuōchē dōu dài ānquán mào, yě hěn zhùyì hónglǜdēng.', 'Đúng rồi, tớ thấy mọi người đi xe máy đều đội mũ bảo hiểm và rất chú ý đèn đỏ đèn xanh.', 3) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_24_3_4', 'txt_24_3', 'Minh', '是啊，每个人遵守交通规则，路上才安全。', '是啊，每个人遵守交通规则，路上 (lùshang: trên đường)才 (cái: mới)安全。', 'Shì a, měi gèrén zūnshǒu jiāotōng guīzé, lùshang cái ānquán.', 'Đúng vậy, mỗi người đều tuân thủ luật giao thông thì đi đường mới an toàn.', 4) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_24_3_1', 'lesson-24', 'txt_24_3', 'listening', 'listening', '从学校去火车站坐公共汽车还是坐出租车方便？ 早上乘客多、容易堵车，坐地铁或者提早出门打车比较好。 对了，我看大家骑摩托车都戴安全帽，也很注意红绿灯。 是啊，每个人遵守交通规则，路上才安全。', NULL, '[Nghe hiểu tình huống mới] Minh khuyên nên làm gì khi muốn đi từ trường ra ga tàu hỏa vào buổi sáng?', '["Đi bộ mất cả ngày","Đi xe máy không cần đội mũ bảo hiểm","Đi tàu điện ngầm hoặc ra khỏi nhà sớm để bắt taxi vì sáng dễ tắc đường","Đợi giờ cao điểm mới đi xe buýt"]'::jsonb, 2, 'Minh giải thích buổi sáng hành khách đông dễ tắc đường nên khuyên ''坐地铁或者提早出门打车''.', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_24_3_2', 'lesson-24', 'txt_24_3', 'listening', 'listening', '从学校去火车站坐公共汽车还是坐出租车方便？', NULL, '[Mở rộng] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Một bức tranh","Từ trường ra ga tàu hỏa thì đi xe buýt hay taxi tiện hơn?","Năm nay bác bao nhiêu tuổi rồi ạ? (Hỏi người lớn tuổi)","Học sinh trung học không được phép hút thuốc."]'::jsonb, 1, 'Nội dung nghe được: 从学校去火车站坐公共汽车还是坐出租车方便？ (Cóng xuéxiào qù huǒchēzhàn zuò gōnggòng qìchē háishi zuò chūzūchē fāngbiàn?) → Từ trường ra ga tàu hỏa thì đi xe buýt hay taxi tiện hơn?', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_24_3_3', 'lesson-24', 'txt_24_3', 'listening', 'listening', '早上乘客多、容易堵车，坐地铁或者提早出门打车比较好。', NULL, '[Mở rộng] Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["如果担心 (dānxīn: lo lắng)迷路，你可以先看看手机地图。","如果明天下雨，我们就不去玩 (wán: chơi)了。","早上乘客多、容易堵车，坐 (zuò: ngồi)地铁或者提早 (zǎo: sớm)出门打 (dǎ: đánh, gọi, chơi)车 (chē: xe)比较好。","我走了一会儿 (ér: con, (âm uốn lưỡi))就回来 (lái: đến)。"]'::jsonb, 2, 'Câu vừa đọc: 早上乘客多、容易堵车，坐地铁或者提早出门打车比较好。 (Zǎoshang chéngkè duō, róngyì dǔchē, zuò dìtiě huòzhě tízǎo chūmén dǎchē bǐjiào hǎo.) → Buổi sáng hành khách đông, dễ tắc đường, đi tàu điện ngầm hoặc ra sớm bắt taxi thì tốt hơn.', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_24_3_4', 'lesson-24', 'txt_24_3', 'listening', 'listening', '对了，我看大家骑摩托车都戴安全帽，也很注意红绿灯。', NULL, '[Mở rộng] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Chúng tôi đang bàn bạc thảo luận.","Hẹn gặp lại vào ngày mai! (Hoặc “Mai gặp nhé!”)","Đúng rồi, tớ thấy mọi người đi xe máy đều đội mũ bảo hiểm và rất chú ý đèn đỏ đèn xanh.","Tốt nhất bạn nên tiếp tục rèn luyện sức khỏe đi!"]'::jsonb, 2, 'Nội dung nghe được: 对了，我看大家骑摩托车都戴安全帽，也很注意红绿灯。 (Duì le, wǒ kàn dàjiā qí mótuōchē dōu dài ānquán mào, yě hěn zhùyì hónglǜdēng.) → Đúng rồi, tớ thấy mọi người đi xe máy đều đội mũ bảo hiểm và rất chú ý đèn đỏ đèn xanh.', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss24_1', 'lesson-24', '我看了一个上午的书了', 'Tôi đã đọc sách hết một buổi sáng.', 'Wǒ kànle yígè shàngwǔ de shū le.', '["我","看了","一个","上午","的","书了"]'::jsonb, NULL, 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss24_2', 'lesson-24', '去旅游的东西你准备好了吗', 'Bạn đã chuẩn bị đầy đủ đồ đạc để đi du lịch chưa?', 'Qù lǚyóu de dōngxi nǐ zhǔnbèi hǎo le ma?', '["去","旅游的","东西","你","准备","好了吗"]'::jsonb, NULL, 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss24_3', 'lesson-24', '他就是我的弟弟', 'Nó chính là em trai của tôi.', 'Tā jiùshì wǒ de dìdi.', '["他","就","是","我","的","弟弟"]'::jsonb, NULL, 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss24_4', 'lesson-24', '如果有什么不知道你就问我', 'Nếu có gì không biết thì cậu cứ hỏi tớ.', 'Rúguǒ yǒu shénme bù zhīdào, nǐ jiù wèn wǒ.', '["如果有","什么","不","知道","你就","问我"]'::jsonb, NULL, 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss24_5', 'lesson-24', '爸爸热情地接待了我的同学', '[Ôn tập Bài 12] Bố tôi đã tiếp đón bạn học của tôi rất nhiệt tình.', 'Bàba rèqíng de jiēdài le wǒ de tóngxué.', '["爸爸","热情","地","接待了","我的","同学"]'::jsonb, NULL, 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss24_6', 'lesson-24', '她吃了三个饺子', '[Ôn tập Bài 23] Cô ấy đã ăn 3 cái sủi cảo.', 'Tā chīle sān gè jiǎozi.', '["她","吃","了","三","个","饺子"]'::jsonb, NULL, 6) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss24_exp_1', 'lesson-24', '小兰你来中国留学快要一年了中国的交通你习惯了吗', 'Tiểu Lan, cậu sang Trung Quốc du học gần một năm rồi, cậu đã quen với giao thông ở Trung Quốc chưa?', 'Xiǎolán, nǐ lái Zhōngguó liúxué kuàiyào yī nián le, Zhōngguó de jiāotōng nǐ xíguàn le ma?', '["小","兰","你","来","中国","留","学","快","要","一","年","了","中国","的","交通","你","习惯","了","吗"]'::jsonb, NULL, 7) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss24_exp_2', 'lesson-24', '我习惯了中国的交通很好高峰时间很少堵车', 'Tớ quen rồi. Giao thông ở Trung Quốc rất tốt, giờ cao điểm cũng ít khi tắc đường.', 'Wǒ xíguàn le. Zhōngguó de jiāotōng hěn hǎo, gāofēng shíjiān hěn shǎo dǔchē.', '["我","习惯","了","中国","的","交通","很","好","高峰时间","很","少","堵车"]'::jsonb, NULL, 8) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss24_exp_3', 'lesson-24', '是啊大部分中国人都遵守交通规则', 'Đúng vậy! Phần lớn người Trung Quốc đều tuân thủ luật giao thông.', 'Shì a! Dàbùfen Zhōngguó rén dōu zūnshǒu jiāotōng guīzé.', '["是","啊","大","部分","中国","人","都","遵守","交通规则"]'::jsonb, NULL, 9) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss24_exp_4', 'lesson-24', '你会骑什么车', 'Cậu biết đi xe gì?', 'Nǐ huì qí shénme chē?', '["你","会","骑","什么","车"]'::jsonb, NULL, 10) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss24_exp_5', 'lesson-24', '我会骑自行车和摩托车我爸爸刚买了一辆汽车所以我正在学开车学会的时候我就开车去玩儿', 'Tớ biết đi xe đạp và xe máy, bố tớ vừa mua một chiếc ô tô nên tớ đang học lái xe. Khi nào học xong tớ sẽ lái xe đi chơi.', 'Wǒ huì qí zìxíngchē hé mótuōchē, wǒ bàba gāng mǎi le yí liàng qìchē, suǒyǐ wǒ zhèngzài xué kāichē. Xuéhuì de shíhou wǒ jiù kāichē qù wánr.', '["我","会","骑","自行车","和","摩托车","我","爸爸","刚","买","了","一","辆","汽车","所以","我","正在","学","开车","学","会","的","时候","我","就","开车","去","玩儿"]'::jsonb, NULL, 11) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss24_exp_6', 'lesson-24', '你很棒啊你会不会迷路', 'Cậu giỏi thế! Cậu có hay bị lạc đường không?', 'Nǐ hěn bàng a! Nǐ huì bu huì mílù?', '["你","很","棒","啊","你","会","不","会","迷路"]'::jsonb, NULL, 12) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss24_exp_7', 'lesson-24', '不会啊如果不知道的话我就看地图或者可以看路上的标志', 'Không đâu, nếu không biết đường thì tớ xem bản đồ hoặc nhìn biển báo chỉ đường.', 'Bú huì a, rúguǒ bù zhīdao dehuà, wǒ jiù kàn dìtú huòzhě kěyǐ kàn lùshang de biāozhì.', '["不","会","啊","如果","不","知道","的","话","我","就","看","地图","或者","可以","看","路","上","的","标志"]'::jsonb, NULL, 13) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss24_exp_8', 'lesson-24', '你觉得在中国坐什么车比较方便', 'Cậu thấy ở Trung Quốc đi phương tiện gì thì tiện hơn?', 'Nǐ juéde zài Zhōngguó zuò shénme chē bǐjiào fāngbiàn?', '["你","觉得","在","中国","坐","什么","车","比较","方便"]'::jsonb, NULL, 14) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss24_exp_9', 'lesson-24', '如果要去比较近的地方你可以走路或者骑自行车较远的地方可以坐火车出租车或者公共汽车但公共汽车上的乘客比较多', 'Nếu đi chỗ gần, cậu có thể đi bộ hoặc đạp xe. Chỗ xa hơn có thể đi tàu hỏa, taxi hoặc xe buýt, nhưng hành khách trên xe buýt khá đông.', 'Rúguǒ yào qù bǐjiào jìn de dìfang, nǐ kěyǐ zǒulù huòzhě qí zìxíngchē. Jiào yuǎn de dìfang kěyǐ zuò huǒchē, chūzūchē huòzhě gōnggòng qìchē, dàn gōnggòng qìchē shàng de chéngkè bǐjiào duō.', '["如果","要","去","比较","近","的","地方","你","可以","走路","或者","骑","自行车","较","远","的","地方","可以","坐","火车","出租车","或者","公共汽车","但","公共汽车","上","的","乘客","比较","多"]'::jsonb, NULL, 15) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss24_exp_10', 'lesson-24', '是的我昨天坐公共汽车去上课车上很拥挤所以司机开车开得挺慢我坐车坐了一个小时才到学校', 'Đúng thế, hôm qua tớ đi xe buýt đến lớp, trên xe rất đông đúc. Vì vậy tài xế lái khá chậm, tớ ngồi xe mất một tiếng mới tới trường.', 'Shì de, wǒ zuótiān zuò gōnggòng qìchē qù shàngkè, chē shàng hěn yōngjǐ. Suǒyǐ sījī kāichē kāi de tǐng màn, wǒ zuòchē zuòle yígè xiǎoshí cái dào xuéxiào.', '["是","的","我","昨天","坐","公共汽车","去","上课","车","上","很","拥挤","所以","司机","开车","开","得","挺","慢","我","坐车","坐","了","一","个","小时","才","到","学校"]'::jsonb, NULL, 16) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss24_exp_11', 'lesson-24', '最好应该骑摩托车但是要有安全帽红绿灯的红灯亮了要停车因为路上都有交通警察', 'Tốt nhất là nên đi xe máy, nhưng phải đội mũ bảo hiểm, đèn đỏ bật sáng là phải dừng xe vì trên đường đều có cảnh sát giao thông.', 'Zuì hǎo yīnggāi qí mótuōchē, dànshì yào yǒu ānquán mào, hónglǜdēng de hóngdēng liàngle yào tíngchē, yīnwèi lùshang dōu yǒu jiāotōng jǐngchá.', '["最","好","应该","骑","摩托车","但是","要","有","安全帽","红绿灯","的","红","灯","亮","了","要","停","车","因为","路","上","都","有","交通","警察"]'::jsonb, NULL, 17) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss24_exp_12', 'lesson-24', '昨天我去了超市和书店你去哪儿了', 'Hôm qua tôi đã đi đến siêu thị và hiệu sách. (Bạn đã đi đâu thế?)', 'Zuótiān wǒ qù le chāoshì hé shūdiàn. (Nǐ qù nǎr le?)', '["昨天","我","去","了","超市","和","书店","你","去","哪儿","了"]'::jsonb, NULL, 18) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss24_exp_13', 'lesson-24', '你累了还是去休息吧', 'Mẹ mệt rồi, mẹ cứ đi nghỉ ngơi đi!', 'Nǐ lèile, háishi qù xiūxi ba!', '["你","累","了","还是","去","休息","吧"]'::jsonb, NULL, 19) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss24_exp_14', 'lesson-24', '中午好', 'Chào buổi trưa!', 'Zhōngwǔ hǎo', '["中午","好"]'::jsonb, NULL, 20) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr24_vi_1', 'lesson-24', 'vi_to_zh', '[Mở rộng] Vào giờ cao điểm, hành khách trên xe buýt rất đông.', NULL, NULL, '高峰时间公共汽车上的乘客非常多。', NULL, 'gāofēng shíjiān gōnggòng qìchē shàng de chéngkè fēicháng duō', '[]'::jsonb, 'Gợi ý Pinyin: Gāofēng shíjiān gōnggòng qìchē shàng de chéngkè fēicháng duō. | Từ chưa học: 上 (shàng: trên / lên)', 'Vào giờ cao điểm, hành khách trên xe buýt rất đông. → 高峰时间公共汽车上的乘客非常多。 (Gāofēng shíjiān gōnggòng qìchē shàng de chéngkè fēicháng duō.)', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr24_vi_2', 'lesson-24', 'vi_to_zh', '[Mở rộng] Nếu lo bị lạc đường, bạn có thể xem trước bản đồ trên điện thoại.', NULL, NULL, '如果担心迷路，你可以先看看手机地图。', NULL, 'rúguǒ dānxīn mílù nǐ kěyǐ xiān kànkan shǒujī dìtú', '[]'::jsonb, 'Gợi ý Pinyin: Rúguǒ dānxīn mílù, nǐ kěyǐ xiān kànkan shǒujī dìtú. | Từ chưa học: 担心 (dānxīn: lo lắng)', 'Nếu lo bị lạc đường, bạn có thể xem trước bản đồ trên điện thoại. → 如果担心迷路，你可以先看看手机地图。 (Rúguǒ dānxīn mílù, nǐ kěyǐ xiān kànkan shǒujī dìtú.)', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr24_vi_3', 'lesson-24', 'vi_to_zh', 'Tôi đã đọc sách hết một buổi sáng.', NULL, NULL, '我看了一个上午的书了。', NULL, 'wǒ kànle yígè shàngwǔ de shū le', '[]'::jsonb, 'Gợi ý Pinyin: Wǒ kànle yígè shàngwǔ de shū le.', 'Tôi đã đọc sách hết một buổi sáng. → 我看了一个上午的书了。 (Wǒ kànle yígè shàngwǔ de shū le.)', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr24_vi_4', 'lesson-24', 'vi_to_zh', 'Bạn đã chuẩn bị đầy đủ đồ đạc để đi du lịch chưa?', NULL, NULL, '去旅游的东西你准备好了吗？', NULL, 'qù lǚyóu de dōngxi nǐ zhǔnbèi hǎo le ma', '[]'::jsonb, 'Gợi ý Pinyin: Qù lǚyóu de dōngxi nǐ zhǔnbèi hǎo le ma?', 'Bạn đã chuẩn bị đầy đủ đồ đạc để đi du lịch chưa? → 去旅游的东西你准备好了吗？ (Qù lǚyóu de dōngxi nǐ zhǔnbèi hǎo le ma?)', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr24_vi_exp_1', 'lesson-24', 'vi_to_zh', 'Tiểu Lan, cậu sang Trung Quốc du học gần một năm rồi, cậu đã quen với giao thông ở Trung Quốc chưa?', NULL, NULL, '小兰， 你来中国留学快要一年了，中国的交通你习惯了吗？', NULL, 'xiǎolán nǐ lái zhōngguó liúxué kuàiyào yī nián le zhōngguó de jiāotōng nǐ xíguàn le ma', '[]'::jsonb, 'Gợi ý Pinyin: Xiǎolán, nǐ lái Zhōngguó liúxué kuàiyào yī nián le, Zhōngguó de jiāotōng nǐ xíguàn le ma?', 'Tiểu Lan, cậu sang Trung Quốc du học gần một năm rồi, cậu đã quen với giao thông ở Trung Quốc chưa? → 小兰， 你来中国留学快要一年了，中国的交通你习惯了吗？ (Xiǎolán, nǐ lái Zhōngguó liúxué kuàiyào yī nián le, Zhōngguó de jiāotōng nǐ xíguàn le ma?)', 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr24_vi_exp_2', 'lesson-24', 'vi_to_zh', 'Tớ quen rồi. Giao thông ở Trung Quốc rất tốt, giờ cao điểm cũng ít khi tắc đường.', NULL, NULL, '我习惯了。 中国的交通很好，高峰时间很少堵车。', NULL, 'wǒ xíguàn le zhōngguó de jiāotōng hěn hǎo gāofēng shíjiān hěn shǎo dǔchē', '[]'::jsonb, 'Gợi ý Pinyin: Wǒ xíguàn le. Zhōngguó de jiāotōng hěn hǎo, gāofēng shíjiān hěn shǎo dǔchē.', 'Tớ quen rồi. Giao thông ở Trung Quốc rất tốt, giờ cao điểm cũng ít khi tắc đường. → 我习惯了。 中国的交通很好，高峰时间很少堵车。 (Wǒ xíguàn le. Zhōngguó de jiāotōng hěn hǎo, gāofēng shíjiān hěn shǎo dǔchē.)', 6) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr24_vi_exp_3', 'lesson-24', 'vi_to_zh', 'Đúng vậy! Phần lớn người Trung Quốc đều tuân thủ luật giao thông.', NULL, NULL, '是啊! 大部分中国人都遵守交通规则。', NULL, 'shì a dàbùfen zhōngguó rén dōu zūnshǒu jiāotōng guīzé', '[]'::jsonb, 'Gợi ý Pinyin: Shì a! Dàbùfen Zhōngguó rén dōu zūnshǒu jiāotōng guīzé.', 'Đúng vậy! Phần lớn người Trung Quốc đều tuân thủ luật giao thông. → 是啊! 大部分中国人都遵守交通规则。 (Shì a! Dàbùfen Zhōngguó rén dōu zūnshǒu jiāotōng guīzé.)', 7) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr24_vi_exp_4', 'lesson-24', 'vi_to_zh', 'Cậu biết đi xe gì?', NULL, NULL, '你会骑什么车？', NULL, 'nǐ huì qí shénme chē', '[]'::jsonb, 'Gợi ý Pinyin: Nǐ huì qí shénme chē?', 'Cậu biết đi xe gì? → 你会骑什么车？ (Nǐ huì qí shénme chē?)', 8) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr24_vi_exp_5', 'lesson-24', 'vi_to_zh', 'Tớ biết đi xe đạp và xe máy, bố tớ vừa mua một chiếc ô tô nên tớ đang học lái xe. Khi nào học xong tớ sẽ lái xe đi chơi.', NULL, NULL, '我会骑自行车和摩托车，我爸爸刚买了一辆汽车， 所以我正在学开车。学会的时候我就开车去玩儿。', NULL, 'wǒ huì qí zìxíngchē hé mótuōchē wǒ bàba gāng mǎi le yí liàng qìchē suǒyǐ wǒ zhèngzài xué kāichē xuéhuì de shíhou wǒ jiù kāichē qù wánr', '[]'::jsonb, 'Gợi ý Pinyin: Wǒ huì qí zìxíngchē hé mótuōchē, wǒ bàba gāng mǎi le yí liàng qìchē, suǒyǐ wǒ zhèngzài xué kāichē. Xuéhuì de shíhou wǒ jiù kāichē qù wánr.', 'Tớ biết đi xe đạp và xe máy, bố tớ vừa mua một chiếc ô tô nên tớ đang học lái xe. Khi nào học xong tớ sẽ lái xe đi chơi. → 我会骑自行车和摩托车，我爸爸刚买了一辆汽车， 所以我正在学开车。学会的时候我就开车去玩儿。 (Wǒ huì qí zìxíngchē hé mótuōchē, wǒ bàba gāng mǎi le yí liàng qìchē, suǒyǐ wǒ zhèngzài xué kāichē. Xuéhuì de shíhou wǒ jiù kāichē qù wánr.)', 9) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr24_vi_exp_6', 'lesson-24', 'vi_to_zh', 'Cậu giỏi thế! Cậu có hay bị lạc đường không?', NULL, NULL, '你很棒啊！你会不会迷路?', NULL, 'nǐ hěn bàng a nǐ huì bu huì mílù', '[]'::jsonb, 'Gợi ý Pinyin: Nǐ hěn bàng a! Nǐ huì bu huì mílù?', 'Cậu giỏi thế! Cậu có hay bị lạc đường không? → 你很棒啊！你会不会迷路? (Nǐ hěn bàng a! Nǐ huì bu huì mílù?)', 10) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr24_vi_exp_7', 'lesson-24', 'vi_to_zh', 'Không đâu, nếu không biết đường thì tớ xem bản đồ hoặc nhìn biển báo chỉ đường.', NULL, NULL, '不会啊，如果不知道的话，我就看地图或者可以看路上的标志。', NULL, 'bú huì a rúguǒ bù zhīdao dehuà wǒ jiù kàn dìtú huòzhě kěyǐ kàn lùshang de biāozhì', '[]'::jsonb, 'Gợi ý Pinyin: Bú huì a, rúguǒ bù zhīdao dehuà, wǒ jiù kàn dìtú huòzhě kěyǐ kàn lùshang de biāozhì.', 'Không đâu, nếu không biết đường thì tớ xem bản đồ hoặc nhìn biển báo chỉ đường. → 不会啊，如果不知道的话，我就看地图或者可以看路上的标志。 (Bú huì a, rúguǒ bù zhīdao dehuà, wǒ jiù kàn dìtú huòzhě kěyǐ kàn lùshang de biāozhì.)', 11) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr24_vi_exp_8', 'lesson-24', 'vi_to_zh', 'Cậu thấy ở Trung Quốc đi phương tiện gì thì tiện hơn?', NULL, NULL, '你觉得在中国坐什么车比较方便？', NULL, 'nǐ juéde zài zhōngguó zuò shénme chē bǐjiào fāngbiàn', '[]'::jsonb, 'Gợi ý Pinyin: Nǐ juéde zài Zhōngguó zuò shénme chē bǐjiào fāngbiàn?', 'Cậu thấy ở Trung Quốc đi phương tiện gì thì tiện hơn? → 你觉得在中国坐什么车比较方便？ (Nǐ juéde zài Zhōngguó zuò shénme chē bǐjiào fāngbiàn?)', 12) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr24_vi_exp_9', 'lesson-24', 'vi_to_zh', 'Nếu đi chỗ gần, cậu có thể đi bộ hoặc đạp xe. Chỗ xa hơn có thể đi tàu hỏa, taxi hoặc xe buýt, nhưng hành khách trên xe buýt khá đông.', NULL, NULL, '如果要去比较近的地方，你可以走路或者骑自行车。较远的地方可以坐火车、出租车或者公共汽车， 但公共汽车上的乘客比较多。', NULL, 'rúguǒ yào qù bǐjiào jìn de dìfang nǐ kěyǐ zǒulù huòzhě qí zìxíngchē jiào yuǎn de dìfang kěyǐ zuò huǒchē chūzūchē huòzhě gōnggòng qìchē dàn gōnggòng qìchē shàng de chéngkè bǐjiào duō', '[]'::jsonb, 'Gợi ý Pinyin: Rúguǒ yào qù bǐjiào jìn de dìfang, nǐ kěyǐ zǒulù huòzhě qí zìxíngchē. Jiào yuǎn de dìfang kěyǐ zuò huǒchē, chūzūchē huòzhě gōnggòng qìchē, dàn gōnggòng qìchē shàng de chéngkè bǐjiào duō.', 'Nếu đi chỗ gần, cậu có thể đi bộ hoặc đạp xe. Chỗ xa hơn có thể đi tàu hỏa, taxi hoặc xe buýt, nhưng hành khách trên xe buýt khá đông. → 如果要去比较近的地方，你可以走路或者骑自行车。较远的地方可以坐火车、出租车或者公共汽车， 但公共汽车上的乘客比较多。 (Rúguǒ yào qù bǐjiào jìn de dìfang, nǐ kěyǐ zǒulù huòzhě qí zìxíngchē. Jiào yuǎn de dìfang kěyǐ zuò huǒchē, chūzūchē huòzhě gōnggòng qìchē, dàn gōnggòng qìchē shàng de chéngkè bǐjiào duō.)', 13) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr24_vi_exp_10', 'lesson-24', 'vi_to_zh', 'Đúng thế, hôm qua tớ đi xe buýt đến lớp, trên xe rất đông đúc. Vì vậy tài xế lái khá chậm, tớ ngồi xe mất một tiếng mới tới trường.', NULL, NULL, '是的，我昨天坐公共汽车去上课，车上很拥挤。所以司机开车开得挺慢，我坐车坐了一个小时才到学校。', NULL, 'shì de wǒ zuótiān zuò gōnggòng qìchē qù shàngkè chē shàng hěn yōngjǐ suǒyǐ sījī kāichē kāi de tǐng màn wǒ zuòchē zuòle yígè xiǎoshí cái dào xuéxiào', '[]'::jsonb, 'Gợi ý Pinyin: Shì de, wǒ zuótiān zuò gōnggòng qìchē qù shàngkè, chē shàng hěn yōngjǐ. Suǒyǐ sījī kāichē kāi de tǐng màn, wǒ zuòchē zuòle yígè xiǎoshí cái dào xuéxiào.', 'Đúng thế, hôm qua tớ đi xe buýt đến lớp, trên xe rất đông đúc. Vì vậy tài xế lái khá chậm, tớ ngồi xe mất một tiếng mới tới trường. → 是的，我昨天坐公共汽车去上课，车上很拥挤。所以司机开车开得挺慢，我坐车坐了一个小时才到学校。 (Shì de, wǒ zuótiān zuò gōnggòng qìchē qù shàngkè, chē shàng hěn yōngjǐ. Suǒyǐ sījī kāichē kāi de tǐng màn, wǒ zuòchē zuòle yígè xiǎoshí cái dào xuéxiào.)', 14) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr24_zh_1', 'lesson-24', 'zh_to_vi', '[Mở rộng] 大家 (dàjiā: mọi người)都要遵守交通规则，注意 (zhùyì: chú ý)红绿灯标志。', '大家都要遵守交通规则，注意红绿灯标志。', 'Dàjiā dōu yào zūnshǒu jiāotōng guīzé, zhùyì hónglǜdēng biāozhì.', NULL, 'Mọi người đều phải tuân thủ luật giao thông và chú ý biển báo đèn giao thông.', NULL, '["Mọi","người","đều"]'::jsonb, 'Pinyin: Dàjiā dōu yào zūnshǒu jiāotōng guīzé, zhùyì hónglǜdēng biāozhì.', '大家都要遵守交通规则，注意红绿灯标志。 (Dàjiā dōu yào zūnshǒu jiāotōng guīzé, zhùyì hónglǜdēng biāozhì.) nghĩa là: Mọi người đều phải tuân thủ luật giao thông và chú ý biển báo đèn giao thông.', 15) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr24_zh_2', 'lesson-24', 'zh_to_vi', '[Mở rộng] 骑 (qí: cưỡi, đi (xe đạp/máy))摩托车的时候一定 (yīdìng: nhất định)要戴好安全帽。', '骑摩托车的时候一定要戴好安全帽。', 'Qí mótuōchē de shíhou yídìng yào dài hǎo ānquán mào.', NULL, 'Khi đi xe máy nhất định phải đội mũ bảo hiểm cẩn thận.', NULL, '["Khi","đi","xe"]'::jsonb, 'Pinyin: Qí mótuōchē de shíhou yídìng yào dài hǎo ānquán mào.', '骑摩托车的时候一定要戴好安全帽。 (Qí mótuōchē de shíhou yídìng yào dài hǎo ānquán mào.) nghĩa là: Khi đi xe máy nhất định phải đội mũ bảo hiểm cẩn thận.', 16) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr24_zh_3', 'lesson-24', 'zh_to_vi', '他就是我的弟弟。', '他就是我的弟弟。', 'Tā jiùshì wǒ de dìdi.', NULL, 'Nó chính là em trai của tôi.', NULL, '["Nó","chính","là"]'::jsonb, 'Pinyin: Tā jiùshì wǒ de dìdi.', '他就是我的弟弟。 (Tā jiùshì wǒ de dìdi.) nghĩa là: Nó chính là em trai của tôi.', 17) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
