INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr24_zh_exp_5', 'lesson-24', 'zh_to_vi', '是啊，每个人遵守交通规则，路上才安全。', '是啊，每个人遵守交通规则，路上才安全。', 'Shì a, měi gèrén zūnshǒu jiāotōng guīzé, lùshang cái ānquán.', NULL, 'Đúng vậy, mỗi người đều tuân thủ luật giao thông thì đi đường mới an toàn.', NULL, '["đúng","vậy","mỗi","người","đều","tuân","thủ","luật","giao","thông","thì","đi","đường","mới","an","toàn"]'::jsonb, 'Pinyin: Shì a, měi gèrén zūnshǒu jiāotōng guīzé, lùshang cái ānquán.', '是啊，每个人遵守交通规则，路上才安全。 (Shì a, měi gèrén zūnshǒu jiāotōng guīzé, lùshang cái ānquán.) nghĩa là: Đúng vậy, mỗi người đều tuân thủ luật giao thông thì đi đường mới an toàn.', 23) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr24_zh_exp_6', 'lesson-24', 'zh_to_vi', '对了，我看大家骑摩托车都戴安全帽，也很注意红绿灯。', '对了，我看大家骑摩托车都戴安全帽，也很注意红绿灯。', 'Duì le, wǒ kàn dàjiā qí mótuōchē dōu dài ānquán mào, yě hěn zhùyì hónglǜdēng.', NULL, 'Đúng rồi, tớ thấy mọi người đi xe máy đều đội mũ bảo hiểm và rất chú ý đèn đỏ đèn xanh.', NULL, '["đúng","rồi","tớ","thấy","mọi","người","đi","xe","máy","đều","đội","mũ","bảo","hiểm","và","rất","chú","đèn","đỏ","đèn","xanh"]'::jsonb, 'Pinyin: Duì le, wǒ kàn dàjiā qí mótuōchē dōu dài ānquán mào, yě hěn zhùyì hónglǜdēng.', '对了，我看大家骑摩托车都戴安全帽，也很注意红绿灯。 (Duì le, wǒ kàn dàjiā qí mótuōchē dōu dài ānquán mào, yě hěn zhùyì hónglǜdēng.) nghĩa là: Đúng rồi, tớ thấy mọi người đi xe máy đều đội mũ bảo hiểm và rất chú ý đèn đỏ đèn xanh.', 24) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr24_zh_exp_7', 'lesson-24', 'zh_to_vi', '早上乘客多、容易堵车，坐地铁或者提早出门打车比较好。', '早上乘客多、容易堵车，坐地铁或者提早出门打车比较好。', 'Zǎoshang chéngkè duō, róngyì dǔchē, zuò dìtiě huòzhě tízǎo chūmén dǎchē bǐjiào hǎo.', NULL, 'Buổi sáng hành khách đông, dễ tắc đường, đi tàu điện ngầm hoặc ra sớm bắt taxi thì tốt hơn.', NULL, '["buổi","sáng","hành","khách","đông","dễ","tắc","đường","đi","tàu","điện","ngầm","hoặc","ra","sớm","bắt","taxi","thì","tốt","hơn"]'::jsonb, 'Pinyin: Zǎoshang chéngkè duō, róngyì dǔchē, zuò dìtiě huòzhě tízǎo chūmén dǎchē bǐjiào hǎo.', '早上乘客多、容易堵车，坐地铁或者提早出门打车比较好。 (Zǎoshang chéngkè duō, róngyì dǔchē, zuò dìtiě huòzhě tízǎo chūmén dǎchē bǐjiào hǎo.) nghĩa là: Buổi sáng hành khách đông, dễ tắc đường, đi tàu điện ngầm hoặc ra sớm bắt taxi thì tốt hơn.', 25) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
