INSERT INTO lessons (id, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id) VALUES ('lesson-25', 'Bài 25: Giao tiếp - Đơn nguyên 7: Du học Trung Quốc', 'Bài 25', 'Đơn nguyên 7: Du học Trung Quốc', 'Kỹ năng giao lưu, trò chuyện với người bản xứ, nâng cao khẩu ngữ và hiểu biết xã hội.', '2026-11-14'::date, 25, TRUE, NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, date_added = EXCLUDED.date_added, sort_order = EXCLUDED.sort_order, is_system = TRUE, updated_at = NOW();
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v25_1', 'lesson-25', '湖边', 'hú biān', 'biên', 'bờ hồ', 'Danh từ', '水/氵 (Thủy) (Nước, chất lỏng, sông ngòi)', '湖: 氵 (Thủy: mặt nước hồ) + 胡 (Hồ) • 边: 力 (Lực) + 辶 (Sước: đi ven mép)', 'Ghép 湖 [bộ 氵] + 边 [bộ 辶] để nhớ từ 湖边 (hú biān): "bờ hồ".', '这是留学生常遇到的困难。你应该多去外面走走，比如晚上你可以到湖边或者公园散步，然后跟那里的人说话。如果你听不清楚的话，也可以让他们再说一遍。慢慢的你的沟通问题就没有了。', 'Zhè shì liúxuéshēng cháng yùdào de kùnnan. Nǐ yīnggāi duō qù wàimian zǒuzou, bǐrú wǎnshàng nǐ kěyǐ dào hú biān huòzhě gōngyuán sànbù, ránhòu gēn', 'Đây là khó khăn thường gặp của du học sinh. Em nên ra ngoài đi dạo nhiều hơn, ví dụ buổi tối ra bờ hồ hoặc công viên tản bộ rồi trò chuyện với mọi người ở đó. Nếu nghe chưa rõ thì có thể nhờ họ nói lại lần nữa. Dần dần vấn đề giao tiếp của em sẽ hết thôi.', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v25_2', 'lesson-25', '词语', 'cíyǔ', 'ngữ', 'từ vựng', 'Danh từ', '言/讠 (Ngôn) (Lời nói, ngôn ngữ, giao tiếp)', '词: 讠 (Ngôn: ngôn từ) + 司 (Tư) • 语: 讠 (Ngôn: lời nói) + 吾 (Ngô)', 'Ghép 词 [bộ 讠] + 语 [bộ 讠] để nhớ từ 词语 (cíyǔ): "từ vựng".', '跟中国朋友说话的时候，我觉得他们说什么我都能听懂，因为朋友们说得很慢，还选择比较简单的词语。但是如果在路边随便找一个人问路，他们说得很快，还用很多我不知道的词语，我听不清楚。', 'Gēn Zhōngguó péngyou shuōhuà de shíhou, wǒ juéde tāmen shuō shénme wǒ dōu néng tīng dǒng, yīnwèi péngyoumen shuō de hěn màn, hái xuǎnzé bǐ jiào jiǎndān de cíyǔ. Dànshì rúguǒ zài lù biān suíbiàn zhǎo yígè rén wèn lù, tāmen shuō de hěn kuài, hái yòng hěnduō wǒ bù zhīdao de cíyǔ, wǒ tīng bu qīngchu.', 'Khi nói chuyện với bạn bè Trung Quốc, em thấy họ nói gì em cũng hiểu, vì các bạn nói chậm và chọn từ ngữ khá đơn giản. Nhưng nếu hỏi đường ngẫu nhiên một người ngoài phố, họ nói rất nhanh lại dùng nhiều từ em không biết nên em nghe không rõ.', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v25_3', 'lesson-25', '进步', 'jìnbù', 'tiến bộ', 'tiến bộ', 'Danh từ / Động từ / Tính từ', '辶 (Sước) (Bước đi, di chuyển, khoảng cách)', '进: 井 (Tỉnh) + 辶 (Sước: bước tiến vào) • 步: 止 (Chỉ: bước chân trên) + 少 biến thể (bước chân dưới)', 'Ghép 进 [bộ 辶] + 步 [bộ 止] để nhớ từ 进步 (jìnbù): "tiến bộ".', '您也知道我们来中国留学是为了想学汉语学得更好，说得更流利更标准。但是来中国以后，我发现自己没有进步。我不知道要怎么办，所以只好来找您。', 'Nín yě zhīdao wǒmen lái Zhōngguó liúxué shì wèile xiǎng xué Hànyǔ xué de gèng hǎo, shuō de gèng liúlì gèng biāozhǔn. Dànshì lái Zhōngguó yǐhòu, wǒ fāxiàn zìjǐ méiyǒu jìnbù. Wǒ bù zhīdào yào zěnme bàn, suǒyǐ zhǐhǎo lái zhǎo nín.', 'Thầy/cô cũng biết chúng em sang Trung Quốc du học là để học tiếng Hán tốt hơn, nói trôi chảy và chuẩn hơn. Nhưng sau khi đến Trung Quốc, em thấy mình không tiến bộ. Em không biết phải làm sao nên đành đến tìm thầy/cô.', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v25_4', 'lesson-25', '沟通', 'gōutōng', 'câu thông', 'giao tiếp, giao lưu', 'Động từ', '水/氵 (Thủy) (Nước, chất lỏng, sông ngòi)', '沟: 氵 (Thủy: rãnh nước) + 勾 (Câu) • 通: 甬 (Dũng) + 辶 (Sước: đi thông suốt)', 'Ghép 沟 [bộ 氵] + 通 [bộ 辶] để nhớ từ 沟通 (gōutōng): "giao tiếp, giao lưu".', '这是留学生常遇到的困难。你应该多去外面走走，比如晚上你可以到湖边或者公园散步，然后跟那里的人说话。如果你听不清楚的话，也可以让他们再说一遍。慢慢的你的沟通问题就没有了。', 'Zhè shì liúxuéshēng cháng yùdào de kùnnan. Nǐ yīnggāi duō qù wàimian zǒuzou, bǐrú wǎnshàng nǐ kěyǐ dào hú biān huòzhě gōngyuán sànbù, ránhòu gēn', 'Đây là khó khăn thường gặp của du học sinh. Em nên ra ngoài đi dạo nhiều hơn, ví dụ buổi tối ra bờ hồ hoặc công viên tản bộ rồi trò chuyện với mọi người ở đó. Nếu nghe chưa rõ thì có thể nhờ họ nói lại lần nữa. Dần dần vấn đề giao tiếp của em sẽ hết thôi.', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v25_5', 'lesson-25', '发现', 'fāxiàn', 'phát hiện', 'phát hiện', 'Động từ', '又 (Hựu) (Bàn tay phải, lặp lại, lại nữa)', '发: 𠃋 + 又 (Hựu: phóng ra, phát sinh) • 现: 王 (Ngọc: viên ngọc sáng) + 见 (Kiến: nhìn thấy)', 'Ghép 发 [bộ 又] + 现 [bộ 王] để nhớ từ 发现 (fāxiàn): "phát hiện".', '您也知道我们来中国留学是为了想学汉语学得更好，说得更流利更标准。但是来中国以后，我发现自己没有进步。我不知道要怎么办，所以只好来找您。', 'Nín yě zhīdao wǒmen lái Zhōngguó liúxué shì wèile xiǎng xué Hànyǔ xué de gèng hǎo, shuō de gèng liúlì gèng biāozhǔn. Dànshì lái Zhōngguó yǐhòu, wǒ fāxiàn zìjǐ méiyǒu jìnbù. Wǒ bù zhīdào yào zěnme bàn, suǒyǐ zhǐhǎo lái zhǎo nín.', 'Thầy/cô cũng biết chúng em sang Trung Quốc du học là để học tiếng Hán tốt hơn, nói trôi chảy và chuẩn hơn. Nhưng sau khi đến Trung Quốc, em thấy mình không tiến bộ. Em không biết phải làm sao nên đành đến tìm thầy/cô.', 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v25_6', 'lesson-25', '找', 'zhǎo', 'trảo', 'tìm', 'Động từ', '手/扌 (Thủ) (Bàn tay, động tác, thao tác)', '找 = 扌 (Thủ: tay lần tìm) + 戈 (Qua).', 'Chữ 找 (zhǎo) mang nghĩa "tìm", bộ chính 手/扌 (Thủ); cấu tạo: 扌 (Thủ: tay lần tìm) + 戈 (Qua).', '您也知道我们来中国留学是为了想学汉语学得更好，说得更流利更标准。但是来中国以后，我发现自己没有进步。我不知道要怎么办，所以只好来找您。', 'Nín yě zhīdao wǒmen lái Zhōngguó liúxué shì wèile xiǎng xué Hànyǔ xué de gèng hǎo, shuō de gèng liúlì gèng biāozhǔn. Dànshì lái Zhōngguó yǐhòu, wǒ fāxiàn zìjǐ méiyǒu jìnbù. Wǒ bù zhīdào yào zěnme bàn, suǒyǐ zhǐhǎo lái zhǎo nín.', 'Thầy/cô cũng biết chúng em sang Trung Quốc du học là để học tiếng Hán tốt hơn, nói trôi chảy và chuẩn hơn. Nhưng sau khi đến Trung Quốc, em thấy mình không tiến bộ. Em không biết phải làm sao nên đành đến tìm thầy/cô.', 6) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v25_7', 'lesson-25', '选择', 'xuǎnzé', 'từ Hán ngữ', 'chọn, lựa chọn', 'Động từ / Danh từ', '辶 (Sước) (Bước đi, di chuyển, khoảng cách)', '选: 先 (Tiên) + 辶 (Sước: chọn lựa bước đi) • 择: 扌 (Thủ: tay lựa chọn) + 𠬤', 'Ghép 选 [bộ 辶] + 择 [bộ 扌] để nhớ từ 选择 (xuǎnzé): "chọn, lựa chọn".', '跟中国朋友说话的时候，我觉得他们说什么我都能听懂，因为朋友们说得很慢，还选择比较简单的词语。但是如果在路边随便找一个人问路，他们说得很快，还用很多我不知道的词语，我听不清楚。', 'Gēn Zhōngguó péngyou shuōhuà de shíhou, wǒ juéde tāmen shuō shénme wǒ dōu néng tīng dǒng, yīnwèi péngyoumen shuō de hěn màn, hái xuǎnzé bǐ jiào jiǎndān de cíyǔ. Dànshì rúguǒ zài lù biān suíbiàn zhǎo yígè rén wèn lù, tāmen shuō de hěn kuài, hái yòng hěnduō wǒ bù zhīdao de cíyǔ, wǒ tīng bu qīngchu.', 'Khi nói chuyện với bạn bè Trung Quốc, em thấy họ nói gì em cũng hiểu, vì các bạn nói chậm và chọn từ ngữ khá đơn giản. Nhưng nếu hỏi đường ngẫu nhiên một người ngoài phố, họ nói rất nhanh lại dùng nhiều từ em không biết nên em nghe không rõ.', 7) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v25_8', 'lesson-25', '注意', 'zhùyì', 'từ Hán ngữ', 'chú ý', 'Động từ', '水/氵 (Thủy) (Nước, chất lỏng, sông ngòi)', '注: 氵 (Thủy: dòng nước đổ vào) + 主 (Chủ: tập trung chú ý) • 意: 音 (Âm: tiếng nói) + 心 (Tâm: ý nghĩ trong lòng)', 'Ghép 注 [bộ 氵] + 意 [bộ 心] để nhớ từ 注意 (zhùyì): "chú ý".', '不会的。中国人很热情，他们一定会帮你。可是你要注意一点，就是不要害怕说错。你是留学生，你说错也没有人笑你。', 'Bú huì de. Zhōngguó rén hěn rèqíng, tāmen yídìng huì bāng nǐ. Kěshì nǐ yào zhùyì yīdiǎn, jiùshì búyào hàipà shuō cuò. Nǐ shì liúxuéshēng, nǐ shuō cuò yě méiyǒu rén xiào nǐ.', 'Không đâu. Người Trung Quốc rất nhiệt tình, họ nhất định sẽ giúp em. Nhưng em cần chú ý một điều là đừng sợ nói sai. Em là du học sinh, nói sai cũng không ai cười em đâu.', 8) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v25_9', 'lesson-25', '打扰', 'dǎrǎo', 'từ Hán ngữ', 'làm phiền', 'Động từ', '手/扌 (Thủ) (Bàn tay, động tác, thao tác)', '打: 扌 (Thủ: bàn tay) + 丁 (Đinh) • 扰: 扌 (Thủ: tay quấy phá) + 尤 (Uông)', 'Ghép 打 [bộ 扌] + 扰 [bộ 扌] để nhớ từ 打扰 (dǎrǎo): "làm phiền".', '但是这样做可能会打扰他们。', 'Dànshì zhèyàng zuò kěnéng huì dǎrǎo tāmen.', 'Nhưng làm như vậy có thể sẽ làm phiền họ ạ.', 9) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v25_10', 'lesson-25', '让', 'ràng', 'từ Hán ngữ', 'bảo, khiến', 'Động từ', '言/讠 (Ngôn) (Lời nói, ngôn ngữ, giao tiếp)', '让 = 讠 (Ngôn: lời nói nhường nhịn) + 上 (Thượng).', 'Chữ 让 (ràng) mang nghĩa "bảo, khiến", bộ chính 言/讠 (Ngôn); cấu tạo: 讠 (Ngôn: lời nói nhường nhịn) + 上 (Thượng).', '这是留学生常遇到的困难。你应该多去外面走走，比如晚上你可以到湖边或者公园散步，然后跟那里的人说话。如果你听不清楚的话，也可以让他们再说一遍。慢慢的你的沟通问题就没有了。', 'Zhè shì liúxuéshēng cháng yùdào de kùnnan. Nǐ yīnggāi duō qù wàimian zǒuzou, bǐrú wǎnshàng nǐ kěyǐ dào hú biān huòzhě gōngyuán sànbù, ránhòu gēn', 'Đây là khó khăn thường gặp của du học sinh. Em nên ra ngoài đi dạo nhiều hơn, ví dụ buổi tối ra bờ hồ hoặc công viên tản bộ rồi trò chuyện với mọi người ở đó. Nếu nghe chưa rõ thì có thể nhờ họ nói lại lần nữa. Dần dần vấn đề giao tiếp của em sẽ hết thôi.', 10) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v25_11', 'lesson-25', '笑', 'xiào', 'từ Hán ngữ', 'cười', 'Động từ', '竹/⺮ (Trúc) (Tre trúc, đồ đan, sách vở)', '笑 = ⺮ (Trúc) + 夭 (Yêu: người nghiêng mình cười vui).', 'Chữ 笑 (xiào) mang nghĩa "cười", bộ chính 竹/⺮ (Trúc); cấu tạo: ⺮ (Trúc) + 夭 (Yêu: người nghiêng mình cười vui).', '不会的。中国人很热情，他们一定会帮你。可是你要注意一点，就是不要害怕说错。你是留学生，你说错也没有人笑你。', 'Bú huì de. Zhōngguó rén hěn rèqíng, tāmen yídìng huì bāng nǐ. Kěshì nǐ yào zhùyì yīdiǎn, jiùshì búyào hàipà shuō cuò. Nǐ shì liúxuéshēng, nǐ shuō cuò yě méiyǒu rén xiào nǐ.', 'Không đâu. Người Trung Quốc rất nhiệt tình, họ nhất định sẽ giúp em. Nhưng em cần chú ý một điều là đừng sợ nói sai. Em là du học sinh, nói sai cũng không ai cười em đâu.', 11) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v25_12', 'lesson-25', '害怕', 'hàipà', 'từ Hán ngữ', 'sợ, sợ hãi', 'Động từ', '宀 (Miên) (Mái nhà, che chở, nơi ở)', '害: 宀 (Miên) + 丰 + 口 (lời nói gây tổn hại dưới mái nhà) • 怕: 忄 (Tâm đứng: cảm xúc) + 白 (Bạch: mặt tái nhợt vì sợ)', 'Ghép 害 [bộ 宀] + 怕 [bộ 忄] để nhớ từ 害怕 (hàipà): "sợ, sợ hãi".', '不会的。中国人很热情，他们一定会帮你。可是你要注意一点，就是不要害怕说错。你是留学生，你说错也没有人笑你。', 'Bú huì de. Zhōngguó rén hěn rèqíng, tāmen yídìng huì bāng nǐ. Kěshì nǐ yào zhùyì yīdiǎn, jiùshì búyào hàipà shuō cuò. Nǐ shì liúxuéshēng, nǐ shuō cuò yě méiyǒu rén xiào nǐ.', 'Không đâu. Người Trung Quốc rất nhiệt tình, họ nhất định sẽ giúp em. Nhưng em cần chú ý một điều là đừng sợ nói sai. Em là du học sinh, nói sai cũng không ai cười em đâu.', 12) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v25_13', 'lesson-25', '清楚', 'qīngchu', 'từ Hán ngữ', 'rõ ràng, rõ rệt', 'Tính từ / Động từ', '水/氵 (Thủy) (Nước, chất lỏng, sông ngòi)', '清: 氵 (Thủy: nước trong) + 青 (Thanh: trong sạch) • 楚: 林 (Lâm: rừng cây) + 疋 (Thất: rõ ràng)', 'Ghép 清 [bộ 氵] + 楚 [bộ 木] để nhớ từ 清楚 (qīngchu): "rõ ràng, rõ rệt".', '跟中国朋友说话的时候，我觉得他们说什么我都能听懂，因为朋友们说得很慢，还选择比较简单的词语。但是如果在路边随便找一个人问路，他们说得很快，还用很多我不知道的词语，我听不清楚。', 'Gēn Zhōngguó péngyou shuōhuà de shíhou, wǒ juéde tāmen shuō shénme wǒ dōu néng tīng dǒng, yīnwèi péngyoumen shuō de hěn màn, hái xuǎnzé bǐ jiào jiǎndān de cíyǔ. Dànshì rúguǒ zài lù biān suíbiàn zhǎo yígè rén wèn lù, tāmen shuō de hěn kuài, hái yòng hěnduō wǒ bù zhīdao de cíyǔ, wǒ tīng bu qīngchu.', 'Khi nói chuyện với bạn bè Trung Quốc, em thấy họ nói gì em cũng hiểu, vì các bạn nói chậm và chọn từ ngữ khá đơn giản. Nhưng nếu hỏi đường ngẫu nhiên một người ngoài phố, họ nói rất nhanh lại dùng nhiều từ em không biết nên em nghe không rõ.', 13) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v25_14', 'lesson-25', '简单', 'jiǎndān', 'từ Hán ngữ', 'đơn giản', 'Tính từ', '竹/⺮ (Trúc) (Tre trúc, đồ đan, sách vở)', '简: ⺮ (Trúc: thẻ tre ghi chép) + 间 (Gian: giản lược) • 单: 丷 + 甲 biến thể (đơn chiếc, tờ đơn)', 'Ghép 简 [bộ 竹] + 单 [bộ 十] để nhớ từ 简单 (jiǎndān): "đơn giản".', '跟中国朋友说话的时候，我觉得他们说什么我都能听懂，因为朋友们说得很慢，还选择比较简单的词语。但是如果在路边随便找一个人问路，他们说得很快，还用很多我不知道的词语，我听不清楚。', 'Gēn Zhōngguó péngyou shuōhuà de shíhou, wǒ juéde tāmen shuō shénme wǒ dōu néng tīng dǒng, yīnwèi péngyoumen shuō de hěn màn, hái xuǎnzé bǐ jiào jiǎndān de cíyǔ. Dànshì rúguǒ zài lù biān suíbiàn zhǎo yígè rén wèn lù, tāmen shuō de hěn kuài, hái yòng hěnduō wǒ bù zhīdao de cíyǔ, wǒ tīng bu qīngchu.', 'Khi nói chuyện với bạn bè Trung Quốc, em thấy họ nói gì em cũng hiểu, vì các bạn nói chậm và chọn từ ngữ khá đơn giản. Nhưng nếu hỏi đường ngẫu nhiên một người ngoài phố, họ nói rất nhanh lại dùng nhiều từ em không biết nên em nghe không rõ.', 14) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v25_15', 'lesson-25', '标准', 'biāozhǔn', 'từ Hán ngữ', 'chuẩn, đúng', 'Tính từ', '木 (Mộc) (Cây cối, gỗ, thực vật)', '标: 木 (Mộc: cột mốc gỗ) + 示 (Thị: chỉ dấu hiệu) • 准: 冫 (Băng) + 隹 (Chuy)', 'Ghép 标 [bộ 木] + 准 [bộ 冫] để nhớ từ 标准 (biāozhǔn): "chuẩn, đúng".', '您也知道我们来中国留学是为了想学汉语学得更好，说得更流利更标准。但是来中国以后，我发现自己没有进步。我不知道要怎么办，所以只好来找您。', 'Nín yě zhīdao wǒmen lái Zhōngguó liúxué shì wèile xiǎng xué Hànyǔ xué de gèng hǎo, shuō de gèng liúlì gèng biāozhǔn. Dànshì lái Zhōngguó yǐhòu, wǒ fāxiàn zìjǐ méiyǒu jìnbù. Wǒ bù zhīdào yào zěnme bàn, suǒyǐ zhǐhǎo lái zhǎo nín.', 'Thầy/cô cũng biết chúng em sang Trung Quốc du học là để học tiếng Hán tốt hơn, nói trôi chảy và chuẩn hơn. Nhưng sau khi đến Trung Quốc, em thấy mình không tiến bộ. Em không biết phải làm sao nên đành đến tìm thầy/cô.', 15) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v25_16', 'lesson-25', '流利', 'liúlì', 'lưu', 'lưu loát, trôi chảy', 'Tính từ', '水/氵 (Thủy) (Nước, chất lỏng, sông ngòi)', '流: 氵 (Thủy: dòng nước) + 㐬 (dòng chảy trôi chảy) • 利: 禾 (Hòa: cây lúa) + 刂 (Đao: liềm sắc gặt nhanh, thuận lợi)', 'Ghép 流 [bộ 氵] + 利 [bộ 刂] để nhớ từ 流利 (liúlì): "lưu loát, trôi chảy".', '您也知道我们来中国留学是为了想学汉语学得更好，说得更流利更标准。但是来中国以后，我发现自己没有进步。我不知道要怎么办，所以只好来找您。', 'Nín yě zhīdao wǒmen lái Zhōngguó liúxué shì wèile xiǎng xué Hànyǔ xué de gèng hǎo, shuō de gèng liúlì gèng biāozhǔn. Dànshì lái Zhōngguó yǐhòu, wǒ fāxiàn zìjǐ méiyǒu jìnbù. Wǒ bù zhīdào yào zěnme bàn, suǒyǐ zhǐhǎo lái zhǎo nín.', 'Thầy/cô cũng biết chúng em sang Trung Quốc du học là để học tiếng Hán tốt hơn, nói trôi chảy và chuẩn hơn. Nhưng sau khi đến Trung Quốc, em thấy mình không tiến bộ. Em không biết phải làm sao nên đành đến tìm thầy/cô.', 16) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v25_17', 'lesson-25', '错', 'cuò', 'từ Hán ngữ', 'sai', 'Tính từ', '金/钅 (Kim) (Kim loại, tiền bạc, đồ dùng kim khí)', '错 = 钅 (Kim) + 昔 (Tích).', 'Chữ 错 (cuò) mang nghĩa "sai", bộ chính 金/钅 (Kim); cấu tạo: 钅 (Kim) + 昔 (Tích).', '不会的。中国人很热情，他们一定会帮你。可是你要注意一点，就是不要害怕说错。你是留学生，你说错也没有人笑你。', 'Bú huì de. Zhōngguó rén hěn rèqíng, tāmen yídìng huì bāng nǐ. Kěshì nǐ yào zhùyì yīdiǎn, jiùshì búyào hàipà shuō cuò. Nǐ shì liúxuéshēng, nǐ shuō cuò yě méiyǒu rén xiào nǐ.', 'Không đâu. Người Trung Quốc rất nhiệt tình, họ nhất định sẽ giúp em. Nhưng em cần chú ý một điều là đừng sợ nói sai. Em là du học sinh, nói sai cũng không ai cười em đâu.', 17) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v25_18', 'lesson-25', '着急', 'zháojí', 'từ Hán ngữ', 'lo lắng, sốt ruột', 'Tính từ', '心/忄 (Tâm) (Trái tim, tình cảm, suy nghĩ, tâm lý)', '着: 羊 biến thể + 目 (Mục: nhìn chăm chú, trạng thái tiếp diễn) • 急: ⺈ + 彐 + 心 (Tâm: lòng nôn nóng vội vã)', 'Ghép 着 [bộ 目] + 急 [bộ 心] để nhớ từ 着急 (zháojí): "lo lắng, sốt ruột".', '你不要着急，我们慢慢学。其实现在你汉语说得很流利了。', 'Nǐ búyào zháojí, wǒmen mànmàn xué. Qíshí xiànzài nǐ Hànyǔ shuō de hěn liúlì le.', 'Em đừng nóng vội, chúng ta cứ học từ từ. Thực ra bây giờ tiếng Hán của em nói cũng rất trôi chảy rồi đấy.', 18) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v25_19', 'lesson-25', '更', 'gèng', 'từ Hán ngữ', 'càng', 'Phó từ', '曰 (Viết) (Nói rằng, lời nói)', '更 = 一 + 曰 + 乂 (thay đổi, càng hơn).', 'Chữ 更 (gèng) mang nghĩa "càng", bộ chính 曰 (Viết); cấu tạo: 一 + 曰 + 乂 (thay đổi, càng hơn).', '您也知道我们来中国留学是为了想学汉语学得更好，说得更流利更标准。但是来中国以后，我发现自己没有进步。我不知道要怎么办，所以只好来找您。', 'Nín yě zhīdao wǒmen lái Zhōngguó liúxué shì wèile xiǎng xué Hànyǔ xué de gèng hǎo, shuō de gèng liúlì gèng biāozhǔn. Dànshì lái Zhōngguó yǐhòu, wǒ fāxiàn zìjǐ méiyǒu jìnbù. Wǒ bù zhīdào yào zěnme bàn, suǒyǐ zhǐhǎo lái zhǎo nín.', 'Thầy/cô cũng biết chúng em sang Trung Quốc du học là để học tiếng Hán tốt hơn, nói trôi chảy và chuẩn hơn. Nhưng sau khi đến Trung Quốc, em thấy mình không tiến bộ. Em không biết phải làm sao nên đành đến tìm thầy/cô.', 19) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v25_20', 'lesson-25', '随便', 'suíbiàn', 'tiện', 'tùy tiện, tùy ý', 'Động từ / Tính từ', '阝 (Phụ/Ấp) (Gò đất hoặc vùng đất, thành ấp)', '随: 阝 (Phụ) + 有 biến thể + 辶 (Sước: đi theo) • 便: 亻 (Nhân đứng) + 更 (Canh)', 'Ghép 随 [bộ 阝] + 便 [bộ 亻] để nhớ từ 随便 (suíbiàn): "tùy tiện, tùy ý".', '跟中国朋友说话的时候，我觉得他们说什么我都能听懂，因为朋友们说得很慢，还选择比较简单的词语。但是如果在路边随便找一个人问路，他们说得很快，还用很多我不知道的词语，我听不清楚。', 'Gēn Zhōngguó péngyou shuōhuà de shíhou, wǒ juéde tāmen shuō shénme wǒ dōu néng tīng dǒng, yīnwèi péngyoumen shuō de hěn màn, hái xuǎnzé bǐ jiào jiǎndān de cíyǔ. Dànshì rúguǒ zài lù biān suíbiàn zhǎo yígè rén wèn lù, tāmen shuō de hěn kuài, hái yòng hěnduō wǒ bù zhīdao de cíyǔ, wǒ tīng bu qīngchu.', 'Khi nói chuyện với bạn bè Trung Quốc, em thấy họ nói gì em cũng hiểu, vì các bạn nói chậm và chọn từ ngữ khá đơn giản. Nhưng nếu hỏi đường ngẫu nhiên một người ngoài phố, họ nói rất nhanh lại dùng nhiều từ em không biết nên em nghe không rõ.', 20) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v25_21', 'lesson-25', '只好', 'zhǐhǎo', 'hảo', 'đành phải, chỉ đành', 'Phó từ', '口 (Khẩu) (Miệng, ăn uống, lời nói, âm thanh phát ra)', '只: 口 (Khẩu) + 八 (Bát) • 好: 女 (Nữ: người mẹ) + 子 (Tử: đứa con)', 'Ghép 只 [bộ 口] + 好 [bộ 女] để nhớ từ 只好 (zhǐhǎo): "đành phải, chỉ đành".', '下雨了，我没带伞，只好在学校等着。', 'Xià yǔle, wǒ méi dài sǎn, zhǐhǎo zài xuéxiào děngzhe.', 'Trời mưa rồi mà tôi không mang ô, chỉ đành đợi ở trường.', 21) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v25_22', 'lesson-25', '遍', 'biàn', 'từ Hán ngữ', 'lần', 'Lượng từ', '辶 (Sước) (Bước đi, di chuyển, khoảng cách)', '遍 = 扁 (Biển) + 辶 (Sước: đi khắp một lượt).', 'Chữ 遍 (biàn) mang nghĩa "lần", bộ chính 辶 (Sước); cấu tạo: 扁 (Biển) + 辶 (Sước: đi khắp một lượt).', '这是留学生常遇到的困难。你应该多去外面走走，比如晚上你可以到湖边或者公园散步，然后跟那里的人说话。如果你听不清楚的话，也可以让他们再说一遍。慢慢的你的沟通问题就没有了。', 'Zhè shì liúxuéshēng cháng yùdào de kùnnan. Nǐ yīnggāi duō qù wàimian zǒuzou, bǐrú wǎnshàng nǐ kěyǐ dào hú biān huòzhě gōngyuán sànbù, ránhòu gēn', 'Đây là khó khăn thường gặp của du học sinh. Em nên ra ngoài đi dạo nhiều hơn, ví dụ buổi tối ra bờ hồ hoặc công viên tản bộ rồi trò chuyện với mọi người ở đó. Nếu nghe chưa rõ thì có thể nhờ họ nói lại lần nữa. Dần dần vấn đề giao tiếp của em sẽ hết thôi.', 22) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v25_23', 'lesson-25', '为了', 'wèile', 'từ Hán ngữ', 'vì, để', 'Giới từ', '丶 (Chủ) (Điểm chấm, khởi đầu)', '为: 丶 + 丿 + 𠃌 + 丶 (làm việc, vì) • 了: Bộ 亅 (Quyết - nét móc kết thúc, chữ độc thể)', 'Ghép 为 [bộ 丶] + 了 [bộ 亅] để nhớ từ 为了 (wèile): "vì, để".', '您也知道我们来中国留学是为了想学汉语学得更好，说得更流利更标准。但是来中国以后，我发现自己没有进步。我不知道要怎么办，所以只好来找您。', 'Nín yě zhīdao wǒmen lái Zhōngguó liúxué shì wèile xiǎng xué Hànyǔ xué de gèng hǎo, shuō de gèng liúlì gèng biāozhǔn. Dànshì lái Zhōngguó yǐhòu, wǒ fāxiàn zìjǐ méiyǒu jìnbù. Wǒ bù zhīdào yào zěnme bàn, suǒyǐ zhǐhǎo lái zhǎo nín.', 'Thầy/cô cũng biết chúng em sang Trung Quốc du học là để học tiếng Hán tốt hơn, nói trôi chảy và chuẩn hơn. Nhưng sau khi đến Trung Quốc, em thấy mình không tiến bộ. Em không biết phải làm sao nên đành đến tìm thầy/cô.', 23) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order) VALUES ('g25_1', 'lesson-25', '1. 得 (状态补语)', 'Vị từ  ( động hoặc tính từ) + 得 + Bổ ngữ trình độ', ' Bổ ngữ trạng thái được dùng để mô tả hay đánh giá kết quả, mức độ hoặc trạng thái của hành động hoặc một tính chất nào . Nó dùng sau vị từ ( động từ hoặc tính từ), giữa nó và vị từ thường có trợ từ kết cấu 得. Công thức chung : Công thức trên được tạ', NULL, '[{"hanzi":"他跑得很快。","pinyin":"Tā pǎo de hěn kuài.","meaning":"Anh ấy chạy rất nhanh."},{"hanzi":"我起得很早。","pinyin":"Wǒ qǐ de hěn zǎo.","meaning":"Tôi dậy rất sớm."}]'::jsonb, 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order) VALUES ('g25_2', 'lesson-25', '2. 只好 - Đành phải, không thể không', 'Cấu trúc câu ngữ pháp trọng tâm', ' Biểu thị không còn cách nào khác. 下雨了，我没带伞，只好在学校等着。 Xià yǔle, wǒ méi dài sǎn, zhǐhǎo zài xuéxiào děngzhe. Trời mưa rồi mà tôi không mang ô, chỉ đành đợi ở trường. 这个问题我不知道，只好去问妈妈。 Zhège wèntí wǒ bù zhīdào, zhǐhǎo qù wèn māma. Vấn đề này tôi không bi', NULL, '[{"hanzi":"他说汉语说得很好。","pinyin":"Tā shuō Hànyǔ shuō de hěn hǎo.","meaning":"Anh ấy nói tiếng Trung rất tốt."},{"hanzi":"他汉语说得很好。","pinyin":"Tā Hànyǔ shuō de hěn hǎo.","meaning":"Anh ấy nói tiếng Trung rất tốt."}]'::jsonb, 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order) VALUES ('g25_3', 'lesson-25', '3. 可能 Có thể, có lẽ', 'Cấu trúc câu ngữ pháp trọng tâm', ' Biểu thị khả năng. 明天天气可能会变冷。 Míngtiān tiānqì kěnéng huì biàn lěng. Ngày mai có khả năng trời sẽ trở lạnh. 都七点了，他可能下班回家了。 Dōu qī diǎnle, tā kěnéng xiàbān huí jiāle. Đã bảy giờ rồi, chắc anh ấy đã tan làm về nhà rồi. 第二十六课：毕业后 Bài 26: Sau khi tốt ngh', NULL, '[{"hanzi":"他歌唱得很好听。","pinyin":"Tā gē chàng de hěn hǎotīng.","meaning":"Anh ấy hát rất hay."},{"hanzi":"他吃得不太饱。","pinyin":"Tā chī de bú tài bǎo.","meaning":"Anh ấy ăn không no lắm."}]'::jsonb, 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order) VALUES ('g25_4', 'lesson-25', '1.专业 zhuānyè dt. tt. chuyên ngành, chuyên nghiệp', 'Cấu trúc câu ngữ pháp trọng tâm', 'Quy tắc ngữ pháp quan trọng trong Giao tiếp.', NULL, '[{"hanzi":"他歌唱得不太好听。","pinyin":"Tā gē chàng de bù tài hǎotīng.","meaning":"Anh ấy hát không hay lắm."},{"hanzi":"他说汉语说得不好。","pinyin":"Tā shuō Hànyǔ shuō de bù hǎo.","meaning":"Anh ấy nói tiếng Trung không tốt."}]'::jsonb, 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order;
INSERT INTO texts (id, lesson_id, title, description, sort_order) VALUES ('txt_25_1', 'lesson-25', 'Bài khoá #1: Hội thoại giáo trình — Giao tiếp', 'Hội thoại chuẩn giáo trình Bài 25. Từ vựng chưa học được chú thích phiên âm & nghĩa trong ngoặc.', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_25_1_1', 'txt_25_1', '阮日明', '老师，我遇到一个问题想问您！', '老师，我遇到一个问题想问您！', 'Lǎoshī, wǒ yùdào yí gè wèntí xiǎng wèn nín!', 'Thưa thầy/cô, em gặp một vấn đề muốn hỏi thầy/cô ạ!', 1) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_25_1_2', 'txt_25_1', '刘老师', '你说吧！', '你说吧！', 'Nǐ shuō ba!', 'Em cứ nói đi!', 2) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_25_1_3', 'txt_25_1', '阮日明', '您也知道我们来中国留学是为了想学汉语学得更好，说得更流利更标准。但是来中国以后，我发现自己没有进步。我不知道要怎么办，所以只好来找您。', '您也知道我们来 (lái: đến)中国留学 (liúxué: du học)是为了想学 (xué: học)汉语学得更好，说得更流利更标准。但是来中国以后，我发现自己没有 (méiyǒu: không có)进步。我不知道要怎么办，所以 (suǒyǐ: cho nên)只好来找您。', 'Nín yě zhīdao wǒmen lái Zhōngguó liúxué shì wèile xiǎng xué Hànyǔ xué de gèng hǎo, shuō de gèng liúlì gèng biāozhǔn. Dànshì lái Zhōngguó yǐhòu, wǒ fāxiàn zìjǐ méiyǒu jìnbù. Wǒ bù zhīdào yào zěnme bàn, suǒyǐ zhǐhǎo lái zhǎo nín.', 'Thầy/cô cũng biết chúng em sang Trung Quốc du học là để học tiếng Hán tốt hơn, nói trôi chảy và chuẩn hơn. Nhưng sau khi đến Trung Quốc, em thấy mình không tiến bộ. Em không biết phải làm sao nên đành đến tìm thầy/cô.', 3) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_25_1_4', 'txt_25_1', '刘老师', '你为什么这么想？', '你为 (wèi: vì)什么这么想？', 'Nǐ wèishénme zhème xiǎng?', 'Sao em lại nghĩ như vậy?', 4) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_25_1_5', 'txt_25_1', '阮日明', '跟中国朋友说话的时候，我觉得他们说什么我都能听懂，因为朋友们说得很慢，还选择比较简单的词语。但是如果在路边随便找一个人问路，他们说得很快，还用很多我不知道的词语，我听不清楚。', '跟 (gēn: cùng, với)中国朋友说话 (huà: lời nói)的时候，我觉得他们说什么我都能听 (tīng: nghe)懂，因为朋友们说得很慢，还选择比较简单的词语。但是如果在路边 (lùbiān: ven đường)随便找一个人问路 (lù: đường)，他们说得很快，还用很多我不知道的词语，我听不清楚。', 'Gēn Zhōngguó péngyou shuōhuà de shíhou, wǒ juéde tāmen shuō shénme wǒ dōu néng tīng dǒng, yīnwèi péngyoumen shuō de hěn màn, hái xuǎnzé bǐ jiào jiǎndān de cíyǔ. Dànshì rúguǒ zài lù biān suíbiàn zhǎo yígè rén wèn lù, tāmen shuō de hěn kuài, hái yòng hěnduō wǒ bù zhīdao de cíyǔ, wǒ tīng bu qīngchu.', 'Khi nói chuyện với bạn bè Trung Quốc, em thấy họ nói gì em cũng hiểu, vì các bạn nói chậm và chọn từ ngữ khá đơn giản. Nhưng nếu hỏi đường ngẫu nhiên một người ngoài phố, họ nói rất nhanh lại dùng nhiều từ em không biết nên em nghe không rõ.', 5) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_25_1_6', 'txt_25_1', '刘老师', '这是留学生常遇到的困难。你应该多去外面走走，比如晚上你可以到湖边或者公园散步，然后跟那里的人说话。如果你听不清楚的话，也可以让他们再说一遍。慢慢的你的沟通问题就没有了。', '这是留学生常遇到的困难。你应该多去外面 (wàimian: bên ngoài)走走，比如晚上你可以到湖边或者公园散步，然后跟 (gēn: cùng, với)那里 (lǐ: trong)的人说话 (huà: lời nói)。如果你听 (tīng: nghe)不清楚的话，也可以让他们再说一遍。慢慢的你的沟通问题就没有 (méiyǒu: không có)了。', 'Zhè shì liúxuéshēng cháng yùdào de kùnnan. Nǐ yīnggāi duō qù wàimian zǒuzou, bǐrú wǎnshàng nǐ kěyǐ dào hú biān huòzhě gōngyuán sànbù, ránhòu gēn', 'Đây là khó khăn thường gặp của du học sinh. Em nên ra ngoài đi dạo nhiều hơn, ví dụ buổi tối ra bờ hồ hoặc công viên tản bộ rồi trò chuyện với mọi người ở đó. Nếu nghe chưa rõ thì có thể nhờ họ nói lại lần nữa. Dần dần vấn đề giao tiếp của em sẽ hết thôi.', 6) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_25_1_7', 'txt_25_1', '阮日明', '但是这样做可能会打扰他们。', '但是这样做 (zuò: làm)可能会打扰他们。', 'Dànshì zhèyàng zuò kěnéng huì dǎrǎo tāmen.', 'Nhưng làm như vậy có thể sẽ làm phiền họ ạ.', 7) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_25_1_8', 'txt_25_1', '刘老师', '不会的。中国人很热情，他们一定会帮你。可是你要注意一点，就是不要害怕说错。你是留学生，你说错也没有人笑你。', '不会的。中国人很热情，他们一定 (yīdìng: nhất định)会帮 (bāng: giúp đỡ)你。可是你要注意一点，就是不要害怕说错。你是留学生，你说错也没有 (méiyǒu: không có)人笑你。', 'Bú huì de. Zhōngguó rén hěn rèqíng, tāmen yídìng huì bāng nǐ. Kěshì nǐ yào zhùyì yīdiǎn, jiùshì búyào hàipà shuō cuò. Nǐ shì liúxuéshēng, nǐ shuō cuò yě méiyǒu rén xiào nǐ.', 'Không đâu. Người Trung Quốc rất nhiệt tình, họ nhất định sẽ giúp em. Nhưng em cần chú ý một điều là đừng sợ nói sai. Em là du học sinh, nói sai cũng không ai cười em đâu.', 8) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_25_1_9', 'txt_25_1', '阮日明', '老师，我知道了。', '老师，我知道了。', 'Lǎoshī, wǒ zhīdao le.', 'Vâng, em hiểu rồi ạ.', 9) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_25_1_10', 'txt_25_1', '刘老师', '你不要着急，我们慢慢学。其实现在你汉语说得很流利了。', '你不要着急，我们慢慢学 (xué: học)。其实现在你汉语说得很流利了。', 'Nǐ búyào zháojí, wǒmen mànmàn xué. Qíshí xiànzài nǐ Hànyǔ shuō de hěn liúlì le.', 'Em đừng nóng vội, chúng ta cứ học từ từ. Thực ra bây giờ tiếng Hán của em nói cũng rất trôi chảy rồi đấy.', 10) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_25_1_11', 'txt_25_1', '阮日明', '谢谢您！', '谢谢您！', 'Xièxie nín!', 'Em cảm ơn thầy/cô ạ!', 11) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_25_1_1', 'lesson-25', 'txt_25_1', 'listening', 'listening', '老师，我遇到一个问题想问您！', NULL, 'Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Bệnh của mẹ khỏi lâu rồi, con đừng lo lắng.","Thưa thầy/cô, em gặp một vấn đề muốn hỏi thầy/cô ạ!","bút bi của cô ấy","Anh ấy vẫn cứ chờ đợi cậu."]'::jsonb, 1, 'Nội dung nghe được: 老师，我遇到一个问题想问您！ (Lǎoshī, wǒ yùdào yí gè wèntí xiǎng wèn nín!) → Thưa thầy/cô, em gặp một vấn đề muốn hỏi thầy/cô ạ!', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_25_1_2', 'lesson-25', 'txt_25_1', 'listening', 'listening', '你说吧！', NULL, 'Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["你说吧！","他歌唱 (gēchàng: ca hát)得不太好听 (tīng: nghe)。","他说汉语说得很好。","选择简单清楚的词语会让交 (jiāo: nộp, kết bạn)流 (liú: chảy)更轻松。"]'::jsonb, 0, 'Câu vừa đọc: 你说吧！ (Nǐ shuō ba!) → Em cứ nói đi!', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_25_1_3', 'lesson-25', 'txt_25_1', 'listening', 'listening', '您也知道我们来中国留学是为了想学汉语学得更好，说得更流利更标准。但是来中国以后，我发现自己没有进步。我不知道要怎么办，所以只好来找您。', NULL, 'Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Mai tớ thi rồi, không thể đi cùng cậu được.","Trời có thể sắp mưa.","Tối hôm qua tôi đã ôn tập qua bài khóa rồi.","Thầy/cô cũng biết chúng em sang Trung Quốc du học là để học tiếng Hán tốt hơn, nói trôi chảy và chuẩn hơn. Nhưng sau khi đến Trung Quốc, em thấy mình không tiến bộ. Em không biết phải làm sao nên đành đến tìm thầy/cô."]'::jsonb, 3, 'Nội dung nghe được: 您也知道我们来中国留学是为了想学汉语学得更好，说得更流利更标准。但是来中国以后，我发现自己没有进步。我不知道要怎么办，所以只好来找您。 (Nín yě zhīdao wǒmen lái Zhōngguó liúxué shì wèile xiǎng xué Hànyǔ xué de gèng hǎo, shuō de gèng liúlì gèng biāozhǔn. Dànshì lái Zhōngguó yǐhòu, wǒ fāxiàn zìjǐ méiyǒu jìnbù. Wǒ bù zhīdào yào zěnme bàn, suǒyǐ zhǐhǎo lái zhǎo nín.) → Thầy/cô cũng biết chúng em sang Trung Quốc du học là để học tiếng Hán tốt hơn, nói trôi chảy và chuẩn hơn. Nhưng sau khi đến Trung Quốc, em thấy mình không tiến bộ. Em không biết phải làm sao nên đành đến tìm thầy/cô.', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_25_1_4', 'lesson-25', 'txt_25_1', 'listening', 'listening', '你为什么这么想？', NULL, 'Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["他歌唱 (gēchàng: ca hát)得不太好听 (tīng: nghe)。","晚上在湖边散步时 (shí: lúc, khi)，我发现很多人都在练习说话 (huà: lời nói)。","你为 (wèi: vì)什么这么想？","爸爸累得下 (xià: dưới / xuống)了班 (bān: lớp học)就想睡觉 (jiào: giấc ngủ)。"]'::jsonb, 2, 'Câu vừa đọc: 你为什么这么想？ (Nǐ wèishénme zhème xiǎng?) → Sao em lại nghĩ như vậy?', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO texts (id, lesson_id, title, description, sort_order) VALUES ('txt_25_2', 'lesson-25', 'Bài nghe tổng hợp: Ôn tập lũy tiến (Bài 1 – Bài 25)', 'Kết hợp từ vựng & mẫu câu đã học từ Bài 1 đến Bài 24 cùng trọng tâm Bài 25 để củng cố phản xạ nghe.', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_25_2_1', 'txt_25_2', 'Ôn Bài 24', '如果有什么不知道，你就问我。', '如果有什么不知道，你就问我。', 'Rúguǒ yǒu shénme bù zhīdào, nǐ jiù wèn wǒ.', 'Nếu có gì không biết thì cậu cứ hỏi tớ.', 1) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_25_2_2', 'txt_25_2', 'Bài 25', '他说汉语说得很好。', '他说汉语说得很好。', 'Tā shuō Hànyǔ shuō de hěn hǎo.', 'Anh ấy nói tiếng Trung rất tốt.', 2) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_25_2_3', 'txt_25_2', 'Ôn Bài 12', '从我家走路到学校，五分钟就到。', '从我家走路到学校，五分钟就到。', 'Cóng wǒ jiā zǒulù dào xuéxiào, wǔ fēnzhōng jiù dào.', 'Đi bộ từ nhà tôi tới trường, chỉ mất 5 phút là đến rồi.', 3) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_25_2_4', 'txt_25_2', 'Bài 25', '他汉语说得很好。', '他汉语说得很好。', 'Tā Hànyǔ shuō de hěn hǎo.', 'Anh ấy nói tiếng Trung rất tốt.', 4) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_25_2_5', 'txt_25_2', 'Ôn Bài 1', '晚上好！', '晚上好！', 'Wǎnshang hǎo', 'Chào buổi tối!', 5) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_25_2_6', 'txt_25_2', 'Bài 25', '他说汉语说得不好。', '他说汉语说得不好。', 'Tā shuō Hànyǔ shuō de bù hǎo.', 'Anh ấy nói tiếng Trung không tốt.', 6) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_25_2_7', 'txt_25_2', 'Ôn Bài 9', '你买吧！', '你买吧！', 'Nǐ mǎi ba!', 'Cậu mua đi!', 7) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_25_2_8', 'txt_25_2', 'Bài 25', '这个问题我不知道，只好去问妈妈。', '这个问题我不知道，只好去问妈妈。', 'Zhège wèntí wǒ bù zhīdào, zhǐhǎo qù wèn māma.', 'Vấn đề này tôi không biết nên chỉ đành đi hỏi mẹ.', 8) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_25_2_1', 'lesson-25', 'txt_25_2', 'listening', 'listening', '如果有什么不知道，你就问我。', NULL, '[Ôn tập Bài 24] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Phía bên trái trường học có một ngân hàng.","Nếu có gì không biết thì cậu cứ hỏi tớ.","Anh ấy kể chuyện cho tôi nghe một cách hạnh phúc.","Một bức tranh"]'::jsonb, 1, 'Nội dung nghe được: 如果有什么不知道，你就问我。 (Rúguǒ yǒu shénme bù zhīdào, nǐ jiù wèn wǒ.) → Nếu có gì không biết thì cậu cứ hỏi tớ.', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_25_2_2', 'lesson-25', 'txt_25_2', 'listening', 'listening', '他说汉语说得很好。', NULL, '[Bài 25] Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["他说汉语说得不好。","他说汉语说得很好。","你觉得我穿 (chuān: mặc)得漂不漂亮？","下雨了，我没 (méi: chưa, không có)带 (dài: mang theo)伞 (sǎn: cái ô, dù)，只好在学校等着 (zhe: đang (trạng thái))。"]'::jsonb, 1, 'Câu vừa đọc: 他说汉语说得很好。 (Tā shuō Hànyǔ shuō de hěn hǎo.) → Anh ấy nói tiếng Trung rất tốt.', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_25_2_3', 'lesson-25', 'txt_25_2', 'listening', 'listening', '从我家走路到学校，五分钟就到。', NULL, '[Ôn tập Bài 12] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Năm nay cậu bao nhiêu tuổi? (Hỏi chung chung)","Đi bộ từ nhà tôi tới trường, chỉ mất 5 phút là đến rồi.","Không phải ngoài trời đang mưa à? Cậu dùng ô của tớ đi! (Khẳng định","bút bi của cô ấy"]'::jsonb, 1, 'Nội dung nghe được: 从我家走路到学校，五分钟就到。 (Cóng wǒ jiā zǒulù dào xuéxiào, wǔ fēnzhōng jiù dào.) → Đi bộ từ nhà tôi tới trường, chỉ mất 5 phút là đến rồi.', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_25_2_4', 'lesson-25', 'txt_25_2', 'listening', 'listening', '他汉语说得很好。', NULL, '[Bài 25] Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["他歌唱 (gēchàng: ca hát)得很好听 (tīng: nghe)。","弟弟高兴得跳 (tiào: nhảy)了起来 (qǐlái: lên (bổ ngữ))。","他汉语说得很好。","都七点了，他可能下班 (xiàbān: tan làm)回家了。"]'::jsonb, 2, 'Câu vừa đọc: 他汉语说得很好。 (Tā Hànyǔ shuō de hěn hǎo.) → Anh ấy nói tiếng Trung rất tốt.', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_25_2_5', 'lesson-25', 'txt_25_2', 'listening', 'listening', '晚上好！', NULL, '[Ôn tập Bài 1] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Xin hỏi, đi đến bệnh viện như thế nào vậy?","Bên trái tôi không phải là tòa giảng đường.","Chào buổi tối!","người mà tôi yêu"]'::jsonb, 2, 'Nội dung nghe được: 晚上好！ (Wǎnshang hǎo) → Chào buổi tối!', 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO texts (id, lesson_id, title, description, sort_order) VALUES ('txt_25_3', 'lesson-25', 'Bài khoá mở rộng: Bí quyết luyện khẩu ngữ hiệu quả (Mở rộng)', 'Hội thoại tình huống mới xây dựng dựa trên từ vựng và ngữ pháp Bài 25 (không trùng lặp nguyên văn giáo trình).', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_25_3_1', 'txt_25_3', 'Lan', '老师，我发现和中国人交流时，我还是有点儿害怕说错。', '老师，我发现和中国人交 (jiāo: nộp, kết bạn)流 (liú: chảy)时 (shí: lúc, khi)，我还是有点儿害怕说错。', 'Lǎoshī, wǒ fāxiàn hé Zhōngguó rén jiāoliú shí, wǒ háishi yǒudiǎnr hàipà shuō cuò.', 'Thưa thầy, em thấy khi giao tiếp với người Trung Quốc em vẫn hơi sợ nói sai.', 1) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_25_3_2', 'txt_25_3', 'Thầy Lưu', '别怕！你应该先从简单的词语开始，慢慢就能说清楚。', '别 (bié: đừng)怕！你应该先从简单的词语开 (kāi: mở, lái)始，慢慢就能说清楚。', 'Bié pà! Nǐ yīnggāi xiān cóng jiǎndān de cíyǔ kāishǐ, mànmàn jiù néng shuō qīngchu.', 'Đừng sợ! Em nên bắt đầu từ những từ ngữ đơn giản trước, dần dần sẽ nói rõ ràng thôi.', 2) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_25_3_3', 'txt_25_3', 'Lan', '我可以晚上去湖边找大家聊天儿吗？怕打扰他们。', '我可以晚上去湖边找大家 (dàjiā: mọi người)聊天儿吗？怕打扰他们。', 'Wǒ kěyǐ wǎnshang qù húbiān zhǎo dàjiā liáotiānr ma? Pà dǎrǎo tāmen.', 'Buổi tối em có thể ra bờ hồ bắt chuyện với mọi người không? Em sợ làm phiền họ ạ.', 3) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_25_3_4', 'txt_25_3', 'Thầy Lưu', '只要礼貌沟通，大家不仅不会笑你，还会帮你快速进步！', '只要礼貌沟通，大家 (dàjiā: mọi người)不仅不会笑你，还会帮 (bāng: giúp đỡ)你快速进步！', 'Zhǐyào lǐmào gōutōng, dàjiā bùjǐn bú huì xiào nǐ, hái huì bāng nǐ kuàisù jìnbù!', 'Chỉ cần giao tiếp lịch sự, mọi người chẳng những không cười em mà còn giúp em tiến bộ nhanh đấy!', 4) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_25_3_1', 'lesson-25', 'txt_25_3', 'listening', 'listening', '老师，我发现和中国人交流时，我还是有点儿害怕说错。 别怕！你应该先从简单的词语开始，慢慢就能说清楚。 我可以晚上去湖边找大家聊天儿吗？怕打扰他们。 只要礼貌沟通，大家不仅不会笑你，还会帮你快速进步！', NULL, '[Nghe hiểu tình huống mới] Thầy Lưu khuyên Ngọc Lan bắt đầu luyện nói như thế nào để bớt sợ sai?', '["Chỉ học thuộc từ điển ở nhà, không nói chuyện với ai","Phải dùng ngay các câu thật dài và khó","Tránh đi dạo công viên hoặc bờ hồ","Bắt đầu từ những từ ngữ đơn giản và mạnh dạn giao tiếp lịch sự với mọi người"]'::jsonb, 3, 'Thầy Lưu dặn ''先从简单的词语开始... 只要礼貌沟通，大家...会帮你快速进步''.', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_25_3_2', 'lesson-25', 'txt_25_3', 'listening', 'listening', '老师，我发现和中国人交流时，我还是有点儿害怕说错。', NULL, '[Mở rộng] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Nghỉ ngơi một chút","Anh ấy hát không hay lắm.","Thưa thầy, em thấy khi giao tiếp với người Trung Quốc em vẫn hơi sợ nói sai.","Ngày mai tớ sẽ đến nhà cậu chơi tiếp nhé!"]'::jsonb, 2, 'Nội dung nghe được: 老师，我发现和中国人交流时，我还是有点儿害怕说错。 (Lǎoshī, wǒ fāxiàn hé Zhōngguó rén jiāoliú shí, wǒ háishi yǒudiǎnr hàipà shuō cuò.) → Thưa thầy, em thấy khi giao tiếp với người Trung Quốc em vẫn hơi sợ nói sai.', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_25_3_3', 'lesson-25', 'txt_25_3', 'listening', 'listening', '别怕！你应该先从简单的词语开始，慢慢就能说清楚。', NULL, '[Mở rộng] Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["不好意思，现在打扰您五分钟可以吗？","他吃得不太饱 (bǎo: no)。","明天天气可能会变 (biàn: biến đổi, trở nên)冷。","别 (bié: đừng)怕！你应该先从简单的词语开 (kāi: mở, lái)始，慢慢就能说清楚。"]'::jsonb, 3, 'Câu vừa đọc: 别怕！你应该先从简单的词语开始，慢慢就能说清楚。 (Bié pà! Nǐ yīnggāi xiān cóng jiǎndān de cíyǔ kāishǐ, mànmàn jiù néng shuō qīngchu.) → Đừng sợ! Em nên bắt đầu từ những từ ngữ đơn giản trước, dần dần sẽ nói rõ ràng thôi.', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_25_3_4', 'lesson-25', 'txt_25_3', 'listening', 'listening', '我可以晚上去湖边找大家聊天儿吗？怕打扰他们。', NULL, '[Mở rộng] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["quyển từ điển kia","Nếu tám giờ mà tớ vẫn chưa quay lại thì cậu không cần đợi tớ nữa nhé.","Tôi 23 tuổi.","Buổi tối em có thể ra bờ hồ bắt chuyện với mọi người không? Em sợ làm phiền họ ạ."]'::jsonb, 3, 'Nội dung nghe được: 我可以晚上去湖边找大家聊天儿吗？怕打扰他们。 (Wǒ kěyǐ wǎnshang qù húbiān zhǎo dàjiā liáotiānr ma? Pà dǎrǎo tāmen.) → Buổi tối em có thể ra bờ hồ bắt chuyện với mọi người không? Em sợ làm phiền họ ạ.', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss25_1', 'lesson-25', '不要害怕说错没有人会笑你的', '[Mở rộng] Đừng sợ nói sai, sẽ không có ai cười bạn đâu.', 'Búyào hàipà shuō cuò, méiyǒu rén huì xiào nǐ de.', '["不要","害怕","说错","没有","人会笑","你的"]'::jsonb, 'Từ chưa học: 没有 (méiyǒu: không có)', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss25_2', 'lesson-25', '他的普通话说得又流利又标准', '[Mở rộng] Tiếng phổ thông của anh ấy nói vừa trôi chảy vừa chuẩn.', 'Tā de Pǔtōnghuà shuō de yòu liúlì yòu biāozhǔn.', '["他的","普通","话说","得又","流利又","标准"]'::jsonb, 'Từ chưa học: 话 (huà: lời nói)', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss25_3', 'lesson-25', '他说汉语说得很好', 'Anh ấy nói tiếng Trung rất tốt.', 'Tā shuō Hànyǔ shuō de hěn hǎo.', '["他说","汉语","说","得","很","好"]'::jsonb, NULL, 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss25_4', 'lesson-25', '他汉语说得很好', 'Anh ấy nói tiếng Trung rất tốt.', 'Tā Hànyǔ shuō de hěn hǎo.', '["他","汉语","说","得","很","好"]'::jsonb, NULL, 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss25_5', 'lesson-25', '从宿舍到食堂怎么走', '[Ôn tập Bài 6] Từ ký túc xá đến nhà ăn đi như thế nào?', 'Cóng sùshè dào shítáng zěnme zǒu?', '["从","宿舍","到","食堂","怎么","走"]'::jsonb, NULL, 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss25_6', 'lesson-25', '她叫什么名字', '[Ôn tập Bài 2] Cô ấy tên là gì?', 'Tā jiào shénme míngzi?', '["她","叫","什么","名字"]'::jsonb, NULL, 6) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss25_exp_1', 'lesson-25', '老师我遇到一个问题想问您', 'Thưa thầy/cô, em gặp một vấn đề muốn hỏi thầy/cô ạ!', 'Lǎoshī, wǒ yùdào yí gè wèntí xiǎng wèn nín!', '["老师","我","遇到","一","个","问题","想","问","您"]'::jsonb, NULL, 7) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss25_exp_2', 'lesson-25', '你说吧', 'Em cứ nói đi!', 'Nǐ shuō ba!', '["你","说","吧"]'::jsonb, NULL, 8) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss25_exp_3', 'lesson-25', '您也知道我们来中国留学是为了想学汉语学得更好说得更流利更标准但是来中国以后我发现自己没有进步我不知道要怎么办所以只好来找您', 'Thầy/cô cũng biết chúng em sang Trung Quốc du học là để học tiếng Hán tốt hơn, nói trôi chảy và chuẩn hơn. Nhưng sau khi đến Trung Quốc, em thấy mình không tiến bộ. Em không biết phải làm sao nên đành đến tìm thầy/cô.', 'Nín yě zhīdao wǒmen lái Zhōngguó liúxué shì wèile xiǎng xué Hànyǔ xué de gèng hǎo, shuō de gèng liúlì gèng biāozhǔn. Dànshì lái Zhōngguó yǐhòu, wǒ fāxiàn zìjǐ méiyǒu jìnbù. Wǒ bù zhīdào yào zěnme bàn, suǒyǐ zhǐhǎo lái zhǎo nín.', '["您","也","知道","我们","来","中国","留","学","是","为了","想","学","汉语","学","得","更","好","说","得","更","流利","更","标准","但是","来","中国","以后","我","发现","自己","没有","进步","我","不","知道","要","怎么","办","所以","只好","来","找","您"]'::jsonb, NULL, 9) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss25_exp_4', 'lesson-25', '你为什么这么想', 'Sao em lại nghĩ như vậy?', 'Nǐ wèishénme zhème xiǎng?', '["你","为","什么","这么","想"]'::jsonb, NULL, 10) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss25_exp_5', 'lesson-25', '跟中国朋友说话的时候我觉得他们说什么我都能听懂因为朋友们说得很慢还选择比较简单的词语但是如果在路边随便找一个人问路他们说得很快还用很多我不知道的词语我听不清楚', 'Khi nói chuyện với bạn bè Trung Quốc, em thấy họ nói gì em cũng hiểu, vì các bạn nói chậm và chọn từ ngữ khá đơn giản. Nhưng nếu hỏi đường ngẫu nhiên một người ngoài phố, họ nói rất nhanh lại dùng nhiều từ em không biết nên em nghe không rõ.', 'Gēn Zhōngguó péngyou shuōhuà de shíhou, wǒ juéde tāmen shuō shénme wǒ dōu néng tīng dǒng, yīnwèi péngyoumen shuō de hěn màn, hái xuǎnzé bǐ jiào jiǎndān de cíyǔ. Dànshì rúguǒ zài lù biān suíbiàn zhǎo yígè rén wèn lù, tāmen shuō de hěn kuài, hái yòng hěnduō wǒ bù zhīdao de cíyǔ, wǒ tīng bu qīngchu.', '["跟","中国","朋友","说","话","的","时候","我","觉得","他们","说","什么","我","都","能","听","懂","因为","朋友","们","说","得","很","慢","还","选择","比较","简单","的","词语","但是","如果","在","路","边","随便","找","一","个","人","问","路","他们","说","得","很","快","还","用","很","多","我","不","知道","的","词语","我","听","不","清楚"]'::jsonb, NULL, 11) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss25_exp_6', 'lesson-25', '这是留学生常遇到的困难你应该多去外面走走比如晚上你可以到湖边或者公园散步然后跟那里的人说话如果你听不清楚的话也可以让他们再说一遍慢慢的你的沟通问题就没有了', 'Đây là khó khăn thường gặp của du học sinh. Em nên ra ngoài đi dạo nhiều hơn, ví dụ buổi tối ra bờ hồ hoặc công viên tản bộ rồi trò chuyện với mọi người ở đó. Nếu nghe chưa rõ thì có thể nhờ họ nói lại lần nữa. Dần dần vấn đề giao tiếp của em sẽ hết thôi.', 'Zhè shì liúxuéshēng cháng yùdào de kùnnan. Nǐ yīnggāi duō qù wàimian zǒuzou, bǐrú wǎnshàng nǐ kěyǐ dào hú biān huòzhě gōngyuán sànbù, ránhòu gēn', '["这","是","留学生","常","遇到","的","困难","你","应该","多","去","外","面","走","走","比如","晚上","你","可以","到","湖边","或者","公园","散步","然","后","跟","那里","的","人","说","话","如果","你","听","不","清楚","的","话","也","可以","让","他们","再说","一","遍","慢慢","的","你","的","沟通","问题","就","没有","了"]'::jsonb, NULL, 12) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss25_exp_7', 'lesson-25', '但是这样做可能会打扰他们', 'Nhưng làm như vậy có thể sẽ làm phiền họ ạ.', 'Dànshì zhèyàng zuò kěnéng huì dǎrǎo tāmen.', '["但是","这样","做","可能","会","打扰","他们"]'::jsonb, NULL, 13) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss25_exp_8', 'lesson-25', '不会的中国人很热情他们一定会帮你可是你要注意一点就是不要害怕说错你是留学生你说错也没有人笑你', 'Không đâu. Người Trung Quốc rất nhiệt tình, họ nhất định sẽ giúp em. Nhưng em cần chú ý một điều là đừng sợ nói sai. Em là du học sinh, nói sai cũng không ai cười em đâu.', 'Bú huì de. Zhōngguó rén hěn rèqíng, tāmen yídìng huì bāng nǐ. Kěshì nǐ yào zhùyì yīdiǎn, jiùshì búyào hàipà shuō cuò. Nǐ shì liúxuéshēng, nǐ shuō cuò yě méiyǒu rén xiào nǐ.', '["不","会","的","中国","人","很","热情","他们","一","定","会","帮","你","可是","你","要","注意","一点","就","是","不","要","害怕","说","错","你","是","留学生","你","说","错","也","没有","人","笑","你"]'::jsonb, NULL, 14) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss25_exp_9', 'lesson-25', '老师我知道了', 'Vâng, em hiểu rồi ạ.', 'Lǎoshī, wǒ zhīdao le.', '["老师","我","知道","了"]'::jsonb, NULL, 15) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss25_exp_10', 'lesson-25', '你不要着急我们慢慢学其实现在你汉语说得很流利了', 'Em đừng nóng vội, chúng ta cứ học từ từ. Thực ra bây giờ tiếng Hán của em nói cũng rất trôi chảy rồi đấy.', 'Nǐ búyào zháojí, wǒmen mànmàn xué. Qíshí xiànzài nǐ Hànyǔ shuō de hěn liúlì le.', '["你","不","要","着急","我们","慢慢","学","其实","现在","你","汉语","说","得","很","流利","了"]'::jsonb, NULL, 16) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss25_exp_11', 'lesson-25', '谢谢您', 'Em cảm ơn thầy/cô ạ!', 'Xièxie nín!', '["谢谢","您"]'::jsonb, NULL, 17) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss25_exp_12', 'lesson-25', '如果有什么不知道你就问我', 'Nếu có gì không biết thì cậu cứ hỏi tớ.', 'Rúguǒ yǒu shénme bù zhīdào, nǐ jiù wèn wǒ.', '["如果","有","什么","不","知道","你","就","问","我"]'::jsonb, NULL, 18) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss25_exp_13', 'lesson-25', '从我家走路到学校五分钟就到', 'Đi bộ từ nhà tôi tới trường, chỉ mất 5 phút là đến rồi.', 'Cóng wǒ jiā zǒulù dào xuéxiào, wǔ fēnzhōng jiù dào.', '["从","我","家","走路","到","学校","五","分","钟","就","到"]'::jsonb, NULL, 19) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss25_exp_14', 'lesson-25', '晚上好', 'Chào buổi tối!', 'Wǎnshang hǎo', '["晚上","好"]'::jsonb, NULL, 20) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr25_vi_1', 'lesson-25', 'vi_to_zh', '[Mở rộng] Xin lỗi, bây giờ làm phiền thầy năm phút có được không ạ?', NULL, NULL, '不好意思，现在打扰您五分钟可以吗？', NULL, 'bù hǎoyìsi xiànzài dǎrǎo nín wǔ fēnzhōng kěyǐ ma', '[]'::jsonb, 'Gợi ý Pinyin: Bù hǎoyìsi, xiànzài dǎrǎo nín wǔ fēnzhōng kěyǐ ma?', 'Xin lỗi, bây giờ làm phiền thầy năm phút có được không ạ? → 不好意思，现在打扰您五分钟可以吗？ (Bù hǎoyìsi, xiànzài dǎrǎo nín wǔ fēnzhōng kěyǐ ma?)', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr25_vi_2', 'lesson-25', 'vi_to_zh', '[Mở rộng] Giao tiếp nhiều với người Trung Quốc, tiếng Hán của bạn nhất định sẽ tiến bộ.', NULL, NULL, '多和中国人沟通，你的汉语一定会进步。', NULL, 'duō hé zhōngguó rén gōutōng nǐ de hànyǔ yídìng huì jìnbù', '[]'::jsonb, 'Gợi ý Pinyin: Duō hé Zhōngguó rén gōutōng, nǐ de Hànyǔ yídìng huì jìnbù. | Từ chưa học: 一定 (yīdìng: nhất định)', 'Giao tiếp nhiều với người Trung Quốc, tiếng Hán của bạn nhất định sẽ tiến bộ. → 多和中国人沟通，你的汉语一定会进步。 (Duō hé Zhōngguó rén gōutōng, nǐ de Hànyǔ yídìng huì jìnbù.)', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr25_vi_3', 'lesson-25', 'vi_to_zh', 'Anh ấy nói tiếng Trung rất tốt.', NULL, NULL, '他说汉语说得很好。', NULL, 'tā shuō hànyǔ shuō de hěn hǎo', '[]'::jsonb, 'Gợi ý Pinyin: Tā shuō Hànyǔ shuō de hěn hǎo.', 'Anh ấy nói tiếng Trung rất tốt. → 他说汉语说得很好。 (Tā shuō Hànyǔ shuō de hěn hǎo.)', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr25_vi_4', 'lesson-25', 'vi_to_zh', 'Anh ấy nói tiếng Trung rất tốt.', NULL, NULL, '他汉语说得很好。', NULL, 'tā hànyǔ shuō de hěn hǎo', '[]'::jsonb, 'Gợi ý Pinyin: Tā Hànyǔ shuō de hěn hǎo.', 'Anh ấy nói tiếng Trung rất tốt. → 他汉语说得很好。 (Tā Hànyǔ shuō de hěn hǎo.)', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr25_vi_exp_1', 'lesson-25', 'vi_to_zh', 'Thưa thầy/cô, em gặp một vấn đề muốn hỏi thầy/cô ạ!', NULL, NULL, '老师，我遇到一个问题想问您！', NULL, 'lǎoshī wǒ yùdào yí gè wèntí xiǎng wèn nín', '[]'::jsonb, 'Gợi ý Pinyin: Lǎoshī, wǒ yùdào yí gè wèntí xiǎng wèn nín!', 'Thưa thầy/cô, em gặp một vấn đề muốn hỏi thầy/cô ạ! → 老师，我遇到一个问题想问您！ (Lǎoshī, wǒ yùdào yí gè wèntí xiǎng wèn nín!)', 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr25_vi_exp_2', 'lesson-25', 'vi_to_zh', 'Em cứ nói đi!', NULL, NULL, '你说吧！', NULL, 'nǐ shuō ba', '[]'::jsonb, 'Gợi ý Pinyin: Nǐ shuō ba!', 'Em cứ nói đi! → 你说吧！ (Nǐ shuō ba!)', 6) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr25_vi_exp_3', 'lesson-25', 'vi_to_zh', 'Thầy/cô cũng biết chúng em sang Trung Quốc du học là để học tiếng Hán tốt hơn, nói trôi chảy và chuẩn hơn. Nhưng sau khi đến Trung Quốc, em thấy mình không tiến bộ. Em không biết phải làm sao nên đành đến tìm thầy/cô.', NULL, NULL, '您也知道我们来中国留学是为了想学汉语学得更好，说得更流利更标准。但是来中国以后，我发现自己没有进步。我不知道要怎么办，所以只好来找您。', NULL, 'nín yě zhīdao wǒmen lái zhōngguó liúxué shì wèile xiǎng xué hànyǔ xué de gèng hǎo shuō de gèng liúlì gèng biāozhǔn dànshì lái zhōngguó yǐhòu wǒ fāxiàn zìjǐ méiyǒu jìnbù wǒ bù zhīdào yào zěnme bàn suǒyǐ zhǐhǎo lái zhǎo nín', '[]'::jsonb, 'Gợi ý Pinyin: Nín yě zhīdao wǒmen lái Zhōngguó liúxué shì wèile xiǎng xué Hànyǔ xué de gèng hǎo, shuō de gèng liúlì gèng biāozhǔn. Dànshì lái Zhōngguó yǐhòu, wǒ fāxiàn zìjǐ méiyǒu jìnbù. Wǒ bù zhīdào yào zěnme bàn, suǒyǐ zhǐhǎo lái zhǎo nín.', 'Thầy/cô cũng biết chúng em sang Trung Quốc du học là để học tiếng Hán tốt hơn, nói trôi chảy và chuẩn hơn. Nhưng sau khi đến Trung Quốc, em thấy mình không tiến bộ. Em không biết phải làm sao nên đành đến tìm thầy/cô. → 您也知道我们来中国留学是为了想学汉语学得更好，说得更流利更标准。但是来中国以后，我发现自己没有进步。我不知道要怎么办，所以只好来找您。 (Nín yě zhīdao wǒmen lái Zhōngguó liúxué shì wèile xiǎng xué Hànyǔ xué de gèng hǎo, shuō de gèng liúlì gèng biāozhǔn. Dànshì lái Zhōngguó yǐhòu, wǒ fāxiàn zìjǐ méiyǒu jìnbù. Wǒ bù zhīdào yào zěnme bàn, suǒyǐ zhǐhǎo lái zhǎo nín.)', 7) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr25_vi_exp_4', 'lesson-25', 'vi_to_zh', 'Sao em lại nghĩ như vậy?', NULL, NULL, '你为什么这么想？', NULL, 'nǐ wèishénme zhème xiǎng', '[]'::jsonb, 'Gợi ý Pinyin: Nǐ wèishénme zhème xiǎng?', 'Sao em lại nghĩ như vậy? → 你为什么这么想？ (Nǐ wèishénme zhème xiǎng?)', 8) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr25_vi_exp_5', 'lesson-25', 'vi_to_zh', 'Khi nói chuyện với bạn bè Trung Quốc, em thấy họ nói gì em cũng hiểu, vì các bạn nói chậm và chọn từ ngữ khá đơn giản. Nhưng nếu hỏi đường ngẫu nhiên một người ngoài phố, họ nói rất nhanh lại dùng nhiều từ em không biết nên em nghe không rõ.', NULL, NULL, '跟中国朋友说话的时候，我觉得他们说什么我都能听懂，因为朋友们说得很慢，还选择比较简单的词语。但是如果在路边随便找一个人问路，他们说得很快，还用很多我不知道的词语，我听不清楚。', NULL, 'gēn zhōngguó péngyou shuōhuà de shíhou wǒ juéde tāmen shuō shénme wǒ dōu néng tīng dǒng yīnwèi péngyoumen shuō de hěn màn hái xuǎnzé bǐ jiào jiǎndān de cíyǔ dànshì rúguǒ zài lù biān suíbiàn zhǎo yígè rén wèn lù tāmen shuō de hěn kuài hái yòng hěnduō wǒ bù zhīdao de cíyǔ wǒ tīng bu qīngchu', '[]'::jsonb, 'Gợi ý Pinyin: Gēn Zhōngguó péngyou shuōhuà de shíhou, wǒ juéde tāmen shuō shénme wǒ dōu néng tīng dǒng, yīnwèi péngyoumen shuō de hěn màn, hái xuǎnzé bǐ jiào jiǎndān de cíyǔ. Dànshì rúguǒ zài lù biān suíbiàn zhǎo yígè rén wèn lù, tāmen shuō de hěn kuài, hái yòng hěnduō wǒ bù zhīdao de cíyǔ, wǒ tīng bu qīngchu.', 'Khi nói chuyện với bạn bè Trung Quốc, em thấy họ nói gì em cũng hiểu, vì các bạn nói chậm và chọn từ ngữ khá đơn giản. Nhưng nếu hỏi đường ngẫu nhiên một người ngoài phố, họ nói rất nhanh lại dùng nhiều từ em không biết nên em nghe không rõ. → 跟中国朋友说话的时候，我觉得他们说什么我都能听懂，因为朋友们说得很慢，还选择比较简单的词语。但是如果在路边随便找一个人问路，他们说得很快，还用很多我不知道的词语，我听不清楚。 (Gēn Zhōngguó péngyou shuōhuà de shíhou, wǒ juéde tāmen shuō shénme wǒ dōu néng tīng dǒng, yīnwèi péngyoumen shuō de hěn màn, hái xuǎnzé bǐ jiào jiǎndān de cíyǔ. Dànshì rúguǒ zài lù biān suíbiàn zhǎo yígè rén wèn lù, tāmen shuō de hěn kuài, hái yòng hěnduō wǒ bù zhīdao de cíyǔ, wǒ tīng bu qīngchu.)', 9) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr25_vi_exp_6', 'lesson-25', 'vi_to_zh', 'Đây là khó khăn thường gặp của du học sinh. Em nên ra ngoài đi dạo nhiều hơn, ví dụ buổi tối ra bờ hồ hoặc công viên tản bộ rồi trò chuyện với mọi người ở đó. Nếu nghe chưa rõ thì có thể nhờ họ nói lại lần nữa. Dần dần vấn đề giao tiếp của em sẽ hết thôi.', NULL, NULL, '这是留学生常遇到的困难。你应该多去外面走走，比如晚上你可以到湖边或者公园散步，然后跟那里的人说话。如果你听不清楚的话，也可以让他们再说一遍。慢慢的你的沟通问题就没有了。', NULL, 'zhè shì liúxuéshēng cháng yùdào de kùnnan nǐ yīnggāi duō qù wàimian zǒuzou bǐrú wǎnshàng nǐ kěyǐ dào hú biān huòzhě gōngyuán sànbù ránhòu gēn', '[]'::jsonb, 'Gợi ý Pinyin: Zhè shì liúxuéshēng cháng yùdào de kùnnan. Nǐ yīnggāi duō qù wàimian zǒuzou, bǐrú wǎnshàng nǐ kěyǐ dào hú biān huòzhě gōngyuán sànbù, ránhòu gēn', 'Đây là khó khăn thường gặp của du học sinh. Em nên ra ngoài đi dạo nhiều hơn, ví dụ buổi tối ra bờ hồ hoặc công viên tản bộ rồi trò chuyện với mọi người ở đó. Nếu nghe chưa rõ thì có thể nhờ họ nói lại lần nữa. Dần dần vấn đề giao tiếp của em sẽ hết thôi. → 这是留学生常遇到的困难。你应该多去外面走走，比如晚上你可以到湖边或者公园散步，然后跟那里的人说话。如果你听不清楚的话，也可以让他们再说一遍。慢慢的你的沟通问题就没有了。 (Zhè shì liúxuéshēng cháng yùdào de kùnnan. Nǐ yīnggāi duō qù wàimian zǒuzou, bǐrú wǎnshàng nǐ kěyǐ dào hú biān huòzhě gōngyuán sànbù, ránhòu gēn)', 10) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr25_vi_exp_7', 'lesson-25', 'vi_to_zh', 'Nhưng làm như vậy có thể sẽ làm phiền họ ạ.', NULL, NULL, '但是这样做可能会打扰他们。', NULL, 'dànshì zhèyàng zuò kěnéng huì dǎrǎo tāmen', '[]'::jsonb, 'Gợi ý Pinyin: Dànshì zhèyàng zuò kěnéng huì dǎrǎo tāmen.', 'Nhưng làm như vậy có thể sẽ làm phiền họ ạ. → 但是这样做可能会打扰他们。 (Dànshì zhèyàng zuò kěnéng huì dǎrǎo tāmen.)', 11) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr25_vi_exp_8', 'lesson-25', 'vi_to_zh', 'Không đâu. Người Trung Quốc rất nhiệt tình, họ nhất định sẽ giúp em. Nhưng em cần chú ý một điều là đừng sợ nói sai. Em là du học sinh, nói sai cũng không ai cười em đâu.', NULL, NULL, '不会的。中国人很热情，他们一定会帮你。可是你要注意一点，就是不要害怕说错。你是留学生，你说错也没有人笑你。', NULL, 'bú huì de zhōngguó rén hěn rèqíng tāmen yídìng huì bāng nǐ kěshì nǐ yào zhùyì yīdiǎn jiùshì búyào hàipà shuō cuò nǐ shì liúxuéshēng nǐ shuō cuò yě méiyǒu rén xiào nǐ', '[]'::jsonb, 'Gợi ý Pinyin: Bú huì de. Zhōngguó rén hěn rèqíng, tāmen yídìng huì bāng nǐ. Kěshì nǐ yào zhùyì yīdiǎn, jiùshì búyào hàipà shuō cuò. Nǐ shì liúxuéshēng, nǐ shuō cuò yě méiyǒu rén xiào nǐ.', 'Không đâu. Người Trung Quốc rất nhiệt tình, họ nhất định sẽ giúp em. Nhưng em cần chú ý một điều là đừng sợ nói sai. Em là du học sinh, nói sai cũng không ai cười em đâu. → 不会的。中国人很热情，他们一定会帮你。可是你要注意一点，就是不要害怕说错。你是留学生，你说错也没有人笑你。 (Bú huì de. Zhōngguó rén hěn rèqíng, tāmen yídìng huì bāng nǐ. Kěshì nǐ yào zhùyì yīdiǎn, jiùshì búyào hàipà shuō cuò. Nǐ shì liúxuéshēng, nǐ shuō cuò yě méiyǒu rén xiào nǐ.)', 12) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr25_vi_exp_9', 'lesson-25', 'vi_to_zh', 'Vâng, em hiểu rồi ạ.', NULL, NULL, '老师，我知道了。', NULL, 'lǎoshī wǒ zhīdao le', '[]'::jsonb, 'Gợi ý Pinyin: Lǎoshī, wǒ zhīdao le.', 'Vâng, em hiểu rồi ạ. → 老师，我知道了。 (Lǎoshī, wǒ zhīdao le.)', 13) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr25_vi_exp_10', 'lesson-25', 'vi_to_zh', 'Em đừng nóng vội, chúng ta cứ học từ từ. Thực ra bây giờ tiếng Hán của em nói cũng rất trôi chảy rồi đấy.', NULL, NULL, '你不要着急，我们慢慢学。其实现在你汉语说得很流利了。', NULL, 'nǐ búyào zháojí wǒmen mànmàn xué qíshí xiànzài nǐ hànyǔ shuō de hěn liúlì le', '[]'::jsonb, 'Gợi ý Pinyin: Nǐ búyào zháojí, wǒmen mànmàn xué. Qíshí xiànzài nǐ Hànyǔ shuō de hěn liúlì le.', 'Em đừng nóng vội, chúng ta cứ học từ từ. Thực ra bây giờ tiếng Hán của em nói cũng rất trôi chảy rồi đấy. → 你不要着急，我们慢慢学。其实现在你汉语说得很流利了。 (Nǐ búyào zháojí, wǒmen mànmàn xué. Qíshí xiànzài nǐ Hànyǔ shuō de hěn liúlì le.)', 14) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr25_zh_1', 'lesson-25', 'zh_to_vi', '[Mở rộng] 不要害怕说错，没有 (méiyǒu: không có)人会笑你的。', '不要害怕说错，没有人会笑你的。', 'Búyào hàipà shuō cuò, méiyǒu rén huì xiào nǐ de.', NULL, 'Đừng sợ nói sai, sẽ không có ai cười bạn đâu.', NULL, '["Đừng","sợ","nói"]'::jsonb, 'Pinyin: Búyào hàipà shuō cuò, méiyǒu rén huì xiào nǐ de.', '不要害怕说错，没有人会笑你的。 (Búyào hàipà shuō cuò, méiyǒu rén huì xiào nǐ de.) nghĩa là: Đừng sợ nói sai, sẽ không có ai cười bạn đâu.', 15) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr25_zh_2', 'lesson-25', 'zh_to_vi', '[Mở rộng] 晚上在湖边散步时 (shí: lúc, khi)，我发现很多人都在练习说话 (huà: lời nói)。', '晚上在湖边散步时，我发现很多人都在练习说话。', 'Wǎnshang zài húbiān sànbù shí, wǒ fāxiàn hěnduō rén dōu zài liànxí shuōhuà.', NULL, 'Buổi tối đi dạo bên bờ hồ, tôi phát hiện rất nhiều người đang luyện nói chuyện.', NULL, '["Buổi","tối","đi"]'::jsonb, 'Pinyin: Wǎnshang zài húbiān sànbù shí, wǒ fāxiàn hěnduō rén dōu zài liànxí shuōhuà.', '晚上在湖边散步时，我发现很多人都在练习说话。 (Wǎnshang zài húbiān sànbù shí, wǒ fāxiàn hěnduō rén dōu zài liànxí shuōhuà.) nghĩa là: Buổi tối đi dạo bên bờ hồ, tôi phát hiện rất nhiều người đang luyện nói chuyện.', 16) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr25_zh_3', 'lesson-25', 'zh_to_vi', '他说汉语说得不好。', '他说汉语说得不好。', 'Tā shuō Hànyǔ shuō de bù hǎo.', NULL, 'Anh ấy nói tiếng Trung không tốt.', NULL, '["Anh","ấy","nói"]'::jsonb, 'Pinyin: Tā shuō Hànyǔ shuō de bù hǎo.', '他说汉语说得不好。 (Tā shuō Hànyǔ shuō de bù hǎo.) nghĩa là: Anh ấy nói tiếng Trung không tốt.', 17) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr25_zh_4', 'lesson-25', 'zh_to_vi', '[Ôn tập Bài 12] 他这个人真好！', '他这个人真好！', 'Tā zhège rén zhēn hǎo!', NULL, 'Con người anh ta thật là tốt!', NULL, '["Con","người","anh"]'::jsonb, 'Pinyin: Tā zhège rén zhēn hǎo!', '他这个人真好！ (Tā zhège rén zhēn hǎo!) nghĩa là: Con người anh ta thật là tốt!', 18) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr25_zh_exp_1', 'lesson-25', 'zh_to_vi', '下雨了，我没带伞，只好在学校等着。', '下雨了，我没带伞，只好在学校等着。', 'Xià yǔle, wǒ méi dài sǎn, zhǐhǎo zài xuéxiào děngzhe.', NULL, 'Trời mưa rồi mà tôi không mang ô, chỉ đành đợi ở trường.', NULL, '["trời","mưa","rồi","mà","tôi","không","mang","chỉ","đành","đợi","trường"]'::jsonb, 'Pinyin: Xià yǔle, wǒ méi dài sǎn, zhǐhǎo zài xuéxiào děngzhe.', '下雨了，我没带伞，只好在学校等着。 (Xià yǔle, wǒ méi dài sǎn, zhǐhǎo zài xuéxiào děngzhe.) nghĩa là: Trời mưa rồi mà tôi không mang ô, chỉ đành đợi ở trường.', 19) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr25_zh_exp_2', 'lesson-25', 'zh_to_vi', '他歌唱得不太好听。', '他歌唱得不太好听。', 'Tā gē chàng de bù tài hǎotīng.', NULL, 'Anh ấy hát không hay lắm.', NULL, '["anh","ấy","hát","không","hay","lắm"]'::jsonb, 'Pinyin: Tā gē chàng de bù tài hǎotīng.', '他歌唱得不太好听。 (Tā gē chàng de bù tài hǎotīng.) nghĩa là: Anh ấy hát không hay lắm.', 20) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
