INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr25_zh_exp_7', 'lesson-25', 'zh_to_vi', '只要礼貌沟通，大家不仅不会笑你，还会帮你快速进步！', '只要礼貌沟通，大家不仅不会笑你，还会帮你快速进步！', 'Zhǐyào lǐmào gōutōng, dàjiā bùjǐn bú huì xiào nǐ, hái huì bāng nǐ kuàisù jìnbù!', NULL, 'Chỉ cần giao tiếp lịch sự, mọi người chẳng những không cười em mà còn giúp em tiến bộ nhanh đấy!', NULL, '["chỉ","cần","giao","tiếp","lịch","sự","mọi","người","chẳng","những","không","cười","em","mà","còn","giúp","em","tiến","bộ","nhanh","đấy"]'::jsonb, 'Pinyin: Zhǐyào lǐmào gōutōng, dàjiā bùjǐn bú huì xiào nǐ, hái huì bāng nǐ kuàisù jìnbù!', '只要礼貌沟通，大家不仅不会笑你，还会帮你快速进步！ (Zhǐyào lǐmào gōutōng, dàjiā bùjǐn bú huì xiào nǐ, hái huì bāng nǐ kuàisù jìnbù!) nghĩa là: Chỉ cần giao tiếp lịch sự, mọi người chẳng những không cười em mà còn giúp em tiến bộ nhanh đấy!', 25) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr25_zh_exp_8', 'lesson-25', 'zh_to_vi', '我可以晚上去湖边找大家聊天儿吗？怕打扰他们。', '我可以晚上去湖边找大家聊天儿吗？怕打扰他们。', 'Wǒ kěyǐ wǎnshang qù húbiān zhǎo dàjiā liáotiānr ma? Pà dǎrǎo tāmen.', NULL, 'Buổi tối em có thể ra bờ hồ bắt chuyện với mọi người không? Em sợ làm phiền họ ạ.', NULL, '["buổi","tối","em","có","thể","ra","bờ","hồ","bắt","chuyện","với","mọi","người","không","em","sợ","làm","phiền","họ"]'::jsonb, 'Pinyin: Wǒ kěyǐ wǎnshang qù húbiān zhǎo dàjiā liáotiānr ma? Pà dǎrǎo tāmen.', '我可以晚上去湖边找大家聊天儿吗？怕打扰他们。 (Wǒ kěyǐ wǎnshang qù húbiān zhǎo dàjiā liáotiānr ma? Pà dǎrǎo tāmen.) nghĩa là: Buổi tối em có thể ra bờ hồ bắt chuyện với mọi người không? Em sợ làm phiền họ ạ.', 26) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr25_zh_exp_9', 'lesson-25', 'zh_to_vi', '别怕！你应该先从简单的词语开始，慢慢就能说清楚。', '别怕！你应该先从简单的词语开始，慢慢就能说清楚。', 'Bié pà! Nǐ yīnggāi xiān cóng jiǎndān de cíyǔ kāishǐ, mànmàn jiù néng shuō qīngchu.', NULL, 'Đừng sợ! Em nên bắt đầu từ những từ ngữ đơn giản trước, dần dần sẽ nói rõ ràng thôi.', NULL, '["đừng","sợ","em","nên","bắt","đầu","từ","những","từ","ngữ","đơn","giản","trước","dần","dần","sẽ","nói","rõ","ràng","thôi"]'::jsonb, 'Pinyin: Bié pà! Nǐ yīnggāi xiān cóng jiǎndān de cíyǔ kāishǐ, mànmàn jiù néng shuō qīngchu.', '别怕！你应该先从简单的词语开始，慢慢就能说清楚。 (Bié pà! Nǐ yīnggāi xiān cóng jiǎndān de cíyǔ kāishǐ, mànmàn jiù néng shuō qīngchu.) nghĩa là: Đừng sợ! Em nên bắt đầu từ những từ ngữ đơn giản trước, dần dần sẽ nói rõ ràng thôi.', 27) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
