INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq25_11', 'lesson-25', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, 'Phiên âm Pinyin chính xác của “随便” là gì?', '["suíbiàn","gèng","wèile","xiào"]'::jsonb, 0, '“随便” đọc là: suíbiàn (tùy tiện, tùy ý).', 11) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq25_12', 'lesson-25', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, 'Phiên âm Pinyin chính xác của “更” là gì?', '["xuǎnzé","gèng","zháojí","zhǎo"]'::jsonb, 1, '“更” đọc là: gèng (càng).', 12) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq25_13', 'lesson-25', NULL, 'expanded_quiz', 'radical', NULL, NULL, 'Chữ Hán “湖边” chứa bộ thủ nào sau đây?', '["糸/纟 (Mịch) (Sợi tơ, gắn kết, màu sắc)","青 (Thanh) (Màu xanh, tươi trẻ)","水/氵 (Thủy) (Nước, chất lỏng, sông ngòi)","凵 (Khảm) (Há miệng, hố trũng)"]'::jsonb, 2, 'Chữ “湖边” có bộ chính 水/氵 (Thủy) (Nước, chất lỏng, sông ngòi). Chiết tự: 湖: 氵 (Thủy: mặt nước hồ) + 胡 (Hồ) • 边: 力 (Lực) + 辶 (Sước: đi ven mép)', 13) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq25_14', 'lesson-25', NULL, 'expanded_quiz', 'radical', NULL, NULL, 'Chữ Hán “词语” chứa bộ thủ nào sau đây?', '["毋/母 (Vô/Mẫu) (Mẹ, nuôi dưỡng, ngăn cấm)","羽 (Vũ) (Lông chim, đôi cánh)","革 (Cách) (Da thú, thay đổi)","言/讠 (Ngôn) (Lời nói, ngôn ngữ, giao tiếp)"]'::jsonb, 3, 'Chữ “词语” có bộ chính 言/讠 (Ngôn) (Lời nói, ngôn ngữ, giao tiếp). Chiết tự: 词: 讠 (Ngôn: ngôn từ) + 司 (Tư) • 语: 讠 (Ngôn: lời nói) + 吾 (Ngô)', 14) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq25_15', 'lesson-25', NULL, 'expanded_quiz', 'radical', NULL, NULL, 'Chữ Hán “进步” chứa bộ thủ nào sau đây?', '["香 (Hương) (Mùi thơm, hương vị)","厶 (Tư) (Riêng tư, cuộn tròn)","斗 (Đẩu) (Cái đấu đong lường, chiến đấu)","辶 (Sước) (Bước đi, di chuyển, khoảng cách)"]'::jsonb, 3, 'Chữ “进步” có bộ chính 辶 (Sước) (Bước đi, di chuyển, khoảng cách). Chiết tự: 进: 井 (Tỉnh) + 辶 (Sước: bước tiến vào) • 步: 止 (Chỉ: bước chân trên) + 少 biến thể (bước chân dưới)', 15) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq25_16', 'lesson-25', NULL, 'expanded_quiz', 'radical', NULL, NULL, 'Chữ Hán “沟通” chứa bộ thủ nào sau đây?', '["儿 (Nhi) (Trẻ nhỏ, phần chân nâng đỡ)","巾 (Cân) (Khăn vải, mũ nón, vải vóc)","水/氵 (Thủy) (Nước, chất lỏng, sông ngòi)","犬/犭 (Khuyển) (Con chó, loài thú)"]'::jsonb, 2, 'Chữ “沟通” có bộ chính 水/氵 (Thủy) (Nước, chất lỏng, sông ngòi). Chiết tự: 沟: 氵 (Thủy: rãnh nước) + 勾 (Câu) • 通: 甬 (Dũng) + 辶 (Sước: đi thông suốt)', 16) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq25_17', 'lesson-25', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, '[Ôn tập Bài 2] Từ đã học “见” (jiàn) có nghĩa là gì?', '["nghỉ ngơi","cai, bỏ, chừa","nhìn thấy, gặp","bờ hồ"]'::jsonb, 2, 'Ôn tập Bài 2: “见” (jiàn) nghĩa là: nhìn thấy, gặp.', 17) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq25_18', 'lesson-25', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, '[Ôn tập Bài 6] Từ đã học “就” (jiù) có nghĩa là gì?', '["là (dùng sau từ chỉ thời gian, số lượng từ, biểu thị thời gian sớm, số lượng ít, nhỏ tuổi, cuối câu thường dùng 了).","vị, mùi vị, mùi","năm sau","tin tức"]'::jsonb, 0, 'Ôn tập Bài 6: “就” (jiù) nghĩa là: là (dùng sau từ chỉ thời gian, số lượng từ, biểu thị thời gian sớm, số lượng ít, nhỏ tuổi, cuối câu thường dùng 了)..', 18) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq25_19', 'lesson-25', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, '[Ôn tập Bài 8] Từ đã học “块” (kuài) có nghĩa là gì?', '["đồng (đơn vị tiền)","hiểu","ôn bài","như vậy, như thế đấy"]'::jsonb, 0, 'Ôn tập Bài 8: “块” (kuài) nghĩa là: đồng (đơn vị tiền).', 19) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq25_20', 'lesson-25', NULL, 'expanded_quiz', 'reading', NULL, NULL, '[Mở rộng] Câu “不好意思，现在打扰您五分钟可以吗？” có nghĩa tiếng Việt là gì?', '["Cô ấy đã ăn 3 cái sủi cảo.","Xin lỗi, bây giờ làm phiền thầy năm phút có được không ạ?","Tôi mệt đến mức chẳng muốn động đậy gì nữa.","Tôi nhất định phải học tốt tiếng Trung, nếu không tôi sẽ không về nước."]'::jsonb, 1, '不好意思，现在打扰您五分钟可以吗？ (Bù hǎoyìsi, xiànzài dǎrǎo nín wǔ fēnzhōng kěyǐ ma?) → Xin lỗi, bây giờ làm phiền thầy năm phút có được không ạ?', 20) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq25_21', 'lesson-25', NULL, 'expanded_quiz', 'reading', NULL, NULL, '[Đọc hiểu mở rộng] Đọc đoạn hội thoại:
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq25_22', 'lesson-25', NULL, 'expanded_quiz', 'reading', NULL, NULL, 'Câu “他说汉语说得很好。” có nghĩa tiếng Việt là gì?', '["Anh ấy nói tiếng Trung rất tốt.","Bệnh của tôi vẫn chưa khỏi.","Tôi đi một lát thì quay lại ngay.","Nếu cậu ấy tham gia cuộc thi lần này thì tôi sẽ tham gia."]'::jsonb, 0, '他说汉语说得很好。 (Tā shuō Hànyǔ shuō de hěn hǎo.) → Anh ấy nói tiếng Trung rất tốt.', 22) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct25_1', 'lesson-25', NULL, 'comprehensive_test', 'listening', '他的普通话说得又流利又标准', NULL, 'Nghe đoạn ghi âm và chọn nghĩa tiếng Việt đúng:', '["Thử qua một chút.","Tiếng phổ thông của anh ấy nói vừa trôi chảy vừa chuẩn.","Vậy cậu thích ăn vị gì?","Hoa quả ở đây bán thế nào vậy ạ?"]'::jsonb, 1, 'Nội dung nghe được: “他的普通话说得又流利又标准” (Tā de Pǔtōnghuà shuō de yòu liúlì yòu biāozhǔn.) → Tiếng phổ thông của anh ấy nói vừa trôi chảy vừa chuẩn.', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct25_2', 'lesson-25', NULL, 'comprehensive_test', 'listening', '老师，我知道了。', NULL, 'Nghe đoạn ghi âm và chọn câu tiếng Trung khớp với nội dung vừa nghe:', '["等我一下儿，这是我家的照片，给你看。","那个人是王老师。","老师，我知道了。","对。每天下午我都去体育馆游泳，打篮球、打网球和武术。周末如果天气好我就跟几个朋友去爬山。我觉得你的身体太弱，可能是因为不经常锻炼身体。"]'::jsonb, 2, 'Câu vừa đọc: “老师，我知道了。” (Lǎoshī, wǒ zhīdao le.) → Vâng, em hiểu rồi ạ.', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct25_3', 'lesson-25', NULL, 'comprehensive_test', 'listening', '但是这样做可能会打扰他们。', NULL, 'Nghe đoạn ghi âm và chọn nghĩa tiếng Việt đúng:', '["Nhưng làm như vậy có thể sẽ làm phiền họ ạ.","Còn mùa thu thì sao?","Cô ấy tên là gì?","Rất vui được làm quen với bạn! Bạn đến từ Canada à?"]'::jsonb, 0, 'Nội dung nghe được: “但是这样做可能会打扰他们。” (Dànshì zhèyàng zuò kěnéng huì dǎrǎo tāmen.) → Nhưng làm như vậy có thể sẽ làm phiền họ ạ.', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct25_4', 'lesson-25', NULL, 'comprehensive_test', 'listening', '这个问题我不知道，只好去问妈妈。', NULL, 'Nghe đoạn ghi âm và chọn câu tiếng Trung khớp với nội dung vừa nghe:', '["他可能同意了吧？","下星期六是我妹妹的生日","这个问题我不知道，只好去问妈妈。","我差点儿忘了，星期六也是我的一个朋友的生日。那你买你的吧，我现在去书店给他买一本汉语书，明天再跟你说吧！"]'::jsonb, 2, 'Câu vừa đọc: “这个问题我不知道，只好去问妈妈。” (Zhège wèntí wǒ bù zhīdào, zhǐhǎo qù wèn māma.) → Vấn đề này tôi không biết nên chỉ đành đi hỏi mẹ.', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct25_5', 'lesson-25', NULL, 'comprehensive_test', 'listening', '谢谢您！', NULL, 'Nghe đoạn ghi âm và chọn nghĩa tiếng Việt đúng:', '["Vậy cậu có dám ăn đậu phụ thối hay các món thật cay không?","Em cảm ơn thầy/cô ạ!","Ghen tị với bạn quá đi! Kỳ nghỉ hè năm nay tôi cũng sẽ đi du lịch Bắc Kinh.","Các bạn học sinh"]'::jsonb, 1, 'Nội dung nghe được: “谢谢您！” (Xièxie nín!) → Em cảm ơn thầy/cô ạ!', 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct25_6', 'lesson-25', NULL, 'comprehensive_test', 'listening', '他吃得不太饱。', NULL, 'Nghe đoạn ghi âm và chọn câu tiếng Trung khớp với nội dung vừa nghe:', '["老师您好！","他吃得不太饱。","我家有很多人，每个人的爱好都不一样。","你每天几点起床去学武术"]'::jsonb, 1, 'Câu vừa đọc: “他吃得不太饱。” (Tā chī de bú tài bǎo.) → Anh ấy ăn không no lắm.', 6) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct25_7', 'lesson-25', NULL, 'comprehensive_test', 'listening', '你为什么这么想？', NULL, 'Nghe đoạn ghi âm và chọn nghĩa tiếng Việt đúng:', '["Cậu nói gì?","Hôm qua trời có tuyết rơi, lạnh lắm, nên hình như tớ bị cảm rồi.","Sao em lại nghĩ như vậy?","Tớ rất đau đầu, không thể đi học được."]'::jsonb, 2, 'Nội dung nghe được: “你为什么这么想？” (Nǐ wèishénme zhème xiǎng?) → Sao em lại nghĩ như vậy?', 7) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
