INSERT INTO lessons (id, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id) VALUES ('lesson-26', 'Bài 26: Sau khi tốt nghiệp - Đơn nguyên 7: Du học Trung Quốc', 'Bài 26', 'Đơn nguyên 7: Du học Trung Quốc', 'Định hướng tương lai: học lên thạc sĩ, đi làm phiên dịch, giảng dạy, tuyển dụng và tổng kết khóa học.', '2026-11-14'::date, 26, TRUE, NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, date_added = EXCLUDED.date_added, sort_order = EXCLUDED.sort_order, is_system = TRUE, updated_at = NOW();
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v26_1', 'lesson-26', '专业', 'zhuānyè', 'nghiệp', 'chuyên ngành, chuyên nghiệp', 'Danh từ / Tính từ', '一 (Nhất) (Số một, nền tảng, nét ngang cơ bản)', '专: 二 + 乚 + 丶 (chuyên tâm một việc) • 业: 业 (hai cặp nhánh đứng trên vạch ngang: công việc, sự nghiệp)', 'Ghép 专 [bộ 一] + 业 [bộ 一] để nhớ từ 专业 (zhuānyè): "chuyên ngành, chuyên nghiệp".', '因为我的专业是汉语教育，所以回国后我想当一位老师。我想帮助越南学生学习汉语，让他们更了解中国文化，更喜欢中国。那你呢？你有什么打算？', 'Yīnwèi wǒ de zhuānyè shì Hànyǔ jiàoyù, suǒyǐ huíguó hòu wǒ xiǎng dāng yí wèi lǎoshī. Wǒ xiǎng bāngzhù Yuènán xuésheng xuéxí Hànyǔ, ràng tāmen gèng liǎojiě Zhōngguó wénhuà, gèng xǐhuan Zhōngguó. Nà nǐ ne? Nǐ yǒu shén me dǎsuan?', 'Vì chuyên ngành của tôi là Giáo dục Hán ngữ, nên sau khi về nước tôi muốn làm giáo viên. Tôi muốn giúp học sinh Việt Nam học tiếng Hán, giúp các em hiểu hơn về văn hóa Trung Quốc và yêu thích Trung Quốc hơn. Còn cậu thì sao? Cậu có dự định gì?', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v26_2', 'lesson-26', '硕士', 'shuòshì', 'từ Hán ngữ', 'thạc sĩ', 'Danh từ', '石 (Thạch) (Hòn đá, vật cứng)', '硕: 石 (Thạch: đá lớn) + 页 (Hiệt: to lớn, thạc sĩ) • 士: Bộ 士 (Sĩ - nét trên dài hơn nét dưới, người có học)', 'Ghép 硕 [bộ 石] + 士 [bộ 士] để nhớ từ 硕士 (shuòshì): "thạc sĩ".', '你想学硕士吗？', 'Nǐ xiǎng xué shuòshì ma?', 'Cậu muốn học thạc sĩ à?', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v26_3', 'lesson-26', '理想', 'lǐxiǎng', 'tưởng', 'lý tưởng', 'Danh từ', '玉/王 (Ngọc) (Đá quý, vua chúa)', '理: 王 (Ngọc: mài giũa đường vân ngọc) + 里 (Lý: đạo lý) • 想: 相 (Tương: hình ảnh) + 心 (Tâm: lòng suy nghĩ)', 'Ghép 理 [bộ 王] + 想 [bộ 心] để nhớ từ 理想 (lǐxiǎng): "lý tưởng".', '你的理想工作是什么？', 'Nǐ de lǐxiǎng gōngzuò shì shénme?', 'Công việc lý tưởng của cậu là gì?', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v26_4', 'lesson-26', '梦想', 'mèngxiǎng', 'tưởng', 'khát vọng, ước mơ', 'Danh từ', '夕 (Tịch) (Buổi chiều tối, đêm tối)', '梦: 林 (Lâm: rừng tối) + 夕 (Tịch: buổi đêm nằm mơ) • 想: 相 (Tương: hình ảnh) + 心 (Tâm: lòng suy nghĩ)', 'Ghép 梦 [bộ 夕] + 想 [bộ 心] để nhớ từ 梦想 (mèngxiǎng): "khát vọng, ước mơ".', '翻译。这是我从小的梦想。现在我正在一家企业实习。虽然工作有点儿累，但是在这里我学会了很多技能和经验。', 'Fānyì. Zhè shì wǒ cóngxiǎo de mèngxiǎng. Xiànzài wǒ zhèng zài yījiā qǐyè shíxí. Suīrán gōngzuò yǒudiǎnr lèi dànshì zài zhèlǐ wǒ xué huì le hěn duō jìnéng hé jīngyàn.', 'Phiên dịch viên. Đây là ước mơ từ nhỏ của tôi. Hiện tôi đang thực tập tại một doanh nghiệp. Tuy công việc hơi vất vả nhưng ở đây tôi học được rất nhiều kỹ năng và kinh nghiệm.', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v26_5', 'lesson-26', '工作', 'gōngzuò', 'công tác', 'nghề nghiệp, công việc', 'Danh từ / Động từ', '工 (Công) (Công việc, kỹ thuật, thợ thủ công)', '工: Bộ 工 (Công - dụng cụ thợ, công việc) • 作: 亻 (Nhân đứng: người) + 乍 (Sạ: làm việc)', 'Ghép 工 [bộ 工] + 作 [bộ 亻] để nhớ từ 工作 (gōngzuò): "nghề nghiệp, công việc".', '学两年。然后我会回国找工作。', 'Xué liǎng nián. Ránhòu wǒ huì huíguó zhǎo gōngzuò.', 'Học hai năm. Sau đó tôi sẽ về nước tìm việc.', 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v26_6', 'lesson-26', '翻译', 'fānyì', 'từ Hán ngữ', 'dịch, phiên dịch', 'Danh từ / Động từ', '羽 (Vũ) (Lông chim, đôi cánh)', '翻: 番 (Phiên: lật qua) + 羽 (Vũ: đôi cánh bay lật) • 译: 讠 (Ngôn: ngôn ngữ) + 𠬤 (dịch chuyển nghĩa)', 'Ghép 翻 [bộ 羽] + 译 [bộ 讠] để nhớ từ 翻译 (fānyì): "dịch, phiên dịch".', '翻译。这是我从小的梦想。现在我正在一家企业实习。虽然工作有点儿累，但是在这里我学会了很多技能和经验。', 'Fānyì. Zhè shì wǒ cóngxiǎo de mèngxiǎng. Xiànzài wǒ zhèng zài yījiā qǐyè shíxí. Suīrán gōngzuò yǒudiǎnr lèi dànshì zài zhèlǐ wǒ xué huì le hěn duō jìnéng hé jīngyàn.', 'Phiên dịch viên. Đây là ước mơ từ nhỏ của tôi. Hiện tôi đang thực tập tại một doanh nghiệp. Tuy công việc hơi vất vả nhưng ở đây tôi học được rất nhiều kỹ năng và kinh nghiệm.', 6) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v26_7', 'lesson-26', '教育', 'jiàoyù', 'giáo', 'giáo dục, đào tạo', 'Danh từ / Động từ', '攴/攵 (Phộc) (Đánh khẽ, hành động, dạy dỗ)', '教: 孝 (Hiếu) + 攵 (Phộc: thầy cầm roi dạy bảo) • 育: 亠 + 厶 + 月 (Nhục: nuôi dưỡng con lớn lên)', 'Ghép 教 [bộ 攵] + 育 [bộ 月] để nhớ từ 教育 (jiàoyù): "giáo dục, đào tạo".', '因为我的专业是汉语教育，所以回国后我想当一位老师。我想帮助越南学生学习汉语，让他们更了解中国文化，更喜欢中国。那你呢？你有什么打算？', 'Yīnwèi wǒ de zhuānyè shì Hànyǔ jiàoyù, suǒyǐ huíguó hòu wǒ xiǎng dāng yí wèi lǎoshī. Wǒ xiǎng bāngzhù Yuènán xuésheng xuéxí Hànyǔ, ràng tāmen gèng liǎojiě Zhōngguó wénhuà, gèng xǐhuan Zhōngguó. Nà nǐ ne? Nǐ yǒu shén me dǎsuan?', 'Vì chuyên ngành của tôi là Giáo dục Hán ngữ, nên sau khi về nước tôi muốn làm giáo viên. Tôi muốn giúp học sinh Việt Nam học tiếng Hán, giúp các em hiểu hơn về văn hóa Trung Quốc và yêu thích Trung Quốc hơn. Còn cậu thì sao? Cậu có dự định gì?', 7) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v26_8', 'lesson-26', '技能', 'jìnéng', 'từ Hán ngữ', 'kỹ năng, năng lực (chuyên môn)', 'Danh từ', '手/扌 (Thủ) (Bàn tay, động tác, thao tác)', '技: 扌 (Thủ: bàn tay khéo) + 支 (Chi: kỹ năng) • 能: 厶 + 月 (Nhục) + 匕 + 匕 (gấu mạnh mẽ có khả năng)', 'Ghép 技 [bộ 扌] + 能 [bộ 月] để nhớ từ 技能 (jìnéng): "kỹ năng, năng lực (chuyên môn)".', '翻译。这是我从小的梦想。现在我正在一家企业实习。虽然工作有点儿累，但是在这里我学会了很多技能和经验。', 'Fānyì. Zhè shì wǒ cóngxiǎo de mèngxiǎng. Xiànzài wǒ zhèng zài yījiā qǐyè shíxí. Suīrán gōngzuò yǒudiǎnr lèi dànshì zài zhèlǐ wǒ xué huì le hěn duō jìnéng hé jīngyàn.', 'Phiên dịch viên. Đây là ước mơ từ nhỏ của tôi. Hiện tôi đang thực tập tại một doanh nghiệp. Tuy công việc hơi vất vả nhưng ở đây tôi học được rất nhiều kỹ năng và kinh nghiệm.', 8) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v26_9', 'lesson-26', '经验', 'jīngyàn', 'từ Hán ngữ', 'kinh nghiệm', 'Danh từ', '糸/纟 (Mịch) (Sợi tơ, gắn kết, màu sắc)', '经: 纟 (Mịch: sợi dọc khung cửi) + 圣 • 验: 马 (Mã: xem xét ngựa) + 佥 (Thiêm: kiểm nghiệm)', 'Ghép 经 [bộ 纟] + 验 [bộ 马] để nhớ từ 经验 (jīngyàn): "kinh nghiệm".', '翻译。这是我从小的梦想。现在我正在一家企业实习。虽然工作有点儿累，但是在这里我学会了很多技能和经验。', 'Fānyì. Zhè shì wǒ cóngxiǎo de mèngxiǎng. Xiànzài wǒ zhèng zài yījiā qǐyè shíxí. Suīrán gōngzuò yǒudiǎnr lèi dànshì zài zhèlǐ wǒ xué huì le hěn duō jìnéng hé jīngyàn.', 'Phiên dịch viên. Đây là ước mơ từ nhỏ của tôi. Hiện tôi đang thực tập tại một doanh nghiệp. Tuy công việc hơi vất vả nhưng ở đây tôi học được rất nhiều kỹ năng và kinh nghiệm.', 9) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v26_10', 'lesson-26', '企业', 'qǐyè', 'nghiệp', 'xí nghiệp, doanh nghiệp', 'Danh từ', '人/亻 (Nhân) (Con người, nhân loại, hành động)', '企: 人 (Nhân: người đứng kiễng chân) + 止 (Chỉ: mong ngóng, xí nghiệp) • 业: 业 (hai cặp nhánh đứng trên vạch ngang: công việc, sự nghiệp)', 'Ghép 企 [bộ 人] + 业 [bộ 一] để nhớ từ 企业 (qǐyè): "xí nghiệp, doanh nghiệp".', '翻译。这是我从小的梦想。现在我正在一家企业实习。虽然工作有点儿累，但是在这里我学会了很多技能和经验。', 'Fānyì. Zhè shì wǒ cóngxiǎo de mèngxiǎng. Xiànzài wǒ zhèng zài yījiā qǐyè shíxí. Suīrán gōngzuò yǒudiǎnr lèi dànshì zài zhèlǐ wǒ xué huì le hěn duō jìnéng hé jīngyàn.', 'Phiên dịch viên. Đây là ước mơ từ nhỏ của tôi. Hiện tôi đang thực tập tại một doanh nghiệp. Tuy công việc hơi vất vả nhưng ở đây tôi học được rất nhiều kỹ năng và kinh nghiệm.', 10) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v26_11', 'lesson-26', '毕业', 'bìyè', 'tất nghiệp', 'tốt nghiệp', 'Động từ', '比 (Tỷ) (So sánh, kề bên)', '毕: 比 (Tỷ) + 十 (Thập: hoàn thành tốt nghiệp) • 业: 业 (hai cặp nhánh đứng trên vạch ngang: công việc, sự nghiệp)', 'Ghép 毕 [bộ 比] + 业 [bộ 一] để nhớ từ 毕业 (bìyè): "tốt nghiệp".', '日明，快要毕业了，你有什么打算了吗？', 'Rìmíng, kuàiyào bìyè le, nǐ yǒu shénme dǎsuan le ma?', 'Nhật Minh, sắp tốt nghiệp rồi, cậu đã có dự định gì chưa?', 11) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v26_12', 'lesson-26', '回国', 'huíguó', 'quốc', 'về nước', 'Động từ', '囗 (Vi) (Vây quanh, không gian kín, lãnh thổ)', '回: 囗 (Vi: vòng ngoài) + 口 (Khẩu: vòng trong, quay về) • 国: 囗 (Vi: biên giới) + 玉 (Ngọc: báu vật quốc gia)', 'Ghép 回 [bộ 囗] + 国 [bộ 囗] để nhớ từ 回国 (huíguó): "về nước".', '学两年。然后我会回国找工作。', 'Xué liǎng nián. Ránhòu wǒ huì huíguó zhǎo gōngzuò.', 'Học hai năm. Sau đó tôi sẽ về nước tìm việc.', 12) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v26_13', 'lesson-26', '当', 'dāng', 'từ Hán ngữ', 'đảm nhiệm, làm', 'Động từ', '彐 (Kệ) (Đầu nhím, bàn tay nắm)', '当 = ⺌ + 彐 (Kệ).', 'Chữ 当 (dāng) mang nghĩa "đảm nhiệm, làm", bộ chính 彐 (Kệ); cấu tạo: ⺌ + 彐 (Kệ).', '因为我的专业是汉语教育，所以回国后我想当一位老师。我想帮助越南学生学习汉语，让他们更了解中国文化，更喜欢中国。那你呢？你有什么打算？', 'Yīnwèi wǒ de zhuānyè shì Hànyǔ jiàoyù, suǒyǐ huíguó hòu wǒ xiǎng dāng yí wèi lǎoshī. Wǒ xiǎng bāngzhù Yuènán xuésheng xuéxí Hànyǔ, ràng tāmen gèng liǎojiě Zhōngguó wénhuà, gèng xǐhuan Zhōngguó. Nà nǐ ne? Nǐ yǒu shén me dǎsuan?', 'Vì chuyên ngành của tôi là Giáo dục Hán ngữ, nên sau khi về nước tôi muốn làm giáo viên. Tôi muốn giúp học sinh Việt Nam học tiếng Hán, giúp các em hiểu hơn về văn hóa Trung Quốc và yêu thích Trung Quốc hơn. Còn cậu thì sao? Cậu có dự định gì?', 13) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v26_14', 'lesson-26', '实习', 'shíxí', 'tập', 'thực tập', 'Động từ', '宀 (Miên) (Mái nhà, che chở, nơi ở)', '实: 宀 (Miên: mái nhà) + 头 (Đầu: đầy đủ chân thật) • 习: 乛 (cánh chim) + 冫 (chim non tập bay nhiều lần)', 'Ghép 实 [bộ 宀] + 习 [bộ 乙] để nhớ từ 实习 (shíxí): "thực tập".', '翻译。这是我从小的梦想。现在我正在一家企业实习。虽然工作有点儿累，但是在这里我学会了很多技能和经验。', 'Fānyì. Zhè shì wǒ cóngxiǎo de mèngxiǎng. Xiànzài wǒ zhèng zài yījiā qǐyè shíxí. Suīrán gōngzuò yǒudiǎnr lèi dànshì zài zhèlǐ wǒ xué huì le hěn duō jìnéng hé jīngyàn.', 'Phiên dịch viên. Đây là ước mơ từ nhỏ của tôi. Hiện tôi đang thực tập tại một doanh nghiệp. Tuy công việc hơi vất vả nhưng ở đây tôi học được rất nhiều kỹ năng và kinh nghiệm.', 14) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v26_15', 'lesson-26', '了解', 'liǎojiě', 'từ Hán ngữ', 'hiểu rõ, biết rõ', 'Động từ', '刀/刂 (Đao) (Con dao, cắt xẻ, phân chia)', '了: Bộ 亅 (Quyết - nét móc kết thúc, chữ độc thể) • 解: 角 (Giác: sừng) + 刀 (Đao: dao) + 牛 (Ngưu: mổ phân tích)', 'Ghép 了 [bộ 亅] + 解 [bộ 刀] để nhớ từ 了解 (liǎojiě): "hiểu rõ, biết rõ".', '因为我的专业是汉语教育，所以回国后我想当一位老师。我想帮助越南学生学习汉语，让他们更了解中国文化，更喜欢中国。那你呢？你有什么打算？', 'Yīnwèi wǒ de zhuānyè shì Hànyǔ jiàoyù, suǒyǐ huíguó hòu wǒ xiǎng dāng yí wèi lǎoshī. Wǒ xiǎng bāngzhù Yuènán xuésheng xuéxí Hànyǔ, ràng tāmen gèng liǎojiě Zhōngguó wénhuà, gèng xǐhuan Zhōngguó. Nà nǐ ne? Nǐ yǒu shén me dǎsuan?', 'Vì chuyên ngành của tôi là Giáo dục Hán ngữ, nên sau khi về nước tôi muốn làm giáo viên. Tôi muốn giúp học sinh Việt Nam học tiếng Hán, giúp các em hiểu hơn về văn hóa Trung Quốc và yêu thích Trung Quốc hơn. Còn cậu thì sao? Cậu có dự định gì?', 15) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v26_16', 'lesson-26', '实现', 'shíxiàn', 'hiện', 'thực hiện', 'Động từ', '宀 (Miên) (Mái nhà, che chở, nơi ở)', '实: 宀 (Miên: mái nhà) + 头 (Đầu: đầy đủ chân thật) • 现: 王 (Ngọc: viên ngọc sáng) + 见 (Kiến: nhìn thấy)', 'Ghép 实 [bộ 宀] + 现 [bộ 王] để nhớ từ 实现 (shíxiàn): "thực hiện".', '我觉得当翻译也很好，很多人都想做这个工作。希望你能实现你的梦想！', 'Wǒ juéde dāng fānyì yě hěn hǎo, hěnduō rén dōu xiǎng zuò zhège gōngzuò. Xīwàng nǐ néng shíxiàn nǐ de mèngxiǎng!', 'Tôi thấy làm phiên dịch viên cũng rất hay, rất nhiều người muốn làm công việc này. Chúc cậu thực hiện được ước mơ của mình!', 16) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v26_17', 'lesson-26', '合适', 'héshì', 'hợp thích', 'hợp, thích hợp, vừa vặn', 'Tính từ', '口 (Khẩu) (Miệng, ăn uống, lời nói, âm thanh phát ra)', '合: 人 (Nhân) + 一 + 口 (Khẩu: nắp đậy vừa khít) • 适: 舌 (Thiệt) + 辶 (Sước: đi đến nơi phù hợp)', 'Ghép 合 [bộ 口] + 适 [bộ 辶] để nhớ từ 合适 (héshì): "hợp, thích hợp, vừa vặn".', '我想找一份好工作。不过对我们留学生来说，在中国找工作确实很难，所以我只好回国，希望找到一份合适的工作。', 'Wǒ xiǎng zhǎo yí fèn hǎo gōngzuò. Búguò duì wǒmen liúxuéshēng lái shuō, zài Zhōngguó zhǎo gōngzuò quèshí hěn nán, suǒyǐ wǒ zhǐhǎo huíguó, xīwàng zhǎodào yí fèn héshì de gōngzuò.', 'Tôi muốn tìm một công việc tốt. Nhưng với du học sinh chúng mình, tìm việc ở Trung Quốc thực sự rất khó, nên tôi đành về nước, hy vọng tìm được một công việc phù hợp.', 17) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v26_18', 'lesson-26', '然后', 'ránhòu', 'hậu', 'sau đó, tiếp đó', 'Liên từ', '火/灬 (Hỏa) (Lửa, nhiệt độ, nấu nướng, nóng bức)', '然: 肰 (Nhiên) + 灬 (Hỏa: ngọn lửa đốt) • 后: 厂 + 一 + 口 (Khẩu: phía sau)', 'Ghép 然 [bộ 灬] + 后 [bộ 口] để nhớ từ 然后 (ránhòu): "sau đó, tiếp đó".', '学两年。然后我会回国找工作。', 'Xué liǎng nián. Ránhòu wǒ huì huíguó zhǎo gōngzuò.', 'Học hai năm. Sau đó tôi sẽ về nước tìm việc.', 18) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v26_19', 'lesson-26', '不过', 'búguò', 'từ Hán ngữ', 'nhưng, tuy nhiên', 'Liên từ', '一 (Nhất) (Số một, nền tảng, nét ngang cơ bản)', '不: 一 (Nhất) + 丿 + 丨 + 丶 (chữ độc thể phủ định) • 过: 寸 (Thốn) + 辶 (Sước: bước đi qua)', 'Ghép 不 [bộ 一] + 过 [bộ 辶] để nhớ từ 不过 (búguò): "nhưng, tuy nhiên".', '我想找一份好工作。不过对我们留学生来说，在中国找工作确实很难，所以我只好回国，希望找到一份合适的工作。', 'Wǒ xiǎng zhǎo yí fèn hǎo gōngzuò. Búguò duì wǒmen liúxuéshēng lái shuō, zài Zhōngguó zhǎo gōngzuò quèshí hěn nán, suǒyǐ wǒ zhǐhǎo huíguó, xīwàng zhǎodào yí fèn héshì de gōngzuò.', 'Tôi muốn tìm một công việc tốt. Nhưng với du học sinh chúng mình, tìm việc ở Trung Quốc thực sự rất khó, nên tôi đành về nước, hy vọng tìm được một công việc phù hợp.', 19) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v26_20', 'lesson-26', '份', 'fèn', 'từ Hán ngữ', 'phần (lượng từ của công việc)', 'Lượng từ', '人/亻 (Nhân) (Con người, nhân loại, hành động)', '份 = 亻 (Nhân đứng: phần của mỗi người) + 分 (Phân).', 'Chữ 份 (fèn) mang nghĩa "phần (lượng từ của công việc)", bộ chính 人/亻 (Nhân); cấu tạo: 亻 (Nhân đứng: phần của mỗi người) + 分 (Phân).', '我想找一份好工作。不过对我们留学生来说，在中国找工作确实很难，所以我只好回国，希望找到一份合适的工作。', 'Wǒ xiǎng zhǎo yí fèn hǎo gōngzuò. Búguò duì wǒmen liúxuéshēng lái shuō, zài Zhōngguó zhǎo gōngzuò quèshí hěn nán, suǒyǐ wǒ zhǐhǎo huíguó, xīwàng zhǎodào yí fèn héshì de gōngzuò.', 'Tôi muốn tìm một công việc tốt. Nhưng với du học sinh chúng mình, tìm việc ở Trung Quốc thực sự rất khó, nên tôi đành về nước, hy vọng tìm được một công việc phù hợp.', 20) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v26_21', 'lesson-26', '位', 'wèi', 'từ Hán ngữ', 'vị (lượng từ chỉ người, thể hiện sự tôn trọng)', 'Lượng từ', '人/亻 (Nhân) (Con người, nhân loại, hành động)', '位 = 亻 (Nhân đứng: người) + 立 (Lập: vị trí đứng).', 'Chữ 位 (wèi) mang nghĩa "vị (lượng từ chỉ người, thể hiện sự tôn trọng)", bộ chính 人/亻 (Nhân); cấu tạo: 亻 (Nhân đứng: người) + 立 (Lập: vị trí đứng).', '因为我的专业是汉语教育，所以回国后我想当一位老师。我想帮助越南学生学习汉语，让他们更了解中国文化，更喜欢中国。那你呢？你有什么打算？', 'Yīnwèi wǒ de zhuānyè shì Hànyǔ jiàoyù, suǒyǐ huíguó hòu wǒ xiǎng dāng yí wèi lǎoshī. Wǒ xiǎng bāngzhù Yuènán xuésheng xuéxí Hànyǔ, ràng tāmen gèng liǎojiě Zhōngguó wénhuà, gèng xǐhuan Zhōngguó. Nà nǐ ne? Nǐ yǒu shén me dǎsuan?', 'Vì chuyên ngành của tôi là Giáo dục Hán ngữ, nên sau khi về nước tôi muốn làm giáo viên. Tôi muốn giúp học sinh Việt Nam học tiếng Hán, giúp các em hiểu hơn về văn hóa Trung Quốc và yêu thích Trung Quốc hơn. Còn cậu thì sao? Cậu có dự định gì?', 21) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, sort_order) VALUES ('v26_22', 'lesson-26', '确实', 'quèshí', 'từ Hán ngữ', 'thực sự, khẳng định', 'Phó từ', '石 (Thạch) (Hòn đá, vật cứng)', '确: 石 (Thạch: vững như đá) + 角 biến thể (chính xác) • 实: 宀 (Miên: mái nhà) + 头 (Đầu: đầy đủ chân thật)', 'Ghép 确 [bộ 石] + 实 [bộ 宀] để nhớ từ 确实 (quèshí): "thực sự, khẳng định".', '我想找一份好工作。不过对我们留学生来说，在中国找工作确实很难，所以我只好回国，希望找到一份合适的工作。', 'Wǒ xiǎng zhǎo yí fèn hǎo gōngzuò. Búguò duì wǒmen liúxuéshēng lái shuō, zài Zhōngguó zhǎo gōngzuò quèshí hěn nán, suǒyǐ wǒ zhǐhǎo huíguó, xīwàng zhǎodào yí fèn héshì de gōngzuò.', 'Tôi muốn tìm một công việc tốt. Nhưng với du học sinh chúng mình, tìm việc ở Trung Quốc thực sự rất khó, nên tôi đành về nước, hy vọng tìm được một công việc phù hợp.', 22) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order) VALUES ('g26_1', 'lesson-26', '1. Cách biểu đạt tuổi tác', 'Cấu trúc câu ngữ pháp trọng tâm', ' 你今年多大了？ Nǐ jīnnián duōdà le? Năm nay cậu bao nhiêu tuổi? (Hỏi chung chung) 你今年几岁了？ Nǐ jīnnián jǐ suì le? Năm nay cháu mấy tuổi rồi (Hỏi trẻ em dưới mười tuổi) 你今年多大年纪了？ Nǐ jīnnián duōdà niánjì le? Năm nay bác bao nhiêu tuổi rồi ạ? (Hỏi người lớn tuổ', NULL, '[{"hanzi":"你今年多大了？","pinyin":"Nǐ jīnnián duōdà le?","meaning":"Năm nay cậu bao nhiêu tuổi? (Hỏi chung chung)"},{"hanzi":"你今年几岁了？","pinyin":"Nǐ jīnnián jǐ suì le?","meaning":"Năm nay cháu mấy tuổi rồi (Hỏi trẻ em dưới mười tuổi)"}]'::jsonb, 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order) VALUES ('g26_2', 'lesson-26', '2. Cách sử dụng của 了', 'Cấu trúc câu ngữ pháp trọng tâm', ' 他睡觉了。 Tā shuìjiào le. Thằng bé ngủ rồi. 我去了几家商店才买到她喜欢的玩具。 Wǒ qù le jǐ jiā shāngdiàn cái mǎi dào tā xǐhuan de wánjù. Tôi đi khắp mấy cửa hàng mới mua được món đồ chơi mà con bé thích. 他画了一个上午才画完这幅画儿。 Tā huà le yígè shàngwǔ cái huà wán zhè fú huàr. Cậ', NULL, '[{"hanzi":"你今年多大年纪了？","pinyin":"Nǐ jīnnián duōdà niánjì le?","meaning":"Năm nay bác bao nhiêu tuổi rồi ạ? (Hỏi người lớn tuổi)"},{"hanzi":"我去了几家商店才买到她喜欢的玩具。","pinyin":"Wǒ qù le jǐ jiā shāngdiàn cái mǎi dào tā xǐhuan de wánjù.","meaning":"Tôi đi khắp mấy cửa hàng mới mua được món đồ chơi mà con bé thích."}]'::jsonb, 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order) VALUES ('g26_3', 'lesson-26', '3. 好像', 'Cấu trúc câu ngữ pháp trọng tâm', ' 刚才我好像看见了她。 Gāngcái wǒ hǎoxiàng kànjiàn le tā. Hình như ban nãy tôi mới trông thấy cô ấy. 他好像又长高了。 Tā hǎoxiàng yòu zhǎng gāo le. Hình như cậu ấy lại cao hơn rồi.', NULL, '[{"hanzi":"他画了一个上午才画完这幅画儿。","pinyin":"Tā huà le yígè shàngwǔ cái huà wán zhè fú huàr.","meaning":"Cậu ấy vẽ hết một buổi sáng mới vẽ xong bức tranh này."},{"hanzi":"小阳回了家就去做饭。","pinyin":"Xiǎoyáng huí le jiā jiù qù zuò fàn.","meaning":"Dương vừa về nhà là đi nấu cơm."}]'::jsonb, 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order) VALUES ('g26_4', 'lesson-26', '4. Trợ từ kết cấu 地', 'Cấu trúc câu ngữ pháp trọng tâm', ' 爸爸轻轻地拍我的肩膀，无声地安慰我。 Bàba qīngqīng de pāi wǒ de jiānbǎng, wúshēng de ānwèi wǒ. Bố nhẹ nhàng vỗ vai tôi, lẳng lặng an ủi tôi. 他连忙地向我挥手。 Tā liánmáng de xiàng wǒ huīshǒu. Cậu ấy vội vàng vẫy tay với tôi.', NULL, '[{"hanzi":"刚才我好像看见了她。","pinyin":"Gāngcái wǒ hǎoxiàng kànjiàn le tā.","meaning":"Hình như ban nãy tôi mới trông thấy cô ấy."},{"hanzi":"爸爸轻轻地拍我的肩膀，无声地安慰我。","pinyin":"Bàba qīngqīng de pāi wǒ de jiānbǎng, wúshēng de ānwèi wǒ.","meaning":"Bố nhẹ nhàng vỗ vai tôi, lẳng lặng an ủi tôi."}]'::jsonb, 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order;
INSERT INTO texts (id, lesson_id, title, description, sort_order) VALUES ('txt_26_1', 'lesson-26', 'Bài khoá #1: Hội thoại giáo trình — Sau khi tốt nghiệp', 'Hội thoại chuẩn giáo trình Bài 26. Từ vựng chưa học được chú thích phiên âm & nghĩa trong ngoặc.', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_26_1_1', 'txt_26_1', '马克', '日明，快要毕业了，你有什么打算了吗？', '日明，快要毕业了，你有什么打算了吗？', 'Rìmíng, kuàiyào bìyè le, nǐ yǒu shénme dǎsuan le ma?', 'Nhật Minh, sắp tốt nghiệp rồi, cậu đã có dự định gì chưa?', 1) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_26_1_2', 'txt_26_1', '阮日明', '我打算继续在这儿学习。', '我打算继续在这儿学习 (xuéxí: học tập)。', 'Wǒ dǎsuan jìxù zài zhèr xuéxí.', 'Tôi dự định tiếp tục học ở đây.', 2) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_26_1_3', 'txt_26_1', '马克', '你想学硕士吗？', '你想学 (xué: học)硕士吗？', 'Nǐ xiǎng xué shuòshì ma?', 'Cậu muốn học thạc sĩ à?', 3) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_26_1_4', 'txt_26_1', '阮日明', '对。', '对。', 'Duì.', 'Đúng vậy.', 4) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_26_1_5', 'txt_26_1', '马克', '学几年？', '学 (xué: học)几年？', 'Xué jǐ nián?', 'Học mấy năm?', 5) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_26_1_6', 'txt_26_1', '阮日明', '学两年。然后我会回国找工作。', '学 (xué: học)两 (liǎng: hai (số lượng))年。然后我会回国找工作。', 'Xué liǎng nián. Ránhòu wǒ huì huíguó zhǎo gōngzuò.', 'Học hai năm. Sau đó tôi sẽ về nước tìm việc.', 6) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_26_1_7', 'txt_26_1', '马克', '你想做什么工作？', '你想做 (zuò: làm)什么工作？', 'Nǐ xiǎng zuò shénme gōngzuò?', 'Cậu muốn làm công việc gì?', 7) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_26_1_8', 'txt_26_1', '阮日明', '因为我的专业是汉语教育，所以回国后我想当一位老师。我想帮助越南学生学习汉语，让他们更了解中国文化，更喜欢中国。那你呢？你有什么打算？', '因为我的专业是汉语教育，所以 (suǒyǐ: cho nên)回国后 (hòu: sau)我想当一位老师。我想帮助越南学生学习 (xuéxí: học tập)汉语，让他们更了解中国文化，更喜欢中国。那你呢？你有什么打算？', 'Yīnwèi wǒ de zhuānyè shì Hànyǔ jiàoyù, suǒyǐ huíguó hòu wǒ xiǎng dāng yí wèi lǎoshī. Wǒ xiǎng bāngzhù Yuènán xuésheng xuéxí Hànyǔ, ràng tāmen gèng liǎojiě Zhōngguó wénhuà, gèng xǐhuan Zhōngguó. Nà nǐ ne? Nǐ yǒu shén me dǎsuan?', 'Vì chuyên ngành của tôi là Giáo dục Hán ngữ, nên sau khi về nước tôi muốn làm giáo viên. Tôi muốn giúp học sinh Việt Nam học tiếng Hán, giúp các em hiểu hơn về văn hóa Trung Quốc và yêu thích Trung Quốc hơn. Còn cậu thì sao? Cậu có dự định gì?', 8) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_26_1_9', 'txt_26_1', '马克', '我想找一份好工作。不过对我们留学生来说，在中国找工作确实很难，所以我只好回国，希望找到一份合适的工作。', '我想找一份好工作。不过对我们留学生来 (lái: đến)说，在中国找工作确实很难，所以 (suǒyǐ: cho nên)我只好回国，希望找到一份合适的工作。', 'Wǒ xiǎng zhǎo yí fèn hǎo gōngzuò. Búguò duì wǒmen liúxuéshēng lái shuō, zài Zhōngguó zhǎo gōngzuò quèshí hěn nán, suǒyǐ wǒ zhǐhǎo huíguó, xīwàng zhǎodào yí fèn héshì de gōngzuò.', 'Tôi muốn tìm một công việc tốt. Nhưng với du học sinh chúng mình, tìm việc ở Trung Quốc thực sự rất khó, nên tôi đành về nước, hy vọng tìm được một công việc phù hợp.', 9) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_26_1_10', 'txt_26_1', '阮日明', '你的理想工作是什么？', '你的理想工作是什么？', 'Nǐ de lǐxiǎng gōngzuò shì shénme?', 'Công việc lý tưởng của cậu là gì?', 10) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_26_1_11', 'txt_26_1', '马克', '翻译。这是我从小的梦想。现在我正在一家企业实习。虽然工作有点儿累，但是在这里我学会了很多技能和经验。', '翻译。这是我从小的梦想。现在我正在一家企业实习。虽然工作有点儿累，但是在这里 (lǐ: trong)我学 (xué: học)会了很多技能和经验。', 'Fānyì. Zhè shì wǒ cóngxiǎo de mèngxiǎng. Xiànzài wǒ zhèng zài yījiā qǐyè shíxí. Suīrán gōngzuò yǒudiǎnr lèi dànshì zài zhèlǐ wǒ xué huì le hěn duō jìnéng hé jīngyàn.', 'Phiên dịch viên. Đây là ước mơ từ nhỏ của tôi. Hiện tôi đang thực tập tại một doanh nghiệp. Tuy công việc hơi vất vả nhưng ở đây tôi học được rất nhiều kỹ năng và kinh nghiệm.', 11) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_26_1_12', 'txt_26_1', '阮日明', '我觉得当翻译也很好，很多人都想做这个工作。希望你能实现你的梦想！', '我觉得当翻译也很好，很多人都想做 (zuò: làm)这个工作。希望你能实现你的梦想！', 'Wǒ juéde dāng fānyì yě hěn hǎo, hěnduō rén dōu xiǎng zuò zhège gōngzuò. Xīwàng nǐ néng shíxiàn nǐ de mèngxiǎng!', 'Tôi thấy làm phiên dịch viên cũng rất hay, rất nhiều người muốn làm công việc này. Chúc cậu thực hiện được ước mơ của mình!', 12) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_26_1_13', 'txt_26_1', '马克', '谢谢！希望你也是！', '谢谢！希望你也是！', 'Xièxie! Xīwàng nǐ yěshì!', 'Cảm ơn cậu! Chúc cậu cũng vậy nhé!', 13) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_26_1_1', 'lesson-26', 'txt_26_1', 'listening', 'listening', '日明，快要毕业了，你有什么打算了吗？', NULL, 'Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Nhật Minh, sắp tốt nghiệp rồi, cậu đã có dự định gì chưa?","Thời tiết dễ chịu quá!","Tôi không hay (không thường) liên lạc với Lý Quân.","Anh ta mời tôi ngày mai tới nhà dùng cơm."]'::jsonb, 0, 'Nội dung nghe được: 日明，快要毕业了，你有什么打算了吗？ (Rìmíng, kuàiyào bìyè le, nǐ yǒu shénme dǎsuan le ma?) → Nhật Minh, sắp tốt nghiệp rồi, cậu đã có dự định gì chưa?', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_26_1_2', 'lesson-26', 'txt_26_1', 'listening', 'listening', '我打算继续在这儿学习。', NULL, 'Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["刚才 (gāngcái: vừa nãy)我好像看见了她。","我打算继续在这儿学习 (xuéxí: học tập)。","爸爸轻轻 (qīngqīng: nhẹ nhàng)地拍 (pāi: chụp, vỗ)我的肩膀 (jiānbǎng: bờ vai)，无声 (wúshēng: không tiếng động)地安慰 (ānwèi: an ủi)我。","我的理想是当一名 (míng: người (lượng từ))优秀的汉语翻译。"]'::jsonb, 1, 'Câu vừa đọc: 我打算继续在这儿学习。 (Wǒ dǎsuan jìxù zài zhèr xuéxí.) → Tôi dự định tiếp tục học ở đây.', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_26_1_3', 'lesson-26', 'txt_26_1', 'listening', 'listening', '你想学硕士吗？', NULL, 'Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Cậu muốn học thạc sĩ à?","Ngày mai chúng tôi sẽ đi leo núi.","Cô ấy tự tin tham gia cuộc thi.","Anh ta không thích tôi, tôi còn đi làm gì? (Tôi không đi)"]'::jsonb, 0, 'Nội dung nghe được: 你想学硕士吗？ (Nǐ xiǎng xué shuòshì ma?) → Cậu muốn học thạc sĩ à?', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_26_1_4', 'lesson-26', 'txt_26_1', 'listening', 'listening', '学几年？', NULL, 'Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["回国以后，我想帮助学生更了解中国文化。","他笑得留下 (liúxià: để lại)了眼泪 (yǎnlèi: nước mắt)。","学 (xué: học)几年？","我朋友就要去重庆 (Chóngqìng: Trùng Khánh)留学 (liúxué: du học)了。"]'::jsonb, 2, 'Câu vừa đọc: 学几年？ (Xué jǐ nián?) → Học mấy năm?', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO texts (id, lesson_id, title, description, sort_order) VALUES ('txt_26_2', 'lesson-26', 'Bài nghe tổng hợp: Ôn tập lũy tiến (Bài 1 – Bài 26)', 'Kết hợp từ vựng & mẫu câu đã học từ Bài 1 đến Bài 25 cùng trọng tâm Bài 26 để củng cố phản xạ nghe.', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_26_2_1', 'txt_26_2', 'Ôn Bài 25', '他说汉语说得很好。', '他说汉语说得很好。', 'Tā shuō Hànyǔ shuō de hěn hǎo.', 'Anh ấy nói tiếng Trung rất tốt.', 1) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_26_2_2', 'txt_26_2', 'Bài 26', '日明，快要毕业了，你有什么打算了吗？', '日明，快要毕业了，你有什么打算了吗？', 'Rìmíng, kuàiyào bìyè le, nǐ yǒu shénme dǎsuan le ma?', 'Nhật Minh, sắp tốt nghiệp rồi, cậu đã có dự định gì chưa?', 2) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_26_2_3', 'txt_26_2', 'Ôn Bài 13', 'A: 今天星期几啊？', 'A: 今天星期几啊？', 'Jīntiān xīngqī jǐ a?', 'Hôm nay là thứ mấy thế?', 3) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_26_2_4', 'txt_26_2', 'Bài 26', '对。', '对。', 'Duì.', 'Đúng vậy.', 4) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_26_2_5', 'txt_26_2', 'Ôn Bài 1', '她是老师。', '她是老师。', 'Tā shì lǎoshī.', 'Cô ấy là giáo viên.', 5) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_26_2_6', 'txt_26_2', 'Bài 26', '你的理想工作是什么？', '你的理想工作是什么？', 'Nǐ de lǐxiǎng gōngzuò shì shénme?', 'Công việc lý tưởng của cậu là gì?', 6) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_26_2_7', 'txt_26_2', 'Ôn Bài 11', '他正在听音乐呢。', '他正在听音乐呢。', 'Tā zhèngzài tīng yīnyuè ne.', 'Anh ấy đang nghe nhạc.', 7) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_26_2_8', 'txt_26_2', 'Bài 26', '谢谢！希望你也是！', '谢谢！希望你也是！', 'Xièxie! Xīwàng nǐ yěshì!', 'Cảm ơn cậu! Chúc cậu cũng vậy nhé!', 8) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_26_2_1', 'lesson-26', 'txt_26_2', 'listening', 'listening', '他说汉语说得很好。', NULL, '[Ôn tập Bài 25] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Anh ấy nói tiếng Trung rất tốt.","Mẹ bảo tôi ăn cơm xong thì giúp mẹ quét dọn nhà cửa.","thời gian bắt đầu cuộc họp","Tớ định đi xe buýt."]'::jsonb, 0, 'Nội dung nghe được: 他说汉语说得很好。 (Tā shuō Hànyǔ shuō de hěn hǎo.) → Anh ấy nói tiếng Trung rất tốt.', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_26_2_2', 'lesson-26', 'txt_26_2', 'listening', 'listening', '日明，快要毕业了，你有什么打算了吗？', NULL, '[Bài 26] Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["日明，快要毕业了，你有什么打算了吗？","你今 (jīn: hôm nay, nay)年多大年纪了？","大学 (dàxué: đại học)毕业以后，我想继续读 (dú: đọc)汉语教育硕士。","他连忙 (liánmáng: vội vàng)地向 (xiàng: hướng về)我挥手 (huīshǒu: vẫy tay)。"]'::jsonb, 0, 'Câu vừa đọc: 日明，快要毕业了，你有什么打算了吗？ (Rìmíng, kuàiyào bìyè le, nǐ yǒu shénme dǎsuan le ma?) → Nhật Minh, sắp tốt nghiệp rồi, cậu đã có dự định gì chưa?', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_26_2_3', 'lesson-26', 'txt_26_2', 'listening', 'listening', 'A: 今天星期几啊？', NULL, '[Ôn tập Bài 13] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Mẹ gõ nhẹ vào đầu tôi.","Năm nay hay năm sau cậu đi du học?","Buổi chiều chúng ta đi nhé!","Hôm nay là thứ mấy thế?"]'::jsonb, 3, 'Nội dung nghe được: A: 今天星期几啊？ (Jīntiān xīngqī jǐ a?) → Hôm nay là thứ mấy thế?', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_26_2_4', 'lesson-26', 'txt_26_2', 'listening', 'listening', '她是老师。', NULL, '[Ôn tập Bài 1] Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["这次 (cì: lần)比赛如果他参加我就参加。","希望你早 (zǎo: sớm)日 (rì: ngày)找到一份理想的工作，实现梦想！","回国以后，我想帮助学生更了解中国文化。","她是老师。"]'::jsonb, 3, 'Câu vừa đọc: 她是老师。 (Tā shì lǎoshī.) → Cô ấy là giáo viên.', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_26_2_5', 'lesson-26', 'txt_26_2', 'listening', 'listening', '你的理想工作是什么？', NULL, '[Bài 26] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["zǒu jiù dào.","Công việc lý tưởng của cậu là gì?","Cái váy này là của em à?","đứa bé hiểu chuyện"]'::jsonb, 1, 'Nội dung nghe được: 你的理想工作是什么？ (Nǐ de lǐxiǎng gōngzuò shì shénme?) → Công việc lý tưởng của cậu là gì?', 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO texts (id, lesson_id, title, description, sort_order) VALUES ('txt_26_3', 'lesson-26', 'Bài khoá mở rộng: Định hướng sau lễ tốt nghiệp (Mở rộng)', 'Hội thoại tình huống mới xây dựng dựa trên từ vựng và ngữ pháp Bài 26 (không trùng lặp nguyên văn giáo trình).', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_26_3_1', 'txt_26_3', 'Minh', '下个月就要毕业了，你的梦想是什么工作？', '下 (xià: dưới / xuống)个月就要毕业了，你的梦想是什么工作？', 'Xià gè yuè jiù yào bìyè le, nǐ de mèngxiǎng shì shénme gōngzuò?', 'Tháng sau là tốt nghiệp rồi, công việc mơ ước của cậu là gì?', 1) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_26_3_2', 'txt_26_3', 'Lan', '我的专业是汉语教育，想先读两年硕士，以后当一位老师。', '我的专业是汉语教育，想先读 (dú: đọc)两 (liǎng: hai (số lượng))年硕士，以后当一位老师。', 'Wǒ de zhuānyè shì Hànyǔ jiàoyù, xiǎng xiān dú liǎng nián shuòshì, yǐhòu dāng yí wèi lǎoshī.', 'Chuyên ngành của mình là Giáo dục Hán ngữ, mình muốn học thạc sĩ hai năm trước rồi sau này làm giáo viên.', 2) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_26_3_3', 'txt_26_3', 'Minh', '真好！我现在在一家企业实习做翻译，积累了很多技能和经验。', '真好！我现在在一家企业实习做 (zuò: làm)翻译，积累了很多技能和经验。', 'Zhēn hǎo! Wǒ xiànzài zài yì jiā qǐyè shíxí zuò fānyì, jīlěi le hěnduō jìnéng hé jīngyàn.', 'Hay quá! Mình thì đang thực tập biên phiên dịch tại một doanh nghiệp, tích lũy được nhiều kỹ năng và kinh nghiệm.', 3) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order) VALUES ('ts_26_3_4', 'txt_26_3', 'Lan', '祝我们都能找到理想的工作，继续了解并热爱中国文化！', '祝我们都能找到理想的工作，继续了解并热爱中国文化！', 'Zhù wǒmen dōu néng zhǎodào lǐxiǎng de gōngzuò, jìxù liǎojiě bìng rè''ài Zhōngguó wénhuà!', 'Chúc hai đứa mình đều tìm được công việc lý tưởng và tiếp tục hiểu biết, yêu mến văn hóa Trung Quốc!', 4) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_26_3_1', 'lesson-26', 'txt_26_3', 'listening', 'listening', '下个月就要毕业了，你的梦想是什么工作？ 我的专业是汉语教育，想先读两年硕士，以后当一位老师。 真好！我现在在一家企业实习做翻译，积累了很多技能和经验。 祝我们都能找到理想的工作，继续了解并热爱中国文化！', NULL, '[Nghe hiểu tình huống mới] Nhật Minh hiện đang tích lũy kinh nghiệm làm công việc gì trước khi tốt nghiệp?', '["Mở nhà hàng ở Bắc Kinh","Học thạc sĩ y khoa","Làm tài xế taxi","Thực tập làm biên phiên dịch tại một doanh nghiệp"]'::jsonb, 3, 'Minh nói rõ ''现在在一家企业实习做翻译，积累了很多技能和经验''.', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_26_3_2', 'lesson-26', 'txt_26_3', 'listening', 'listening', '下个月就要毕业了，你的梦想是什么工作？', NULL, '[Mở rộng] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Tháng sau là tốt nghiệp rồi, công việc mơ ước của cậu là gì?","thành tích kiểm tra","Tôi đang vẽ tranh.","Tàu hỏa sắp chạy ngay bây giờ."]'::jsonb, 0, 'Nội dung nghe được: 下个月就要毕业了，你的梦想是什么工作？ (Xià gè yuè jiù yào bìyè le, nǐ de mèngxiǎng shì shénme gōngzuò?) → Tháng sau là tốt nghiệp rồi, công việc mơ ước của cậu là gì?', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_26_3_3', 'lesson-26', 'txt_26_3', 'listening', 'listening', '我的专业是汉语教育，想先读两年硕士，以后当一位老师。', NULL, '[Mở rộng] Nghe đoạn ghi âm và chọn câu Hán tự khớp với nội dung vừa nghe:', '["希望你早 (zǎo: sớm)日 (rì: ngày)找到一份理想的工作，实现梦想！","我的专业是汉语教育，想先读 (dú: đọc)两 (liǎng: hai (số lượng))年硕士，以后当一位老师。","我的理想是当一名 (míng: người (lượng từ))优秀的汉语翻译。","我朋友就要去重庆 (Chóngqìng: Trùng Khánh)留学 (liúxué: du học)了。"]'::jsonb, 1, 'Câu vừa đọc: 我的专业是汉语教育，想先读两年硕士，以后当一位老师。 (Wǒ de zhuānyè shì Hànyǔ jiàoyù, xiǎng xiān dú liǎng nián shuòshì, yǐhòu dāng yí wèi lǎoshī.) → Chuyên ngành của mình là Giáo dục Hán ngữ, mình muốn học thạc sĩ hai năm trước rồi sau này làm giáo viên.', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('lq_26_3_4', 'lesson-26', 'txt_26_3', 'listening', 'listening', '真好！我现在在一家企业实习做翻译，积累了很多技能和经验。', NULL, '[Mở rộng] Nghe câu tiếng Trung và chọn nghĩa tiếng Việt chính xác nhất:', '["Hay quá! Mình thì đang thực tập biên phiên dịch tại một doanh nghiệp, tích lũy được nhiều kỹ năng và kinh nghiệm.","Cậu thích mùa xuân hay mùa hè?","Không sớm cũng không muộn, rất đúng giờ!","Cảm ơn cậu! Chúc cậu cũng vậy nhé!"]'::jsonb, 0, 'Nội dung nghe được: 真好！我现在在一家企业实习做翻译，积累了很多技能和经验。 (Zhēn hǎo! Wǒ xiànzài zài yì jiā qǐyè shíxí zuò fānyì, jīlěi le hěnduō jìnéng hé jīngyàn.) → Hay quá! Mình thì đang thực tập biên phiên dịch tại một doanh nghiệp, tích lũy được nhiều kỹ năng và kinh nghiệm.', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss26_1', 'lesson-26', '你的理想工作是什么', 'Công việc lý tưởng của cậu là gì?', 'Nǐ de lǐxiǎng gōngzuò shì shénme?', '["你","的","理想","工作","是","什么"]'::jsonb, NULL, 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss26_2', 'lesson-26', '你今年多大了', 'Năm nay cậu bao nhiêu tuổi? (Hỏi chung chung)', 'Nǐ jīnnián duōdà le?', '["你","今","年","多大","了"]'::jsonb, 'Từ chưa học: 今 (jīn: hôm nay, nay)', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss26_3', 'lesson-26', '你今年几岁了', 'Năm nay cháu mấy tuổi rồi (Hỏi trẻ em dưới mười tuổi)', 'Nǐ jīnnián jǐ suì le?', '["你","今","年","几","岁","了"]'::jsonb, 'Từ chưa học: 今 (jīn: hôm nay, nay)', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss26_4', 'lesson-26', '你今年多大年纪了', 'Năm nay bác bao nhiêu tuổi rồi ạ? (Hỏi người lớn tuổi)', 'Nǐ jīnnián duōdà niánjì le?', '["你","今","年","多大","年纪","了"]'::jsonb, 'Từ chưa học: 今 (jīn: hôm nay, nay)', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss26_5', 'lesson-26', '北京的秋天比夏天凉快得多', '[Ôn tập Bài 15] Mùa thu ở Bắc Kinh mát mẻ hơn mùa hè nhiều.', 'Běijīng de qiūtiān bǐ xiàtiān liángkuai de duō.', '["北京的","秋天","比","夏天","凉快","得多"]'::jsonb, NULL, 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss26_6', 'lesson-26', '他汉语说得很好', '[Ôn tập Bài 25] Anh ấy nói tiếng Trung rất tốt.', 'Tā Hànyǔ shuō de hěn hǎo.', '["他","汉语","说","得","很","好"]'::jsonb, NULL, 6) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss26_exp_1', 'lesson-26', '日明快要毕业了你有什么打算了吗', 'Nhật Minh, sắp tốt nghiệp rồi, cậu đã có dự định gì chưa?', 'Rìmíng, kuàiyào bìyè le, nǐ yǒu shénme dǎsuan le ma?', '["日","明","快","要","毕业","了","你","有","什么","打算","了","吗"]'::jsonb, NULL, 7) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss26_exp_2', 'lesson-26', '我打算继续在这儿学习', 'Tôi dự định tiếp tục học ở đây.', 'Wǒ dǎsuan jìxù zài zhèr xuéxí.', '["我","打算","继续","在","这儿","学","习"]'::jsonb, NULL, 8) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss26_exp_3', 'lesson-26', '你想学硕士吗', 'Cậu muốn học thạc sĩ à?', 'Nǐ xiǎng xué shuòshì ma?', '["你","想","学","硕士","吗"]'::jsonb, NULL, 9) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss26_exp_4', 'lesson-26', '学几年', 'Học mấy năm?', 'Xué jǐ nián?', '["学","几","年"]'::jsonb, NULL, 10) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss26_exp_5', 'lesson-26', '学两年然后我会回国找工作', 'Học hai năm. Sau đó tôi sẽ về nước tìm việc.', 'Xué liǎng nián. Ránhòu wǒ huì huíguó zhǎo gōngzuò.', '["学","两","年","然后","我","会","回国","找","工作"]'::jsonb, NULL, 11) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss26_exp_6', 'lesson-26', '你想做什么工作', 'Cậu muốn làm công việc gì?', 'Nǐ xiǎng zuò shénme gōngzuò?', '["你","想","做","什么","工作"]'::jsonb, NULL, 12) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss26_exp_7', 'lesson-26', '因为我的专业是汉语教育所以回国后我想当一位老师我想帮助越南学生学习汉语让他们更了解中国文化更喜欢中国那你呢你有什么打算', 'Vì chuyên ngành của tôi là Giáo dục Hán ngữ, nên sau khi về nước tôi muốn làm giáo viên. Tôi muốn giúp học sinh Việt Nam học tiếng Hán, giúp các em hiểu hơn về văn hóa Trung Quốc và yêu thích Trung Quốc hơn. Còn cậu thì sao? Cậu có dự định gì?', 'Yīnwèi wǒ de zhuānyè shì Hànyǔ jiàoyù, suǒyǐ huíguó hòu wǒ xiǎng dāng yí wèi lǎoshī. Wǒ xiǎng bāngzhù Yuènán xuésheng xuéxí Hànyǔ, ràng tāmen gèng liǎojiě Zhōngguó wénhuà, gèng xǐhuan Zhōngguó. Nà nǐ ne? Nǐ yǒu shén me dǎsuan?', '["因为","我","的","专业","是","汉语","教育","所以","回国","后","我","想","当","一","位","老师","我","想","帮助","越南","学生","学","习","汉语","让","他们","更","了解","中国","文化","更","喜欢","中国","那","你","呢","你","有","什么","打算"]'::jsonb, NULL, 13) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss26_exp_8', 'lesson-26', '我想找一份好工作不过对我们留学生来说在中国找工作确实很难所以我只好回国希望找到一份合适的工作', 'Tôi muốn tìm một công việc tốt. Nhưng với du học sinh chúng mình, tìm việc ở Trung Quốc thực sự rất khó, nên tôi đành về nước, hy vọng tìm được một công việc phù hợp.', 'Wǒ xiǎng zhǎo yí fèn hǎo gōngzuò. Búguò duì wǒmen liúxuéshēng lái shuō, zài Zhōngguó zhǎo gōngzuò quèshí hěn nán, suǒyǐ wǒ zhǐhǎo huíguó, xīwàng zhǎodào yí fèn héshì de gōngzuò.', '["我","想","找","一","份","好","工作","不过","对","我们","留学生","来","说","在","中国","找","工作","确实","很","难","所以","我","只好","回国","希望","找","到","一","份","合适","的","工作"]'::jsonb, NULL, 14) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss26_exp_9', 'lesson-26', '翻译这是我从小的梦想现在我正在一家企业实习虽然工作有点儿累但是在这里我学会了很多技能和经验', 'Phiên dịch viên. Đây là ước mơ từ nhỏ của tôi. Hiện tôi đang thực tập tại một doanh nghiệp. Tuy công việc hơi vất vả nhưng ở đây tôi học được rất nhiều kỹ năng và kinh nghiệm.', 'Fānyì. Zhè shì wǒ cóngxiǎo de mèngxiǎng. Xiànzài wǒ zhèng zài yījiā qǐyè shíxí. Suīrán gōngzuò yǒudiǎnr lèi dànshì zài zhèlǐ wǒ xué huì le hěn duō jìnéng hé jīngyàn.', '["翻译","这","是","我","从","小","的","梦想","现在","我","正在","一","家","企业","实习","虽然","工作","有点儿","累","但是","在","这里","我","学","会","了","很","多","技能","和","经验"]'::jsonb, NULL, 15) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss26_exp_10', 'lesson-26', '我觉得当翻译也很好很多人都想做这个工作希望你能实现你的梦想', 'Tôi thấy làm phiên dịch viên cũng rất hay, rất nhiều người muốn làm công việc này. Chúc cậu thực hiện được ước mơ của mình!', 'Wǒ juéde dāng fānyì yě hěn hǎo, hěnduō rén dōu xiǎng zuò zhège gōngzuò. Xīwàng nǐ néng shíxiàn nǐ de mèngxiǎng!', '["我","觉得","当","翻译","也","很","好","很","多","人","都","想","做","这","个","工作","希望","你","能","实现","你","的","梦想"]'::jsonb, NULL, 16) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss26_exp_11', 'lesson-26', '谢谢希望你也是', 'Cảm ơn cậu! Chúc cậu cũng vậy nhé!', 'Xièxie! Xīwàng nǐ yěshì!', '["谢谢","希望","你","也","是"]'::jsonb, NULL, 17) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss26_exp_12', 'lesson-26', '他说汉语说得很好', 'Anh ấy nói tiếng Trung rất tốt.', 'Tā shuō Hànyǔ shuō de hěn hǎo.', '["他","说","汉语","说","得","很","好"]'::jsonb, NULL, 18) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss26_exp_13', 'lesson-26', '今天星期几啊', 'Hôm nay là thứ mấy thế?', 'Jīntiān xīngqī jǐ a?', '["今天","星期几","啊"]'::jsonb, NULL, 19) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order) VALUES ('ss26_exp_14', 'lesson-26', '她是老师', 'Cô ấy là giáo viên.', 'Tā shì lǎoshī.', '["她","是","老师"]'::jsonb, NULL, 20) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, unlearned_hint = EXCLUDED.unlearned_hint, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr26_vi_1', 'lesson-26', 'vi_to_zh', '[Mở rộng] Sau khi về nước, tôi muốn giúp học sinh hiểu thêm về văn hóa Trung Quốc.', NULL, NULL, '回国以后，我想帮助学生更了解中国文化。', NULL, 'huíguó yǐhòu wǒ xiǎng bāngzhù xuésheng gèng liǎojiě zhōngguó wénhuà', '[]'::jsonb, 'Gợi ý Pinyin: Huíguó yǐhòu, wǒ xiǎng bāngzhù xuésheng gèng liǎojiě Zhōngguó wénhuà.', 'Sau khi về nước, tôi muốn giúp học sinh hiểu thêm về văn hóa Trung Quốc. → 回国以后，我想帮助学生更了解中国文化。 (Huíguó yǐhòu, wǒ xiǎng bāngzhù xuésheng gèng liǎojiě Zhōngguó wénhuà.)', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr26_vi_2', 'lesson-26', 'vi_to_zh', '[Mở rộng] Thực tập tại doanh nghiệp giúp tôi học được rất nhiều kỹ năng và kinh nghiệm làm việc.', NULL, NULL, '在企业实习让我学到了很多工作技能和经验。', NULL, 'zài qǐyè shíxí ràng wǒ xuédào le hěnduō gōngzuò jìnéng hé jīngyàn', '[]'::jsonb, 'Gợi ý Pinyin: Zài qǐyè shíxí ràng wǒ xuédào le hěnduō gōngzuò jìnéng hé jīngyàn. | Từ chưa học: 学 (xué: học)', 'Thực tập tại doanh nghiệp giúp tôi học được rất nhiều kỹ năng và kinh nghiệm làm việc. → 在企业实习让我学到了很多工作技能和经验。 (Zài qǐyè shíxí ràng wǒ xuédào le hěnduō gōngzuò jìnéng hé jīngyàn.)', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr26_vi_3', 'lesson-26', 'vi_to_zh', 'Năm nay cậu bao nhiêu tuổi? (Hỏi chung chung)', NULL, NULL, '你今年多大了？', NULL, 'nǐ jīnnián duōdà le', '[]'::jsonb, 'Gợi ý Pinyin: Nǐ jīnnián duōdà le? | Từ chưa học: 今 (jīn: hôm nay, nay)', 'Năm nay cậu bao nhiêu tuổi? (Hỏi chung chung) → 你今年多大了？ (Nǐ jīnnián duōdà le?)', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr26_vi_4', 'lesson-26', 'vi_to_zh', 'Năm nay cháu mấy tuổi rồi (Hỏi trẻ em dưới mười tuổi)', NULL, NULL, '你今年几岁了？', NULL, 'nǐ jīnnián jǐ suì le', '[]'::jsonb, 'Gợi ý Pinyin: Nǐ jīnnián jǐ suì le? | Từ chưa học: 今 (jīn: hôm nay, nay)', 'Năm nay cháu mấy tuổi rồi (Hỏi trẻ em dưới mười tuổi) → 你今年几岁了？ (Nǐ jīnnián jǐ suì le?)', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr26_vi_exp_1', 'lesson-26', 'vi_to_zh', 'Nhật Minh, sắp tốt nghiệp rồi, cậu đã có dự định gì chưa?', NULL, NULL, '日明，快要毕业了，你有什么打算了吗？', NULL, 'rìmíng kuàiyào bìyè le nǐ yǒu shénme dǎsuan le ma', '[]'::jsonb, 'Gợi ý Pinyin: Rìmíng, kuàiyào bìyè le, nǐ yǒu shénme dǎsuan le ma?', 'Nhật Minh, sắp tốt nghiệp rồi, cậu đã có dự định gì chưa? → 日明，快要毕业了，你有什么打算了吗？ (Rìmíng, kuàiyào bìyè le, nǐ yǒu shénme dǎsuan le ma?)', 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr26_vi_exp_2', 'lesson-26', 'vi_to_zh', 'Tôi dự định tiếp tục học ở đây.', NULL, NULL, '我打算继续在这儿学习。', NULL, 'wǒ dǎsuan jìxù zài zhèr xuéxí', '[]'::jsonb, 'Gợi ý Pinyin: Wǒ dǎsuan jìxù zài zhèr xuéxí.', 'Tôi dự định tiếp tục học ở đây. → 我打算继续在这儿学习。 (Wǒ dǎsuan jìxù zài zhèr xuéxí.)', 6) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr26_vi_exp_3', 'lesson-26', 'vi_to_zh', 'Cậu muốn học thạc sĩ à?', NULL, NULL, '你想学硕士吗？', NULL, 'nǐ xiǎng xué shuòshì ma', '[]'::jsonb, 'Gợi ý Pinyin: Nǐ xiǎng xué shuòshì ma?', 'Cậu muốn học thạc sĩ à? → 你想学硕士吗？ (Nǐ xiǎng xué shuòshì ma?)', 7) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr26_vi_exp_4', 'lesson-26', 'vi_to_zh', 'Học mấy năm?', NULL, NULL, '学几年？', NULL, 'xué jǐ nián', '[]'::jsonb, 'Gợi ý Pinyin: Xué jǐ nián?', 'Học mấy năm? → 学几年？ (Xué jǐ nián?)', 8) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr26_vi_exp_5', 'lesson-26', 'vi_to_zh', 'Học hai năm. Sau đó tôi sẽ về nước tìm việc.', NULL, NULL, '学两年。然后我会回国找工作。', NULL, 'xué liǎng nián ránhòu wǒ huì huíguó zhǎo gōngzuò', '[]'::jsonb, 'Gợi ý Pinyin: Xué liǎng nián. Ránhòu wǒ huì huíguó zhǎo gōngzuò.', 'Học hai năm. Sau đó tôi sẽ về nước tìm việc. → 学两年。然后我会回国找工作。 (Xué liǎng nián. Ránhòu wǒ huì huíguó zhǎo gōngzuò.)', 9) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr26_vi_exp_6', 'lesson-26', 'vi_to_zh', 'Cậu muốn làm công việc gì?', NULL, NULL, '你想做什么工作？', NULL, 'nǐ xiǎng zuò shénme gōngzuò', '[]'::jsonb, 'Gợi ý Pinyin: Nǐ xiǎng zuò shénme gōngzuò?', 'Cậu muốn làm công việc gì? → 你想做什么工作？ (Nǐ xiǎng zuò shénme gōngzuò?)', 10) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr26_vi_exp_7', 'lesson-26', 'vi_to_zh', 'Vì chuyên ngành của tôi là Giáo dục Hán ngữ, nên sau khi về nước tôi muốn làm giáo viên. Tôi muốn giúp học sinh Việt Nam học tiếng Hán, giúp các em hiểu hơn về văn hóa Trung Quốc và yêu thích Trung Quốc hơn. Còn cậu thì sao? Cậu có dự định gì?', NULL, NULL, '因为我的专业是汉语教育，所以回国后我想当一位老师。我想帮助越南学生学习汉语，让他们更了解中国文化，更喜欢中国。那你呢？你有什么打算？', NULL, 'yīnwèi wǒ de zhuānyè shì hànyǔ jiàoyù suǒyǐ huíguó hòu wǒ xiǎng dāng yí wèi lǎoshī wǒ xiǎng bāngzhù yuènán xuésheng xuéxí hànyǔ ràng tāmen gèng liǎojiě zhōngguó wénhuà gèng xǐhuan zhōngguó nà nǐ ne nǐ yǒu shén me dǎsuan', '[]'::jsonb, 'Gợi ý Pinyin: Yīnwèi wǒ de zhuānyè shì Hànyǔ jiàoyù, suǒyǐ huíguó hòu wǒ xiǎng dāng yí wèi lǎoshī. Wǒ xiǎng bāngzhù Yuènán xuésheng xuéxí Hànyǔ, ràng tāmen gèng liǎojiě Zhōngguó wénhuà, gèng xǐhuan Zhōngguó. Nà nǐ ne? Nǐ yǒu shén me dǎsuan?', 'Vì chuyên ngành của tôi là Giáo dục Hán ngữ, nên sau khi về nước tôi muốn làm giáo viên. Tôi muốn giúp học sinh Việt Nam học tiếng Hán, giúp các em hiểu hơn về văn hóa Trung Quốc và yêu thích Trung Quốc hơn. Còn cậu thì sao? Cậu có dự định gì? → 因为我的专业是汉语教育，所以回国后我想当一位老师。我想帮助越南学生学习汉语，让他们更了解中国文化，更喜欢中国。那你呢？你有什么打算？ (Yīnwèi wǒ de zhuānyè shì Hànyǔ jiàoyù, suǒyǐ huíguó hòu wǒ xiǎng dāng yí wèi lǎoshī. Wǒ xiǎng bāngzhù Yuènán xuésheng xuéxí Hànyǔ, ràng tāmen gèng liǎojiě Zhōngguó wénhuà, gèng xǐhuan Zhōngguó. Nà nǐ ne? Nǐ yǒu shén me dǎsuan?)', 11) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr26_vi_exp_8', 'lesson-26', 'vi_to_zh', 'Tôi muốn tìm một công việc tốt. Nhưng với du học sinh chúng mình, tìm việc ở Trung Quốc thực sự rất khó, nên tôi đành về nước, hy vọng tìm được một công việc phù hợp.', NULL, NULL, '我想找一份好工作。不过对我们留学生来说，在中国找工作确实很难，所以我只好回国，希望找到一份合适的工作。', NULL, 'wǒ xiǎng zhǎo yí fèn hǎo gōngzuò búguò duì wǒmen liúxuéshēng lái shuō zài zhōngguó zhǎo gōngzuò quèshí hěn nán suǒyǐ wǒ zhǐhǎo huíguó xīwàng zhǎodào yí fèn héshì de gōngzuò', '[]'::jsonb, 'Gợi ý Pinyin: Wǒ xiǎng zhǎo yí fèn hǎo gōngzuò. Búguò duì wǒmen liúxuéshēng lái shuō, zài Zhōngguó zhǎo gōngzuò quèshí hěn nán, suǒyǐ wǒ zhǐhǎo huíguó, xīwàng zhǎodào yí fèn héshì de gōngzuò.', 'Tôi muốn tìm một công việc tốt. Nhưng với du học sinh chúng mình, tìm việc ở Trung Quốc thực sự rất khó, nên tôi đành về nước, hy vọng tìm được một công việc phù hợp. → 我想找一份好工作。不过对我们留学生来说，在中国找工作确实很难，所以我只好回国，希望找到一份合适的工作。 (Wǒ xiǎng zhǎo yí fèn hǎo gōngzuò. Búguò duì wǒmen liúxuéshēng lái shuō, zài Zhōngguó zhǎo gōngzuò quèshí hěn nán, suǒyǐ wǒ zhǐhǎo huíguó, xīwàng zhǎodào yí fèn héshì de gōngzuò.)', 12) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr26_vi_exp_9', 'lesson-26', 'vi_to_zh', 'Công việc lý tưởng của cậu là gì?', NULL, NULL, '你的理想工作是什么？', NULL, 'nǐ de lǐxiǎng gōngzuò shì shénme', '[]'::jsonb, 'Gợi ý Pinyin: Nǐ de lǐxiǎng gōngzuò shì shénme?', 'Công việc lý tưởng của cậu là gì? → 你的理想工作是什么？ (Nǐ de lǐxiǎng gōngzuò shì shénme?)', 13) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr26_vi_exp_10', 'lesson-26', 'vi_to_zh', 'Phiên dịch viên. Đây là ước mơ từ nhỏ của tôi. Hiện tôi đang thực tập tại một doanh nghiệp. Tuy công việc hơi vất vả nhưng ở đây tôi học được rất nhiều kỹ năng và kinh nghiệm.', NULL, NULL, '翻译。这是我从小的梦想。现在我正在一家企业实习。虽然工作有点儿累，但是在这里我学会了很多技能和经验。', NULL, 'fānyì zhè shì wǒ cóngxiǎo de mèngxiǎng xiànzài wǒ zhèng zài yījiā qǐyè shíxí suīrán gōngzuò yǒudiǎnr lèi dànshì zài zhèlǐ wǒ xué huì le hěn duō jìnéng hé jīngyàn', '[]'::jsonb, 'Gợi ý Pinyin: Fānyì. Zhè shì wǒ cóngxiǎo de mèngxiǎng. Xiànzài wǒ zhèng zài yījiā qǐyè shíxí. Suīrán gōngzuò yǒudiǎnr lèi dànshì zài zhèlǐ wǒ xué huì le hěn duō jìnéng hé jīngyàn.', 'Phiên dịch viên. Đây là ước mơ từ nhỏ của tôi. Hiện tôi đang thực tập tại một doanh nghiệp. Tuy công việc hơi vất vả nhưng ở đây tôi học được rất nhiều kỹ năng và kinh nghiệm. → 翻译。这是我从小的梦想。现在我正在一家企业实习。虽然工作有点儿累，但是在这里我学会了很多技能和经验。 (Fānyì. Zhè shì wǒ cóngxiǎo de mèngxiǎng. Xiànzài wǒ zhèng zài yījiā qǐyè shíxí. Suīrán gōngzuò yǒudiǎnr lèi dànshì zài zhèlǐ wǒ xué huì le hěn duō jìnéng hé jīngyàn.)', 14) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr26_zh_1', 'lesson-26', 'zh_to_vi', '[Mở rộng] 大学 (dàxué: đại học)毕业以后，我想继续读 (dú: đọc)汉语教育硕士。', '大学毕业以后，我想继续读汉语教育硕士。', 'Dàxué bìyè yǐhòu, wǒ xiǎng jìxù dú Hànyǔ jiàoyù shuòshì.', NULL, 'Sau khi tốt nghiệp đại học, tôi muốn học tiếp thạc sĩ Giáo dục Hán ngữ.', NULL, '["Sau","khi","tốt"]'::jsonb, 'Pinyin: Dàxué bìyè yǐhòu, wǒ xiǎng jìxù dú Hànyǔ jiàoyù shuòshì.', '大学毕业以后，我想继续读汉语教育硕士。 (Dàxué bìyè yǐhòu, wǒ xiǎng jìxù dú Hànyǔ jiàoyù shuòshì.) nghĩa là: Sau khi tốt nghiệp đại học, tôi muốn học tiếp thạc sĩ Giáo dục Hán ngữ.', 15) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr26_zh_2', 'lesson-26', 'zh_to_vi', '[Mở rộng] 希望你早 (zǎo: sớm)日 (rì: ngày)找到一份理想的工作，实现梦想！', '希望你早日找到一份理想的工作，实现梦想！', 'Xīwàng nǐ zǎorì zhǎodào yí fèn lǐxiǎng de gōngzuò, shíxiàn mèngxiǎng!', NULL, 'Hy vọng bạn sớm tìm được một công việc lý tưởng và thực hiện được ước mơ!', NULL, '["Hy","vọng","bạn"]'::jsonb, 'Pinyin: Xīwàng nǐ zǎorì zhǎodào yí fèn lǐxiǎng de gōngzuò, shíxiàn mèngxiǎng!', '希望你早日找到一份理想的工作，实现梦想！ (Xīwàng nǐ zǎorì zhǎodào yí fèn lǐxiǎng de gōngzuò, shíxiàn mèngxiǎng!) nghĩa là: Hy vọng bạn sớm tìm được một công việc lý tưởng và thực hiện được ước mơ!', 16) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr26_zh_3', 'lesson-26', 'zh_to_vi', '你今 (jīn: hôm nay, nay)年多大年纪了？', '你今年多大年纪了？', 'Nǐ jīnnián duōdà niánjì le?', NULL, 'Năm nay bác bao nhiêu tuổi rồi ạ? (Hỏi người lớn tuổi)', NULL, '["Năm","nay","bác"]'::jsonb, 'Pinyin: Nǐ jīnnián duōdà niánjì le?', '你今年多大年纪了？ (Nǐ jīnnián duōdà niánjì le?) nghĩa là: Năm nay bác bao nhiêu tuổi rồi ạ? (Hỏi người lớn tuổi)', 17) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr26_zh_4', 'lesson-26', 'zh_to_vi', '[Ôn tập Bài 13] A: 今天星期几啊？', 'A: 今天星期几啊？', 'Jīntiān xīngqī jǐ a?', NULL, 'Hôm nay là thứ mấy thế?', NULL, '["Hôm","nay","là"]'::jsonb, 'Pinyin: Jīntiān xīngqī jǐ a?', 'A: 今天星期几啊？ (Jīntiān xīngqī jǐ a?) nghĩa là: Hôm nay là thứ mấy thế?', 18) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr26_zh_exp_1', 'lesson-26', 'zh_to_vi', '爸爸轻轻地拍我的肩膀，无声地安慰我。', '爸爸轻轻地拍我的肩膀，无声地安慰我。', 'Bàba qīngqīng de pāi wǒ de jiānbǎng, wúshēng de ānwèi wǒ.', NULL, 'Bố nhẹ nhàng vỗ vai tôi, lẳng lặng an ủi tôi.', NULL, '["bố","nhẹ","nhàng","vỗ","vai","tôi","lẳng","lặng","an","ủi","tôi"]'::jsonb, 'Pinyin: Bàba qīngqīng de pāi wǒ de jiānbǎng, wúshēng de ānwèi wǒ.', '爸爸轻轻地拍我的肩膀，无声地安慰我。 (Bàba qīngqīng de pāi wǒ de jiānbǎng, wúshēng de ānwèi wǒ.) nghĩa là: Bố nhẹ nhàng vỗ vai tôi, lẳng lặng an ủi tôi.', 19) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr26_zh_exp_2', 'lesson-26', 'zh_to_vi', '刚才我好像看见了她。', '刚才我好像看见了她。', 'Gāngcái wǒ hǎoxiàng kànjiàn le tā.', NULL, 'Hình như ban nãy tôi mới trông thấy cô ấy.', NULL, '["hình","như","ban","nãy","tôi","mới","trông","thấy","cô","ấy"]'::jsonb, 'Pinyin: Gāngcái wǒ hǎoxiàng kànjiàn le tā.', '刚才我好像看见了她。 (Gāngcái wǒ hǎoxiàng kànjiàn le tā.) nghĩa là: Hình như ban nãy tôi mới trông thấy cô ấy.', 20) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr26_zh_exp_3', 'lesson-26', 'zh_to_vi', '小阳回了家就去做饭。', '小阳回了家就去做饭。', 'Xiǎoyáng huí le jiā jiù qù zuò fàn.', NULL, 'Dương vừa về nhà là đi nấu cơm.', NULL, '["dương","vừa","về","nhà","là","đi","nấu","cơm"]'::jsonb, 'Pinyin: Xiǎoyáng huí le jiā jiù qù zuò fàn.', '小阳回了家就去做饭。 (Xiǎoyáng huí le jiā jiù qù zuò fàn.) nghĩa là: Dương vừa về nhà là đi nấu cơm.', 21) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr26_zh_exp_4', 'lesson-26', 'zh_to_vi', '他画了一个上午才画完这幅画儿。', '他画了一个上午才画完这幅画儿。', 'Tā huà le yígè shàngwǔ cái huà wán zhè fú huàr.', NULL, 'Cậu ấy vẽ hết một buổi sáng mới vẽ xong bức tranh này.', NULL, '["cậu","ấy","vẽ","hết","một","buổi","sáng","mới","vẽ","xong","bức","tranh","này"]'::jsonb, 'Pinyin: Tā huà le yígè shàngwǔ cái huà wán zhè fú huàr.', '他画了一个上午才画完这幅画儿。 (Tā huà le yígè shàngwǔ cái huà wán zhè fú huàr.) nghĩa là: Cậu ấy vẽ hết một buổi sáng mới vẽ xong bức tranh này.', 22) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr26_zh_exp_5', 'lesson-26', 'zh_to_vi', '我去了几家商店才买到她喜欢的玩具。', '我去了几家商店才买到她喜欢的玩具。', 'Wǒ qù le jǐ jiā shāngdiàn cái mǎi dào tā xǐhuan de wánjù.', NULL, 'Tôi đi khắp mấy cửa hàng mới mua được món đồ chơi mà con bé thích.', NULL, '["tôi","đi","khắp","mấy","cửa","hàng","mới","mua","được","món","đồ","chơi","mà","con","bé","thích"]'::jsonb, 'Pinyin: Wǒ qù le jǐ jiā shāngdiàn cái mǎi dào tā xǐhuan de wánjù.', '我去了几家商店才买到她喜欢的玩具。 (Wǒ qù le jǐ jiā shāngdiàn cái mǎi dào tā xǐhuan de wánjù.) nghĩa là: Tôi đi khắp mấy cửa hàng mới mua được món đồ chơi mà con bé thích.', 23) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
