INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr26_zh_exp_7', 'lesson-26', 'zh_to_vi', '你今年多大了？', '你今年多大了？', 'Nǐ jīnnián duōdà le?', NULL, 'Năm nay cậu bao nhiêu tuổi? (Hỏi chung chung)', NULL, '["năm","nay","cậu","bao","nhiêu","tuổi","hỏi","chung","chung"]'::jsonb, 'Pinyin: Nǐ jīnnián duōdà le?', '你今年多大了？ (Nǐ jīnnián duōdà le?) nghĩa là: Năm nay cậu bao nhiêu tuổi? (Hỏi chung chung)', 25) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr26_zh_exp_8', 'lesson-26', 'zh_to_vi', '祝我们都能找到理想的工作，继续了解并热爱中国文化！', '祝我们都能找到理想的工作，继续了解并热爱中国文化！', 'Zhù wǒmen dōu néng zhǎodào lǐxiǎng de gōngzuò, jìxù liǎojiě bìng rè''ài Zhōngguó wénhuà!', NULL, 'Chúc hai đứa mình đều tìm được công việc lý tưởng và tiếp tục hiểu biết, yêu mến văn hóa Trung Quốc!', NULL, '["chúc","hai","đứa","mình","đều","tìm","được","công","việc","lý","tưởng","và","tiếp","tục","hiểu","biết","yêu","mến","văn","hóa","trung","quốc"]'::jsonb, 'Pinyin: Zhù wǒmen dōu néng zhǎodào lǐxiǎng de gōngzuò, jìxù liǎojiě bìng rè''ài Zhōngguó wénhuà!', '祝我们都能找到理想的工作，继续了解并热爱中国文化！ (Zhù wǒmen dōu néng zhǎodào lǐxiǎng de gōngzuò, jìxù liǎojiě bìng rè''ài Zhōngguó wénhuà!) nghĩa là: Chúc hai đứa mình đều tìm được công việc lý tưởng và tiếp tục hiểu biết, yêu mến văn hóa Trung Quốc!', 26) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr26_zh_exp_9', 'lesson-26', 'zh_to_vi', '真好！我现在在一家企业实习做翻译，积累了很多技能和经验。', '真好！我现在在一家企业实习做翻译，积累了很多技能和经验。', 'Zhēn hǎo! Wǒ xiànzài zài yì jiā qǐyè shíxí zuò fānyì, jīlěi le hěnduō jìnéng hé jīngyàn.', NULL, 'Hay quá! Mình thì đang thực tập biên phiên dịch tại một doanh nghiệp, tích lũy được nhiều kỹ năng và kinh nghiệm.', NULL, '["hay","quá","mình","thì","đang","thực","tập","biên","phiên","dịch","tại","một","doanh","nghiệp","tích","lũy","được","nhiều","kỹ","năng","và","kinh","nghiệm"]'::jsonb, 'Pinyin: Zhēn hǎo! Wǒ xiànzài zài yì jiā qǐyè shíxí zuò fānyì, jīlěi le hěnduō jìnéng hé jīngyàn.', '真好！我现在在一家企业实习做翻译，积累了很多技能和经验。 (Zhēn hǎo! Wǒ xiànzài zài yì jiā qǐyè shíxí zuò fānyì, jīlěi le hěnduō jìnéng hé jīngyàn.) nghĩa là: Hay quá! Mình thì đang thực tập biên phiên dịch tại một doanh nghiệp, tích lũy được nhiều kỹ năng và kinh nghiệm.', 27) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order) VALUES ('tr26_zh_exp_10', 'lesson-26', 'zh_to_vi', '我的专业是汉语教育，想先读两年硕士，以后当一位老师。', '我的专业是汉语教育，想先读两年硕士，以后当一位老师。', 'Wǒ de zhuānyè shì Hànyǔ jiàoyù, xiǎng xiān dú liǎng nián shuòshì, yǐhòu dāng yí wèi lǎoshī.', NULL, 'Chuyên ngành của mình là Giáo dục Hán ngữ, mình muốn học thạc sĩ hai năm trước rồi sau này làm giáo viên.', NULL, '["chuyên","ngành","của","mình","là","giáo","dục","hán","ngữ","mình","muốn","học","thạc","sĩ","hai","năm","trước","rồi","sau","này","làm","giáo","viên"]'::jsonb, 'Pinyin: Wǒ de zhuānyè shì Hànyǔ jiàoyù, xiǎng xiān dú liǎng nián shuòshì, yǐhòu dāng yí wèi lǎoshī.', '我的专业是汉语教育，想先读两年硕士，以后当一位老师。 (Wǒ de zhuānyè shì Hànyǔ jiàoyù, xiǎng xiān dú liǎng nián shuòshì, yǐhòu dāng yí wèi lǎoshī.) nghĩa là: Chuyên ngành của mình là Giáo dục Hán ngữ, mình muốn học thạc sĩ hai năm trước rồi sau này làm giáo viên.', 28) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
