INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq26_11', 'lesson-26', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, 'Phiên âm Pinyin chính xác của “不过” là gì?', '["zhuānyè","liǎojiě","búguò","héshì"]'::jsonb, 2, '“不过” đọc là: búguò (nhưng, tuy nhiên).', 11) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq26_12', 'lesson-26', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, 'Phiên âm Pinyin chính xác của “然后” là gì?', '["shíxiàn","fèn","ránhòu","liǎojiě"]'::jsonb, 2, '“然后” đọc là: ránhòu (sau đó, tiếp đó).', 12) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq26_13', 'lesson-26', NULL, 'expanded_quiz', 'radical', NULL, NULL, 'Chữ Hán “专业” chứa bộ thủ nào sau đây?', '["一 (Nhất) (Số một, nền tảng, nét ngang cơ bản)","彐 (Kệ) (Đầu nhím, bàn tay nắm)","生 (Sinh) (Sinh sôi, sự sống, mới mẻ)","见 (Kiến) (Nhìn thấy, gặp gỡ)"]'::jsonb, 0, 'Chữ “专业” có bộ chính 一 (Nhất) (Số một, nền tảng, nét ngang cơ bản). Chiết tự: 专: 二 + 乚 + 丶 (chuyên tâm một việc) • 业: 业 (hai cặp nhánh đứng trên vạch ngang: công việc, sự nghiệp)', 13) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq26_14', 'lesson-26', NULL, 'expanded_quiz', 'radical', NULL, NULL, 'Chữ Hán “硕士” chứa bộ thủ nào sau đây?', '["青 (Thanh) (Màu xanh, tươi trẻ)","凵 (Khảm) (Há miệng, hố trũng)","彡 (Sam) (Hoa văn, lông tóc, nét trang trí)","石 (Thạch) (Hòn đá, vật cứng)"]'::jsonb, 3, 'Chữ “硕士” có bộ chính 石 (Thạch) (Hòn đá, vật cứng). Chiết tự: 硕: 石 (Thạch: đá lớn) + 页 (Hiệt: to lớn, thạc sĩ) • 士: Bộ 士 (Sĩ - nét trên dài hơn nét dưới, người có học)', 14) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq26_15', 'lesson-26', NULL, 'expanded_quiz', 'radical', NULL, NULL, 'Chữ Hán “理想” chứa bộ thủ nào sau đây?', '["火/灬 (Hỏa) (Lửa, nhiệt độ, nấu nướng, nóng bức)","至 (Chí) (Đến nơi, cực điểm)","玉/王 (Ngọc) (Đá quý, vua chúa)","食/饣 (Thực) (Đồ ăn, ẩm thực)"]'::jsonb, 2, 'Chữ “理想” có bộ chính 玉/王 (Ngọc) (Đá quý, vua chúa). Chiết tự: 理: 王 (Ngọc: mài giũa đường vân ngọc) + 里 (Lý: đạo lý) • 想: 相 (Tương: hình ảnh) + 心 (Tâm: lòng suy nghĩ)', 15) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq26_16', 'lesson-26', NULL, 'expanded_quiz', 'radical', NULL, NULL, 'Chữ Hán “梦想” chứa bộ thủ nào sau đây?', '["廴 (Dẫn) (Bước dài, kéo dài)","瓦 (Ngõa) (Ngói, đồ gốm sứ)","夕 (Tịch) (Buổi chiều tối, đêm tối)","衣/衤 (Y) (Áo quần, y phục)"]'::jsonb, 2, 'Chữ “梦想” có bộ chính 夕 (Tịch) (Buổi chiều tối, đêm tối). Chiết tự: 梦: 林 (Lâm: rừng tối) + 夕 (Tịch: buổi đêm nằm mơ) • 想: 相 (Tương: hình ảnh) + 心 (Tâm: lòng suy nghĩ)', 16) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq26_17', 'lesson-26', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, '[Ôn tập Bài 8] Từ đã học “芒果” (mángguǒ) có nghĩa là gì?', '["xoài","rất","Di Hòa Viên","giày, dép"]'::jsonb, 0, 'Ôn tập Bài 8: “芒果” (mángguǒ) nghĩa là: xoài.', 17) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq26_18', 'lesson-26', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, '[Ôn tập Bài 13] Từ đã học “干” (gàn) có nghĩa là gì?', '["làm","đi bộ","táo","gần đây"]'::jsonb, 0, 'Ôn tập Bài 13: “干” (gàn) nghĩa là: làm.', 18) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq26_19', 'lesson-26', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, '[Ôn tập Bài 13] Từ đã học “帽子” (màozi) có nghĩa là gì?', '["người, con người","cao","tập luyện, tập","mũ"]'::jsonb, 3, 'Ôn tập Bài 13: “帽子” (màozi) nghĩa là: mũ.', 19) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq26_20', 'lesson-26', NULL, 'expanded_quiz', 'reading', NULL, NULL, '[Mở rộng] Câu “回国以后，我想帮助学生更了解中国文化。” có nghĩa tiếng Việt là gì?', '["Hình như ban nãy tôi mới trông thấy cô ấy.","Sau khi về nước, tôi muốn giúp học sinh hiểu thêm về văn hóa Trung Quốc.","Bệnh của tôi vẫn chưa khỏi.","Quyển sách đó ở ngay trên bàn."]'::jsonb, 1, '回国以后，我想帮助学生更了解中国文化。 (Huíguó yǐhòu, wǒ xiǎng bāngzhù xuésheng gèng liǎojiě Zhōngguó wénhuà.) → Sau khi về nước, tôi muốn giúp học sinh hiểu thêm về văn hóa Trung Quốc.', 20) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq26_21', 'lesson-26', NULL, 'expanded_quiz', 'reading', NULL, NULL, '[Đọc hiểu mở rộng] Đọc đoạn hội thoại:
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('eq26_22', 'lesson-26', NULL, 'expanded_quiz', 'reading', NULL, NULL, 'Câu “你今 (jīn: hôm nay, nay)年多大了？” có nghĩa tiếng Việt là gì?', '["Anh ấy chạy rất nhanh.","Anh ấy hát không hay lắm.","Năm nay cậu bao nhiêu tuổi? (Hỏi chung chung)","Lúc đó, người con gái ấy khóc không ngớt."]'::jsonb, 2, '你今年多大了？ (Nǐ jīnnián duōdà le?) → Năm nay cậu bao nhiêu tuổi? (Hỏi chung chung)', 22) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct26_1', 'lesson-26', NULL, 'comprehensive_test', 'listening', '今天星期几啊？', NULL, 'Nghe đoạn ghi âm và chọn nghĩa tiếng Việt đúng:', '["Hôm nay là thứ mấy thế?","Bạn cứ đi thẳng, sau đó rẽ phải là sẽ nhìn thấy bệnh viện ở bên trái của","Mùa đông có phải rất lạnh không?","Năm nay cháu mấy tuổi rồi (Hỏi trẻ em dưới mười tuổi)"]'::jsonb, 0, 'Nội dung nghe được: “今天星期几啊？” (Jīntiān xīngqī jǐ a?) → Hôm nay là thứ mấy thế?', 1) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct26_2', 'lesson-26', NULL, 'comprehensive_test', 'listening', '他说汉语说得很好。', NULL, 'Nghe đoạn ghi âm và chọn câu tiếng Trung khớp với nội dung vừa nghe:', '["他说汉语说得很好。","现在的我们","最好的办法是什么都不要说，保持安静！","是的！"]'::jsonb, 0, 'Câu vừa đọc: “他说汉语说得很好。” (Tā shuō Hànyǔ shuō de hěn hǎo.) → Anh ấy nói tiếng Trung rất tốt.', 2) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct26_3', 'lesson-26', NULL, 'comprehensive_test', 'listening', '下个月就要毕业了，你的梦想是什么工作？', NULL, 'Nghe đoạn ghi âm và chọn nghĩa tiếng Việt đúng:', '["Đâu có đâu! Đều do cậu tự vượt qua cả, bọn tớ có làm gì đâu.","Tháng sau là tốt nghiệp rồi, công việc mơ ước của cậu là gì?","Màu sắc của chiếc áo khoác dài này tôi rất thích.","Tiểu Bạch, bạn thấy chiếc cặp sách hôm nay tôi mua thế nào?"]'::jsonb, 1, 'Nội dung nghe được: “下个月就要毕业了，你的梦想是什么工作？” (Xià gè yuè jiù yào bìyè le, nǐ de mèngxiǎng shì shénme gōngzuò?) → Tháng sau là tốt nghiệp rồi, công việc mơ ước của cậu là gì?', 3) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct26_4', 'lesson-26', NULL, 'comprehensive_test', 'listening', '你想学硕士吗？', NULL, 'Nghe đoạn ghi âm và chọn câu tiếng Trung khớp với nội dung vừa nghe:', '["爸爸很少带我去旅游。","你想学硕士吗？","那你帮我跟刘老师说一声， 我生病不能上课了！","你好，你想买什么衣服？"]'::jsonb, 1, 'Câu vừa đọc: “你想学硕士吗？” (Nǐ xiǎng xué shuòshì ma?) → Cậu muốn học thạc sĩ à?', 4) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct26_5', 'lesson-26', NULL, 'comprehensive_test', 'listening', '祝我们都能找到理想的工作，继续了解并热爱中国文化！', NULL, 'Nghe đoạn ghi âm và chọn nghĩa tiếng Việt đúng:', '["Nakamura là người Trung Quốc hay người Nhật Bản?","Chúc hai đứa mình đều tìm được công việc lý tưởng và tiếp tục hiểu biết, yêu mến văn hóa Trung Quốc!","Nếu có gì không biết thì cậu cứ hỏi tớ.","Anh ấy nói tiếng Trung rất tốt."]'::jsonb, 1, 'Nội dung nghe được: “祝我们都能找到理想的工作，继续了解并热爱中国文化！” (Zhù wǒmen dōu néng zhǎodào lǐxiǎng de gōngzuò, jìxù liǎojiě bìng rè''ài Zhōngguó wénhuà!) → Chúc hai đứa mình đều tìm được công việc lý tưởng và tiếp tục hiểu biết, yêu mến văn hóa Trung Quốc!', 5) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct26_6', 'lesson-26', NULL, 'comprehensive_test', 'listening', '学两年。然后我会回国找工作。', NULL, 'Nghe đoạn ghi âm và chọn câu tiếng Trung khớp với nội dung vừa nghe:', '["学两年。然后我会回国找工作。","她不来了吧。","弟弟在花园里玩儿。","妈妈，我的衣服在哪儿呢？"]'::jsonb, 0, 'Câu vừa đọc: “学两年。然后我会回国找工作。” (Xué liǎng nián. Ránhòu wǒ huì huíguó zhǎo gōngzuò.) → Học hai năm. Sau đó tôi sẽ về nước tìm việc.', 6) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct26_7', 'lesson-26', NULL, 'comprehensive_test', 'listening', '我想找一份好工作。不过对我们留学生来说，在中国找工作确实很难，所以我只好回国，希望找到一份合适的工作。', NULL, 'Nghe đoạn ghi âm và chọn nghĩa tiếng Việt đúng:', '["Anh ấy nói tiếng Trung không tốt.","Tôi muốn tìm một công việc tốt. Nhưng với du học sinh chúng mình, tìm việc ở Trung Quốc thực sự rất khó, nên tôi đành về nước, hy vọng tìm được một công việc phù hợp.","Không phải bạn nói năm nay sẽ đi du lịch Nhật Bản sao?","Phía bên trái nhà ăn"]'::jsonb, 1, 'Nội dung nghe được: “我想找一份好工作。不过对我们留学生来说，在中国找工作确实很难，所以我只好回国，希望找到一份合适的工作。” (Wǒ xiǎng zhǎo yí fèn hǎo gōngzuò. Búguò duì wǒmen liúxuéshēng lái shuō, zài Zhōngguó zhǎo gōngzuò quèshí hěn nán, suǒyǐ wǒ zhǐhǎo huíguó, xīwàng zhǎodào yí fèn héshì de gōngzuò.) → Tôi muốn tìm một công việc tốt. Nhưng với du học sinh chúng mình, tìm việc ở Trung Quốc thực sự rất khó, nên tôi đành về nước, hy vọng tìm được một công việc phù hợp.', 7) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct26_8', 'lesson-26', NULL, 'comprehensive_test', 'listening', '刚才我好像看见了她。', NULL, 'Nghe đoạn ghi âm và cho biết nhận định sau ĐÚNG hay SAI:
