INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order) VALUES ('ct26_11', 'lesson-26', NULL, 'comprehensive_test', 'listening', '因为我的专业是汉语教育，所以回国后我想当一位老师。我想帮助越南学生学习汉语，让他们更了解中国文化，更喜欢中国。那你呢？你有什么打算？', NULL, 'Nghe đoạn ghi âm và cho biết nhận định sau ĐÚNG hay SAI:
